-- Inserting report ID 31659
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Prepare for hypochlorite transformer replacement', 'Electrical & Instrument', 'OTH ', 'In Progress', '2024-05-21', '<p>Action:&nbsp;Prepare for hypochlorite transformer replacement</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Discuss with CR team and scafolder to erect the scaffold.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Move the spare hypochloride transformer to laydown area.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Wrap the spare hypochloride transformer with palstic sheet to prevent form raining.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Clean the transformer area.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Prepare the lifting tools to replace the transformer.&nbsp;</p><p>Plan to erect the scaffold and lifting tool tomorrow.</p><p><br></p><p>History :19 May 2024</p><p>Action : Prepared lifting gears for replacing hypochlorite transformer.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Borrowed lifting gears from mechanic team and keep at EI workshop.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Transformer oil drums have already relocated at lower deck chemical storage area.</p><p><br></p><p>History : 18 May 2024<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Inspected and prepared the Weldon pump for filling up the transformer oil after installing the new one.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Prepared the required accessories to assemble the pump, performed a dry test run at EI workshop.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Confirmed the pump is working properly and stored it together with necessary parts in EI workshop.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Requested the logistic team to relocate three transformer oil drums from Main Deck to chemical storage area on Lower Deck.</p><p><br></p><p>History : 17 May 2024</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Continued applying cable tags for new Ex-e junction box and Ex-e TR connection box.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Surveyed at the existing transformer junction boxes for new one replacement.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;Found that&nbsp;- Cable entry of existing Ex-e box need to be removed and to install at new one which lacks cable entry.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Need to change the new cable lugs (with 16.5mm hole size) for cable D6640-001A, B, C, D of current Ex-e TR connection box due to new TR terminal stud bolt size is 16.5mm.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Applied heat shrink to the damaged insulation cables.</p><p><br></p><p>History : 16 May 2024</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Surveyed the cable terminations of Ex-d and Ex-e junction boxes on new transformer.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Performed visual inspection on the Ex-d junction box and found that damaged cables insulation.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Damaged insulation was on the cable used for PE terminal from control Ex-e to Ex-d junction box. Found that cable was not terminated inside Ex-d junction box.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Applied the cable termination tags from Ex-e control junction box to Ex-e T/R connection box.&nbsp;</p>', NULL, '2024-05-21 17:17:23', '2024-05-21 17:23:12', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-6640', 'ZTK-X-6640', 'Hypochlorite Package', NULL, NULL, 'Hypochlorite Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'EI Team', NULL, 'EXTERNAL', '2024-05-21 17:17:23', '2024-05-21 17:23:12', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

