  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To changeover and verify ventilation fan 2 of GTC1', 'Electrical & Instrument', 'OTH ', 'Completed', '2024-05-22', '<p>Problem: On 20 May 2024: FM-4297B failure and automatically changeover to FM-4297A.</p><p>Action:</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 21 May 2024:</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Found that communication loss message at MCC for M-4297B.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Reset the drawer and communication loss alarm clear.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; FM-4297A is duty and FM-4297B is standby.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 22 May 2024:</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Checked the MCC drawer and found normal.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Checked the enclosure pressure is around 0.68 in H2O with fan 1 ( FM-4297A).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Inform CCR and changeover with fan 2 (FM-4297B).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; The enclosure pressure is 0.57 in H2O.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Alarm set point for enclosure pressure: Low Alarm = 0.25 in H2O, Low Low Alarm(SD)=0.15 inH2O.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; As left status: FM-4297A is standby and FM-4297B is duty.<br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-05-22_FM-4297B,To change over and verify ventilation fan 2 of GTC 4200">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-05-22_FM-4297B,To change over and verify ventilation fan 2 of GTC 4200</a><br></p>', '2024-05-22 14:47:25', '2024-05-22 14:52:27', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
