  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-V-6661B', 'ZTK-V-6661B', 'Permeator B', NULL, NULL, 'Permeator B', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
