  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix water seeping from ball valve flange', 'Mechanic', 'CM ', 'Completed', '2024-05-23', '<p>Problem - water seeping from 2 inch ball valve flange of PCV-6711.</p><p>As found - found misalign gasket with flange and wrong using gasket type.</p><p>Action - Loosen the stud bolts and remove the wrong gasket (2" 150 class SPW).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Install the correct gasket type (CNAF 2" 150 class) and retighten the stud bolts (69 Nm)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Waiting for leak test.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\P-6710 Diesel Fire Water Pump Package No. 2\\2024\\2024-05-23 Fix water seeping from ball valve flange">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\P-6710 Diesel Fire Water Pump Package No. 2\\2024\\2024-05-23 Fix water seeping from ball valve flange</a><br></p>', '2024-05-23 11:05:15', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6710-PCKG', 'ZTK-P-6710-PCKG', 'Fire Water Pump No.2', NULL, NULL, 'Fire Water Pump No.2', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
