  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S GA-02A Hot Plates no.1 & no.2 not working', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-05-23', '<p>Problem: GA-02A: 2 Hot plates Plates No. 1 and No. 2&nbsp; are not working.</p><p>Action:&nbsp; &nbsp;Checked the cable termination of hot plates(heating element).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;:&nbsp; Checked the current of hot plate(heating element) and found all hot plates(heating element) around 2.58 A.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;:&nbsp; Insulation test and found the heating element (Hot plate) No.1 insulation resistance is low.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Normalized the equipment and function testing.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Found RCCB tripped after power up.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Isolate the heating element no.1 and reset thermostat.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Performed test run again and found Heating elements No.2, 3 and 4 are working properly.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">Next Plan</span>: To replace Heating Element No.1.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p><br></p><p><br></p><p><br></p>', NULL, '2024-05-23 15:47:44', '2024-05-24 17:15:43', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
