  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S GA-02A Hot Plates no.1 & no.2 not working', 'Electrical & Instrument', 'CM ', 'Completed', '2024-05-24', '<p>Problem: GA-02A: Hot Plates No.1 not working.</p><p>Action:&nbsp; </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Replaced Hot plates No. 1 with new spare.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Performed insulation and resistant test for new spare heating element. (OK)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Function test run all hot plates and now all are working properly.</p><p><span style="background-color: rgb(255, 255, 0);">History</span></p><p><span style="background-color: rgb(255, 255, 0);">23.05.2024</span></p><p><span style="background-color: rgb(255, 255, 0);">Problem: GA-02A: 2 Hot plates Plates No. 1 and No. 2&nbsp; are not working.</span></p><p><span style="background-color: rgb(255, 255, 0);">Action:&nbsp; &nbsp;Checked the cable termination of hot plates(heating element).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;:&nbsp; Checked the current of hot plate(heating element) and found all hot plates(heating element) around 2.58 A.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;:&nbsp; Insulation test and found the heating element (Hot plate) No.1 insulation resistance is low.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Normalized the equipment and function testing.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Found RCCB tripped after power up.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Isolate the heating element no.1 and reset thermostat.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Performed test run again and found Heating elements No.2. 3 and 4 are working properly.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-05-24_GA-02A, TS hot plates No.1 and No.2 not working', '2024-05-24 15:45:40', '2024-05-24 17:35:15', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
