-- Inserting report ID 31685
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace hypochloride transformer', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-05-24', '<p>Action:Replace hypochlorite transformer</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Drill on the skip of hypochlorite to install the bolt for transformer by mechanic team.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Fill the transformer oil around 520 liters.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Install the cable termination of transformer and control junction box.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Install back lighting fixture.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Keep the lifting tools and clean the working area.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Keep the drum of use transformer oil and empty drum to lower deck drum area.</p><p>Plan to deisolate the power and function test.</p><p><br></p><p><span style="background-color: rgb(255, 0, 0);">Insulation resistance Test in X''mer</span></p><p><span style="background-color: rgb(255, 0, 0);">L1-G =235MOhm</span></p><p><span style="background-color: rgb(255, 0, 0);">L2-G =230MOhm</span></p><p><span style="background-color: rgb(255, 0, 0);">L3-G= 250MOhm</span></p><p><span style="background-color: rgb(255, 0, 0);"><br></span></p><p><span style="background-color: rgb(255, 0, 0);">Winding Resistance Test in X''mer</span></p><p><span style="background-color: rgb(255, 0, 0);">L1-L2 =0.5Ohm</span></p><p><span style="background-color: rgb(255, 0, 0);">L3-L2 =0.5Ohm</span></p><p><span style="background-color: rgb(255, 0, 0);">L1-L3 =0.5Ohm</span></p><p><span style="background-color: rgb(255, 0, 0);"><br></span></p><p><span style="background-color: rgb(255, 0, 0);">Thyristor Resistance</span></p><p><span style="background-color: rgb(255, 0, 0);">V1G-V1K = 17 Ohm</span></p><p><span style="background-color: rgb(255, 0, 0);">V2G-V2K = 16.6Ohm</span></p><p><span style="background-color: rgb(255, 0, 0);">V3G-V3K = 18 Ohm</span></p><p><span style="background-color: rgb(255, 0, 0);">V4G-V4K = 15.7Ohm</span></p><p><span style="background-color: rgb(255, 0, 0);">V5G-V5K = 16.8 Ohm</span></p><p><span style="background-color: rgb(255, 0, 0);">V6G-V6K = 17.4Ohm</span></p><p><span style="background-color: rgb(255, 0, 0);"><br></span></p><p><span style="background-color: rgb(255, 0, 0);">All Temperature Switch in X''mer = Closed</span></p><p><span style="background-color: rgb(255, 0, 0);">Level S/W in X''mer= Open (Before oil filling), Closed (After oil filling)</span></p><p><span style="background-color: rgb(255, 0, 0);">Approximately new 2.5 Drums was filled.</span></p><p><span style="background-color: rgb(255, 0, 0);"><br></span></p><p><span style="background-color: rgb(255, 0, 0);">Emergency Stop Function Test OK! (Tripped the breaker)</span></p><p>&nbsp;</p><p><br></p><p>History on 23-May-2024</p><p>Action: Replace hypochlorite transformer with new one due to transformer oil is leak.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Removed the cable from transformer and junction box to romove the transformer.(Existing one)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Removed the transformer oil form existing onw and store in empty drum( around 520 liters)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Put the label "used oil for hypochloride transformer oil" on empty drum,keep at he lay down area.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- After removed the existing one, keep it at the lower deck lay down area.( Wrapped with plastic)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Installed new transformer and junction box on skid.</p><p>Plan to install termination of new transformer.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-05-24_X-6640, Replace Hypochlorite Transformer', '2024-05-24 15:51:18', '2025-09-02 22:57:52', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-6640', 'ZTK-X-6640', 'Hypochlorite Package', NULL, NULL, 'Hypochlorite Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-05-24 15:51:18', '2025-09-02 22:57:52', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2024-05-24 15:51:18', '2025-09-02 22:57:52', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
