-- Inserting report ID 31687
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 2Y (8K) PM at P-4710 A', 'Mechanic', 'PM ', 'Completed', '2024-05-28', '<p><b><u>2024-05-24</u></b></p><p><b style="background-color: rgb(0, 255, 0);">Perform 2Y PM</b></p><p><b style="background-color: rgb(0, 255, 0);">DAY-1</b></p><p>- Drained old lube oil from crankcase and gearbox.</p><p>- Top-up lube oil - <b style="background-color: rgb(0, 255, 0);">crankcase- 60L and Gearbox- 9L.</b></p><p>- Disposed old lube oil into Used oil drum which locates at Upper Deck.</p><p>- Applied RTV gasket at crank case top cover.</p><p>- <b style="background-color: rgb(255, 156, 0);">According to bad weather (from 13:00 to 17:00), we''ll continue tomorrow.</b></p><p>- Housekeeping the area.</p><p><span style="background-color: rgb(255, 255, 0);">(<b> Found -&nbsp; Charging kit for Pulsation Damper is seeping from vent port even its in close position. Tomorrow, We''ll troubleshoot on it )</b></span></p><p><b><br></b></p><p><b><u>2025-05-25</u></b></p><p><b><u>DAY-2</u></b></p><p>- TS damper charging kit that''s malfunction.</p><p>- Found that vent valve is not working properly and replaced with another one from closed drain charging kit.( Closed drain charging kit also not working properly).</p><p>- So, I combined two <span style="background-color: rgb(0, 255, 0);">charging kit into one that''s working now.</span></p><p>- Removed stuffing box,2/2 rings, packing locking nuts, plungers and their locking nuts.</p><p>-&nbsp;<span style="background-color: rgb(255, 156, 0);"><b>According to bad weather (from 08:00 to 10:00 and 15:30 to 18:00), we''ll continue tomorrow.</b></span></p><p><span style="background-color: rgb(255, 156, 0);"><b><br></b></span></p><p><b ><u>2025-05-26</u></b></p><p><b ><u>DAY-3</u></b></p><p>- Installed<b><span style="background-color: rgb(0, 255, 0);"> "O-ring -4430'' , mean seal packing and rare seal packing</span> </b>at stuffing box.</p><p>- Preserved plungers and lock nuts, 2/2 rings and packing locking nuts.</p><p>- Installed all stuffing boxes on unit.</p><p>- Installed plungers and back pates.</p><p>-<b style="background-color: rgb(255, 156, 0);"> According to SSHE MS training ( From- 13:30 to 16:00),we''ll continue tomorrow.</b>
<br class="Apple-interchange-newline"></p><p><br></p><p><b><u>2025-05-27</u></b></p><p><b><u>DAY-4</u></b></p><p>- Recharged N2 pressure to pulsation damper - 40 bar.</p><p>- Re-tighten all locking nuts for plungers.</p><p>- Tightened with torque-330 Nm for plunger end plate.</p><p>- Need to Modify for packing cooling line due to flow indicator is damaged.&nbsp;</p><p><br></p><p><b><u>2025-05-28</u></b></p><p><b><u>DAY-5</u></b></p><p>- Fabricated and installed packing cooling line.</p><p>- Test run and adjust the packings.</p><p>- For plunger temperatures - no.1- 68 C, no.2- 70 C, no.3-67 C.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Dropping rates no.1- 7 drops/min, no.2- 5 drops/min and no.3- 7 drops/min.</p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\47 GLYCOL REGENERATION T1\\P-4710 A\\2024\\2024-05-24 2Y (8K)  PM">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\47 GLYCOL REGENERATION T1\\P-4710 A\\2024\\2024-05-24 2Y (8K)  PM</a><br></p>', '2024-05-24 17:39:50', '2024-05-28 17:59:36', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-4710A-ASSY', 'ZTK-P-4710A-ASSY', 'Glycol Circulation Pump Assembly Train1A', NULL, NULL, 'Glycol Circulation Pump Assembly Train1A', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'John', NULL, 'EXTERNAL', '2024-05-24 17:39:50', '2024-05-28 17:59:36', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kaung', NULL, 'EXTERNAL', '2024-05-24 17:39:50', '2024-05-28 17:59:36', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ko Sett', NULL, 'EXTERNAL', '2024-05-24 17:39:50', '2024-05-28 17:59:36', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
