  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S ZPQ crane can''t start', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-05-25', '<p>Found: Earth leakage lamp is activited at the X29A Motor Starterr Control panel.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Load Shed limit lamp is activited at the X26 Annuciator panel</p><p>Action: Checked the X29A junction box.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Tighten the cable termination.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Found no water ingress at the junction box.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Apply contact cleaner for all terminal block.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Earth leakage alarm is clear.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Checked the load shed limit.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked the load shed limit cable at X1/25 siginal pedestal junction box.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Disconnected the cable from X1/25 junction box.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Found that load shed for CR-7170 pedistal crane is enable at ECS.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Currently ZPQ crane is avilable.</p><p>Plan to check load shwd limit alarm at ECS and X3 main elecrtical control panel</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-05-25,CR-7170,TS ZPQ crane can''t start', '2024-05-25 17:31:54', '2024-05-25 17:36:04', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-7170', 'ZTK-CR-7170', 'ZPQ Platform Crane', NULL, NULL, 'ZPQ Platform Crane', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-05-25 17:31:54', '2024-05-25 17:36:04', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
