-- Inserting report ID 31695
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS hypochlorite transformer', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-05-25', '<p>Action : Power deisolate the hypochlorite transformer and performed function test.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Found that Q1 breaker tripped and cannot be turned ON due to XA-66411 transformer emergency stop status to LCP is activated.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked inside LCP-CPP-6640 and found that F4(2A) fuse had blown. Replaced with a spare fuse, reset the alarms and can Turn ON the Q1 breaker.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Local/Remote status cannot be changed by the switch on the Exe panel cannot physically make contact with the junction box contact inside. Use the washer to be more reachable to the contact.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Test run and found that K3 timer relay cannot activate the magnetic contact. Bypass the terminal (18/15) for 1 sec to energize the magnetic contact.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- During test run, rectifier cannot be controlled remotely by reason of malfunction transducer. So, selected to control rectifier by locally. </p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Additionally, local DC current adjuster on the Ex-e junction box panel cannot be operated caused by misalignment with the magnetism inside junction box. Re-aligned and it can operate now.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Tomorrow troubleshooting will continue.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">History on 24-May-2024</span><br></p><p>Action : Replace hypochlorite transformer</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Drill on the skip of hypochlorite to install the bolt for transformer by mechanic team.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Fill the transformer oil around 520 liters.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Install the cable termination of transformer and control junction box.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Install back lighting fixture.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Keep the lifting tools and clean the working area.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Keep the drum of use transformer oil and empty drum to lower deck drum area.</p><p>Plan to deisolate the power and function test.</p><p>&nbsp;</p><p>History on 23-May-2024</p><p>Action: Replace hypochlorite transformer with new one due to transformer oil is leak.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Removed the cable from transformer and junction box to remove the transformer.(Existing one)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Removed the transformer oil form existing onw and store in empty drum( around 520 liters)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Put the label "used oil for hypochlorite transformer oil" on empty drum, keep at he lay down area.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- After removed the existing one, keep it at the lower deck lay down area.( Wrapped with plastic)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Installed new transformer and junction box on skid.</p><p>Plan to install termination of new transformer.</p>', '\\\\pttep.com\\DFSRootZPQ\\zpqshare\\Department Share\\04_MAINTENANCE\\03 E&amp;I\\09 Document\\New Hypochlorite Transformer skid\\Installation Picture', '2024-05-25 19:44:54', '2024-05-28 17:55:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-6640', 'ZTK-X-6640', 'Hypochlorite Package', NULL, NULL, 'Hypochlorite Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'EI Team', NULL, 'EXTERNAL', '2024-05-25 19:44:54', '2024-05-28 17:55:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

