  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Rectify GTG train 1 Enclosure pressure low', 'Electrical & Instrument', 'CM ', 'Completed', '2024-05-26', '<p>Problem: PDT-72117-7 (PDT6180) enclosure differential pressure low alarm time to time due to strong wind.</p><p>Action: Re-oriented the low side atmosphere line tubing 3/8" but the reading was still low.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Prepared new fittings and tubing union T 3/8" the headline and adjust orientation at stable reading position.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: The reading is 0.46 inch-h2O and keep monitoring.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: During monitoring, the pressure Low Alarm (0.25 InchH2O)&nbsp; come again at 11:17:53 one time</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: After monitoring for 3 hrs, the differential pressure remains stable at around 0.52 inH2O.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Then, performed on load GTG-7210 and Stop GTG-7220.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p><br></p><p><br></p><p>&nbsp;</p>', NULL, '2024-05-26 11:26:40', '2024-05-26 16:20:25', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
