-- Inserting report ID 31708
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S ZAH07211B activate time by time for ESDV ', 'Electrical & Instrument', 'CM ', 'Completed', '2024-05-27', '<p><b><u>Problem</u></b>:&nbsp;ZAH07211B activate time by time for ESDV-07211.</p><p><b><u><span style="background-color: rgb(255, 255, 0);">Action</span>:</u></b> Informed CCR/Automaton to perform Force ZAH07211A/B/C.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Then, performed the ESDV vent/exhaust line manual force to keep opening the valve by connecting instrument tubing with isolation ball valve. (To prevent unexpected Valve may Close during troubleshooting)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Checked the as found proximity limit switch A, B and C.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Limit switch A &amp; B are OK but switch B was malfunctioned. (no voltage)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Performed self electrical isolation to replaced all limit switches.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Replaced all limit switches for ZAH07211A/ B and C.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : During replaced, observed that the cable lugs of limit switches ZAH07211A/B and C were not good condition. So, cut off the cable lugs, fixed and redressing all cables in good condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : After replaced new limit switches and performed de-isolation power, found there was no voltage for limit switches ZAH07211A/B/ C and also ZAH07215, ZAH07221, ZAH07231 were discrepancy (that caused ESD3M on WP07 and affected to WP-09 ESD3A activated).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Checked the DI card 1756-IB16D (DI) at EI room PLC cabinet and found no any signal LED&nbsp; status at the Card.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Verified the incoming signal lines for DI card and found the related fuse F-09 was blown.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: So, suspected that the limit switches of ZAH-07211 lines were short circuited.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Performed back self electrical isolation.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Verified all limit switches connections and found ZAH-07211B existing cable terminal block&nbsp; was not in good condition. So that caused short circuited and fuse F-09 Blown.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; : Changed the existing connection to others spare terminal block and ensured they were not grounded.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; : De-isolation back and checked the limit switches were back to normal.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; : Informed CCR/Automation to remove Force and checked the conditions of all limit switches one by one.</p><p>&nbsp; &nbsp; &nbsp; &nbsp;: Now cleared all limit switches Alarm and no more discrepancy.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-05-27_ESDV-07211, TS ZAH07211B activate time by time for ESDV', '2024-05-27 14:32:37', '2024-05-27 15:48:22', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP07', 'ZTK-WP07', 'Zawtika Wellhead Platform 07', NULL, NULL, 'Zawtika Wellhead Platform 07', 'WP07', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-ESDV-07211', 'ZTK-ESDV-07211', 'ESDV on 18"-GC-07011-B31.8 for ESD 1,2C', NULL, NULL, 'ESDV on 18"-GC-07011-B31.8 for ESD 1,2C', 'WP07', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2024-05-27 14:32:37', '2024-05-27 15:48:22', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-05-27 14:32:37', '2024-05-27 15:48:22', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-05-27 14:32:37', '2024-05-27 15:48:22', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
