  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Chemical Seeping From connecting rod', 'Mechanic', 'CM ', 'Completed', '2024-05-27', '<p>Problem : Chemical Seeping from Connecting Rod Chamber.</p><p>Found&nbsp; &nbsp; : Water ingress into the connecting rod chamber.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Drain plug at the connecting rod is loosen.</p><p>Action&nbsp; &nbsp; : (1) Drain out the residual water and clean the chamber.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Perform test run and verify no leak from PH buffer side and pump lube oil side. Found no leak.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Clean the seal area and apply new RTV and install back the acrylic plate.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\47 GLYCOL REGENERATION T1\\P-4784\\2024\\2024-05-27 TS chemical seeping from connecting rod">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\47 GLYCOL REGENERATION T1\\P-4784\\2024\\2024-05-27 TS chemical seeping from connecting rod</a><br></p>', '2024-05-27 18:01:30', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Cmms-Tech', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-4784-ASSY', 'ZTK-P-4784-ASSY', 'PH Buffer Injection Pump Assembly', NULL, NULL, 'PH Buffer Injection Pump Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Yan', NULL, 'EXTERNAL', '2024-05-27 18:01:30', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Cmms-Tech', NULL);
