  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS thawing machine can''t run', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-05-28', '<p><u>Problem:</u></p><p>- Thawing machine GA 26 show Error E01.</p><p><u>Found&nbsp;</u></p><p>-Thawing machine meat probe temperature sensor is not working and not showing temperature value</p><p><u>Action</u><br></p><p>- Replaced&nbsp; the food probe different NTC model type.</p><p>- Check the wiring terminal and inside cabinet probe.</p><p>- Manual Reset at the compressor control junction box.</p><p>- Performed the test run the unit and monitor the any abnormal.</p><p><br></p><p><br></p><p>Plan&nbsp;</p><p>Plan to rearrange the food probe sensor and plan to check the heating element function.</p><p>Plan to function test run with frozen meat.</p><p>&nbsp;&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-05-28_TS Thawing Machine">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-05-28_GA 26, TS Thawing Machine can''t run</a><br></p>', '2024-05-28 15:51:50', '2024-06-05 18:25:52', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
