-- Inserting report ID 31717
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS ZPQ crane engine stopped by load shedding alarm', 'Electrical & Instrument', 'CM ', 'Completed', '2024-05-28', '<p><b>Problem:</b></p><p>- ZPQ CR-71710, crane engine stopped by load shedding alarm.</p><p><b>Found:</b></p><p>- Water ingress inside slip ring junction box<b> (X2R Ring Side JB)</b>.</p><p><b>Action:</b></p><p>- Cleaned the water ingress and applied with contact cleaner.</p><p>- Checked all junction boxes inside slip ring.</p><p>- Checked the alarm and found load shedding alarm is cleared.</p><p>- Now, ZPQ crane is back to normal.</p><p><br></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History:</span></p><p><span style="background-color: rgb(255, 255, 0);">Found: Earth leakage lamp is activited at the X29A Motor Starterr Control panel.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Load Shed limit lamp is activited at the X26 Annuciator panel</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Checked the X29A junction box.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Tighten the cable termination.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Found no water ingress at the junction box.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Apply contact cleaner for all terminal block.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Earth leakage alarm is clear.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Checked the load shed limit.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked the load shed limit cable at X1/25 siginal pedestal junction box.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Disconnected the cable from X1/25 junction box.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Found that load shed for CR-7170 pedistal crane is enable at ECS.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Currently ZPQ crane is avilable.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to check load shwd limit alarm at ECS and X3 main elecrtical control panel</span></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-05-28_CR-7170, TS ZPQ Crane load shedding alarm">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-05-28_CR-7170, TS ZPQ Crane load shedding alarm</a><br></p>', '2024-05-28 15:52:13', '2024-05-28 16:05:01', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
