  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 6M PM Gas Composition Analyzer', 'Electrical & Instrument', 'PM ', 'In Progress', '2024-05-30', '<p><b>Today Action:</b></p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed base-line run for two times and then performed as-found condition check. (Not pass)</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed adjustment to the carrier gas from 110 bar to 100 bar with only one cylinder (no.2)</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed base-line run and performed as-found condition check. (Not pass)</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed calibration and not passed with "Excess response factor"<br></p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed maintenance check list again and adjusted for bridge balance and vent flow.&nbsp;</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Adjusted the carrier gas to 95 bar because of suspecting the excess response factor.&nbsp;</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed base-line run and as-found condition check. (Not pass)</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Adjusted the carrier gas to 115 bar and done as-found condition check in order to analysis the result. (Not pass)</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Adjusted the carrier gas back to 110 bar and performed as-found condition check with process gas (stream 2). (Not pass)</p><p>&nbsp; &nbsp;</p><p><b>Tomorrow: -</b>&nbsp; &nbsp; Going to perform as-found condition check with carrier gas 110 bar and bridge balance 0.1 and 0.2 mV.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;-&nbsp; &nbsp; If not pass, plan to replace new standard gas.<br></p><p><b><br></b></p><p><b style="background-color: rgb(255, 255, 0);">Yesterday 29/05/2024:</b></p><p><span style="background-color: rgb(255, 255, 0);"><b>Action</b> - Performed 6M PM for OGC as per procedure Rev.2. (Document No.: 13267-WIS-144-R02)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Informed CCR and changed&nbsp; Keypad mode.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Performed as-found condition checked and the result was fail.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replace new spare regulator at GC cylinder and adjusted as per maintenance check list.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;- In progress</span></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', NULL, '2024-05-30 15:34:52', '2024-05-30 19:04:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
