  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1M PM BDG on load test', 'Electrical & Instrument', 'PM ', 'Completed', '2024-06-03', '<div><u>Action:</u>&nbsp; &nbsp;<br></div><div><p>Performed 1M PM BDG 7205 on load test as per procedure.</p><p>- Performed pre-checked the generator before onload test run with worksite operator.</p><p>- Performed start the generator BDG-7205 and standby onsite operator during engine running cycle.</p>  <p>&nbsp;- Started the generator with both electric and hydraulic modes.</p><p></p><p>- Checked and recorded the generator parameter.</p><p>- Started the BDG with electric mode and ran for 1 hour with load.</p><p>- Checked the UCP panel after onload test.</p>  <p>- Checked the generator onsite after onload test.</p><p><br></p><p><b><u>Remark:</u></b></p><p>- After completed Stop cycle, checked inside the the generator and found oil seeping on the deck floor&nbsp;</p>  <p>- Investigated the seeping point and found it was come from the diesel return line.</p>  <p>- Found the fitting cap did not reinstall back in the diesel return line from engine to tank.</p><p><br></p><p><br></p><p><br></p></div>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-03_BDG-72005, 1MPM onload test', '2024-06-03 14:32:10', '2024-06-03 18:58:12', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
