-- Inserting report ID 31772
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Thawing machine breaker tripped', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-06-03', '<p>Problem: GA-26 Thawing machine breaker is tripped.</p><p>Found: The transformer power supply breaker F3 and F4 were tripped and Main Breaker MCCB was&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;tripped.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Found transformer is short circuit due to overload.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Found transformer current rating is 1.3 Amp, Heater running current is 5.1 Amp.</p><p>Action: Replace the transformer with 2.17 amp.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Plan to provide an external power supply to heater.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History on 29 May 2024</span></p><p>Action: Performed function test with froozen meat.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found that heating element E1(230V Ac) is not working but contactor K4 energized.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Check the heating element E1, internal resistance 31.7 Ohm, Insulation 2.96 Mohm.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Fount that voltage is drop around 170V AC due to natural is come from different loop (T2_control&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; transformer)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Reloop the natural point from power transformer (T1).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Heating element E1 is working. Running current is 5.1 Amp AC.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The unit is under monitoring.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);">History on 28 May 24</u><br></p><p><u>Problem:</u></p><p>- Thawing machine GA 26 show Error E01.</p><p><u>Found&nbsp;</u></p><p>-Thawing machine meat probe temperature sensor is not working and not showing temperature value</p><p><u>Action</u><br></p><p>- Replaced&nbsp; the food probe different NTC model type.</p><p>- Check the wiring terminal and inside cabinet probe.</p><p>- Manual Reset at the compressor control junction box.</p><p>- Performed the test run the unit and monitor the any abnormal.</p><p><br></p><p><br></p><p>Plan&nbsp;</p><p>Plan to rearrange the food probe sensor and plan to check the heating element function.</p><p>Plan to function test run with frozen meat.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06.03_GA 26, TS Thawing machine breaker tripped', '2024-06-03 15:40:18', '2024-06-05 18:23:03', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'Accommodation', 'Accommodation', 'Accommodation', NULL, NULL, 'Accommodation', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-06-03 15:40:18', '2024-06-05 18:23:03', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2024-06-03 15:40:18', '2024-06-05 18:23:03', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
