  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S GDU train 1 tripped', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-06-03', '<p>Problem: The pilot tube (4750) was tripped time by time.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The pilot flame was ON and the ionization current was around 4-5 microamp.</p><p>Action: Replaced the pilot tube and flame monitor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed a test of the unit.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The ionization current for pilot tube (4750): 7-9&nbsp; Micro Amp.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The Ionization current for pilot tube ( 4752): 14 Micro Amp.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found that the cable was loose at the pilot tube (4750). Secured it by wrapping with insulation tape&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; and tighting with cable tie.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The unit is currently operational and under monitoring.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-03_E-4750, TS GDU train 1 tripped', '2024-06-03 20:26:00', '2024-06-09 16:52:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
