  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-06-03 20:26:00', '2024-06-09 16:52:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
