-- Inserting report ID 31776
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot the OGC', 'Electrical & Instrument', 'CM ', 'Completed', '2024-06-04', '<p><b>Action:</b>&nbsp; &nbsp; -&nbsp; &nbsp; Performed troubleshooting the "total unnormalized mole concentration high alarm" at flow com.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Replaced first the standard cylinder with old one. (Cylinder No.: 22TE633)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Performed maintenance check list. (Adjusted bridge balance to 0.0 mV)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Performed baseline run for two times and calibration up to two times.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(RT and RF deviation are much more than tolerance: same as previous condition)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;(RF deviation tolerance : +/- 2, RT deviation tolerance: +/- 0.5)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Performed as-found condition check for four cycles and checked the BTU value and total unnormalized concentration value. &gt; total unnormalized concentration value = still high (102.1)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(Carrier gas pressure: 110 psi, standard gas pressure inlet: 20 psi, vent flow: 50 cc/min).</p><p><br></p><p><b>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</b>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; Performed&nbsp;to reduce carrier pressure to 105 psi and monitor the BTU value and the total&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; unnormalized concentration value are 101.5 - 101.6.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -&nbsp; The unit is currently operational and monitored for a week the GCV values and total unnormalized concentration values. (No more alarm comes and GCV is good).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;-&nbsp; Job is closed.<br></p><p><br></p><p><i><b>Note to Highlight:</b>&nbsp; &nbsp;&nbsp;</i></p><p><i>&nbsp; &nbsp; -&nbsp; &nbsp; When performing with standard gas, the repeatability for three analysis cycle runs are quite good. (Pass)</i></p><p><i>&nbsp; &nbsp; -&nbsp; &nbsp; But the reproducibility for analysis 2 and 3 verses certified conc.: are not good. (Not Pass) (Especially C3, i-C4 and n-C4)</i></p><p><i>&nbsp; &nbsp; -&nbsp; &nbsp; Then the maintenance check lists are within acceptable range.</i></p><p><i>&nbsp; &nbsp; -&nbsp; &nbsp; The problems we suspected are %RT and %RF deviations. And we have to adjust the RT and its related factors in accordance with as-found repeatability. (Out of performer''s capability)</i></p><p><i>&nbsp; &nbsp; -&nbsp; &nbsp; Need to discuss with vendor and get help from him.</i></p><p>&nbsp; &nbsp; -&nbsp; <i>&nbsp; For the alarm and GCV values monitoring, no more alarm comes after monitoring for a week.&nbsp;</i></p><p><i>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(The total unnormalized value is maintained around 101.3 - 101.6 and GCV values differences between ZPQ and ZOC is not much (about 942.37 (ZOC) - 941.24 (ZPQ) = 1.13 BTU/scf).&nbsp;<br></i><br></p><p><br></p><p><b style="background-color: rgb(255, 255, 0);">History:</b></p><p><b style="background-color: rgb(255, 255, 0);">02/06/2024</b></p><p><span style="background-color: rgb(255, 255, 0);">Today activity -&nbsp; &nbsp; Performed as-found condition check with carrier gas 110 bar and bridge balance 0.1 and 0.2 mV.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp;-&nbsp; &nbsp;Replaced new standard gas and updated component data as per the certification.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; - Performed base-line run for two times and then performed as-found condition check.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Performed adjustment to the carrier gas from 110 bar with two cylinders.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Performed base-line run and performed as-found condition check. (Not pass)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Performed calibration and not passed with "Excess response factor.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Adjusted the carrier gas to 105 bar because of suspecting the excess response factor.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Performed base-line run and as-found condition check. (Not pass)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Adjusted the carrier gas to 110 bar and done as-found condition check in order to analysis the result. (Not pass).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;- Normalized to the process (stream 2) and removed Keypad mode.</span></p><p><span style="background-color: rgb(255, 255, 0);">Next Plan:&nbsp;&nbsp; - To discuss with PMO/I &amp; Vendor for further action.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">History:</span></p><p><span style="background-color: rgb(255, 255, 0);">31/5/2024</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Performed base-line run for two times and then performed as-found condition check. (Not pass)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Performed adjustment to the carrier gas from 110 bar to 100 bar with only one cylinder (no.2)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Performed base-line run and performed as-found condition check. (Not pass)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Performed calibration and not passed with "Excess response factor"<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Performed maintenance check list again and adjusted for bridge balance and vent flow.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Adjusted the carrier gas to 95 bar because of suspecting the excess response factor.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Performed base-line run and as-found condition check. (Not pass)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Adjusted the carrier gas to 115 bar and done as-found condition check in order to analysis the result. (Not pass)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Adjusted the carrier gas back to 110 bar and performed as-found condition check with process gas (stream 2). (Not pass)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;29/05/2024:</span></p><p><span style="background-color: rgb(255, 255, 0);">Action&nbsp;- Performed 6M PM for OGC as per procedure Rev.2. (Document No.: 13267-WIS-144-R02)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Informed CCR and changed&nbsp; Keypad mode.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Performed as-found condition checked and the result was fail.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replace new spare regulator at GC cylinder and adjusted as per maintenance check list.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;- In progress</span></p>', NULL, '2024-06-04 15:22:12', '2024-06-12 08:45:02', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-AT-46001', 'ZTK-AT-46001', 'GC Analyzer Trans,M-4600,CH,CO2,N2 IND', NULL, NULL, 'GC Analyzer Trans,M-4600,CH,CO2,N2 IND', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-06-04 15:22:12', '2024-06-12 08:45:02', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-06-04 15:22:12', '2024-06-12 08:45:02', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation');
END $$;

