-- Inserting report ID 31778
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S GDU unit A tripped', 'Electrical & Instrument', 'CM ', 'Completed', '2024-06-04', '<p>Problem: GDU unit A tripped by burner low low alarm</p><p>Found&nbsp; &nbsp;: E-4750 pilot tube ionization current is around 2 micro Amp.</p><p>Action&nbsp; &nbsp;: Checked and tightened the cable terminal inside the junction box.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;Replaced the new overhauled pilot tube and but ionization current is still low.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Rearrange the ignition cable and ionization current is back to around 12 micro amp.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Suspect the cable and found the cable tip is defective.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;So, remove the defective cable and confirm cable connection by continuity test (OK).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Replaced the cable gland (M25) and secure the cable with cable tie.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Start the pilot and run the burner after purging cycle.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;The ionization current is around 13 to 18 micro-Amp (Normal in Range).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Now GDU 4700 is running normal.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">History:</span></p><p><span style="background-color: rgb(255, 255, 0);">Problem: The pilot tube (4750) was tripped time by time.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The pilot flame was ON and the ionization current was around 4-5 microamp.</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Replaced the pilot tube and flame monitor.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed a test of the unit.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The ionization current for pilot tube (4750): 7-9&nbsp; Micro Amp.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The Ionization current for pilot tube ( 4752): 14 Micro Amp.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found that the cable was loose at the pilot tube (4750). Secured it by wrapping with insulation tape&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; and tighting with cable tie.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The unit is currently operational and under monitoring.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-04_E-4750, TS GDU unit A tripped by burner low low alarm', '2024-06-04 17:41:53', '2024-06-04 18:09:52', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-E-4750-ASSY', 'ZTK-E-4750-ASSY', 'Fire Tube Heater Assembly', NULL, NULL, 'Fire Tube Heater Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-E-4752-ASSY', 'ZTK-E-4752-ASSY', 'Fire Tube Heater Assembly', NULL, NULL, 'Fire Tube Heater Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'William', NULL, 'EXTERNAL', '2024-06-04 17:41:53', '2024-06-04 18:09:52', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'E&I Team', NULL, 'EXTERNAL', '2024-06-04 17:41:53', '2024-06-04 18:09:52', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop');
