BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS UV Sterilizer Tripped and Alarm Time to Time', 'Electrical & Instrument', 'CM ', 'Completed', '2024-06-05', '<p>Activity:&nbsp;Troubleshoot fresh water UV sterilizer tripped and alarm time to time</p><p>Finding: Low intensity level with 36.9 W/m2 at 4010 lamp hours ( set point <b>=&lt;35.8</b> W/m2)</p><p>Action: - Removed and cleaned the UV sensor.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Flushed the UV chamber with fresh water.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Replaced UV lamp and quartz sleeve.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Reset the lamp hours to zero.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - System start up and back to normal. (Intensity level back to 44.2 W/m2)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Unit under monitoring.</p><p><br></p><p>Remark: Need to order UV sensor, lamp and sleeve.</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-05_X-6820, TS UV sterilizer tripped by low intensity">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-05_X-6820, TS UV sterilizer tripped by low intensity</a><br></p>', '2024-06-05 15:03:22', '2024-06-05 17:58:44', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
