  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1M PM EDG on load test', 'Electrical & Instrument', 'PM ', 'Completed', '2024-06-05', '<div><b><u>Action:</u>&nbsp; &nbsp;</b><span style="font-size: 14px;">Performed 1M PM EDG 7200 on load test as per procedure.</span></div><div><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Checked and recorded the generator parameter before and after.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Started the EDG with electric mode and ran for 1 hour with load.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Started the EDG with hydraulic mode and ran for 10 minutes with no load.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- EDG can run properly.</p><p><i><br></i></p><p><i>Note:&nbsp; &nbsp; The EDG was stopped on the first attempt by "Start Up Failure Speed Failed". After normalize the local and reset, performed second attempt. The EDG was running properly with no load and load via electric and hydraulic.</i></p></div>', NULL, '2024-06-05 16:07:31', '2024-06-05 16:10:28', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EDG-7200', 'ZTK-EDG-7200', 'Emergency Diesel Generator Package', NULL, NULL, 'Emergency Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
