-- Inserting report ID 31801
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS PDG-452 alternator malfunction', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-06-08', '<p>Activity: Troubleshoot PDG-452, alternator malfunction and cannot charge battery</p><p>Action&nbsp; : Water come out When we running the engine found the exhaust outlet that why we stopped the&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; engine and Switch off all the breaker.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; :We found water inside the engine oil tank checked together with Mechanic team.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Activity: Troubleshoot PDG-452, alternator malfunction and cannot charge battery</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: - Checked and tightened battery connection before test run for verifying alternator output.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- Performed test run and found generator stop without alarm when releasing start push button &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(can run normal on&nbsp;holding push button)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- Checked relays and found normal.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- Exercised inlet/outlet dampers limit switch and run PDG</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- PDG can be run normally.(Running time 5mins)&nbsp;&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- Verify battery charging current (0.2A)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- Stop the job due to heavy rain.<br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: - To&nbsp; run PDG for around 30 mins and monitor alternator output and battery voltage.</span></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-08_TS alternator malfunction and cannot charge the battery">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-08_TS alternator malfunction and cannot charge the battery</a><br></p>', '2024-06-08 14:53:35', '2024-06-08 17:45:10', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
