  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Belt Shaking at Lube Oil Cooler E-4393B', 'Mechanic', 'CM ', 'Completed', '2024-06-09', '<p>Problem : Belt is loosen and shaking.</p><p>Found : As found belt tension is 29.2 Hz.</p><p>Action : (1) Open and remove the pulley guard.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(2) Check as found alignment and belt tension.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(3) As found alignment is 29.2 Hz.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(4) As found belt condition is last replaced in 7-Sep-2023 by OGAS.<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(5) Adjust belt tension to 43.8 Hz in range condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(6) Clean the sprocket and cover.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(7) Unit running normal.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\Lube oil cooler\\E-4393B\\2024\\2024-06-09 TS Belt Shaking">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\Lube oil cooler\\E-4393B\\2024\\2024-06-09 TS Belt Shaking</a><br></p>', '2024-06-09 17:38:10', '2024-06-09 17:39:09', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
