  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix Water Leak at Fire Hose Reels', 'Mechanic', 'CM ', 'Completed', '2024-06-09', '<p>Tag No&nbsp; &nbsp; :&nbsp; X-9037(Mezzanine deck),X-9067 (cooler deck)</p><p>Problem&nbsp; : Water leak at fire hose reels swivel joints.</p><p>Found&nbsp; &nbsp; &nbsp;: (1) Seal ring at the water inlet line is damaged.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(2) O-ring at the swivel joint are long term usage and worn out.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(3) Replaced seal ring with O-ring and swivel joint O-ring.</p><p>Spare Parts : (1) Cross Ref. AN 6227 Dash Nos. (-27) ,Series No. 2-222 = 8 EA.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Cross Ref. AN 6227 Dash Nos. (-19) , Series No. 2-214 = 5 EA.</p>', NULL, '2024-06-09 18:13:49', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-9067', 'ZTK-X-9067', 'Fire Water Hose Reel on 2"-FW-67550-A7', NULL, NULL, 'Fire Water Hose Reel on 2"-FW-67550-A7', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
