  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS abnormal noise ', 'Mechanic', 'CM ', 'Completed', '2024-06-10', '<p>Problem:</p><p>Abnormal noise from PMA blower.</p><p><br></p><p>Action:</p><p>Test run and check the sound.</p><p>The abnormal noise come from blower side.</p><p>Stop the unit and removed the belt.</p><p>Check the blower bearing and found abnormal noise come from bearing.</p><p>Realignment the blower and motor slightly.</p><p>Install belt and check belt tension around 50 lbs.</p><p>Test run and abnormal noise still come from bearing.</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\78 TOPSIDE ENCLOSURE HVAC\\7802 Primary Muster Area HVAC System\\P-7880 A\\2024-06-10 TS abnormal noise">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\78 TOPSIDE ENCLOSURE HVAC\\7802 Primary Muster Area HVAC System\\P-7880 A\\2024-06-10 TS abnormal noise</a><br></p>', '2024-06-10 13:58:50', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-B-7880A', 'ZTK-B-7880A', 'Fan Coil Unit No.1', NULL, NULL, 'Fan Coil Unit No.1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
