  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S strange noise from fan coil unit A ', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-06-10', '<p>Problem; Fan coil unit B-7880A produces a strange noise when the unit is running.</p><p>Found: Blower bearing is degraded.</p><p>Action: Removed the belt from the motor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Manually turned the blower; identified strange noise</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Suspected the blower bearing is degraded, replacement required.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed motor alignment and adjusted the belt tension 50 lbs.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed test run the blower, the noise is still exist.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style="background-color: rgb(255, 255, 0);">Bearing Code: SKF YET205*2</span></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Currently the unit A is still running with strange noise.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The unit B is not cooling, Suspected low refrigerant.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Plan to troubleshoot the  unit B accordingly.</p><p><br></p><p>Plan to discuss with mechanic team to order bearing spare.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-10_B-7880A, TS strange noise from fan coil unit A', '2024-06-10 15:12:31', '2024-06-10 17:03:42', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
