-- Inserting report ID 31822
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace the defective motor bearing', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-06-10', '<p><b>&nbsp;Action :</b></p><p>Removed the motor fan and coupling.</p><p>Removed the DE &amp; NDE cover of the motor and the rotor.</p><p>Job is in progress.</p><p><b>Plan :</b></p><p>To be contiuned replace the motor bearing and reassembly the condenser motor and fan.</p><p><span style="background-color: rgb(255, 255, 0);"><b>History :</b></span></p><p><span style="background-color: rgb(255, 255, 0);">Problem: Chiller unit A (A-7820A) tripped due to overload caused by condensing fan motor (B-7802A-4).</span></p><p><span style="background-color: rgb(255, 255, 0);">Found: Condensing fan motor(B-7802A-4) and (B-7802A-3) fan were stuck.</span></p><p><span style="background-color: rgb(255, 255, 0);"><a href="action:Isolated">Action</a>: Isolated the power supply for the condensing fan motors.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Disconnected the power cables for condensing fan motors (B-7802A-3 and B-7802A-4).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Installed lifting gears as per the lifting plan.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the condensing fan motors from the frame.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Moved down the condensing motors to the floor.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Condensing fan motor B-7802A-3 and B-7802A-4 have already been moved down to the floor.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Both condensing fan are in workshop.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to replace the bearings for both motors with the mechanic team.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-10_B-7802-A-3&amp;4, Removed and overhual the condenser motor', '2024-06-10 15:53:00', '2024-06-10 17:08:24', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-B-7802C-ASSY', 'ZTK-B-7802C-ASSY', 'Condenser Fan C Assembly,Duty Chiller', NULL, NULL, 'Condenser Fan C Assembly,Duty Chiller', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
