-- Inserting report ID 31829
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S PMA HVAC compressor refrigerant low', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-06-11', '<p>Problem: ACCU unit B is not cooling.</p><p>Found: Suction and discharge pressure is low when the unit is running.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; As found suction and discharge pressure is around zero.</p><p>Action: Checked the compressor winding insulation and resistance.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found winding resistance is still low.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked the crankcase heater insulation and resistance. (OK)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed to test run of the compressor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found the initial starting current to be high at 49 A when the compressor is started then drop to&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 3.7A.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Charge the refrigerant (R134A) from the high side.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; As left suction pressure is 8 PSI and discharge pressure is 90 PSI.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Currently, ACCU unit A is running.</p><p>&nbsp; &nbsp; &nbsp; &nbsp;</p><p>Plan to charge the refrigerant from the suction side and find the refrigerant leak point.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-11_A-7890B, TS the PMA HVAC compressor refrigerant low', '2024-06-11 15:18:31', '2024-06-11 23:29:18', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-7890B', 'ZTK-A-7890B', 'Air Cooled Condensing Stand by Unit', NULL, NULL, 'Air Cooled Condensing Stand by Unit', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-C-7890B', 'ZTK-C-7890B', 'Compressor for PMA ACCU Stand by Unit', NULL, NULL, 'Compressor for PMA ACCU Stand by Unit', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-06-11 15:18:31', '2024-06-11 23:29:18', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2024-06-11 15:18:31', '2024-06-11 23:29:18', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
