-- Inserting report ID 31830
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Treadmill machine not working properly', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-06-11', '<p>Problem - Treadmill machine #TM 04 and 03 stop while starting machine.</p><p>Action&nbsp; &nbsp; - Start to operate both machine and waiting for some times.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Found it is working properly.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - But when we simulate the emergency stop by touching a little bit, it suddenly stop.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Suspect that it come from emergency stop pin and found some dirt.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - So, remove both emergency stop from #TM04 and 03 and clean with contact cleaner.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Perform function test and simulate again&nbsp; the emergency stop by touching a little bit and it is &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;working properly.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-11_Treadmill machine not working properly', '2024-06-11 16:04:46', '2024-06-11 17:52:32', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'Accommodation', 'Accommodation', 'Accommodation', NULL, NULL, 'Accommodation', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'William', NULL, 'EXTERNAL', '2024-06-11 16:04:46', '2024-06-11 17:52:32', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Turbine');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Brown', NULL, 'EXTERNAL', '2024-06-11 16:04:46', '2024-06-11 17:52:32', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Turbine');
