-- Inserting report ID 31835
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS water mixed with engine oil', 'Mechanic', 'CM ', 'Completed', '2024-06-18', '<p>Problem:</p><p>PDG 452 found white smoke and water come out from exhaust, water mixed with the engine oil.</p><p><br></p><p>Action:</p><p>Drain engine oil and found water mixed , engine oil color already changed to milky.</p><p>Removed exhaust silencer and found water come out from the flange and silencer. (about 15 liters)</p><p>Removed exhaust flame arrestor and found water come out.(about 15 liters)</p><p><br></p><p>On 12-6-2024:</p><p>-Remove tappet cover and check condition. Found milky lube oil.</p><p>-Use two hydraulic profile to support radiator and engine.</p><p>-Remove mounting and oil sump mounting bolts side by side</p><p>-Remove oil sump.</p><p>-Oil sump is still full of milky lube oil. Found no pieces of metal and debris</p><p>-Found injection line no 4 has diesel leak.</p><p>-Remove fuel injection line and injectors.</p><p>-Perform borescope inspection inside combustion chamber.</p><p>-Found a lot of water and oil mix.</p><p>-Perform housekeeping and job will be continued tomorrow.</p><p><br></p><p>On 13-06-2024:</p><p>-Remove lube oil suction strainer and pipe.</p><p>-Clean internal parts by using solvent and rags.</p><p>-Deep clean internal parts (Air inlet manifold/combustion chamber/crank case) by using utility air.</p><p>-Perform borescope inspection inside combustion chamber. Found no more oil.</p><p>-Flush oil channel by pouring new lube oil. Milky lube oil come out.</p><p>-Clean oil sump and make new gasket.</p><p>-Job will be continued tomorrow.</p><p><br></p><p>On 14-06-2024:</p><p>-Remove exhaust pipe line and flame arrestor.</p><p>-Remove exhaust manifold drain plug. Found a lot of water come out.</p><p>-Clean exhaust manifold and jacket water line by using utility air.</p><p>-Clean exhaust pipe line and muffler with utility water and air.</p><p>-Perform borescope inspection for the liners. All liners are a little bit corroded.</p><p>-Reinstall exhaust pipe line, flame arrestor and muffler.</p><p>-Flush lube oil line by pouring new lube oil from the top. Found no more milky oil come out.</p><p><br></p><p>On 15-06-2024:</p><p>-Install oil suction strainer.</p><p>-Install oil sump with new gasket and RTV.</p><p>-Install mounting plate.</p><p>-Install fuel injection line and injectors.</p><p>-Install new engine oil filter CAT 220 1523.</p><p>-Refill new engine oil (15W40 10 liters).</p><p>-Install engine tappet cover.</p><p>-Install air inlet line.</p><p>-Refill new coolant. (CAT ELC premix about 18 liters).</p><p><br></p><p>On 16-06-2024:</p><p>-Clean all combustion chambers with solvent and air.</p><p>-Top up lube oil 8 liters and coolant.</p><p>-Install tappet cover and air inlet line.</p><p>-Leave glow plug and test crank 3 times to check diesel flow.</p><p>-Install glow plug.</p><p>-Install air filter.</p><p>-Adjust belt tension.</p><p>-Start engine and check any abnormal condition.</p><p>-Found every condition is normal.</p><p>-Drain lube oil and replace with new oil. (8 liters)</p><p>-Perform housekeeping inside the skid.</p><p><br></p><p>On 18-06-2024:</p><p>-Drain all lube oil.</p><p>-Replace new lube oil filter.</p><p>-Fill new lube oil 15WD-40 (8 liters).</p><p>-Test run the engine about 15 minutes.</p><p>-Every condition is normal.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\102 PORTABLE EQUIPMENTS\\Mobile Gen DG-WP-452\\2024-06-11 TS water mix Engine oil">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\102 PORTABLE EQUIPMENTS\\Mobile Gen DG-WP-452\\2024-06-11 TS water mix Engine oil</a><br></p>', '2024-06-11 17:37:33', '2025-09-05 13:26:34', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Turbi', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-DG-WP-452', 'ZTK-DG-WP-452', 'Portable Diesel Generator', NULL, NULL, 'Portable Diesel Generator', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ko Sett', NULL, 'EXTERNAL', '2024-06-11 17:37:33', '2025-09-05 13:26:34', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Turbi');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kaung', NULL, 'EXTERNAL', '2024-06-11 17:37:33', '2025-09-05 13:26:34', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Turbi');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Plate', NULL, 'EXTERNAL', '2024-06-11 17:37:33', '2025-09-05 13:26:34', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Turbi');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Eric', NULL, 'EXTERNAL', '2024-06-11 17:37:33', '2025-09-05 13:26:34', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Turbi');
