  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'fix defective lighting fixture & emergency exit ', 'Electrical & Instrument', 'CM ', 'Completed', '2024-06-12', '<p>- Fx the defective lighting fixture at inlet separator area.</p><p>- LE-220-07Y06 (replace both lighting and ballast)</p><p>- LE-220-07B09 (replace&nbsp;both lighting and ballast)</p><p>- LN-200-14Y10 (replace lighting)</p><p>- LN-200-15R04(replace lighting)</p><p><br></p><p>Fix emergency exist lighting at office.<br></p><p>- LE-220-12R11 frame is left hanging.</p><p>- Drill new two holes wtih the self tapping screw and tighten them.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-12_fix defective lighting fixture &amp; emergency exit', '2024-06-12 16:04:19', '2024-06-12 16:57:34', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
