  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EF-4330C', 'ZTK-EF-4330C', '1st Stg Comp Disch Cooler Fan C', NULL, NULL, '1st Stg Comp Disch Cooler Fan C', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
