-- Inserting report ID 31845
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace gaskets regarding HRC0093', 'Mechanic', 'CM ', 'Completed', '2024-06-13', '<p>Problem: Replace gaskets due to HRC-0093.&nbsp;</p><p><br></p><p>Action:</p><p>PT-47509</p><p>Removed PT-47509, found SPW 3/4" 150# gasket.</p><p>Replaced with the 3/4" non CAF 150# gasket.</p><p>Applied 34 Nm torque to install the PT-47509.</p><p><br></p><p>Upstream ball valve of PCV-47266</p><p>Removed the ball valve.</p><p>Found SPW 3/4" 150# damaged gaskets at both side of the valve flange faces.</p><p>Clean the flange surfaces and ball valve surfaces.</p><p>Reinstalled with&nbsp;&nbsp;3/4" non CAF 150# gasket to both sides.</p><p>Applied 34 Nm torque to install the ball valve.</p><p><br></p><p>Downstream of FT 47501A</p><p>Removed the downstream flange of FT 47501A.</p><p>The flange is 1 1/2" size.</p><p>Found 1 1/2" non CAF 300# gasket.</p><p>Replaced with 1 1/2" non CAF 150# gasket.</p><p>Applied torque 69 Nm to install the flange.</p><p><br></p><p>Process deisolation and performed leak test.</p><p>Found No leak.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\47 GLYCOL REGENERATION T1\\General\\2024\\2024-6-13 Replace gaskets regarding HRC0093 (3 Points)">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\47 GLYCOL REGENERATION T1\\General\\2024\\2024-6-13 Replace gaskets regarding HRC0093 (3 Points)</a><br></p>', '2024-06-13 14:37:33', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SK-4700', 'ZTK-SK-4700', 'Glycol Regeneration Package Train 1', NULL, NULL, 'Glycol Regeneration Package Train 1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PT-47509', 'ZTK-PT-47509', 'PT on 3/4"-IA-47382,AL HI/LO & HH/LL ESD', NULL, NULL, 'PT on 3/4"-IA-47382,AL HI/LO & HH/LL ESD', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
