  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S PMA HVAC compressor refrigerant low', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-06-13', '<p>Action : Checked the compressor suction and discharge pressures.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Suction pressure 28 PSI , Discharge pressure, 190 PSI.( Not significantly different from before)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The compressor running current is 7.1 A .</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Rechecked the refrigerant leaking/Seeping points int the compressure compartment and&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; evaporator coil.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; No refrigerant leak/seeping points were not found in the compressor compartment and&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; evaporator&nbsp; coil.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Operate only unit B. The unit is under monitoring.&nbsp; </p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style="background-color: rgb(255, 0, 0);">(A little bit leak form the point which is mention last pictiure in this report. When open the cup&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; leak.)</span></p><p>Note: <span style="background-color: rgb(255, 255, 0);">Found that the lamp inside the blower is not working; needs to check the ballast.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found that the blower motor fan belt is shaking; requires replacement of the fan belt.</span></p><div class="flex-1 overflow-hidden"><div class="react-scroll-to-bottom--css-itmnk-79elbk h-full"><div class="react-scroll-to-bottom--css-itmnk-1n7m0yu"><div class="flex flex-col text-sm"><div class="w-full text-token-text-primary" dir="auto" data-testid="conversation-turn-3" data-scroll-anchor="true"><div class="py-2 juice:py-[18px] px-3 text-base md:px-4 m-auto md:px-5 lg:px-1 xl:px-5"><div class="mx-auto flex flex-1 gap-3 text-base juice:gap-4 juice:md:gap-5 juice:lg:gap-6 md:max-w-3xl lg:max-w-[40rem] xl:max-w-[48rem]"><div class="group/conversation-turn relative flex w-full min-w-0 flex-col agent-turn"><div class="flex-col gap-1 md:gap-3"><div class="flex flex-grow flex-col max-w-full"><div data-message-author-role="assistant" data-message-id="6504db58-78bd-41fb-b30c-4592ce2c1e7d" dir="auto" class="min-h-[20px] text-message flex flex-col items-start whitespace-pre-wrap break-words [.text-message+&amp;]:mt-5 juice:w-full juice:items-end overflow-x-auto gap-3"><div class="markdown prose w-full break-words dark:prose-invert light"><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History on 12 June 2024</span><br></p></div></div></div></div></div></div></div></div></div></div></div></div><p>Action: Perform the charging of the refrigerant from the compressor suction service port while the&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; compressor is running.<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The compressor is running at a current of 4.1 A (100% Load)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; After recharging the refrigerant (3-4 kg), the compressor running current is now 7.1 A (100% Load).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The compressor suction pressure is 28 PSI, and the discharge pressure is 190 PSI.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The compressor can run at the desired set point.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Find the refrigerant leak/seeping point using a snoop and refrigerant leak detector.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The refrigerant leak/seeping point cannot be found in the compressor compartment.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Operate only unit B. The unit is under monitoring.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">History on 11 June 2024</span></p><p>Problem: ACCU unit B is not cooling.</p><p>Found: Suction and discharge pressure is low when the unit is running.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; As found suction and discharge pressure is around zero.</p><p>Action: Checked the compressor winding insulation and resistance.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found winding resistance is still low.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked the crankcase heater insulation and resistance. (OK)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed to test run of the compressor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found the initial starting current to be high at 49 A when the compressor is started then drop to&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 3.7A.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Charge the refrigerant (R134A) from the high side.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; As left suction pressure is 8 PSI and discharge pressure is 90 PSI.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Currently, ACCU unit A is running.</p><p>&nbsp; &nbsp; &nbsp; &nbsp;</p><p>Plan to charge the refrigerant from the suction side and find the refrigerant leak point.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-13_A-7890B, TS PMA HVAC compressor refrigerant low', '2024-06-13 15:25:17', '2024-06-17 21:37:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-C-7890B', 'ZTK-C-7890B', 'Compressor for PMA ACCU Stand by Unit', NULL, NULL, 'Compressor for PMA ACCU Stand by Unit', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-B-7890B-ASSY', 'ZTK-B-7890B-ASSY', 'Condenser Fan Assy for PMA Stand by ACCU', NULL, NULL, 'Condenser Fan Assy for PMA Stand by ACCU', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-06-13 15:25:17', '2024-06-17 21:37:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'William', NULL, 'EXTERNAL', '2024-06-13 15:25:17', '2024-06-17 21:37:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
