-- Inserting report ID 31849
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Upgrade LTMR for MCC drawer.', 'Automation', 'OTH ', 'In Progress', '2024-06-13', '<p><b>Action Today:</b></p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed follow-up action for MCC communication loss which is LTMR100MBD (P6805A and simulation station) is not working after firmware upgraded.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed collecting log file and calibration file from TeSys Programmer as per Schneider''s suggestion.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed to check and test at simulation station but still not succeeded.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Plan to test at local LTMR100MBD of P-6850A tomorrow.<br></p><p><br></p><p><br></p><p><b>History:</b></p><p><span style="background-color: rgb(255, 255, 0);">09 May 2024:</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Setup LTMR100MBD in simulation station to test for Firmware version upgrading.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;Open P-6850A_MCC.psx in SoMove 2.9.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed “Store to device” the file.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed “Firmware update”.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;Performed to upgrade at LTMR100MBD (Simulation and test setup) to version 3.0 from version 2.4.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; But Pop-up message shows that “LTMR Firmware Update Partially Successful” and</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; “Restore Settings: FAILURE”.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Performed to downgrade at LTMR100MBD (Simulation and test setup)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;to version 2.4 from version 3.0.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;But Pop-up message shows that “LTMR Firmware Update Partially Successful” and</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;“Restore Settings: FAILURE”.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Summarized the findings at simulation station and</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;the findings at upgrading at P-6805A on 27-Apr-2024.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Sent email to PMO/I and vendor to give advise and the way forwards.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History:&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Problem&nbsp; &nbsp;: MCC communication loss follow up action to upgrade LTMR firmware version 2.4 to 3.0.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Sequence of event for LTMR Firmware update activity,</span></p><p><span style="background-color: rgb(255, 255, 0);">1.&nbsp;&nbsp;&nbsp;&nbsp;P6805A,&nbsp;F14-6, Drawer Type&gt;&gt;&gt;&gt;LVM1, LTMR100MBD,LTMEV40BD version 1.9.</span></p><p><span style="background-color: rgb(255, 255, 0);">As Found &nbsp; &nbsp;: Chek LTMR network address and firmware version before upgrading LTMR version.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &gt;&gt; LTMR Original FW version * 2.4 * and LTMCU language Pack *1.1*.</span></p><p><span style="background-color: rgb(255, 255, 0);"></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Action&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;:&nbsp;Connect with SoMove (2.9) and Backup configuration file before performing LTMR FW upgrade.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;: Connect with Tesys Programming Tools(3.2) to upgrade.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;: Found that alert MSG was POP up as below,</span></p><p><span style="background-color: rgb(255, 255, 0);"></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : Inside TeSys Programming tools cannot find the correct Calibration files to open after that click ok and its automatically start Updating as below,</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : When its reach to&nbsp;Backup setting to Device step,&nbsp;alarm msg was pop up as below,</span></p><p><span style="background-color: rgb(255, 255, 0);"></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : After alarm msg was pop up, wait for nearly 30 Min and found there has no improvement. Force close the TeSys Program and try to reconnect found&nbsp;LTMR FW was already updated to Version 3.0.</span></p><p><span style="background-color: rgb(255, 255, 0);"></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : Try to upgrade LTMR FW version and "Alarm Msg stil popup to choose correct Calibrated File to choose". This time found calibration file inside Tesys Programmer folder. Select the Calibration file after that its start updating. During this time its only&nbsp;Execute restore setting to device step.&nbsp;After that Update successfully message was pop up. After that update&nbsp;LTMCU Language Pack.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;Original LTMCU language pack &gt;&gt;&gt;&gt; 1.1&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; New LTMCU Language pack&nbsp;&nbsp; &nbsp; &gt;&gt;&gt;&gt; 1.3</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : Open Config file for Drawer P6805A and connect with SoMove and alarm Message was pop up as below,</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;"Configuration you created is not compatible with connected device."&nbsp;<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: After that follow the procedure that vendor provided and after that can communicate with LTMR by using SoMove software.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Test Run and Problem,</span></p><p><span style="background-color: rgb(255, 255, 0);">Activity,</span></p><p><span style="background-color: rgb(255, 255, 0);">Inform CCR to test run and CCR give start command from PCS and Drawer can start normally.</span></p><p><span style="background-color: rgb(255, 255, 0);">After running around 3-10sec MCC show stop and PCS show discrepancy alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);">Site operator informed that Pump start at local and after that stop around 3-10 sec.</span></p><p><span style="background-color: rgb(255, 255, 0);">Conclusion,</span></p><p><span style="background-color: rgb(255, 255, 0);">Suspect that FW upgrading activity LTMR has error and its effect the configuration and calibration setting of the LTMR.&nbsp;</span></p>', NULL, '2024-06-13 15:54:57', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-06-13 15:54:57', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Liam', NULL, 'EXTERNAL', '2024-06-13 15:54:57', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL);
END $$;

