  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Upgrade LTMR for MCC drawer.', 'Automation', 'OTH ', 'In Progress', '2024-06-13', '<p><b>Action Today:</b></p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed follow-up action for MCC communication loss which is LTMR100MBD (P6805A and simulation station) is not working after firmware upgraded.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed collecting log file and calibration file from TeSys Programmer as per Schneider''s suggestion.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed to check and test at simulation station but still not succeeded.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Plan to test at local LTMR100MBD of P-6850A tomorrow.<br></p><p><br></p><p><br></p><p><b>History:</b></p><p><span style="background-color: rgb(255, 255, 0);">09 May 2024:</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Setup LTMR100MBD in simulation station to test for Firmware version upgrading.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;Open P-6850A_MCC.psx in SoMove 2.9.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed “Store to device” the file.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed “Firmware update”.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;Performed to upgrade at LTMR100MBD (Simulation and test setup) to version 3.0 from version 2.4.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; But Pop-up message shows that “LTMR Firmware Update Partially Successful” and</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; “Restore Settings: FAILURE”.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Performed to downgrade at LTMR100MBD (Simulation and test setup)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;to version 2.4 from version 3.0.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;But Pop-up message shows that “LTMR Firmware Update Partially Successful” and</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;“Restore Settings: FAILURE”.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Summarized the findings at simulation station and</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;the findings at upgrading at P-6805A on 27-Apr-2024.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Sent email to PMO/I and vendor to give advise and the way forwards.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History:&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Problem&nbsp; &nbsp;: MCC communication loss follow up action to upgrade LTMR firmware version 2.4 to 3.0.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Sequence of event for LTMR Firmware update activity,</span></p><p><span style="background-color: rgb(255, 255, 0);">1.&nbsp;&nbsp;&nbsp;&nbsp;P6805A,&nbsp;F14-6, Drawer Type&gt;&gt;&gt;&gt;LVM1, LTMR100MBD,LTMEV40BD version 1.9.</span></p><p><span style="background-color: rgb(255, 255, 0);">As Found &nbsp; &nbsp;: Chek LTMR network address and firmware version before upgrading LTMR version.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &gt;&gt; LTMR Original FW version * 2.4 * and LTMCU language Pack *1.1*.</span></p><p><span style="background-color: rgb(255, 255, 0);"></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Action&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;:&nbsp;Connect with SoMove (2.9) and Backup configuration file before performing LTMR FW upgrade.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;: Connect with Tesys Programming Tools(3.2) to upgrade.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;: Found that alert MSG was POP up as below,</span></p><p><span style="background-color: rgb(255, 255, 0);"></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : Inside TeSys Programming tools cannot find the correct Calibration files to open after that click ok and its automatically start Updating as below,</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : When its reach to&nbsp;Backup setting to Device step,&nbsp;alarm msg was pop up as below,</span></p><p><span style="background-color: rgb(255, 255, 0);"></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : After alarm msg was pop up, wait for nearly 30 Min and found there has no improvement. Force close the TeSys Program and try to reconnect found&nbsp;LTMR FW was already updated to Version 3.0.</span></p><p><span style="background-color: rgb(255, 255, 0);"></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : Try to upgrade LTMR FW version and "Alarm Msg stil popup to choose correct Calibrated File to choose". This time found calibration file inside Tesys Programmer folder. Select the Calibration file after that its start updating. During this time its only&nbsp;Execute restore setting to device step.&nbsp;After that Update successfully message was pop up. After that update&nbsp;LTMCU Language Pack.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;Original LTMCU language pack &gt;&gt;&gt;&gt; 1.1&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; New LTMCU Language pack&nbsp;&nbsp; &nbsp; &gt;&gt;&gt;&gt; 1.3</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : Open Config file for Drawer P6805A and connect with SoMove and alarm Message was pop up as below,</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;"Configuration you created is not compatible with connected device."&nbsp;<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: After that follow the procedure that vendor provided and after that can communicate with LTMR by using SoMove software.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Test Run and Problem,</span></p><p><span style="background-color: rgb(255, 255, 0);">Activity,</span></p><p><span style="background-color: rgb(255, 255, 0);">Inform CCR to test run and CCR give start command from PCS and Drawer can start normally.</span></p><p><span style="background-color: rgb(255, 255, 0);">After running around 3-10sec MCC show stop and PCS show discrepancy alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);">Site operator informed that Pump start at local and after that stop around 3-10 sec.</span></p><p><span style="background-color: rgb(255, 255, 0);">Conclusion,</span></p><p><span style="background-color: rgb(255, 255, 0);">Suspect that FW upgrading activity LTMR has error and its effect the configuration and calibration setting of the LTMR.&nbsp;</span></p>', NULL, '2024-06-13 15:55:35', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-06-13 15:55:35', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Liam', NULL, 'EXTERNAL', '2024-06-13 15:55:35', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL);
END $$;

-- Inserting report ID 31851
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace the defective motor bearing', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-06-13', '<p><b >Action (13-Jun-23):</b></p><p>Reinstalled back two overhauled condeser fan motor at chiller unit A on site.</p><p><b>Plan :</b></p><p>Will perform function test run and check the condenser fun condition on site.</p><p><br></p><p><b>History :</b></p><p><span style="background-color: rgb(255, 255, 0);">12/06/2024</span>
<br class="Apple-interchange-newline"></p><p><span style="background-color: rgb(255, 255, 0);">Replaced the motor bearing for both NDE and DE side.</span></p><p><span style="background-color: rgb(255, 255, 0);">Reassembly both motors and checked winding resistance ( 2.5 Ohms) and insulation resistance (&gt; 550 M-Ohms).</span></p><p><span style="background-color: rgb(255, 255, 0);">Performed function test at workshop without load.</span></p><p><span style="background-color: rgb(255, 255, 0);">Both motors can run smoothly and found no abnormal noise.</span></p><p><span style="background-color: rgb(255, 255, 0);">Reassembly blower fans installation is completed.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: Tomorrow, we will install back both condenser fan on skid.</span></p><p><span style="background-color: rgb(255, 255, 0);">Bearing Part No: 6306-2Z (SKF)</span></p><p><span style="background-color: rgb(255, 255, 0);">MESC :&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;58.01.10.906.1</span></p><p><span style="background-color: rgb(255, 255, 0);">11/06/2024</span></p><p><span style="background-color: rgb(255, 255, 0);">Action :</span></p><p><span style="background-color: rgb(255, 255, 0);">Removed the DE &amp; NDE bearing of the motor.</span></p><p><span style="background-color: rgb(255, 255, 0);">Cleaned the motor and fan accessories.</span></p><p><span style="background-color: rgb(255, 255, 0);">Job is in progress.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan :</span></p><p><span style="background-color: rgb(255, 255, 0);">To be contiuned replace the motor bearing and reassembly the condenser motor and fan.</span></p><p><span style="background-color: rgb(255, 255, 0);">History :</span></p><p><span style="background-color: rgb(255, 255, 0);">10-06-2024</span></p><p><span style="background-color: rgb(255, 255, 0);">Action :</span></p><p><span style="background-color: rgb(255, 255, 0);">Removed the motor fan and coupling.</span></p><p><span style="background-color: rgb(255, 255, 0);">Removed the DE &amp; NDE cover of the motor and the rotor.</span></p><p><span style="background-color: rgb(255, 255, 0);">Job is in progress.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan :</span></p><p><span style="background-color: rgb(255, 255, 0);">To be contiuned replace the motor bearing and reassembly the condenser motor and fan.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">09-06-2024</span></p><p><span style="background-color: rgb(255, 255, 0);">Problem: Chiller unit A (A-7820A) tripped due to overload caused by condensing fan motor (B-7802A-4).</span></p><p><span style="background-color: rgb(255, 255, 0);">Found: Condensing fan motor(B-7802A-4) and (B-7802A-3) fan were stuck.</span></p><p><span style="background-color: rgb(255, 255, 0);"><a href="action:Isolated">Action</a>: Isolated the power supply for the condensing fan motors.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Disconnected the power cables for condensing fan motors (B-7802A-3 and B-7802A-4).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Installed lifting gears as per the lifting plan.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the condensing fan motors from the frame.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Moved down the condensing motors to the floor.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Condensing fan motor B-7802A-3 and B-7802A-4 have already been moved down to the floor.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Both condensing fan are in workshop.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to replace the bearings for both motors with the mechanic team.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-13_B-7802-A-3&amp;4, Replaced the motor bearing', '2024-06-13 15:56:42', '2024-06-13 17:46:34', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-B-7802C', 'ZTK-B-7802C', 'Condenser Fan C for Duty Chiller', NULL, NULL, 'Condenser Fan C for Duty Chiller', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-B-7802D', 'ZTK-B-7802D', 'Condenser Fan D for Duty Chiller', NULL, NULL, 'Condenser Fan D for Duty Chiller', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
