  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Joseph', NULL, 'EXTERNAL', '2024-06-13 15:56:42', '2024-06-13 17:46:34', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bo', NULL, 'EXTERNAL', '2024-06-13 15:56:42', '2024-06-13 17:46:34', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
