  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support GDU 4700 start up', 'Electrical & Instrument', 'OTH ', 'Completed', '2024-06-13', '<p>-&nbsp;Support GDU 4700 start up after mechanic team gasket replacement activities.</p><p>- Open Junction box and check pilot ionization current :</p><p>&nbsp; E- 4750 : 19.10 Micro Amp.</p><p>&nbsp; E- 4752 : 16.23 Micro Amp.</p><p>- Now GDU 4700 is back to service.</p>', NULL, '2024-06-13 16:02:52', '2024-06-13 16:03:15', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
