-- Inserting report ID 31853
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify antisurge valve fully open intermittently ', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-06-13', '<p>Problem: Antisurge valve(second stage) fully open and close intermittently two times at GTC train-3.</p><p>Action: Check the alarm history at UCP panel.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Antisurge valve is fully opened and closed two times. </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; For first time, <span style="background-color: rgb(255, 255, 0);">take 84 milliseconds(opening time).</span></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;For second time, <span style="background-color: rgb(255, 255, 0);">take 407 milliseconds(opening time).</span></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Visually checked the I/O card module condition.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Check the instruments supply pressure and visually check the smart positioner at the local.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found air seeping at the valve control volume booster inlet and outlet connection.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">Plan: If happen again, will check the wiring loop and I/O module of the antisurge valve and fix the air seeping.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-13_FV-44530, Verify second stage antisurge valve open intermittently', '2024-06-13 17:21:51', '2024-06-13 18:09:13', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4400', 'ZTK-GTC-4400', 'Train 3,Gas Turbine Comp Package', NULL, NULL, 'Train 3,Gas Turbine Comp Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
