-- Inserting report ID 31860
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhaul 2nd stage anti surge valve', 'Electrical & Instrument', 'OTH ', 'In Progress', '2024-06-14', '<p>Action: Prepare and check the spare part repair kits of second stage anti surge valve<span style="background-color: rgb(255, 255, 0);"> (FV-4X530).</span></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Transer the anti surge valve from transformer area to the workshop to overhaul.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Remove the instrument tubing, smart positoner, volume booster and positoner indicator.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Job progress<span style="background-color: rgb(255, 255, 0);"> 5% completed.</span><br></p><p><br></p><p>Plan: Continue to remove the vave and actuator assembly. And will replace repair kit and perform calibration and function test.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-14_FV-4X530, Overhaul sencond stage anti surge valve', '2024-06-14 16:23:51', '2024-06-14 16:36:27', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
