-- Inserting report ID 31861
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace the defective motor bearing', 'Electrical & Instrument', 'CM ', 'Completed', '2024-06-14', '<p>Action :</p><p>Performed function test run the chiller unit A (A-7802A).</p><p>Checked the condenser fan at the worksite.</p><p>Checked and measured the running current for both overhauled condenser fans.</p><p>For B-7802A-3, L1 = 4.2 A , L2 = 4.17 A , L3 = 3.57 A</p><p>For B-7802A-4, L1 = 4.2 A , L2 = 4.13 A , L3 = 3.56 A</p><p>Now, Unit A is duty and unit B is standby.</p><p><br></p><p><b style="background-color: rgb(255, 255, 0);">History :</b></p><p><span style="background-color: rgb(255, 255, 0);">13-Jun-2024</span></p><p><span style="background-color: rgb(255, 255, 0);">Action :</span></p><p><span style="background-color: rgb(255, 255, 0);">Reinstalled back two overhauled condeser fan motor at chiller unit A on site.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan :</span></p><p><span style="background-color: rgb(255, 255, 0);">Will perform function test run and check the condenser fun condition on site.</span></p><p><span style="background-color: rgb(255, 255, 0);">12/06/2024<br class="Apple-interchange-newline"></span></p><p><span style="background-color: rgb(255, 255, 0);">Replaced the motor bearing for both NDE and DE side.</span></p><p><span style="background-color: rgb(255, 255, 0);">Reassembly both motors and checked winding resistance ( 2.5 Ohms) and insulation resistance (&gt; 550 M-Ohms).</span></p><p><span style="background-color: rgb(255, 255, 0);">Performed function test at workshop without load.</span></p><p><span style="background-color: rgb(255, 255, 0);">Both motors can run smoothly and found no abnormal noise.</span></p><p><span style="background-color: rgb(255, 255, 0);">Reassembly blower fans installation is completed.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: Tomorrow, we will install back both condenser fan on skid.</span></p><p><span style="background-color: rgb(255, 255, 0);">Bearing Part No: 6306-2Z (SKF)</span></p><p><span style="background-color: rgb(255, 255, 0);">MESC :&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;58.01.10.906.1</span></p><p><span style="background-color: rgb(255, 255, 0);">11/06/2024</span></p><p><span style="background-color: rgb(255, 255, 0);">Action :</span></p><p><span style="background-color: rgb(255, 255, 0);">Removed the DE &amp; NDE bearing of the motor.</span></p><p><span style="background-color: rgb(255, 255, 0);">Cleaned the motor and fan accessories.</span></p><p><span style="background-color: rgb(255, 255, 0);">Job is in progress.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan :</span></p><p><span style="background-color: rgb(255, 255, 0);">To be contiuned replace the motor bearing and reassembly the condenser motor and fan.</span></p><p><span style="background-color: rgb(255, 255, 0);">History :</span></p><p><span style="background-color: rgb(255, 255, 0);">10-06-2024</span></p><p><span style="background-color: rgb(255, 255, 0);">Action :</span></p><p><span style="background-color: rgb(255, 255, 0);">Removed the motor fan and coupling.</span></p><p><span style="background-color: rgb(255, 255, 0);">Removed the DE &amp; NDE cover of the motor and the rotor.</span></p><p><span style="background-color: rgb(255, 255, 0);">Job is in progress.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan :</span></p><p><span style="background-color: rgb(255, 255, 0);">To be contiuned replace the motor bearing and reassembly the condenser motor and fan.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">09-06-2024</span></p><p><span style="background-color: rgb(255, 255, 0);">Problem: Chiller unit A (A-7820A) tripped due to overload caused by condensing fan motor (B-7802A-4).</span></p><p><span style="background-color: rgb(255, 255, 0);">Found: Condensing fan motor(B-7802A-4) and (B-7802A-3) fan were stuck.</span></p><p><span style="background-color: rgb(255, 255, 0);"><a href="action:Isolated">Action</a>: Isolated the power supply for the condensing fan motors.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Disconnected the power cables for condensing fan motors (B-7802A-3 and B-7802A-4).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Installed lifting gears as per the lifting plan.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the condensing fan motors from the frame.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Moved down the condensing motors to the floor.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Condensing fan motor B-7802A-3 and B-7802A-4 have already been moved down to the floor.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Both condensing fan are in workshop.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to replace the bearings for both motors with the mechanic team.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-14_B-7802A-3&amp;4 Replaced defective motor bearing', '2024-06-14 16:30:22', '2024-06-14 16:39:30', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-B-7802C-ASSY', 'ZTK-B-7802C-ASSY', 'Condenser Fan C Assembly,Duty Chiller', NULL, NULL, 'Condenser Fan C Assembly,Duty Chiller', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-B-7802D-ASSY', 'ZTK-B-7802D-ASSY', 'Condenser Fan D Assembly,Duty Chiller', NULL, NULL, 'Condenser Fan D Assembly,Duty Chiller', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Joseph', NULL, 'EXTERNAL', '2024-06-14 16:30:22', '2024-06-14 16:39:30', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2024-06-14 16:30:22', '2024-06-14 16:39:30', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine');
