-- Inserting report ID 31866
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Check Spare feeder LTMR', 'Automation', 'CM ', 'Completed', '2024-06-14', '<p>Activity,</p><p>Action&nbsp; &nbsp; : Check spare feeder (F19-30 ) which was suspected LTMR damage.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Connect LTMR with Tesys Programming tools and check LTMR calibration file as per vendor recommendation and found that there has no calibration data.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Installed hot spare part (LTMR) at simulation and check calibration data and calibration data was found in hot spare LTMR. Save calibration data from hot spare part (LTMR).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Installed back up calibration file from Hot Spare (LTMR) to the (F19-30) feeder. However, alarm msg was pop up and cannot write data to Spare Feeder.&nbsp;</p><p>&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Check the Tesys Log file and found that <b>Checksum value </b>must be put to write the calibration data. Check sum value can be found inside TeSys log file and put in the <b>Checksum Tab.</b></p><p>After filling the checksum value <b>Calibration data </b>can write to LTMR.</p><p><br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br></p>', NULL, '2024-06-14 17:53:30', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Liam', NULL, 'EXTERNAL', '2024-06-14 17:53:30', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-06-14 17:53:30', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL);
END $$;

