DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Test run spare feeder at P-6805A', 'Automation', 'CM ', 'Under Monitoring', '2024-06-15', '<p><b>Action Today:</b></p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed test run and monitor spare feeder at fresh water pump A, P-6805A.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Racked-out the existing fresh water pump A from the feeder.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed as-found data check to its calibration registers and log files via Tesys Programmer Tools.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed parameter list check via SoMove.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Backed-up calibration registers and log files of existing fresh water pump A, P-6805A.&nbsp;<br></p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Compared its data (existing fresh water pump A, P-6805A) with the spare feeder data. {<i>Found that the checksum value (30400) in the P-6805A is not matched with the spare feeder data''s (30566)}</i></p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Upload the configuration files to the spare feeder.<i><br></i></p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Rewrite calibration registers of P-6805A to spare feeder data and change checksum value to 30566.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Rack-in the spare feeder data for P-6805A and performed test run with operator.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; The fresh water pump A, P-6805A is properly running. </p><p>&nbsp; &nbsp; -&nbsp;&nbsp;&nbsp;&nbsp;<i><b>No trip, properly running and keep under monitoring.</b></i><br></p><p><br></p><p><b style="background-color: rgb(255, 255, 0);">History:</b></p><p><b style="background-color: rgb(255, 255, 0);">14/06/2024</b></p><p><span style="background-color: rgb(255, 255, 0);">Activity,</span></p><p><span style="background-color: rgb(255, 255, 0);">Action&nbsp; &nbsp; : Check spare feeder (F19-30 ) which was suspected LTMR damage.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Connect LTMR with Tesys Programming tools and check LTMR calibration file as per vendor recommendation and found that there has no calibration data.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Installed hot spare part (LTMR) at simulation and check calibration data and calibration data was found in hot spare LTMR. Save calibration data from hot spare part (LTMR).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Installed back up calibration file from Hot Spare (LTMR) to the (F19-30) feeder. However, alarm msg was pop up and cannot write data to Spare Feeder.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Check the Tesys Log file and found that&nbsp;Checksum value&nbsp;must be put to write the calibration data. Check sum value can be found inside TeSys log file and put in the&nbsp;Checksum Tab.</span></p><p><span style="background-color: rgb(255, 255, 0);">After filling the checksum value&nbsp;Calibration data&nbsp;can write to LTMR.</span></p>', NULL, '2024-06-15 15:28:09', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6805A-ASSY', 'ZTK-P-6805A-ASSY', 'Fresh Water Pump A Assembly', NULL, NULL, 'Fresh Water Pump A Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
