  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Liam', NULL, 'EXTERNAL', '2024-06-15 15:28:09', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL);
