  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS charging battery voltage low alarm', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-06-16', '<p>Problem: Battery voltage low alarm come and EDG is not ready to start.</p><p>Action: Perform visually checked the battery and found battery was replaced since 9-06-2018.</p><p>-Found one battery is deformed and terminal is corroded.</p><p>-Charge the new battery at workshop to replace.</p><p>-Perform electrical isolation and remove the old batteries.</p><p>-Installed the new batteries.</p><p>-Start the engine with electric mode, engine can start properly but stop by "Engine red alarm" after 1 min.</p><p>-Start the engine with electric mode second times, engine cannot reach to combustion stage by low battery voltage.</p><p>-Tried to start the engine with hydraulic mode but not success because of leak at hydraulic motor fitting.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -During unit stop, "Emergency shutdown genset" alarm is pop up.</p><p>-Plan to charge the battery overnight and Mech will fix hydraulic leak at tomorrow.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-16_EDG-7200, TS battery voltage low alarm', '2024-06-16 15:53:10', '2024-06-18 14:33:26', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
