-- Inserting report ID 31891
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S control net channel B shows fault', 'Automation', 'CM ', 'Completed', '2024-06-17', '<p><b>Activity today,</b></p><p><b>Activity&nbsp;</b> &nbsp; : Troubleshoot control net channel B show fault,</p><p><b>Action</b>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Installed (End tap or Terminator Plugs 75 ohm) at the Node 11 (JBN-080) channel B Tab. </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Checked at PLC and found that all the node in front of Node 11 show fault. (downstream of JBN-080)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- After that, swapped with channel A cable from (JBN-081&nbsp; to JBN-080) and test again this time. (All the note can be found on PLC). </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Found that Control net cable "A" (JBN-081 to JBN-080) has some stress at cable tap due to improper cable laying.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Also found ControlNet cable "B" (JBN-081 to JBN-080) has some stress at cable tap as well.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - After rearrange cable, both channel shows healthy.</p><p><br></p><p><b>Next Plan:</b></p><p>&nbsp; &nbsp; -&nbsp;&nbsp;&nbsp;&nbsp;Need to order control net cable accessories to perform troubleshooting activity for future reliability.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Need to replace <b>Two ControlNet cables</b> from <i><b>JBN-WP03-081 to JBN-WP03-080 </b></i>with <b>new cable taps</b>.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; (length: 12 ft).</p><p>Note:&nbsp; &nbsp;-&nbsp; Also<b> cable tap</b> from <i><b>JBN-WP03-080 to JBN-WP03-006</b></i> has some stress. <i>(Side of JBN-WP03-080)</i></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - But since that cable length is long and seem hard to replace, so better to cut and change <b>cable tap</b>&nbsp;only.</p><p><br></p><p><b>FYI:</b>&nbsp; ControNet cable specification</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - BELDEN&nbsp; 3092A RO-6/U TTPE 75C QUAD SHIELD 1C13 CONTROLNET (TM) CABLE B34972 (W)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Junction box cover dimension for JBN-WP03-006 replacement,&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Width: 79.5 cm, Height: 99.5 cm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History,</span></p><p><span style="background-color: rgb(255, 255, 0);">Activity:&nbsp;T/S control net channel A shows fault</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Tried to force the ESDV-03221 and ESDV-03215 by plugging vent of valve actuator but it was difficult &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;to access.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Forced the ESDV-03221 and ESDV-03215 by suppling external nitrogen from the vent of pilot valve.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Now, valves are remain open position and waiting 10 min before shutdown the plant for abnormality.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Note: Automation will scan the control net for fault point.</span></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-17_WP03-ControlNet Channel A and B fault">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-17_WP03-ControlNet Channel A and B fault</a><br></p>', '2024-06-17 15:43:28', '2024-06-17 23:58:04', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SCS-WP03-001', 'ZTK-SCS-WP03-001', 'PLC Control Assembly for WP03', NULL, NULL, 'PLC Control Assembly for WP03', 'WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Liam', NULL, 'EXTERNAL', '2024-06-17 15:43:28', '2024-06-17 23:58:04', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-06-17 15:43:28', '2024-06-17 23:58:04', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2024-06-17 15:43:28', '2024-06-17 23:58:04', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop');
