  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Open strainer cover for inspection', 'Mechanic', 'CM ', 'Completed', '2024-06-20', '<p>Issue: To remove strainer SP-0048 cover for inspection due to leakage.</p><p>Action: </p><p>On 17-06-2024:</p><p>-Remove all fastening bolts.</p><p>-Remove strainer cover. Move cover into workshop.</p><p>-Perform inspection by inspector.</p><p>-Found corrosion.</p><p>-Remove strainer and clean with utility water.</p><p><br></p><p>On 18-06-2024:</p><p>-Clean stud bolts.</p><p>-Make new rubber gasket.</p><p><br></p><p>On 19-06-2024:</p><p>-Perform NDT test for welding joint.</p><p>-Apply belzona 1111 at flange surface.</p><p>-Clean flange surface.</p><p><br></p><p>On 20-06-2024:</p><p>-Reinstall strainer cover.</p><p>-Tighten bolts with torque 382 N-m.</p><p>-Perform leak test with pressure 11 barg.</p><p>-Found no leak.</p><p>-Permit handback and monitor the condition.</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\Fire Ring Main\\2024\\2024-06-17 Fire water ring main strainer internal eroded at vent port">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\Fire Ring Main\\2024\\2024-06-17 Fire water ring main strainer internal eroded at vent port</a><br></p>', '2024-06-17 17:08:52', '2024-06-20 18:34:11', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
