  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Strange noise from the belt E-4360A', 'Mechanic', 'CM ', 'Completed', '2024-06-17', '<p>Problem - Strange noise from the belt.</p><p>Found -&nbsp; Motor pulley stopper and fan belt is touching each other.</p><p>Action -&nbsp; (1) Removed fan cover and Checked belt tension - 23 Hz.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Checked alignment and removed shim 0.6mm form left and right upper side of motor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Removed fan belt, replace motor pulley and adjust the motor''s pulley position.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (4) Replace the new belt.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (5) Adjust belt tension - 24.6 Hz and Installed back the cover.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (6) Apply belt dressing spray (WD-40).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (7) Test run with satisfy result.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\GAS COOLER FAN (E-4360-A and E-4360B)\\E-4360 (2nd Stage)\\E-4360A\\2024\\2024-06-17 TS strange noise">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\GAS COOLER FAN (E-4360-A and E-4360B)\\E-4360 (2nd Stage)\\E-4360A\\2024\\2024-06-17 TS strange noise</a><br></p>', '2024-06-17 17:28:58', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
