-- Inserting report ID 31897
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform EDG Hyd seeping', 'Mechanic', 'CM ', 'Completed', '2024-06-17', '<p>Problem : hydraulic seeping from hydraulic starter motor</p><p>Found&nbsp; &nbsp; &nbsp;: hydraulic seeping from charge line ( inlet line)</p><p>Action&nbsp; &nbsp; &nbsp; : remove the hydraulic hose from outlet line( return to tank)&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; remove bracket of hydraulic pipe</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; remove inlet line fitting of starter motor</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; found NPT fitting is installed by large amount of seal tape</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;try to find BSPP fitting(BSPP -British Standard Parallel Pipe) ( SAE 16 )</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;after found BSPP fitting the another end is NPT thread</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;after adapter were connected fitting are</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;starter motor(female) -BSPP(Male)- NPT(Male)-NPT(Female)-NPT(Female)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;NPT(Male)-Swagelok(Male) .</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;after installation the fitting test run and found not leak&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\72 MAIN &amp; VITAL POWERr GENERATION\\7200 Emergency Diesel Generator\\2024\\2024-04-17 hyd seeping from starter">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\72 MAIN &amp; VITAL POWERr GENERATION\\7200 Emergency Diesel Generator\\2024\\2024-04-17 hyd seeping from starter</a><br></p>', '2024-06-17 18:53:34', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EDG-7200', 'ZTK-EDG-7200', 'Emergency Diesel Generator Package', NULL, NULL, 'Emergency Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'ALi', NULL, 'EXTERNAL', '2024-06-17 18:53:34', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
