-- Inserting report ID 31899
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S EDG emergency shutdown genset alarm', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-06-18', '<p>-No more alarm activated at last night. Maintain the K1(Emergency shutdown genset) loop by cleaning and tightening.</p><p>-Verify loose connection and heat spot by using thermoscan at A001.3 (ECP fuses) JB, A001.1 ECP PLC JB and A001.1 ECP terminals JB.</p><p>-Found heat point (70''C) inside the A001.3 ECP fuses JB, at locking terminal beside the K1 magnetic contactor (Emergency shutdown contactor) and K1,K2 and K3 all are heat up to 60''C. (Always energize in normal condition)</p><p>-Isolated the DC power supply by de-energizing K132 contactor for ECP.</p><p>-Investigate the locking terminal and found terminal is hot by heat radiation from K1 contactor coil. Whereas no burning sign had found on both K1 contactor and locking terminal.</p><p>-Conclusion, all loop continuity are ok. Voltage drop around 2VDC at the loop (K1 contactor measurement A1 &amp; A2 = 21.65VDC) and Heat dissipation from K1,K2,K3 may play major role for spurious shutdown.</p><p>-Will keep monitor and take action upon finding at next.</p><p>-De-isolate the DC power supply for ECP and function test EDG with electrical starter motor.</p><p>-EDG can start properly and on load test also success.</p>', NULL, '2024-06-18 13:41:11', '2024-06-18 16:05:01', 'PTTEP\\ZPQ.EI-Supv', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EDG-7200', 'ZTK-EDG-7200', 'Emergency Diesel Generator Package', NULL, NULL, 'Emergency Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Sithu', NULL, 'EXTERNAL', '2024-06-18 13:41:11', '2024-06-18 16:05:01', 'PTTEP\\ZPQ.EI-Supv', 'PTTEP\\ZPQ.EI-Supv');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bo', NULL, 'EXTERNAL', '2024-06-18 13:41:11', '2024-06-18 16:05:01', 'PTTEP\\ZPQ.EI-Supv', 'PTTEP\\ZPQ.EI-Supv');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2024-06-18 13:41:11', '2024-06-18 16:05:01', 'PTTEP\\ZPQ.EI-Supv', 'PTTEP\\ZPQ.EI-Supv');
