-- Inserting report ID 31901
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S pressure switch is activated', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-06-18', '<p>Action&nbsp; &nbsp; : Removed pressure switch PS-65102, fixed adjuster mechanism and adjust pressure set point.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; High pressure set point PSH-65102&nbsp;is 3.1 bar</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Low pressure set point PSL-65102 is 0.68 bar.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Function test with operation team. <span style="background-color: rgb(0, 255, 0);">(Completed)</span></p><p><br></p><p><span style="background-color: rgb(255, 156, 0);">Tomorrow will perform on PS-65101</span></p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);">History</u></p><p><span style="background-color: rgb(255, 255, 0);">Problem: T/S pressure switch is activated while tower starts to pressurize</span></p><p><span style="background-color: rgb(255, 255, 0);">Found: Low pressure switch(PSL-68102) is activated while unit is stop (Air dryer A_A-6510A)</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Performed to test run the air dryer A, Found that while air dryer is pressurized PSL is activated.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked the pressure switch, found the pressure switch contact is not functioning properly.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Replaced the pressure switch with a new spare.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed to test run again on the unit, PSL alarm is still exist.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found that pressure switch mechanism is malfunction.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Plan to removed the pressure switch and recalibrate it in work shop.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Note: PSL-65101 is activated as well.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-18_PS-65102 TS pressure switch activated', '2024-06-18 15:43:12', '2024-06-18 17:42:09', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PS-65101', 'ZTK-PS-65101', 'Press SW on Air Dryer Tank A,AL HI-LO', NULL, NULL, 'Press SW on Air Dryer Tank A,AL HI-LO', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
