  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To assist PMO/E for wind turbine ZTK-MOD-22010', 'Electrical & Instrument', 'MD ', 'In Progress', '2024-06-18', '<p>Activity:&nbsp;To assist PMO/E for wind turbine ZTK-MOD-22010</p><p>Action: Performed the cable laying from PJB-WP-02-355 to SCS cabinet for signal cable of TEG/Wind &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;turbine switching status to show at HMI&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Glanding the power cable at PJB-WP-02-355&nbsp;to tie in at VR-WP-02-350.&nbsp;</p><p><br></p><p>Plan: Tomorrow, continue termination the wiring at SCS cabinet and function test the switching and monitor in HMI.</p><p><br></p><p><br></p><p><u style="background-color: rgb(255, 255, 0);">History:</u></p><p><span style="background-color: rgb(255, 255, 0);">Activity:&nbsp;To assist PMO/E for wind turbine ZTK-MOD-22010</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Perform re alignment for junction box position.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Performed installation for cables termination.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Re located wind sensor from in front of EI room to helideck near solar panels.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; All TEGs are left running except G.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wind turbine are left running by isolating TEG/WIND TURBINE SWITCHING&nbsp;jUNCTION BOX</span></p><p><span style="background-color: rgb(255, 255, 0);">(PJB- WP02-355)<br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Activity:&nbsp;To assist PMO/E for wind turbine ZTK-MOD-22010</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Removed the junction box for wind turbine and TEG switching temporary by scaffolding</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Installed the junction box for charge controller and wind turbine and TEG switching permanently.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; All TEGs are left running except G, and wind turbine need to stop for cable disconnected while junction box installation.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Activity:&nbsp;To assist PMO/E for wind turbine ZTK-MOD-22010</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Supported the PMO/E team to install the wind sensor at helideck</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; But cannot install at helideck location&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Installed infront of EI Room.</span></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-18_Assist PMOE for wind turbine ZTK-MOD-22010', '2024-06-18 16:36:52', '2024-06-18 17:22:06', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP02', 'ZTK-WP02', 'Zawtika Wellhead Platform 02', NULL, NULL, 'Zawtika Wellhead Platform 02', 'WP02', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Peter', NULL, 'EXTERNAL', '2024-06-18 16:36:52', '2024-06-18 17:22:06', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
