-- Inserting report ID 31906
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'P-4710B Glycol Circulation pump 2Y PM', 'Mechanic', 'PM ', 'Completed', '2024-06-20', '<p>18.06.2024</p><p>-Drained gear oil from the crankcase.</p><p>-Drained gear oil from the reducer gearbox.</p><p>-Removed the coupling guards and check the couplings condition.</p><p>-Removed the end plates of the plunger from the hydraulic end.</p><p>-Disconnected the cross head and plunger by removed the two to two rings.</p><p>-Removed all the plungers out and checked the plunger condition.</p><p>-Removed the plunger packing and stuffing boxes.</p><p>-Housekeeping the area.</p><p><br></p><p>19.06.2024</p><p>-Cleaned the plungers and check the plunger condition.</p><p>-Removed existing mean seal packings and rear seal packing.</p><p>-Cleaned the stuffing boxes and check the condition.</p><p>-Inserted the new packings into the stuffing boxes.</p><p>-Installed stuffing boxes at the hydraulic end.</p><p>-Reconnected the plungers with the crossheads and tighten the crosshead lock nuts.</p><p>-Removed the suction strainer and cleaned &amp; checked the strainer condition.</p><p>-Filled the gear oil and crankcase oil.</p><p>-Checked the pulsation dampener''s bladder nitrogen pressure found (10.18bar)&nbsp;</p><p><br></p><p>20.06.2024</p><p>-Charged nitrogen to the pulsation dampener(40Bar)</p><p>-Fabricated the packing drain line that damaged at its ferrules.</p><p>-Connect the packing&nbsp; drain line between plunger stuffing boxes and suction manifold.</p><p>-Applied RTV to the crankcase top cover and tighten its screw.</p><p>-Test run the pump and running normal.</p><p>-Adjusted the plunger packing and keep monitoring for temperature and glycol drop per minute.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\47 GLYCOL REGENERATION T1\\P-4710 B\\2024\\2024-06-18 2Y PM">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\47 GLYCOL REGENERATION T1\\P-4710 B\\2024\\2024-06-18 2Y PM</a><br></p>', '2024-06-18 18:11:44', '2024-07-28 16:43:01', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-4710B', 'ZTK-P-4710B', 'Glycol Circulation Pump Train 1B', NULL, NULL, 'Glycol Circulation Pump Train 1B', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2024-06-18 18:11:44', '2024-07-28 16:43:01', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Henry', NULL, 'EXTERNAL', '2024-06-18 18:11:44', '2024-07-28 16:43:01', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kaung', NULL, 'EXTERNAL', '2024-06-18 18:11:44', '2024-07-28 16:43:01', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
