  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Upgrade LTMR firmware to 3.0 for MCC drawers.', 'Automation', 'OTH ', 'Completed', '2024-06-19', '<p>Activity,</p><p>Upgrade LTMR Firmware version for F19-30 from 2.4 to 3.0.</p><p>Upgrade LTMCU language pack 1.1 from 1.3.</p><p><b>Preparation to Upgrade FW as follow,</b></p><p>1. Backup SoMove Configuration before performing upgrade.</p><p>2. Backup Calibration file by Tesys Programing tools before upgrade FW.</p><p>3. Save TeSys Log File before Upgrade.</p><p>Upgrade FW version as follow,</p><p>1. Connect LTMR module with TeSys Programming tools.</p><p>2. Select Desire FW version.</p><p>3. Click Update.</p><p>4. If the Alert message was pop up "Corrupted Calibration File".</p><p>5. Click ok and browse the Calibration file which is backup in preparation step.</p><p>6.Firmware&nbsp; Upgrade version step will start automatically after selecting Calibration File.</p><p>7. If Updated successfully Message was pop up "Click " Ok.</p><p>After restart power for LTMR.&nbsp;</p><p><br></p>', '\\\\pttep.com\\DFSRootZPQ\\zpqshare\\Department Share\\04_MAINTENANCE\\03 E&amp;I\\01 Automation\\01. Picture and Document for History Report\\Hand Over Rev.52 (27 May to 25 Jun 24)\\20240619_F19-30 FW upgrade', '2024-06-19 15:41:17', '2025-04-15 08:04:34', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
