  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS GDFR fault alarm ', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-06-19', '<p>Problem : GDFR-40021 shows fault alarm time to time.</p><p>Found&nbsp; &nbsp; : GDFR status shows normal reading.</p><p>Action&nbsp; &nbsp; : Checked the aliagnment between tramsmitter and receiver. Found good condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Cleaned and tightened the terminal.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;Cleaned the len sensor both sides.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed the zero calibration.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp;&nbsp; &nbsp; &nbsp;Performed the alarm function test with CCR.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The GDFR is under monitoring.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-19_GDFR-40021, TS GDFR shows fault alarm', '2024-06-19 15:55:21', '2024-06-27 13:15:36', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
