  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhaul 2nd stage anti surge valve', 'Electrical & Instrument', 'OTH ', 'In Progress', '2024-06-19', '<p><u>Today Action</u></p><p>-Re-assemble the internal part of the actuator (actuator stem, spring and piston).</p><p>Job progress-20% completed.</p><p>Plan: Continue to perform overhaul for valve internal parts.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History:15-06-2024</span></p><p><u style="background-color: rgb(255, 255, 0);">Today Action</u></p><p><span style="background-color: rgb(255, 255, 0);">-Remove the actuator from the valve body.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">-Remove the actuator cylinder and disassemble the internal parts.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Clean the all internal assembly and perform visual check.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Replace yoke O-ring, piston O-ring and actuator stem O-ring.</span></p><p><span style="background-color: rgb(255, 255, 0);">Job progress-10% completed.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: Continue to reinstall back all assembly internal part of the actuator. After that, will install back to valve body.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History: 14-06-2024<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Prepare and check the spare part repair kits of second stage anti surge valve&nbsp;(FV-4X530).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Transfer the anti surge valve from transformer area to the workshop to overhaul.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Remove the instrument tubing, smart positoner, volume booster and positoner indicator.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Job progress&nbsp;5% completed.<br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: Continue to remove the vave and actuator assembly. And will replace repair kit and perform calibration and function test.&nbsp;</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-19_FV-4X530, Overhual 2nd stage anti surge valve', '2024-06-19 15:56:59', '2024-06-19 16:10:27', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
