  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Lube oil cooler fan E-4293A belt shaking.', 'Mechanic', 'CM ', 'Completed', '2024-06-19', '<p>Problem : Belt is loosen and shaking.</p><p>Found : As found belt tension is 29.2 Hz.</p><p>Action : (1) Open and remove the pulley guard.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(2) Check as found alignment and belt tension.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(3) As found alignment is 29.2 Hz.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(5) Adjust belt tension to 43.8 Hz in range condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(6) Clean the sprocket and cover.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(7) Unit running normal.</p>', '\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ&nbsp; MECH&nbsp; HISTORY PICTURE\\01 ZPQ\\42 GAS COMPRESSOR T 1\\Lube oil cooler fan\\E-4293A\\2024\\2024-06-19 TS belt shaking', '2024-06-19 16:54:03', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-FM-4293A', 'ZTK-FM-4293A', 'Lube Oil Cooler Fan Motor No.1', NULL, NULL, 'Lube Oil Cooler Fan Motor No.1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
