-- Inserting report ID 31918
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS ZPQ crane engine stopped by load shedding alarm', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-06-20', '<p><b><u>Today Action</u></b></p><p>-Remove the breather (Drain Plug) of slip ring. Found water come out from slip ring.</p><p>-Open the slip ring<span style="background-color: rgb(255, 255, 0);"> upper junction box (X2R) </span>of signal cable and power cable.</p><p>-Found water ingress inside and clean the water and visual check the terminal.</p><p>-Open the slip ring lower JB <span style="background-color: rgb(255, 255, 0);">(signal cable box- X2B2)</span>. There is no water ingress and good condition.</p><p>-For the power cable of<span style="background-color: rgb(255, 255, 0);"> lower JB (X2B1)</span> is not yet checked.</p><p>-For the load shedding signal cable at the outside of crane column is not yet terminated.</p><p><br></p><p>Plan: Continue to check the inside of slip ring and to check the insulation resistance test for all JB of slip ring and apply silicon and Denso tape at the potential of water ingress place.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History : 6-06-2024
</span></p><p><span style="background-color: rgb(255, 255, 0);">
Problem:
</span></p><p><span style="background-color: rgb(255, 255, 0);">
- ZPQ CR-7170, crane engine stopped by load shedding alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found:</span></p><p><span style="background-color: rgb(255, 255, 0);">- Water ingress inside slip ring junction box.</span></p><p><span style="background-color: rgb(255, 255, 0);">Action:</span></p><p><span style="background-color: rgb(255, 255, 0);">- Removed the loading shedding alarm cable inside X1/25 junction box due to ZPQ ready to use.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Checked the alarm and found load shedding alarm is cleared.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Now, ZPQ crane is avaiable.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Job is in progress.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan:</span></p><p><span style="background-color: rgb(255, 255, 0);">- To be continued the water ingress.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-20_CR-7170, TS load shedding alarm and check sling ring junction box', '2024-06-20 15:58:28', '2024-06-20 16:26:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-7170', 'ZTK-CR-7170', 'ZPQ Platform Crane', NULL, NULL, 'ZPQ Platform Crane', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Peter', NULL, 'EXTERNAL', '2024-06-20 15:58:28', '2024-06-20 16:26:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2024-06-20 15:58:28', '2024-06-20 16:26:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
