  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S EDG emergency shutdown genset alarm', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-06-20', '<p>-EDG-7200 shows alarm "Emergency shutdown genset" while in stop condition.</p><p>-As found both air shutoff and fuel valve are close and emergency shutdown activated.</p><p>-Checked engine package emergency push button ESB1,ESB2,ESB3 and ECP emergency push button. All the cables connection and condition are ok.</p><p>-Checked all ECP emergency shutdown cable loop and found normal.</p><p>-Temporary jump (X10/101 and X10/1) at the ECP panel in order to confirm spurious signal come from UCP or ECP.</p><p></p><p>-EDG will be put in local control mode, in case of emergency, remove the jumper and start the EDG manually.<br></p>', NULL, '2024-06-20 16:18:32', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Supv', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EDG-7200', 'ZTK-EDG-7200', 'Emergency Diesel Generator Package', NULL, NULL, 'Emergency Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
