  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace new main wire rope', 'Mechanic', 'CM ', 'Completed', '2024-06-22', '<p>Issue: WP-01 main wire rope is damaged.</p><p>Action: </p><p>On 22-06-2024:</p><p>-Move crane boom to the safe area.</p><p>-Remove dead end wedge socket.</p><p>-Lay down old wire rope on the canvas sheave in figure 8.</p><p>-Found two main wire rope boom tip sheaves are damaged on the shoulder.</p><p>-Replace both sheaves.</p><p>-Reinstate hot spare wire rope.</p><p>-Found one wire from strand (2cm in length) is cut at 4th layer on main winch drum. <span style="background-color: rgb(0, 255, 0);">(Still inside the API standard).</span></p><p>-Reinstall dead end wedge socket.</p><p>-Move the boom at the boom rest.</p><p>-Function test and integrity check for both main and aux wire rope will be performed tomorrow.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP1\\Crane CR-0173\\2024\\2024-06-22 during wire rope replacement">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP1\\Crane CR-0173\\2024\\2024-06-22 during wire rope replacement</a><br></p>', '2024-06-22 18:51:45', '2024-06-29 11:03:18', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
