  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Respool main winch wire rope', 'Mechanic', 'CM ', 'Completed', '2024-06-26', '<p>Work - Respool main winch wire rope</p><p>Found - wire rope has bad spooling.</p><p>Action</p><p>- Assemble snap lock pulley to add more part line on main winch system.</p><p>- Found bad spooling at 3rd inner most layer.</p><p>- Winch down until 2nd inner most layer.</p><p>- Found a bit loosen wire rope reel on the drum.</p><p>- With snap lock method, block down cant go till to the 1st inner most layer.</p><p>- Try to make good tension on the reel as much as possible.</p><p>- Respool the wire rope and disassemble the snap lock pulleys.</p><p>- Perform function test, found normal.</p><p>- Perform crane routine lifting 3 cargos offboard. (2x 4.5 tons and 2 tons) by logistics team.</p><p>- Found bad spooling at outer most 2 layers.</p><p>- Need to respool with the method by striping down all the wire rope on the floor.</p><p><br></p><p>On 26-06-2024:</p><p>-Roll out all wire rope until first layer and lay down on the canvas sheet in figure 8.</p><p>-Respool wire rope.</p><p>-Test with load 2 ton.</p><p>-Condition is satisfied. Need to respool with tension and test with more load.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP1\\Crane CR-0173\\2024\\2024-06-24 Respool main wire rope">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP1\\Crane CR-0173\\2024\\2024-06-24 Respool main wire rope</a><br></p>', '2024-06-24 15:51:30', '2024-06-26 18:59:57', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP01-CR-0173', 'ZTK-WP01-CR-0173', 'Pedestal Crane Package for ZTK WP01', NULL, NULL, 'Pedestal Crane Package for ZTK WP01', 'WP01', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
