  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S GDFR fault alarm time to time', 'Electrical & Instrument', 'CM ', 'Completed', '2024-06-24', '<p>Problem: GDFR fault alarm come time to time.</p><p>Action : Check the existing GDFR parameter absorption and gas gain that is out of range.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Replaced it with new spare type. (short range)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Set the heater setting at 30% for both Transmitter and Receiver.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;Adjust the alignment from both side.<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Function test with CCR and will monitor the alarm.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Now GDFR/T is working properly. (under monitoring condition)</p><p>Note: Reserve 2 spare already.&nbsp;</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History: 19-Jun-2024</span></p><p><span style="background-color: rgb(255, 255, 0);">Problem : GDFR-40021 shows fault alarm time to time.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found&nbsp; &nbsp; : GDFR status shows normal reading.</span></p><p><span style="background-color: rgb(255, 255, 0);">Action&nbsp; &nbsp; : Checked the aliagnment between tramsmitter and receiver. Found good condition.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Cleaned and tightened the terminal.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;Cleaned the len sensor both sides.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed the zero calibration.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp;&nbsp; &nbsp; &nbsp;Performed the alarm function test with CCR.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The GDFR is under monitoring.</span></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-24_GDFR-40021, TS fault alarm come time to time', '2024-06-24 15:53:38', '2024-07-23 17:55:58', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
