  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'A-6500C Fix auto drain valve passing from LP ', 'Mechanic', 'CM ', 'Completed', '2024-06-25', '<p>Problem : Too much air come out from the auto drain valve''s outlet.</p><p>Found&nbsp; &nbsp; : The sealing rubber plug from the floating ball inside the auto drain valve was damaged.</p><p>Action&nbsp; &nbsp; : Removed the auto drain valve and bypass ball valve to the workshop.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked the ball valve condition and found good.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked the auto drain valve inside condition and found sealing rubber plug was broken.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Replace new rubber plug with floating ball.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Re-instated the auto drain valve and reinstalled at the compressor LP side.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Test run the compressor and found air was come out with normal floor.&nbsp;</p>', NULL, '2024-06-25 17:09:02', '2024-09-07 17:29:51', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-6500C', 'ZTK-A-6500C', 'Air Compressor No.3 Packages', NULL, NULL, 'Air Compressor No.3 Packages', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2024-06-25 17:09:02', '2024-09-07 17:29:51', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jacob', NULL, 'EXTERNAL', '2024-06-25 17:09:02', '2024-09-07 17:29:51', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
