  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Sithu', NULL, 'EXTERNAL', '2024-06-26 16:13:40', '2024-07-02 15:53:26', 'PTTEP\\ZPQ.EI-Supv', 'PTTEP\\ZPQ.EI-Supv');
