  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S chilled water pump A tripped', 'Electrical & Instrument', 'CM ', 'Completed', '2024-06-27', '<p><b><u>Problem:</u></b></p><p>- Topside chilled water pump A (P-7810A) was tripped.</p><p><b><u>Found:</u></b></p><p>- MCCB (P4) was tripped and HMI shows tripped alarm for P-7810A.&nbsp;&nbsp;</p><p>- Found cable (R12) burn sign at MCCB (P4) downstream.</p><p><b><u>Action:</u></b></p><p>- Checked the motor insulation resistance and winding resistance.</p><p>- No abnormal found.</p><p>- Cleaned and tightened the cable termination at motor junction box.</p><p>- Cut the burn part of the cable and reinstalled with new cable lag.</p><p>- Performed function and working properly without tripping the MCCB.</p><p>- Chilled water pump P-7810A is on duty and undermoinitoring.</p><p><b><u>Note:</u></b></p><p>- Found overload setting for the chilled water pump A overload relay (0L-9) is set at (32 A) more than MCCB over current trip set point (30 A).</p><p>- Need to check the overload setting parameter.</p><p><br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-27_P-7810A, TS chilled water pump A tripped', '2024-06-27 14:52:01', '2024-07-15 09:55:15', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-7810A-ASSY', 'ZTK-P-7810A-ASSY', 'Chilled Water Pump Duty Unit Assembly', NULL, NULL, 'Chilled Water Pump Duty Unit Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
