  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S navigation aids control panel trip alarm', 'Electrical & Instrument', 'CM ', 'Completed', '2024-06-28', '<p><b><u>Problem:</u></b></p><p>- Navigation Aids control panel trip alarm.</p><p><b><u>Found:</u></b></p><p>- LCB trip alarm at Nav Aids control panel and Navigation DB common alarm at HMI.</p><p><b><u>Action: </u></b></p><p>- Checked at the nav aid control panel and found the LCB trip alarm comes from RL-4 relay.</p><p>- Found there is no power at the relay.</p><p> </p><p>- Found the auxiliary contact is missing at CB 14 spare circuit breaker and all auxiliary contact termination are not installed.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p>- Reinstalled the auxiliary contact termination with spare terminal block for temporary.</p><p>- RL-4 relay becomes back to normal and all alarms are cleared.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);"><b><u>Notes: </u></b></span></p><p><span style="background-color: rgb(255, 255, 0);">- Need to install the original auxiliary contact.</span></p><p><br></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-28_ZTK-NACP-WP11-402, TS navigation aids control panel trip alarm', '2024-06-28 14:25:34', '2024-06-28 21:12:40', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
