-- Inserting report ID 31969
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S chilled water pump A tripped', 'Electrical & Instrument', 'CM ', 'Completed', '2024-06-29', '<p><b><u>Action:</u></b></p><p>- Visual checked the local chilled water pump A (P-7810A) running condition and no abnormal found.</p><p>- Checked the P-7810A running current at (MCC-CPP-7870A) cabinet. (R12 = 28.27A, Y12 = 28.49A, B12 = 27.95A)</p><p>- Visual checked the cable condition at MCC cabinet during pump running. (no burn sign)</p><p>- Checked the MCCB (P4) and cable termination temperature by using thermo scan. (53.7 DegC)</p><p>- Chilled water pump P-7810A is on duty and working properly.<br></p><p><b><u style="background-color: rgb(255, 255, 0);">27 Jun 24 Histroy:</u></b></p><p><u style="background-color: rgb(255, 255, 0);">Problem:</u></p><p><span style="background-color: rgb(255, 255, 0);">- Topside chilled water pump A (P-7810A) was tripped.</span></p><p><u style="background-color: rgb(255, 255, 0);">Found:</u></p><p><span style="background-color: rgb(255, 255, 0);">- MCCB (P4) was tripped and HMI shows tripped alarm for P-7810A.&nbsp;&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">- Found cable (R12) burn sign at MCCB (P4) downstream.</span></p><p><u style="background-color: rgb(255, 255, 0);">Action:</u></p><p><span style="background-color: rgb(255, 255, 0);">- Checked the motor insulation resistance and winding resistance.</span></p><p><span style="background-color: rgb(255, 255, 0);">- No abnormal found.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Cleaned and tightened the cable termination at motor junction box.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Cut the burn part of the cable and reinstalled with new cable lag.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Performed function and working properly without tripping the MCCB.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Chilled water pump P-7810A is on duty and undermoinitoring.</span></p><p><u style="background-color: rgb(255, 255, 0);">Note:</u></p><p><span style="background-color: rgb(255, 255, 0);">- Found overload setting for the chilled water pump A overload relay (0L-9) is set at (32 A) more than MCCB over current trip set point (30 A).</span></p><p><span style="background-color: rgb(255, 255, 0);">- Need to check the overload setting parameter.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-29_P-7810A, TS chilled water pump A tripped\\Thermo Scan\\29 Jun 2024', '2024-06-29 13:26:55', '2024-06-29 15:27:13', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-7810A-ASSY', 'ZTK-P-7810A-ASSY', 'Chilled Water Pump Duty Unit Assembly', NULL, NULL, 'Chilled Water Pump Duty Unit Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zarni', NULL, 'EXTERNAL', '2024-06-29 13:26:55', '2024-06-29 15:27:13', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2024-06-29 13:26:55', '2024-06-29 15:27:13', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

-- Inserting report ID 31970
