  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Condition check monorails for readiness', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-06-29', '<p>Action: Condition check&nbsp;monorails for readiness of fire water pump PM.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;For X-4270, perform visual checked and found remote control cable gland is loosen and fixed it.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Check the limit switch of the hoist up/down and forward/backward.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found the limit switch are stuck and corroded.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Clean and perform manual exercise the limit switch arm.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Check the terminal contact changed or not during the exercise.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found hoist down limit switch is not functioning and need to check and replace.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">Plan: Continue to check the motor condition and limit switch contact functioning of X-7450</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">Note: Most of the special cable gland clamping are corroded.</span></p><p><br></p>', NULL, '2024-06-29 15:58:33', '2024-06-29 18:22:26', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
