  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S MAC address duplication & check LAN cables', 'Automation', 'CM ', 'In Progress', '2024-06-30', '<p>Problem: During scan IP address in electrical control system as per vendor recommendation,</p><p>found MAC address are duplicated for IP address 192.168.26.200 and 192.168.26.90.</p><p>Action: Checked MAC address for IP address 192.168.26.200 and 192.168.26.90.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found that there has one network card and two IP address. (192.168.26.200 and 192.168.26.90)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Consulted the issue with SE vendor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed IP address 192.168.26.90 as per SE vendor recommendation.</p><p>Next Plan: Check LAN cables as per ECS architecture.</p>', NULL, '2024-06-30 15:03:54', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-UELP-ECS', 'ZTK-UELP-ECS', 'Electrical Network Monitor & Control Sys', NULL, NULL, 'Electrical Network Monitor & Control Sys', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
