-- Inserting report ID 31973
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To perform 6M PM_EL WP12 Pedestal Crane', 'Electrical & Instrument', 'PM ', 'Completed', '2024-06-30', '<p>Action: Performed crane 6MPM as per job card.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Check the alternator 1 &amp;2 charging current and voltage.<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Check the resistance fuel shutoff SOV (20 Ohm) and air shut off (1.1 Ohm).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Perform cable tightness and check all the lighting and aviation lighting. (normal)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Check solar charging current &amp; voltage and the crane battery for lighting and aviation lighting.</p><p><br></p><p><b><u>Abnormal finding</u></b></p><p>-During check the battery, <span style="background-color: rgb(255, 255, 0);">internal resistance of bank A is too high (31.1 mohm)</span></p><p>-Battery voltage without load is 26.6 VDC and with load is 14.4 VDC.</p><p>-Individually checked, Bank A is 1.5 VDC and&nbsp; Bank B is 12.5 VDC.</p><p>-Battery A is needed to replace.</p><p>-For other finding, during crane operation, crane <span style="background-color: rgb(255, 255, 0);">cannot be stopped when activate the stop button.</span></p><p>-When check the fuel shut off relay during activate the push button, found relay can energize.&nbsp;</p><p>-Fuel shut off valve has the power. But the FSO is not working.</p><p>-Need to check and verify the FSO valve and wiring in next visit.&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-06-30_CR-1273, Perform 6M PM_EL WP12 Pedestal Crane', '2024-06-30 15:43:38', '2024-07-01 20:34:54', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-1273-EN', 'ZTK-CR-1273-EN', 'Pedestal Crane Diesel Engine WP12', NULL, NULL, 'Pedestal Crane Diesel Engine WP12', 'WP12', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Peter', NULL, 'EXTERNAL', '2024-06-30 15:43:38', '2024-07-01 20:34:54', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
