  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To install the magnetic contactor for the wind tur', 'Electrical & Instrument', 'OTH ', 'In Progress', '2024-07-02', '<p><b><u>Action: </u></b> <br class="Apple-interchange-newline"></p><p>- Performed installation of the magnetic contactor in TEG/Wind turbine switching JB.</p><p>-&nbsp; After installation and normalization of the system, found the TRISTAR battery charging controller was not power up. </p><p>- Controller input voltage from the wind turbine is normal but controller was not working due to no voltage on the charger load side. (Need load side voltage sensing for TRISTAR controller boost up)</p><p>- Also suspect that load side voltage can not sensing by charger controller due to load side voltage is isolated by the diode at the downstream of the wind turbine magnetic contactor (C1).</p><p>- Isolated the installed contactor and put the system back in the previous condition left by the project team.</p><p> </p><p><b><u>Plan: </u></b></p><p>- Will continue to troubleshoot on next visit.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-02_WP-02, Install the magnetic contactor for the wind turbine', '2024-07-02 15:49:01', '2024-07-03 19:03:38', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
