  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S chiller unit A was not functioning normal', 'Electrical & Instrument', 'CM ', 'Completed', '2024-07-03', '<p><b><u>Problem:</u></b></p><p>- Chiller unit A (A-7820A) was not functioning normal.</p><p><b><u>Found:</u></b></p><p>- Chiller A (A-7820A1 and A-7820A2) refrigerant pressure low.</p><p><b><u>Action:</u></b></p><p>- Checked the leak point at condensing coil, refrigerant manifold, receiver valves and service ports during unit stop condition. No leak found.</p><p>- Started the unit A and checked the leak at A-7820A1 and A-7820A2. No leak found.</p><p>- Charged the refrigerant (R134a) to A-7820A and checked leak again.</p><p>- Found refrigerant seeping at A-7820A2 high pressure side service port and no leak for A-7820A1.</p><p>- Stop unit A and tighten A-7820A2 service port.</p><p>- Started unit A and checked leak point.<br></p><p>- No&nbsp; more leak found and&nbsp;</p><p>- Chiller Unit A (A-7820A) is now running properly.</p><p><b><u>Note:</u></b></p><p><span style="background-color: rgb(255, 255, 0);">- Refrigerant usage for A-7820A1 = 5 Kg</span></p><p><span style="background-color: rgb(255, 255, 0);">- Refrigerant usage for A-7820A2 = 1 Kg</span></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-03_A-7820A, TS topside chiller unit A malfunction', '2024-07-03 15:06:41', '2024-07-07 22:25:58', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-7820-SKID', 'ZTK-A-7820-SKID', 'Air Cooled Chiller Skid for Top Side', NULL, NULL, 'Air Cooled Chiller Skid for Top Side', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
