-- Inserting report ID 32002
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Condition check monorails for readiness', 'Electrical & Instrument', 'OTH ', 'In Progress', '2024-07-03', '<p><u><b>Action</b></u></p><p>-For X-4270 (10MT), check the motor winding resistance and insulation of hoist up/down and forward/backward motor.</p><p>For forward/backward motor winding resistance TT1/TT2=14.9 ohm, TT2/TT3=14.9 Ohm, TT1/TT3=14.9&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Winding resistance TT11/T12=4.6 ohm, TT12/TT13=4.6Ohm, TT11/TT13=4.6</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Insulation resistance TT1G&gt;24.4 Mohm, TT2G&gt;24.1 Mohm, TT3G&gt;24.2 Mohm<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Insulation resistance TT11G&gt;31.1 Mohm, TT12G&gt;31.1 Mohm, TT13G&gt;31.1 Mohm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;For hoist up/down motor winding resistance T1T2=97.6 ohm, T2T3=97.6 Ohm, T1T3=97.6 Ohm</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Winding resistance T11T12=47.4 ohm, T12T13=47.4 Ohm, T11T13=47.4 Ohm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Insulation resistance T1G &gt;550 Mohm, T2G&gt;550 Mohm, T3G&gt;550 Mohm<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Insulation resistance T11G&gt;550 Mohm, T12G&gt;550 Mohm, T13G&gt;550 Mohm</p><p><br></p><p><b>For X-7450(5MT</b>), perform visual checked ,tighten the cable, manual exercise and clean the limit switch arm.</p><p>-Check the limit switch of the hoist up/down and forward/backward.(working properly)</p><p>-Check the motor winding resistance and insulation of hoist up/down and forward/backward motor.</p><p>&nbsp; &nbsp;For forward/backward motor winding resistance TT1/TT2=14.9 ohm, TT2/TT3=14.9 Ohm, TT1/TT3=14.9&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Winding resistance TT11/T12=4.6 ohm, TT12/TT13=4.6Ohm, TT11/TT13=4.6</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Insulation resistance TT1G&gt;28.1 Mohm, TT2G&gt;29.1 Mohm, TT3G&gt;28.1 Mohm<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Insulation resistance TT11G&gt;31.1 Mohm, TT12G&gt;31.1 Mohm, TT13G&gt;31.1 Mohm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;For hoist up/down motor winding resistance T1T2=99.4 ohm, T2T3=99.1 Ohm, T1T3=99.3 Ohm</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Winding resistance T11T12=49.5 ohm, T12T13=49.5 Ohm, T11T13=49.5 Ohm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Insulation resistance T1G &gt;225 Mohm, T2G&gt;225 Mohm, T3G&gt;225 Mohm<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Insulation resistance T11G&gt;216 Mohm, T12G&gt;213 Mohm, T13G&gt;210 Mohm</p><p><br></p><p><br></p><p>Note: The job is completed for condition check today. And function test to operate is after removing scaffold.<br></p><p><br></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History:29-Jun-2024</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Condition check&nbsp;monorails for readiness of fire water pump PM.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;For X-4270, perform visual checked and found remote control cable gland is loosen and fixed it.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Check the limit switch of the hoist up/down and forward/backward.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found the limit switch are stuck and corroded.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Clean and perform manual exercise the limit switch arm.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Check the terminal contact changed or not during the exercise.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found hoist down limit switch is not functioning and need to check and replace.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: Continue to check the motor condition and limit switch contact functioning of X-7450</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Note: Most of the special cable gland clamping are corroded.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-03_X-4270, X-7450, check condition of monorails', '2024-07-03 16:01:13', '2024-07-03 19:01:06', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Peter', NULL, 'EXTERNAL', '2024-07-03 16:01:13', '2024-07-03 19:01:06', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2024-07-03 16:01:13', '2024-07-03 19:01:06', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

