  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S solenoid for biocide injection blocked', 'Electrical & Instrument', 'CM ', 'Completed', '2024-07-04', '<p>Action: Checked both&nbsp;SOV-07946 and SOV-07956. Found that both are filter blocked with biocide.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Removed the filters and installed back solenoids together with spacers.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Performed function test and found that SOV-07956 is working normal.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - For SOV-07946, the solenoid coil is defective (OL), so replaced with the new one (190 Ohm).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Now, both are functioning properly.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-04_SOV-07946,SOV-07956, TS solenoid for biocide were blocked', '2024-07-04 15:39:45', '2024-07-04 19:24:39', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
