-- Inserting report ID 32010
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhaul 2nd stage anti surge valve', 'Electrical & Instrument', 'OTH ', 'In Progress', '2024-07-04', '<p><u>Today Action</u></p><p>-Check and compare the spare internal parts of valve body.</p><p>-Install valve bonnet and stem packing.</p><p>-Install actuator, instrument tubing and positioner support.</p><p>Job progress: <span style="background-color: rgb(255, 255, 0);">45% completed.</span></p><p>Plan: Continue to install smart positioner(DVC-6200), volume booster, regulator and solenoid.</p><p><br></p><p><u><br></u></p><p><span style="background-color: rgb(255, 255, 0);">History: 27-Jun-2024</span></p><p><u style="background-color: rgb(255, 255, 0);">Today action</u></p><p><span style="background-color: rgb(255, 255, 0);">-Remove the valve stem packing of the bonnet.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Compare and check the old and new internal spare parts of the valve body.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Replace the internal parts (Ring backup, retaining ring, seal ring, cage, plug/stem and seat ring.</span></p><p><span style="background-color: rgb(255, 255, 0);">Job progress: 36% completed.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: Continue to install valve bonnet and stem packing.</span></p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);">Today action</u></p><p><span style="background-color: rgb(255, 255, 0);">-Deeply clean the inside of valve body and bonnet flange surface.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Use the utility air and clean the inside of valve body at the outside of laydown area.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Check the inside surface of valve body.</span></p><p><span style="background-color: rgb(255, 255, 0);">Job progress: 33% completed.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan : Continue to remove valve stem packing and replace the internal parts of valve.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><span style="background-color: rgb(255, 255, 0);">History: 22-06-2024<u><br></u></span></p><p><u style="background-color: rgb(255, 255, 0);">Today Action</u></p><p><span style="background-color: rgb(255, 255, 0);">-Remove the bonnet from the valve body.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Remove the internal parts of the valve body. (Valve stem, plug, seat ring and packing seals)</span></p><p><span style="background-color: rgb(255, 255, 0);">-Clean all the internal parts of the valve and bonnet flange surface.</span></p><p><span style="background-color: rgb(255, 255, 0);">Job progress: 28% completed.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: Continue to clean and replace the internal parts of the valve tomorrow.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History: 21-06-2024<u><br></u></span></p><p><u style="background-color: rgb(255, 255, 0);">Today Action</u></p><p><span style="background-color: rgb(255, 255, 0);">-Apply paint remover for 20 minutes to the stud bolts and nuts of the valve body.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Clean the paint of the stud bolt and nuts.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Apply liquid wrench to the stud bolt and remove the nuts with hydraulic troque wrench pump.</span></p><p><span style="background-color: rgb(255, 255, 0);">Job progress: 23% completed.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: Tomorrow, continue to remove internal parts of valve assembly.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History: 19-06-2024</span></p><p><u style="background-color: rgb(255, 255, 0);">Today Action</u></p><p><span style="background-color: rgb(255, 255, 0);">-Re-assemble the internal part of the actuator (actuator stem, spring and piston).</span></p><p><span style="background-color: rgb(255, 255, 0);">Job progress-20% completed.</span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: Continue to perform overhaul for valve internal parts.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History:15-06-2024</span></p><p><u style="background-color: rgb(255, 255, 0);">Today Action</u></p><p><span style="background-color: rgb(255, 255, 0);">-Remove the actuator from the valve body.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">-Remove the actuator cylinder and disassemble the internal parts.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Clean the all internal assembly and perform visual check.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Replace yoke O-ring, piston O-ring and actuator stem O-ring.</span></p><p><span style="background-color: rgb(255, 255, 0);">Job progress-10% completed.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: Continue to reinstall back all assembly internal part of the actuator. After that, will install back to valve body.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History: 14-06-2024<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Prepare and check the spare part repair kits of second stage anti surge valve&nbsp;(FV-4X530).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Transfer the anti surge valve from transformer area to the workshop to overhaul.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Remove the instrument tubing, smart positoner, volume booster and positoner indicator.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Job progress&nbsp;5% completed.<br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: Continue to remove the valve and actuator assembly. And will replace repair kit and perform calibration and function test.&nbsp;</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-04_FV-4X530, Overhaul 2nd stage anti surge valve', '2024-07-04 15:43:40', '2024-07-04 16:12:45', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Peter', NULL, 'EXTERNAL', '2024-07-04 15:43:40', '2024-07-04 16:12:45', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-07-04 15:43:40', '2024-07-04 16:12:45', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

