  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'P-7810B TS strange noise', 'Mechanic', 'CM ', 'Completed', '2024-07-06', '<p><b>04-07-2024</b></p><p>Problem&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : Heard strange noise when unit running.<br></p><p>Action&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : Removed pump and motor to workshop. Removed impeller and mechanical seal. Seal was good condition. When turning the shaft heard abnormal sound from bearing.</p><p><br></p><p><b>05-07-2024</b></p><p>Action&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : Overhauled pump and replaced bearing 1 Ea and mechanical seal 1 set.. Mounted pump at onsite and try to turn by hand. Everything was normal. Performed painting for extension frame and motor base frame. Waiting for paint killing time.</p><p><br></p><p><b>06-07-2024</b></p><p>Action&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : Installed extension frame and applied torque 60 Nm. Installed motor and applied torque 60 Nm. Performed test run and will keep monitor 1 day.</p>', '\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ&nbsp; MECH&nbsp; HISTORY PICTURE\\01 ZPQ\\78 TOPSIDE ENCLOSURE HVAC\\7801 Topside Enclosure HVAC System\\P-7810 B\\2024\\2024-04-07 TS strange noise', '2024-07-04 17:16:02', '2024-07-22 17:35:52', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
