-- Inserting report ID 32019
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1M PM EDG on load test', 'Electrical & Instrument', 'PM ', 'In Progress', '2024-07-05', '<p>Action : Performed 1M PM EDG 7200 on load test as per procedure.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and recorded the generator parameter before and after.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Started the EDG in electric mode and running it&nbsp; for 1 hour with load. A standby technician checked at local and no abnormal found. EDG can run properly.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Switched to hydraulic mode and performed test run EDG. While engine run for a few minutes, local technician found that hydraulic starter motor return hose had suddenly disconnected from the fitting.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Stopped the unit and notified to mechanic team to address the disconnected hydraulic hose.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Checked and found that fitting front ferrule was missing.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Reinstalled the new fitting, reconnected the hose and cleaned the area inside.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Performed test run in hydraulic mode and EDG cannot start.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Checked at local and found that cavitation within the fuel line. Released the trapped air inside by pumping and performed test run in hydraulic mode again. EDG can start properly.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<span style="background-color: rgb(0, 255, 0);">Unit is available now.</span></p><p><br></p><p>Tomorrow Plan : To run with electric mode again.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-05_EDG-7200, 1MPM EDG on load test', '2024-07-05 15:06:57', '2024-07-05 18:29:25', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EDG-7200', 'ZTK-EDG-7200', 'Emergency Diesel Generator Package', NULL, NULL, 'Emergency Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-07-05 15:06:57', '2024-07-05 18:29:25', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-07-05 15:06:57', '2024-07-05 18:29:25', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Mechanic Team.', NULL, 'EXTERNAL', '2024-07-05 15:06:57', '2024-07-05 18:29:25', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
