  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Performed 6M PM sand monitoring system backup.', 'Automation', 'PM ', 'In Progress', '2024-07-05', '<p>Action: Performed 6M PM sand monitoring system backup. (50% completed)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked Drive C for sand monitoring system (1A &amp; 1B).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found that free space for Drive C is 4.47 GB.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Need to delete unused wells data.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Before delete the data, copy the backup files to external hardisk drive (Sand monitoring HDD)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Now data copying and backup files are in progress.</p><p>Next Plan: After finished backup files, delete unused wells data.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Backup files for sand monitoring (1C &amp; 1D). (Field Watch server)</p>', NULL, '2024-07-05 15:36:33', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
