  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Cleaned air purifier filter for the Maint Sup room', 'Electrical & Instrument', 'OTH ', 'Completed', '2024-07-06', '<p>Found:&nbsp;Maint Sup room air purifier was showed the filter alarm.&nbsp;&nbsp;</p><p>Action: Take off the both side of filters and bring its to workshop for clean.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Cleaned the filters with vacuum cleanser and instrument air.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; After cleaned, reinstalled the filters and cleaned the sensor of the purifier.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; And then reset the air purifier filter alarm and test run about 15mins.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Purifier was running as normal and not came any alarms.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; So, relocated on the Maint Sup room and continues running.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-06_ Clean the filter for air purifier at the Maint Supdent room', '2024-07-06 13:59:25', '2024-07-06 17:22:44', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
