-- Inserting report ID 32037
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S wind turbine power switching system', 'Electrical & Instrument', 'CM ', 'Completed', '2024-07-06', '<p>-PMO/E requested to troubleshoot magnetic contactor from power switching system is not working.</p><p>-As found wind turbine was stopped by low wind speed 4 m/s, 249'', run by itself around 15m/S, 305''.</p><p>-Verified the magnetic contactor (Schneider LC1 D150) function and found contactor coil could not close the contacts properly. (Sometime partially energize and sometime not energize at all). Removed the contactor for investigating at workshop for further assessment and to clarify with PMO/E team.</p><p>-Installed new magnetic contactor (SIEMENS SIRIUS 3RT1056-6AB36) and function test with successful results.</p><p>-Disconnected (C1-1/+) and (D1-1/+) cable from diode module. Found (C1-1/+) cable lug stud hole diameter is smaller than (D1-1/+) so could not installed at same points.</p><p>-Drilled (C1-1/+) cable lug stud hole with 4mm drill bit to get more diameter. Then connected together both (C1-1/+) and (D1-1/+) as per vendor recommendation.</p><p>-Function test the wind turbine charger controller 1&amp;2 with success. Both controller boost up after energizing the C1 contactor with green LED flashing 1 Sec On, 1Sec Off (Float state).</p><p>-Performed OTP test with automation and CCR.</p><p>-Found discrepancy when testing Remote control condition, </p><p>&nbsp; &nbsp;#CCR and local HMI could not parallel the power supply from WT &amp; TEG (Interlock each other)</p><p>&nbsp; &nbsp;#CCR and local HMI could not power off the load after power on.</p><p>&nbsp; &nbsp;#If WT &amp; TEG selector switch are ON position, when power on one source, activated both WT&amp;TEG.</p><p>-Found local control mode OTP is normal. Running both power source in parallel also normal.</p><p>-Start up all 12 TEGs.</p><p>-As left, All TEGs run and standby, switching control (SS1) is in remote mode, local selector switch (SS2) OFF, local selector switch (SS3) OFF, Power ON wind turbine by remote mode.</p><p>-Will monitor the wind turbine data trend as per PMO/E request.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-06_ WP02, TS wind turbine switching system', '2024-07-07 08:54:08', '2024-07-07 19:28:55', 'PTTEP\\ZPQ.EI-Supv', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP02', 'ZTK-WP02', 'Zawtika Wellhead Platform 02', NULL, NULL, 'Zawtika Wellhead Platform 02', 'WP02', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Sithu', NULL, 'EXTERNAL', '2024-07-07 08:54:08', '2024-07-07 19:28:55', 'PTTEP\\ZPQ.EI-Supv', 'PTTEP\\ZPQ.EI-Supv');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zarni', NULL, 'EXTERNAL', '2024-07-07 08:54:08', '2024-07-07 19:28:55', 'PTTEP\\ZPQ.EI-Supv', 'PTTEP\\ZPQ.EI-Supv');
  INSERT INTO spare (report_id, action, mesc, detail, qty, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Withdraw', '67.94.59.829.9', 'T/S wind turbine power switching system', '1', '2024-07-07 19:28:55', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Supv', NULL);
