-- Inserting report ID 32038
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S sewage unit firing board alarm and macerator', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-07-07', '<p>Today Action : Continued to troubleshoot PCB firing board alarm.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked the bi-polar plate terminal junction box and found that water ingress inside.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Cleaned and applied grease to prevent water ingress.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inspected the condition inside bookcell and observed that bi-polar plates was dirty.&nbsp; &nbsp; &nbsp; </p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Cleaned the bi-polar plates and tightened bolts and nuts with the proper torque (13.5 N-m).&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Performed test run the unit and it tripped by firing board alarm.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked three ways valve XV-73401A and XV-73401B and found that they are functioning normally.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Test run again and checked at the pump side, found that pump cannot run even motor side is in running situation.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Informed mechanic team to check the pump coupling side. Job is in progress.</p><p><span style="background-color: rgb(255, 255, 255);">Plan : After mechanic troubleshooting, will test run again.</span></p><p><span style="background-color: rgb(255, 255, 255);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);">History : 06-July-2024</u></p><p>- Troubleshoot sewage unit macerator pump cannot be started.</p><p>- Isolate the power and process isolation for the sewage unit.</p><p>- Check the alarm and connection of the unit panel.</p><p>- Check and measure the macerator pump motor with continuity and Mega-testing.&nbsp;</p><p>- Record the Mega-testing result, motor condition is good.</p><p>- De-isolate the power and unit running test.</p><p>- Motor can run about 2 minutes and tripped by firing board alarm signal.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-07_X-7300, TS sewage unit firing board alarm and macerator pump cannot be started', '2024-07-07 15:19:25', '2024-07-07 19:44:57', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-7300', 'ZTK-X-7300', 'Sewage Treatment Package', NULL, NULL, 'Sewage Treatment Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-07-07 15:19:25', '2024-07-07 19:44:57', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zarni.', NULL, 'EXTERNAL', '2024-07-07 15:19:25', '2024-07-07 19:44:57', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
