BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS UV Water Sterilize cannot not start ', 'Electrical & Instrument', 'CM ', 'Completed', '2024-07-07', '<p>Problem: Fresh water UV Sterilizer low intensity</p><p>Found : Check the local control panel display. Found alarms that UV low and Failure Lamp..</p><p>Action:&nbsp; - Removed and found water ingress inside UV lamp sleeve, caused the UV lamp malfunction.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked the leak point and fixed it and properly tightened the cap.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -&nbsp; Replaced new UV lamp, Sleeve and properly capsulated the UV lamp socket.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -&nbsp; Reset the lamp hours to zero.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Start up the unit and system run properly.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Intensity value is 44.1 W/m2 and display show System OK.</p><p><br></p><p><br></p><p><br></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-07_X-6820, TS UV sterilizer is tripped', '2024-07-07 15:37:20', '2024-07-15 14:59:02', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-6820', 'ZTK-X-6820', 'Sterilizer Skid', NULL, NULL, 'Sterilizer Skid', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LCP-CPP-6820', 'ZTK-LCP-CPP-6820', 'Local Control Panel for Sterilizer', NULL, NULL, 'Local Control Panel for Sterilizer', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2024-07-07 15:37:20', '2024-07-15 14:59:02', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation');
