-- Inserting report ID 32045
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '4K PM crank soak wash ', 'Mechanic', 'PM ', 'Completed', '2024-07-07', '<p>-Remove all required accessories, tubing and drain ports to perform crank soak wash as per procedure.</p>  <p>-Take sample for chlorine concentration for air inlet cone and plenum before crank soak wash.</p>  <p>-Check the condition of air inlet filters.</p>  <p>-Install external air hose and apply pressure 2 bar for baring 3.</p>  <p>- Perform crank soak wash activity take sample for total iron &nbsp;concentration as per procedure.</p>  <p>- Take sample for chlorine concentration for air inlet cone and plenum after crank soak wash.</p>  <p>-Apply CI for VGV.</p>  <p>-Check the condition of VGV ACTUATOR LOOSE ROD END AND/OR JAM NUT according to service bulletin 8.6/124.</p>  <p>-Install back all accessories and test run.</p>', NULL, '2024-07-07 18:32:30', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Turbi', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
