  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S reading error of dew point analyzer', 'Electrical & Instrument', 'CM ', 'Completed', '2024-07-08', '<p><b><u>Problem:</u></b></p><p>- Reading error of dew point analyzer at the air dryer discharge.</p><p><b><u>Found:</u></b></p><p>- No reading error and alarm cleared.</p><p><b><u>Action:</u></b></p><p>- Checked and tighten the wiring loop for the AT-65212 at local and UCP.</p><p>- Checked the&nbsp;milliampere feedback signal with&nbsp;milliamp clamp meter.</p><p>- The reading for AT-65212 is now stable at (-62.4 DegC).</p><p>- No alarm for AT-65212 and reading is within the range (-55 DegC to -65 DegC)</p><p><b><u>Note:</u></b></p><p>- Alarm setpoint for AT-65212:</p><p>&nbsp; &nbsp; : HH = 20 DegC</p><p>&nbsp; &nbsp; : PH = -29 DegC</p><p>&nbsp; &nbsp; : PL = -100 DegC</p><p>&nbsp; &nbsp; : LL = -100 DegC</p><p>&nbsp; &nbsp; : VL = 120 DegC<br></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-08_AT-65212, TS reading error of dew point analyzer at the air dryer discharge', '2024-07-08 14:44:16', '2024-07-08 17:24:37', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
