  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S WP13 sand monitoring system malfuncation.', 'Automation', 'CM ', 'In Progress', '2024-07-09', '<p>Problem: Sand data from WP13 show fault in Z1D SCADA system.</p><p>Action: Performed remote acess to WP13 sand monitoring server.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked the sand probes data and all data are not updated since 16 June 2024.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Opened Microcor Driver Setup.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed transmitter test to all sand probes.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Showed that "The operation has timed out" message.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed hard reset and tightened all connections.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; And performed transmitter test again.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Showed that "The operation has timed out" message.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Communication is lost between sand monitoring server and sand probes.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Changed RS232 female socket from Port 4 to Port 1 at WP13 Interface Intelligence Unit.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed remote acess to WP13 IIU sand monitoring server.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Opened Microcor Driver Setup.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Changed "Serial Port" from "COM4" to "COM1" for all transmitters. (XT-13x13).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed "Transmitter Test" and "Transmitter Test" shows "The operation has timed out"</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-09_ZTK-WP13-XT, TS sand monitoring system malfunction', '2024-07-09 15:54:07', '2024-07-10 14:59:06', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
