  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ever', NULL, 'EXTERNAL', '2024-07-09 15:54:07', '2024-07-10 14:59:06', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
