  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To replace electronic module at LT', 'Electrical & Instrument', 'CM ', 'Completed', '2024-07-10', '<p>Action : Checked at local and found that LT-06307 showed 112.52 % .</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replaced the defective electronic module of LT-06307 and performed configuration.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Now, the reading at LT-06307 and LT-06306 are the same.</p><p><br></p><p><br></p><p>History: <span style="background-color: rgb(255, 255, 0);">Checked the condition of LT-06306 and found the LT-06306 display and HMI shows error reading.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Swap electronic module from LT-06307 to recover from spike high alarm.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The alarm was cleared after swapped. Fault low alarm comes because the level in the vessel is actual low. Need to replace the electronic module at LT-06307 on next visit.</span></p>', NULL, '2024-07-10 15:46:49', '2024-07-25 10:06:04', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
