  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S LT was fluctuating time to time', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-07-10', '<p><b ><u>Action:</u></b></p><p>- Flushed the chamber of the LT and cleaned the float.&nbsp;</p><p>- But the high noise alarm still present.&nbsp;</p><p>- And the reading does not change even the column was filled with water.&nbsp;</p><p>- Checked the echo curve for the noise preventing tracking of level.</p><p>- Level Noise/ Threshold is 143%.</p><p>- Disconnected and cleaned the transmitter and sensor probe connection.</p><p>- Removed the electronic module and installed at LT-13327 and found working normal with no alarm.</p><p>- Suspect the sensor probe is malfunction.<br><b><u>Plan:</u></b></p><p>- Will continue TS on next visit.</p><p><br></p><p><u ><b style="background-color: rgb(255, 255, 0);">History:</b></u></p><p><span style="background-color: rgb(255, 255, 0);">- Checked the condition at local and found LT reading was fluctuating.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Performed calibration and the reading becomes back to normal for a short time.</span></p><p><span style="background-color: rgb(255, 255, 0);">- After that the alarm still comes.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Performed mA trim but mA access is restricted and can not perform.</span></p><p><span style="background-color: rgb(255, 255, 0);">- The LT chamber need to be flushed but there is no water available. The job is still in progress.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-10_LT-13328, TS LT was fluctuating time to time', '2024-07-10 15:53:50', '2024-07-11 08:41:18', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
