  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Performed ESD test with ESDV from WP12 force open ', 'Electrical & Instrument', 'OTH ', 'Completed', '2024-07-11', '<p>Action: Performed ESD test with ESDV from WP12 incoming force open.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed force open at ESDV-11221 and ESDV-11215.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed ESD test as per procedure. </p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Job has completed.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">Note </span>: ESDV force opened by supplying N2 to the vent of the solenoid. Performed ESD test and found that both ESDV-11221 and ESDV-11215 was remaining opened. During ESD test, ESDVs temporarily closed due to the High pressure regulator failure by N2 leaked from high pressure regulator pressure gauge body.&nbsp;</p><p>Closed the ball valves from smart panel and changed the direction of three ways valves (the inlet of regulator on ESDVs panel) to instrument supply line to be opened the ESDVs. Replaced new high pressure regulator and line up for force open.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - After platform power resumed, DCDB solar and battery charger status showed fault in local HMI while CCR cannot see any status. Checked at local and found that F8 fuse (6A) was burned out which is inside DCDB-WP11-350 charger controller junction box.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - All status on both local HMI and CCR back to normal after replaced with the spare fuse (6A).</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-14_Perform ESD test with ESDV from WP12 force open', '2024-07-11 15:33:08', '2024-07-12 13:48:20', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP11', 'ZTK-WP11', 'Zawtika Wellhead Platform 11', NULL, NULL, 'Zawtika Wellhead Platform 11', 'WP11', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-07-11 15:33:08', '2024-07-12 13:48:20', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Chan', NULL, 'EXTERNAL', '2024-07-11 15:33:08', '2024-07-12 13:48:20', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.Mechanical-Works');
