DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Swap choke valve HCV-13T04 with HCV-13A04 ', 'Mechanic', 'CM ', 'Completed', '2024-07-10', '<p>Problem - Choke valve passing confirmed by production team.</p><p>Action</p><p><u>09-Jul-24</u>&nbsp;</p><p>- Perform process isolation for Well T.</p><p>- Perform electrical &amp; instrument isolation.</p><p>- Erect scaffold for lifting point and installed lifting gear.</p><p>- Loose bolts of choke valve body flanges ( for Well T).</p><p>- Lift the choke valve and pull down to the deck floor.</p><p>- Loose bolts of choke valve body flanges ( for Well A).</p><p>- Lift the choke valve and pull down to the deck floor.</p><p>- Check the internal pipe line of well T and cleaned the flanges both well T &amp; A.</p><p>- Swap the choke valve Well T and Well A.</p><p>- Reinstall choke valve body into the pipe line.</p><p>- tighten stud bolts of choke valve and apply hand torque for both Well A &amp; T</p><p><br></p><p><b><u>10-Jul-24</u></b></p><p>Flange information 6" Class 1500#</p><p>Stud bolts information&nbsp; 1 3/8 stud ,Nut size 2 3/16 (55mm) ,1656 Nm Torque , 4000 PSI Hyd Torque.</p><p>- First step tighten stud bolts for choke valve intel flange and outlet flange 50 % Torque valve.</p><p>- Second step tighten stud bolts for choke valve intel flange and outlet flange 100 % Torque valve. ( according to Torque chart and Hydraulic torque chart).</p><p>- Installed Electrical and instrument equipment.</p><p>- Calibration actuator with control room.</p><p>- Perform process deisolation for Well T.</p><p>- Perform leak test with 60 Bars and found no leak.</p><p>- Housekeeping around the working area.</p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP13\\Choke Valve\\2024-07-09 Swap choke valve A and T">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP13\\Choke Valve\\2024-07-09 Swap choke valve A and T</a><br></p>', '2024-07-12 14:39:53', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HCV-13A04', 'ZTK-HCV-13A04', 'Valve choke on 6''''GC13A01-H70 for Well A', NULL, NULL, 'Valve choke on 6''''GC13A01-H70 for Well A', 'WP13', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
