-- Inserting report ID 32087
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Check condition and function test mobile air comp', 'Mechanic', 'PM ', 'Completed', '2024-07-12', '<p><span style="background-color: rgb(255, 255, 0);"><u style="font-weight: bold;">11-Jul-24&nbsp; </u>&nbsp;&nbsp;</span></p><p>- Performed condition check and test run.</p><p>- Checked fuel line condition and fuel tank level.</p><p>- Checked Coolant level and topped up coolant around 1 liter.</p><p>- Checked Air filter condition ( last changed date 25-Mar-24)</p><p>- Checked Engine lube oil level and Topped up lube oil around 1 liter.</p><p>- Checked Fan belt condition and belt tension.</p><p>- Checked compressor oil level.</p><p>- Checked any loosen.</p><p>- Test Run with no load and load.</p><p>- Found engine stop when air used with valve fully open position.</p><p>- We suspected&nbsp; that air manifold regulator malfunction because insufficient air efficiency.</p><p>- Replaced internal kits of air manifold regulator.</p><p>- After reinstall air manifold regulator, engine can''t start and found some alarm concern with fuel line.</p><p>- Troubleshoot fuel line and bleed the air from fuel system.</p><p>- Found SSAM Module socket connection loosen and secure any loosen connection by E&amp;I Team.</p><p>- Test Run and Used the air by valve fully open position.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);"><b><u>12-Jul-24</u></b></span></p><p>- Performed Yearly PM.</p><p>- Replaced compressor oil filter.</p><p>- Replaced air and fluid separator filter.</p><p>- Replaced compressor oil.</p><p>- Adjust governor for engine speed.</p><p>-&nbsp; Test Run the air compressor and can open the valve to use the air fully open position without engine stop.</p><p><br></p><p>&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\103 GENERAL\\2024\\2024-07-12 Perform condition check and running test and PM activities">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\103 GENERAL\\2024\\2024-07-12 Perform condition check and running test and PM activities</a><br></p>', '2024-07-12 16:39:02', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-AC-WP-001', 'ZTK-AC-WP-001', 'Rig Safe Diesel Air Compressor', NULL, NULL, 'Rig Safe Diesel Air Compressor', 'WP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
