  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Install rain protection at E&I room', 'Mechanic', 'CM ', 'Completed', '2024-07-10', '<p>Background History&nbsp; : Need to install rain protection guard to protect platform shutdown.</p><p>Description : Install rain protection guard at E&amp;I room.</p><p>Action&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Drill hole and make taping for install rain guard.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Install rain guard.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Apply silicone to protect rain ingress.&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP6\\GENERAL\\2024\\2024-07-10 Install rain guard at EI room">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP6\\GENERAL\\2024\\2024-07-10 Install rain guard at EI room</a><br></p>', '2024-07-12 17:10:11', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Crane', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
