-- Inserting report ID 32089
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhaul Pump Assemble', 'Mechanic', 'CM ', 'Completed', '2024-07-13', '<div><b><u>2024-07-12</u></b></div><div><b><u><br></u></b></div><div>Problem : Troubleshoot water seeping at mech seal drain port.</div><div>Found&nbsp; &nbsp; : (1) Mech seal (rotating part) is damaged.</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) In-board bearing is stuck. Not rotate. Found rusty at the inboard spherical roller bearing.</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Found that seal housing lips where process seal (stationary seal) area is damaged.</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (4) Found that process seal (stationary seal) area surface has small scratches.</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (5) Found some green deposition at Labyrinth seal (stator).</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (6) Found some scratches at the seal housing surface area where meets with impeller.</div><div>Action&nbsp; &nbsp; : (1) Dismantle the pump assemble as per user manual.</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Measure the impeller gap (max area is 1.6 mm and min area is 1.1 mm)</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Found the mech seal (rotating part) is damaged and some debris are found inside the&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;mech seal housing.</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (4) Found inboard bearing is stuck and not rotate.</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (5) Clean the every components of the pump assemble and ready to assemble back.</div><div><br></div><div><b><u>2024-07-13</u></b></div><div><br></div><div>- Before install the bearing, checked the shaft alignment with Dia gauge at inboard and outboard bearing area - tolerance is about 0.01~0.02 in.(Good condition).</div><div>- Re-assemble the shaft assembly and mech seal housing as per user manual..</div><div>- Keep as hot spare inside the shaft.</div><div><br></div><div>Item used</div><div>(a) Seal Kit Complete Set, P/N K2535 (1 set)</div><div>(b)&nbsp;SEAL,LABY,GEARBOX,STATOR,P/N.S2506 (1 EA)</div><div>(c)&nbsp;SEAL,LABY,GEARBOX,RTR 17-4 PH,P/N.S2503 (1 EA)</div><div>(d)&nbsp;HOUSING,SEAL,P/N.H2502 (1 EA)</div>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6625\\2024\\2024-07-12 P-6661 Overhaul Pump Assemble">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6625\\2024\\2024-07-12 P-6661 Overhaul Pump Assemble</a><br></p>', '2024-07-13 09:50:39', '2024-07-13 17:52:14', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6661', 'ZTK-P-6661', 'Fresh Water High Pressure Pump', NULL, NULL, 'Fresh Water High Pressure Pump', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Yan', NULL, 'EXTERNAL', '2024-07-13 09:50:39', '2024-07-13 17:52:14', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'John', NULL, 'EXTERNAL', '2024-07-13 09:50:39', '2024-07-13 17:52:14', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
