  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S GDU- train 1 tripped by burner low alarm', 'Electrical & Instrument', 'CM ', 'Completed', '2024-07-13', '<p>Action: Found the pilot of the burner for the GDU train 1 was tripped by BALL-47511.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Replaced the pilot of the E-4750 with the overhauled one.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Cleaned and Adjusted the pilot mixer for both E-4750 and E-4752.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Restarted the unit and monitored the ionization currents of E-4750 and E-4752.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (E-4752 = 15.23 micro Amp, E-4750 = 16.83 micro Amp)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Now the unit is back to normal.</p><p><br></p><p>Note : The old pilot E-4750 was keeping at workshop to perform overhaul.</p>', '<p><a href="U:\\01 E&amp;I\\Activity Photos\\2024-07-13_TS GDU train 1 tripped by burner low-low alarm">U:\\01 E&amp;I\\Activity Photos\\2024-07-13_TS GDU train 1 tripped by burner low-low alarm</a><br></p>', '2024-07-13 15:50:06', '2024-07-23 17:29:56', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
