-- Inserting report ID 32095
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS PDG Frequency Fluctuation', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-07-13', '<p>Problem: The engine speed and frequency of PDG-451 fluctuated.</p><p>Action: Checked the magnetic pickup and found that the lock nut of magnetic pick up is not tighten enough.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Removed the magnetic pick up and found that some scratches on the sensing surface of magnetic pick-up.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; There is no magnetic pick up spare onboard. So, adjust the position and reinstalled the pick up.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Start the engine and, after running about 15 min, the engine stopped itself.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; After that engine cannot be started.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; We will find same spare magnetic pick up from other unit and will confirm that fuel control valve actuator is working properly or not.</p><p><br></p><p><b><u>HISTORY (12-07-2024)</u></b></p><p> </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Performed pre-checked&nbsp; and start the unit.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found that the abnormal engine sound and the frequency is swinging from 49.1 Hz to 52.3Hz.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; And also engine speed is fluctuated even in idle mode.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Adjusted the gain and stability of speed control unit SCU and found that the frequency is nearly stable.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Keep running for 10 min and stop unit.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Start the unit again and found that the frequency is still swinging in wide range.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Adjust from SCU to nearly stable. Keep running for 10 min and stop the engine.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Start again and found that same scenario.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Tried about 5 times and the result is same.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Replaced Speed Control Unit SCU and Engine Control Unit ECU.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Run the unit and frequency is still swinging with narrow range.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Plan to checked magnetic pick-up on tomorrow.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\20204-07-13_PDG-451 TS Frequency Fluctuation">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\20204-07-13_PDG-451 TS Frequency Fluctuation</a><br></p>', '2024-07-13 16:21:44', '2024-07-13 16:25:28', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-DG-WP-451', 'ZTK-DG-WP-451', 'Portable Diesel Generator', NULL, NULL, 'Portable Diesel Generator', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2024-07-13 16:21:44', '2024-07-13 16:25:28', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2024-07-13 16:21:44', '2024-07-13 16:25:28', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine');
END $$;

