  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhauled Biocide Pump D', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-07-14', '<p><u><b>Action:</b></u></p><p>- Perform overhauled the Biocide Pump Delta at workshop.</p><p>- Replace with new seal kits and check the internal parts.</p><p>- Fill up the Hydraulic Oil inside the pump body''s tank.</p><p>- Perform function test and working properly or not.</p><p><b>Note: </b>Modified the plastics pump diaphragm by cutting the identatical in circular shape and design.</p><p><b><u>Job Status: </u></b></p><p>Working in progress.</p><p><br></p><p><u><span style="background-color: rgb(255, 255, 0);">History</span> </u>(13.07.2024)</p><p><u>Problem:</u></p><p>- Biocide pump Delta&nbsp; is not working.</p><p><u>Action:</u></p><p>- Cleaned and overhaul the internal parts.</p><p>Plan</p><p>- Perform function test and working properly or not..</p>', '<p><a href="U:\\01 E&amp;I\\Activity Photos\\2024-07-14_Overhauled Biocide Pump D Phase 1D">U:\\01 E&amp;I\\Activity Photos\\2024-07-14_Overhauled Biocide Pump D Phase 1D</a><br></p>', '2024-07-14 15:59:11', '2024-07-14 15:59:47', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2024-07-14 15:59:11', '2024-07-14 15:59:47', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-07-14 15:59:11', '2024-07-14 15:59:47', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
