BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace Turbocharger Hose and Aux Ball', 'Mechanic', 'CM ', 'Completed', '2024-07-14', '<p>Problem : (1) Turbocharger hose is temporary fix with with general spare parts.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Non-spark material is peeled off at aux ball hook.</p><p>Action&nbsp; &nbsp; : (1) Replace turbocharger hose with OEM spare parts arrived.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Replace some small plain hose at breather and, inlet and out let of after cooler since they are long time usage and damaged.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Replace aux ball with overhaul spare arrived. Perform function test and result is normal operation.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP1\\Crane CR-0173\\2024\\2024-07-14 Replace Turbocharger Hose and Aux Ball">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP1\\Crane CR-0173\\2024\\2024-07-14 Replace Turbocharger Hose and Aux Ball</a><br></p>', '2024-07-14 17:18:34', '2024-07-14 17:19:58', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Crane', false, 'ZTK') RETURNING id INTO new_report_id;
