-- Inserting report ID 32110
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS PDG-452 alternator cant charge Battery', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-07-15', '<p>Action&nbsp; &nbsp; : Checked the alternator wiring and control cable.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Checked the battery voltage and terminal loose or not.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Found that the battery voltage is under 12V and removed and charged at workshop.<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; :&nbsp; Installed back the Multimeter EPM-04C and terminal make sure tighten.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :&nbsp; Found water droplet at the exhaust bank.<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; :&nbsp; Before cranking the engine, checked lube-oil level and&nbsp; fuel level</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :&nbsp; Found the Lube-oil colour and viscosity were ab-normal, we suspect Lube-oil inside the some water and informed to mechanic team.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Installed back the battery after fully charged.<br></p><p><br></p><p>History</p><p>Action&nbsp; &nbsp; : Found water droplet to alternator belt and make engine strange noise.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Waiting for fix leak.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Already verified excitation cable termination.</p><p><br></p><p>Plan to test run and check alternator charging voltage and current.</p><p><u>History&nbsp;</u><br></p><p>Action&nbsp; &nbsp; : Checked PDG-452 alternator output voltage and current.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;Alternator cannot generator output voltage.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Open alternator back cover and check condition. (No burning sign and abnormal findings)<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;Checked alternator wiring and found alternator excitation cable is disconnect.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Excitation cable and wiring are not shown in drawing. (Need to verify)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;Used external 9 V battery as excitation source.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;Checked alternator charging voltage is 12.87 V and current is 40.29V.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Alternator can generate output and charge battery properly.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; Alternator is back to normal.</p><p><br></p><p>Plan : Need to verify excitation cable termination and trace cable loop.</p><p><br></p><p><u>History</u></p><p>Activity: Troubleshoot PDG-452, alternator malfunction and cannot charge battery</p><p>Action&nbsp; : Water come out When we running the engine found the exhaust outlet that why we stopped the&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; engine and Switch off all the breaker.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; :We found water inside the engine oil tank checked together with Mechanic team.</p><p><br></p><p><br></p><p><br></p><p>Activity: Troubleshoot PDG-452, alternator malfunction and cannot charge battery</p><p>Action: - Checked and tightened battery connection before test run for verifying alternator output.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- Performed test run and found generator stop without alarm when releasing start push button &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(can run normal on&nbsp;holding push button)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- Checked relays and found normal.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- Exercised inlet/outlet dampers limit switch and run PDG</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- PDG can be run normally.(Running time 5mins)&nbsp;&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- Verify battery charging current (0.2A)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- Stop the job due to heavy rain.<br></p><p><br></p><p>Plan: - To&nbsp; run PDG for around 30 mins and monitor alternator output and battery voltage.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\20204-07-14_PDG-452 TS alternator malfunction and function test">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\20204-07-14_PDG-452 TS alternator malfunction and function test</a><br></p>', '2024-07-15 15:55:48', '2024-07-15 17:03:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2024-07-15 15:55:48', '2024-07-15 17:03:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2024-07-15 15:55:48', '2024-07-15 17:03:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

-- Inserting report ID 32111
DO $$
