  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot 2" ball valve too hard to operate.', 'Mechanic', 'CM ', 'Completed', '2024-07-15', '<p>Problem&nbsp; &nbsp;: 2 inch ball valve too hard to operate at the biocide injection line of sand accumulator.</p><p>As Found : valve was blocked with sand and biocide at the biocide injection line of sand accumulator.</p><p>Action : (1) Remove old stud bolts and gasket ( as found Gasket type is CNAF material)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(2) Cleaned the line because line was blocked with biocide and sand.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(3) Replaced 2 inch ball valve (Class 300).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(4)&nbsp; Replaced stud bolts ( 5/8 stud bolts 16 EA).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(5) Replaced gaskets ( SPW 2" 300&nbsp; 2 EA).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(6) Tighten stud bolts by torque wrench ( Torque value is 69 Nm)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(7) Perform leak test but no found leak.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\61 PRODUCED WATER\\V 6115\\2024-07-15 Replace 2 inch ball valve of biocide injection line">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\61 PRODUCED WATER\\V 6115\\2024-07-15 Replace 2 inch ball valve of biocide injection line</a><br></p>', '2024-07-15 18:01:56', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-V-6115', 'ZTK-V-6115', 'Sand Accumulator Vessel', NULL, NULL, 'Sand Accumulator Vessel', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Yan', NULL, 'EXTERNAL', '2024-07-15 18:01:56', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Gary', NULL, 'EXTERNAL', '2024-07-15 18:01:56', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
