DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S water ingress into engine oil sump', 'Mechanic', 'CM ', 'Completed', '2024-07-17', '<p>Problem - Found engine oil level high by E&amp;I Team.</p><p>As found - Water ingress into engine oil sump and exhaust system from exhaust pipe.</p><p><u><b>16-07-24</b></u></p><p>Action -&nbsp; Drain out water from engine exhaust system.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; Cleaned exhaust system.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; &nbsp;Drain out water and oil from engine oil sump.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; &nbsp;Flush engine oil around 3 times until engine oil clean color.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; &nbsp;Modify exhaust pipe end with Belzona 1111 to prevent water ingress.</p><p><br></p><p><u>17-07-24</u><br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Replaced Fan Belt.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Replaced engine oil filter.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -&nbsp; Adjust engine speed 1500 RPM. (As found 2000 RPM).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Test run and found engine trip by emergency alarm.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - When alarm cable disconnect and engine can run normally.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Troubleshoot this problem by E&amp;I Team.</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\102 PORTABLE EQUIPMENTS\\Mobile Gen DG-WP-452\\2024\\2024-07-16 TS water ingress oil chamber">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\102 PORTABLE EQUIPMENTS\\Mobile Gen DG-WP-452\\2024\\2024-07-16 TS water ingress oil chamber</a><br></p>', '2024-07-16 18:45:51', '2024-07-22 13:52:53', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-DG-WP-452', 'ZTK-DG-WP-452', 'Portable Diesel Generator', NULL, NULL, 'Portable Diesel Generator', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
