  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'KoKo', NULL, 'EXTERNAL', '2024-07-16 18:45:51', '2024-07-22 13:52:53', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
