  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace fuel hoses for fire water pump', 'Mechanic', 'CM ', 'Completed', '2024-07-17', '<p>Problem : (1) Diesel hoses are crack and deteriorate.</p><p>Action&nbsp; &nbsp; : (1) Replace diesel hoses 5 EA.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(a) 1/4 Hose, FJIC x FJIC, 1.95 m</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(b) 3/8 Hose, 90 FJIC x FJIC, 2.5 m</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(c) 3/8 Hose, FJIC x FJIC, 2.15 m</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(d) 3/8 Hose, FJIC x FJIC, 2 m</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(e) 3/8 Hose, FJIC x FJIC, 40 cm</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Bleed air from the diesel line.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Perform test run and check leakage. Found engine is running normal condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\P-6710 Diesel Fire Water Pump Package No. 2\\2024\\2024-07-17 Replaced Defective Diesel Hoses">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\P-6710 Diesel Fire Water Pump Package No. 2\\2024\\2024-07-17 Replaced Defective Diesel Hoses</a><br></p>', '2024-07-17 17:09:26', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6710-PCKG', 'ZTK-P-6710-PCKG', 'Fire Water Pump No.2', NULL, NULL, 'Fire Water Pump No.2', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
