-- Inserting report ID 32138
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S SDV-62211A shows closed status at CCR', 'Electrical & Instrument', 'CM ', 'Completed', '2024-07-18', '<p><b><u>Problem:</u></b></p><p>Troubleshoot Fuel gas filter separator liquid outlet SDV-62211A shows closed status at CCR.</p><p><b><u>Action:</u></b></p><p>- Visual check and inspection for SDV-62211 A at fuel gas filter separator liquid outlet area.</p><p>- Confirm the signal open and close status of the SDV-62211 A with CCR.</p><p>- SDV shows only closed status at CCR although the open condition in local valve positioner.</p><p>- Check and inspect the enclosure of the valve feedback condition.</p><p>- One of the magnet was removed by itself from the cam shaft and touch with the valve body. (Old design)</p><p>- Replace with the new magnetic cam shaft. (New design)</p><p>- Check and tighten the termination.</p><p>- Function test with CCR for both open and close status.</p><p>- Close the enclosure and function test again, SDV shows normal status for open &amp; close with CCR.</p><p><b><u>Job Status:</u></b></p><p>This job is completed.</p><p><br></p>', '<p><a href="U:\\01 E&amp;I\\Activity Photos\\2024-07-18_Troubleshoot SDV-62211 A shows signal error at CCR">U:\\01 E&amp;I\\Activity Photos\\2024-07-18_Troubleshoot SDV-62211 A shows signal error at CCR</a><br></p>', '2024-07-18 15:22:33', '2024-07-18 16:04:03', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SDV-62211A', 'ZTK-SDV-62211A', 'SDV on V-6220A Condt Outlet,ESD 3NC,3LJ', NULL, NULL, 'SDV on V-6220A Condt Outlet,ESD 3NC,3LJ', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-07-18 15:22:33', '2024-07-18 16:04:03', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Joseph', NULL, 'EXTERNAL', '2024-07-18 15:22:33', '2024-07-18 16:04:03', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
