-- Inserting report ID 32139
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Rectify & replace automatic fire shutter mechanism', 'Electrical & Instrument', 'CM ', 'Completed', '2024-07-18', '<p>Problem : Rectify 3 automatic fire shutters in galley and replaced the new mechanisms.</p><p>Action&nbsp; &nbsp; : Continued the remaining two fire shutters H-87100C (Food Tray Counter) and H-87100D (Near Dish Washer)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Checked the electromagnetic cable release mechanism for both shutters.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Installed the new counter weights on both and installed new load release mechanisms along with the solenoid for H-87100C.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Lubricated the fire shutters and performed function test by de-energizing the solenoids.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Mechanism released and fire shutters closed automatically.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Corrected the mismatched cable tags and terminations in the local junction box. (Put the warning sign to keep open fire shutter all the time)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<span style="background-color: rgb(0, 255, 0);">Job has completed.</span></p><p><span style="background-color: rgb(0, 255, 0);">Note : Hot spare and some accessories of fire shutters are keeping at LQM Level 3.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History : 17 Jul 2024</span></p><p>Action&nbsp; &nbsp; : Checked the conditions of roller doors, found that mis-matched cable tags and terminations in the local junction box.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;H-87100D (Roller shutter near dish washer)&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;H-87100C (Roller shutter of food tray counter)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;H-87100B (Roller shutter of camp boss office)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;H-87100A (Sliding door at the back side of galley)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked the electromagnetic cable release mechanism for instant release of loads. Found that the release mechanism was not attached to the fire shutter. (The type is&nbsp;EH GMHX 050 - energized to hold). Additionally, counter weight was missing.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Installed the new counter weight and load release magnetism along with the solenoid.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Lubricated the fire shutter and performed function test by de-energizing the solenoid.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- As a result, the mechanism was released and the fire shutter automatically closed.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Completed work on the fire shutter at the camp boss office (H-87110B) today. (Put the warning sign to keep open fire shutter all the time)</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-18_Rectify &amp; replace automatic fire shutter mechanism', '2024-07-18 15:43:15', '2024-07-18 17:31:45', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-H-87100A', 'ZTK-H-87100A', 'Magnetic Door Galley LQM LVL 1', NULL, NULL, 'Magnetic Door Galley LQM LVL 1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
