  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify drain clogged alarm for LD-01 B', 'Electrical & Instrument', 'OTH ', 'Completed', '2024-07-18', '<p><b><u>Problem:</u></b></p><p>- LD-01 B washing machine shows the alarm drain clogged.</p><p><b><u>Action:&nbsp;</u></b></p><p>- Visual check the alarm signal from the washing machine.</p><p>- Check the container and internal function condition.</p><p>- Clear the alarm and reset the system and function test 3 times.</p><p>- Check the drain line piping and drain outlet frame.</p><p>- Water and sand blocked the drain pipe and surge the drain line.</p><p>- Repair the surge the drain line by junk with wood blocks.</p><p>- Perform the function test and keep monitoring by nightshift Laundary man.</p><p><b><u>Job Status:</u></b></p><p>Completed. (No more alarm comes out).</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-18_Verify the drain clogged alarm from LD01-B">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-18_Verify the drain clogged alarm from LD01-B</a><br></p>', '2024-07-18 17:20:17', '2024-07-23 17:37:37', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
