  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Yan', NULL, 'EXTERNAL', '2024-07-18 18:05:23', '2024-07-20 14:13:23', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
