-- Inserting report ID 32979
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Trouble lamp for fan coil unit at PMA', 'Electrical & Instrument', 'CM ', 'Completed', '2024-07-20', '<p>)Problem: The compartment lamp installed inside fan coil unit (B-7880B) is not working.</p><p>Found : Lamp is not working.</p><p>Action: Stopped the fan coil unit B.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked the lamp inside fan coil unit.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found that one of the terminal of ballast ( which is included transformer and ignitor) is loosen.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Tighten the terminal and lamp is back to normal.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Restarted the fan coil unit (B-7880B) which is resumed the normal operation.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Need to order ballast.(500552347)</p><p><br></p><p>Note: B-7880A_ Stop the unit due to strange noise.</p><p><br></p><p><br></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-20_B-7880B, Fix the lamp that is installed inside the fan coil unit', '2024-07-20 13:21:30', '2024-07-20 14:44:12', 'PTTEP\\ZPQ.Mechanical-TeamL', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-B-7880B', 'ZTK-B-7880B', 'Fan Coil Unit No.2', NULL, NULL, 'Fan Coil Unit No.2', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-07-20 13:21:30', '2024-07-20 14:44:12', 'PTTEP\\ZPQ.Mechanical-TeamL', 'PTTEP\\ZPQ.EI-TeamLead');
