  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify air leak and adjust air flow LQM SWGR', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-07-21', '<p><b>Action</b>:&nbsp; &nbsp; Performed verification of air leak and adjusting air flow at LQM SWGR and camp boss office.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Felt that the air flow in LQM SWGR room and LWM ESWGR is low and temperature is hotter.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Felt that the temperature in ESWGR is more than SWGR room.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Found that the HVD-86116 for ESWGR is 10% opened and HVD-86113 for SWGR is 10% opened.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Adjusted the HVD-86116 for ESWGR to 30% opened and HVD-86113 for SWGR to 25% opened.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Then, found that the HVD-86131 for camp boss room is 100% opened.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Adjusted the HVD86131 for camp boss room to 50% opened only.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; The temperature and air flow will keep monitoring.<br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-21_LQM Level 1, air flow, verify air leak and adjust air flow at LQM SWGR and camp boss">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-21_LQM Level 1, air flow, verify air leak and adjust air flow at LQM SWGR and camp boss</a><br></p>', '2024-07-21 17:56:14', '2024-07-21 18:05:12', 'PTTEP\\ZPQ.Mechanical-TeamL', 'PTTEP\\