  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S 16" Butterfly valve hard to operate', 'Mechanic', 'CM ', 'In Progress', '2024-07-22', '<p><b>22-07-2024</b></p><p>Problem : (1) 16" Butterfly valve hard to operate</p><p>Tag No.&nbsp; : (1) 16"-FW-67019-A10 ring main line</p><p>Found&nbsp; &nbsp; : (1) Small amount of Rusty inside the gear box housing.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Long time no operate since it is live line.</p><p>Action&nbsp; &nbsp; : (1) Open the gear box cover and check inside.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Exercise the valve several time. Only a small amount of travel is obtained.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Clean the gear box and apply grease EP3 to the worm gear.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (4) Still the valve is hard to operate. Waiting for further instruction.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\Fire Ring Main\\2024\\2024-07-22 TS 16in butterfly valve hard to operate at 16-FW-67019-A19 ring main line">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\Fire Ring Main\\2024\\2024-07-22 TS 16in butterfly valve hard to operate at 16-FW-67019-A19 ring main line</a><br></p>', '2024-07-22 13:51:07', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
