  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Mercelo', NULL, 'EXTERNAL', '2024-07-22 13:51:07', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
