  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Tumble dryer has high vibration', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-07-23', '<p>Problem: LD-02B Tumble dryer has high vibration (noise).</p><p>Action: Manually turned&nbsp; the drum of LD-02B slowly and it generated strange noise.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Opened up the cover and observed the motor pulley &amp; drive belt.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Found cracking points on the motor pulley mounting support.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Disassembled the mounting and checked the pulley condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Found the one side of bearing was severely damaged.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Need to order spare : Ball Bearings 2 Ea &amp; Shaft</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Need to fix pulley mounting cracking areas.</p><p>Bearing P/N : <b>SKF ITALY 04&nbsp; 09 124J&nbsp; 6001-2RSH&nbsp;&nbsp;</b></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-23_LD-02B, TS laundry dryer abnormal noise', '2024-07-23 15:10:32', '2024-07-27 13:36:08', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
