  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Joseph', NULL, 'EXTERNAL', '2024-07-23 15:10:32', '2024-07-27 13:36:08', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
