-- Inserting report ID 33011
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot BA air compressor can''t run', 'Mechanic', 'CM ', 'Completed', '2024-07-23', '<p>Problem: BA (Breathing Apparatus) air compressor can''t run.</p><p>Found: BA air compressor is stopped due to low oil pressure.(shutdown at 36 PSI)</p><p>Action: (1) Checked the oil pressure switch, oil filter, oil level and motor rotation.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Oil filter is clean. Oil level is max level at indicator.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Motor rotation is counter clock wise facing to flywheel.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (4) Inspected the check valve (minimum pressure valve) located in the line between the oil pump and compressor.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (5) Cleaned the check valve and installed it.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (6) Restart the BA air compressor. Oil pressure is stable at 70 PSI.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (7) BA air compressor is now operation normally and unit is under monitoring the unit.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\77 SAFETY LIVE SAVING &amp; PORTABLE FIRE FIGHTING EQUIPMENT\\General\\2024\\2024-07-23 TS SCBA Trip &amp; Shutdown Malfunction">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\77 SAFETY LIVE SAVING &amp; PORTABLE FIRE FIGHTING EQUIPMENT\\General\\2024\\2024-07-23 TS SCBA Trip &amp; Shutdown Malfunction</a><br></p>', '2024-07-23 18:02:21', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SLFE-SCBA', 'ZTK-SLFE-SCBA', 'Self-Contained Breathing Apparatus', NULL, NULL, 'Self-Contained Breathing Apparatus', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Yan', NULL, 'EXTERNAL', '2024-07-23 18:02:21', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ko Ko', NULL, 'EXTERNAL', '2024-07-23 18:02:21', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
