  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform to TS Check valve malfunction', 'Mechanic', 'CM ', 'Completed', '2024-07-24', '<p>Problem : during pressure switch testing found switch is not working</p><p>Action&nbsp; &nbsp; &nbsp;: during drain the line to reduce pressure (found water is passing by 14" butterfly valve)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -remove the 1" flange and install blind not to have water pressure</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -remove the check valve of check any damage or condition(spring and face)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-install back the check valve and remove blind flange install drain plug</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Production want to confirm to make sure pressure switch function</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -we need to open the 2 globe valve fully near at pressure switch to activate switch and run firewater pump</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -house keeping and clean sea water worksite</p>', NULL, '2024-07-24 18:01:12', '2024-08-19 08:56:07', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6720-PCKG', 'ZTK-P-6720-PCKG', 'Fire Water Pump No.3', NULL, NULL, 'Fire Water Pump No.3', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Henry', NULL, 'EXTERNAL', '2024-07-24 18:01:12', '2024-08-19 08:56:07', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
