  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-E-4852-ASSY', 'ZTK-E-4852-ASSY', 'Fire Tube Heater Assembly', NULL, NULL, 'Fire Tube Heater Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-07-26 08:47:17', '2024-07-29 14:22:37', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Joseph', NULL, 'EXTERNAL', '2024-07-26 08:47:17', '2024-07-29 14:22:37', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
