-- Inserting report ID 33031
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To rectify malfunction dampers at Hot workshop', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-07-26', '<p>Problem: The closed status of the dampers (HFD-78121 &amp; HPD-78107) were not show at UCP HMI.</p><p>Action: Checked the physical condition at the local.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Opened the junction box and checked the cable terminations.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Checked the positioner limit switches and adjusted the magnet position.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Performed function test and both dampers can open and close smoothly.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Checked at the UPC HMI, both open and close status show and also match with local position.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-26_ HFD-98121 HPD-78107 TS fire damper malfunction at Hot workshop">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-26_ HFD-98121 HPD-78107 TS fire damper malfunction at Hot workshop</a><br></p>', '2024-07-26 14:58:08', '2024-07-26 15:44:23', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HFD-78121', 'ZTK-HFD-78121', 'Fire Damper on Hot Workshop', NULL, NULL, 'Fire Damper on Hot Workshop', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2024-07-26 14:58:08', '2024-07-26 15:44:23', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Turbine');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-07-26 14:58:08', '2024-07-26 15:44:23', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Turbine');
