-- Inserting report ID 33032
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Tumble dryer has high vibration', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-07-26', '<p>Problem: LD-02B tumble dryer has high vibration (noise).<br></p><p>Found:&nbsp; Found the one side of pulley bearing was severely damaged.</p><p>Action: Replaced new bearings 2 Ea for Pulley.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Reinstalled and adjusted the belt tensions as per Maintenance Manual. (Adjusted Belt tension C: 72.2 Hz , B: 76.2 Hz) with a frequency meter.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Function test run and no more strange noise.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : But the equipment was stop by "No Vacuum" Error code.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Checked and verified the Vacuum switch, the switch is working properly.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Checked the vacuum switch hose condition and it looked abnormal.</p><p>&nbsp;<span style="background-color: rgb(255, 255, 0);">Next plan</span> : <span style="background-color: rgb(255, 255, 0);">To verify the vacuum switch hose line. (in progress)</span></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p>History:</p><p>Problem: LD-02B cloth dryer has high vibration (noise).</p><p>Action: Manually turned&nbsp; the drum of LD-02B slowly and it generated strange noise.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Opened up the cover and observed the motor pulley &amp; drive belt.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Found cracking points on the motor pulley mounting support.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Disassembled the mounting and checked the pulley condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Found the one side of pulley&nbsp; bearing was severely damaged.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Need to order spare : Ball Bearings 2 Ea &amp; Shaft</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Need to fix pulley mounting cracking areas.</p><p>Bearing P/N :&nbsp;SKF ITALY 04&nbsp; 09 124J&nbsp; 6001-2RSH&nbsp;&nbsp;</p>', NULL, '2024-07-26 15:00:12', '2024-07-27 13:36:28', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LQM-LAUNDRY', 'ZTK-LQM-LAUNDRY', 'Laundry Room', NULL, NULL, 'Laundry Room', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Joseph', NULL, 'EXTERNAL', '2024-07-26 15:00:12', '2024-07-27 13:36:28', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2024-07-26 15:00:12', '2024-07-27 13:36:28', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
