-- Inserting report ID 33037
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Tumble dryer has high vibration', 'Electrical & Instrument', 'CM ', 'Completed', '2024-07-27', '<p><b><u>Problem</u></b>:&nbsp; After replaced the new bearings, the equipment can manual turn properly with no more vibration noise. While function test run,&nbsp; it was tripped by <span style="background-color: rgb(255, 255, 0);">"No Vacuum"</span> Error code.<br></p><p>Found:&nbsp; Found the vacuum switch hose condition was not good.</p><p>Action : Replaced and arranged new Vacuum switch hose.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Function test run with Load by Laundry man&nbsp; and it can run properly. (No more trip and vibration noise).</p><p><u>Spare part: Hose P/N: 877 5251-02</u></p><p><b><u><br></u></b></p><p><b><u>History:</u></b><br></p><p>Action: Replaced new bearings 2 Ea for Pulley.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Reinstalled and adjusted the belt tensions as per Maintenance Manual. (Adjusted Belt tension C: 72.2 Hz , B: 76.2 Hz) with a frequency meter.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Function test run and no more strange noise.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : But the equipment was stop by "No Vacuum" Error code.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Checked and verified the Vacuum switch, the switch is working properly.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Checked the vacuum switch hose condition and it looked abnormal.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Manually turned&nbsp; the drum of LD-02B slowly and it generated strange noise.<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Opened up the cover and observed the motor pulley &amp; drive belt.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Found cracking points on the motor pulley mounting support.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Disassembled the mounting and checked the pulley condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Found the one side of pulley&nbsp; bearing was severely damaged.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Need to order spare : Ball Bearings 2 Ea &amp; Shaft</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Need to fix pulley mounting cracking areas.</p><p>Bearing P/N :&nbsp;SKF ITALY 04&nbsp; 09 124J&nbsp; 6001-2RSH&nbsp;&nbsp;</p>', NULL, '2024-07-27 13:25:56', '2024-07-29 17:23:35', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LQM-LAUNDRY', 'ZTK-LQM-LAUNDRY', 'Laundry Room', NULL, NULL, 'Laundry Room', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
