  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace fan bearings and shaft', 'Mechanic', 'CM ', 'Completed', '2024-07-26', '<p>Work - To replace fan bearings and shaft.</p><p>Found</p><p>- Bearings are defective.</p><p>- Shaft is still in good condition.</p><p>Action</p><p>- Measure as found alignment and found ok.</p><p>- Assemble lifting aid.</p><p>- Remove fan blade.</p><p>- Remove fan sprocket.</p><p>- Remove bearings and shaft.</p><p>- Install upper bearing and shaft.</p><p>- Install lower bearing.</p><p>- Measure bearing and shaft in a vertical position.</p><p>- Install fan sprocket and adjust alignment between pulleys.</p><p>- Install fan blade and measure clearance of blade tip.</p><p>- Install belt and adjust tension (31hz)</p><p>- Perform test run and found normal running condition.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\42 GAS COMPRESSOR T 1\\GAS COOLER\\E-4230 (1st Stage)\\E-4230D\\2024\\2024-July-26 Replace fan bearings and shaft">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\42 GAS COMPRESSOR T 1\\GAS COOLER\\E-4230 (1st Stage)\\E-4230D\\2024\\2024-July-26 Replace fan bearings and shaft</a><br></p>', '2024-07-27 15:00:40', '2024-07-27 15:58:07', 'PTTEP\\ZPQ.Mechanical-Turbi', 'PTTEP\\ZPQ.Mechanical-Crane', false, 'ZTK') RETURNING id INTO new_report_id;
