-- Inserting report ID 33048
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S level transmitter error condensate coalescer', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-07-28', '<p><u>Problem:</u> Level transmitter LT-50603 reading error.</p><p><u>Found </u>: - As per manual, loop current output over 20.5mA&nbsp; can be float defective, wrong magnet type selected, wrong mounting direction selected and transmitter electronics defective).</p><p>- Float condition is good, magnet type and mounting direction is correct.</p><p>- Suspect the transmitter electronic defective as per manual.</p><p><br></p><p><u>Action:</u>&nbsp;Prepared new spare&nbsp; Level transmitter.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Saved the existing configuration from the transmitter with HART.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Installed new level transmitter, it gets the power 24VDC but the display does not show and could not connect with HART.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: To check that new transmitter at Simulation station <span style="background-color: rgb(255, 255, 0);">(in progress)</span></p><p><br></p><p><u>History:</u></p><p><u>Problem:</u></p><p>- Level transmitter ILT 50603 show reading error.</p><p><u>Found:</u></p><p>- Transmitter initilization and no float alarm show at transmitter display.</p><p>- PV loop current is 21.005 mA.</p><p><u>Action:</u></p><p>- Flushed the level transmitter column and function test.</p><p>- Filled the water level to 50% and found that transmitter still show initilization and no float alarm.</p><p>- Removed and cleaned the float with water.</p><p>- Performed function test and found transmitter still show alarms.</p><p>- As per manual, loop current output over 20.5mA&nbsp; can be float defective, wrong magnet type selected, wrong mounting direction selected and transmitter electronics defective).</p><p>- Float condition is good, magnet type and mounting direction is correct.</p><p>- Suspect the transmitter electronic defective and need to replace.</p><p><u>Plan:</u></p><p>- Will replace with new transmitter.</p><p><u>Note:</u></p><p>- No on hand spare for this type of transmitter and need to order.&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-28_Replace new level transmitter LIT-50603 at Main deck">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-28_Replace new level transmitter LIT-50603 at Main deck</a><br></p>', '2024-07-28 11:16:48', '2024-07-28 18:22:42', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-ILT-50603', 'ZTK-ILT-50603', 'LT on F-5060, Alarm High', NULL, NULL, 'LT on F-5060, Alarm High', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
