  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2024-07-28 11:16:48', '2024-07-28 18:22:42', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
