  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Performed 1YPM Moisture analyzer', 'Electrical & Instrument', 'PM ', 'Completed', '2024-07-28', '<p>Action: </p><p>- Checked the H20 reading: 2.103 lbs/MMscf.</p><p>- Checked for leaks at the filter inlet and membrane separato.(No leak)</p><p>- Performed calibration</p><p>&nbsp; New RATA Multiplier value is 0.84641</p><p>&nbsp; New RATA Offset is 0.</p><p>- Performed validation by apply high/Low moisture concentration gas to analyzer.&nbsp;</p><p>- Normalize the system, H2O reading is 2.28 lbs/MMscf.</p><p><br></p><p><u style="background-color: rgb(255, 255, 0);">History on 27-07-24</u><br></p><p>Perform 1 YPM Moisture Analyzer AT-46002</p><p>Actions:</p><p>- Recorded PCS value at HMI = 2.4955 lb. / MMSCF</p><p>- Inspected external conditions, including mounting, fittings, and connections.</p><p>- Checked heater regulator at pressure reducing station (PRS).</p><p>- Record the H2O reading value 2.43 lb./ MMSCF on the local display</p><p>- Record the system parameter, Enter "RATA" setting parameter</p><p>- As Found- Repeatability analysis Vs Average , Reproducibility analysis&nbsp;(Fail)<br></p><p>- Found that standard gas regular is reading freeze, flashing the line and set the pressure 20 PSI.</p><p>- Recheck the Repeatability analysis Vs Average , Reproducibility analysis&nbsp;(Pass)</p><p>- Replaced the filter Cartridge 7 micron and gasket in Sample Condition System junction box.</p><p>- Replaced membrane separator in Sample Condition System junction box.</p><p><br></p><p>Plan to continue calibration tomorrow.</p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-28_AT-46002_Performed 1YPM Moisture analyzer', '2024-07-28 14:44:55', '2025-09-09 22:00:21', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
