-- Inserting report ID 33054
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S level transmitter error condensate coalescer', 'Electrical & Instrument', 'CM ', 'Completed', '2024-07-29', '<p><u>Problem:</u>&nbsp;Level transmitter LT-50603 reading error.<u><br></u></p><p><u>Action:&nbsp;</u>&nbsp; Checked that new transmitter at Simulation station and it can power up but&nbsp; it could not be connected with HART and also the display does not show.</p><p>- Checked one hot spare Level transmitter (with sensing rod), power up and can be communicated with HART.</p><p>- But the display card was malfunction, and then replaced new display card.</p><p>- Re-config. that hot spare transmitter to be same with the defective one.</p><p>- Re-installed at site and&nbsp; performed zero and span calibration.</p><p>- Performed function test with water 0% to 100% reading at Local Gauge, Transmitter and DCS reading. (OK).</p><p>- Normalized all lines and now the level transmitter reading is Normal.</p><p><br></p><p><u>History:</u></p><p><u>Found&nbsp;</u>: - As per manual, loop current output over 20.5mA&nbsp; can be float defective, wrong magnet type selected, wrong mounting direction selected and transmitter electronics defective).</p><p>- Float condition is good, magnet type and mounting direction is correct.</p><p>- Suspect the transmitter electronic defective as per manual.</p><p><br></p><p><u>Action:</u>&nbsp;Prepared new spare&nbsp; Level transmitter.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Saved the existing configuration from the transmitter with HART.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Installed new level transmitter, it gets the power 24VDC but the display does not show and could not connect with HART.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\29-07-2024_TS level transmitter error condensate coalescer', '2024-07-29 15:20:39', '2024-07-29 18:26:14', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-ILT-50603', 'ZTK-ILT-50603', 'LT on F-5060, Alarm High', NULL, NULL, 'LT on F-5060, Alarm High', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2024-07-29 15:20:39', '2024-07-29 18:26:14', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2024-07-29 15:20:39', '2024-07-29 18:26:14', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop');
