-- Inserting report ID 33055
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS GDU train 1 tripped by E-4750 instantaneously', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-07-29', '<p>Troubleshoot GDU train-1 was tripped by E-4750 instantaneously</p><p><b><u>Action:</u></b></p><p>- Prepare tools and equipment to replace the pilot tube E-4750 at GDU train-1</p><p>- Isolate the power for E-4750 at local Ex junction box</p><p>- Replace with new pilot tube E-4750 and running test</p><p><b><u>As Found:&nbsp;</u></b></p><p>During 1st time running, GDU train-1 was tripped by E-4752 low ionization current</p><p>- Perform the junk start with both of the pilot tube E-4750/4752.</p><p>- Monitor the ionization currents of E-4750 &amp; E-4752.</p><p>(E-4750= 2.36 micro Amp, E-4752= 2.23 micro Amp)</p><p>- Adjust and clean the air flow adjuster for both pilot tubes</p><p>(E-4750= 16.44 micro Amp, E-4752= 14.71 micro Amp)</p><p><b>Remark: </b>If we removed the air flow cleaner, the ionization current values are low again.</p><p>- Start the main burner for GDU train-1 and monitor the ionization current values</p><p>- The ionization current values are unstable and fluctuated around (4 to 12 micro Amp)</p><p>- Inform to E&amp;I team leader and E&amp;I supervisor for the condition</p><p>- GDU is keep running and monitoring to transfer the stable temperature and normal load condition by CCR</p><p><b><u>Job Status:&nbsp;</u></b> &nbsp;</p><p>Under Monitoring with CCR&nbsp;</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-29_TS GDU train1 tripped by E-4750">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-29_TS GDU train1 tripped by E-4750</a><br></p>', '2024-07-29 15:26:55', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-E-4740-SKID', 'ZTK-E-4740-SKID', 'Glycol Reboiler Skid', NULL, NULL, 'Glycol Reboiler Skid', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-E-4750-ASSY', 'ZTK-E-4750-ASSY', 'Fire Tube Heater Assembly', NULL, NULL, 'Fire Tube Heater Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
