-- Inserting report ID 33073
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Check the configuration of VFD of air compressor', 'Electrical & Instrument', 'OTH ', 'Completed', '2024-07-31', '<p>Action: Download the project configuration file from A-6500B VFD.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Export the project file to .cfg file via SoMove.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Copy to digital display and installed it to new VFD unit.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Power up the display unit and sent the config file to drive but cannot run with new config file.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Schneider said that&nbsp;SoMove does not have the capability to&nbsp;compare or convert configurations between ATV61/71 and ATV600 series Process drives.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Config manually and the following function is not in new VFD.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; MFR&nbsp; &nbsp; -&nbsp; &nbsp; Multiplying Coeffocient</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; RSM&nbsp; &nbsp; -&nbsp; &nbsp; Measured stator Resistance</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; NSI&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp;&nbsp; &nbsp;Nominal Motor Slip</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; PNN&nbsp; &nbsp; -&nbsp; &nbsp; Poles Pair Number</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; R2&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;-&nbsp; &nbsp; Relay Output 2 Assignment<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Connected 24VDC power supply for control unit to perform function check.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Installed one push button for start command at DI1.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; When press the start button, unit started and tripped by "Output Phase Loss".</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Disable the Output Phase Loss function, because the output device is not connected.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Restart and the unit can start properly.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Stopped the unit and change "Output Phase Loss" back to enable.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Unit can operate with 100% (50 HZ) properly, for the 50% need to check the control wiring.<br></p><p><br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-31_Performance Check of spare VFD of air Compressor">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-31_Performance Check of spare VFD of air Compressor</a><br></p>', '2024-07-31 16:09:15', '2024-08-01 08:28:06', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
