  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S engine yellow alarm of BDG', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-07-31', '<p>Problem: BDG Yellow Engine alarm appear from UCP panel&nbsp;</p><p><br></p><p>Found&nbsp; &nbsp;: Engine yellow alarm come from ECU (Engine control Unit).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Activated <b>fault codes 410 (injector voltage too low, level 1) and 411 (injector voltage too low, level 1)</b> in UCP panel.</p><p><br></p><p>Action&nbsp; &nbsp;: Check the power of the ECU system. Found 26.79 Vdc.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Check the physical condition of the ECU <b>(ECU 8-06, P/N - X00E 5020 7957)</b> and other sensors to ECU.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Checked the ECU self-test.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Job is in progress.<b><br></b><br></p><p>&nbsp;</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-07-31_BDG-7205, TS engine yellow alarm on BDG', '2024-07-31 16:12:03', '2024-07-31 18:14:30', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
