  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot diesel leakage at bowl', 'Mechanic', 'CM ', 'Completed', '2024-08-02', '<p>Work - troubleshoot diesel leakage at bowl.</p><p>Found - diesel leaks at bowl during running.</p><p>31-July-2024</p><p>Action&nbsp;</p><p>- Dismantle internal parts to find the leak point.</p><p>- Work in progress.</p><p>01-Aug-2024</p><p>- Investigate the leak point.</p><p>- Found possible leak point at main bowl bottom.</p><p>- Remove deformed O-ring and RTV and clean the surface.</p><p>- Replace O-ring (Part 130) and apply RTV.</p><p>- Install flange ring and diaphragm.</p><p>- Put it back by the reverse order.</p><p>- Replace O-ring (Part 340, 210, 280).</p><p>- Apply O-ring grease at every rubber and teflon seals and gaskets.</p><p>02-Aug-2024</p><p>- Perform test run.</p><p>- Found no leak and no strange noise.&nbsp;<br></p><p><br></p><p>&nbsp;</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\71 DIESEL SYSTEM, CRANE &amp; AVIATION\\X-7115B\\2024\\TS seeping at bowl">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\71 DIESEL SYSTEM, CRANE &amp; AVIATION\\X-7115B\\2024\\TS seeping at bowl</a><br></p>', '2024-07-31 18:29:17', '2024-08-02 18:39:26', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
