-- Inserting report ID 33077
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform to replace globe valve diesel bankering', 'Mechanic', 'CM ', 'Completed', '2024-07-31', '<p>Problem: Globe valve damage</p><p>Action&nbsp; &nbsp;:remove the old valve and stud bolt&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;valve and flange are severely damage (need to repaint)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;install blind flanges and stud bolt not to ingress water in pipe line</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;tomorrow painter will repaint the flanges</p><p>1/Aug/24&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Painter were recondition and repaint the flanges</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;install two spiral wound gasket 3inch 150 class</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;tighten the flange with 117 Nm</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;install back the valve and purge the nitrogen into line&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;found leak from stem packing&nbsp; at 5 bar&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;retighten the dog bot check any leak&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; pressure rise up to 6.5 bar and found no leak</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; exercise the valve open and close 4 time and check leak&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; close the permit and housekeeping the area</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\99 VALVES\\2024\\2024-07-31 Replace Globe valve of disel bankering">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\99 VALVES\\2024\\2024-07-31 Replace Globe valve of disel bankering</a><br></p>', '2024-07-31 18:32:07', '2024-08-01 18:33:59', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
