  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S flame detector shows fault alarm time to time', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-08-01', '<p>Problem: Flame detector shows fault alarm time to time.</p><p>Found: "COPM FAULT" active time to time. (Continuous Optical Path Monitoring)</p><p>Action: Replaced the optical part of the flame detector.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Tighten the wire termination. found no water ingress.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Applied Down Corning grease to the optical part before reinstalling.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed function test with CCR. The result is OK.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked "mA" for normal operation. Fond 4.29 mA. (OK)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Need to monitor the unit.</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-01_FD-63005_TS flame detector shows fault alarm time to time">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-01_FD-63005_TS flame detector shows fault alarm time to time</a><br></p>', '2024-08-01 15:13:04', '2024-08-01 18:15:11', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-FD-63005', 'ZTK-FD-63005', 'Flame Det,near HP Flare KO Drum V-6300', NULL, NULL, 'Flame Det,near HP Flare KO Drum V-6300', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-08-01 15:13:04', '2024-08-01 18:15:11', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2024-08-01 15:13:04', '2024-08-01 18:15:11', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
