  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support hookup and commissioning team', 'Electrical & Instrument', 'OTH ', 'In Progress', '2024-08-03', '<p>Activity:&nbsp; &nbsp; Supported OTP test for well "E" to commissioning team and checked all sand monitoring data with test probe and troubleshooting sand "C" data lost.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Performed OTP tests as per procedure.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Checked and test the sand monitoring transmitters with test probe. All good except "C".<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Troubleshooted sand monitoring for well "C" data lost.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Found that the transmitter for well "C" is good.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Checked the wiring and termination (from JBZ-WP15-105 and JBZ-WP15-110. &gt; Correct as per Microcor wiring diagram.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Removed well "A", "B" and then check only well "C" without test probe. &gt; Data is shown at well "A" HMI.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; When check with test probe for well "C". &gt; Nothing shown at well "A" HMI.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Suspected that the cable for well "C" from JBZ-WP15-105 to JBZ-WP15-110 is damaged or the wiring is not correct.&nbsp;<br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-03_WP15_ESD test and OTP">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-03_WP15_ESD test and OTP</a><br></p>', '2024-08-03 20:06:32', '2024-08-03 20:24:20', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
