  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bo', NULL, 'EXTERNAL', '2024-08-03 20:06:32', '2024-08-03 20:24:20', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
