-- Inserting report ID 33099
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS abnormal noise and high vibration', 'Mechanic', 'CM ', 'Completed', '2024-08-04', '<p>Problem :&nbsp;</p><p>Abnormal noise around the check valves of the suction and discharge manifolds.</p><p><br></p><p>Action:</p><p><b>3 August 2024</b></p><p>(1) Disconnect the suction manifold flanges and removed the suction manifold.</p><p>(2) Disconnect the discharge manifold flanges and removed the discharge manifold. (by using special tool to move down the discharge manifold)</p><p>(3) Check the as found conditions of the check valves, 3 at suction and 3 at the discharge, and found discharge check valve no.3 is stuck a little more than others.</p><p>(4) Removed all check valves and inspect, exercise the valve discs and spring.</p><p>(5) Replaced all valve discs and springs with new one (6 EA) and replaced one valve lantern for no.3 discharge.</p><p>(6) Installed back all check valves to the manifolds.</p><p>(7) Installed the suction and discharged manifolds. (Torque 330 N-m)</p><p>(8) Installed the discharged flanges with new gaskets 3 inch 300/600 2EA. (150 N-m)</p><p>(9) Installed the suction flanges with new gasket 4 inch 600. (240 N-m)</p><p>(10) Clear and housekeeping the area.</p><p><br></p><p><b>4 August 2024</b></p><p>(1) Performed electrical and process deisolation.</p><p>(2) Test run and found no abnormal noise.</p><p>(3) Pump running with 0.4 Bar suction and 60 Bar discharged.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\48 GLYCOL REGENERATION T2\\P-4810 A\\2024\\2024-08-03 TS high vibration">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\48 GLYCOL REGENERATION T2\\P-4810 A\\2024\\2024-08-03 TS high vibration</a><br></p>', '2024-08-04 14:23:11', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-4810A-ASSY', 'ZTK-P-4810A-ASSY', 'Glycol Circulation Pump Assembly Train2A', NULL, NULL, 'Glycol Circulation Pump Assembly Train2A', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
