-- Inserting report ID 33142
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S PMA HVAC compressor refrigerant low', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-08-09', '<p>Action: Checked the leak/seeping point using snoop and refrigerant leak detector.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Detected refrigerant seeping from the liquid receiver service port (Check valve type)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Tighten the cup of the service port. No more seeping.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked the blower side.(No Leak)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Recharge the refrigerant 1kg.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Compressor running current is now&nbsp;<u>7.5 A (100% Load)</u>.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The compressor suction pressure is <u>32&nbsp;PSI,</u>&nbsp;and the discharge pressure is<u> 220&nbsp;PSI</u>.</p><p><span style="background-color: rgb(255, 255, 0);">Note: Blower(B-7880A) Bearing is damage.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Place a "Do NOT RUN" label on blower B-7880A.(MCC-CPP-7875)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Currently Blower (B-7880A) is not available. Blower (B-7880B) is available.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Spare of bearing will be arrived next two weeks.</span></p><p><br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<br></p><p><u>History on 02 Aug 24</u></p><p>Action: Perform the charging of the refrigerant from the compressor suction service port while the&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; compressor is running.<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The compressor is running at a current of&nbsp;<u>3.7 A (100% Load)</u></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;After recharging the refrigerant<u>&nbsp;(4 kg)</u>, the compressor running current is now&nbsp;<u>7.2 A (100% Load)</u>.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The compressor suction pressure is&nbsp;<u>28 PSI,</u>&nbsp;and the discharge pressure is&nbsp;<u>190 PSI</u>.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The compressor can run at the desired set point.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;The unit is keep running.</p><p><br></p><p>Plan to check motor insulation and resistance.</p><p>Plan to check the leak point.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-09_A7890A, TS pma air compressor leak">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-09_A7890A, TS pma air compressor leak</a><br></p>', '2024-08-09 15:20:22', '2024-08-16 17:03:31', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-7890B', 'ZTK-A-7890B', 'Air Cooled Condensing Stand by Unit', NULL, NULL, 'Air Cooled Condensing Stand by Unit', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-08-09 15:20:22', '2024-08-16 17:03:31', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-08-09 15:20:22', '2024-08-16 17:03:31', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.EI-TeamLead');
