  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 1Y PM lifeboat No.3 ', 'Mechanic', 'PM ', 'Completed', '2024-08-11', '<p><b><u>2024-08-09</u></b></p><p>Performed mechanical 1Y PM. 40% in progress</p><p>- Replaced engine oil PTT 15W40 (6L).</p><p>- Replace transmission gear oil (Automat DX III) 600mL..</p><p>- Top up steering oil Ptt HVI 15.</p><p>- Checked engine drive belt found in good condition.</p><p>- Replaced engine oil filter, fuel filter.</p><p>- Checked air cylinder pressure and found as<span style="background-color: rgb(255, 156, 0);"><b> air leakage at outlet common line from cylinders.</b></span></p><p>- Test run engine and housekeeping work area.</p><p><br></p><p><b><u>2024-08-11</u></b></p><p>- Replaced winch drum lube oil.</p><p>- Applied Bri-lube to wire ropes.</p><p>- Replaced HYD filter.</p><p>- Exercise the winch and checked the cylinders at both sides. (No leakage)</p><p>- Unit back in service.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\77 SAFETY LIVE SAVING &amp; PORTABLE FIRE FIGHTING EQUIPMENT\\SC - 7730\\2024\\2024-08-09 1Y PM">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\77 SAFETY LIVE SAVING &amp; PORTABLE FIRE FIGHTING EQUIPMENT\\SC - 7730\\2024\\2024-08-09 1Y PM</a><br></p>', '2024-08-09 17:25:54', '2025-07-20 14:36:23', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Cmms-Tech', false, 'ZTK') RETURNING id INTO new_report_id;
