-- Inserting report ID 33148
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Performed mechanical 8K PM & CSW', 'Mechanic', 'PM ', 'Completed', '2024-08-10', '<div><u>09-Aug</u></div><div><br></div><div>Performed mechanical 8K PM.</div><div><br></div><div><p>(1) Performed process, mechanical and electrical isolation.</p><p>(2) Replaced two diesel filters, lube oil filters and instrument air filters.</p><p>(3) Clean and check condition of flame arrestor.&nbsp;</p><p>(4) Check coupling condition. Found some rust then cleaned by WD40.&nbsp;</p><p><br></p><p><u>10-Aug</u></p><p><br></p><p>Performed engine crank soak wash.</p><p><br></p><p>(1)&nbsp; &nbsp; Remove piping accessary.</p><p>(2)&nbsp; &nbsp; Remove ignition cable and install dummy spark plug.</p><p>(3)&nbsp; &nbsp; Install air supply 30 psi to front bearing seal.</p><p>(4)&nbsp; &nbsp; Open air inlet premium manhole and Turbine air inlet filter duct to collect chloride sample. (Before and after)</p><p>(5)&nbsp; &nbsp; Fill cleaning product ZOK 1 pail and Deionized water 4 pail into mobile injection tank.</p><p>(6)&nbsp; &nbsp; Crank engine by using test crank mode.</p><p>(7)&nbsp; &nbsp; Open the spray valve 50% at the package to spray cleaning product while engine NGP reach to 21.1%.</p><p>(8)&nbsp; &nbsp; Step of cleaning</p><table border="1" cellspacing="0" cellpadding="0"><tbody><tr><td width="202" valign="top"><p align="center">Spray</p></td><td width="186" valign="top"><p align="center">Soak</p></td><td width="19" rowspan="2" valign="top"><p><br></p></td></tr><tr><td width="202" valign="top"><p align="center">8 min</p></td><td width="186" valign="top"><p align="center">30 min</p></td></tr></tbody></table><p>(9)&nbsp; &nbsp; Take water sample from drain line of exhaust duct.</p><p>(10)&nbsp; &nbsp; Wait for 15 min then continue process washing.</p><p>(11)&nbsp; &nbsp; Step of rinse water</p><p>&nbsp;Fill Deionized water 5 pail into mobile injection tank</p><table border="1" cellspacing="0" cellpadding="0"><tbody><tr><td width="126" valign="top"><p>&nbsp;</p></td><td width="198" valign="top"><p align="center">Spray</p></td><td width="198" valign="top"><p align="center">Stop</p></td></tr><tr><td width="126" valign="top"><p>1st&nbsp;Rinse</p></td><td width="198" valign="top"><p align="center">8 min</p></td><td width="198" valign="top"><p align="center">15 min</p></td></tr><tr><td width="126" valign="top"><p>2nd&nbsp;Rinse</p></td><td width="198" valign="top"><p align="center">8 min</p></td><td width="198" valign="top"><p align="center">5 min</p></td></tr></tbody></table><p>(12)&nbsp; &nbsp;Dry crank 8 min for 2 time.</p><p>(13)&nbsp; &nbsp;Reinstated piping and replaced new spark plug.</p><p>(14)&nbsp; &nbsp;Apply CI to VIGV and exercise by firing dry by running engine without load for 20 min.</p><p>Running Hour: 13419 Hr. Start Count 53.</p><p><br></p><p>Chloride content</p><p><br></p><p><br></p><p>Water properties analysis</p><p><br></p></div><div><p><br></p><p><br></p><p><br></p></div>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\72 MAIN &amp; VITAL POWERr GENERATION\\7210 Gas Turbine Generator No. 1\\2024\\2024-08-09 8K PM">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\72 MAIN &amp; VITAL POWERr GENERATION\\7210 Gas Turbine Generator No. 1\\2024\\2024-08-09 8K PM</a><br></p>', '2024-08-09 17:52:18', '2024-08-11 21:42:29', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Turbi', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTG-7210', 'ZTK-GTG-7210', 'Gas Turbine Generator Package No.1', NULL, NULL, 'Gas Turbine Generator Package No.1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Eric', NULL, 'EXTERNAL', '2024-08-09 17:52:18', '2024-08-11 21:42:29', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Turbi');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Henry', NULL, 'EXTERNAL', '2024-08-09 17:52:18', '2024-08-11 21:42:29', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Turbi');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Plate', NULL, 'EXTERNAL', '2024-08-09 17:52:18', '2024-08-11 21:42:29', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Turbi');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Leo', NULL, 'EXTERNAL', '2024-08-09 17:52:18', '2024-08-11 21:42:29', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Turbi');
