BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Test run Hydrate inhibitor injection pump phase 1D', 'Electrical & Instrument', 'OTH ', 'In Progress', '2024-08-09', '<p><b><u>Problem: </u></b></p><p>Air seeping at pilot.</p><p><b><u>Found: </u></b></p><p>Pilot assembly underneath is seeping</p><p><b><u>Action: </u></b></p><p>Replaced the O-ring and overhaul the pilot.</p><p>Performed function test at workshop.&nbsp;</p><p>Pump is working properly.</p><p><br></p><p>PUMP MODEL: <b>P1000V800</b></p><p>PILOT MODEL: <b>P04-6S-L- Test run Hydrate inhibitor injection pump</b>&nbsp;for Phase 1D.</p><p><b><u>Note :&nbsp;</u></b></p><p>Hydrate inhibitor injection pump, 3 out of 1 is completed.</p><p><br></p><p><br></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-09_Test run Hydrate inhibitor injection pump phase 1D', '2024-08-09 18:29:51', '2024-08-09 21:38:42', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
