-- Inserting report ID 33150
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Upgrade LTMR version for P-6835', 'Automation', 'OTH ', 'Under Monitoring', '2024-08-10', '<p><b>Activity</b>:&nbsp; &nbsp; Upgrading LTMR version (motor control) from "2.4" to "3.0" for P-6835/F3-12.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Racked-out the spare feeder/F17-54 (18.5kW).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Back-up the project file, configuration file and log file of spare feeder.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Checked the original LTMR version of spare feeder. (version: 2.4)<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Upgraded the LTMR version of spare feeder from 2.4 to 3.0.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Change the network address of spare feeder from 4 to 2. <i>(In order to be same with network address of P-6835 (network address: 2)).</i></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Racked out the feeder for P-6835/F3-12 (wash down water pump).</p><p></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Racked the spare feeder into F3-12 but no succeeded. (Got <b>Undervoltage alarm</b>).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Racked out the spare feeder and checked the project file again.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Copied the project file and calibration file from P-6835 and download into the spare feeder.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Racked in the spare feeder again into the F3-12 and check. (Still no success: <b>Undervoltage Alarm</b>).</p><p><b><br></b></p><p><b>Status</b>:&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp; &nbsp; Job is still in progress. (Finding the reason of why undervoltage alarm appear even though all the project file and calibration file plus checksum are same with those from washdown water pump, P-6835.)</p><p><br></p><p><b>Update Job Status:</b></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Checked the LTME which is sources of voltage sensing points.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Found that the terminal connections of that LTME is loosen and not properly inserted into the slot.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Properly and firmly inserted it into the slot.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Performed test run the spare feeder into the F3-12. (The pump is running properly and no more alarm). &gt; Succeeded.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Keep running and change the tag as in "P-6835/F3-12" and keep the original wash down feeder into spare feeder which is F17-54.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; The job is now already completed but keep under monitoring.</p><p><br></p><p><b>Note:</b>&nbsp; &nbsp; -&nbsp;<i> &nbsp; The completed finalized calibration and log files are in the link below.</i></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; </p><p><br></p><p></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-10_LTMR, P-6836, Upgrade LTMR version for P-6835 Washdown water pump">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-10_LTMR, P-6836, Upgrade LTMR version for P-6835 Washdown water pump</a><br></p>', '2024-08-10 15:15:55', '2024-08-10 17:30:28', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6835-ASSY', 'ZTK-P-6835-ASSY', 'Wash Down Water Pump Assembly', NULL, NULL, 'Wash Down Water Pump Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-08-10 15:15:55', '2024-08-10 17:30:28', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
