-- Inserting report ID 33181
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Remove and install the belt tensioner of dryer B', 'Electrical & Instrument', 'CM ', 'Completed', '2024-08-13', '<p><b><u>Found:</u></b></p><p>- Laundry dryer machine (LD 02A &amp; LD02B) belt tensioner joint are cracked.</p><p><b><u>Action:</u></b></p><p>- Removed the belt tensioner from the dryer machine LD02B.</p><p>- Fixed the cracked joint by welder.</p><p>- Re-installed the belt tensioner at dryer machine LD02B.</p><p>- Adjusted the belt tension by mechanic team. (72.4 Hz)</p><p>- Performed function and working properly.</p><p><b><u>Plan:</u></b></p><p>- Will remove and fix the belt tensioner crack joint for LD02A.</p><p><span style="background-color: rgb(255, 255, 0);"><u><b>History:</b></u></span></p><p><span style="background-color: rgb(255, 255, 0);">26 July 2024<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Replaced new bearings 2 Ea for Pulley.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Reinstalled and adjusted the belt tensions as per Maintenance Manual. (Adjusted Belt tension C: 72.2 Hz , B: 76.2 Hz) with a frequency meter.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Function test run and no more strange noise.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : But the equipment was stop by "No Vacuum" Error code.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Checked and verified the Vacuum switch, the switch is working properly.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Checked the vacuum switch hose condition and it looked abnormal.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Manually turned&nbsp; the drum of LD-02B slowly and it generated strange noise.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Opened up the cover and observed the motor pulley &amp; drive belt.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Found cracking points on the motor pulley mounting support.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Disassembled the mounting and checked the pulley condition.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Found the one side of pulley&nbsp; bearing was severely damaged.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Need to order spare : Ball Bearings 2 Ea &amp; Shaft</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Need to fix pulley mounting cracking areas.</span></p><p><span style="background-color: rgb(255, 255, 0);">Bearing P/N :&nbsp;SKF ITALY 04&nbsp; 09 124J&nbsp; 6001-2RSH&nbsp;&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">27 July 2024</span></p><p><span style="background-color: rgb(255, 255, 0);"><u>Problem</u>:&nbsp; After replaced the new bearings, the equipment can manual turn properly with no more vibration noise. While function test run,&nbsp; it was tripped by&nbsp;"No Vacuum"&nbsp;Error code.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Found:&nbsp; Found the vacuum switch hose condition was not good.</span></p><p><span style="background-color: rgb(255, 255, 0);">Action : Replaced and arranged new Vacuum switch hose.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Function test run with Load by Laundry man&nbsp; and it can run properly. (No more trip and vibration noise).</span></p><p><u style="background-color: rgb(255, 255, 0);">Spare part: Hose P/N: 877 5251-02</u></p><div><u><br></u></div>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-13_LD02B, Remove and install belt tensioner for dryer machine', '2024-08-13 15:27:03', '2024-08-17 21:15:02', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'Accommodation', 'Accommodation', 'Accommodation', NULL, NULL, 'Accommodation', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zarni', NULL, 'EXTERNAL', '2024-08-13 15:27:03', '2024-08-17 21:15:02', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bo', NULL, 'EXTERNAL', '2024-08-13 15:27:03', '2024-08-17 21:15:02', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Plate', NULL, 'EXTERNAL', '2024-08-13 15:27:03', '2024-08-17 21:15:02', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
