  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS abnormal noise at bearings', 'Mechanic', 'CM ', 'Completed', '2024-08-13', '<p>Work - To verify abnormal noise from bearings.</p><p>Action</p><p>- Check as found pulley alignment. Found normal.</p><p>- Check as found belt tension. Found slightly high tension.</p><p>- Remove belt and check bearing defect.</p><p>- Found no bearings defect but low level of grease inside the bearings.</p><p>- Inject grease until the old grease comes out from the ring.</p><p>- Tighten the bearings mounting bolts.</p><p>- Check the alignment and install the belt.</p><p>- Adjust the belt tension. 32 Hz.</p><p>- Perform test run and no abnormal sound occurs.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\GAS COOLER FAN (E-4360-A and E-4360B)\\E-4330 (1st Stage)\\E-4330 D\\2024\\2024-08-13 TS abnormal noise">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\GAS COOLER FAN (E-4360-A and E-4360B)\\E-4330 (1st Stage)\\E-4330 D\\2024\\2024-08-13 TS abnormal noise</a><br></p>', '2024-08-13 17:33:13', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
