  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhaul hydrate inhibitor pump', 'Electrical & Instrument', 'CM ', 'Completed', '2024-08-13', '<p><b><u>Problem:</u></b></p><p>- Hydrate inhibitor pump (P-1594C) is leak from the pilot body.</p><p><b><u>Found:</u></b></p><p>- Pilot piston O-rings are deformed.</p><p><b><u>Action:</u></b></p><p>- Replaced the pilot piston O-rings with new spare.</p><p>- Performed function test and leak check.</p><p>- No leak found.</p><p>- Pump can run properly and built up pressure to 1300 PSI.</p><p><br></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-13_P-1594C, Overhaul hydrate inhibitor pump from WP15', '2024-08-13 19:09:55', '2024-08-13 19:38:25', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
