  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify hydrate inhibitor pump not working', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-08-13', '<p><b><u>Action</u></b></p><p>For P-1594A, check the instrument supply to the air pilot relay (5 bar).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -Found the air pilot relay that cannot drive to the pump.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (found sometime pilot port change when visually checked)</p><p>For P-1594B, check the instrument supply to air pilot relay (5bar)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -Pilot can drive the pump but discharge of the pump cannot build up the pressure.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p><p><b><u>As left condition</u></b></p><p>-Swap the air pilot from pump B to A and function test the pump A. (It can work properly but take time to build up pressure)</p><p>-Remove the pump B to ZPQ for overhauling.</p><p><br></p><p><b><u>Plan</u></b></p><p>-Tomorrow, continue to replace the overhaul one for Pump B</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-13_P-1594A,B, Fix hydrate injection pump not working', '2024-08-13 20:19:25', '2024-08-21 19:44:57', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
