-- Inserting report ID 33204
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS wash down water pump trip', 'Electrical & Instrument', 'CM ', 'Completed', '2024-08-14', '<p><b><u>Problem:</u></b></p><p>- Wash down water pump feeder drawer (F3-12) break trip.</p><p><b><u>Found:</u></b></p><p>- The breaker is tripped without any alarm at feeder drawer when the unit start.</p><p>- At CCR side show emergency stop and fault.</p><p><b><u>Action:</u></b></p><p>- As found wash down water pump feeder drawer is LTMR version upgraded spare drawer that swapped from original drawer.</p><p>- Suspected the drawer malfunction and need to troubleshoot.</p><p>- Replaced with wash down water pump original drawer and performed function test.</p><p>- The pump can run properly without tripping the breaker.</p><p><b><u>Plan:</u></b></p><p>- Will upgrade the LTMR version for the wash down water pump feeder drawer.</p><p><u style="background-color: rgb(255, 255, 0);"><b>History:</b></u></p><p><span style="background-color: rgb(255, 255, 0);"><b>Activity:</b>&nbsp; &nbsp; Upgrading LTMR version (motor control) from "2.4" to "3.0" for P-6835/F3-12.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Racked-out the spare feeder/F17-54 (18.5kW).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Back-up the project file, configuration file and log file of spare feeder.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Checked the original LTMR version of spare feeder. (version: 2.4)<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Upgraded the LTMR version of spare feeder from 2.4 to 3.0.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Change the network address of spare feeder from 4 to 2.&nbsp;<i>(In order to be same with network address of P-6835 (network address: 2)).</i></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Racked out the feeder for P-6835/F3-12 (wash down water pump).</span></p><p></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Racked the spare feeder into F3-12 but no succeeded. (Got&nbsp;Undervoltage alarm).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Racked out the spare feeder and checked the project file again.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Copied the project file and calibration file from P-6835 and download into the spare feeder.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Racked in the spare feeder again into the F3-12 and check. (Still no success:&nbsp;Undervoltage Alarm).</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Status:&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp; &nbsp; Job is still in progress. (Finding the reason of why undervoltage alarm appear even though all the project file and calibration file plus checksum are same with those from washdown water pump, P-6835.)</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Update Job Status:</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Checked the LTME which is sources of voltage sensing points.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Found that the terminal connections of that LTME is loosen and not properly inserted into the slot.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Properly and firmly inserted it into the slot.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Performed test run the spare feeder into the F3-12. (The pump is running properly and no more alarm). &gt; Succeeded.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Keep running and change the tag as in "P-6835/F3-12" and keep the original wash down feeder into spare feeder which is F17-54.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; The job is now already completed but keep under monitoring.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Note:&nbsp; &nbsp; -&nbsp;<i>&nbsp;&nbsp; The completed finalized calibration and log files are in the link below.</i></span></p>', NULL, '2024-08-14 20:05:13', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6835-ASSY', 'ZTK-P-6835-ASSY', 'Wash Down Water Pump Assembly', NULL, NULL, 'Wash Down Water Pump Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zarni', NULL, 'EXTERNAL', '2024-08-14 20:05:13', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Liam', NULL, 'EXTERNAL', '2024-08-14 20:05:13', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL);
END $$;

