  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support GDU condensate line project team', 'Electrical & Instrument', 'OTH ', 'Completed', '2024-08-14', '<p>-&nbsp;Support GDU condensate line project team by:</p><p>- Installed needle valves at atomization air line. (E- 4750 and 4752).</p><p>- Bypass both pilot flame signal. (E- 4750 and 4752)</p><p>- Re boiler is combustion properly with condensate line as per below parameters ;</p><p>FCV = 36%, Condensate Fuel Flow = 37kg/hr , Combustion Air Flow = 1300 kg/hr , Air to Fuel Ratio = 35.13</p><p><br></p><p>Note: When running with condensate about 20 minutes, pilot ionization is very low (0.2 Micro Amp) and&nbsp;</p><p>After running about 30minutes and production team want to stop the burner, at this time we performed that when removing the pilot bypass, the unit is trip by pilot flame off.</p><p>Old atomization airline tubing for E-4750 and 4752 was given to the Operator.&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-14_Support GDU condensate project Night', '2024-08-15 08:03:16', '2024-08-16 19:10:42', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
