  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'HSWG-CPP-100 B Communication unhealthy alarm', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-06-29', '<p>Activity:&nbsp;HSWG-CPP-100 B Communication unhealthy alarm</p><p>Found:&nbsp;GTG-7220, GTG-7230 and load under Bus B cannot control by ECS</p><p>Action: Started GTG-7210 running with GTG-7220 and stop GTG-7230</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;SIS gate way for HSWG-CPP-100 Bus C &amp; B shows communication unhealthy at ECS system</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;Performed tightness check for LAN connector</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;After LAN tightness check for SIS gate way B, alarm cleared by itself</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;SIS gate way running normal with no alarm</p><p><br></p><p>Note:&nbsp;Plan to check LAN continuity if alarm come again</p><p>Plan Next Action if it come from other issue</p><div>•Transfer all HV load from bus B to Bus A</div><div>•Perform hard reset SIS Gateway No. IP: 192.168.26.72&nbsp;&nbsp; Type: 4 ports, Firmware :V4.1.1.0 and Monitor</div><p>    </p><div>•If alarm still persist, replace with new spare.</div><div><br></div><div><br></div><div><br></div><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br></p>', NULL, '2024-08-15 16:56:38', '2024-08-15 16:59:25', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HSWG-CPP-100', 'ZTK-HSWG-CPP-100', 'HV Switchgear 6.6kV 2500A PCKG', NULL, NULL, 'HV Switchgear 6.6kV 2500A PCKG', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Sithu', NULL, 'EXTERNAL', '2024-08-15 16:56:38', '2024-08-15 16:59:25', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
END $$;

