  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, ' HSWG-CPP-100 B Communication unhealthy alarm', 'Electrical & Instrument', 'CM ', 'Completed', '2024-08-15', '<p>Activity:&nbsp;&nbsp;HSWG-CPP-100 B Communication unhealthy alarm</p><p>Found: The applied cable tie squeezed the communication cable&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Cut the cable tie</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Now, no alarm and SIS gate way running normal</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History: 29 June 2024</span></p><p>Activity:&nbsp;HSWG-CPP-100 B Communication unhealthy alarm</p><p>Found:&nbsp;GTG-7220, GTG-7230 and load under Bus B cannot control by ECS</p><p>Action: Started GTG-7210 running with GTG-7220 and stop GTG-7230</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;SIS gate way for HSWG-CPP-100 Bus C &amp; B shows communication unhealthy at ECS system</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;Performed tightness check for LAN connector</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;After LAN tightness check for SIS gate way B, alarm cleared by itself</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;SIS gate way running normal with no alarm</p><p><br></p><p>Note:&nbsp;Plan to check LAN continuity if alarm come again</p><p>Plan Next Action if it come from other issue</p><div>•Transfer all HV load from bus B to Bus A</div><div>•Perform hard reset SIS Gateway No. IP: 192.168.26.72&nbsp;&nbsp; Type: 4 ports, Firmware :V4.1.1.0 and Monitor</div><p></p><div>•If alarm still persist, replace with new spare.</div><div><br></div><div><br></div><div><br></div><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', NULL, '2024-08-15 17:10:31', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-TeamLead', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
