  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support GDU-4700 start up for production', 'Electrical & Instrument', 'OTH ', 'Completed', '2024-08-15', '<p>Action :&nbsp;</p><p>-&nbsp;Support GDU-4700 start up for production.</p><p>- Start both pilots (E-4752 and E-4750) and local pilot flames are present enough.</p><p>- Start the burner and local burner flames are present enough.</p><p>- But Ionization current of E-4752 is low (Around 4 Micro Amp).</p><p>- Opened the cone, adjusted the pilot air adjuster and Ionization current of E-4752 is increased.</p><p>- Now GDU-4700 is running properly.&nbsp;</p><p><br></p><p>Ionization current: E-4750 is 20.37 Micro Amp.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; E-4752 is 19.41 Micro Amp.</p>', 'U:\\01 E&amp;I\\Activity Photos\\2024-08-15_GDU-4700, Support start up for production', '2024-08-15 18:36:29', '2024-08-15 18:46:52', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
