-- Inserting report ID 33237
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To fix the valve is stuck at 50% ', 'Electrical & Instrument', 'CM ', 'Completed', '2024-08-18', '<p><b><u>Problem:</u></b></p><p>-To fix the valve SDV-03119 is stuck at 50% when close command.</p><p><b><u>Action: </u></b></p><p>- Cleaned the pilot valve and quick exhaust valve.</p><p>- Removed the actuator from the valve and function test.</p><p>- Confirm that the actuator is function properly.</p><p>- Function test the valve manually by hand</p><p>- Found valve is stuck&nbsp;</p><p>- When function test the valve with actuator, valve can open but can not close and stuck at 50%.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<br></p><p><b><u style="background-color: rgb(255, 255, 0);">History: 12Aug24</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Activity:&nbsp;To fix the gas leak from the solenoid valve of shutdown valve SDV-03119</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Function test with CCR</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; No gas leak was found</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found that the SOV for PCS is defective</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Replaced with new spare one</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Function test with CCR</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found that actuator cannot close the valve fully and stuck at 50%</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Exercised the actuator many times but still the same result</span></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-18_SDV-03119, To fix the valve is stuck at 50% when close command', '2024-08-18 16:04:15', '2024-08-19 19:37:35', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SDV-03119', 'ZTK-SDV-03119', 'SDV on 4"-PL-03103-JS2N for ESD 3CA', NULL, NULL, 'SDV on 4"-PL-03103-JS2N for ESD 3CA', 'WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
