  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S GDU train 2 cannot start', 'Electrical & Instrument', 'CM ', 'Completed', '2024-08-18', '<p>Problem : GDU train 2 cannot start after blower changeover.</p><p>Found&nbsp; &nbsp; : GDU was tripped by E-4850 pilot flame off alarm.</p><p>Action&nbsp; &nbsp; : Perform running test and check the pilot flame monitor. </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Found pilot flame is ON and ionization current of E-4850 is low.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Restarted the unit and monitored the ionization current for both E-4850 and E-4852.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (E-4850=16.36 micro Amp, E-4852 =15.68 micro Amp)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Now the unit is back to normal.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-18_E-4850,52, GDU train 2 cannot start', '2024-08-18 19:35:24', '2024-10-20 08:06:39', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-E-4850-ASSY', 'ZTK-E-4850-ASSY', 'Fire Tube Heater Assembly', NULL, NULL, 'Fire Tube Heater Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
