  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Lube oil seeping from GB LSS at P-4810A', 'Mechanic', 'CM ', 'Completed', '2024-08-24', '<p><b><u>2024-08-21</u></b></p><p>- Removed coupling guards and absorbers for both sides (LSS and HSS) of Gearbox.</p><p>- Drained all lube oil from gearbox.</p><p>- Measured all shim as per below - (<b>Points are ref, from vibration Points)</b>. -&nbsp;</p><p><br></p><table class="table table-bordered"><tbody><tr><td>No.3&nbsp;</td><td>0.3 mm</td></tr><tr><td>No.4&nbsp;</td><td>0.25mm</td></tr><tr><td>No.5&nbsp;</td><td>0.25mm</td></tr><tr><td><p>No.6</p></td><td>0.3mm</td></tr><tr><td>No.7</td><td>0.3mm</td></tr><tr><td>No.8</td><td>0.25mm</td></tr></tbody></table><p>- Moved down the gearbox to the workshop.</p><p>- Checked shaft end and coupling distance from the shaft.</p><p>- Removed coupling for gearbox LSS.&nbsp;</p><p>- Housekeeping the area.</p><p><br></p><p><b><u>2024-08-21</u></b></p><p>- Removed seal cover and seal.</p><p>- Measured shaft OD - 89.57mm and coupling ID - 89.82mm.</p><p>- Replaced new oil seal and installed it back.</p><p>- Tightened with torque 57 Nm for side cover.</p><p>- Tried to Install coupling with heating pad about 130C temperature but cannot fit it.</p><p>- Found technical error on&nbsp; heating machine.(Program error).</p><p>- Housekeeping the area.</p><p><br></p><p><b><u>2024-08-23</u></b></p><p>- Installed coupling to GB shaft LSS about 150C temperature.</p><p>- Performed air and water cooling to the shaft to avoid&nbsp;thermal radiation&nbsp;to the seal.</p><p>- Moved to upper deck and set up on the skip.</p><p>- Installed absorbers on both side of LSS and HSS.</p><p>- Top-up lube oil about 8L.</p><p>- Housekeeping the area.</p><p><br></p><p><b><u>2024-08-24</u></b></p><p>- Performed laser alignment on both LSS and HSS with <span style="background-color: rgb(0, 255, 0);"><b>quiet good result.</b></span></p><p><br></p><p>- Measured coupling gap for LSS- 3.5mm and HSS- 2.5mm.</p><p>- Tightened all nuts with torque 240 Nm.</p><p>- Performed test run and keep close monitoring. (No leakage at all).</p><p>- Housekeeping the area.</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\48 GLYCOL REGENERATION T2\\P-4810 A\\2024\\2024-08-21 TS lube oil seeping at GB LSS">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\48 GLYCOL REGENERATION T2\\P-4810 A\\2024\\2024-08-21 TS lube oil seeping at GB LSS</a><br></p>', '2024-08-21 17:50:04', '2024-08-24 17:42:51', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
