  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Butterfly valve passing and seawater leaking', 'Mechanic', 'CM ', 'Completed', '2024-08-23', '<p>Problem - Sea water was leaked at the pump discharge bypass line.</p><p>As Found - GRP pipe was damaged and sea water leaked out from this point.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Isolation butterfly valve was passing.</p><p>Action - Remove the defective butterfly valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inspect the valve condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replaced with new butterfly valve ( 3" 150 class).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Tighten the stud bolts ( Torque valve is 86Nm)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Perform leak test and found no leak at flange joint.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Perform belzona first coating at the leak point and waiting kiling time around 2 hours.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Perform belzona 1982 solidfier and fiber glass wrapping to fix leak point and waiting killing time&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;around 4 hours.</p><p><br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\P-6610 A Jocky Pump\\2024\\2024-08-23 Replaced isolation butterfly valve of pump discharge line">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\P-6610 A Jocky Pump\\2024\\2024-08-23 Replaced isolation butterfly valve of pump discharge line</a><br></p>', '2024-08-23 17:54:46', '2024-08-24 17:24:49', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
