  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, ' T/S level transmitter shows fault low alarm', 'Electrical & Instrument', 'CM ', 'Completed', '2024-08-25', '<p>Action: Checked the transmitter and found the reading shows negative value.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Test the transmitter reading with magnet move along the sensor probe, the transmitter can show correct reading.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Clean the chamber for the probe with water but the transmitter reading is still incorrect.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Suspect that the probe is not moving along with water during cleaning.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Cleaned the chamber with the oiler one and the probe moved.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Calibrate the LT transmitter and performed function test. The transmitter reading is normal without fluctuation.</p>', NULL, '2024-08-25 15:42:42', '2024-08-26 00:36:55', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
