-- Inserting report ID 33298
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S level transmitter abnormal reading', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-08-26', '<p>Problem :&nbsp;T/S level transmitter abnormal reading. As per CCR information, there were some spikes on 25/08/2024.</p><p>Found&nbsp; &nbsp; : :LT-41009 is reading normal when we found.</p><p>Action&nbsp; &nbsp; : Simulate the transmitter by HART (0-2000 mm) and monitor with milli amp clamp meter.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found CCR and local transmitter are same as per simulated value.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Cleaned the sensor probe of guided wave level transmitter.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Flushed the chamber with the water.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Function test with CCR and it is working properly (Under Monitoring).</p><p><br></p><p>Note : Found LT''s Column drain ball valve is passing. Found LT''s Column drain ball valve gasket is not fitted and we fitted with new gasket.</p><p>Gasket size : SPW 3/4" 300#</p><p>LT column tag no, is mismatched LT 41009 and LT41008. Need to swap tags.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-26_LT41009,TS abnormal reading', '2024-08-26 16:00:49', '2024-08-27 16:44:55', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LT-41009', 'ZTK-LT-41009', 'LT on V-4100 to Control LV-41009', NULL, NULL, 'LT on V-4100 to Control LV-41009', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'William', NULL, 'EXTERNAL', '2024-08-26 16:00:49', '2024-08-27 16:44:55', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Peter', NULL, 'EXTERNAL', '2024-08-26 16:00:49', '2024-08-27 16:44:55', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
