-- Inserting report ID 33299
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S platform tripped and resume power', 'Electrical & Instrument', 'OTH ', 'Completed', '2024-08-26', '<p>Action: The platform was tripped with ESD1.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Turn KOS switches on and resume the power.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Found the fusible loop pressure low low alarm with pressure 2.4 barg. Checked all the instruments in the fusible loop.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Found the communication was not resolved. Assist ICT to troubleshoot IDU malfunction.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;ICT onboard at WP03 and replaced malfunction IDU. The communication back to normal.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Checked the breaker and relay condition for main breaker and solar incoming.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Found both relays and breakers are in good condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Reset ESD. Performed trip test with com loss scenario and power loss. Found no root cause of the platform power loss.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Checked the whole wiring loop for electrical system. No abnormal found.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Restarted the platform.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-26 TS WP-03 Trip and Communication Loss', '2024-08-26 17:23:54', '2024-08-26 22:34:22', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP03', 'ZTK-WP03', 'Zawtika Wellhead Platform 03', NULL, NULL, 'Zawtika Wellhead Platform 03', 'WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bo', NULL, 'EXTERNAL', '2024-08-26 17:23:54', '2024-08-26 22:34:22', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.Automation');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Brown', NULL, 'EXTERNAL', '2024-08-26 17:23:54', '2024-08-26 22:34:22', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.Automation');
