  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S tumble dryer machine malfunction', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-08-29', '<p>Problem: Laundry dryer machine (LD-02B) is tripped during running.</p><p>Found: LD-02B is tripped by No Vacuum alarm during both unit A and B running after 10 minutes.</p><p>Action: Check the vacuum pressure switch and function test the contact.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;Found the switch is working properly.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Check and clean the filter of drum to exhaust duct line.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Check and clean the main exhaust line of LD-02B.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Check the vacuum switch sensing duct line. Found a lot of dusts (particles).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Remove Heating element and clean the vacuum switch sensing duct line.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;Reinstall back all the assemblies and monitor the dryer machine condition. (no alarm)</p><p><span style="background-color: rgb(255, 255, 0);">Note: Inform to night shift person to keep monitoring the tripped alarm when the both unit run.&nbsp;</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-29_LD-02B,TS Laundry Dryer malfunction and tripped by low vaccum alarm', '2024-08-29 15:10:51', '2024-08-31 21:24:24', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'Accommodation', 'Accommodation', 'Accommodation', NULL, NULL, 'Accommodation', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
