-- Inserting report ID 33324
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify lifeboat no.3 Davit motor low insulation', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-08-30', '<p>Problem: Lifeboat no.3 davit motor was insulation low.</p><p>Found: Motor heaters power cables was isolated.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Davit motor local control panel was corroded sign due to water ingress at long time ago.&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;</p><p>Action: Measured the winding resistance, insulation resistance and microohm for davit motor and motor heater.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Before removed the main incoming and heaters power cables, results are follows</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Microohm&nbsp;resistance for motor <a href="winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-W1:223.0mOhm">winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-</a>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<a href="winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-W1:223.0mOhm">W1:223.0mOhm</a></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Resistance for motor winding:<a href="U1-V1:0.6Ohm,U1-V1:0.6Ohm,V1-W1:0.5mOhm">U1-V1:0.6Ohm,U1-V1:0.6Ohm,V1-W1:0.5mOhm</a><a href="winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-W1:223.0mOhm"></a></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Insulation resistance for motor <a href="winding:U1:0.02MOhm,V1:0.02MOhm,W1:0.02MOhm">winding:U1:0.02MOhm,V1:0.02MOhm,W1:0.02MOhm</a></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Resistance for motor heaters: N<a href="no.1:45.0Ohm">o.1:45.0Ohm</a>, <a href="No.2:45.0Ohm">No.2:45.0Ohm</a>&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Insulation resistance for motor <a href="heaters:no.1:0.09MOhm,">heaters:No.1:0.09MOhm,</a>&nbsp;<a href="No.2:0.09Mohm">No.2:0.09Mohm</a><a href="No.2:0.09Mohm"></a></p><p><br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; After&nbsp;removed the main incoming and heaters power cables, results are follows</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Microohm&nbsp;resistance for motor&nbsp;<a href="winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-W1:223.0mOhm">winding:U1-V1:334.5mOhm,U1-V1:333.4mOhm,V1-</a>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<a href="winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-W1:223.0mOhm">W1:333.4mOhm</a></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Resistance for motor winding:<a href="u1-v1:0.6Ohm,U1-V1:0.6Ohm,V1-W1:0.5mOhm">U1-V1:0.6Ohm,U1-V1:0.6Ohm,V1-W1:0.5mOhm</a><a href="winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-W1:223.0mOhm"></a></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Insulation resistance for motor&nbsp;<a href="winding:U1:0.02MOhm,V1:0.02MOhm,W1:0.02MOhm">winding:U1:0.02MOhm,V1:0.02MOhm,W1:0.02MOhm</a></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Resistance for motor heaters: N<a href="no.1:45.0Ohm">o.1:1.372kOhm</a>, No.2:1.375kOhm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Insulation resistance for motor heaters: No.<a href="heaters:no.1:0.09MOhm,">1:23.7MOhm,</a>&nbsp;<a href="no.2:0.09Mohm">No.2:23.2Mohm</a></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; After measured the motor heater, replaced the heater terminal block and installed the power cables &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;for heater and measured the voltage and ampere are 233.4VAc and 0.2A.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Covered the davit motor local control panel and motor junction box with Denso tape for protect &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;water ingress.<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Under monitoring the motor heater and will measure the motor insulation again on next days.</p><p><br></p><p>Note: Isolated the motor thermostat cables due to replace for motor heater terminal block which used from &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;the motor thermostat terminal block.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br></p><p><br></p><p><br></p><p><br></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-30_SC-7730, To verify Davit motor for life boat No3 that has low insulation', '2024-08-30 19:25:19', '2024-09-01 08:45:43', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HPU-7730', 'ZTK-HPU-7730', 'Hydr Power Unit for Davit Life Boat No.3', NULL, NULL, 'Hydr Power Unit for Davit Life Boat No.3', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SC-7730', 'ZTK-SC-7730', 'Free Fall Life Boat No.3 Main Deck', NULL, NULL, 'Free Fall Life Boat No.3 Main Deck', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2024-08-30 19:25:19', '2024-09-01 08:45:43', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2024-08-30 19:25:19', '2024-09-01 08:45:43', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

-- Inserting report ID 33325
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace proximitor sensor of bearing #1Y', 'Electrical & Instrument', 'CM ', 'Completed', '2024-08-31', '<p><b><u>Problem</u></b></p><p>-Gap voltage of bearing #1Y axis reading is abnormal.</p><p><b><u>Action</u></b></p><p>-Replace the proximitor sensor (14 meter system) of VE-72341-1(<span style="background-color: rgb(255, 255, 0);">bearing #1Y axis</span>).</p><p>-Check the cable brass connection between probe cable and extension cable.(Good)</p><p>-As per SOLAR team recommendation, check the part number of extension cable, sensor probe and proximotor sensor of bearing #1Y.</p><p>-(Extension cable P/N:190816-120 , Sensor probe P/N:1046778-14 , Proximitor P/N:33180-X1-05 )</p><p>-Monitor the gap voltage of #1Y is -9.4Vdc. (Before replaced is -11.0Vdc)</p><p><br></p><p>-For <span style="background-color: rgb(255, 255, 0);">bearing #1X axis</span>, check the part number of extension cable, sensor probe and proximotor sensor of bearing #1Y. </p><p>-(Extension cable P/N:190816-120 , Sensor probe P/N:1046778-14 , Proximitor P/N:33180-X1-05 )</p><p>-Measure the R total of #1X is 11.7 Ohm.</p><p>&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-31_GTG-7230, Replace proximitor bearing #1Y', '2024-08-31 15:16:48', '2024-08-31 16:07:12', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTG-7230', 'ZTK-GTG-7230', 'Gas Turbine Generator Package No.3', NULL, NULL, 'Gas Turbine Generator Package No.3', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
