  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '12M PM Topside gas detector GDF and GDFR/T', 'Electrical & Instrument', 'PM ', 'In Progress', '2024-08-31', '<p><u>Action:</u></p><p>Performed 12M PM on topside point watch and open path gas detector for Lower deck and Upper deck.</p><p>- Performed detector fault test.</p><p>- Checked cable gland condition and tighten cable termination.</p><p>- Applied grease for detector earth connection.</p><p>- Performed calibration for GDF-42206, GDF-67001, GDF-40011.</p><p>- Function test with automation.&nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">Upper/Cooler Deck and GDU =7.5% Completed (3 out of 40 completed)</span></p><p><span style="background-color: rgb(0, 255, 0);">Main/ Mezzanine Deck&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;=&nbsp;100% Completed&nbsp;(50 out of 50 Completed)</span></p><p><span style="background-color: rgb(0, 255, 0);">Lower Deck&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; = 100% Completed (45 out of 45 completed)</span></p><p><span style="background-color: rgb(0, 255, 0);">Sea Deck&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; = 100% Completed (6 out of 6 completed)</span></p><p><span style="background-color: rgb(255, 255, 0);">Total completed&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; = 74% (104 out of 141) (Still in progress)</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History:</span></p><p><u style="background-color: rgb(255, 255, 0);">30 Aug 24</u></p><p><span style="background-color: rgb(255, 255, 0);">Upper/Cooler Deck and GDU =0% Completed</span></p><p><span style="background-color: rgb(255, 255, 0);">Main/ Mezzanine Deck&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;=&nbsp;100% Completed&nbsp;(50 out of 50 Completed)</span></p><p><span style="background-color: rgb(255, 255, 0);">Lower Deck&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; = 51% Completed (23 out of 45 completed)</span></p><p><span style="background-color: rgb(255, 255, 0);">Sea Deck&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; =&nbsp;0% Completed</span></p><p><span style="background-color: rgb(255, 255, 0);">Total completed&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; = 52% (73 out of 141)</span></p><p><u style="background-color: rgb(255, 255, 0);">History:</u></p><p><u style="background-color: rgb(255, 255, 0);">29 Aug 24_</u></p><p><span style="background-color: rgb(255, 255, 0);">Upper/Cooler Deck and GDU =0% Completed</span></p><p><span style="background-color: rgb(255, 255, 0);">Main/ Mezzanine Deck&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;=&nbsp;70% Completed&nbsp;(35 out of 50 Completed)</span></p><p><span style="background-color: rgb(255, 255, 0);">Lower Deck&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;=&nbsp;0% Completed</span></p><p><span style="background-color: rgb(255, 255, 0);">Sea Deck&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; =&nbsp;0% Completed</span></p><p><span style="background-color: rgb(255, 255, 0);">Total completed&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; =&nbsp;25% (35 out of 141)</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-31_12M PM Topside gas detector GDF and GDFR', '2024-08-31 15:37:23', '2024-08-31 19:06:58', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
