-- Inserting report ID 33327
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S level transmitter malfunction', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-08-31', '<p><b><u>Problem:</u></b></p><p>- Level transmitter (LT-41009) at inlet separator malfunction.</p><p><b><u>Found:</u></b><br>- Level transmitter shows reading (-1.57%) when the seperator level is (19%).</p><p><b><u>Action:</u></b></p><p>- Saved the config from the old transmitter.</p><p>- Isolated the transmitter power&nbsp; and replaced the transmitter with new spare.</p><p>- De-isolated the power and send the config to new transmitter.</p><p>- The new transmitter reading still shows (-1.57%).</p><p>- Fulshed and cleaned the level transmitter column.</p><p>- But the reading still freezed at (-1.57%).</p><p><b><u>Note:</u></b></p><p>- Probe resistance = 0.96 Mohm</p><p><b><u>Plan:</u></b></p><p>- Will clean the level transmitter probe by removing the flange.</p><p><b><u style="background-color: rgb(255, 255, 0);">History:</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">26 Aug 2024</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Problem :&nbsp;T/S level transmitter abnormal reading. As per CCR information, there were some spikes on&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Found&nbsp; &nbsp; : :LT-41009 is reading normal when we found.</span></p><p><span style="background-color: rgb(255, 255, 0);">Action&nbsp; &nbsp; : Simulate the transmitter by HART (0-2000 mm) and monitor with milli amp clamp meter.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found CCR and local transmitter are same as per simulated value.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Cleaned the sensor probe of guided wave level transmitter.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Flushed the chamber with the water.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Function test with CCR and it is working properly (Under Monitoring).</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Note : Found LT''s Column drain ball valve is passing. Found LT''s Column drain ball valve gasket is not fitted and we fitted with new gasket.</span></p><p><span style="background-color: rgb(255, 255, 0);">Gasket size : SPW 3/4" 300#</span></p><p><span style="background-color: rgb(255, 255, 0);">LT column tag no, is mismatched LT 41009 and LT41008. Need to swap tags.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-08-31_LT-41009, TS spike alarm messages come to CCR', '2024-08-31 15:38:15', '2024-08-31 19:24:18', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LT-41009', 'ZTK-LT-41009', 'LT on V-4100 to Control LV-41009', NULL, NULL, 'LT on V-4100 to Control LV-41009', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zarni', NULL, 'EXTERNAL', '2024-08-31 15:38:15', '2024-08-31 19:24:18', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-08-31 15:38:15', '2024-08-31 19:24:18', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

