BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Keep hot spare PCV', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-01', '<p><b><u>Action:</u></b></p><p>- Fixed the PCV-66502 and PCV-66602 leak point by welder.</p><p>- Cleaned the internal parts and re-assembled the PCV.</p><p>- Keep the hot spare PCV (3Ea) at safety store (E3).</p><p><b><u style="background-color: rgb(255, 255, 0);">History:</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">24 Aug 2024</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Action: Check the leak point of the PCV-66502 by opening inlet ball valve (BV-1)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found the leakage (two points) at the body of PCV.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Remove the PCV and disassemble the PCV at workshop.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Request the mechanic team to weld the leak points.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found 1 new PCV in the safety store. Install new PCV at local. (Adjust PCV pressure at 6.2 bar)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Perform leak test after installation. There is no leak and unit is back to normal.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: After completed welding, will keep the old PCV as a hot spare.</span></p>', '<p>\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-01_PCV-66502 &amp; 66602, Water maker PCV hot spare<br></p>', '2024-09-01 15:31:10', '2024-09-01 18:40:30', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PCV-66502', 'ZTK-PCV-66502', 'Press Regulator for Fresh Water Inlet', NULL, NULL, 'Press Regulator for Fresh Water Inlet', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
