-- Inserting report ID 33334
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify lifeboat no.3 Davit motor low insulation', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-09-01', '<p><b><u>Action</u></b></p><p>-Check the motor heater load current (0.3A).</p><p>-Isolate the power supply and check the motor winding insulation resistance and winding resistance <span style="background-color: rgb(255, 255, 0);">without disconnecting supply cable</span>.</p><p>-Winding insulation resistance is following as; U+E=7.5 Mohm, V+E=7.4 Mohm and W+E=7.2 Mohm.</p><p>-Winding resistance is following as; U1U2=224.1 mohm, V1V2=223.1 mohm and W1W2=223.8 mohm.</p><p><br></p><p>Plan: Continue to check the winding insulation resistance as per plan.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History: 30-08-2024</span><br></p><p><span style="background-color: rgb(255, 255, 0);">Problem: Lifeboat no.3 davit motor was insulation low.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found: Motor heaters power cables was isolated.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Davit motor local control panel was corroded sign due to water ingress at long time ago.&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Measured the winding resistance, insulation resistance and microohm for davit motor and motor heater.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Before removed the main incoming and heaters power cables, results are follows</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Microohm&nbsp;resistance for motor&nbsp;<a href="winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-W1:223.0mOhm">winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-</a>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<a href="winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-W1:223.0mOhm">W1:223.0mOhm</a></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Resistance for motor winding:<a href="u1-v1:0.6Ohm,U1-V1:0.6Ohm,V1-W1:0.5mOhm">U1-V1:0.6Ohm,U1-V1:0.6Ohm,V1-W1:0.5mOhm</a><a href="winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-W1:223.0mOhm"></a></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Insulation resistance for motor&nbsp;<a href="winding:U1:0.02MOhm,V1:0.02MOhm,W1:0.02MOhm">winding:U1:0.02MOhm,V1:0.02MOhm,W1:0.02MOhm</a></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Resistance for motor heaters: N<a href="no.1:45.0Ohm">o.1:45.0Ohm</a>,&nbsp;<a href="no.2:45.0Ohm">No.2:45.0Ohm</a>&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Insulation resistance for motor&nbsp;<a href="heaters:no.1:0.09MOhm,">heaters:No.1:0.09MOhm,</a>&nbsp;<a href="no.2:0.09Mohm">No.2:0.09Mohm</a><a href="no.2:0.09Mohm"></a></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; After&nbsp;removed the main incoming and heaters power cables, results are follows</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Microohm&nbsp;resistance for motor&nbsp;<a href="winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-W1:223.0mOhm">winding:U1-V1:334.5mOhm,U1-V1:333.4mOhm,V1-</a>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<a href="winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-W1:223.0mOhm">W1:333.4mOhm</a></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Resistance for motor winding:<a href="u1-v1:0.6Ohm,U1-V1:0.6Ohm,V1-W1:0.5mOhm">U1-V1:0.6Ohm,U1-V1:0.6Ohm,V1-W1:0.5mOhm</a><a href="winding:U1-V1:222.6mOhm,U1-V1:1822.9mOhm,V1-W1:223.0mOhm"></a></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Insulation resistance for motor&nbsp;<a href="winding:U1:0.02MOhm,V1:0.02MOhm,W1:0.02MOhm">winding:U1:0.02MOhm,V1:0.02MOhm,W1:0.02MOhm</a></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Resistance for motor heaters: N<a href="no.1:45.0Ohm">o.1:1.372kOhm</a>, No.2:1.375kOhm</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Insulation resistance for motor heaters: No.<a href="heaters:no.1:0.09MOhm,">1:23.7MOhm,</a>&nbsp;<a href="no.2:0.09Mohm">No.2:23.2Mohm</a></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; After measured the motor heater, replaced the heater terminal block and installed the power cables &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;for heater and measured the voltage and ampere are 233.4VAc and 0.2A.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Covered the davit motor local control panel and motor junction box with Denso tape for protect &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;water ingress.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Under monitoring the motor heater and will measure the motor insulation again on next days.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Note: Isolated the motor thermostat cables due to replace for motor heater terminal block which used from &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;the motor thermostat terminal block.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-01_SC-7730, To verify davit motor for life boat No.3', '2024-09-01 15:39:02', '2024-09-09 07:33:28', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HPU-7730', 'ZTK-HPU-7730', 'Hydr Power Unit for Davit Life Boat No.3', NULL, NULL, 'Hydr Power Unit for Davit Life Boat No.3', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SC-7730', 'ZTK-SC-7730', 'Free Fall Life Boat No.3 Main Deck', NULL, NULL, 'Free Fall Life Boat No.3 Main Deck', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Peter', NULL, 'EXTERNAL', '2024-09-01 15:39:02', '2024-09-09 07:33:28', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Benjamin', NULL, 'EXTERNAL', '2024-09-01 15:39:02', '2024-09-09 07:33:28', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation');
