  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1YPM on EDG-7200 ', 'Electrical & Instrument', 'PM ', 'In Progress', '2024-09-02', '<p>Action : Perform&nbsp;1YPM at EDG-7200 Emergency diesel generator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and tightened the motor cable terminations and junction boxes.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and recorded the batteries voltage and internal resistance.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and recorded the motor insulation and resistance tests of the following unit;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Fuel Cooler Ventilation Motor</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Preheating Unit</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Pre priming pump</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Hydraulic starter pump</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Generator cooling fan motor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - 50% completed. Job is in progress.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">Note </span>: Found that W2 terminal of hydraulic starter pump motor was broken.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Insulation resistance of preheating unit is about 0.22Mohm.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-02_EDG-7200, 1Y PM_EL EDG-7200 Emergency Diesel Gen', '2024-09-02 15:01:16', '2024-09-02 18:28:45', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
