-- Inserting report ID 33343
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 4KPM and crank soak wash ', 'Mechanic', 'PM ', 'Completed', '2024-09-02', '<div>Perform crank soak wash</div><div><br></div><div>- Open air inlet duct covers both sides.</div><div>- Open IGV cover.</div><div>- Disconnect Gas fuel line.</div><div>- Disconnect spark plug cable time.</div><div>- Disconnect drain line ( Air inlet Phenom, Combustion, Exhaust).</div><div>- Disconnect PCD line both side and plug.</div><div>- Disconnect liquid fuel line (Diesel).</div><div>- Disconnect all atomizing line at torch.</div><div>- Disconnect gas and liquid fuel manifold drain line.</div><div>- Disconnect PCD purging line.</div><div>- Connect air supply to bearing#1 and maintain pressure 2 bars.</div><div>- Fill cleaning product ZOK/De-ionic water 5/25 Gal into mobile injection tank.</div><div>- Spray cleaning product while engine NGP reach to 21 %.</div><div>- Collect sample for visual inspection.</div><div>- Wait for 30 min then continue process washing.</div><div>- Dry crank 5 min for 1 time.</div><div>- Re-assembly piping.</div><div>- Replace ignition plug.</div><div>- Housekeeping work area.</div><div>Spray corrosion inhibitor and exercise inlet guide vanes</div><div>Test run and internal check leak<br></div>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\72 MAIN &amp; VITAL POWERr GENERATION\\7220 Gas Turbine Generator No. 2\\GTG-7220\\2024\\2024-09-02 Perform 4K PM and crank soak wash">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\72 MAIN &amp; VITAL POWERr GENERATION\\7220 Gas Turbine Generator No. 2\\GTG-7220\\2024\\2024-09-02 Perform 4K PM and crank soak wash</a><br></p>', '2024-09-02 17:39:16', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTG-7220', 'ZTK-GTG-7220', 'Gas Turbine Generator Package No.2', NULL, NULL, 'Gas Turbine Generator Package No.2', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
