  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace defective bearing at PMA HVAC', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-02', '<div class="subtext"><p><b ><u>Problem:</u></b></p><p>- PMA FCU unit A (B-7880A) is not available due to bearing damaged.</p><p><u><b>Action:</b></u><br></p><p>- Removed the belt and bearing support from blower.</p><p>- Removed the shaft and bring to workshop.</p><p>- Removed the pulley from the shaft.</p><p>- Removed the defective bearings by using hydraulic press machine.</p><p>- Removed the rubber bushing between bearings and bearing support and installed at the new bearing.</p><p>- Installed the new bearing (SKF YET205) and pulley at the shaft.</p><p><u><b>Plan:</b></u></p><p>- Will replace the shaft at the PMA blower skid.</p><p>- Will perform function test.</p></div>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-02_B-7880A, To replace defective bearing at PMA', '2024-09-02 18:14:18', '2024-09-02 18:26:01', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
