-- Inserting report ID 33345
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Resume platform power, ESDV force open', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-03', '<p><b><u>Action: </u></b></p><p>Performed platform power resume and ESDV force open.</p><p>- Performed ESDV force open for ESDV-03221 and ESDV-03215.&nbsp;</p><p>- Both pilot manifold spools stuck and cannot force open from pilot manifold vent.</p><p>- Bypass the pilot manifold and inject N2 from downstream of pilot manifold to force open on both ESDV-03221 and ESDV-03215.&nbsp;</p><p>- Checked all the as found breaker condition.&nbsp;</p><p>- Found both battery breakers and RCB breaker for platform DC power are tripped.&nbsp;</p><p>- Checked K4 relay that tripped RCB breaker and shunt trip coil, found all have no abnormal condition.</p><p>- Replaced the K4 relay with new spare.</p><p>- Battery bank A breaker inside PJB-353 cannot be reset. Found that the internal mechanism of breaker is stuck. Fixed the breaker internal mechanism and it can functioning properly.</p><p>- Replaced the fuse with new spare for XS-03997A/B/C.</p><p>- Replaced DO card (NODE 3 - SLOT7) with new spare.</p><p>- Replaced both K3 relays inside battery breaker junction boxes&nbsp; A&amp;B.&nbsp;</p><p>- Replaced new UVT with base and set the same config setting as per original one.</p><p>- Resume the platform power by bypassing KOS and run all TEGs. (TEG-J &amp; I cannot be run and suspect that TEG-H transducer is malfunction)</p><p>- Removed all force open and normalize ESDV-03221 and ESDV-03215.&nbsp;</p><p>- Now the platform power system is back to normal.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-03_WP-03, Plaform power resume and investigation, ESDV03251 and 03221 force open', '2024-09-03 14:35:52', '2024-09-04 00:25:15', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP03', 'ZTK-WP03', 'Zawtika Wellhead Platform 03', NULL, NULL, 'Zawtika Wellhead Platform 03', 'WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zarni', NULL, 'EXTERNAL', '2024-09-03 14:35:52', '2024-09-04 00:25:15', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-09-03 14:35:52', '2024-09-04 00:25:15', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
