  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace defective bearing at PMA HVAC', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-04', '<p><b><u>Action:</u></b></p><p>- Installed the shaft at the blower skid.</p><p>- Performed alignment for bearing (DE/ NDE) and blower.</p><p>- Installed bearing support.</p><p>- Performed blower and motor pulley alignment by using laser alignment tool.</p><p>- Installed belts (SPZ 1400) and perform belt tension (250N).<br></p><p>- Performed function test and B-7880A can run properly.</p><p><b><u style="background-color: rgb(255, 255, 0);">History:</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">2 Sep 2024</u></b></p><p><u><b style="background-color: rgb(255, 255, 0);">Problem:</b></u></p><p><span style="background-color: rgb(255, 255, 0);">- PMA FCU unit A (B-7880A) is not available due to bearing damaged.</span></p><p><span style="background-color: rgb(255, 255, 0);"><u>Action:</u><br></span></p><p><span style="background-color: rgb(255, 255, 0);">- Removed the belt and bearing support from blower.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Removed the shaft and bring to workshop.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Removed the pulley from the shaft.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Removed the defective bearings by using hydraulic press machine.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Removed the rubber bushing between bearings and bearing support and installed at the new bearing.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Installed the new bearing (SKF YET205) and pulley at the shaft.</span></p><p><u style="background-color: rgb(255, 255, 0);">Plan:</u></p><p><span style="background-color: rgb(255, 255, 0);">- Will replace the shaft at the PMA blower skid.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Will perform function test.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-04_B-7880A, Replaced defective bearing with new spare for PMA HVAC', '2024-09-04 15:07:22', '2024-09-08 15:59:24', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
