  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Benjamin', NULL, 'EXTERNAL', '2024-09-04 15:07:22', '2024-09-08 15:59:24', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
