-- Inserting report ID 33351
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify FWP no.1 not auto start', 'Electrical & Instrument', 'OTH ', 'Completed', '2024-09-04', '<p><b><u>Problem:</u></b></p><p>- Fire water pump No.1 P-6700 not auto start with low ring main pressure.</p><p><b><u>Action:</u></b></p><p>- Function test by reducing one of the pressure transmitter pressure (1 out of 2) and found that fire water pump No.1 start automatically when the ring main pressure low.</p><p>- Adjust PCV-67054 from 12.6 Barg to 14 Barg as per CCR request.</p><p><b><u>Note:</u></b></p><p>- The firewater ring main pressure will be maintained at 11 Barg by continuously running jockey pump. Pressure alarm low is set at 10.3 Barg. The preimary fire water pump will start, if firewater ring main pressure falls below 8.5 Barg. If the ring main pressure does not rise to 8.5 Barg within 15 second, second fire water pump will start. If ring main pressure has still not reach 8.5 Barg in 30 second, third fire water pump will start.</p>', NULL, '2024-09-04 15:34:58', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6700-PCKG', 'ZTK-P-6700-PCKG', 'Fire Water Pump No.1', NULL, NULL, 'Fire Water Pump No.1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PCV-67054', 'ZTK-PCV-67054', 'Press Regulator,Fire Water to Overboard', NULL, NULL, 'Press Regulator,Fire Water to Overboard', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zarni', NULL, 'EXTERNAL', '2024-09-04 15:34:58', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Benjamin', NULL, 'EXTERNAL', '2024-09-04 15:34:58', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL);
END $$;

