  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support Mech for flushing condensate line GDU-4700', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-04', '<p><b><u>Activity:</u></b></p><p>Support Mechanic team for flushing condensate line GDU-4700&nbsp;</p><p><b><u>Action:</u></b></p><p>- Remove the flow sensor element and check the internal parts &amp; circuit</p><p>- Check and clean the condensate flow line between the flow control valve and shutdown valve</p><p>- Check and clean the check valve of condensate line E-4750 and E-4752</p><p>- Remove the fire tube burner of the condensate line of E-4750 and E-4752</p><p>- Take the photo inside the ball valve after cleaning the surface&nbsp;</p><p>- Connect back to normal flange and fire tube of the whole condensate line</p><p>- Check and inspect along the connection piont and gasket of the condensate line</p><p>- Ready for the leak test and running test with condenste fuel of GDU-4700&nbsp;</p><p><b><u>Job Status:</u></b></p><p>In Progress</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-04_Support Mech team for flushing condensate line of GDU train 1">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-04_Support Mech team for flushing condensate line of GDU train 1</a><br></p>', '2024-09-04 15:58:57', '2024-09-04 19:30:23', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
