-- Inserting report ID 33355
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To reinstall HI pump B and function test', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-04', '<p>Action: Reinstalled HI pump B that was function tested at workshop. </p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed function test and found the discharge pressure was not built up. </p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked all the line up and bleed off the air. Pump stroke well during bleed off but still no output when normalize. </p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found some instrument air leak at relay. Remove and fix the leak.&nbsp;</p><p>For pump A, found the pump is functioning normal. Will run continuously with line up and monitor condition before removing.&nbsp;</p><p>Plan: Will install back the relay and perform function test after it.</p><p><br></p><p><br></p><p><u>&nbsp;History</u><br class="Apple-interchange-newline"></p><p>-Checked all the line up for the HI pump A/B and C (P-1594A/B/C).&nbsp;</p><p>-Found pump A can be run. But the pump out put stopped (no flow) after half an hour run.</p><p>-Bleed off the suction line from bleed port, found pump has flow.</p><p>-But it happened again no flow after running for half an hour. (Pump A is also not available)</p><p>-For pump B and C, there have no flow and cannot build up the pressure.</p><p></p><p>-Removed both pumps to be overhauled at ZPQ.</p><p>&nbsp;The job is still in progress.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-04_HI pump,To reinstall HI pump B and function test', '2024-09-04 16:09:32', '2024-09-05 07:19:56', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP15', 'ZTK-WP15', 'Zawtika Wellhead Platform 15', NULL, NULL, 'Zawtika Wellhead Platform 15', 'WP15', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Grayson', NULL, 'EXTERNAL', '2024-09-04 16:09:32', '2024-09-05 07:19:56', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

