-- Inserting report ID 33357
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S level transmitter malfunction', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-05', '<p><b><u>Action:</u></b></p><p>- Removed the level transmitter (LT-41009) sensor probe from the column.</p><p>- Cleaned the sensor probe and cleaned the column by filling with Oiler-1.</p><p>- Replaced the remote connection cable with new spare.</p><p>- Installed back the sensor probe to the column.</p><p>- Performed function test with CCR and found working properly.</p><p>- Performed process deisolation and leak checked.</p><p>- No leak found and the LT-41009 reading show 17.78%. (LT-41008_18.15%)</p><p><b><u>Note:</u></b></p><p>- Sensor probe flange - 4" #300RF</p><p>- Nut size - 32mm (8Eea)</p><p>- Torque - 185 Nm</p><p><b><u style="background-color: rgb(255, 255, 0);">History:</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">31 Aug 24</u></b></p><p><b ><u style="background-color: rgb(255, 255, 0);">Problem:</u></b></p><p><span style="background-color: rgb(255, 255, 0);">- Level transmitter (LT-41009) at inlet separator malfunction.</span></p><p><span style="background-color: rgb(255, 255, 0);"><u>Found:</u><br>- Level transmitter shows reading (-1.57%) when the seperator level is (19%).</span></p><p><u style="background-color: rgb(255, 255, 0);">Action:</u></p><p><span style="background-color: rgb(255, 255, 0);">- Saved the config from the old transmitter.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Isolated the transmitter power&nbsp; and replaced the transmitter with new spare.</span></p><p><span style="background-color: rgb(255, 255, 0);">- De-isolated the power and send the config to new transmitter.</span></p><p><span style="background-color: rgb(255, 255, 0);">- The new transmitter reading still shows (-1.57%).</span></p><p><span style="background-color: rgb(255, 255, 0);">- Fulshed and cleaned the level transmitter column.</span></p><p><span style="background-color: rgb(255, 255, 0);">- But the reading still freezed at (-1.57%).</span></p><p><u style="background-color: rgb(255, 255, 0);">Note:</u></p><p><span style="background-color: rgb(255, 255, 0);">- Probe resistance = 0.96 Mohm</span></p><p><u style="background-color: rgb(255, 255, 0);">Plan:</u></p><p><span style="background-color: rgb(255, 255, 0);">- Will clean the level transmitter probe by removing the flange.</span></p><p><u style="background-color: rgb(255, 255, 0);">History:</u></p><p><u style="background-color: rgb(255, 255, 0);">26 Aug 2024</u></p><p><span style="background-color: rgb(255, 255, 0);">Problem :&nbsp;T/S level transmitter abnormal reading. As per CCR information, there were some spikes on&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Found&nbsp; &nbsp; : :LT-41009 is reading normal when we found.</span></p><p><span style="background-color: rgb(255, 255, 0);">Action&nbsp; &nbsp; : Simulate the transmitter by HART (0-2000 mm) and monitor with milli amp clamp meter.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found CCR and local transmitter are same as per simulated value.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Cleaned the sensor probe of guided wave level transmitter.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Flushed the chamber with the water.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Function test with CCR and it is working properly (Under Monitoring).</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Note : Found LT''s Column drain ball valve is passing. Found LT''s Column drain ball valve gasket is not fitted and we fitted with new gasket.</span></p><p><span style="background-color: rgb(255, 255, 0);">Gasket size : SPW 3/4" 300#</span></p><p><span style="background-color: rgb(255, 255, 0);">LT column tag no, is mismatched LT 41009 and LT41008. Need to swap tags.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-05_LT-41009, TS level transmitter malfunction', '2024-09-05 15:13:08', '2024-09-09 07:32:30', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LT-41009', 'ZTK-LT-41009', 'LT on V-4100 to Control LV-41009', NULL, NULL, 'LT on V-4100 to Control LV-41009', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zarni', NULL, 'EXTERNAL', '2024-09-05 15:13:08', '2024-09-09 07:32:30', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Grayson', NULL, 'EXTERNAL', '2024-09-05 15:13:08', '2024-09-09 07:32:30', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Benjamin', NULL, 'EXTERNAL', '2024-09-05 15:13:08', '2024-09-09 07:32:30', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation');
