-- Inserting report ID 33358
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1Y PM on Emergency Diesel Generator', 'Electrical & Instrument', 'PM ', 'In Progress', '2024-09-05', '<p>Action :&nbsp;Performed 1Y PM on EDG 7200 emergency diesel generator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Measured and recorded main stator windings insulation and winding resistance.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked the polarization index for stator winding at 500V.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<span style="background-color: rgb(255, 255, 0);">&nbsp;R at 10 min = 635 Mohm , R at 1 min = 497 Mohm, PI = 1.27</span></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked the rectifier diode voltage and resistances.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and tightened terminal connections inside AVR (K3) junction box.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Job is in progress.&nbsp;</p><p>Plan: To check main rotor and exciter winding.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History : 02 Sep 2024</span></p><p>Action: Perform&nbsp;1YPM at EDG-7200 Emergency diesel generator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and tightened the motor cable terminations and junction boxes.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and recorded the batteries voltage and internal resistance.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and recorded the motor insulation and resistance tests of the following unit;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Fuel Cooler Ventilation Motor</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Preheating Unit</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Pre priming pump</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Hydraulic starter pump</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Generator cooling fan motor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - 50% completed. Job is in progress.</p><p>Note&nbsp;: Found that W2 terminal of hydraulic starter pump motor was broken.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Insulation resistance of preheating unit is about 0.22Mohm.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-05_EDG-7200, 1YPM Emergency Diesel Generator', '2024-09-05 15:28:50', '2024-09-08 14:47:47', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EDG-7200', 'ZTK-EDG-7200', 'Emergency Diesel Generator Package', NULL, NULL, 'Emergency Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-09-05 15:28:50', '2024-09-08 14:47:47', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han.', NULL, 'EXTERNAL', '2024-09-05 15:28:50', '2024-09-08 14:47:47', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

-- Inserting report ID 33359
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S PSH-73601 alarm High and shutdown sewage unit', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-05', '<p><b><u>Activity:</u></b></p><p>T/S pressure switch alarm at HMI and cannot reset at sewage unit</p><p><b><u>Action:</u></b></p><p>- Check the pressure switch alarm for HMI at sewage unit</p><p>-<b> As Found</b>: PSH-73601 High Pressure Alarm and Shutdown</p><p>- Check the wire connection and fuse of the pressure switch</p><p>- PSH-73601 shows High (Above-1" Water Column &gt; 30 sec)</p><p>- Remove the vent line and reset the alarm at HMI</p><p>- Calibrate the pressure switch PSH-73601 with fluke automatic pressure calibrator</p><p>- Flush the pressure switch tubing, found that <span style="background-color: rgb(255, 255, 0);">impurities &amp; water block</span> the high vent sensing line</p><p>- Check and measure the parameter of the pressure switch and connection terminal.</p><p><b>Remark</b>: PSH-73601 Remote Mounted <span style="background-color: rgb(255, 255, 0);">1/2" SS tubing</span>&nbsp;connection is <span style="background-color: rgb(255, 255, 0);">different with manual drawing</span>.&nbsp;</p><p>- Perform de-isolation for both process and electrical of the sewage unit</p><p>- Test run the sewage unit and keep monitior the condition. (No High Alarm PSH-73601)</p><p><b><u>Job Status:</u></b></p><p>- Completed.</p>', '<p><a href="U:\\01 E&amp;I\\Activity Photos\\2024-09-05_TS pressure switch alarm at HMI and cannot reset at sewage unit">U:\\01 E&amp;I\\Activity Photos\\2024-09-05_TS pressure switch alarm at HMI and cannot reset at sewage unit</a><br></p>', '2024-09-05 15:32:22', '2024-09-08 15:59:06', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-7300', 'ZTK-X-7300', 'Sewage Treatment Package', NULL, NULL, 'Sewage Treatment Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-09-05 15:32:22', '2024-09-08 15:59:06', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2024-09-05 15:32:22', '2024-09-08 15:59:06', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
END $$;

