-- Inserting report ID 33374
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1Y PM on Emergency Diesel Generator', 'Electrical & Instrument', 'PM ', 'Completed', '2024-09-08', '<p>Action : Performed 1Y PM on EDG 7200 emergency diesel generator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and recorded the exciter winding insulation and resistance.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked at the package as per on-load test procedure before test run.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Normalized the power isolation and CO2 system inhibit.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Performed on-load test with electric mode for 1hr and test run by hydraulic with 10 minutes. (No any abnormal found during test run)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- After engine stop, low coolant level charge air alarm pop up.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Reset the alarm by disconnecting sensor cable and probe then connect back.&nbsp; Alarm was cleared.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Now the unit is back to normal and ready to start.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">History : 05 Sep 2024</span></p><p>Action :&nbsp;Performed 1Y PM on EDG 7200 emergency diesel generator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Measured and recorded main stator windings insulation and winding resistance.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked the polarization index for stator winding at 500V.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;R at 10 min = 635 Mohm , R at 1 min = 497 Mohm, PI = 1.27</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked the rectifier diode voltage and resistances.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and tightened terminal connections inside AVR (K3) junction box.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Job is in progress.&nbsp;</p><p>Plan: To check main rotor and exciter winding.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History : 02 Sep 2024</span></p><p>Action: Perform&nbsp;1YPM at EDG-7200 Emergency diesel generator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and tightened the motor cable terminations and junction boxes.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and recorded the batteries voltage and internal resistance.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and recorded the motor insulation and resistance tests of the following unit;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Fuel Cooler Ventilation Motor</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Preheating Unit</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Pre priming pump</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Hydraulic starter pump</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Generator cooling fan motor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - 50% completed. Job is in progress.</p><p>Note&nbsp;: Found that W2 terminal of hydraulic starter pump motor was broken.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Insulation resistance of preheating unit is about 0.22Mohm.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-08_EDG-7200, 1YPM Emergency Diesel Generator and on-load test', '2024-09-08 14:59:25', '2024-09-08 18:21:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EDG-7200', 'ZTK-EDG-7200', 'Emergency Diesel Generator Package', NULL, NULL, 'Emergency Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-09-08 14:59:25', '2024-09-08 18:21:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han.', NULL, 'EXTERNAL', '2024-09-08 14:59:25', '2024-09-08 18:21:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

