-- Inserting report ID 33378
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix water leak from the washing machine', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-08', '<p><b><u>Problem:</u></b></p><p>- Water leak from the PRIMUS washing machine (LD01A).</p><p><b><u>Action:</u></b></p><p>- Removed the washing machine cover and performed function test.</p><p>- Found water leak from the drain pipe connection joint.</p><p>- Removed and checked the drain pipe connection joint.</p><p>- Found the connection Tee joint is cracked.</p><p>- Fixed the cracked joint by using RTV at workshop.</p><p>- Reinstalled the drained pipe connection joint and function test run the machine.</p><p>- Now the machine has no more water leak.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-08_LD01A, Fixed water leak from the washing machine', '2024-09-08 15:41:07', '2024-09-08 18:07:13', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
