  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zarni', NULL, 'EXTERNAL', '2024-09-08 15:41:07', '2024-09-08 18:07:13', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation');
