-- Inserting report ID 33381
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform pyroban deep cleaning', 'Mechanic', 'CM ', 'Completed', '2024-09-09', '<p><b>8-Sep-2024</b></p><p>Problem : Engine exhaust temp high.</p><p>Action&nbsp; &nbsp; : <b>Deep Cleaning Pyroban (Exhaust cooler)</b></p><p><b>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </b>(1) Install lifting gear as per lifting plan.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Remove the flexible bellow, connection bolts and piping.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Remove and lower down the exhaust cooler upper part.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (4) Remove the flame arrestor (3 EA) one by one.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (5) Drain out coolant from exhaust cooler.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (6) Clean the exhaust cooler upper part and flame arrestor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (7) Clean fin-tube exhuast cooler part with ZOK (2 times) and water (3 times).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (8) Perform housekeeping the work area.</p><p><br></p><p><b><u>9-Sep-2024&nbsp;</u>&nbsp;</b></p><p>&nbsp; &nbsp; -&nbsp; Clean fin-tube exhuast cooler lower part with oiler one (2 times) and water (3 times) and air (1 times).</p><p>&nbsp; &nbsp; -&nbsp; Apply belzona coating at some pitting points of exhaust cooler and flame arrestor area.</p><p>&nbsp; &nbsp; -&nbsp; Install back exhaust cooler upper part and install turbo charger flexible bellow.</p><p>&nbsp; &nbsp; -&nbsp; Connect cooling line of exhaust cooler.</p><p>&nbsp; &nbsp; -&nbsp; Install back flame arrestor to the location.</p><p>&nbsp; &nbsp; -&nbsp; Fill up coolant to coolant expension tank of exhaust cooler.</p><p><br></p><p><b><u>10-Sep-2024&nbsp;</u></b></p><p>&nbsp; &nbsp; - Test run 30 minutes and monitor exhaust temperature.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-Start temp 27''C</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-10 min after 120"C</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-20 min after 126.5''C</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-30 min after 129.8''C</p><p>&nbsp; &nbsp; - Check any leakage around exhaust cooler.</p><p>&nbsp; &nbsp; -Cleaned around the area and housekeeping.</p><p>&nbsp; &nbsp;</p><p>&nbsp; &nbsp;&nbsp;</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\P-6700 Diesel Fire Water Pump Package No. 1\\2024\\2024-09-08 Perform deep clean exhaust cooler pyroban">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\P-6700 Diesel Fire Water Pump Package No. 1\\2024\\2024-09-08 Perform deep clean exhaust cooler pyroban</a><br></p>', '2024-09-08 18:17:37', '2025-06-22 16:28:37', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Crane', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6700-PCKG', 'ZTK-P-6700-PCKG', 'Fire Water Pump No.1', NULL, NULL, 'Fire Water Pump No.1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Mercelo', NULL, 'EXTERNAL', '2024-09-08 18:17:37', '2025-06-22 16:28:37', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Crane');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jason', NULL, 'EXTERNAL', '2024-09-08 18:17:37', '2025-06-22 16:28:37', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Crane');
