-- Inserting report ID 33389
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support GDU burner start with condensate fuel', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-09', '<p>Action : Support production team to start GDU-4700 with condensate mode.</p><p>- GDU-4700 started with condensate mode and tripped by BALL-47511 pilot A failed.</p><p>- Adjusted PCV-47267 to reduce pressure from 5.7 bar to 5 bar. Adjust atomization air for burner A to 4.8</p><p>and&nbsp; burner B to 4 bar. Test run and trip again by condensate fuel pressure low low.</p><p>- Adjust I/A supply of SDV-47288 from 4.9 bar to 5.3 bar and SDV-47290 5.3 to 4.9 bar.</p><p>- During the fourth attempt of function test, some smoke come out from condensate supply spacer thread</p><p>connection of burner A.</p><p>- Adjust back I/A supply of SDV-47288 from 5.3 to 4.9 bar and SDV-47290 from 4.9 to 5.3 bar. Cleaned the atomization air adjustment needle valve of burner B.</p><p>- Function test again and tripped by BALL-47507 burner A. (Both burner A and B ON for 7 sec and</p><p>mA can detect in multimeter)</p><p>- Test run by bypassing both flame monitors and found that burner A and B ON about 8 sec and failed.</p><p>- Tried test run for three times by flame monitor signal bypass and results are the same.</p><p>- Restarted GDU-4700 with gas mode and both burners can function normally. </p><p>(E-4750=16.88 micro A, E4752=17.33 micro A)</p><p><br></p><p><u style="background-color: rgb(255, 255, 0);">History</u></p><p><span style="background-color: rgb(255, 255, 0);">Automation change set point for&nbsp; GDU Train-1 to be run with condensate fuel</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Changed Leak Test SP and LL setpoints for PT-47505, PT-47509 and PT-47552 as per request.</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Leak Test_SP as found = 0.005&nbsp; &nbsp; as left = 0.01</span></p><p><span style="background-color: rgb(255, 255, 0);">:- PT-47505 LL as found = 2.65&nbsp; &nbsp; as left = 1</span></p><p><span style="background-color: rgb(255, 255, 0);">:- PT-47509 LL as found = 5.5&nbsp; &nbsp; &nbsp; as left = 3</span></p><p><span style="background-color: rgb(255, 255, 0);">:- PT-47552 LL as found = 0.4&nbsp; &nbsp; &nbsp;as left = 0.2</span></p><p><span style="background-color: rgb(255, 255, 0);">Pilot started and the ionization current and flame condition are normal( around 13 micro A for both pilot) with healthy status.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Main burner started with condensate fuel. Fail with atomization pressure high on first attempt.</span></p><p><span style="background-color: rgb(255, 255, 0);">When second time started the pressure for condensate was low. The burner fail to start.</span></p><p><span style="background-color: rgb(255, 255, 0);">Bypass the flow transmitter with tubing line and will restart the burner. The job is still in progress.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">- Check I/A supply of SDV-47285/ 47286 and BDV-47287 (Pilot Line)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Check I/A supply of SDV-47288/ 47290 (Condensate Line)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Perform function test open and close for SDV-47285, SDV-47286 (Opening /Closing Time= 1 sec)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Perform function test open and close for BDV-47287 (Opening /Closing Time= 1 sec)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Adjust the flow rate fuel gas line for E-4750 &amp; E-4752 (0.8 to 0.75 bar)&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">- Adjust the I/A air flow rate SDV-47233 ( 5.2 bar to 4.9 bar)&nbsp; &nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">- Adjust the I/A air flow rate SDV-47290 (4.9 bar to 5.3 bar)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Start the pilot tube E-4750 and E-4752 without burner running</span></p><p><span style="background-color: rgb(255, 255, 0);">- As Found: E-4750 ionization current is healthy, but E-4752 ionization current is unhealthy</span></p><p><span style="background-color: rgb(255, 255, 0);">- E-4752 ionization current is about 4.08 - 4.35 micro Amp in local</span></p><p><span style="background-color: rgb(255, 255, 0);">- E-4752 ionization current is about 1.08 - 1.39 micro Amp in CCR</span></p><p><span style="background-color: rgb(255, 255, 0);">- Adjust the flow rate fuel gas line for E-4750 &amp; E-4752 (0.75 to 0.8 bar) and adjust air flow at E-4752.</span></p><p><span style="background-color: rgb(255, 255, 0);">- E-4752 ionization current is about 14.73 - 16.08 micro Amp in local</span></p><p><span style="background-color: rgb(255, 255, 0);">- Operation team test run the condensate fuel line without any junk&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">- GDU Train-1 is tripped by flame burner failed and no pressure build up in condensate fuel line</span></p><p><span style="background-color: rgb(255, 255, 0);">- Replaced the flame monitor module AAC76 for E-4752</span></p><p><span style="background-color: rgb(255, 255, 0);">-Started GDU train 1. Both pilot are working normal. Start main burner with condensate fuel. Tripped with atomization&nbsp; pressure low low ( 5 bar for 4750 and 5.1 bar for 4752). Will adjust the air pressure and will restart burner with condensate.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">-Start burner with condensate, GDU Tripped by both pilot tube E-4750 and E-4752.</span></p><p><span style="background-color: rgb(255, 255, 0);">- E-4752 ionization current is shown unhealthy again.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-09_Support GDU Train-1 with condensate running', '2024-09-09 19:45:37', '2024-09-09 20:01:51', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SK-4700', 'ZTK-SK-4700', 'Glycol Regeneration Package Train 1', NULL, NULL, 'Glycol Regeneration Package Train 1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-09-09 19:45:37', '2024-09-09 20:01:51', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-09-09 19:45:37', '2024-09-09 20:01:51', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

