  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Condition check for FWP air starting solenoid', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-10', '<p><b><u>Problem:</u></b></p><p>- Fire water pump No.1 cranking and fail to start when command start.</p><p><b><u>Found:</u></b></p><p>- Can start the fire water pump wtihout any alarm.</p><p><b><u>Action:</u></b></p><p>- Checked the air starting solenoid (XSV-67002) coil resistance and found normal (283.7 kOhm). (New solenoid = 291.3 kOhm)</p><p>- Checked the fuse for the air starting solenoid. (0.3 Ohm)</p><p>- Tightened the cable terminal for air starting solenoid.</p><p><b><u>Plan:</u></b></p><p>- Will remove air starting solenoid and function test at workshop.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-10_XSV-67002, Condition check for FWP air starting solenoid', '2024-09-10 15:50:26', '2024-09-10 19:57:45', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-XSV-67002', 'ZTK-XSV-67002', 'Air Start Solenoid Valve Control Engine', NULL, NULL, 'Air Start Solenoid Valve Control Engine', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zarni', NULL, 'EXTERNAL', '2024-09-10 15:50:26', '2024-09-10 19:57:45', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
