  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support OGAS team for 1YPM GDU train 2', 'Electrical & Instrument', 'PM ', 'In Progress', '2024-09-10', '<p><b><u>Activity:</u></b></p><p>Support OGAS team for 1 YPM GDU train 2</p><p><b><u>Action:</u></b></p><p>- Assist OGAS team for 1YPM GDU skid train 2.</p><p>- Checked and performed function test PT-48509, PT-48504, PT-48505 and FV-48550.&nbsp;</p><p>- Performed valve function test on SDV-48291, SDV-48285, SDV-48287, SDV-48281, SDV-48282 with CCR. All are functioning properly.</p><p>-&nbsp; The following valves can not perform function test SDV-48286, SDV-48288, SDV-48290 due to mechanical tasks are performing condensate fire burner replacement.&nbsp;</p><p>- Checked blower motors B-4855 A and B-4855B as per job card.</p><p>- Measure ground wire resistance for both blower motors.</p><p>We need to order the spare part for pilot lamp LED (Domo, 230 V) 230VAC power on flame monitor junction box.</p><p><b><u>Note:&nbsp;</u></b></p><p>- SDV48291, replace proximity switch due to open status shows discrepancy.</p><p>- B-4855 B, replace air line tubing.&nbsp; &nbsp;</p><p><b><u>Job Status:</u></b></p><p>- In Progress</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-10_Perform 1 YPM GDU Train 2 with OGAS Team">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-10_Perform 1 YPM GDU Train 2 with OGAS Team</a><br></p>', '2024-09-10 16:02:18', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-TeamLead', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
