-- Inserting report ID 33400
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS AHU blower A unit trip', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-09-11', '<p>Problem: AHU blower A is tripped by earth fault.</p><p>Found: Found that earth fault current is around 150 mA.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Alarm setting is 50 mA with 3s timer.</p><p>Action: Isolated the power supply for AHU blower A.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Measured the insulation resistance between line and ground at MCC-CPP-7870A.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Found that the insulation resistance is &gt;550 MOhm (Between line and ground).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Measured the insulation resistance of motor space heater.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Found that insulation resistance is &gt;220 Mohm. Heater resistance is 830 Ohm</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Opened and checked the local motor junction box inside.( OK )</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Check the resistance of motor winding .</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(U-V= 61.8 mOhm, U-W= 61.8 mOhm and V-W= 61.8 mOhm)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Perform to test run.(OK)</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">Note: B-7840A and B-7840B, Changed the earth fault current alarm set point form 50 to 250 mA for unit availability.&nbsp;</span></p><p><br></p>', NULL, '2024-09-11 13:49:48', '2024-09-11 16:03:53', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-B-7840A', 'ZTK-B-7840A', 'Air Handling Duty Unit on Top Side MD', NULL, NULL, 'Air Handling Duty Unit on Top Side MD', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-09-11 13:49:48', '2024-09-11 16:03:53', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2024-09-11 13:49:48', '2024-09-11 16:03:53', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

-- Inserting report ID 33401
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S GDU train 2 cannot start', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-11', '<p>Problem : GDU train 2 cannot started and tripped by E-4852 pilot flame off alarm.</p><p>Action&nbsp; &nbsp; : Performed test run and checked the condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Found pilot flame is ON and ionization current of E-4852 was low.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Cleaned and adjusted the pilot air adjuster and found that Ionization current of E-4852 built up to around 14 micro Amp.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Started the burners and monitored for both E-4850 and E-4852.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (E-4850=18.55 micro Amp, E-4852 =16.44 micro Amp)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Now the unit is back to normal.</p>', NULL, '2024-09-11 13:55:33', '2025-04-02 14:37:55', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SK-4800', 'ZTK-SK-4800', 'Glycol Regeneration Package Train 2', NULL, NULL, 'Glycol Regeneration Package Train 2', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-09-11 13:55:33', '2025-04-02 14:37:55', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-09-11 13:55:33', '2025-04-02 14:37:55', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
