-- Inserting report ID 33403
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Allen Bradley PLC In-house training day 3', 'Automation', 'OTH ', 'Completed', '2024-09-11', '<p>Action:</p><p>:- Conducted Allen Bradely PLC In-house training day 3 at simulation station.</p><p>:- Explained about RSLogix 5000 Software overview.</p><p>:- Explained and demonstrated about how to create project in RSLogix 5000 Software overview.</p><p>:- Explained and demonstrated about how to check firmware version of Logix controller.</p><p>:- Explained and demonstrated about how to upgrade and downgrade firmware version of Logix controller using Control Flash.</p><p>:- Explained and demonstrated about how to upload and download project.</p><p>:- Explained and demonstrated about how to create simple ladder rungs using XIC, XIO, OTE and Timer.</p><p>:- All attendants performed and create new project according to simulation station hardware installation.</p><p>:- All attendants performed upload and download project.</p><p>:- All attendants performed to create simple ladder logic.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History:</span></p><p><span style="background-color: rgb(255, 255, 0);">Action:</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Conducted Allen Bradely PLC In-house training day 2 at simulation station.</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Explained about RSLinx.</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Demonstrated how to setup engineering laptop IP configuration.</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Demonstrated how to check communication between engineering laptop and logix controller.</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Demonstrated how to check devices name and revision using RSLinx Classic Gateway.</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Demonstrated how to configure and delete RSLinx Drivers.</span></p><p><span style="background-color: rgb(255, 255, 0);">:- All attendents performed the configuration and deletion of their RSLinx Drivers.</span></p><p><span style="background-color: rgb(255, 255, 0);">Next: Conducted Allen Bradely PLC In-house training day 3 at simulation station.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History:</span></p><p><span style="background-color: rgb(255, 255, 0);">Action:&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Conducted&nbsp;Allen Bradely PLC In-house trainging day 1 at simulation station.</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Explained about System Overview of Allen-Bradley PLC.</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Explained about Chassis and the ControlBus Backplane.</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Explained about Power Supplies</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Explained about Logix 5000 Processors</span></p><p><span style="background-color: rgb(255, 255, 0);">:-Explained about Discrete and Analog I/O</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Explained about Communication Bridge Modules</span></p><p><span style="background-color: rgb(255, 255, 0);">:- Explained about Motion Control Modules</span></p><p><span style="background-color: rgb(255, 255, 0);">Next: Conduct Allen Bradely PLC In-house training day 2</span></p>', NULL, '2024-09-11 14:27:39', '2024-09-11 15:32:14', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
