  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS hypochlorite pump shows stop at CCR', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-11', '<p>Activity:&nbsp; &nbsp; TS hypochlorite pump, P-6642A shows STOP at CCR while pump was running at local.</p><p>Action:&nbsp; &nbsp; Performed checking the wiring loop of hypochlorite distribution pump (motor starter panel/MCC-CPP-6642) at local.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Checked the cable terminations and tightened as required. </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp;&nbsp;&nbsp;&nbsp;Found that the fuse/10A in F4 is missing. (Installed back the new 10 fuse)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Checked the cable terminations local control panel/LCP-CPP-6640.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Found that the cable terminations are loosen in the X2 terminal block.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Tightened the loosen cable terminations as required.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Checked all the other cable terminations blocks and tightened as required.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Checked the cable termination in the marshalling cabinet side.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp;Power back and function tested run with CCR and Site Operator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -&nbsp; The unit can run properly and DCS shows Run status during P-6642A running.</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-11_P-6642A, TS hypocholorite pump A show no signal at CCR">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-11_P-6642A, TS hypocholorite pump A show no signal at CCR</a><br></p>', '2024-09-11 15:04:47', '2024-10-29 23:40:47', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
