-- Inserting report ID 33408
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify air starting solenoid at FWP no.1 ', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-11', '<p><b><u>Action:</u></b></p><p>- Removed the tubing connection and isolate the power for air starting solenoid (XSV-67002).</p><p>- Removed air starting solenoid (XSV-67002) from the FWP No.1 skid.</p><p>- Function test the existing air starting solenoid at workshop and found working properly.</p><p>- Functin test new solenoid at workshop and replaced the existing solenoid with new spare for integrity. (In Progress)</p><p>- Performed function test for new solenoid at local and found working properly.</p><p>- Normalize the power supply and tubing connection.</p><p>- Performed function test the fire water pump No.01 </p><p><b>1st (Start from local push button)</b></p><p>- Fire water pump No.1 fail to start with overspeed alarm. (HMI status show stop, RPM show 2656)</p><p>- After a few second, the RPM value back to normal.</p><p><b>2nd (Start from local push button)</b></p><p>- Fire water pump No.1 can start properly without any alarm .</p><p><b>3rd (Start from ringmain pressure low)</b></p><p>- FWP 1 start to crank (just cranking for few second) and stop cranking at local and FWP is not running.</p><p>- But HMI status show running.</p><p><b>4th (Start from ringmain pressure low)</b></p><p>- FWP 1 start cranking and running properly without any alarm.</p><p><b>5th (Start from ringmain pressure low)</b></p><p>- FWP 1 start cranking for few second and fail to start with overspeed alarm (RPM show 2656).</p><p><b><u>Plan:</u></b></p><p>- Will continue TS on tomorrow.</p><p><b><u style="background-color: rgb(255, 255, 0);">History:</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">10 Sep 2024</u></b></p><p><u style="background-color: rgb(255, 255, 0);">Problem:</u></p><p><span style="background-color: rgb(255, 255, 0);">- Fire water pump No.1 cranking and fail to start when command start.</span></p><p><u style="background-color: rgb(255, 255, 0);">Found:</u></p><p><span style="background-color: rgb(255, 255, 0);">- Can start the fire water pump wtihout any alarm.</span></p><p><u style="background-color: rgb(255, 255, 0);">Action:</u></p><p><span style="background-color: rgb(255, 255, 0);">- Checked the air starting solenoid (XSV-67002) coil resistance and found normal (283.7 kOhm). (New solenoid = 291.3 kOhm)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Checked the fuse for the air starting solenoid. (0.3 Ohm)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Tightened the cable terminal for air starting solenoid.</span></p><p><u style="background-color: rgb(255, 255, 0);">Plan:</u></p><p><span style="background-color: rgb(255, 255, 0);">- Will remove air starting solenoid and function test at workshop.</span></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-11_XSV-67002, verify FWP air starting solenoid', '2024-09-11 15:23:55', '2024-09-11 19:52:58', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-XSV-67002', 'ZTK-XSV-67002', 'Air Start Solenoid Valve Control Engine', NULL, NULL, 'Air Start Solenoid Valve Control Engine', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zarni', NULL, 'EXTERNAL', '2024-09-11 15:23:55', '2024-09-11 19:52:58', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-09-11 15:23:55', '2024-09-11 19:52:58', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

