  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To perform 6M PM_EL WP12-CR-1273 Pedestal Crane', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-12', '<p>Action : Performed 6MPM on WP12 crane.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked the battery, alternators and all the condition of electrical system as per job card.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and measured the batteries voltage and internal resistances,</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Battery cell No.1 , voltage = 12.63 V, internal resistance = 84.6 mOhm&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Battery cell No.2 , voltage = 14.79 V, internal resistance = 5.5 mOhm&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Air shut off solenoid = 1.1 Ohm</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Fuel shut off solenoid = 20 Ohm</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Performed function test, checked all the lightings and crane functions. All lightings are in good conditions. Found that crane cannot stop with normal stop button.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">Note:</span> Crane battery cell No.1 is low performance and need to replace with new one. ( Isolate the DC power supply switch at X3 main electrical control panel)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-12_CR-1273, Perform 6MPM WP12-CR-1273 pedestal crane', '2024-09-12 16:02:15', '2024-09-13 08:47:30', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP12-UTLG-CR1273-PKG', 'ZTK-WP12-UTLG-CR1273-PKG', 'Pedestal Crane Package WP12', NULL, NULL, 'Pedestal Crane Package WP12', 'WP12', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-09-12 16:02:15', '2024-09-13 08:47:30', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2024-09-12 16:02:15', '2024-09-13 08:47:30', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
