-- Inserting report ID 33418
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS fire water pump No.1 can''t start', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-12', '<p>Problem: Fire water pump No.1 can''t start due to an overspeed alarm (2656 rpm)</p><p>Action: Checked the speed sensor(magnetic pick up).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Inspected the wiring connections and terminations. (OK).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Tested frequency transducer with frequency calibrator. (OK)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Removed the speed sensor and found some debris at the tip of the sensor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Cleaned the sensor and reinstalled it.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Verified the start sequence programming of the fire water pump.(OK)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Started the fire water pump using local push button. (OK)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Started the fire water pump ring main pressure low. (OK)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The unit is running now normally.(Confirmed with the production team)</p><p><span style="background-color: rgb(255, 255, 0);">Spare parts of speed sensor MESC:&nbsp;&nbsp;<span style="font-size: 15px;">17.90.05.021.3</span></span></p><p>History</p><p><u>Action:</u></p><p>- Removed the tubing connection and isolate the power for air starting solenoid (XSV-67002).</p><p>- Removed air starting solenoid (XSV-67002) from the FWP No.1 skid.</p><p>- Function test the existing air starting solenoid at workshop and found working properly.</p><p>- Function test new solenoid at workshop and replaced the existing solenoid with new spare for integrity. (In Progress)</p><p>- Performed function test for new solenoid at local and found working properly.</p><p>- Normalize the power supply and tubing connection.</p><p>- Performed function test the fire water pump No.01</p><p>1st (Start from local push button)</p><p>- Fire water pump No.1 fail to start with overspeed alarm. (HMI status show stop, RPM show 2656)</p><p>- After a few second, the RPM value back to normal.</p><p>2nd (Start from local push button)</p><p>- Fire water pump No.1 can start properly without any alarm .</p><p>3rd (Start from ringmain pressure low)</p><p>- FWP 1 start to crank (just cranking for few second) and stop cranking at local and FWP is not running.</p><p>- But HMI status show running.</p><p>4th (Start from ringmain pressure low)</p><p>- FWP 1 start cranking and running properly without any alarm.</p><p>5th (Start from ringmain pressure low)</p><p>- FWP 1 start cranking for few second and fail to start with overspeed alarm (RPM show 2656).</p><p><u>Plan:</u></p><p>- Will continue TS on tomorrow.</p><p><u>History:</u></p><p><u>10 Sep 2024</u></p><p><u>Problem:</u></p><p>- Fire water pump No.1 cranking and fail to start when command start.</p><p><u>Found:</u></p><p>- Can start the fire water pump wtihout any alarm.</p><p><u>Action:</u></p><p>- Checked the air starting solenoid (XSV-67002) coil resistance and found normal (283.7 kOhm). (New solenoid = 291.3 kOhm)</p><p>- Checked the fuse for the air starting solenoid. (0.3 Ohm)</p><p>- Tightened the cable terminal for air starting solenoid.</p><p><u>Plan:</u></p><p>- Will remove air starting solenoid and function test at workshop.</p><p>&nbsp; &nbsp; &nbsp;&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-12_P-6700_TS fire water pump No.1 can''t start', '2024-09-12 16:11:17', '2024-09-12 16:19:49', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6700-PCKG', 'ZTK-P-6700-PCKG', 'Fire Water Pump No.1', NULL, NULL, 'Fire Water Pump No.1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-09-12 16:11:17', '2024-09-12 16:19:49', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2024-09-12 16:11:17', '2024-09-12 16:19:49', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Liam', NULL, 'EXTERNAL', '2024-09-12 16:11:17', '2024-09-12 16:19:49', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
END $$;

