  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1Y PM_EL BDG Black Start Diesel Generator', 'Electrical & Instrument', 'PM ', 'In Progress', '2024-09-13', '<p>Action: Perform&nbsp;1YPM at BDG-7205 black start diesel generator.<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and tightened the motor cable terminations and junction boxes.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and recorded the motor insulation and resistance tests of the following unit;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Pre-heating Unit&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Pre-priming pump</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Hydraulic starter pump</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Generator cooling fan motor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Main Generator</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - 50% completed. Job is in progress.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">Tomorrow Plan:</span> To check rectifier diode voltage and resistances</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : To check&nbsp; main rotor and exciter winding</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: To replace indicator lamps (2 Ea) at Battery charger Ex JB.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: To measure battery resistance and voltage.<br></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\13-09-2024_1Y PM BDG (Electrical)', '2024-09-13 15:13:00', '2024-09-14 08:06:41', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
