-- Inserting report ID 33426
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support GDU Train 1 run with condensate fuel', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-13', '<p><b><u>Activity</u></b></p><p>Support GDU Train-1 run with condensate fuel</p><p><b><u>Action:</u></b></p><p>- Prepare tools and multimeters for measuring mA, VDC and micro Amp of flame scanner and flame monitor</p><p>- Perform running test for both pilots E-4750 and E-4752 before starting the main burner</p><p>- Monitor the micro Amp values for both pilots (E-4750= 17.70 micro Amp, E-4752=&nbsp; 15.26 micro Amp)</p><p>- During starting the main burner, it was tripped by E-4752 main burner.</p><p>- Test again and found that burners tripped by condensate pressure high-high around 7 bars (PT-47505)</p><p>-&nbsp;As found: some smoke coming out from the condensate fuel burner E-4750 and E-4752&nbsp;<br></p><p>- Reduce the condensate line pressure to 4.4 bar at pressure transmitter (PT-47505)</p><p>- Perform starting the main burner, both burner flame ON about 6 sec and tripped again.</p><p>- Test run and monitor the pilot current for E-4750 (17.42 micro Amp) and E-4752 (16.48 micro Amp), after that start the burners and both burners ON for 8 ses and trip by condensate HH.&nbsp;</p><p>- For the last time running test, burners tripped by pilot E-4750.</p><p><b><u>Job Status:</u></b></p><p>In progress.</p><p><br></p><p><b><u style="background-color: rgb(255, 255, 0);">History</u></b></p><p>Support GDU Train-1 running with condensate fuel&nbsp;</p><p><u>Action:</u></p><p>- Assist &amp; witness to Mech team for changing fire burner nozzle tubes (E-4750 and E-4752)</p><p>- Test run with air and water injection for fire burner nozzle tubes at upper deck</p><p>- Mounted on the fire burner for E-4750 &amp; E-4752 at GDU train-1</p><p>- Perform function test for the fire burner with condensate fuel</p><p>- Check and measure for the ignition pilot current (E-4750= 16.37 micro Amp, E-4752= 18.13 micro Amp)</p><p>- Check and measure the flame scanner current during burner started. (Only 2 sec run on E-4750 burner )</p><p>- GDU train-1 cannot start with condensate fuel due to main burner tripped</p><p><u>Job Status:&nbsp;</u></p><p>- In Progress</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-13_Support GDU Train-1 run with condensate fuel">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-13_Support GDU Train-1 run with condensate fuel</a><br></p>', '2024-09-13 16:02:42', '2024-09-13 18:59:13', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SK-4700', 'ZTK-SK-4700', 'Glycol Regeneration Package Train 1', NULL, NULL, 'Glycol Regeneration Package Train 1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-09-13 16:02:42', '2024-09-13 18:59:13', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-09-13 16:02:42', '2024-09-13 18:59:13', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
