  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Blowdown valve shows discrepency', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-14', '<p>Problem: Blowdown valve (BDV-40217) shows discrepancy at CCR but fully closed at local.</p><p>Found: Valve is fully close at local. CCR displays a discrepancy.</p><p>Action: Checked the limit switch and magnet.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found the magnet was used in old model.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Replaced the magnet with stem new model.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Function test the valve with CCR. (OK)</p><p>&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\14-09-2024_BDV-40217_ TS blowdown valve shows discrepancy', '2024-09-14 13:24:12', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-TeamLead', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
