  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S shutdown valve fail to function on demand', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-14', '<p>Activity:&nbsp;T/S shutdown valve fail to function on demand</p><p>Action: Overhauled the pilot valve&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Performed leak test. (No leak)<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Function test with CCR&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Opening time: 3Sec</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Closing time: 8Sec</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Now, back to normal<br></p><p><br></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History: 18 August 2024</span><u><br></u></p><p><u>Problem:</u></p><p>- Shutdown valve SDV 03116 fail to function on demand.</p><p><u>Found:</u></p><p>- Function test the valve and found the valve is not moving.<br></p><p><u>Action:&nbsp;</u></p><p></p><p>- Checked the quick exhaust valve and found diaphragm is defective.</p><p>- Replaced the defective diaphragm with new spare.</p><p>- Function test the valve and found the valve can open properly but stuck when command close.</p><p>- Cleaned the pilot valve and function test again but still stuck at close command.</p><p>- Found the pilot valve is still malfunction and seeping due to O-ring deformed.</p><p>- Need to replaced the pilot when spare arrived.</p><p><br></p><p>History: 12Aug24</p><p>Activity:&nbsp;T/S shutdown valve fail to function on demand (SDV-03116)</p><p>Action: Function test with CCR&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found that pilot valve at valve control panel is malfunction</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Swapping the pilot from SDV-03119.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Both SDV-03116 and SDV-03119 pilot valves are passing.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-14_SDV-03116,TS shutdown valve fail to function on demand', '2024-09-14 15:17:22', '2024-09-14 21:43:03', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SDV-03116', 'ZTK-SDV-03116', 'SDV,V-0311 GasOutlet to ProdHeader,ESD3C', NULL, NULL, 'SDV,V-0311 GasOutlet to ProdHeader,ESD3C', 'WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
