-- Inserting report ID 33438
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S choke valve stuck on command from CCR', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-14', '<p>Activity:&nbsp;T/S choke valve stuck on command from CCR</p><p>Action: Informed CCR to stoke test and found that the SOV for hydraulic return line was not working (stuck at 25%.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Checked the two solenoid coil resistances 158 Ohm (same with new spare).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Suspected that the solenoid pilots were malfunction and replaced the two new solenoids.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Performed manual stroke test and the choke valve was stuck opened at 25%.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Inspected the hydraulic restrictor manifolds and found they were in good condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Reassembled all manifolds and solenoids.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Manual stroke test again but the valve still stuck open at 25% and could not be fully opened.</p><p>&nbsp;</p><p>Next Plan: To verify the actuator condition ( to remove valve stem coupling and function stroke test).</p><p><br></p><p><br></p><p><br></p><p><br></p><p>&nbsp; &nbsp; &nbsp;</p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\14-09-2024_TS choke valve stuck on command from CCR WP-11 HCV-11H04', '2024-09-14 16:14:09', '2024-09-15 07:40:39', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HCV-11H04', 'ZTK-HCV-11H04', 'Valve Choke on 6''''GC11H01-J70 for Well H', NULL, NULL, 'Valve Choke on 6''''GC11H01-J70 for Well H', 'WP11', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2024-09-14 16:14:09', '2024-09-15 07:40:39', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.Automation');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2024-09-14 16:14:09', '2024-09-15 07:40:39', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.Automation');
