  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S valve can not fully close when command', 'Mechanic', 'CM ', 'In Progress', '2024-09-14', '<p>Problem - Valve can not fully close when command by CCR.</p><p>As found - Valve was stuck from open position to close position around 60%.</p><p>Action - Remove actuator from valve body.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Apply sealant at stem grease point.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Exercise the valve around 30 times from opening to closing.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Valve is very stuck inside the valve body ( may be ball was damage).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Install back actuator to valve and exercise the valve but still stuck the 60% closing position.</p><p>Next step - will order the new valve and waiting for replacement.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP3\\General\\2024\\2024-09-14 TS SDV-03119 was stuck close position" target="_blank">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP3\\General\\2024\\2024-09-14 TS SDV-03119 was stuck close position</a><br></p>', '2024-09-14 21:45:30', '2024-09-16 07:42:07', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Meeting-Room', false, 'ZTK') RETURNING id INTO new_report_id;
