  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ko Sett', NULL, 'EXTERNAL', '2024-09-14 21:45:30', '2024-09-16 07:42:07', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Meeting-Room');
