  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS pressure transmitter malfunction', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-15', '<p>Problem :</p><p>Pressure transmitter of test separator malfunction.</p><p>Found :</p><p>Fuse blown at the local junction box.</p><p><b>LRV - 0 Bar and URV - 60 Bar.</b></p><p>Action :</p><p>Replaced fuse and checked the transmitter voltage.(Normal)</p><p>Performed transmitter calibration.</p><p>Function test with CCR both low and high alarm are functioning properly.<b>(Low alarm - 19.5 Bar &amp; High alarm - 38 Bar )</b></p><p>Transmitter was back to normal.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-15_PT-01107, TS pressure transmitter of test separator malfunction', '2024-09-15 14:15:39', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
