  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support operation team on GDU condensate', 'Automation', 'OTH ', 'In Progress', '2024-09-16', '<p><b>Today Activity:</b></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Changed back the leak testing ON (pilot fuel gas) from 0.005 to 0.02 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; &nbsp; Changed back the PT-47505 HH (condensate fuel line) from 5.4 to to 7.5 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; &nbsp; Changed back the PT-47505 LL (condensate fuel line) from 2.65 to 1 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; &nbsp; Changed back the PT-47509 LL (atomization air line) from 5.5 to 3 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; &nbsp; Changed back the PT-47552 LL (combustion air line) from 0.4 to 0.2 mbar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; &nbsp; &nbsp;Job is still in progress.</p><p><br></p><p><b style="background-color: rgb(255, 255, 0);">History:</b></p><p><b style="background-color: rgb(255, 255, 0);">14 Sep 2024</b></p><p><span style="background-color: rgb(255, 255, 0);">Activity:&nbsp; &nbsp; Support operation team on GDU condensate activity</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Adjusted the leak testing ON (pilot fuel gas) from 0.01 to 0.02.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Adjusted the PT-47505 HH from 5.4 to 7.5 which is condensate fuel.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Performed online-test as per instruction.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Performed Force for SDV-47288 and SDV-47290 (condensate fuel line), SDV-47291 (atomization air line) as per CCR requested.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Changed back the leak testing ON (pilot fuel gas) from 0.01 to 0.005 bar.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Changed back the PT-47505 HH (condensate fuel line) from 7.5 to to 5.4 bar.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Changed back the PT-47505 LL (condensate fuel line) from 1 to 2.65 bar.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Changed back the PT-47509 LL (atomization air line) from 3 to 5.5 bar.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Changed back the PT-47552 LL (combustion air line) from 0.2 to 0.4 mbar.</span></p>', NULL, '2024-09-16 14:01:52', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
