-- Inserting report ID 33457
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support GDU Train 1 run with condensate fuel', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-16', '<p>Action:</p><p>- Support GDU Train-1 running with condensate fuel&nbsp;</p><p>- Witness to Mech team for changing fire burner nozzle tubes (E-4750 and E-4752)</p><p>- Test run with air and water injection for fire burner nozzle tubes at upper deck</p><p>- Mounted on the fire burner for E-4750 &amp; E-4752 at GDU train-1</p><p>- For the first start, applied force open to SDV-47288 and adjusted the condensate pressure PT-47505 as found 7.1 bar&nbsp; to 6.2 bar (as left).</p><p>&nbsp; &nbsp;&nbsp;<span style="background-color: rgb(255, 255, 0);">1st time </span>Perform function test for the fire burner with condensate fuel</p><p>- Check and measure for the ignition pilot current (E-4750= 16.37 micro Amp, E-4752= 15.13 micro Amp)</p><p>- Check and measure the flame scanner current during burner started. (Only 2 sec run going up 4 mA to&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;6mA online monitoring with multimeter)&nbsp; on E-4750 burner.</p><p>- GDU train-1 cannot start with condensate fuel due to main burner tripped</p><p><br></p><p>&nbsp; &nbsp;<span style="background-color: rgb(255, 255, 0);"> 2nd time</span> Perform unction test for the fire burner with condensate fuel</p><p>&nbsp; &nbsp; - E-4750A&nbsp; only 5s&nbsp; Burner on after that Pilot Trip.</p><p>&nbsp; &nbsp; - E-4752A&nbsp; only 10s Burner on after that Pilot Trip.</p><p><br></p><p>&nbsp; <span style="background-color: rgb(255, 255, 0);">&nbsp; 3rd time</span> Perform unction test for the fire burner with condensate fuel</p><p>&nbsp; &nbsp; &nbsp;- E-4750A&nbsp; only 5s&nbsp; Burner on after that Pilot Trip.</p><p>&nbsp; &nbsp; &nbsp;- E-4752A&nbsp; only 10s Burner on after that Pilot Trip.<br></p><p>&nbsp; &nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">4th time</span> Perform unction test for the fire burner with condensate fuel</p><p>&nbsp;- Adjusted the condensate pressure PT-47505 as found 6.2 bar&nbsp; to 7.1 bar (as left).<br></p><p>&nbsp;-Jumped the burner pilot flame for both E-4750 and E-4752 after start burner.</p><p>&nbsp;- E-4750 run only 10 s due to pilot flame E-4750 tripped.<br></p><p>&nbsp; - Pilot Flame LED ON for both burners at LCP panel and monitored the flame.&nbsp;<br></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;Last start</span> : Adjusted the condensate pressure PT-47505 as found 6.2 bar&nbsp; to 7.1 bar (as left).</p><p>- Jumped the burner pilot flame for both E-4750 and E-4752 after start burner.</p><p>- Pilot Flame LED ON for both burners at LCP panel and monitored the flame.&nbsp;</p><p>- E-4750 run only 18 s due to pilot flame E-4750 tripped.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-16_Support GDU Train 1 run with condensate fuel', '2024-09-16 15:22:03', '2024-09-17 08:05:23', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SK-4700', 'ZTK-SK-4700', 'Glycol Regeneration Package Train 1', NULL, NULL, 'Glycol Regeneration Package Train 1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2024-09-16 15:22:03', '2024-09-17 08:05:23', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
