  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Flow transmitter reading fluctuate', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-16', '<p><b>Problem:</b></p><p> Flow transmitter reading fluctuate.</p><p><b>Found:</b></p><p>Unable to power up Wellhead platform WP-08.</p><p><b>Action:</b></p><p>Checked the battery bank voltage - 25.34 VDC.</p><p>Checked the battery input CB(MCCB-1), solar charger output CB(MCCB-5&amp;6) &amp; charger controller output CB(MCCB-7).(Normal)</p><p><span style="background-color: rgb(255, 255, 0);">Found DCDB CB(MCCB-1) no incoming voltage.</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked the continuity test between MCCB-7 and MCCB-1(DCDB).</span></p><p><span style="background-color: rgb(255, 255, 0);">Found the negative cable terminal loosen.(Fixed)</span></p><p>Platform power back to service.</p><p><b>Note:</b></p><p>Still need to verify flow transmitter in next visit.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-16_FT-08112, TS flow transmitter fluctuate', '2024-09-16 15:31:32', '2024-09-16 23:27:12', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
