  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1Y PM on FGS System at GTC train 3', 'Electrical & Instrument', 'PM ', 'Completed', '2024-09-16', '<p>Activity: Performed 1Y PM FGS on GTC-44000 Train 3 as per procedure and PM job task (ZTK-GT-4X00-FGSD)</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Applied electrical isolation as per permit to work requirement.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed condition check to the enclosure, doors, dampers and water mist nozzles.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed flame detectors for cleanliness and sensitivity with magnet and its functionality. &gt; Good.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed gas detectors check, zero calibration and functionality as per required. &gt; Good.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed heat detector functionality check with heat gun. &gt; Good.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed water mist system check. &gt; Good. But N2 cylinder for water mist system B is low &gt; Need to charge.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed fire and gas system test as per cause and effect. &gt; Good</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed checking of strobes and horn working properly or not. &gt; Good</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed all systems back to normal and no alarm at the UCP panel.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Performed electrical de-isolation.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Waiting for resume running from CCR.&nbsp;<br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-16_GTC-4400,1Y F&amp;G PM">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-16_GTC-4400,1Y F&amp;G PM</a><br></p>', '2024-09-16 18:45:50', '2024-09-16 18:48:25', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
