  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist EI to replace sump pump', 'Mechanic', 'CM ', 'Completed', '2024-09-16', '<p><b>Assist EI team to replace sump pump.</b></p><p>Action : (1) Remove union coupling suction 2 EA, discharge 2 EA, and IG suction line and discharge line.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(2) Remove pump from the skid and replaced with new one.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(3) Install back the overhaul sump pump. Make sure union connection are align properly.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(4) Use new SPW gasket for flange joint. (3/4" #150 for IG line, 3/4" #300,600 for discharge line, 1-1/2" for IG return line)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(5) Check leak for any leakage at union joint. Test with Snoop for IG line leakage.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP10\\Sump Pump\\2024\\2024-09-16 Assist EI to Replace Overhual Sump Pump">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP10\\Sump Pump\\2024\\2024-09-16 Assist EI to Replace Overhual Sump Pump</a><br></p>', '2024-09-16 18:55:02', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-1052', 'ZTK-P-1052', 'Sump Pump Deliver from V-1051 to ZPQ', NULL, NULL, 'Sump Pump Deliver from V-1051 to ZPQ', 'WP10', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Yan', NULL, 'EXTERNAL', '2024-09-16 18:55:02', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'EI Team', NULL, 'EXTERNAL', '2024-09-16 18:55:02', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
