  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS abnormal noise of cooler fan E-4460A.', 'Mechanic', 'CM ', 'Completed', '2024-09-17', '<p><b>Description: Performed troubleshooting abnormal noise of GTC train 3 second stage cooler fan.</b></p><p><br></p><p><b><u>Working steps:</u></b></p><p>-Performed electrical isolation.</p><p>-Removed fan guard cover.</p><p>-Checked as found belt condition, sprocket pulley alignment. (tension= <span style="background-color: rgb(255, 255, 0);">19.6 Hz)</span></p><p>-Cleaned the fan sprocket teeth and motor sprocket.</p><p>-Replaced the fan belt with the new one.</p><p>-Adjusted the belt tension to (<span style="background-color: rgb(0, 255, 0);">25 Hz).</span></p><p>-Applied Anti-seize to the alignment stud bolts, engine mounting bolts.</p><p>-Installed back the fan guard cover.</p><p>-Performed electrical de-isolation and test run.</p><p>-Found no abnormal noise.</p><p><br></p><p><b><u>Photo link in details.</u></b></p><p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\44 GAS COMPRESSOR T 3\\GAS COOLER\\E-4460 (Second stage)\\E-4460A\\2024\\2024-09-17 TS abnormal noise of coolar fan">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\44 GAS COMPRESSOR T 3\\GAS COOLER\\E-4460 (Second stage)\\E-4460A\\2024\\2024-09-17 TS abnormal noise of coolar fan</a><br></p>', NULL, '2024-09-17 14:08:11', '2024-09-17 14:10:16', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
