-- Inserting report ID 33473
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S ESDV shows fault dueto ZSH1211A position fault', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-18', '<p>Activity :&nbsp;T/S ESDV shows fault due to ZSH1211A position fault alarm.</p><p>Action&nbsp; : Checked at local and found that a voltage drop of around 12VDC for position switch ZSH1211A.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replaced the position switch with new one and performed function test with CCR.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Valve can operate properly and all status showed normal.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- But, the intermittent position fault alarm for ZSH1211A reoccured at 4:30PM.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Checked and tightened the connections at local positioner terminals and local junction box&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Inspected at SIS cabinet and found that ZSH-12211A terminal at TB-M8-1 was loosened.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- The alarm was cleared just after retightened the terminal.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Performed another function test with CCR and confirmed that all open &amp; close statues are normal and no further position fault alarm.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Opening time : 15 Sec</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Closing time : 14 Sec<br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-18_ESDV-12211 TS ESDV shows status fault at CCR', '2024-09-18 15:27:42', '2024-09-19 18:07:23', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-ESDV-12211', 'ZTK-ESDV-12211', 'ESDV 18"-GC-12011-F06P for ESD 1,2,2CB', NULL, NULL, 'ESDV 18"-GC-12011-F06P for ESD 1,2,2CB', 'WP12', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-09-18 15:27:42', '2024-09-19 18:07:23', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-09-18 15:27:42', '2024-09-19 18:07:23', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
