DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replaced the gasket for sump pump', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-18', '<p>Activtiy:&nbsp;Replaced the gasket for sump pump</p><p>Action : Replaced the Gasket at IG Supply Flange.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Found no more leakage</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- But found that liquid leak at the pump section thread</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Fixed it and function test again. No more leak and pump is back to service.<br></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History: 12 Sep 2024</span></p><p>Problem: T/S sump pump is not working.</p><p>Action: Replaced the sump pump with overhaul one.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: When we Performed the function test IG supply Flange was leakage.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Now we used the old gasket for IG flange.</p><p><br></p><p>Plan&nbsp; &nbsp;: Next Visit neeed to replaced the Gasket at IG Supply Flange.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 3/4 150 and 1" 150 (Gasket )</p><p><br></p><p>Notes for Phase 1D:</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Gasket Requirements&nbsp; &nbsp; :&nbsp; &nbsp; 3/4" 150# spiral wound gasket&nbsp; &nbsp; :&nbsp; &nbsp; 2 nos. (for IG Supply line)</p><p>&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;:&nbsp; &nbsp; 1" 150# spiral wound gasket&nbsp; &nbsp; :&nbsp; &nbsp; 2 nos. (in case)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; :&nbsp; &nbsp; 1-1/2 " 150# spiral wound gasket&nbsp; &nbsp; :&nbsp; &nbsp; 2 nos. (For vent line)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; :&nbsp; &nbsp; 3/4" 300/600# spiral wound gasket&nbsp; &nbsp; :&nbsp; &nbsp; 2 nos. (For discharge line)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; :&nbsp; &nbsp; 1-1/2" 300/600# spiral wound gasket&nbsp; &nbsp; :&nbsp; &nbsp; 2 nos. (For suction line)</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Tool Requirement&nbsp; &nbsp; :&nbsp; &nbsp; Spanner&nbsp; &nbsp; :&nbsp; &nbsp; 7/8&nbsp; &nbsp; :&nbsp; &nbsp; 2 nos.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; :&nbsp; &nbsp; 3/4&nbsp; &nbsp; :&nbsp; &nbsp; 2 nos.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; :&nbsp; &nbsp; 1-5/16 (32 mm)&nbsp; &nbsp; :&nbsp; &nbsp; 2 nos.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; :&nbsp; &nbsp; 14 mm&nbsp; &nbsp; :&nbsp; &nbsp; 2 nos.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-18_WP-12, P-1252 Replace sump pump gasket', '2024-09-18 15:30:52', '2024-09-18 22:08:53', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-1252', 'ZTK-P-1252', 'Sump Pump Deliver from V-1251 to WP11', NULL, NULL, 'Sump Pump Deliver from V-1251 to WP11', 'WP12', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-09-18 15:30:52', '2024-09-18 22:08:53', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
