  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S the VCB power meters of GTG train 2 & 3', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-19', '<p>Problem: The VCB power meters of VCB F-09_GTG train 2 &amp; VCB F-17_GTG train 3 readings freeze at ECS.</p><p>Action: Verified &amp; checked at HSWG-CPP-100, found the local power meters are in good condition. (Normal)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Checked at ECS architecture at ECS, and found the SIS gateway B at (HSWG-CPP-100) communication was abnormal. (Fault)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Checked Alarm event Log and found the communication of HSWG-CPP-100 SIS Gateway B was intermittently fault.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Observed the communication LAN cable from SIS Gateway B to ECS server was loosen.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Firmly fixed the loosen LAN cable and now the power meter readings at ECS are in normal condition.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-19_VCB F09 &amp; VCB F17, TS Power Meter Freeze at ECS for GTG-7220 &amp; GTG-7230">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-19_VCB F09 &amp; VCB F17, TS Power Meter Freeze at ECS for GTG-7220 &amp; GTG-7230</a><br></p>', '2024-09-19 15:28:36', '2024-09-20 07:22:19', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
