-- Inserting report ID 33487
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support GDU Train 1 run with condensate fuel', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-19', '<p><b><u>Activity:</u></b></p><p>Support GDU Train 1 run with condensate fuel</p><p><b><u>Action:</u></b></p><p>- Prepare tools and equipment for measuring m Amp , micro Amp of flame scanner and flame monitor</p><p>- Perform running test for both pilots E-4750 and E-4752 before starting the main burner (16.32 micro Amp)</p><p>- Adjust condensate pressure from 8 bar to 4.7 bar before start the main burner</p><p>- For the <span style="background-color: rgb(255, 255, 0);">1st time</span> running, GDU was tripped by <span style="background-color: rgb(255, 255, 0);">main burner A</span> (E-4750)</p><p>- Adjust atomization air for burner A - 4.8 bar &amp; burner B - 4.4 bar and FV- 50 % open, combustion air- 1600 psi</p><p>- For the <span style="background-color: rgb(255, 255, 0);">2nd time</span> running, GDU was tripped by <span style="background-color: rgb(255, 255, 0);">pilot A&nbsp;</span> &nbsp;&nbsp;</p><p>- Adjust atomization air for burner A - 4.0 bar &amp; burner B - 4.6 bar and FV- 45 % open, combustion air- 1500 psi, condensate pressure- 8 bar</p><p>- For the <span style="background-color: rgb(255, 255, 0);">3rd time</span> running, GDU was tipped by <span style="background-color: rgb(255, 255, 0);">Main burner B</span> (E-4752)</p><p>- Adjust atomization air for burner A - 4.0 bar &amp; burner B - 4.6 bar and FV- 40 % open, combustion air- 1500 psi, condensate pressure- 8 bar</p><p>- For the <span style="background-color: rgb(255, 255, 0);">4th time</span> running, GDU was tipped by <span style="background-color: rgb(255, 255, 0);">pilot A</span> (E-4750)</p><p>- Adjust atomization air for burner A - 4.8 bar &amp; burner B - 4.0 bar and FV- 40 % open, combustion air- 1300 psi, condensate pressure- 8 bar</p><p>- For the<span style="background-color: rgb(255, 255, 0);"> 5th time</span> running, GDU was tipped by <span style="background-color: rgb(255, 255, 0);">Main burner A</span> (E-4750)</p><p>- Adjust atomization air for burner A - 4.8 bar &amp; burner B - 4.0 bar and FV- 40 % open, combustion air- 1200 psi, condensate pressure- 8 bar</p><p>- For the <span style="background-color: rgb(255, 255, 0);">6th time</span> running, GDU was tipped by<span style="background-color: rgb(255, 255, 0);"> pilot A </span>(E-4750)</p><p>- Perform jump start for the both pilot A &amp; B</p><p>&nbsp;- Adjust atomization air for burner A - 4.8 bar &amp; burner B - 4.0 bar and FV- 40 % open, combustion air- 1200 psi, condensate pressure- 8 bar</p><p>- For the <span style="background-color: rgb(255, 255, 0);">7th time</span> running, GDU was tipped by<span style="background-color: rgb(255, 255, 0);"> pilot A</span> (E-4750)</p><p>- Keep trying the burning with condensate fuel&nbsp; for GDU Train-1</p><p><b><u>Job Status:</u></b></p><p>In Progress.</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-19_GDU 4700, Support GDU Train-1 run with condensate fuel">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-19_GDU 4700, Support GDU Train-1 run with condensate fuel</a><br></p>', '2024-09-19 16:09:37', '2024-09-19 16:12:59', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SK-4700', 'ZTK-SK-4700', 'Glycol Regeneration Package Train 1', NULL, NULL, 'Glycol Regeneration Package Train 1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2024-09-19 16:09:37', '2024-09-19 16:12:59', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-09-19 16:09:37', '2024-09-19 16:12:59', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
