  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S TEG found malfunction', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-19', '<p><b>Activity: </b></p><p>T/S TEG-0395 J/L malfunction.</p><p><b>Action:</b></p><p><b>For TEG-0395 J,</b></p><p> </p><p>Started the TEG and no defective equipment.</p><p> The unit can start while holding the auto shut off valve.</p><p>The units stopped when removed the auto shut off valve.</p><p><b>For TEG-0395 L,</b></p><p>Replaced the manual start push button and thermocouple.<b><br></b></p><p>The unit can start while holding the auto shut off valve.</p><p>The units stopped when removed the auto shut off valve.</p><p><b>Remark:</b></p><p>Need to verify the thermopile performance.<br></p><p><br></p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\19-09-2024_TS TEG found malfunction', '2024-09-19 17:27:37', '2024-09-20 08:40:17', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
