  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Hypochlorite injection valve is not open', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-19', '<p>Problem:&nbsp;Hypochlorite injection valve unable to open when comman open.</p><p>Action: CCR command for open the valve. </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found that the solenoid is working but valve is not moving.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Keep command open and isolated the instrument supply.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found that IA pressure drop immediately.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Search and found the leak point and it''s from the connecting point of valve and flange.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;</p><p>NOTE: Internal leak may be between actuator and valve. May need to replace the whole set.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-19_XV-66451, TS Hypochlorite injection valve is not open">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-19_XV-66451, TS Hypochlorite injection valve is not open</a><br></p>', '2024-09-19 17:38:54', '2024-09-19 17:39:24', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-XV-66451', 'ZTK-XV-66451', 'Shutoff Valve,Hypochlorite to T-6705', NULL, NULL, 'Shutoff Valve,Hypochlorite to T-6705', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2024-09-19 17:38:54', '2024-09-19 17:39:24', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2024-09-19 17:38:54', '2024-09-19 17:39:24', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
