  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist MECH team to TS SDV-03119', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-19', '<p><b>Activity:&nbsp;</b></p><p>Assist MECH team to T/S SDV-03119 shutdown valve fail to function at close position.</p><p><b>Found :</b></p><p>Pilot valve stuck while valve closing.</p><p><b>Action:</b></p><p> </p><p>Removed the tubing for IG supply line and return line.</p><p>Removed the valve actuator and performed function test.</p><p>Founf pilot valve stuck while valve closing.<br></p><p>Overhauled the pilot valve.</p><p>Performed function test and leak test.(No leak)</p><p>Function test with CCR.</p><p>Opening time: 3Sec</p><p>Closing time: 3Sec</p><p>Now, SDV-03119 back to service.</p><p><b>Remark:</b></p><p>Valve actuator is working properly.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-19_SDV-03119, Assist MECH team to TS SDV-03119', '2024-09-19 22:31:23', '2024-09-19 22:58:51', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
