  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To perform davit motor condition check ', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-20', '<p><u>Action</u></p><p>- Check the motor heater insulation resistance and it is <b>&gt;200 M-Ohm</b> .</p><p>- Isolate the power supply and check the motor winding insulation resistance and individual winding resistance.</p><p>- The result is as follow.</p><p>&nbsp;</p><p><br></p><p>&nbsp;</p><p><br></p><p></p><p><br></p><p></p><p><br></p><p><br></p><p><br></p><p>-Found that one of the power cable L3(<b>Gray</b>) that connected to W1 is also low insulation.</p><p>- Performed Polarization Index (PI) test and the result is PI=1.35.</p><p>- Motor Insulation Condition is in <b>POOR </b>Stage.</p><p><br></p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-20_SC-7730">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-20_SC-7730</a><br></p>', '2024-09-20 15:53:50', '2024-09-20 19:05:30', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-7730-SKID', 'ZTK-X-7730-SKID', 'Life Boat Davit Skid No.3', NULL, NULL, 'Life Boat Davit Skid No.3', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
