-- Inserting report ID 33497
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support GDU Train 1 run with condensate fuel', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-20', '<p><b><u>Activity:</u></b></p><p>- Support GDU Train-1 run with condensate fuel</p><p><b><u>Action:&nbsp;</u></b></p><p>- Remove GDU Train-1 pilot tubes E-4750 and E-4752 as per requested by <span style="background-color: rgb(255, 255, 255);">production supervisor</span></p><p>- Visual check and inspection for the pilot tubes E-4750 and E-4752&nbsp;</p><p>As found: Pilot tubes are good in condition and some smoke dusts attached with both pilot tubes</p><p>- Re-install back the pilot tubes E-4750 and E-4752 in normal condition</p><p>- Start GDU Tain-1 and running the pilot tubes E-4750 and E-4752</p><p>As Found: Pilot tubes show E-4750= 15.75 micro Amp &amp; E-4752= (-2.19) micro Amp with jump start</p><p>- Adjust and clean the air adjuster for pilot B the value shows E-4752= 13.45 micro Amp</p><p>As found: E-4752 pilot B air adjuster shows abnormal, founded adjuster locked nut removed and fly inside the pilot mixer&nbsp;</p><p>- Replaced with new pilot E-4752 pilot B and running test again</p><p>- Pilot tube E-4752 shows ionization current low &amp; unstable and tripped by pilot B flame off</p><p>- During running main burner, condensate pressure shows 3-5 bar at condensate line pressure gauge</p><p>- GDU Train-1 was tripped by Main burner E-4750, Pilot B (E-4752) and Pilot A (E-4750)&nbsp;&nbsp;</p><p>- Keep trying the running of GDU-4700 with condensate fuel</p><p><b><u>Job Status:&nbsp;</u></b></p><p>In Progress&nbsp; &nbsp; &nbsp; &nbsp;</p><p><b>Remark</b>: For pilot tube B <span style="background-color: rgb(255, 255, 0);">(E-4752),</span> ionization current is stable <span style="background-color: rgb(255, 255, 0);">(15.57) micro Amp</span> due to fuel line<span style="background-color: rgb(255, 255, 0);"> flow</span> <span style="background-color: rgb(255, 255, 0);">restrictor</span> at air mixer.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-20_GDU-4700, Support GDU Train-1 run with condensate fuel">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-20_GDU-4700, Support GDU Train-1 run with condensate fuel</a><br></p>', '2024-09-20 16:04:53', '2024-09-20 19:49:16', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SK-4700', 'ZTK-SK-4700', 'Glycol Regeneration Package Train 1', NULL, NULL, 'Glycol Regeneration Package Train 1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
