  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Charge N2 to accumulator No.3 ', 'Mechanic', 'CM ', 'Completed', '2024-09-20', '<p>Problem : Nitrogen pressure was low at engine starting accumulator No.3.</p><p>Found&nbsp; &nbsp; : N2 Bladder was broken.</p><p>Action&nbsp; &nbsp; : Arranged the nitrogen rack and high pressure hose.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Charged N2 into the bladder.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Checked the bladder condition at N2 pressure 20 Bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Found hydraulic came out from the N2 charging port.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Removed accumulator cylinder and bring to ZPQ.&nbsp;</p>', NULL, '2024-09-20 16:32:23', '2024-09-21 17:35:26', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Crane', false, 'ZTK') RETURNING id INTO new_report_id;
