  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S SDV-03119 cannot fully close ', 'Mechanic', 'CM ', 'Under Monitoring', '2024-09-20', '<p>Problem - Valve can not fully close when command by CCR.</p><p>As found - Valve was stuck from open position to close position around 60%.</p><p>Action - Remove actuator from valve body.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -remove valve stem extener coupling</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -exercise the valve with pipe wrench</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - exercise the actuator by it self requesting EI team</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-after exercise the actuator found solenoid stem is&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -found gland follower is firmily tight with stud and EI team changed it</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -After remove gland packing try to remove the gland follower is stuck</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - cannot remove the follower</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -put and apply some lubricant to get smooth rotation</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -install back actuator and exercise the valve&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -valve can close fully open and close but not smooth travelling&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -need puller to remove the gland follower</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP3\\General\\2024\\2024-09-20 TS SDV-03119 was stuck to close">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP3\\General\\2024\\2024-09-20 TS SDV-03119 was stuck to close</a><br></p>', '2024-09-20 18:14:19', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SDV-03119', 'ZTK-SDV-03119', 'SDV on 4"-PL-03103-JS2N for ESD 3CA', NULL, NULL, 'SDV on 4"-PL-03103-JS2N for ESD 3CA', 'WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
