-- Inserting report ID 33501
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Install & function test the HI Pump', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-20', '<p><a href="Action:Insta;;">Action: Insta</a>lled HI Pump B and C on the skip.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <u>For pump B</u></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Pump running condition is normal.(No leak at the Pump)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Pump discharge pressure can build up 200 bar and inject the methanol into the well.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed function test,  the pump is operating normally and can build pressure..</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found that flow transmitter has no flow when pump is running.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked and tightened the connections on the flow element (Coriolis flow meter) and swapped the&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; flow transmitter display card from Pump C.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The discharge flow rate was found to be between 11.2 and 44.5 L/h.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Instrument gas supply to run the pump is 4.5 and discharge pressure is 200bar.</p><p><br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <u>For Pump C</u></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Pump running condition is abnormal.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Pump discharge pressure cannot build up.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Internal liquid section of the pump is passing.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Bring back the pump to workshop for inspection.</p><div class="group/conversation-turn relative flex w-full min-w-0 flex-col agent-turn"><div class="flex-col gap-1 md:gap-3"><div class="flex max-w-full flex-col flex-grow"><div data-message-author-role="assistant" data-message-id="53e93c66-6752-419a-ae6b-711fe5d1b0f6" dir="auto" class="min-h-[20px] text-message flex w-full flex-col items-end gap-2 whitespace-normal break-words [.text-message+&amp;]:mt-5"><div class="flex w-full flex-col gap-1 empty:hidden first:pt-[3px]"><div class="markdown prose w-full break-words dark:prose-invert light"><hr><p><br></p></div></div></div></div></div></div><p>History</p><p>Action: Performed function test Pump C , No leak and pressure can built up.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Fixed stoke adjuster Pump B.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Replaced the "O_Ring Spring Seat" .</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed function test, found Pump discharge pressure is a little bit low.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Suspected that Pump Relay is low performance. Swapped the Pump Relay form Pump A.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed function test, Pump discharge flow is normal and pressure can built up.&nbsp;</p><p><br></p><p><br></p><p>History<br></p><p>Action: Disassemble the air drive section of pump C.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Tighten the stroke adjuster.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Fixed the air leak in the air drive section.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Replaced the "O-Ring Spring Seat" with new spare.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed function test, Air Supply at 3.5 bar, Pump discharge flow is normal and&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; pressure builds up.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p>Plan : For Pump B, tighten the stroke adjuster and replace "O-Ring Spring Seat".</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Test run of Pump C again.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Performe a test run Pump B.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Summarized the status of Pumps (A/B/C) in excel file.</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p>History</p><p>Verify hydrate inhibitor injection pump for WP-15 as below.</p><p><br></p><p></p><p><br></p><p>Function test pump B by replacing the suction and discharge check valves.&nbsp;</p><p>Found pump B discharge flow is still low. Need to check pump internal seal kit.</p><p>Plan to disassemble the pump C, tight the stoke adjuster and perform function test.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-21_Install &amp; function test the HI Pump', '2024-09-20 22:23:01', '2024-09-23 07:47:06', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP15', 'ZTK-WP15', 'Zawtika Wellhead Platform 15', NULL, NULL, 'Zawtika Wellhead Platform 15', 'WP15', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-09-20 22:23:01', '2024-09-23 07:47:06', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-09-20 22:23:01', '2024-09-23 07:47:06', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-09-20 22:23:01', '2024-09-23 07:47:06', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.EI-TeamLead');
END $$;

