  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 3M PM Water Maker X-6620', 'Mechanic', 'PM ', 'Completed', '2024-09-18', '<div><span style="font-size: 14px;">Performed mechanical 3 M PM at water maker skid 1.</span><br></div><div><p>-Removed the gear box breather cap.</p><p>-Drained the gear lube oil.</p><p>-Filled with new C''Treat lube oil 2 quart.</p><p>-Checked the filter condition.</p><p>-Checked machine running condition.</p><p>-Perform Mech Seal Flushing.</p><p><br></p><p>(Bag Filters, 1st Stage Filters and 2nd Stage filters are replaced by OGAS 6MPM on 29/8/2024 and not more than 30 days)</p><p><br></p></div>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2024\\2024-09-18 3M PM X-6620">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2024\\2024-09-18 3M PM X-6620</a><br></p>', '2024-09-21 10:50:38', '2024-09-21 10:51:26', 'PTTEP\\ZPQ.Mechanical-TeamL', 'PTTEP\\ZPQ.Mechanical-TeamL', false, 'ZTK') RETURNING id INTO new_report_id;
