BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1Y PM for F&G  Black Start Diesel Generator', 'Electrical & Instrument', 'PM ', 'Completed', '2024-09-21', '<p><u>Action :</u>&nbsp;Performed 1YPM Fire &amp; Gas system for BDG-7205 as per procedure.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Check the conditions of equipment and cable for each detectors.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Function test Flame, Gas, and Heat detector and checked the activation of Air shutoff&nbsp; valves, Fuel Shutoff valve and Battery charger disconnected.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Function test pressure switch.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Normalized the unit and performed on load test run for 1 Hour.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Monitored and recorded all parameters in the procedure check lists.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Test run with Electric and Hydraulic mode completed.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Stop the unit and now unit back to normal.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p>Note: During performed PM, found that UCP panel ventilation fan is stuck and breaker tripped by overload.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Replaced ventilation fan with new one and reset the breaker.</p><p><br></p><p><br></p><p>-Job completed</p>', NULL, '2024-09-21 15:48:30', '2024-09-21 18:24:53', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-BDG-7205', 'ZTK-BDG-7205', 'Black Start Diesel Generator Package', NULL, NULL, 'Black Start Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LCP-CPP-7206', 'ZTK-LCP-CPP-7206', 'Fire & Gas Control Panel for BDG-7205', NULL, NULL, 'Fire & Gas Control Panel for BDG-7205', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
