  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2024-09-21 15:48:30', '2024-09-21 18:24:53', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
