  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS abnormal noise', 'Mechanic', 'CM ', 'Completed', '2024-09-21', '<p>Work - TS abnormal noise</p><p>Found</p><p>- As found alignment is a bit level higher for motor pulley.</p><p>- As found tension is loosen 30Hz (rated tension - 45 to 49Hz)</p><p>- <span style="background-color: rgb(255, 255, 0);">Found water ingress in the motor drive end side bearing.</span></p><p>- Heard minor strange noise from motor non drive end side bearing.</p><p>Action</p><p>- Adjust alignment between motor and fan pulleys.</p><p>- Replace belts (3nos.) and adjust belt tension (47Hz)</p><p>- Do greasing and exercise.</p><p>- House keeping the area.</p><p>- Perform test run.</p><p>- Found fan side is ok.</p><p>- Found motor side bearing has strange noise.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\Lube oil cooler\\E-4393A\\2024\\2024-09-21 TS abnormal noise">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\Lube oil cooler\\E-4393A\\2024\\2024-09-21 TS abnormal noise</a><br></p>', '2024-09-21 16:37:55', '2024-10-14 22:36:35', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EF-4390A', 'ZTK-EF-4390A', 'Lube Oil Cooler Fan No.1', NULL, NULL, 'Lube Oil Cooler Fan No.1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
