  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replaced Hypo injection Valve for FWP no.1', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-22', '<p>Problem: XV-66451 could not be opened.&nbsp;</p><p>Found: IA air leakage between valve actuator and body.</p><p>Action: To replace new&nbsp; on-off valve on the hypochlorite injection to firewater pump no.1.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Disassemble the defective valve and actuator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Install new spare valve and actuator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Normalized and function test the valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Found Open status not showed at DCS and verified the fuse at ITR marshalling cabinet.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : The fuse was blown and replaced with new fuse. (Now Open/Close Status are Normal at Local and DCS.)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Checked leak and found no any leak.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-22_XV-66451_Replaced new actuator and valve', '2024-09-22 15:31:06', '2024-09-23 18:00:45', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
