  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Upgrade LTMR firmware to 3.0 for MCC drawers.', 'Automation', 'OTH ', 'In Progress', '2024-09-22', '<div><b>Today Activity:</b></div><div>&nbsp; &nbsp; -&nbsp; &nbsp; Performed upgrading LTMR version for P-78115B.</div><div>&nbsp; &nbsp; -&nbsp; &nbsp; Performed back-up existing version "2.4" files of P-78115B.</div><div>&nbsp; &nbsp; -&nbsp; &nbsp; Upgraded LTMR version of P-78115B from 2.4 to 3.0.</div><div>&nbsp; &nbsp; -&nbsp; &nbsp; Performed test run for firmware-upgraded P-78115B. (Working properly)</div><div>&nbsp; &nbsp; -&nbsp; &nbsp; Change address of previous already upgraded spare motor (LTMR version 3.0) same with P-78115A. (Address: 3)<br></div><div>&nbsp; &nbsp; -&nbsp; &nbsp; Inserted and performed test run that spare motor into drawer of P-78115A. (Working properly and keep monitoring for a while).</div><div>&nbsp; &nbsp; -&nbsp; &nbsp;&nbsp;Cleaned the jaws and joints of P-78115A and applied&nbsp;ep2&nbsp;pyratex grease lightly.&nbsp;<br></div><div>&nbsp; &nbsp; -&nbsp; &nbsp;&nbsp;Put the temporary stickers in the spare feeder and original feeder for notification. (P-78115A and Spare)<br></div><div><br></div><div><b>Tomorrow Plan: </b>Going to upgrade version of LTMR for P-78115A.</div><div><br></div><div><b><br></b></div><div><b style="background-color: rgb(255, 255, 0);">History:</b></div><div><b style="background-color: rgb(255, 255, 0);">15 Sep 2024:</b></div><div><span style="background-color: rgb(255, 255, 0);">Activity:&nbsp; Performing upgrade LTMR version for drawer type LVM2, P-7115A/B and spare feeder.&nbsp;</span></div><div><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Checked the network address of spare feeder and feeder for P-7115B.</span></div><div><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Racked out the spare feeder F17-6 (22kW) and performed backup related files.<br></span></div><div><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp;&nbsp;&nbsp;&nbsp;Upgraded LTMR version of spare feeder F17-6 (22kW) from "2.4" to "3.0".</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Cleaned the jaws and joints of feeders and applied&nbsp;ep2&nbsp;pyratex grease lightly.&nbsp;<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Performed test run at the feeder for P-7115B with operator for 5 minutes. (Run properly/No any alarm)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Going to keep the upgraded spare feeder in P-7115B for monitoring.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Put the temporary stickers in the spare feeder and original feeder for notification.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Next Plan: If upgraded spare feeder is working properly for some days, will upgrade for original feeders for P-7115A/B.&nbsp;</span></p></div>', NULL, '2024-09-22 15:42:14', '2025-04-15 08:05:24', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
