  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS abnormal noise', 'Mechanic', 'CM ', 'Completed', '2024-09-23', '<p>Work - TS abnormal noise</p><p>Found</p><p>- As found alignment is that motor pulley is a bit higher.</p><p>- As found belt tension is that 32 hz, lower than normal tension.</p><p>- Motor pulley''s groove is wear which is need to replace.</p><p>Action</p><p>- Replace motor pulley.</p><p>- Adjust belt and pulley alignment.</p><p>- Replace belt.</p><p>- Adjust belt tension (47.6 hz).</p><p>- Do greasing and excerise bearings.</p><p>- Reinstate and housekeeping.</p><p>- Perform test run.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\Lube oil cooler\\E-4393C\\2024\\2024-09-23 TS abnormal noise">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\Lube oil cooler\\E-4393C\\2024\\2024-09-23 TS abnormal noise</a><br></p>', '2024-09-23 16:24:27', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-FM-4393C', 'ZTK-FM-4393C', 'Lube Oil Cooler Fan Motor No.3', NULL, NULL, 'Lube Oil Cooler Fan Motor No.3', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
