-- Inserting report ID 33529
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S firewater pump cannot normal stopped', 'Automation', 'CM ', 'In Progress', '2024-09-24', '<p>Activity: Troubleshoot Firewater Pump P-6700 cannot be normal stopped.</p><p>Action: Checked the logic in the PLC and found that it cannot reach the normal stop sequence in the logic. (Reason is from the speed sensor)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Checked if the normal stop push button is working properly or not.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Simulated the speed transducer input. (Got correct value &gt; Good)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Removed the speed sensor terminal connection and sensor. (Found that the speed sensor terminal joint connection is not good).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Checked if the speed sensor is good or not with magnet. (Good)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Checked the speed sensor cable continuity via multimeter. (Good but the terminal connection is not good.)&nbsp;&nbsp;&nbsp;&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Installed the speed sensor and performed test run the fire water pump. (Not readind RPM)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;</p><p>Plan: Since the speed sensor and cable joint conneciton is not good, need to modify. No spare part.&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-24_P-6700, TS fire water pump cannot stop">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-24_P-6700, TS fire water pump cannot stop</a><br></p>', '2024-09-24 15:46:16', '2025-08-18 11:04:01', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6700-PCKG', 'ZTK-P-6700-PCKG', 'Fire Water Pump No.1', NULL, NULL, 'Fire Water Pump No.1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-09-24 15:46:16', '2025-08-18 11:04:01', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Liam', NULL, 'EXTERNAL', '2024-09-24 15:46:16', '2025-08-18 11:04:01', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop');
