-- Inserting report ID 33536
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP01 Crane boom flood light malfunction', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-09-25', '<p>Problem&nbsp; &nbsp; : WP01 Crane boom flood light malfunction</p><p>Found&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;: Cable is defective due to swinging when is in crane operation.</p><p>Action&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; : Cut defective cable and plane to make proper cable jointing which is temporary solution.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; To make secure better solution, need to change flood light orientation but need scaffold assist.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;Job is in progress.&nbsp;<br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-25_WP01 Crane boom flood light malfunction', '2024-09-25 13:36:15', '2024-09-25 19:18:54', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
