BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Coolant Leak From Air Compressor', 'Mechanic', 'CM ', 'Completed', '2024-09-25', '<p>Problem : Coolant is leaking from the air compressor.</p><p>Found&nbsp; &nbsp; : One of the clamping bolt is broken and damaged.</p><p>Action&nbsp; &nbsp; : (1) Remove the air compressor from the engine connection area.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Take out the compressor air chamber.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Remove the residual broken bolt using extractor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (4) Reinstall and mount back with hot spare bolt. (Bolt = Head 13mm, Length = 80 mm, Size = 8mm x 1.25 COARSE)</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP1\\Crane CR-0173\\2024\\2024-09-25 TS Coolant Leaking From Air Compressor">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP1\\Crane CR-0173\\2024\\2024-09-25 TS Coolant Leaking From Air Compressor</a><br></p>', '2024-09-25 16:38:34', '2024-09-25 17:10:51', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
