  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2024-09-25 16:38:34', '2024-09-25 17:10:51', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
