-- Inserting report ID 33553
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhaul 2nd stage anti surge valve', 'Electrical & Instrument', 'OTH ', 'In Progress', '2024-09-26', '<p>Today Activity: <span style="background-color: rgb(255, 255, 0);">Overall job progress 80% completed</span></p><p>- Installed IA and 24 VDC supply for calibration.</p><p>- Performed function test by loop calidrator.</p><p>- Adjusted the stem of Topworx valve positioner to be same with indicator.</p><p>- Performed auto calibration with HART via Valve LInk.</p><p>- Recorded the existing configuration.</p><p>- Checked the step response via Valve link, but still unstisfied.</p><p>- Job is in progress.</p><p><br></p><p><u>History:&nbsp;</u><br></p><p>- Overall job progress 75% completed</p><p></p><p>- Performed bench test to ensure the valve plug is fully seated.</p><p>- Reinstalled the coupling, new upgraded DVC Positioner,&nbsp; and Topworx valve positioner.</p><p>- Rectify and re-assembled&nbsp; the Swagelok tubing/ fittings.</p><p>- Power up the positioner and solenoid (24VDC) to perform calibration.</p><p>- Mounting positioner Magnet Assembly with Alignment template.</p><p>- Performed Auto calibration with HART and stoke testing 0 to 100% (actuator travels OK)&nbsp;</p><p><br></p><p><u>Pending</u>: Fine Tuning and step response test, performance test by Valve Link.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Hydro test.</p><p><br></p><p>-Adjust the air supply regulator to 5 bar.</p><p>-Install the power supply cable to the smart positioner and instrument air supply solenoid.</p><p>-Connect with HART communicator and check the actuator movement to connect coupling for valve stem.</p><p>-Re-adjust the coupling and check the valve stem and actuator movement.</p><p>-Check the air seeping of the instrument tubing with the snoop.</p><p>Job progress-&nbsp;65% completed.</p><p><br></p><p><br></p><p><u>History: 08-Jul-2024</u><br></p><p>--Adjust the air supply regulator to 5 bar.</p><p>-Install the power supply cable to the smart positioner and instrument air supply solenoid.</p><p>-Connect with HART communicator and check the actuator movement to connect coupling for valve stem.</p><p>-Re-adjust the coupling and check the valve stem and actuator movement.</p><p>-Check the air seeping of the instrument tubing with the snoop.</p><p>-Install smart positioner(DVC-6200), volume booster, regulator and solenoid.</p><p>-Adjust the actuator and valve stem to install coupling between actuator and valve stem.</p><p>-Tighten the packing flange with the torque 40 N-m.</p><p>Job progress- 55% completed.</p><p><u>Plan</u></p><p>-Continue to check the instrument tubing tightness and terminate the wire (smart positioner, solenoid and Top-worx indicator) to supply the power for actuator calibration.</p><p><u><br></u></p><p><u>History: 04-Jul-2024</u></p><p><u>Today Action</u></p><p>-Check and compare the spare internal parts of valve body.</p><p>-Install valve bonnet and stem packing.</p><p>-Install actuator, instrument tubing and positioner support.</p><p>Job progress:&nbsp;45% completed.</p><p>Plan: Continue to install smart positioner(DVC-6200), volume booster, regulator and solenoid.</p><p><br></p><p><u><br></u></p><p>History: 27-Jun-2024</p><p><u>Today action</u></p><p>-Remove the valve stem packing of the bonnet.</p><p>-Compare and check the old and new internal spare parts of the valve body.</p><p>-Replace the internal parts (Ring backup, retaining ring, seal ring, cage, plug/stem and seat ring.</p><p>Job progress: 36% completed.</p><p>Plan: Continue to install valve bonnet and stem packing.</p><p><u><br></u></p><p><u>Today action</u></p><p>-Deeply clean the inside of valve body and bonnet flange surface.</p><p>-Use the utility air and clean the inside of valve body at the outside of laydown area.</p><p>-Check the inside surface of valve body.</p><p>Job progress: 33% completed.</p><p>Plan : Continue to remove valve stem packing and replace the internal parts of valve.</p><p><br></p><p><u><br></u></p><p>History: 22-06-2024<u><br></u></p><p><u>Today Action</u></p><p>-Remove the bonnet from the valve body.</p><p>-Remove the internal parts of the valve body. (Valve stem, plug, seat ring and packing seals)</p><p>-Clean all the internal parts of the valve and bonnet flange surface.</p><p>Job progress: 28% completed.</p><p>Plan: Continue to clean and replace the internal parts of the valve tomorrow.</p><p><br></p><p><br></p><p>History: 21-06-2024<u><br></u></p><p><u>Today Action</u></p><p>-Apply paint remover for 20 minutes to the stud bolts and nuts of the valve body.</p><p>-Clean the paint of the stud bolt and nuts.</p><p>-Apply liquid wrench to the stud bolt and remove the nuts with hydraulic troque wrench pump.</p><p>Job progress: 23% completed.</p><p>Plan: Tomorrow, continue to remove internal parts of valve assembly.</p><p><br></p><p>History: 19-06-2024</p><p><u>Today Action</u></p><p>-Re-assemble the internal part of the actuator (actuator stem, spring and piston).</p><p>Job progress-20% completed.</p><p>Plan: Continue to perform overhaul for valve internal parts.</p><p><br></p><p>History:15-06-2024</p><p><u>Today Action</u></p><p>-Remove the actuator from the valve body.<br></p><p>-Remove the actuator cylinder and disassemble the internal parts.</p><p>-Clean the all internal assembly and perform visual check.</p><p>-Replace yoke O-ring, piston O-ring and actuator stem O-ring.</p><p>Job progress-10% completed.</p><p><br></p><p>Plan: Continue to reinstall back all assembly internal part of the actuator. After that, will install back to valve body.</p><p><br></p><p>History: 14-06-2024<br></p><p>Action: Prepare and check the spare part repair kits of second stage anti surge valve&nbsp;(FV-4X530).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Transfer the anti surge valve from transformer area to the workshop to overhaul.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Remove the instrument tubing, smart positoner, volume booster and positoner indicator.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Job progress&nbsp;5% completed.<br></p><p><br></p><p>Plan: Continue to remove the valve and actuator assembly. And will replace repair kit and perform calibration and function test.&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-26_FV-44530, Overhaul Anti-Surge Valve">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-09-26_FV-44530, Overhaul Anti-Surge Valve</a><br></p>', '2024-09-26 16:41:02', '2024-09-26 18:40:49', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2024-09-26 16:41:02', '2024-09-26 18:40:49', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Turbine');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kong', NULL, 'EXTERNAL', '2024-09-26 16:41:02', '2024-09-26 18:40:49', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Turbine');
END $$;

