-- Inserting report ID 33597
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S choke valve stuck on command from CCR', 'Electrical & Instrument', 'CM ', 'Completed', '2024-10-02', '<p>Activity: T/S choke valve stuck on command from CCR</p><p></p><table border="0" cellspacing="0" cellpadding="0" width="1589"><tbody><tr><td width="636"><p>Action: Removed the coupling between actuator and valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found that actuator can function properly.</p><p><br></p><p>Informed production team.</p><p><br></p><p><b style="background-color: rgb(255, 255, 0);">History:</b></p><p><b style="background-color: rgb(255, 255, 0);">14 Sept 2024</b></p><p><span style="background-color: rgb(255, 255, 0);">Activity:&nbsp;T/S choke valve stuck on command from CCR</span></p><p><span style="background-color: rgb(255, 255, 0);">Action: Informed CCR to stoke test and found that the SOV for hydraulic return line was not working (stuck at 25%.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Checked the two solenoid coil resistances 158 Ohm (same with new spare).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Suspected that the solenoid pilots were malfunction and replaced the two new solenoids.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Performed manual stroke test and the choke valve was stuck opened at 25%.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Inspected the hydraulic restrictor manifolds and found they were in good condition.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Reassembled all manifolds and solenoids.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Manual stroke test again but the valve still stuck open at 25% and could not be fully opened.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Next Plan: To verify the actuator condition ( to remove valve stem coupling and function stroke test).</span></p><p><br></p></td></tr></tbody></table><p></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-02_HCV-11H04 _ TS choke valve stuck', '2024-10-02 15:09:14', '2024-10-07 07:44:49', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HCV-11H04', 'ZTK-HCV-11H04', 'Valve Choke on 6''''GC11H01-J70 for Well H', NULL, NULL, 'Valve Choke on 6''''GC11H01-J70 for Well H', 'WP11', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Brown', NULL, 'EXTERNAL', '2024-10-02 15:09:14', '2024-10-07 07:44:49', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Joseph', NULL, 'EXTERNAL', '2024-10-02 15:09:14', '2024-10-07 07:44:49', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
