  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To install biocide pump and unblocked solenoid', 'Electrical & Instrument', 'CM ', 'Completed', '2024-10-03', '<p><b>Activity</b>: P-0299C, To install the biocide pump and troubleshoot solenoid valve, SOV-02947, on biocide injection to export pipeline is blocked</p><p>Action: Installed the biocide pump.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found the solenoid is function properly.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; The filter for solenoid is already removed and confirmed spacer is installed already.<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked the discharge pressure of the pump is build-up. (Discharge Pressure - OK)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Checked if the level is dropped when the pump is running. (Discharge Flow - OK)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Checked if the pump is functioning as per 8 ml/min. (Pump stroke and oscillator Check - OK)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Checked the IG line if leak or not. (OK)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Checked if the dampener is good or not as well. (OK)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Checked if the solenoid blocked is clear or not by confirming closing SOV-02946 (Test separator line). (OK)<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Now, the pump and solenoid black are cleared and are back to service<br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-03_P-0299C,To install biocide pump and unblocked solenoid">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-03_P-0299C,To install biocide pump and unblocked solenoid</a><br></p>', '2024-10-03 16:01:07', '2024-10-03 20:21:16', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
