-- Inserting report ID 33611
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace bearings', 'Mechanic', 'CM ', 'Completed', '2024-10-03', '<p>Work - Replace defected bearings (upper and lower bearings)</p><p>Found - Upper bearing cage is broken and balls come out.</p><p>Action</p><p>- Erect scaffoldings.</p><p>- Assemble lifting gears.</p><p>- Disconnect greasing line and vibration probe.</p><p>- Remove fan sprocket.</p><p>- Lay down the sprocket on the floor and inspect. Found a good condition.</p><p>- Remove fan blade.</p><p>- Secure the fan blade with structure.</p><p>- Remove bearings and shaft with hyd pusher.</p><p>- Clean the bearings area on the shaft surface.</p><p>- Install bearings and adjust alignment.</p><p>- Re-connect greasing line and apply grease.</p><p>- Exercise bearings.</p><p>- Install fan sprocket and fan blade.</p><p>- Install dropped protection disc on shaft.</p><p>- Measure fan blade tip clearance.</p><p>- Install belt and adjust tension (26Hz)</p><p>- Measure alignment and found Ok.</p><p>- Reinstate the fan guard and perform housekeeping</p><p>- Perform test run and found normal.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\GAS COOLER FAN (E-4360-A and E-4360B)\\E-4360 (2nd Stage)\\E-4360A\\2024\\2024-10-03 Replace Bearings">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\GAS COOLER FAN (E-4360-A and E-4360B)\\E-4360 (2nd Stage)\\E-4360A\\2024\\2024-10-03 Replace Bearings</a><br></p>', '2024-10-04 11:09:47', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EF-4360A', 'ZTK-EF-4360A', '2nd Stg Comp Disch Cooler Fan A', NULL, NULL, '2nd Stg Comp Disch Cooler Fan A', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Oak', NULL, 'EXTERNAL', '2024-10-04 11:09:47', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
