BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To overhaul the accumulator removed from WP06 WHCP', 'Electrical & Instrument', 'OTH ', 'In Progress', '2024-10-04', '<p><b>Today Activity:&nbsp;</b></p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Already installed the pop-up ring.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; TIghtened the pop-up ring seat and nuts.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp;Checkedleak of the bladder by charging air up to 10 bar and 20 bar.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp;Found that there is seeping from seal washer of bladder.&nbsp;</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; (<i>Don''t have new spare for seal washer)</i></p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Applied teflon and checked if there is still seeping from that seal washer of bladder.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; Still a bit seeping and the pressure can''t hold.&nbsp;</p><p>&nbsp;</p><p><i>Note:</i>&nbsp; &nbsp; Need to replace that seal washer. (To use new one).<i><br></i><br></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History:</span></p><p><span style="background-color: rgb(255, 255, 0);">04-10-2024:</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Inserted the new bladder into the accumulator. (Completed).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Assembled the bladder port side. (Completed).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Installed the gasket seal, back-up O-ring into the pop-up. (Completed).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Installed the pop-up ring and aligned into the pop-up seat. (Completed).</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Job is progress.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan:&nbsp;&nbsp;&nbsp; Still need to align the pop-up seat onto the accumulator and tightened.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Still need to charge N2 and check leak.<br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History</span></p><p><span style="background-color: rgb(255, 255, 0);">01-10-2024</span></p><p><span style="background-color: rgb(255, 255, 0);">Activity:&nbsp;To overhaul the accumulator removed from WP06 WHCP at workshop.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp; &nbsp; Removed the bladder from the accumulator.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan:&nbsp; &nbsp; - Going to insert the new bladder into the accumulator.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp;Going to insert the pop-up ring and new seat plus gasket and oring.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -&nbsp;Going to charge nitrogen.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Tools important:</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; C-clamp spanner :&nbsp; &nbsp; 110-115</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Adjust Wrench&nbsp; &nbsp; :&nbsp; &nbsp; 30"</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; -&nbsp; &nbsp; Spanner&nbsp; &nbsp; :&nbsp; &nbsp; 1"</span></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-04_Accumulator, To overhaul the accumulator removed from WP06">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-04_Accumulator, To overhaul the accumulator removed from WP06</a><br></p>', '2024-10-04 15:37:15', '2024-10-06 08:25:27', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
