DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S solenoid blocked at CI skid', 'Electrical & Instrument', 'CM ', 'Completed', '2024-10-04', '<p>Activity:&nbsp;</p><p>SOV-15016, T/S solenoid valve on CI injection to test manifold is blocked</p><p>SOV-15018, T/S biocide seeping from solenoid body (biocide injection to test manifold)</p><p>SOV-15020, T/S solenoid valve on CI injection to prod manifold is blocked</p><p>SOV-15022, T/S solenoid valve on biocide injection to prod manifold is blocked</p><p>Action: For SOV-15016, Fixed the blockage of solenoid</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; For SOV-15020, Fixed the blockage of solenoid&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; For SOV-15018, Replaced the solenoid with spare one</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; For SOV-15022, Replaced the manifold of solenoid&nbsp;</p><p>Now, All SOVs are back to service</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-04_TS SOV-15016,15018,15020,15022_ solenoid blocked', '2024-10-04 15:44:07', '2024-11-06 15:59:33', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
