  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Help to support in T/S portable air comp', 'Electrical & Instrument', 'OTH ', 'In Progress', '2024-10-05', '<p>Activity: Supported on troubleshooting portable air compressor for running for crane PM at WP-03.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - As per informed, found that there is no any power signal to the control panel.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Checked the battery voltage: around 12.4 Vdc.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Checked the starting switch and its wiring terminal if loosen or not. Good.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Checked the emergency push button and its wiring. (Emergency push button is good but there is a cable broken inside the terminal.)&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Fixed the broken cable. Good.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Checked the fuel solenoid line. Good.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Started the air compressor, the engine is cranking but can''t started.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Suspected that there is blockage along the fuel line.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Tomorrow, the oilstate team will keep troubleshooting for that line.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Informed oilstate team to use for that air compressor and keep 12V battery for reserve at workshop.<br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-05_WP-03,TS portable air comp unable to start">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-05_WP-03,TS portable air comp unable to start</a><br></p>', '2024-10-05 22:57:49', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
