  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SK-7610', 'ZTK-SK-7610', 'FM-200 for Topside Main Deck Skid', NULL, NULL, 'FM-200 for Topside Main Deck Skid', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
