-- Inserting report ID 33638
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify the air lock pressure low alarm PDT-86531', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-10-06', '<p><b>Activity</b>: To verify the air lock pressure low alarm (monthly alarm management report) PDT-86351. (Day 1)</p><p><b>Action:&nbsp;</b> &nbsp;- Checked the as-found differential pressure for PDT-86351 which is around 10-17 Pa which is Low Alarm.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; (Alarm Settings: Low = 20 Pa, High = 75 Pa)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; (Alarm Reset Settings: Low = 21 Pa, High = 74 Pa)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; <i>Therefore, the PDTs readings should be more than 20 Pa</i><br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Checked at local if the PDT-86351 is good or not. (Good)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -&nbsp; Checked the PDT sensing points for low and high (low: atmosphere pressure, high: room pressure) are blocked. (Not block, Good)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -&nbsp; Monitored that the reading for PDT-86351 and PDT-86353 which are for level 3. (Almost same, so confirmed that the PDT is good)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -&nbsp; Found as well that the PDTs for level 2 and 4 are also low.<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -&nbsp; Checked HVD-86341 which is the air supply line to the air lock room near PDT-86351, and found that only 20% opened.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -&nbsp; &nbsp;Opened HVD-86351 to 80% and also checked other HVDs for level 2 and level 3 corridor area and adjusted to open more.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -&nbsp; &nbsp;Checked if PDTs readings for level 2 and level 3 are increased more or not. (increased)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; (PDT-86351 and PDT-86353 for level 3 : ~ 28 - 31 Pa,&nbsp; PDT-86251 and PDT-86253 for level 2 : ~ 26 - 31 Pa)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -&nbsp; &nbsp; Opened one of the corridor door and closed back. During that time, found that the pressure is dropped to 12 Pa and built up to 25 Pa within 10 sec.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp; &nbsp;Checked if the door are properly locked and sealed, and found that one door in level 3 (production side) is not properly locked and sealed.</p><p><br></p><p><b>Job Status:</b>&nbsp; &nbsp; The job is completed. Kept Under Monitoring whether the pressure drop alarm come or not.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The alarm delay settings in the PLC is 3600 sec.<br></p><p><br></p><p><i><b>Note:</b></i>&nbsp; &nbsp; -&nbsp;<i>Whenever we open the stair case door from level 3 or 2 or 1, there are much pressure drop in PDTs for air lock room pressures since we kept the stair case pressurization fan is off.&nbsp;</i></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -&nbsp;<i>We do not adjust the air flow line to individual room, we just only adjusted for corridor air flow.</i></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-06_PDT-86351, To verify the air lock pressure low alarm">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-06_PDT-86351, To verify the air lock pressure low alarm</a><br></p>', '2024-10-06 16:15:03', '2024-10-21 15:26:51', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PDT-86351', 'ZTK-PDT-86351', 'PDT,LQM LVL 3 Air Lock Room,AL HI/LO', NULL, NULL, 'PDT,LQM LVL 3 Air Lock Room,AL HI/LO', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-10-06 16:15:03', '2024-10-21 15:26:51', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Francis', NULL, 'EXTERNAL', '2024-10-06 16:15:03', '2024-10-21 15:26:51', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-TeamLead');
END $$;

