  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify the galley supply and exhaust fan stop', 'Electrical & Instrument', 'OTH ', 'In Progress', '2024-10-07', '<p><strong>Activity,</strong></p><p>-Verified the galley supply and exhaust fans are stopped as per requested from chef.</p><p><strong>History,</strong></p><p>-NA</p><p><strong>Equipment description and location,</strong></p><p>-Galley Supply and Exhaust Fans, LQM Level 4.</p><p><strong>As found,</strong></p><p>-(1)No incoming power in MCC-LQM-8670B Control Panel for galley supply and exhaust fans.</p><p>-(2)No any breakers trip inside that MCC-LQM-8670B.</p><p><strong>What happen,</strong></p><p>-Main circuit breaker for MCC-LQM-8670B (F5-24), was tripped in ESWG-LQM-320, Level 1.&nbsp;</p><p><strong>Action,</strong></p><p>-Run unit A for galley supply and exhaust fans (B-8670A and B-8745A) for galley room.</p><p>-Checked the main circuit breaker for MCC-LQM-8670B (F5-24) in ESWG-LQM-320, Level 1.</p><p>-Found that alarm Indicator LED status was "Steady ON" in the FDM121 Front Display Module of the circuit breaker for MCC-LQM-8670B (F5-24).</p><p>-Checked the alarm and found Code 1024 in the event log and 1029 in status and control.</p><p>-Informed to team leader and supervisor about the condition.&nbsp;</p><p>-Not reset any breakers as per replied from supervisor in order to trace the root cause in troubleshooting.</p><p><strong>As left,</strong></p><p>-The unit B for MCC-LQM-8670 is not available.</p><p>-Keep the main feeder breaker trip as in as-found condition.</p><p><strong>Next Plan,</strong></p><p>-Going to troubleshoot tomorrow.</p><p><strong>Documentation,</strong></p><p>-NA</p><p><strong>Job Progress,</strong></p><p>-5%</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-07_MCC-CPP-7890B,">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-07_MCC-CPP-7890B,</a><br></p>', '2024-10-07 18:26:41', '2024-10-07 23:12:25', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
