-- Inserting report ID 33684
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform to T/S Choke valve H not working', 'Mechanic', 'CM ', 'Completed', '2024-10-09', '<p>Problem: choke valve is not working properly (cannot close or open,only 10% working up or down)</p><p>Found: choke valve actuator is working as normal when removed coupling of stem</p><p>Action : depressurize the choke valve vent plug from body trap pressure (by 3/4 spanner)</p><p>- remove 8 ea L key bolt for actuator mounting (1/2 " L key)</p><p>- remove packing gland follower nut (60mm)&nbsp;</p><p>- loosen the bonet 8 bolt with 55 mm and hammer wrench</p><p>- lift the actuator with two chain block. cause of support structure is too close and not enough head room to install chain hoist</p><p>-&nbsp;<span style="background-color: rgb(255, 0, 0);"><font color="#ffffff">Do not remove all bolt from bonnet, left two for any trap pressure</font></span></p><p><span style="background-color: rgb(255, 255, 255);">- Lift the bonnet with eye bolt&nbsp;</span></p><p>- remove seal and trim kit and found too much sand in valve body</p><p><span style="background-color: rgb(255, 255, 255);">- clean the valve body inside&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 255);">- replace the new trim kit and seal kit</span></p><p>- install back inside of valve body</p><p><span style="background-color: rgb(255, 255, 255);">- replace stem packing</span></p><p><span style="background-color: rgb(255, 255, 255);">- install back bonnet and actuator</span></p><p><span style="background-color: rgb(255, 255, 255);">- retighten the valve body vent plug</span></p><p><span style="background-color: rgb(255, 255, 255);">- tighten the bonnet bolt with 80Nm,170Nm,260Nm,300Nm with 4 time multiplier</span></p><p><span style="background-color: rgb(255, 255, 255);">- pressure test and passing test with 40 bar, found no leak.</span></p>', NULL, '2024-10-11 14:54:20', '2025-01-16 11:19:41', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-TeamL', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HCV-11H04', 'ZTK-HCV-11H04', 'Valve Choke on 6''''GC11H01-J70 for Well H', NULL, NULL, 'Valve Choke on 6''''GC11H01-J70 for Well H', 'WP11', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Henry', NULL, 'EXTERNAL', '2024-10-11 14:54:20', '2025-01-16 11:19:41', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-TeamL');
