  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS sewage treatment package malfunction', 'Electrical & Instrument', 'CM ', 'Completed', '2024-10-11', '<p><b><u>Activity,</u></b></p><p>-TS sewage treatment X-7300&nbsp;package malfunction.</p><p><u><b>History,</b></u></p><p>-NA.</p><p><u><b>Equipment description and location,</b></u></p><p>-X-7300 Sewage Treatment Package, Sea Deck(West Side)</p><p><u><b>As found,</b></u></p><p>-Unit stopped by emergency stop.</p><p><u><b>What happen,</b></u></p><p>- Macerator pump cannot be stopped.</p><p>- HMI malfunction</p><p>- Level transmitter reading error</p><p><u><b>Action,</b></u></p><p>-Checked the HMI touch screen that found normal operated.</p><p>-Released the emergency stop and compared the level transmitter (18%) and level gauge(21%) values.</p><p>-Values are acceptable range which different only about 3%.</p><p>-So, tested run the Macerator pump by manual and confirm to stop at 15%.</p><p>-After confirm stopped, inform operator to fill the tank level over 35% to function test the pump by auto start.</p><p>-Monitored the operation cycle that pump started at 35% and stopped on 15% on auto sequence as normal.</p><p>-Confirmed with operator for another 2 cycles and pump operating sequences and all function are working normal.</p><p><u><b>As left,</b></u><br></p><p>-Unit available with auto operation mode.&nbsp;</p><p><u><b>Next Plan,</b></u><br></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job Progress,</b></u></p><p>-100% completed.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-11_X-7300, TS Sweage treatment package malfunction', '2024-10-11 16:06:10', '2024-10-14 08:43:49', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-7300', 'ZTK-X-7300', 'Sewage Treatment Package', NULL, NULL, 'Sewage Treatment Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2024-10-11 16:06:10', '2024-10-14 08:43:49', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Grayson', NULL, 'EXTERNAL', '2024-10-11 16:06:10', '2024-10-14 08:43:49', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop');
