-- Inserting report ID 33691
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS washing machine malfunction', 'Electrical & Instrument', 'CM ', 'Completed', '2024-10-12', '<p><b><u>Activity</u>,</b></p><p>-To verify the washing machine LD01A''s door cannot open because water cannot drain form drum.</p><p><b><u>History</u>,</b><br></p><p>-NA</p><p><b><u>Equipment description and location</u>,</b></p><p>-Washing Machine A, Laundry Room.</p><p><b><u>As found</u>,<br></b>- Unit out of service</p><p><b><u>What happen</u>,</b></p><p>- Found the alarm and door cannot open.</p><p><b><u>Action</u>,</b></p><p>- Hard reset the washing machine for alarm clear but cannot.</p><p>-Removed the back side cover and checked the drain system condition.</p><p>-Found that main flexiable drain pipe orienatation was lower than it should be.</p><p>-Lifted the drain pipe and all water drain out.</p><p>-After completed drain out,alarm can reset.</p><p>-Found the drain pipe support was deviated and can support only back side of the drain pipe.</p><p>-Drain pipe front side have slope and water cannot drain out.</p><p>-Realined the drain pipe support and tie with cabel tie to maintain it position.</p><p>-Tested run the washing machine and checked the drain system that can drain properly.<br></p><p><b><u>As Left</u>,</b></p><p>-Unit avaliable.</p><p><b><u>Next Plan</u>,</b><br></p><p>-NA</p><p><b><u>Documentation</u>,</b></p><p>-NA.</p><p>-Link ()<br></p><p><b><u>Job Progress</u>,</b></p><p>-100%</p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-12_LD01A, Washing machine malfunction', '2024-10-12 14:02:55', '2024-10-12 17:31:38', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LQM-LAUNDRY', 'ZTK-LQM-LAUNDRY', 'Laundry Room', NULL, NULL, 'Laundry Room', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
