  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To rectify discharge dampener of WP-14 sump pump', 'Electrical & Instrument', 'OTH ', 'Completed', '2024-10-15', '<p><b><u>Activity</u></b><b>,</b></p>  <p>-To rectify discharge dampener of WP-14 sump pump</p>  <p><b><u>History</u></b><b>,</b></p>  <p>-Continued job from 25 August 2024.</p><p>-HRC clearance for No.0157/2024/ZPQ.</p>  <p><b><u>Equipment description and location</u></b><b>,</b></p>  <p>-P-1452, Closed drain sump pump</p>  <p><b><u>As found</u></b><b>,</b></p>  <p>-The dampener was not fully tightened and Teflon tape was used for BSPP thread type which is improper&nbsp; &nbsp; &nbsp; &nbsp;installation during project stage.</p>  <p><b><u>What happen</u></b><b>,</b></p>  <p>-During sump pump running ,dampeners were loosen by high vibration which case of improper installation.</p>  <p><b><u>Action</u></b><b>,</b></p>  <p>-Removed the discharge dampener from the process flange and tightened the damper.</p><p>-Removed the suction dampener form the process flange to confirm the installation method.</p><p>-After removed, found that teflon tape was used for damper thread as improper installation.</p><p>-Cleaned the damper thread for reinstallation and fully tightened with process flange.</p>  <p>-Checked the discharge and suction dampeners condition which are normal condition during test with&nbsp; &nbsp; &nbsp; &nbsp;sump pump running.</p>  <p><b><u>As left</u></b><b>,</b></p>  <p>-Both dampeners were not loosen even the pump running state.</p>  <p><b><u>Next plan</u></b><b>,</b></p>  <p>-N/A</p>  <p><b><u>Documentation</u></b><b>,</b></p>  <p>-HRC clearance for No.0157/2024/ZPQ</p>  <p>-Link ()</p>  <p><b><u>Job progress</u></b><b>,</b></p>  <p>-100%</p>  <p>&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-15_P-1452,To rectify discharge dampener of WP-14 sump pump', '2024-10-15 15:47:54', '2024-10-15 22:09:37', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-1452', 'ZTK-P-1452', 'Sump Pump Deliver from V-1451 to WP04', NULL, NULL, 'Sump Pump Deliver from V-1451 to WP04', 'WP14', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
