  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S BSD-310 Loop Fault Alarm at AFDS panel', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-10-17', '<p><u><b>Activity,</b></u></p><p>-T/S BSD-310 Loop Fault Alarm at AFDS panel</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-Addressable fire and gas detection system<br></p><p><u><b>As found,</b></u></p><p>-BSD-310 loop-1 fault alarm at AFDS panel.&nbsp;</p><p><u><b>What happen,</b></u></p><p>-Suspected that one of the device has intermitted fault .</p><p><u><b>Action,</b></u></p><p>-Perform disable the loop 1 of BSD-310 at AFDS panel.</p><p>-Remove the loop-1 (M3) terminal contactor from loop driver module BSD-310.</p><p>-Connect to WAS-2000 (AUTRONICA fire and security).</p><p>-Connect to the laptop and run software AS-2000.</p><p>-During scanning the loop, there is no loop breakdown and all devices (41 detectors) are normal condition.</p><p>-Normalize the loop-1 connection and enable the BSD-310.</p><p>-Reset and clear the fault alarm.</p><p><u><b>As left,</b></u><br></p><p>-There is no any abnormal fault alarm.</p><p><u><b>Next Plan,</b></u></p><p>-Keep monitor alarm for a week.</p><p>-If alarm come again, continue to check the connection and condition of 41 detectors at LQM level-1.</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job Progress,</b></u></p><p>-Under monitoring.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-17_AFDS, TS BSD-310 loop fault', '2024-10-17 16:05:39', '2024-10-17 16:30:25', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SFGS-AFDS', 'ZTK-SFGS-AFDS', 'Addressable Fire & Gas Detection System', NULL, NULL, 'Addressable Fire & Gas Detection System', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Peter', NULL, 'EXTERNAL', '2024-10-17 16:05:39', '2024-10-17 16:30:25', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine');
