  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Hypochlorite rectifier not on', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-10-18', '<p><u><b>Activity</b></u>,</p><p>-TS hypochlorite package cannot produce product as per demand (Day 1).</p><p><u><b>History</b></u>,</p><p>-N/A.</p><p><u><b>Equipment description and location</b></u>,</p><p>-DC Rectifier Transformer, Hypochlorite Package, Lower Deck.</p><p><u><b>As found</b></u>,</p><p>-(1) Rectifier functioning properly.</p><p>-(2) Rectifier DC output voltage and current feedback values are not same with HMI and rectifier voltmeter and ammeter.</p><p><u><b>What happen</b></u>,</p><p>-(1) NA.</p><p>-(2) Existing transducers for DC output voltage and current feedback need to adjust to be same with new rectifier transformer.</p><p><u><b>Action</b></u>,</p><p>-(1) Adjusted DC current from PCS and found that transformer rectifier DC output current feedback is functioning as per CCR command.</p><p>-(2) When DC current adjustment from PCS is (14 A), DC output current feedback shows at HMI (15A) and rectifier ammeter shows (10.8 A). Normal operation for DC current adjustment is around 14 A to15 A. Suspected hypochlorite concentration for lab result is not pass due to the actual transformer rectifier DC output current value is lower than feedback value.</p><p><u><b>As left</b></u>,</p><p>-Informed CCR to command DC current adjustment from PCS at 20 A and to check lab result again. (Rectifier output ammeter shows 17.1A)&nbsp;</p><p><u><b>Next plan</b></u>,</p><p>-If the lab result is pass, will adjust the existing transducers for DC output voltage and current feedback to be same with rectifier output ammeter. </p><p>-If the lab result is fail, will check the bipolar tube condition.</p><p><span style="background-color: rgb(255, 255, 0);">!!!(As per 19 Oct 2024 result, NaOCI concentration is still low 6.2mg/l at rectifier current setting 25A)</span></p><p><u><b>Documentation</b></u>,</p><p>-N/A</p><p>-Link ()</p><p><u><b>Job progress</b></u>,</p><p>-50%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-18_ZTK-TR-6640, TS hypochlorite rectifier not on', '2024-10-18 14:43:02', '2024-10-19 13:33:48', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-6640', 'ZTK-X-6640', 'Hypochlorite Package', NULL, NULL, 'Hypochlorite Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
