  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S SDV shows fault when CCR command open', 'Electrical & Instrument', 'CM ', 'Completed', '2024-10-18', '<p><b><u>Activity</u></b><b>,</b></p>  <p>-T/S SDV shows fault when CCR command open</p>  <p><b><u>History</u></b><b>,</b></p>  <p>-NA</p>  <p><b><u>Equipment description and location</u></b><b>,</b></p>  <p>-Shut down valve at liquid Outlet line of V-6220B Fuel Gas Filter Separator, SDV-62211B</p>  <p><b><u>As found</u></b><b>,</b></p>  <p>-SDV cannot open when CCR command.</p>  <p><b><u>What happen</u></b><b>,</b></p>  <p>-There is no DO output voltage for SIS solenoid (SOV-62211B-A)&nbsp;&nbsp;</p>  <p><b><u>Action</u></b><b>,</b></p>  <p>-Request CCR to command open and close for shutdown valve. Found SDV is not moving.</p><p>-Check solenoid supply voltage of (SOV-62211B-B) when CCR command opened. Found 24 VDC.</p><p>-Check solenoid supply voltage of (SOV-62211B-A). Found there was 1.5 VDC.</p><p>-Check the wiring loop for SOV-62244BA at marshalling cabinet (MSH-CPP-243/TP30, terminal 11 &amp;12). Found 1.5VDC. Check fuse condition at terminal 11, it is normal.</p><p>-Check the DO output voltage at (MSH-CPP-243/TPDO-21). Found 1.5 VDC. (Look like no output at DO card for SOV-62211BA)</p><p>-Request automation team to check at SIS digital output signal for SOV-62211BA.</p><p>-Perform enable DO signal at SIS by automation.</p><p>-Check the voltage for SOV-62211BA, found supply voltage 23.43 VDC.</p><p>-Request CCR to command open for SDV-62211B.</p><p>-Found SDV can open and close properly.&nbsp;&nbsp;</p><p><b><u>As left</u></b><b>,</b><br></p>  <p>-NA</p>  <p><b><u>Next plan</u></b><b>,</b></p>  <p>-NA</p>  <p><b><u>Documentation</u></b><b>,</b></p>  <p>-NA</p>  <p><b><u>Job progress</u></b><b>,</b></p>  <p>-Completed.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-18_SDV-62211B, TS shut down valve cannot open', '2024-10-18 16:06:17', '2024-10-18 18:06:47', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SDV-62211B', 'ZTK-SDV-62211B', 'SDV on V-6220B Condt Outlet,ESD 3ND,3LJ', NULL, NULL, 'SDV on V-6220B Condt Outlet,ESD 3ND,3LJ', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
