  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S ZWP12 Crane engine unable to start.', 'Mechanic', 'CM ', 'Completed', '2024-10-20', '<p><b>Description: Verified and troubleshot the crane engine unable to start after several attempts by operators.</b></p><p><br></p><p><u>As found condition;</u></p><p>-Checked the diesel day tank level indicator. <span style="background-color: rgb(255, 255, 0);">(found 1/4 of indicator).</span></p><p>-Checked the diesel day tank level by disconnecting the supply line. (diesel come out).</p><p><br></p><p><u>Working execution steps:</u><br></p><p>-Disconnected the filling port and visually checked the level.</p><p>-Topped up the<b> diesel 40 Liters. (up to 3/8 of indicator)</b></p><p>-Checked the hydraulic accumulator pressure.</p><p>-Pumped out the air from the fuel system lines by manual pumping.</p><p>-Started the engine and able to start by <b>1st time attempt.</b></p><p><br></p><p><u>Root cause</u></p><p>-Day tank suction head&nbsp; is low enough to happen air gap trapped in the system.&nbsp;</p><p><br></p><p><u>Note</u></p><p>-Checked and verified the diesel transfer pump unable to run.</p><p>-Found the IG inlet pressure <b>3bar.</b></p><p>-Found the pump discharge<b> pressure gauge malfunction</b> as EI verified.</p><p>-Found<b> no pressure</b> in the pump discharge line when releasing the pressure from the pump discharge pressure gauge.</p><p>-<span style="background-color: rgb(255, 255, 0);">Troubleshooting is in progress.</span></p><p>&nbsp;</p><p><u>Photo line in details</u></p><p><a href="M:\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP12\\Crane CR-1273\\2024\\2024-10-21 TS engine can''t stop">M:\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP12\\Crane CR-1273\\2024\\2024-10-21 TS engine can''t stop</a><br></p>', '<p>-To follow crane pre-post inspection properly.</p><p>-Continue to troubleshoot the diesel transfer pump unable to start.</p>', '2024-10-21 08:25:47', '2024-10-21 09:46:36', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-1273-EN', 'ZTK-CR-1273-EN', 'Pedestal Crane Diesel Engine WP12', NULL, NULL, 'Pedestal Crane Diesel Engine WP12', 'WP12', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
