  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS choke valve stuck', 'Mechanic', 'CM ', 'Completed', '2024-10-24', '<p>Problem - Choke valve is stuck.</p><p>Action - Perform function test by EI team</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Choke valve can go between 15% to 50 % and can''t close fully&amp; can''t open fully.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Performed process isolation.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Performed hydraulic line isolation for actuator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Installed lifting gear for lifting process.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Job is not completed yet and waiting for next trip.</p><p><br></p><p><u style="background-color: rgb(255, 255, 0);">2024-10-24</u></p><p>Action - Remove actuator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Remove bonnect.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Found a lot of sand and stucking the cage with the seat.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Dismantle choke valve internal parts and remove all seal kit.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Clean and inspect the choke valve internal parts and inside body.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Found good condition of choke valve internal parts and inside body.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replaced seal kit set.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Install back choke valve internal parts and install bonnet.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Tighten the bonnect bolts (55mm)&nbsp; with torque (1200 Nm).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Install the actuator and perform function test.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Perform leak test with 63 bars and found no leak.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP11\\Choke valve\\HCV-11H04\\2024\\2024-10-21 TS choke valve stuck">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP11\\Choke valve\\HCV-11H04\\2024\\2024-10-21 TS choke valve stuck</a><br></p>', '2024-10-21 09:08:57', '2024-10-24 22:19:25', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
