  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To overhaul the spare anti-surge valve', 'Electrical & Instrument', 'OTH ', 'Completed', '2024-10-21', '<p><strong><u>Activity,</u></strong></p><p>-To overhaul the spare anti-surge valve (Day 3)</p><p><strong><u>History,</u></strong></p><p>--Continue job from 20-Oct-2024.</p><p><strong><u>Equipment description and location,</u></strong></p><p>-Spare anti-surge valve for 2nd stage compressor, FV-4X530</p><p><strong><u>As found,</u></strong></p><p>-Valve feedback is overshooting.</p><p><strong><u>What happen,</u></strong></p><p>-NA</p><p><strong><u>Action,</u></strong></p><p>-Insert the basic setup value (Actuator spring type, transmitter configuration and etc..) of DVC-6200 AD for anti-surge valve.</p><p>-Connect valve link software and perform tuning for valve travel control and pressure control with expert mode.</p><p>-Exercise with step response and check the feedback graph.</p><p>-Found the feedback result of&nbsp; valve travelling( Open/close) is satisfied (no overshooting) and within the command range.</p><p>-Make valve link Report and keep the result of data.</p><p><strong><u>As left,</u></strong></p><p>-NA</p><p><strong><u>Next Plan,</u></strong></p><p>-To Keep at ZPQ lower deck transformer area for spare readiness (Full shut down).</p><p><b><u>Documentation,</u></b></p><p>-Link&lt;&lt;V:\\Department Share\\04_MAINTENANCE\\03 E&amp;I\\16 Knowledge sharing\\0.5 Equipment Replacement\\Anti-surge valve replacement\\2024 Overhaul and tuning\\Valve link report FV-4X530</p><p><b><u>Job Progress,</u></b></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-21_FV-4X530, Overhaul antisurge valve', '2024-10-21 17:03:44', '2024-10-21 17:24:32', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
