BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S wireless gateway malfunction', 'Automation', 'CM ', 'Completed', '2024-10-25', '<p><u><b>Activity,</b></u></p><p>-T/S wireless transmitters reading value cannot see in SCADA and HMI.</p><p><u><b>History,</b></u></p><p>-NA.</p><p><u><b>Equipment description and location,</b></u></p><p>- Wireless gateway</p><p><b><u>As found,</u></b></p><p>- The wireless transmitters reading cannot see in SCADA and HMI.</p><p><b><u>What happen,</u></b></p><p>- The function is disable at local HMI.</p><p><u><b>Action,</b></u></p><p>- Checked and compared the local wireless transmitters reading vaule and PLC.</p><p>- All reading are same.</p><p>- Changed "Manned" on local HMI.</p><p>- Login "Maint".</p><p>- Checked the wireless status in HMI.</p><p>- Found that the wireless reading are disabled.</p><p>- Changed the wireless transmitter reading enabled.</p><p><b><u>As left,</u></b></p><p>- Now all reading from wireless transmitters can read from local HMI and SCADA.</p><p><b><u>Next Plan,</u></b></p><p>-N/A</p><p><u><b>Remark,</b></u></p><p>- To read data from wireless transmitters need to enable at local HMI at wireless status page.</p><p>- To enable, need to "Manned" and login "Maint".</p><p><u><b>Documentation,</b></u></p><p>-None</p><p><u><b>Job Progress,</b></u></p><p>-Completed.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-25_WP15, TS wireless gateway malfunction', '2024-10-25 15:33:41', '2024-10-25 21:15:40', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
