  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To rectify air leak at WEIR Batley valve', 'Electrical & Instrument', 'CM ', 'In Progress (Completed)', '2024-10-26', '<p><b><u>&nbsp; Activity</u></b><b>,</b></p>  <p>- To rectify air leak at WEIR Batley valve (PV-41015B) (Day 4).</p>  <p><b><u>History</u></b><b>,</b></p>  <p>- Continued job from 22 Oct, 24 Oct and 25 Oct 2024.</p>  <p><b><u>Equipment description and location</u></b><b>,</b></p>  <p>- Control valve at V-4100 gas outlet to HP flare, Main Deck</p>  <p><b><u>As found</u></b><b>,</b></p>  <p>-(1) Air passing at WEIR Batley valve vent port.</p>  <p><b><u>What happen</u></b><b>,</b></p>  <p>-(1) Valve internal diaphragm deformed.</p>  <p><b><u>Action</u></b><b>,</b></p>  <p>-Replaced both Open and Close volume boosters with new spare for reliability.</p>  <p>-(1) Route tubing and replace damaged WEIR Batley valve with old trip valve (Fisher 377D).&nbsp;</p><p>-Performed function test with CCR, control valve can operate properly but old (Fisher 377D) trip valve vent port is still passing.</p><p>-Upon tracing and line up check, found trip valve pilot supply line was not installed as per GA.</p>  <p><b><u>As left</u></b><b>,</b></p>  <p>-Unit is available but trip valve vent is still passing.</p>  <p><b><u>Next plan</u></b><b>,</b></p>  <p>-To replace old trip valve with new spare trip valve (Fisher 377D).</p><p>-To relocate the tubing of trip valve IA pilot supply line as per GA.</p>  <p><b><u>Documentation</u></b><b>,</b></p>  <p>-N/A</p>  <p>-Link ()</p>  <p><b><u>Job progress</u></b><b>,</b></p>  <p>-95%</p>  <p>&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-26_PV-41015B, To rectify air leak at trip valve', '2024-10-26 15:34:40', '2024-10-28 08:49:28', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PV-41015B', 'ZTK-PV-41015B', 'PCV B,Ctrl V-4100 Gas Outlet to HP Flare', NULL, NULL, 'PCV B,Ctrl V-4100 Gas Outlet to HP Flare', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
