BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To replace fire damper enclosure air inlet', 'Electrical & Instrument', 'CM ', 'In Progress (Completed)', '2024-10-26', '<p><strong><u>Activity</u>,</strong></p><p>-To replace fire damper enclosure air inlet.(Day-2)</p><p><strong><u>History</u>,</strong></p><p>-Continued job from 25-Oct-2024.</p><p><strong><u>Equipment description and location</u>,</strong></p><p>-Fire damper enclosure air inlet, HFD-72131-7.</p><p><strong><u>As found</u>,</strong></p><p>-Two flapper of damper was broken.</p><p><strong><u>What happen</u>,</strong></p><p>-Badly corroded at joint of flapper and shaft.</p><p><strong><u>Action</u>,</strong></p><p>-Clean all the surface of flange joint between enclosure inlet and elbow air intake.</p><p>-Apply silicone to all surface of joints.</p><p>-Replace new fire damper and perform manual exercise. (working properly)</p><p>-Install enclosure air inlet elbow and tighten all bolts and nuts for surface joint.</p><p>-Continue to function test the damper with fire and gas activation.</p><p><strong><u>As left</u>,</strong></p><p>-After function test the damper with fire and gas activation, perform power deisolation to be unit available.</p><p>(Already function test with fire and gas activation for damper, working properly)</p><p><strong><u>Next plan</u>,</strong></p><p>-Tomorrow, continue to test run GTG-7210 and monitor enclosure pressure. (Waiting for overnight_ To dry and proper seal silicon)</p><p><strong><u>Documentation</u>,</strong></p><p>-NA</p><p><strong><u>Job progress</u>,</strong></p><p>-90% completed.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-26_HFD-72131-7, To replace enclosure air inlet damper', '2024-10-26 15:49:48', '2024-10-28 08:08:45', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
