  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS engine stop during operation', 'Mechanic', 'CM ', 'Completed', '2024-10-27', '<p>Issue: Engine stop during operation frequently.</p><p>Found: Engine oil pressure can only build up to 30 psi due to ESD is activated.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Engine oil pressure decreases gradually while engine running with load which stop the engine.&nbsp;<br></p><p>Action: Release ESD switch. Engine oil pressure can build up to 60 psi at maximum rpm and 30 psi at idle.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Monitor around 1 hour while cargo operation. Found no more engine stop.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Engine back to normal condition..<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP1\\Crane CR-0173\\2024\\2024-10-27 Troubleshoot engine stop during operation">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP1\\Crane CR-0173\\2024\\2024-10-27 Troubleshoot engine stop during operation</a><br></p>', '2024-10-27 17:47:10', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
