-- Inserting report ID 33833
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To rectify air leak at WEIR Batley valve', 'Electrical & Instrument', 'CM ', 'Completed', '2024-10-27', '<p><u><b>Activity</b></u><b>,</b></p><p>-To rectify air leak at WEIR Batley valve (PV-41015B) (Day 5).</p><p><b><u>History</u>,</b></p><p>-Continued job from 22 Oct, 24 Oct, 25 Oct and 26 Oct 2024.</p><p><b><u>Equipment description and location</u>,</b></p><p>-Control valve at V-4100 gas outlet to HP flare, Main Deck</p><p><b><u>As found</u>,</b></p><p>-(1) Air still passing at trip valve vent (Old spare Fisher337D trip valve)</p><p>-(2) IA supply tubing for trip valve pilot is wrong connection. (Not follow GA)</p><p><b><u>What happen</u>,</b></p><p>-(1) Old spare Fisher337D trip valve may be not in good condition.</p><p>-(2) Since commissioning, installation error.</p><p><b><u>Action</u>,</b></p><p>-(1) Replaced with new spare trip valve (Fisher 377D).</p><p>-(2) Relocated IA supply tubing for trip valve pilot as per GA.</p><p>-Adjusted trip valve tripping setting to 2 bar and performed function test. Found that trip activates at 2 bar and resets at 2.5 bar. (As left PCV pressure = 3 bar)</p><p>-Performed auto calibration and valve stroke test. Conducted the valve function test with CCR and confirmed that all are working properly.</p><p><b><u>As left</u>,</b></p><p>-Unit is available and no more air passing at trip valve vent.</p><p>-Actuator rarely travel and exercise beyond 83% so valve stuck time by time after 83%. Already notified to CCR. As per calculation and as build formula inside system, CCR command only till 83%.</p><p><b><u>Next plan</u>,</b></p><p>- NA</p><p><b><u>Documentation</u>,</b></p><p>- N/A</p><p>- Link ()</p><p><b><u>Job progress</u>,</b></p><p>-100% completed.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-10-27_PV-41015B, To rectify air leak at trip valve', '2024-10-27 18:24:06', '2024-10-28 08:50:22', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PV-41015B', 'ZTK-PV-41015B', 'PCV B,Ctrl V-4100 Gas Outlet to HP Flare', NULL, NULL, 'PCV B,Ctrl V-4100 Gas Outlet to HP Flare', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
