  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Paing', NULL, 'EXTERNAL', '2024-10-27 18:24:06', '2024-10-28 08:50:22', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Supv');
