BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1MPM of freshwater maker pumps both units.', 'Mechanic', 'PM ', 'Completed', '2024-10-28', '<p><b><u>Description:</u></b> Performed 1M PM of fresh water maker pumps P-6651 and P-6661. (Lube oil replacement and flush mech-seal while running.).</p><p><br></p><p><u ><b>Working steps. (both units).</b></u></p><p>-Performed self-electrical isolation the units with E-stop.</p><p>-Removed the breather port.</p><p>-Drained the lube oil.</p><p>-Flushed the pump.</p><p>-Filled up lube oil 2-1/4 quartz. (50 % of level indicator)</p><p>-De-isolated the units and test run.</p><p>-Checked any abnormal condition and leakage.</p><p>-Flushed the mech-seal while the unit running.</p><p><br></p><p>Photo links in details:</p><p><a href="M:\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2024\\2024-10-28 Performed 1M PM Lube oil replacement">M:\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2024\\2024-10-28 Performed 1M PM Lube oil replacement</a><br></p>', NULL, '2024-10-28 11:13:57', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6651-ASSY', 'ZTK-P-6651-ASSY', 'FW High Pressure Pump Assy', NULL, NULL, 'FW High Pressure Pump Assy', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
