-- Inserting report ID 33929
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS GA-28 dish washing machine stop working', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-11-05', '<p><u>Activity</u>,</p><p>-T/S dish washing machine not working.</p><p><u>History</u>,</p><p>-NA</p><p><u>Equipment description and location</u>,</p><p>-GA-28, Dish Washing Machine, Galley Equipment</p><p><u>As found</u>,</p><p>-Found that there is C12 alarm present and water leakage a lot through the pipe connection of the dish washing pan.</p><p><u>What happen</u>,</p><p>-The water pressure sensor is malfunction. The auxiliary relays, D2 and D3 got malfunction which are for heating element.</p><p><u>Action</u>,</p><p>-Isolated the main power supply line and replaced the water pressure sensor.</p><p>-Applied silicon to the the pipe connection of the dish washing pan.</p><p>-Disconnected the damaged auxiliary relays for heating element.</p><p>-Power on the main power supply line and checked if there is C12 alarm present. (No more C12 alarm)</p><p><u>As left</u>,</p><p>-There has no more C12 alarm present. But the auxiliary replays need to be replaced.</p><p>-Kept to dry the applied silicon to the pipe connection of the dish washing pan.</p><p><u>Next plan</u>,</p><p>-Need to replace the auxiliary relays.</p><p>-Need to fully function test if there is still water leakage through the pipe connection of the dish washing pan.</p><p>-Need to fully function test the dish washing pan if working properly.</p><p><u>Documentation</u>,</p><p>-NA</p><p><u>Job progress</u>,</p><p>-In progress</p>', NULL, '2024-11-06 15:03:28', '2024-11-06 15:04:32', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'Accommodation', 'Accommodation', 'Accommodation', NULL, NULL, 'Accommodation', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-11-06 15:03:28', '2024-11-06 15:04:32', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2024-11-06 15:03:28', '2024-11-06 15:04:32', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Paing', NULL, 'EXTERNAL', '2024-11-06 15:03:28', '2024-11-06 15:04:32', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
