-- Inserting report ID 33931
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S fire detector alarm at EDG', 'Electrical & Instrument', 'CM ', 'Completed', '2024-11-06', '<p><b><u>Activity</u>,</b></p><p>-T/S fire detector alarm at EDG</p><p><b><u>History</u>,</b></p><p>-During daily log sheet, found that open circuit at module 3 channel 6 fire detector alarm from EDG.</p><p><b><u>Equipment description and location</u>,</b></p><p>-Emergency diesel generator, Lower Deck</p><p><b><u>As found</u>,</b></p><p>-No active alarm during troubleshooting</p><p><b><u>What happen</u>,</b></p><p>-NA</p><p><b><u>Action</u>,</b></p><p>-Checked at UCP panel and no active alarm found but history showed open circuit at <span style="background-color: rgb(255, 255, 0);">Module 3, Channel 6 fire detectors alarm.</span></p><p>-Checked local junction box A036.2 &amp; A036.1 and found that flame detectors address at Module 4, channel 7. Confirmed this by disconnecting the resistor (R2) for flame detectors which triggered Open circuit alarm at Module 4, channel 7. Then, Normalized the system.</p><p>-Checked the wiring for module 3, channel 6 as per drawing, it addresses to the gas detector U10.&nbsp;</p><p>-Disconnected the power terminal for U10 and alarm appeared as open circuit at Module 2, channel 5. (actual wiring mis-match with the drawing)</p><p>-Continued tracing the wiring for module 3, channel 6 and found that it was actually addressed to U3, GD-72013.</p><p>-Disconnected the power terminal for U3 and alarm triggered as open circuit at Module 3, channel 6. Normalized back and tightened all wiring terminal.&nbsp;</p><p>-Suspected that intermittent alarm due to GD-72013.</p><p>-Replaced with the new detector, configured and performed calibration.</p><p>-Function test the detector and confirmed alarm with CCR.</p><p>-Normalized the EDG and performed running test in electric mode for 10 minutes.</p><p>-EDG is running properly with no abnormal alarm.</p><p><b><u>As left</u>,</b></p><p>-No active alarm and unit is available.</p><p><b><u>Next plan</u>,</b></p><p>-NA</p><p><b><u>Documentation</u>,</b></p><p>-N/A</p><p>-Link ()</p><p><b><u>Job progress</u>,</b></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-11-06_EDG-7200, TS fire detector alarm at EDG', '2024-11-06 15:59:05', '2024-11-18 21:35:38', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EDG-7200', 'ZTK-EDG-7200', 'Emergency Diesel Generator Package', NULL, NULL, 'Emergency Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2024-11-06 15:59:05', '2024-11-18 21:35:38', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Paing', NULL, 'EXTERNAL', '2024-11-06 15:59:05', '2024-11-18 21:35:38', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
