-- Inserting report ID 33956
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Remove & Overhaul PCV of Degasser LP fuel gas', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-11-09', '<p><b><u>Activity</u>,</b></p><p>-Remove &amp; Overhaul PCV of Degasser LP fuel gas</p><p><b><u>History</u>,</b></p><p>-Remove &amp; Overhaul PCV-62432, LP fuel gas to V-6310 (LP Flare KO Drum Skid)</p><p><b><u>Equipment description and location</u>,</b></p><p>-Pressure Regulator of LP Fuel Gas of Degasser to LP Flare KO Drum Skid</p><p><b><u>As found</u>,</b></p><p>-Found that the PCV cannot be adjusted.</p><p><b><u>What happen</u>,</b></p><p>-Internal diaphragm damaged. Internal debris collected.</p><p><b><u>Action (08-11-2024)</u>,</b></p><p>-Performed process isolation by operator.</p><p>-Removed the PCV from the pipe line and performed blind flange isolation to the flanges.</p><p>-Disassembly the PCV at workshop and checked inside.</p><p>-Cleaned the internal part.</p><p>-Assembly the internal part. (Only replaced one new diaphragm bcz only one is on stock. Used the old diaphragm.)</p><p>-Installed back the PCV at local.</p><p>-Replaced bolts and studs with new ones.</p><p>-Replaced new gaskets 1" #150.</p><p><b><u>Action,</u></b></p><p>-Function tested the PCV at site with operator.</p><p>-The PCV could not be adjusted, the downstream pressure always showed 4.5 bar.</p><p>-Swapped the diaphragm and spring from same size but not same type.</p><p>-Function tested again with operator and the PCV still shows 4.5 bar.</p><p>-Swapped back and normalized the original diaphragm and spring.</p><p><br></p><p><b><u>Next plan</u>,</b></p><p>-To check and function test the spare same size (but not same type) at EI Workshop if it can swap or not.</p><p>-To reserve new spare PCV.</p><p><br></p><p><b><u>Documentation</u>,</b></p><p>-NA</p><p><b><u>Job progress</u>,</b></p><p>-</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-11-09_TS PCV-62432 malfunction', '2024-11-09 15:10:12', '2025-03-09 17:56:42', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PCV-62432', 'ZTK-PCV-62432', 'Press Regulator,LP Fuel Gas to V-6310', NULL, NULL, 'Press Regulator,LP Fuel Gas to V-6310', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Francis', NULL, 'EXTERNAL', '2024-11-09 15:10:12', '2025-03-09 17:56:42', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2024-11-09 15:10:12', '2025-03-09 17:56:42', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop');
