  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S WP13 DHSV status feedback not show in HMI', 'Electrical & Instrument', 'CM ', 'Completed', '2024-11-10', '<p><u>Activity</u>,</p><p>-T/S DHSV C/Q/N/U status feedback not show in local HMI &amp;SCADA.</p><p><u>History</u>,</p><p>-N/A</p><p><u>Equipment description and location</u>,</p><p>-DHSV, Well Bay Area, WP13</p><p><u>As found</u>,</p><p>-(1) Found LED status for Network was red.</p><p><u>What happen</u>,</p><p>-(1) Found LED status for Network was red.</p><p><u>Action</u>,</p><p>-Performed hard reset for LAN cable 1 and LAN cable2. But the network status for the communication module still showed fault.</p><p>-Performed power reset for Flex I/O Dual-port Ethernet/IP adapters and Network status was back to normal.</p><p>-Function test DHSVs C/Q/N/U with CCR and found that well DHSV Q and N feedback were not shown in SCADA.</p><p>-Checked inside WHCP and Pressure Switches of Well Q and N were malfunction.</p><p>-Informed CCR to swap pressure switches of unused wells A &amp; B to Well Q and N. (Swap Well A with Q and Well B with N)</p><p>-After swapped, function test Well Q and N with CCR.</p><p>-Now DHSV status feedback Local and SCADA show correctly.</p><p><u>As left</u>,</p><p>-All status is back to normal.</p><p><u>Next plan</u>,</p><p>-NA</p><p><u>Documentation</u>,</p><p>-N/A</p><p><u>Job progress</u>,</p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-11-10_WP13,TS valve status at HMI and SCADA when the knot is activated', '2024-11-10 23:22:19', '2024-11-11 07:58:30', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
