-- Inserting report ID 33985
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Remove & Overhaul PCV of Degasser LP fuel gas', 'Electrical & Instrument', 'CM ', 'Completed', '2024-11-11', '<p><u>Activity</u>,</p><p>-Remove &amp; Overhaul PCV of Degasser LP fuel gas</p><p><u>History</u>,</p><p>-Remove &amp; Overhaul PCV-62432, LP fuel gas to V-6310 (LP Flare KO Drum Skid)</p><p><u>What happen</u>,</p><p>-Internal diaphragm damaged. Internal debris collected.</p><p><u>Action (08-11-2024)</u>,</p><p>-Performed process isolation by operator.</p><p>-Removed the PCV from the pipe line and performed blind flange isolation to the flanges.</p><p>-Disassembly the PCV at workshop and checked inside.</p><p>-Cleaned the internal part.</p><p>-Assembly the internal part. (Only replaced one new diaphragm bcz only one is on stock. Used the old diaphragm.)</p><p>-Installed back the PCV at local.</p><p>-Replaced bolts and studs with new ones.</p><p>-Replaced new gaskets 1" #150.</p><p><u>Action,(09-11-2024)</u></p><p>-Function tested the PCV at site with operator.</p><p>-The PCV could not be adjusted, the downstream pressure always showed 4.5 bar.</p><p>-Swapped the diaphragm and spring from same size but not same type.</p><p>-Function tested again with operator and the PCV still shows 4.5 bar.</p><p>-Swapped back and normalized the original diaphragm and spring.</p><p><u><br></u></p><p><u><b>Today Action (11-11-2024)</b></u></p><p>-Function test the spare same size (but not same type) at EI Workshop.</p><p>-Adjusted the downstream pressure to 0.5 bar as per P&amp;ID.</p><p>-Swapped new spare PCV at site and function test with site operator &amp; CCR.</p><p>-Online adjusted the PCV to 0.5 bar (as per P&amp;ID) and monitored the condition and leak check.</p><p>-No any leak and the PCV pressure remains stable at 0.5 bar.</p><p><b><u>PCV specification</u>,</b></p><p>-Old existing PCV spare ( Fisher 95L S/N IR10394 Max outlet 8.62 bar &amp; Max inlet 12.76 bar,</p><p>-New spare PCV (Fisher MR 95L S/N R053687191 Max outlet (8.62 bar) 125 psi, Max inlet (18.3 bar)&nbsp; &nbsp; &nbsp;265 psi.</p><p><b><u>Documentation</u>,</b></p><p>-NA</p><p><b><u>Job progress</u>,</b></p><p>-100% completed</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-11-11_TS PCV-62432 malfunction', '2024-11-11 17:20:36', '2025-03-09 17:57:11', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PCV-62432', 'ZTK-PCV-62432', 'Press Regulator,LP Fuel Gas to V-6310', NULL, NULL, 'Press Regulator,LP Fuel Gas to V-6310', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2024-11-11 17:20:36', '2025-03-09 17:57:11', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'P'' Rin', NULL, 'EXTERNAL', '2024-11-11 17:20:36', '2025-03-09 17:57:11', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
