-- Inserting report ID 33986
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS enclosure pressure low alarm', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-11-11', '<p><u>Activity</u>,</p><p>-TS enclosure pressure low alarm at GTG-7210 during strong wind.</p><p><u>History</u>,</p><p>-Investigated 11-Oct-2024 (Day 1),12-Oct-2024 (Day 2) and 13 Oct 2024 (Day-3).</p><p>-Replaced air inlet fire damper and installed front cover of atmosphere side of PDT-72117-7</p><p><u>Equipment description and location</u>,</p><p>-Enclosure pressure transmitter, PDT-72117-7</p><p><u>As found</u>,</p><p>-(1) PDT-72117-7, display show "Current Saturated" message.</p><p>-(2) Vent port isolation needle valve is loosen.</p><p><u>What happen</u>,</p><p>-(1) Transmitter reading fluctuated and UCP reading is -0.017 InH2O.</p><p>-(2) Windy and turbulence can impact to the sensing point.</p><p><u>Action</u>,</p><p>-Run the ventilation fan 1&amp;2 by local control station and record the as found enclosure pressure reading.</p><p>-Fan 1 - (0.52 InH2O) &amp; Fan 2 - (0.78 InH2O). <span style="background-color: rgb(255, 255, 0);">(For reference, in GTG#3, Fan 1 aprox 0.8 inH2O and Fan 2 approx 0.9 inH2O during test run by local control station)</span></p><p>-Tightened the vent port isolation needle valve (<span style="background-color: rgb(255, 255, 0);">as found loosen</span>) and removed sensing tubing for calibration.&nbsp;</p><p>-Performed calibration, analog trim and reinstalled the tubing for function test.</p><p>-Performed function test and it''s OK.</p><p>-Run the ventilation fan 1&amp;2 by local control station and record the enclosure pressure reading.</p><p>-Fan 1 - (0.71 InH2O) &amp; Fan 2 - (0.84 InH2O).</p><p>-Connected the atm sensing point with vinyl tube and change the sensing point to 2 location.</p><p>-Run the ventilation fan 1&amp;2 by local control station and record the enclosure pressure reading and found that the reading is not change much.</p><p>-Fan 1 - (0.71 InH2O) &amp; Fan 2 - (0.84 InH2O).</p><p>-Removed the vinyl tube and reinstalled the atm sensing point front guard.</p><p>-Test run the unit for 30 mins and record the enclosure pressure for both ventilation fans.</p><p>-Fan 1 - (0.52 InH2O) &amp; Fan 2 - (0.68 InH2O).</p><p><u>As left</u>,<br></p><p>-GTG train 1 is stop and GTG train 2 is running with full load.<br></p><p><u>Next Plan</u>,</p><p>-If PDT shows "Current Saturated" message, will replaced with new one.</p><p>- One new spare is ready.</p><p><u>Documentation</u>,<br></p><p>-N/A.</p><p><u>Job Progress</u>,<br></p><p>-Under Monitoring</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-11-11_GTG-7210,PDT-72117 TS Enclosure Pressure Low Alarm">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-11-11_GTG-7210,PDT-72117 TS Enclosure Pressure Low Alarm</a><br></p>', '2024-11-11 17:58:13', '2024-11-13 09:27:44', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTG-7210', 'ZTK-GTG-7210', 'Gas Turbine Generator Package No.1', NULL, NULL, 'Gas Turbine Generator Package No.1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PDT-72117-7', 'ZTK-PDT-72117-7', 'PDT on Encl Press Delta,AL LO & SD LL', NULL, NULL, 'PDT on Encl Press Delta,AL LO & SD LL', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
