  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-11-11 17:58:13', '2024-11-13 09:27:44', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Supv');
