  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Diesel Transfer Pump No Flow', 'Mechanic', 'CM ', 'Completed', '2024-11-17', '<p>Problem : Diesel Transfer Pump No Flow.</p><p>Found&nbsp; &nbsp; : (1) One of the isolation valve at the pedestal crane column was closed due to visible obstruction.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Diesel seeping at diesel dispenser.</p><p>Action&nbsp; &nbsp; : (1) Check the instrument gas pressure. Found 3 bar and ok.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Check pump discharged pressure and found 3 bar and ok.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Check line up valve connection for diesel pumping.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (4) Performing&nbsp; diesel pumping as normal practice. Found normal flow.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (6) Apply PTFE tape for diesel dispenser connection.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (7) Check diesel tote tank condition at strainer and found a small amount of debris and no water.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP13\\Diesel Transfer Pump P-1374\\2024\\17-Nov-2024 TS Pump No Flow">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP13\\Diesel Transfer Pump P-1374\\2024\\17-Nov-2024 TS Pump No Flow</a><br></p>', '2024-11-17 19:28:13', '2024-11-17 19:34:12', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-1374', 'ZTK-P-1374', 'Diesel Oil Transfer Pump for WP13', NULL, NULL, 'Diesel Oil Transfer Pump for WP13', 'WP13', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ko Sett', NULL, 'EXTERNAL', '2024-11-17 19:28:13', '2024-11-17 19:34:12', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Yan', NULL, 'EXTERNAL', '2024-11-17 19:28:13', '2024-11-17 19:34:12', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
