-- Inserting report ID 34124
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Cold store cannot control the temperature', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-11-23', '<p><b><u>Activity</u>,</b></p><p>-T/S&nbsp;Cold store cannot control the temperature</p><p><b><u>History</u>,</b></p><p>-NA</p><p><b><u>Equipment description and location</u>,</b></p><p>-Cold Store Unit A, Lvl 1.</p><p><b><u>As found</u>,</b></p><p>-The ACC1 common fault alarm in the control panel again since 11:30 am after monitoring for a night.</p><p>-The relay R1 is not energized.</p><p>-Found the earth leakage relay (ELR1) got alarm.</p><p><b><u>What happen</u>,</b></p><p>-The ACCU-01 can not run.</p><p><b><u>Action</u>,</b></p><p>-Performed self-isolation to the ACCU-01.</p><p>-Checked if there is real earth fault from the compressor side at field.&nbsp;</p><p>-Checked insulation for the motor of compressor. (U/V/W - E &gt;550 Mohms)</p><p>-Checked the insulation for both the heater (H1/H2 - E &gt; 550 Mohms) and thermistor (T1/T2 - E &gt; 550 Mohms)</p><p>-Checked again at the control circuit for compressor-1 at UCP.</p><p>-Checked continuity test for the contactor by manually energizing the contactor.</p><p>-The earth fault relay cannot be cleared.</p><p>-Performed hard reset to the earth fault relay by removing the power cable.</p><p>-The earth fault relay ELR1 was cleared.</p><p>-Suspected that the earth fault relay ELR1 itself is malfunction.</p><p>-So, swapped with the earth relay ELR2 from compressor 2.</p><p>-So, performed test run to the ACCU-02 and monitored if there is alarm come or not.</p><p><b><u>As left</u>,</b></p><p>-NA</p><p><b><u>Next plan</u>,</b></p><p>-To monitor and if there is alarm come again in the ELR2 (Swapped one from ELR1), replaced ELR2.</p><p>-To check the heater side.</p><p><u><b>Documentation,</b></u></p><p>-N/A&nbsp;</p><p>-Link ()</p><p><b><u>Job progress</u>,</b></p><p>-In progress</p>', NULL, '2024-11-23 15:53:36', '2025-09-01 22:15:37', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LQM-COLDST', 'ZTK-LQM-COLDST', 'Cold Store Room LQM', NULL, NULL, 'Cold Store Room LQM', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LCP-LQM-7340', 'ZTK-LCP-LQM-7340', 'Freezer/Cold Room Local Control Panel', NULL, NULL, 'Freezer/Cold Room Local Control Panel', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
