  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS cold store cannot control temperature', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-11-30', '<p><b><u>Activity</u>,</b></p><p>-TS cold store cannot control temperature</p><p><b><u>History</u>,</b></p><p>-NA</p><p><b><u>Equipment description and location</u>,</b></p><p>-ACCU1 freezer and cold store room</p><p><b><u>As found</u>,</b></p><p>-Ice blocking inside drain pan and evaporator fins</p><p><b><u>What happen</u>,</b></p><p>-Suspect that drain pipe and drain pan heater are not working.</p><p><b><u>Action</u>,</b></p><p>-Unblocked ice inside drain pan and evaporator fins.</p><p>-Performed defrost on for a few minutes to clear the ice attached in the evaporator fins.</p><p>-Measured drip pan heater (defrost heater) is working or not. (Good: 5.14 A ac)</p><p>-Properly cleared all the ice inside drain pan and evaporator fins.</p><p>-Checked if all three fans are running properly or not. (Good)</p><p>-Checked the drain pipe heater current (0.15 A)</p><p>-Checked the drain flexible pipe if there is drain flow or not. (No flow)</p><p>-Measured the drain pipe heater incoming supply. (227 V ac)</p><p>-Suspected that the drain pipe heater is not working properly and still ice inside the drain pipe can not be cleared.</p><p>-Need to replace the drain pipe heater.</p><p><b><u>As left</u>,</b></p><p>-NA</p><p><b><u>Next plan</u>,</b></p><p>-To replace the drain pipe heater.</p><p>-To inform mechanic to fix the freezer door switch.</p><p><u><b>Documentation,</b></u></p><p>-NA&nbsp;</p><p>-Link ()</p><p><b><u>Job progress</u>,</b></p><p>-80% completed.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-11-30_ACCU-1, TS cold connot control temperature">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-11-30_ACCU-1, TS cold connot control temperature</a><br></p>', '2024-11-30 15:36:10', '2025-09-01 22:12:46', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
