-- Inserting report ID 34222
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S fuel shut off valve malfunction', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-12-02', '<p><b><u>&nbsp;Activity</u>,</b></p><p>-T/S crane CR-0573 fuel shutoff valve malfunction.</p><p><b><u>History</u>,</b></p><p>-Continue job from 17-Oct-2024</p><p><b><u>Equipment description and location</u>,</b></p><p>-Fuel shut off valve of&nbsp; WP05 pedestal crane.</p><p><b><u>As found</u>,</b></p><p>- NA</p><p><b><u>What happen</u>,</b></p><p>-Fuse blown and Fuel shutoff solenoid valve malfunction. (As per the history of last visit on 17-Oct-2024)</p><p><b><u>Action</u>,</b></p><p>-Replace new fuse (F6_5A) of fuel shutoff solenoid valve.</p><p>-Checked the timer signal of the T1 &amp; T2 that have output about 27.0Vdc and normal function.</p><p>-Measured the relay coil resistance of the (EK08,10 &amp; 12) that have about 368.7Ohm that compare with new one coil resistance.</p><p>-But fuel shutoff SOV terminals no have voltages that not function the pull and hold coil.</p><p>-Replaced the new relays for (EK08&amp;12) to confirm relay function that difficult to measure the contact signal due to mini relay socket terminal that directly connoted with fuel shutoff solenoid valve protection module.&nbsp; &nbsp;</p><p>-After replaced the new relays, checked the voltage signal for the fuel shutoff SOV pull &amp; hold terminal but still no have the voltage signal.</p><p>-Suspected the fuel shutoff solenoid valve protection module and no have on hand spare.</p><p><b><u>As left</u>,</b></p><p>-Crane is available.&nbsp;</p><p><b><u>Next plan</u>,</b></p><p>-To troubleshoot for fuel shutoff solenoid valve function after on-hand spare for fuel shutoff solenoid valve protection module.</p><p>-Purchase request for fuel shutoff solenoid valve protection module and EK10 relay.</p><p><b><u>Documentation</u>,</b></p><p>-N/A</p><p>-Link ()</p><p><b><u>Job progress</u>,</b></p><p>-In progress.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-12-02_CR-0573_TS fuel shutoff valve cannot work', '2024-12-02 17:39:28', '2024-12-03 07:31:06', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-0573-EN', 'ZTK-CR-0573-EN', 'Pedestal Crane Diesel Engine WP05', NULL, NULL, 'Pedestal Crane Diesel Engine WP05', 'WP05', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2024-12-02 17:39:28', '2024-12-03 07:31:06', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Brown', NULL, 'EXTERNAL', '2024-12-02 17:39:28', '2024-12-03 07:31:06', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
