  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP08', 'ZTK-WP08', 'Zawtika Wellhead Platform 08', NULL, NULL, 'Zawtika Wellhead Platform 08', 'WP08', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SOV-09P04A', 'ZTK-SOV-09P04A', 'Pilot Valve A for Choke Valve HCV-09P04', NULL, NULL, 'Pilot Valve A for Choke Valve HCV-09P04', 'WP09', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2024-12-03 08:36:53', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-TeamLead', NULL);
