-- Inserting report ID 34248
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS shutdown valve cannot open', 'Electrical & Instrument', 'CM ', 'Completed', '2024-12-05', '<p><strong><u>Activity</u>,</strong></p><p>-TS shutdown valve cannot open during turbine compressor Onload, SDV-42616</p><p><strong><u>History</u>,</strong></p><p>-NA</p><p><strong><u>Equipment description and location</u>,</strong></p><p>-Turbine compressor discharge gas outlet shut down valve, Cooler deck</p><p><strong><u>As found</u>,</strong></p><p>-Valve cannot move when CCR command opened(Onload sequence).</p><p><strong><u>What happen</u>,</strong></p><p>-PCS Solenoid valve Maxseal (SOV-42612B) is stuck.</p><p><strong><u>Action</u>,</strong></p><p>-Exercise the shutdown valve with automation team three times. (By force open and close signal)</p><p>-Found valve can opened and closed. (opening time=16s, closing time=12s)</p><p>-Exercise the valve with CCR without starting sequence. (opening time=18s, closing time=12s)</p><p>-During compressor Onload starting sequence, the valve cannot move at first time.</p><p>-At second time, valve can move but take time to open the valve. (more than 20s) And Compressor is blow down.</p><p>-Replace new solenoid valve and start the compressor Onload sequence.</p><p>-Found SDV can operate properly. (opening time=8s)</p><p><strong><u>As left</u>,</strong></p><p>-Turbine compressor is running properly with load.</p><p><strong><u>Next plan</u>,</strong></p><p>-NA</p><p><strong><u>Documentation</u>,</strong></p><p>-NA</p><p><strong><u>Job progress</u>,</strong></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-12-05_SDV-42616, TS SDV not open', '2024-12-05 21:35:55', '2024-12-06 16:08:15', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4200', 'ZTK-GTC-4200', 'Train 1,Gas Turbine Comp Package', NULL, NULL, 'Train 1,Gas Turbine Comp Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
