-- Inserting report ID 34264
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform swap choke valve R to A', 'Mechanic', 'CM ', 'Completed', '2024-12-07', '<p>Perform to swap choke valve From well R to Well A</p><p>1.install lifting gear to lift choke valve (2 point above Choke valve R and A)</p><p>2.WELL R remove choke valve actuator and connection(hydraulic and cable by EI)</p><p>3.remove choke valve down steam stud bolt(60mm)</p><p>4.remove choke valve down steam stud bolt(60mm)</p><p>5.make a tension for choke valve body ,wrap with sling (secure RTJ R38 of down steam can drop to floor)</p><p>6.lay down the valve to grating</p><p>7.clean the flange surfce of well R.</p><p><br></p><p>Well A</p><p>1.Remove the studs of two blind flange&nbsp;</p><p>2.reistall new RTJ and blind flang on well A<br>3.lift up the choke valve to well A and install new RTJ&nbsp;</p><p>4.hand tight the stud bolt on both upsteam and down steam</p><p>5.tighten the stud bolt with 1st step 1000 psi,2nd 2000 psi.3rd 3000 Psi. as a sequence,make a round tighten</p><p>6.remvoe the bonnet assembly</p><p>7.remove plug and cage (stem),seat with special tool</p><p>8.inspect plug and cage condition</p><p>9.replace seal kit assembly</p><p>10.reinstall seat and trim part.</p><p>11.install bonnet gasket and bonnet assembly</p><p>12.tighten the body vent plug</p><p>13.reinstall actuator.tighten the actuator lock nut</p><p>14.install the blind flange on well R retighten the stud bolt</p><p>15.cannot pressure and leak test due to platform is topside depressurize.</p><p>house keeping the area</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP3\\Choke valve\\HCV-03A04\\2024\\06-Dec-2024 Swapped Choke valve body assembly from 03A04">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP3\\Choke valve\\HCV-03A04\\2024\\06-Dec-2024 Swapped Choke valve body assembly from 03A04</a><br></p>', '2024-12-08 11:06:49', '2024-12-08 11:07:08', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HCV-03A04', 'ZTK-HCV-03A04', 'Valve Choke on 4"-GC-03A01 for Well A', NULL, NULL, 'Valve Choke on 4"-GC-03A01 for Well A', 'WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HCV-03R04', 'ZTK-HCV-03R04', 'Valve Choke on 4"-GC-03R01 for Well R', NULL, NULL, 'Valve Choke on 4"-GC-03R01 for Well R', 'WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Henry', NULL, 'EXTERNAL', '2024-12-08 11:06:49', '2024-12-08 11:07:08', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'John', NULL, 'EXTERNAL', '2024-12-08 11:06:49', '2024-12-08 11:07:08', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
