  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Charged refrigerant for topside chiller compressor', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-12-11', '<p><strong><u>Activity,</u></strong></p><p>-Charged refrigerant (R134a) for topside chiller compressor unit A (A-7820A1).</p><p><strong><u>History,</u></strong></p><p>-NA.</p><p><strong><u>Equipment description and location,</u></strong></p><p>-Topside air cooled chiller compressor A1, Lower Deck.</p><p><strong><u>As found,</u></strong></p><p>-(1) During change over to chiller unit B to unit A, tripped by low section pressure. (Low Set Point = 11.6 psi)</p><p><strong><u>What happen,</u></strong></p><p>-(1) Refrigerant pressure low.</p><p><strong><u>Action,</u></strong></p><p>-Checked the leak point with snoop before charging the refrigerant and no leak found.</p><p>-Pre-charged the refrigerant (R134a) before starting the unit A.</p><p>-Started the unit A and continue charging the refrigerant.</p><p>-After charging, checked the leak point again and no leak found.</p><p><b>Refrigerant Used = 24 kg</b></p><p><strong><u>As left,</u></strong></p><p>-Now unit A is running properly without tripping the compressor. (Under Monitoring)</p><p>-PTL = 26.1 psi, PTH = 229 psi, Running current = 183 A&nbsp;</p><p><strong><u>Next Plan,</u></strong></p><p>-NA.</p><p><strong><u>Documentation,</u></strong></p><p>-NA.</p><p>-Link ().</p><p><strong><u>Job Progress,</u></strong></p><p>-100%</p><p>&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-12-11_A-7820A1, Charged refrigerant for topside chiller compressor', '2024-12-11 15:24:53', '2024-12-12 15:36:40', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
