  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Galley equipment malfunction', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-12-19', '<p><u><b>Activity,</b></u></p><p>-T/S Galley equipment malfunction. (Day 3)</p><p><u><b>History,</b></u></p><p>-Continue from 17.Dec.2024.</p><p><u><b>Equipment description and location,</b></u></p><p>-GA-03A/B Marine Grooved Grill&nbsp;</p><p><u><b>As found,</b></u></p><p>-For GA-03B, Chefs don''t use.</p><p>-For GA-03A, Left side heater not working.&nbsp;</p><p><u><b>What happen,</b></u></p><p>-For GA-03B,Because of GA-03B is same function as GA-03A. (GA-03B itself is good)</p><p>-For GA-03A, wrong wiring.</p><p><u><b>Action,</b></u></p><p>-For GA-03A,&nbsp;</p><p>-Checked switch condition and found normal.</p><p>-Checked voltage at heater coil and one of them had no voltage.</p><p>-Checked wiring and found that heat was not in the series loop.</p><p>-After changed back, checked voltage and current of each heater coil.</p><p>-GA-03A is in service now.</p><p><br></p><p>-For GA-03B,</p><p>-Made sure to check coil resistant and running current.</p><p>-Found normal.&nbsp;</p><p><br></p><p><u><b>As left,</b></u></p><p>-NA</p><p><u><b>Next Plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-N/A</p><p><u><b>Job Progress,</b></u></p><p>-65%.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-12-19_GA-03A,B,TS Galley equiment malfunction', '2024-12-19 15:59:30', '2024-12-19 16:30:51', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LQM-GALLEY', 'ZTK-LQM-GALLEY', 'Galley Room', NULL, NULL, 'Galley Room', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Grayson', NULL, 'EXTERNAL', '2024-12-19 15:59:30', '2024-12-19 16:30:51', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Paing', NULL, 'EXTERNAL', '2024-12-19 15:59:30', '2024-12-19 16:30:51', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
