  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Production Manifold shutoff valve', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-12-19', '<p><b><u>Activity</u>,</b></p><p>-T/S the production manifold on /off valve (XV-04K15)</p><p><b><u>History</u>,</b></p><p>-N/A</p><p><b><u>Equipment description and location</u>,</b></p><p>-XV-04K15,Production mainfold shutoff valve, lower deck</p><p><b><u>As found</u>,</b></p><p>-Valve can not close.(Air Fail Open Type)</p><p><b><u>What happen</u>,</b></p><p>-SOV was short circuit that effected to damage the terminal fuse and remote terminal unit node.</p><p><b><u>Action</u>,</b></p><p>-Replaced with new SOV that old SOV coil resistance show 1.9Ohm.</p><p>-Replaced the terminal block due to damage by short circuit of the old SOV.</p><p>-Function tested the shutoff valve but can not action.</p><p>-Found that output of the RTU node was send the 24VDc only during the open/close command by CCR and Automation.</p><p>-No have spare for RTU on board that will replace and funtion test on next visit.</p><p><b><u>As left</u>,</b></p><p>-XV-04K15 can not action.&nbsp;</p><p><b><u>Next plan</u>,</b></p><p>-Replace with new RTU slot and function test.</p><p><b><u>Documentation</u>,</b></p><p>-N/A</p><p>-Link ()</p><p><b><u>Job progress</u>,</b></p><p>-80%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-12-19_XV-04K15, TS Production Manifold shutoff valve', '2024-12-20 00:27:34', '2024-12-20 01:03:00', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-XV-04K15', 'ZTK-XV-04K15', 'SV ON 4''''-GC-04K02-K70 SWITCHING TO PROD', NULL, NULL, 'SV ON 4''''-GC-04K02-K70 SWITCHING TO PROD', 'WP04', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2024-12-20 00:27:34', '2024-12-20 01:03:00', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
