  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS abnormal noise from P- 4710B', 'Mechanic', 'CM ', 'Completed', '2024-12-19', '<p><b><u>2024-12-19</u></b></p><p><b>Problem</b> - Abnormal noise from discharge manifold</p><p><b>Action</b> -&nbsp; Removed plungers'' covers to inspect plungers condition .</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Found all plungers are in good condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Removed discharge manifold to inspect check valves.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Found that abnormal operation of check valve for plunger no.1.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Replaced with new check valve, spring, ''O'' ring and valve latern.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Retightened all bolts for manifold and back cover with torque 330Nm.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Tightened for discharge manifold flange with new gasket SPW 3" #600 - torque 150 Nm,</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Inspected N2 pressure - 30 bar and recharge up to 40 bar.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Test run and running normal.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\47 GLYCOL REGENERATION T1\\P-4710 B\\2024\\2024-12-19 TS abnormal sound">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\47 GLYCOL REGENERATION T1\\P-4710 B\\2024\\2024-12-19 TS abnormal sound</a><br></p>', '2024-12-20 07:50:03', '2024-12-22 17:14:36', 'PTTEP\\ZPQ.Cmms-Tech', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
