  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix lube oil seeping at lube oil cooler plug', 'Mechanic', 'CM ', 'Completed', '2024-12-25', '<p>Problem - Lube oil seeping from cooler plug.</p><p>Action - Before removed the plug, drain out lube oil&nbsp; 2 drum.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Remove leak cooler plug and perform surface cleaning for gasket seating area.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replace lube oil cooler plug (8 EA) from E-4390 train 2.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Tighter cooler plug with torque (180 ft-lbs).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replace Spiral Gasket for lube oil line ( 4 inch class 150 2EA and 2 inch class 150 2EA and 3/4 inch&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;class 150 5EA)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Perform leak test with nitrogen about 3 bars and found no more leak point.</p>', '<p><a href="G:\\Department Share\\04_MAINTENANCE\\02 MECHANICAL\\15-ZPQ MECH SHUTDOWN\\2024\\Cooler Plug replacement\\2024-12-25 E-4390 Cooler plug replacement" target="_blank">G:\\Department Share\\04_MAINTENANCE\\02 MECHANICAL\\15-ZPQ MECH SHUTDOWN\\2024\\Cooler Plug replacement\\2024-12-25 E-4390 Cooler plug replacement</a><br></p>', '2024-12-25 19:45:49', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Mech Team', NULL, 'EXTERNAL', '2024-12-25 19:45:49', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
END $$;

