-- Inserting report ID 34467
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix lube oil seeping at lube oil cooler plug ', 'Mechanic', 'CM ', 'Completed', '2024-12-27', '<p>Problem - Lube oil seeping from cooler plug.</p><p>As found - During taking out cooler plug and found turbulence come out from cooler tube.</p><p>Action - Before removed the plug, drain out lube oil&nbsp; 2 drum.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Remove leak cooler plug and perform surface cleaning for gasket seating area.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replace lube oil cooler plug (22 EA) from E-4390 train 2.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Tighter cooler plug with torque (180 ft-lbs).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replace Spiral Gasket for lube oil line ( 4 inch class 150 2EA and 2 inch class 150 2EA and 3/4&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; inch class 150 5EA)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Perform leak test with nitrogen about 3 bars and found no more leak point.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Refill lube oil 2 Drum (Turbin M32).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Perform housekeeping around area.</p>', '<p><a href="Z:\\Department Share\\04_MAINTENANCE\\02 MECHANICAL\\15-ZPQ MECH SHUTDOWN\\2024\\Photos\\01. Fix lube leakage at cooler plug\\2024-12-26 E-4490 Cooler plug replacement" target="_blank">Z:\\Department Share\\04_MAINTENANCE\\02 MECHANICAL\\15-ZPQ MECH SHUTDOWN\\2024\\Photos\\01. Fix lube leakage at cooler plug\\2024-12-26 E-4490 Cooler plug replacement</a><br></p>', '2024-12-27 19:43:58', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-E-4490', 'ZTK-E-4490', 'Lube Oil Cooler', NULL, NULL, 'Lube Oil Cooler', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Mech Team', NULL, 'EXTERNAL', '2024-12-27 19:43:58', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
END $$;

-- Inserting report ID 34468
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 8KPM crank soap wash', 'Mechanic', 'PM ', 'Completed', '2024-12-27', '<p>Performed Engine crank soak wash. </p><p>1. Remove piping accessory. </p><p>2. Remove ignition cable. </p><p>3. Install air supply 2.7 bar to front and real bearing seal. </p><p>4. Open air inlet plenum manhole. </p><p>5. Take chlorine sample in the air inlet plenum. </p><p>6. Take chlorine sample from air inlet filters room. </p><p>7. Fill cleaning product ZOK/De-ionic water 5/25 Gal into mobile injection tank. </p><p>8. Crank engine by using test crank mode. </p><p>9. Spray cleaning product while engine NGP reaches to 19.9%. </p><p>10. Step of cleaning&nbsp;</p><p>11. Take water sample from drain line of exhaust duct. </p><p>12. Wait for 20 min then continue process washing. </p><p>13. Step of rinse water&nbsp;</p><p>14. Dry crank 5 min for 2 times.due to permissive to start from CCR not clear, Waiting for verifying by the Automation team. </p><p>15. Re-assembly piping. </p><p>16. Performed engine fire dry step and then CCR continuous running unit. </p><p>17. Housekeeping work area.&nbsp;</p>', '<p><a href="http://\\\\pttep.com\\dfsrootzpq\\zpqshare\\Department Share\\04_MAINTENANCE\\02 MECHANICAL\\15-ZPQ MECH SHUTDOWN\\2024\\Photos\\05. GTC-4300 Crank soap wash">\\\\pttep.com\\dfsrootzpq\\zpqshare\\Department Share\\04_MAINTENANCE\\02 MECHANICAL\\15-ZPQ MECH SHUTDOWN\\2024\\Photos\\05. GTC-4300 Crank soap wash</a><br></p>', '2024-12-27 19:32:34', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4300', 'ZTK-GTC-4300', 'Train 2,Gas Turbine Comp Package', NULL, NULL, 'Train 2,Gas Turbine Comp Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'KOKO', NULL, 'EXTERNAL', '2024-12-27 19:32:34', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kaung', NULL, 'EXTERNAL', '2024-12-27 19:32:34', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ko Leo', NULL, 'EXTERNAL', '2024-12-27 19:32:34', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
