  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '12M PM SD INMF-WP4 Inlet Manifolds & Pig', 'Electrical & Instrument', 'PM ', 'In Progress', '2024-12-30', '<p><u><b>Activity,</b></u></p><p>-12M PM SD INMF-WP4 Inlet Manifolds &amp; Pig receiver.</p><p><u><b>History,</b></u></p><p>-NA.</p><p><u><b>Equipment description and location,</b></u></p><div class="ms-sel-item ">-ZTK-ESDV-40402, ESDV for ESD 3AM, WP4 to Inlet Manifold, Sea Deck.</div><div class="ms-sel-item ">-ZTK-SDV-40415, SDV for ESD 3AM WP4 to Inlet Manifold, Lower Deck.</div><div class="ms-sel-item ">-ZTK-HV-40416, Control Valve for WP4 to Inlet Manifold, Lower Deck.</div><p><u><b>As found,</b></u></p><p>-Topwork valve positoner and fisher positioner termination are loosen.</p><p><u><b>What happen,</b></u></p><p>-Vibration.</p><p><u><b>Action,</b></u></p><p>-Tightened the cable termination for the Topwork valve position monitor and fisher positioner.</p><p>-Replaced solenoid with new spare for the ESDV-40402.</p><p>-Performed function test and leak check the control panel at workshop.</p><p>-ESDV-40402 can not performed function test due to under process isolation.</p><p>-Cleaning, greasing and checked the solenoid condition for the SDV-40415 and can not performed function test due to under process isolation.</p><p>-Performed cleaning, greasing and stoke test for the HCV-40416.</p><p>-Found that HCV-40416 show feedback 100% opened at automation but at local only 90% opened.</p><p>-Performed quick calibration but still different at local and automation side.</p><p><u><b>As left,</b></u></p><p>-SOV-40402 (371.9 Ohm)</p><p>-SOV-40415A (192.3 Ohm), SOV-40415B (192.3 Ohm)</p><p><u><b>Next Plan,</b></u></p><p>-Will function test for the SDV-40415 and ESDV-40402 after process deisolation.</p><p>-Will troubleshot for HCV-40416.</p><p><u><b>Documentation,</b></u></p><p>-In Progress.</p><p>-Link (\\\\pttep.com\\DFSRootZPQ\\zpqshare\\Department Share\\04_MAINTENANCE\\03 E&amp;I\\08 PM&amp;CM&amp;Log Sheets Report\\01 PM Records and Test Records\\14. Inlet Manifolds and Pig\\2024\\30 Dec 24_12M PM SD INMF-WP4 Inlet Manifold and pig receiver).</p><p><u><b>Job Progress,</b></u></p><p>-50%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2024-12-30_ESDV-40402, SDV-40415, HCV-40416, 12M PM SD Inlet Manifold &amp; WP04 Pig Receiver', '2024-12-30 15:49:11', '2024-12-30 19:07:20', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-ESDV-40402', 'ZTK-ESDV-40402', 'ESDV for ESD 3AM, WP4 to Inlet Manifold', NULL, NULL, 'ESDV for ESD 3AM, WP4 to Inlet Manifold', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
