  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Vent Plug 16" ball valve of SDV-42101 D/S seeping', 'Mechanic', 'CM ', 'Under Monitoring', '2024-12-30', '<p>Problem - Found Gas seeping from vent plug of ball valve.</p><p>Action - Bleed the pressure from valve body.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Remove this vent plug from ball valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Clean and inspect vent plug &amp; body thread.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Apply sealant and Teflon tape for the thread.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Intall it back.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Waiting for leak test.</p>', '<p><a href="http://\\\\pttep.com\\dfsrootzpq\\zpqshare\\Department Share\\04_MAINTENANCE\\02 MECHANICAL\\15-ZPQ MECH SHUTDOWN\\2024\\Photos\\06.Valves\\2024-12-30 FIxed gas seeping at vent plug of 16inch Ball valve" target="_blank">\\\\pttep.com\\dfsrootzpq\\zpqshare\\Department Share\\04_MAINTENANCE\\02 MECHANICAL\\15-ZPQ MECH SHUTDOWN\\2024\\Photos\\06.Valves\\2024-12-30 FIxed gas seeping at vent plug of 16inch Ball valve</a><br></p>', '2024-12-30 16:06:55', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SDV-42101', 'ZTK-SDV-42101', 'SDV,Gas to V-4210, ESD 3B/3CB/3CH', NULL, NULL, 'SDV,Gas to V-4210, ESD 3B/3CB/3CH', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
