  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify and Check ECS Communication Card.', 'Automation', 'CM ', 'Completed', '2024-12-30', '<p><b><u>Activity</u>,</b></p><p>-Verify and check ECS communication card for ECS Rack5 RIO module.</p><p><b><u>History</u>,</b></p><p>-RE: ECS PLC Rack# 3 Ethernet Module "“140 CRA 312 00 Ethernet RIO drop” was faulty.(Find with Mail subject)</p><p>-On 31 May 2024, ECS initiated Load shedding fault signal.</p><p>--Rack5 slot 2 CRA31200 Ethernet RIO module fault alarm</p><p><b><u>Equipment description and location</u>,</b></p><p>-ECS-CPP-200, CRA 31200 Ethernet RIO drop Module.</p><p><b><u>As found</u>,</b></p><p>-N/A</p><p><u><b>What happen</b></u>,</p><p>-N/A</p><p><b><u>Action</u>,</b></p><p>-Replaced 140 CRA 312 00 RIO module with new spare under Same SV version and Differet SV version.</p><p>-Checked any abnormal alarm at ECS system and there has no alarm in ECS after replacing CRA module.</p><p>-140 CRA 312 00 RIO module can replaced both Same and Different version.</p><p><u><b>As left,</b></u></p><p>-Replaced with new spare part for Rack5 slot 2 (140 CRA 312 00) RIO module with same SV version.</p><p>SV version &gt;&gt;&gt;&gt; 1.09.</p><p>-Kept Old CRA module for Hot spare.</p><p>Total Spare module Including hot spare 3ea.</p><table border="0" cellspacing="0" cellpadding="0" width="439">  <tbody><tr>   <td width="135" nowrap="" valign="bottom">   <p>&nbsp;</p>   </td>   <td width="133" nowrap="" valign="bottom">   <p>Existing   Module&nbsp; SV </p>   </td>   <td width="171" nowrap="" valign="bottom">   <p>On Hand Spare   Module SV</p>   </td>  </tr>  <tr>   <td width="135" nowrap="" valign="bottom">   <p>RIO Drop   Module</p>   </td>   <td width="133" nowrap="">   <p align="center">1.09</p>   </td>   <td width="171" nowrap="">   <p align="center">1.09(Old)/2.14/2.40</p>   </td>  </tr>  <tr>   <td width="135" nowrap="" valign="bottom">   <p>NOE   communication</p>   </td>   <td width="133" nowrap="">   <p align="center">5.10</p>   </td>   <td width="171" nowrap="">   <p align="center">5.50/6.40.6.40</p>   </td>  </tr> </tbody></table><p><u><b>Next plan</b></u>,</p><p>-N/A</p><p><b><u>Documentation</u>,</b></p><p>-N/A</p><p><b><u>Job progress</u>,</b></p>-100%', 'G:\\Department Share\\04_MAINTENANCE\\03 E&amp;I\\01 Automation\\01. Picture and Document for History Report\\Hand Over Rev.58 (11 Dec to 10 Jan 24)\\2024-12-30_ECS RIO card replacement', '2024-12-30 16:12:06', '2024-12-30 16:35:38', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
