  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify and edit online download for alarm message.', 'Automation', 'CM ', 'Completed', '2024-12-30', '<p><u><b>Activity,</b></u></p><p>-Verify and perform online download for Upperdeck Gr_73 voting trip alarm.</p><p><u><b>History,</b></u></p><p>-When performing 1YPM for flame detector at upper deck, found that "Confirm Voting Trip Alarm" was pop-up while FD-47004 was inhibited.</p><p><u><b>Equipment description and location</b>,</u></p><p>- SCS0117, Fire and gas controller, ITR.</p><p><u><b>As found,</b></u></p><p>-Found that FD-47004 logic drawing was wrongly map with UPDECK_GR73_OUT_ANN alarm.</p><p><u><b>What happen,</b></u></p><p>-N/A.</p><p><u><b>Action,</b></u></p><p>-Changed mapping from "UPDECK_GR73_OUT_ANN to UPDECK_GR73_VINH_ANN".</p><p>-Performed integrity analyzer and cross reference analyzer before online download.</p><p>-Build project library and check any error.</p><p>-Performed online download for SCS0117.</p><p>-Function test and check alarm message at PCS.</p><p><u><b>As left,</b></u></p><p>-All alarm message show correctly for each tag no under UPDECK_GR73.</p><p><u><b>Next Plan,</b></u></p><p>-N/A</p><p><u><b>Documentation,</b></u></p><p>-N/A</p><p><u><b>Job Progress</b>,</u></p><p>-100%</p>', NULL, '2024-12-30 16:30:20', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
