-- Inserting report ID 34526
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 8KPM crank soap wash ', 'Mechanic', 'PM ', 'Completed', '2024-12-30', '<p>Performed Engine crank soak wash.</p><p>1. Remove piping accessory.</p><p>2. Remove ignition cable.</p><p>3. Install air supply 2.7 bar to front and real bearing seal.</p><p>4. Open air inlet plenum manhole.</p><p>5. Take chlorine sample in the air inlet plenum.</p><p>6. Take chlorine sample from air inlet filters room.</p><p>7. Fill cleaning product ZOK/De-ionic water 5/25 Gal into mobile injection tank.</p><p>8. Crank engine by using test crank mode.</p><p>9. Spray cleaning product while engine NGP reaches to 19.9%.</p><p>10. Step of cleaning&nbsp;</p><p>11. Take water sample from drain line of exhaust duct.</p><p>12. Wait for 20 min then continue process washing.</p><p>13. Step of rinse water&nbsp;</p><p>14. Dry crank 5 min for 3 times.due to permissive to start from CCR not clear, Waiting for verifying by the Automation team.</p><p>15. Re-assembly piping.</p><p>16. Performed engine fire dry step and then CCR continuous running unit.</p><p>17. Housekeeping work area.&nbsp;</p>', NULL, '2024-12-30 18:55:19', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4200', 'ZTK-GTC-4200', 'Train 1,Gas Turbine Comp Package', NULL, NULL, 'Train 1,Gas Turbine Comp Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'KOKO', NULL, 'EXTERNAL', '2024-12-30 18:55:19', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ko Leo', NULL, 'EXTERNAL', '2024-12-30 18:55:19', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ko Myo', NULL, 'EXTERNAL', '2024-12-30 18:55:19', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
