-- Inserting report ID 34563
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist OPT Test for flare pilots', 'Electrical & Instrument', 'OTH ', 'In Progress', '2025-01-02', '<p><u>Activity,</u></p><p>-Assisted OPT test for flare pilots and thermocouple by PMO/E.</p><p><u>History,</u></p><p>-NA</p><p><u>Equipment description and location,</u></p><p>-Flare Ignition System, Main Deck</p><p><u>As found,</u></p><p>-N/A</p><p><u>What happen,</u></p><p>-N/A.</p><p><u>Action,</u></p><p>-Performed electrical de-isolation rom UPSDB-CPP-231 (B8).</p><p>-Performed preparation at local flare ignition control panel. (All HS : OFF and HS-63302 to "HEI")<br></p><p>-Performed DIP switch No.2 "ON" for each HEI spark generator module for cable and spark generator checking function.</p><p>-Performed function test to each pilot one by one without propane first.</p><p>-Found that </p><p>&nbsp; &nbsp; -&nbsp;&nbsp;&nbsp;&nbsp;HP-01 pilot&nbsp;status&nbsp; &nbsp; :&nbsp; &nbsp; LED orange (green+red)</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; HP-02 pilot status&nbsp; &nbsp; :&nbsp; &nbsp; RED flashing continuously (reignition delay &lt; 10 secs)</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; HP-03 pilot status&nbsp; &nbsp; :&nbsp; &nbsp; RED flashing continuously (reignition delay &lt; 10 secs)</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; LP-01 pilot status&nbsp; &nbsp; :&nbsp; &nbsp; RED then Green when DIP-2 ON.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; LP-02 pilot status&nbsp; &nbsp; :&nbsp; &nbsp; LED orange (green+red) when DIP-2 ON.</p><p>&nbsp; &nbsp; -&nbsp; &nbsp; LP-03&nbsp;pilot status&nbsp; &nbsp; :&nbsp; &nbsp; LED orange (green+red) when DIP-2 ON.</p><p>-Replaced HP-01, LP-01/02/03 spark generator modules.</p><p>-Performed function test to the flare with propane and check spark.</p><p>-Found when LP pilot is test, there is flare on HP side and vice versa, meaning termination wiring are wrong. (Will be changed by project team).</p><p><br></p><p><i><b>Note:</b>&nbsp; &nbsp; LED RED&nbsp;<a href="on:when">ON:</a>&nbsp;when the HEI module is sparking.</i></p><p><i>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;LED GREEN ON: when he HEI module is ON and waiting for spark.</i></p><p><i>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;When DIP-2 is ON, the following function will be valid.<br></i></p><p><i>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;LED RED flashing continuously : cable interrupted or TIP not connected. (reignition delay 30 seconds)</i></p><p><i>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;LED RED flashing continuously : cable interrupted or TIP in short circuit. (reignition delay 10 seconds)</i></p><p><i>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;LED ORANGE (green + red) : flashing continuously: spark generator component o TIP are no more efficiently.</i></p><p><u>As left,</u></p><p>-De-isolated the power supply back.</p><p><u>Next Plan,</u></p><p>-Goin to perform function test for thermocouple.&nbsp;</p><p><u>Documentation,</u></p><p>-NA</p><p><u>Job Progress,</u></p><p>-70%</p>', NULL, '2025-01-02 07:42:17', '2025-01-02 08:18:45', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-6330', 'ZTK-X-6330', 'Flare Ignition and Flare Pilot Assembly', NULL, NULL, 'Flare Ignition and Flare Pilot Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
