  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ryan', NULL, 'EXTERNAL', '2025-01-02 07:42:17', '2025-01-02 08:18:45', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
