-- Inserting report ID 34586
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist PMO/E team on troubleshooting flare system', 'Electrical & Instrument', 'CM ', 'Completed', '2025-01-03', '<p><u>Activity,</u></p><p>-Assisted PMO/E team on troubleshooting flare system.</p><p><u>History,</u></p><p>-No Flame ON on HP-01 pilot and sensor reading errors on TSL-6320A/B (T1/T2) and TSL-63215A/B (T25/T26).</p><p><u>Equipment description and location,</u></p><p>-Flare Ignition System, Main Deck</p><p><u>As found,</u></p><p>-N/A</p><p><u>What happen,</u></p><p>-No flame on HP-01 pilot.</p><p>-TSL-6320A/B (T1/T2) and TSL-63215A/B (T25/T26) showed SE.BR errors.</p><p><u>Action,</u></p><p>-Performed cable resistance test to the HP-01 pilot ignition line.</p><p>-Tightened Ignition HEI cable at local junction boxed in main deck and upper deck.</p><p>-Set the PCV for fuel gas supply (propane) to around 0.4 bar.</p><p>-Started the HP-01 pilot and flame ON.</p><p>-Started HP-02/HP-03 again and both flame ON.</p><p>-Started LP-01/02/03 again and both flame ON.</p><p>-All LP and HP flare pilot system working.</p><p>-For TSL-6320A/B, found that the TSL-6320A and TSL-6320B(spare) loop are break (open circuit) when measured with multimeter. (both showed OL)</p><p>-Checked the TSL-6320A (yellow) and TSL-6320B (red) and found there is closed circuit.</p><p>-Checked again TSl-6320A(red) and TSL-6320B (yellow) and found there is also well closed circuit.&nbsp;</p><p>-Used TSL-6320A(yellow)/TSL06320B(red) as T1/T2 and TSL-6320B(yellow)/TSL-6320A(red) as T3/T4 (spare).</p><p>-TSL-63251A/B loop also showed open circuit.</p><p>-Used TSL-63251A(yellow)/TSL63251B(red) as T25/T26 and TSL-63251B(yellow)/TSL-63251A(red) as T27/T28 (spare).</p><p>-Replaced temperature transmitters for both T1/T2 and T25/T26.</p><p>-Adjusted the settings for temperature transmitters. (HP-01: 177 ''C and <a href="LP-01:70">LP-01:70</a>&nbsp;''C)</p><p>-Now all the thermocouple readings are correct normally and all readings are correct.</p><p><u>As left,</u></p><p>-De-isolated the power supply back.</p><p><u>Next Plan,</u></p><p>-If possible, checking continuity test for HP-01 sparking loop.</p><p>-Cable tightening and adjusted the PCV for fuel gas (propane) for concerning about too lean or rich in fuel gas.</p><p><u>Documentation,</u></p><p>-NA</p><p><u>Job Progress,</u></p><p>-100%</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-03-01_X-6330, TS flare ignition pilot system">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-03-01_X-6330, TS flare ignition pilot system</a><br></p>', '2025-01-03 21:56:32', '2025-01-03 23:29:54', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-6330', 'ZTK-X-6330', 'Flare Ignition and Flare Pilot Assembly', NULL, NULL, 'Flare Ignition and Flare Pilot Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2025-01-03 21:56:32', '2025-01-03 23:29:54', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'P'' Rin', NULL, 'EXTERNAL', '2025-01-03 21:56:32', '2025-01-03 23:29:54', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'PMOE Team', NULL, 'EXTERNAL', '2025-01-03 21:56:32', '2025-01-03 23:29:54', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine');
  INSERT INTO spare (report_id, action, mesc, detail, qty, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Withdraw', '60.05.31.921.3', 'Assist PMO/E team on troubleshooting flare system', '2', '2025-01-03 23:29:54', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Turbine', NULL);
