  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform GTG unit changeover', 'Electrical & Instrument', 'OTH ', 'Completed', '2025-01-05', '<p><b><u>Activity</u>,</b></p><p>-Perform GTG-7210 unit changeover to GTG-7220 after manual crank by Mech team.</p><p>(To stop unit GTG-7210 for borescope inspection).</p><p><b><u>History</u>,</b></p><p>-GTG-7220 could not be started up due to shaft lock.&nbsp;</p><p><b><u>Equipment description and location</u>,</b></p><p>-Gas turbine generator, Upper deck</p><p><b><u>As found</u>,</b></p><p>-GTG-7220 shaft lock and Fail to Crank.</p><p><b><u>What happen</u>,</b></p><p>-GTG-7220 unit trip due to power loss.&nbsp;</p><p><b><u>Action</u>,</b></p><p>-At 13:10: Mech team performed manual cranking by Torque wrench GTG-7210.</p><p>-At 13:47: Test Crank from UCP panel and it functioning properly.</p><p>-At 15:51: Start up GTG-7210 by Gas mode.</p><p>-At 15:58: Ignition pass and Light Off.</p><p>-At 16:00: Ready to load.</p><p>-At 16:04: Performed on load sharing with GTG-7210 and GTG-7230.</p><p>-At 16:09: Unload GTG-7210 and keep monitoring for GTG-7220 &amp; GTG-7230 parameters.</p><p>-At 16:15: Normal stop GTG-7210 and slow roll enable.</p><p><br></p><p><b><u>As left</u>,&nbsp;</b>&nbsp;(As of 05 Jan 2025 17:00)</p><p>-GTG-7220&nbsp;<span style="background-color: rgb(255, 0, 0);">(Running)</span>&nbsp; &nbsp; (Running Hrs. 15217 : / Start count: 68 )</p><p>-GTG-7230&nbsp;<span style="background-color: rgb(255, 0, 0);">(Running)</span>&nbsp; &nbsp; (Running Hrs.: 19643/ Start count: 66 )</p><p>-GTG-7210&nbsp;<span style="background-color: rgb(0, 255, 0);">(STOP)&nbsp;</span>&nbsp;&nbsp; &nbsp; &nbsp; (Running Hrs. 20788 : / Start count: 75 )</p><p><b><u>Next plan</u>,</b></p><p>-NA</p><p><b><u>Documentation</u>,</b></p><p>-NA</p><p><b><u>Job progress</u>,</b></p><p>-Completed.</p>', NULL, '2025-01-05 16:56:23', '2025-01-05 17:28:24', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
