  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace High Pressure Pump P-6651', 'Mechanic', 'CM ', 'Completed', '2025-01-05', '<p>Problem : Water leak from mech seal chamber drain port.</p><p>Action&nbsp; &nbsp; : (1) Remove pump cooling tubing, Victaulic coupling at suction and discharge and loosen the PVC union in order to take out pump suction casing.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Clean the Victaulic coupling and apply ZINC IT.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Take out high pressure pump and replaced with overhaul one (overhauled on 17-Sep-2024).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (4) Check and inspect gear box housing area and outboard bearing seat area. Found normal operations.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (5) Installed pump casing with 52~54 ft-lb.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (6) Priming the pump with incoming water pressure (7 bars). Found no leak on piping connection.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (7) Perform test run and the unit is running normal.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (8) Replaced lube oil 2 and half Quarts.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-Jan-05 Replace Overhaul Pump Due To Leak at Mech Seal Chamber">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-Jan-05 Replace Overhaul Pump Due To Leak at Mech Seal Chamber</a><br></p>', '2025-01-05 17:28:30', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6651', 'ZTK-P-6651', 'Fresh Water High Pressure Pump', NULL, NULL, 'Fresh Water High Pressure Pump', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Yan', NULL, 'EXTERNAL', '2025-01-05 17:28:30', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
