  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS chiller compressor circuit 1 tripped', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-01-10', '<p><b><u>Activity</u>,</b></p><p>-A-7820 A, T/S chiller compressor circuit 1(A-1) is tripped.</p><p><b><u>History</u>,</b></p><p>-NA</p><p><b><u>Equipment description and location</u>,</b></p><p>-Topside air cooled chiller compressor A1, Lower Deck.</p><p><b><u>As found</u>,</b></p><p>-Circuit-1 refrigerant pressure low.</p><p>-During unit stopped condition,</p><p>-Chiller compressor circuit 1(A-1) suction pressure - 36.3 psi&nbsp;and discharge pressure -37.4 psi.</p><p>-Chiller compressor circuit 2(A-2) suction pressure - 49.3 psi&nbsp;and discharge pressure -47.9 psi.</p><p><b><u>What happen</u>,</b></p><p>-Unit tripped by refrigerant low pressure alarm during unit changeover.</p><p><b><u>Action</u>,</b></p><p>-Checked the leak point around the compressor unit.(Normal)</p><p>-Pre-charged the refrigerant (R134a) before starting the unit A-1.</p><p>-Performed run the chiller unit A.</p><p>-After started the chiller, checked the leak point again around the compressor unit.(Normal)</p><p>-Checked the leakage around the condensing coil with refrigerant leak detector.(Normal)</p><p><b>-Refrigerant Used = 27.2 kg (2 CYL)</b></p><p><b><u>As left</u>,</b></p><p>-During unit running and under monitoring condition,</p><p>-Chiller compressor circuit 1(A-1) suction pressure - 26.1 psi&nbsp;and discharge pressure - 216.0 psi.</p><p>-Chiller compressor circuit 2(A-2) suction pressure - 21.8 psi&nbsp;and discharge pressure - 223.3 psi.</p><p>-After 2 Hr running,</p><p>-Chiller compressor circuit 1(A-1) suction pressure - 36.3 psi&nbsp;and discharge pressure - 178.6 psi.</p><p>-Chiller compressor circuit 2(A-2) suction pressure - 27.6 psi&nbsp;and discharge pressure - 207.4 psi.</p><p>-<b>Unit A is duty and Unit B is standby.</b></p><p><b><u>Next plan</u>,</b></p><p>-Undermonitoring the unit A.</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><b><u>Job progress</u>,</b></p><p>-Job completed and the unit A is undermonitoring.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-01-10_A-7820A, TS chiller refrigerant low', '2025-01-10 14:18:54', '2025-02-03 10:14:37', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-7820A', 'ZTK-A-7820A', 'Air Cooled Chiller Duty Unit', NULL, NULL, 'Air Cooled Chiller Duty Unit', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
