  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S UV sterilizer is tripped', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-01-10', '<p><u>Activity</u>,</p><p>-T/S UV sterilizer X-6820 is tripped</p><p><u>History</u>,</p><p>-NA</p><p><u>Equipment description and location</u>,</p><p>-UV sterilizer, Main Deck.</p><p><u>As found</u>,</p><p>-UV sterilizer tripped by "UV low alarm". </p><p>-Set Point: Warning - 37.6 W/sq-M</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Alarm - 35.8 W/sq-M</p><p><u>What happen</u>,</p><p>-Unit tripped by UV low alarm.</p><p><u>Action</u>,</p><p>-Normalized &amp; test run the unit, found that the UV intensity is around 28 W/sq-M.</p><p>-So unit tripped by UV low alarm.</p><p>-Replaced the UV lamp, ballast &amp; UV sensor.</p><p>-Test run the unit and found that the intensity is go up to 43 W/sq-M.</p><p>-When system start up, the intensity drop gradually and tripped again.</p><p>-Checked the sleeve and found that sleeve is cracked.</p><p>-Replaced the sleeve and test run the unit. (OK) UV intensity is 50 W/sq-M.</p><p>-Found that when the unit start, the XV-68201 is not open.</p><p>-XV-68201 able to open by operating the by-pass IA supply. So valve is working properly.</p><p><u>As left</u>,</p><p>-UV intensity is 50 W/sq-M.</p><p><u>Next plan</u>,</p><p>-Will troubleshoot on SOV and thermal switch.</p><p><u>Documentation,</u></p><p>-NA</p><p><u>Job progress</u>,</p><p>-Job is in progress.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-01-10_X-6820 TS UV sterilizer is tripped">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-01-10_X-6820 TS UV sterilizer is tripped</a><br></p>', '2025-01-10 15:51:13', '2025-01-10 18:46:12', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
