  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS chiller compressor unit A gas leak', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-01-12', '<p><b><u>Activity</u>,</b></p><p>-A-7820 A, T/S chiller compressor unit A (A-1) leak.</p><p><b><u>History</u>,</b></p><p>-10.01.2025</p><p><b><u>Equipment description and location</u>,</b></p><p>-Topside air cooled chiller compressor A1, Lower Deck.</p><p><b><u>As found</u>,</b></p><p>-N/A</p><p><b><u>What happen</u>,</b></p><p>-Unit tripped by refrigerant low pressure alarm during unit changeover</p><p><b><u>Action</u>,</b></p><p>-Checked the leak point at the compressor unit&nbsp; A-7820A.</p><p>-<b>For checking sensor line, isolate and leak test</b>&nbsp;</p><p>-Chiller compressor circuit 1(A-1) suction pressure - 46.1 psi&nbsp;and discharge pressure - 46.4 psi.</p><p>-Isolate the sensor line and check leak test at chiller compressor unit A (A-1).</p><p>-After 2 Hr monitoring condition,</p><p>-Chiller compressor circuit 1(A-1) suction pressure - 47.9 psi&nbsp;and discharge pressure - 46.1 psi.</p><p>-<b>For checking compressor line, isolate and leak test</b></p><p>-Chiller compressor circuit 1(A-1) suction pressure - 46.1 psi&nbsp;and discharge pressure - 46.4 psi.</p><p>-Isolate the compressor suction and discharge line and check leak test at chiller compressor unit1 (A-1)</p><p>-After 2 Hr monitoring condition,</p><p>-Chiller compressor circuit 1(A-1) suction pressure - 45.0 psi&nbsp;and discharge pressure - 44.6 psi.</p><p>-After 4 Hr monitoring condition,</p><p>-Chiller compressor circuit 1(A-1) suction pressure - 43.5 psi&nbsp;and discharge pressure - 44.6 psi.</p><p><u><b>As Left,</b></u></p><p>-Under inspection leak check for chiller compressor and Unit A is not available.</p><p>-Isolated the compressor suction and discharge line.</p><p>-Keep monitoring the unit A overnight.</p><p><b><u>Next plan</u>,</b></p><p>-Under monitoring the unit A.</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job progress</b></u>,</p><p>-In progress.</p>', NULL, '2025-01-12 14:59:42', '2025-02-03 10:14:45', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-7820A', 'ZTK-A-7820A', 'Air Cooled Chiller Duty Unit', NULL, NULL, 'Air Cooled Chiller Duty Unit', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
