-- Inserting report ID 34723
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform to T/S Choke valve H stuck', 'Mechanic', 'CM ', 'Completed', '2025-01-15', '<p>Problem: choke valve is not working properly (cannot close or open,only 10% working up or down)</p><p>Found: choke valve actuator is working as normal when removed coupling of stem</p><p>Action : depressurize the choke valve vent plug from body trap pressure (by 3/4 spanner)</p><p>- remove 8 ea L key bolt for actuator mounting (1/2 " L key)</p><p>- remove packing gland follower nut (60mm)&nbsp;</p><p>- loosen the bonet 8 bolt with 55 mm and hammer wrench</p><p>- lift the actuator with two chain block. cause of support structure is too close and not enough head room to install chain hoist</p><p>-&nbsp;Do not remove all bolt from bonnet, left two for any trap pressure</p><p>- Lift the bonnet with eye bolt&nbsp;</p><p>- Remove seal and trim kit and found too much sand in valve body</p><p>- Clean the valve body inside&nbsp;</p><p>- Replace the new trim kit and seal kit</p><p>- Install back inside of valve body</p><p>- Replace stem packing</p><p>- Install back bonnet and actuator</p><p>- Retighten the valve body vent plug</p><p>- Tighten the bonnet bolt with 80Nm,170Nm,260Nm,300Nm with 4 time multiplier</p><p>- Pressure test and passing test with 40 bar, found no leak.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP11\\Choke valve\\HCV-11H04\\2025\\2025-Jan-15 Ts choke valve stuck">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP11\\Choke valve\\HCV-11H04\\2025\\2025-Jan-15 Ts choke valve stuck</a><br></p>', '2025-01-15 22:39:17', '2025-01-16 13:35:51', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-TeamL', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HCV-11H04', 'ZTK-HCV-11H04', 'Valve Choke on 6''''GC11H01-J70 for Well H', NULL, NULL, 'Valve Choke on 6''''GC11H01-J70 for Well H', 'WP11', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Henry', NULL, 'EXTERNAL', '2025-01-15 22:39:17', '2025-01-16 13:35:51', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-TeamL');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Leo', NULL, 'EXTERNAL', '2025-01-15 22:39:17', '2025-01-16 13:35:51', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-TeamL');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kaung', NULL, 'EXTERNAL', '2025-01-15 22:39:17', '2025-01-16 13:35:51', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-TeamL');
