  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Lube Oil Seeping from Exhaust Line', 'Mechanic', 'CM ', 'Completed', '2025-01-17', '<p>Problem : (1) Lube Oil Seep from turbocharger outlet exhaust line.</p><p>Found&nbsp; &nbsp; : <span style="background-color: rgb(255, 156, 0);">(1) Small amount of air seeping from turbocharger outlet to exhaust muffler connection.</span></p><p>Action&nbsp; &nbsp; : (1) Check and inspect any sign of leakage from lube oil supply and return line to turbocharger. Found no sign of leakage.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2)Top up lube oil 1 lit and keeping running the engine at 2000 rpm for 30 min. Found no leak from the connection and let the well service team to perform their job and continuous running the engine with 2000 rpm about 1 hour 45 min.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Check again the leakage. Found no leak and engine oil level no drops.<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (4) Keep running the engine for Slick Line activity for 2 hours with 2000 rpm intervalley. Found no leak from connection and engine oil level no drops.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (5) Coolant level is 100% and no drops at all condition.</p><p>Recommended Action : <span style="background-color: rgb(255, 156, 0);">(1) Turbocharger may be internal leakage.</span></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP2\\Crane CR-0273\\2025\\17-Jan-2025 TS Lube Oil Leak from Turbocharger Exhaust Line">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP2\\Crane CR-0273\\2025\\17-Jan-2025 TS Lube Oil Leak from Turbocharger Exhaust Line</a><br></p>', '2025-01-17 19:45:15', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP02-CR-0273', 'ZTK-WP02-CR-0273', 'Pedestal Crane Package WP02', NULL, NULL, 'Pedestal Crane Package WP02', 'WP02', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
