  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify bearing defects as per SKF report', 'Mechanic', 'CM ', 'Completed', '2025-01-20', '<p>Problem : (1) Verify bearing defects as per SKF report.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Belt was touching to the lower edge of the motor pulley.</p><p>Found&nbsp; &nbsp; : (1) When check with water level, motor pulley is out of alignment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(2) Belt teeth was worn out and 50% left.</p><p>Action&nbsp; &nbsp; : (1) Check the bearing condition with scaffold pipe and visually check. Found no abnormal condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Check the bearing lock screws on shaft for both bearings.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Check the tightness of vibration probe.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (4) Replaced the belt with new one.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (5) Make align the motor pulley by adjusting the jack bolts at motor NDE.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (6) Check alignment and set belt tension to 26 Hz (between specification).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (7) Perform test run and found belt touches to the lower edge of the motor pulley.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (8) Adjust shims at motor NDE (both NDE ends) from 3mm to 2.5mm.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (9) Perform test run and unit is running normal and under monitoring.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\44 GAS COMPRESSOR T 3\\GAS COOLER\\E-4460 (Second stage)\\E-4460B\\2025\\2025-01-20 Verify Bearing defect as per SKF report">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\44 GAS COMPRESSOR T 3\\GAS COOLER\\E-4460 (Second stage)\\E-4460B\\2025\\2025-01-20 Verify Bearing defect as per SKF report</a><br></p>', '2025-01-20 17:06:10', '2025-01-20 17:40:36', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EF-4460B', 'ZTK-EF-4460B', '2nd Stg Comp Disch Cooler Fan B', NULL, NULL, '2nd Stg Comp Disch Cooler Fan B', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
