-- Inserting report ID 34786
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS BDG cannot start', 'Electrical & Instrument', 'CM ', 'Completed', '2025-01-22', '<p><u><b>Activity,</b></u></p><p>-TS BDG-7205 tripped by "Vibration Control System Failure" alarm.</p><p><u><b>History,</b></u></p><p>-During 1MPM onload test, BDG tripped by&nbsp; "Vibration Control System Failure" alarm.</p><p>-17 Jan 2024</p><p>-Checked the event log at vibration control module by handheld module.</p><p>-Checked power supply to the module and found normal.</p><p>-Checked the voltage for each sensors at local JB inside enclosure.</p><p>-Found that the sensor 1(Engine Side) &amp; 3(Generator DE) is around 12 VDC and sensor 2(Generator NDE) is around 22 VDC.</p><p>-At the vibration control module, sensor 2 channel show sensor error alarm.</p><p>-Removed and cleaned the sensor2 and reinstalled back but alarm is activate and clear time by time.</p><p>-Confirmed that sensor2 (Generator NDE) is malfunction and disconnected the sensor from the system.</p><p>-For the unit availability, take the signal from sensor3 (Generator DE).</p><p>-Start the unit and performed 1MPM onload test.</p><p><u><b>Equipment description and location,</b></u></p><p>-Black Start Diesel Generator, Lower Deck<br></p><p><u><b>As found,</b></u></p><p>-NA</p><p><u><b>What happen,</b></u></p><p>-NA</p><p><u><b>Action,</b></u></p><p>-Installed the new vibration sensor (P/N.ASA-062/050/1) 60.55.70.251.9.</p><p>-Rerouted the sensor cable and checked the voltage at local JB.</p><p>-Checked the alarm at vibration control module at UCP panel &amp; found normal.</p><p>-"Vibration Control System Failure" alarm is cleared and test run the unit.</p><p>-Now unit is back to normal operation.</p><p><u><b>As left,</b></u></p><p>-Unit Available.</p><p><u><b>Next Plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job Progress,</b></u></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-01-22_BDG-7205 TS Unit Tripped by Vibration Control System Failure Alarm', '2025-01-22 15:46:33', '2025-01-22 15:57:44', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-BDG-7205', 'ZTK-BDG-7205', 'Black Start Diesel Generator Package', NULL, NULL, 'Black Start Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
