  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2025-01-22 15:46:33', '2025-01-22 15:57:44', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine');
