-- Inserting report ID 34807
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Crane Cannot Start at WP-13', 'Mechanic', 'CM ', 'Completed', '2025-01-23', '<p>Problem : Crane cannot start by the crane operator.</p><p>Found&nbsp; &nbsp; : Air inside the diesel fuel line and air shut of valve was still open from last operation.</p><p>Action&nbsp; &nbsp; : Check the diesel fuel line first.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Check the air shut off valve by removing flexible hose.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Pump the priming pump found fuel leak from the vent port and tighten the vent port.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Cranked the engine but cannot run.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Rechecked the fuel line found there is no fuel between the fuel primary filter and priming pump&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; suction.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the primary fuel filter and check fuel inside found only half.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Filled diesel into the primary filter and installed back.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Pumping diesel to the primary filter and the line between priming pump with pressure from the&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; outside.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Finally can start the engine back.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed engine start and stop three times and engine was running normal.</p><p><br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>', NULL, '2025-01-23 22:09:23', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Crane', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-1273-EN', 'ZTK-CR-1273-EN', 'Pedestal Crane Diesel Engine WP12', NULL, NULL, 'Pedestal Crane Diesel Engine WP12', 'WP12', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2025-01-23 22:09:23', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Crane', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Henry', NULL, 'EXTERNAL', '2025-01-23 22:09:23', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Crane', NULL);
