  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S crane cannot start at WP-10', 'Mechanic', 'CM ', 'Completed', '2025-01-24', '<p>Problem : Crane cannot start according to the crane operator report.</p><p>Found&nbsp; &nbsp; : Hydraulic are empty at all of the starting accumulators.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Fuel pressure gauge was damaged.</p><p>Action&nbsp; &nbsp; : Check the fuel line to the pump and pumped the priming up to boost the diesel pressure.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked the air shutoff valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Charged hydraulic pressure to starting accumulator by hand pump.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Test run the engine and found engine is running well.</p>', NULL, '2025-01-24 18:29:54', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Crane', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-1073-EN', 'ZTK-CR-1073-EN', 'Pedestal Crane Diesel Engine WP10', NULL, NULL, 'Pedestal Crane Diesel Engine WP10', 'WP10', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2025-01-24 18:29:54', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Crane', NULL);
