  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform crane CM after CTU activities', 'Mechanic', 'CM ', 'Completed', '2025-01-28', '<p>Found : Engine oil was dirty, coolant come out from the over flow drain, air leak from the air&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;compressor governor and improper spooling at aux hoist.</p><p>27-01-2025</p><p>Action : Changed the engine oil and replace new engine oil filter.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Made flat surface for the engine radiator cup joint because of it was curve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Removed the mounting bolts of air compressor and apply with two washer to completely tighten.</p><p>28-01-2025</p><p>Action :&nbsp; Performed respooling by using snap-lock</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Lower done until the last layer of the drum.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Realigned the wire rope by slowly spooling, during spooling hutting wire rope with soft hammer to&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; made it aligned to the winch drum.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Testing with the load around 2 ton and result is good.</p><p>&nbsp; &nbsp; &nbsp; &nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p>&nbsp;</p>', NULL, '2025-01-27 22:07:03', '2025-01-28 22:24:50', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Crane', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP02-CR-0273', 'ZTK-WP02-CR-0273', 'Pedestal Crane Package WP02', NULL, NULL, 'Pedestal Crane Package WP02', 'WP02', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2025-01-27 22:07:03', '2025-01-28 22:24:50', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Crane');
