  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS crane control power Q11 breaker tripped', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-01-27', '<p><b><u>Activity</u>,</b></p><p>-TS crane SLI not working (Day3)</p><p><b><u>History</u>,</b></p><p>-Continue from 22.01.2025</p><p><u>Equipment description and location</u>,</p><p>-CR-0773 Crane at WP07</p><p><b><u>As found</u>,</b></p><p>-Q11 breaker was tripped and can not reset after opened the Load selector during crane stopped time.</p><p><b><u>What happen</u>,</b></p><p>-Root cause still analyzing.</p><p><b><u>Action</u>,</b></p><p>-Swapped the Q11 breaker with another breaker for confirm the breaker condition.</p><p>-But still tripped the anther breaker after opened the load selector.</p><p>-Reinstalled the Q11 breaker and changed the Main/Aux: selector switch to Aux:.</p><p>-Reset the Q11 breaker that was not tripped after load selector opened.</p><p>-And then Selected the Man/Aux: selector switch to Main that was not tripped the Q11 breaker.</p><p>-Waited about 5mins and check the SLI.</p><p>-Function tested the crane and checked the condition of crane control system that no abnormal found.</p><p><b><u>As left</u>,</b></p><p>-Crane is available</p><p><b><u>Next plan</u>,</b></p><p>-check the cable termination and coil of SOVs which can cause the Q11 breaker trip.</p><p><b><u>Documentation</u>,</b></p><p>-N/A</p><p><b><u>Job progress</u>,</b></p><p>-30%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-01-27_CR-0773_TS SLI not working', '2025-01-28 06:39:48', '2025-02-26 18:25:58', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
