  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS chiller compressor unit A gas leak', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-01-28', '<p><b><u>Activity</u>,</b></p><p>-A-7820 A, T/S chiller compressor unit A (A-1) leak.</p><p><b><u>History</u>,</b></p><p>-Continue from (10-Jan-2025, 12-Jan-2025, 14- Jan-2025)</p><p><b><u>Equipment description and location</u>,</b></p><p>-Topside air cooled chiller compressor A, Lower Deck.</p><p><b><u>As found</u>,</b></p><p>-N/A</p><p><b><u>What happen</u>,</b></p><p>-Unit tripped by refrigerant low pressure alarm during unit changeover</p><p><u>Action</u>,</p><p>-Checked the leak point at the compressor unit&nbsp; A-7820A.</p><p>-Isolated and checked leak points at High and Low sensing lines for compressor.</p><p>-Isolated and checked leak points at compressor suction and discharge lines.</p><p>-After isolated and monitored for 14 days, pressure does not decrease anymore.</p><p>-Charge 25 kg R134a refrigerant and monitor the unit.</p><p>-Suction side low pressure is 23 psi and discharge side high pressure is 223 psi.&nbsp;</p><p>-Running current is 178A.</p><p><u><b>As Left,</b></u></p><p>-Unit is avaliable</p><p><b><u>Next plan</u>,</b></p><p>-Keep monitoring the unit A.</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><b><u>Job progress</u>,</b></p><p>-In progress.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-01-28_A-7820A TS chiller compressor unit A gas leak', '2025-01-28 15:43:09', '2025-02-03 10:15:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
