  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Brown', NULL, 'EXTERNAL', '2025-01-28 15:43:09', '2025-02-03 10:15:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
