-- Inserting report ID 34869
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS crane control power Q11 breaker tripped', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-01-30', '<p><b><u>Activity</u>,</b></p><p>-TS crane control power Q11 breaker tripped (Day4)</p><p><b><u>History</u>,</b></p><p>-Continue from 27-Jan-2025.</p><p><b><u>Equipment description and location</u>,</b></p><p>-CR-0773 Crane at WP07</p><p><b><u>As found</u>,</b></p><p>-NA</p><p><b><u>What happen</u>,</b></p><p>-Q11 breaker tripped during heavy lift operation.</p><p><b><u>Action</u>,</b></p><p>-Checked and retighten the outgoing cables of the Q11 breaker (25A).</p><p>-Measured the SOV coil resistance and retighten the terminations of SOV.</p><p>-That all resistance are show around 37.5Ohm and normal condition.</p><p>-Measured the insulation resistance and retighten the termination of the limit switches.</p><p>-Measured the outgoing voltage of the Q11 CB is 25.63Vdc.(Incoming is around 26Vdc)</p><p>-Checked the Q11 load ampere is 4.52A after load selector closed.</p><p>-Checked the Q11 CB condition with&nbsp; load selector switch closed/opened after closed&nbsp; the 24Vdc Battery CB.(That is no abnormal and Q11 breaker was not tripped)</p><p>-Checked Q11 load ampere with main is 6.3A and Aux is 7.37A during operation with max:3.9 Ton.</p><p><b><u>As left</u>,</b></p><p>-Crane is available</p><p><b><u>Next plan</u>,</b></p><p>-Continue monitor the Q11 CB condition during lifting operation.</p><p><b><u>Documentation</u>,</b></p><p>-N/A</p><p><b><u>Job progress</u>,</b></p><p>-90%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-01-30_CR-0773,TS crane SLI not working', '2025-01-30 21:03:05', '2025-02-26 18:26:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-0773-EN', 'ZTK-CR-0773-EN', 'Pedestal Crane Diesel Engine WP07', NULL, NULL, 'Pedestal Crane Diesel Engine WP07', 'WP07', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2025-01-30 21:03:05', '2025-02-26 18:26:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bo', NULL, 'EXTERNAL', '2025-01-30 21:03:05', '2025-02-26 18:26:09', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead');
