  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP12-UTLG-CR1273-PKG', 'ZTK-WP12-UTLG-CR1273-PKG', 'Pedestal Crane Package WP12', NULL, NULL, 'Pedestal Crane Package WP12', 'WP12', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2025-02-19 20:09:45', '2025-02-22 19:29:42', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Mechanic Team.', NULL, 'EXTERNAL', '2025-02-19 20:09:45', '2025-02-22 19:29:42', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
