-- Inserting report ID 35140
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Top side chiller unit B tripped', 'Electrical & Instrument', 'PM ', 'In Progress', '2025-02-26', '<p><b><u>Activity</u>,</b></p><p>-A-7820 B, T/S chiller compressor unit B (B-2) is tripped.</p><p><b><u>History</u>,</b></p><p>-NA</p><p><b><u>Equipment description and location</u>,</b></p><p>-Topside air cooled chiller compressor B-2, Lower Deck.</p><p><b><u>As found</u>,</b></p><p>-Chiller compressor unit B is tripped by overload alarm(C-7820B-2).</p><p><b><u>What happen</u>,</b></p><p>-Compressor discharge pressure(PTH01B 7820B-2) was over 282.5 psi.</p><p>-Thermal overload(RT3) for KMCC7801B was tripped.</p><p><b><u>Action</u>,</b></p><p>-Checked and replaced with new one for C-7800B &amp; C-7801B load/unload relays.</p><p>(Total used-8 nos / Finder / 24VAC(Coil) / 8A 250VAC(Contact) /40.52.8.024.0000)</p><p>-Checked magnetic contactor and thermal overload condition.</p><p>-Replaced the contact piece for magnetic contactor KMCC7801B.</p><p>-Checked and measured the load/unload SOV for compressor B-1 &amp; B-2.</p><p>-Replaced the new solenoid coil for SOV-7820B-10.</p><p><u><b>As Left,</b></u></p><p>-In progress.</p><p><b><u>Next plan</u>,</b></p><p>-Tomorrow, will perform function test run.</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><b><u>Job progress</u>,</b></p><p>-In progress.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-02-26_A-7820B, TS chiller unit B is tripped', '2025-02-26 16:01:54', '2025-02-26 19:01:23', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-7820B', 'ZTK-A-7820B', 'Air Cooled Chiller Standby Unit', NULL, NULL, 'Air Cooled Chiller Standby Unit', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Joseph', NULL, 'EXTERNAL', '2025-02-26 16:01:54', '2025-02-26 19:01:23', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2025-02-26 16:01:54', '2025-02-26 19:01:23', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
