TO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP06-UTLY-SOLAR', 'ZTK-WP06-UTLY-SOLAR', 'Solar Panels Package of WP06', NULL, NULL, 'Solar Panels Package of WP06', 'WP06', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
