  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS LT show fault high alarm.', 'Electrical & Instrument', 'CM ', 'Completed', '2025-02-28', '<p><strong><u>Activity,</u></strong></p>  <p>-&nbsp;TS LT-10106 show fault high alarm.</p>  <p><strong><u>History,</u></strong></p>  <p>- NA.</p>  <p><strong><u>Equipment description and location,</u></strong></p>  <p>- Level Transmitter for test separator, Lower Deck.</p>  <p><strong><u>As found,</u></strong></p>  <p>- Level sensor malfunction.</p>  <p><strong><u>What happen,</u></strong></p>  <p>- LT shows high alarm time to time.</p>  <p><strong><u>Action,</u></strong></p>  <p>-Replaced new sensor probe (with Flange) and float.</p><p>-Tightened the sensor probe flange with 226 Nm.</p><p>-Performed function test and leak check.</p><p>-Informed CCR to perform function test with water. (OK)</p><p>-Normalized the process and found that the level reading was a bit different compared with LT-10117.</p><p>-Took out the new spare and re-installed the old spare float.</p><p>-Normalized the process and the level reading is in normal same with LT-10117.</p><p>-Performed leak check with site operator,&nbsp; test separator pressurized 24 bar by CCR and found no any leak.</p>  <p><strong><u>As left,</u></strong></p>  <p>- LT-10106 back to normal.</p>  <p><strong><u>Next Plan,</u></strong></p>  <p>- NA.</p>  <p><strong><u>Documentation,</u></strong></p>  <p>- NA.</p>  <p>- Link ()</p>  <p><strong><u>Job Progress,</u></strong></p>  <p>- 100%</p>  <p>&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-02-28_LT-10106, TS LT shows high alarm', '2025-02-28 18:20:43', '2025-02-28 22:15:46', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
