  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Joseph', NULL, 'EXTERNAL', '2025-02-28 18:20:43', '2025-02-28 22:15:46', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
