  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Amot Malfunction', 'Mechanic', 'CM ', 'In Progress', '2025-03-02', '<p><b>2-Mar-2025</b></p><p>Problem : (1) Amot trigger mechanism does not go back to reset position.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) <span style="background-color: rgb(255, 156, 0);">Air flapper valve is not fully closed</span> when triggered by <span style="background-color: rgb(255, 156, 0);">emergency kill switch</span>.</p><p>Action&nbsp; &nbsp; : (1) Replaced Amot vlv with new one.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (2) Inside old one, found that mechanism are corroded.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (3) Perform function test and found that Amot trigger mechanism goes back to reset position when engine pressure reaches to approximately 30 psi. </p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (4) Adjust spring tension to get the suitable engine oil pressure.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (5) Stopped the engine using emergency killed switch. Engine cannot be stopped.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (6) Continue troubleshooting the problem.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP1\\Crane CR-0173\\2025\\2025-03-02 TS Amot Malfunction">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP1\\Crane CR-0173\\2025\\2025-03-02 TS Amot Malfunction</a><br></p>', '2025-03-02 17:10:35', '2025-03-02 17:14:58', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Crane', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP01-CR-0173', 'ZTK-WP01-CR-0173', 'Pedestal Crane Package for ZTK WP01', NULL, NULL, 'Pedestal Crane Package for ZTK WP01', 'WP01', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Yan', NULL, 'EXTERNAL', '2025-03-02 17:10:35', '2025-03-02 17:14:58', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Crane');
