  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS GTC4200 tripped by fuel supply command disagree', 'Electrical & Instrument', 'CM ', 'Completed', '2025-03-03', '<p><u>Activity,</u></p><p>- Troubleshoot&nbsp;GTC-4200 tripped by&nbsp;<b>“FSNL FN_Fuel_Gas_Supply_Valve_Cmd_Disagree” &nbsp;</b>(Fuel Gas Supply Command Disagree)&nbsp;alarm.</p><p><u>History,</u></p><p>- NA</p><p><u>Equipment description and location,</u></p><p>- Gas Turbine Compressor, Upper Deck</p><p><u>As found,</u></p><p>-&nbsp;the&nbsp;<b>SOV-42353A</b>&nbsp;(SIS solenoid) fail signal of&nbsp;<b>SDV-42353</b>(Fuel gas supply shutdown valve).</p><p><u>What happen,</u></p><p>- NA</p><p><u>Action,</u></p><p>-&nbsp;Checked and found that the resistance of solenoids&nbsp;<b>SOV-42353A</b>&nbsp;is quite high&nbsp;<b>(3.318 K-Ohm)</b>. </p><p>- Surveyed record from DEC 2024 FSD, the resistance is&nbsp;<b>207.2 Ohm</b>.</p><ul><li><div class="x_elementToProof">- Replace SIS solenoids&nbsp;<b>SOV-42353A</b>&nbsp;(new solenoid resistance is 200.3 Ohm) and checked the positioner limit switches.</div><div class="x_elementToProof">- After the solenoids replacement, cleared all alarms and performed function test with CCR.</div><div class="x_elementToProof">- Handover to production team and stat the unit.</div></li></ul><p><u>As left,</u></p><p>-&nbsp; Unit is running with full load.</p><p><u>Next Plan,</u></p><p>- NA</p><p><u>Documentation,</u></p><p>- NA.</p><p>- Link ()</p><p><u>Job Progress,</u></p><p>-100% complete</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-03-02_GTC4200, TS Unit Trip by SDV-42353 discrepency alarm', '2025-03-03 01:32:21', '2025-03-03 01:32:50', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
