  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS LT calibration and function test', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-03-04', '<p><u>Activity</u>,</p><p>-TS level transmitters for test separator, LT-13106 and LT-13117.</p><p><u>History</u>,</p><p>-N/A</p><p><u>Equipment description and location</u>,</p><p>-Level Transmitters for test separator, WP-13</p><p><u>As found</u>,</p><p>-The level readings are different.</p><p><u>What happen</u>,</p><p>-NA</p><p><u>Action</u>,</p><p>-Checked the transmitters for LRV and URV. (0 - 80 cm)</p><p>-Isolated and drain the level transmitters. (Found sludges).</p><p>-Flushed with water for three or four times.</p><p>-Checked if the reading for level indicators and level transmitters are same (Same).</p><p>-Normalized the isolation for both level transmitters. (Both show at first around 0% after normalize)</p><p>-After sometime, the level readings increased for LT-13117 up 100% but still 0% for LT-13106).</p><p>-Isolated the level transmitter for LT-13106 and drained. (Found some sludge).</p><p>-Flushed again with water to LT-13106 line and top up water same with LT-13117 and normalize.</p><p>-Suspected that the level transmitters line is blocked with sludge inside the vessel.</p><p>-The level transmitters are good.</p><p><u>As left,</u></p><p>-Both level transmitters are up to almost 100% and informed CCR to drain the test separator to check if the level reading is reduced from both transmitter equally.</p><p><u>Next plan</u>,</p><p>-NA</p><p><u>Documentation</u>,</p><p>-N/A</p><p><u>Job progress</u>,</p>-100%', '<p><a href="M:\\01 E&amp;I\\Activity Photos\\2025-03-4_TS LT calibration and function test on LT-13106 &amp; LT-13117">M:\\01 E&amp;I\\Activity Photos\\2025-03-4_TS LT calibration and function test on LT-13106 &amp; LT-13117</a><br></p>', '2025-03-04 21:18:04', '2025-03-04 21:24:06', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
