-- Inserting report ID 35261
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '4K PM Crank Soak Wash ', 'Mechanic', 'PM ', 'Completed', '2025-03-08', '<p>Performed crank soak wash.</p><p><u><br></u></p><p>(1)&nbsp; &nbsp; Remove piping accessary.</p><p>(2)&nbsp; &nbsp; Remove ignition cable and install dummy spark plug.</p><p>(3)&nbsp; &nbsp; Install air supply 30 psi to bearings seals.</p><p>(4)&nbsp; &nbsp; Open air inlet premium manhole and Turbine air inlet filter duct to collect chloride sample. (Before and after)</p><p>(5)&nbsp; &nbsp; Fill cleaning product ZOK 1 pail and Deionized water 4 pail into mobile injection tank.</p><p>(6)&nbsp; &nbsp; Crank engine by using test crank mode.</p><p>(7)&nbsp; &nbsp; Open the spray valve 50% at the package to spray cleaning product while engine NGP reach to 20%.</p><p>(8)&nbsp; &nbsp; Step of cleaning</p><table class="table table-bordered"><tbody><tr><td><br></td><td>ZOK + Water</td><td>Soaking time</td></tr><tr><td>1st attempt</td><td>50%&nbsp;</td><td>15 mins</td></tr><tr><td>2nd attempt</td><td>50%&nbsp;</td><td>15 mins</td></tr></tbody></table><p>(9)&nbsp; &nbsp; Take water sample from combustor drain port.&nbsp;</p><p>(10)&nbsp; &nbsp; Wait for 15 min then continue process washing.</p><p>(11)&nbsp; &nbsp; Step of rinse water</p><p>&nbsp;Fill Deionized water 5 pail into mobile injection tank</p><table border="1" cellspacing="0" cellpadding="0"><tbody><tr><td width="126" valign="top"><p>&nbsp;</p></td><td width="198" valign="top"><p align="center">Spray</p></td><td width="198" valign="top"><p align="center">Stop</p></td></tr><tr><td width="126" valign="top"><p>1st&nbsp;Rinse</p></td><td width="198" valign="top"><p align="center">8 min</p></td><td width="198" valign="top"><p align="center">10 min</p></td></tr><tr><td width="126" valign="top"><p>2nd&nbsp;Rinse</p></td><td width="198" valign="top"><p align="center">8 min</p></td><td width="198" valign="top"><p align="center">10 min</p></td></tr></tbody></table><p>(12)&nbsp; &nbsp;Dry crank 8 min for 2 time.</p><p>(13)&nbsp; &nbsp;Reinstated piping and replaced new spark plug.</p><p>(14)&nbsp; &nbsp;Apply CI to VIGV.</p><p>(15)&nbsp; Clean the inside by utility air.&nbsp;</p><p>Running Hour: 33051 Hr. Start Count 37.</p><p><br></p><p>Chloride content at downstream of final engine air inlet filter and air inlet plenum.</p><p><br></p><p></p><p><br></p><p>Water properties analysis collected from combustor drain port.&nbsp;</p><p></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\44 GAS COMPRESSOR T 3\\2025\\2025-03-08 Perform Crane Soak Wash (4K PM)">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\44 GAS COMPRESSOR T 3\\2025\\2025-03-08 Perform Crane Soak Wash (4K PM)</a><br></p>', '2025-03-09 15:13:14', '2025-03-10 07:56:27', 'PTTEP\\ZPQ.Mechanical-Turbi', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
