-- Inserting report ID 35300
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'EDG 6M PM', 'Mechanic', 'PM ', 'Completed', '2025-03-12', '<p>Action: Inspected and check door lock mechanism.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Perform visual inspection for,</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Diesel oil level = 85%.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Hydraulic oil level = 80% (when fully charged 3 accumulators)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Hydraulic pressure = 200 barg.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Flexible hoses condition = Condition is good.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Coolant level = 100%. (PH level 8)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Cooler fan belt condition = Condition is good.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Crankcase breather condition = Condition is good.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Air filter condition = Condition is good.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Centrifugal oil filter condition = Condition is good.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Oil filter condition are good. (Last changed is on 25/Sep/23 and RH = 2324, <span style="background-color: rgb(0, 255, 0);">service hour = 24</span>, on 12/Mar/25 and RH = 2348)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Fuel filter condition are good. (Last changed is on 25/Sep/23 and RH = 2324,&nbsp;<span style="background-color: rgb(0, 255, 0);">service hour = 24</span>, on 12/Mar/25 and RH = 2348)<br></p><p><br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Perform test run. Parameters are;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Engine speed = 1500 RPM</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Lube oil pressure = 6.7 barg</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Lube oil temp = 62 *C</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Coolant temp = 64 *C</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Charge air temp = 37 *C</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Charge air pressure = 1.2 barg</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Exhaust temp bank A = 81 *C</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Exhaust temp bank B = 316 *C</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Engine running hour = 2348 hr</p><p><br></p><p>Found : (1) Found hydraulic oil seeping from HYD Oil Filter connection and retightened the fitting.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(2) Found excessive corrosion at local control skid floor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(3) CO2 cylinders, safety team preserve 2EA and the existing one are to be hydro tested.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\72 MAIN &amp; VITAL POWERr GENERATION\\7200 Emergency Diesel Generator\\2025\\2025-03-12 Perfrom 6M PM">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\72 MAIN &amp; VITAL POWERr GENERATION\\7200 Emergency Diesel Generator\\2025\\2025-03-12 Perfrom 6M PM</a><br></p>', '2025-03-12 14:51:30', '2025-03-12 17:50:36', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
