DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace Helium cylinder No.02 at OGC', 'Electrical & Instrument', 'CM ', 'Completed', '2025-03-13', '<p><u><b>Activity</b></u>,</p><p>-Replace helium cylinder No.02 at OGC skid</p><p><b><u>History</u>,</b><br class="Apple-interchange-newline"></p><p>-N/A</p><p><u><b>Equipment description and location</b></u>,</p><p>-AE-46001- GC analyzer skid, Cooler Deck&nbsp;&nbsp;</p><p><u><b>As found</b></u>,</p><p>-Helium cylinder No.02 is empty.</p><p><u><b>What happen</b></u>,</p><p>-N/A</p><p><u><b>Action</b></u>,</p><p>-Isolate the valve of the empty cylinder</p><p>-Isolate the valve No.3 Helium gas supply to GC</p><p>-Turn around the pressure regulator counter-clock wise direction&nbsp;</p><p>-Open the vent valve No.4 and depressurized the trapped pressure</p><p>-Remove the tubing fitting and pressure regulator&nbsp;</p><p>-Replace with new helium cylinder from spare rack</p><p>-Connect the tubing fitting and pressure regulator&nbsp;</p><p>-Close the vent valve and open the new cylinder&nbsp;</p><p>-Perform check leak test for the cylinder side</p><p>-Open vent valve No.4 and <span style="background-color: rgb(255, 255, 0);">purging</span> the moisture inside</p><p>-Adjust the required pressure 105 psi with vent valve open position</p><p>-Close the vent valve No.4 and leak test again</p><p>-De-isolate the valve No.3 and cylinder No.02 helium gas supply to GC</p><p>-Keep monitor the pressure stable and final leak test&nbsp; &nbsp; &nbsp;&nbsp;</p><p><u><b>As left</b></u>,</p><p>-Helium cylinder No.01= 1790 psi / 107 psi</p><p>-Helium cylinder No.02= 2100 psi / 104 psi</p><p><u><b>Next plan</b></u>,</p><p>-N/A</p><p><u><b>Documentation</b></u>,<br class="Apple-interchange-newline"></p><p>-N/A</p><p><u><b>Job progress</b></u>,</p><p>- 100% job completed.</p>', '<p><a href="M:\\01 E&amp;I\\Activity Photos\\13-03-2025_OGC_Replace the helium cylinder no.02 at OGC analyzer">M:\\01 E&amp;I\\Activity Photos\\13-03-2025_OGC_Replace the helium cylinder no.02 at OGC analyzer</a><br></p>', '2025-03-13 15:26:02', '2025-03-16 18:17:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-ATR-46000', 'ZTK-ATR-46000', 'Gas Composition Analyzer Rack', NULL, NULL, 'Gas Composition Analyzer Rack', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
