  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix Water Leak at cold water line for Room 328', 'Mechanic', 'CM ', 'Completed', '2025-03-13', '<p><u><b>Finding<br></b></u><br></p><p>-Water seeping from cold water line isolation valve for room no-328</p><p>-Found that RTV was not attached to the valve seeping point</p><p><br></p><p><u><b>Action</b></u></p><p><br></p><p>-Clear RTV&nbsp;</p><p>-Clean the valve body and threads of the union fitting&nbsp;&nbsp;</p><p>-Applied RTV to the contact point of the union joint.</p><p>-Wait 1 Hr for RTV curing</p><p>-Open the insolation valve and pressurize the water line&nbsp;</p><p>-Found no leak</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\115 LQM Utility\\2025\\2025-03-13 Room 328 water leak">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\115 LQM Utility\\2025\\2025-03-13 Room 328 water leak</a><br></p>', '2025-03-13 17:23:39', '2025-06-22 16:23:38', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
