  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Top side chiller unit B tripped', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-03-14', '<p><b><u>Activity</u>,</b></p><p>-T/S Chiller unit-B (A-7820B) tripped by High pressure alarm (Top Side)</p><p><b><u>History</u>,</b></p><p>-Continued from 10 Mar 2025 and 13 Mar 2025.&nbsp;</p><p><b><u>Equipment description and location</u>,</b></p><p>-Air cooled chiller unit-B, Lower Deck.</p><p><b><u>As found</u>,</b></p><p>-Chiller unit-B not available.</p><p><b><u>What happen</u>,</b></p><p>-Compressor unit B-2 is tripped circuit -2 high pressure alarm and not found gas flow from sight glass at Chiller compressor discharge line when unit running.</p><p><b><u>Action</u>,</b></p><p>-Run the vacuum pump to perform evacuation task around 30 min and the result is 1444 micron.(Medium Vacuum - 1500 micron)</p><p>-Recharged the refrigerant gas.(Refrigerant Used = 13.6 kg/CYL)</p><p>-Performed test run the chiller unit-B.</p><p>-Chiller unit-B is running and keep monitoring the unit-B.</p><p>-Stopped the unit and test run again.</p><p>-Found unit can not start by overload alarm(C-7820B-2).</p><p><u><b>As left,</b></u></p><p>-Unit B is not available and <b>Unit A is DUTY</b>.</p><p>-On hand full refrigerant cylinder - 19 CYL.</p><p><b><u>Next plan</u>,</b></p><p>-Continued to be troubleshoot.</p><p><b><u>Documentation</u>,</b></p><p>-NA</p><p><b><u>Job progress</u>,</b></p><p>-In progress.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-03-14_A-7820B, TS chiller unit B is tripped', '2025-03-14 16:14:53', '2025-03-18 16:44:58', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
