-- Inserting report ID 35343
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Top side chiller unit B tripped', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-03-16', '<p><u>Activity</u>,</p><p>-T/S Chiller unit-B (A-7820B) tripped by High pressure alarm (Top Side)</p><p><u>History</u>,</p><p>-Continued from 10, 13 and 14 of Mar 2025.&nbsp;</p><p><u>Equipment description and location</u>,</p><p>-Air cooled chiller unit-B, Lower Deck.</p><p><u>As found</u>,</p><p>-Chiller unit-B not available.</p><p>-The hexagonal bolt for thermal expansion valve was hard to remove. (corroded)/So cut from the tip of the bolt with handsaw.</p><p><u>What happen</u>,</p><p>-Compressor unit B-2 is tripped circuit -2 high pressure alarm and not found gas flow from sight glass at Chiller compressor discharge line when unit running.</p><p><u>Action</u>,</p><p>-Released the refrigerant from the line of compressor No.2.</p><p>-Removed the thermal expansion valve which is suspected malfunction.</p><p>-Adjusted the new thermal expansion valve spring same with the removed one via no. of thread sizes.</p><p>-Flushed the line from the filter dryer to the thermal expansion valve(Before install). (To make sure the filter dryer are not block and to clear the line)</p><p>-Re-installed the new thermal expansion valve and capillary tube bulb. (4 hours position)</p><p>-Run the vacuum pump to perform evacuation task. (On going).</p><p><u>As left,</u></p><p>-NA</p><p><u>Next plan</u>,</p><p>-Vacuum process to the low side (in progress).</p><p>-Vacuum process to the high side.</p><p>-Charge the refrigerant to the line.</p><p>-Check leak.</p><p>-Applied the insulation sheet to the pipe.</p><p>-Test run</p><p><u>Documentation</u>,</p><p>-NA</p><p><u>Job progress</u>,</p><p>-In progress.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-16-2025_TS Chiller 7820', '2025-03-16 15:42:36', '2025-03-17 08:14:26', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-7820B', 'ZTK-A-7820B', 'Air Cooled Chiller Standby Unit', NULL, NULL, 'Air Cooled Chiller Standby Unit', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2025-03-16 15:42:36', '2025-03-17 08:14:26', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
