-- Inserting report ID 35353
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Top side chiller unit B tripped', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-03-17', '<p><u>Activity</u>,</p><p>-T/S Chiller unit-B (A-7820B) tripped by High pressure alarm (Top Side)</p><p><u>History</u>,</p><p>-Continued from 10, 13, 14 and 16 of Mar 2025.&nbsp;</p><p><u>Equipment description and location</u>,</p><p>-Air cooled chiller unit-B, Lower Deck.</p><p><u>As found</u>,</p><p>-Chiller unit-B not available.</p><p>-The hexagonal bolt for thermal expansion valve was hard to remove. (corroded)/So cut from the tip of the bolt with handsaw.</p><p><u>What happen</u>,</p><p>-Compressor unit B-2 is tripped circuit -2 high pressure alarm and not found gas flow from sight glass at Chiller compressor discharge line when unit running.</p><p><u>Action</u>,</p><p>-Run the vacuum pump for high side and low side until the result is 1440 micron.</p><p>-Charged the refrigerant to the line until 45 psi and check leak and monitor for 1.5 hours. (No leak)</p><p>-Normalize and run the chiller. (As found PTH01B/PTL01B : 255 / 32 psi, Average ampere : 200 Amp)</p><p>-After running for 1 hour, the PTH01B / PTL01B : 195 / 37 psi, Average ampere: 110 Amp)</p><p>-As-found sub-cooling and superheat : 39.3 / 21.5 degree celcius.</p><p>-Applied the insulation to the pipe.</p><p><u>As left,</u></p><p>-As-left: - PTH01B/PTL01B : 194.7/37.3 psi,</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- Evaporator Temp : 5.7 degree celcius,</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;- Condensing Coil Temp : 53.7 degree celcius,</p><p><u>Next plan</u>,</p><p>-NA</p><p><u>Documentation</u>,</p><p>-NA</p><p><u>Job progress</u>,</p><p>-In progress.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-03-17_A-7820B, TS top side chiller B cannot start">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-03-17_A-7820B, TS top side chiller B cannot start</a><br></p>', '2025-03-17 16:35:23', '2025-03-18 16:50:15', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-7820B', 'ZTK-A-7820B', 'Air Cooled Chiller Standby Unit', NULL, NULL, 'Air Cooled Chiller Standby Unit', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
