  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S the aviation solar charger alarm.', 'Electrical & Instrument', 'CM ', 'Completed', '2025-03-17', '<p><u><b>Activity,</b></u></p><p>-T/S the aviation solar charger alarm.</p><p><u><b>History,</b></u></p><p>- NA.</p><p><u><b>Equipment description and location,</b></u></p><p>-Pedestal crane solar charger, WP-04.</p><p><u><b>As found,</b></u></p><p>-Aviation solar charger alarm at junction box.</p><p>-High battery voltage alarm at solar charger controller.</p><p>-Solar charger controller setting, (<span style="background-color: rgb(255, 255, 0);">High voltage alarm - 30V, Boost charging voltage - 29V, Float charging voltage - 27.6V)</span></p><p><u><b>What happen,</b></u></p><p>- NA.</p><p><u><b>Action,</b></u></p><p>-Checked solar controller charger alarm. (High voltage alarm was activated)</p><p>-Measured&nbsp;&nbsp;incoming voltage from solar panel. (Solar array 1 - 39.57V, array 2 - 39.57V)</p><p>-Measured battery voltage for both battery bank. (Bank 1 - 15.61V, Bank 2 - 15.46v, Total voltage - 31.05V)</p><p>-High voltage alarm was activated due to Battery voltage was higher than high voltage alarm.</p><p>-Measured charging current during alarm was activated. (charging current 0A).</p><p>-Disconnected the incoming voltage form solar panel and discharged battery banks by manually turn on the aviation light. (Discharge battery to 25.5V)</p><p>-Charged the battery again and measured the charging voltage - 29V.</p><p>-Alarm also clear.</p><p><u><b>As left,</b></u></p><p>-Alarm was cleared.</p><p><u><b>Next Plan,</b></u></p><p>-If the alarm occurred again, need to verify the alternator charger.</p><p><u><b>Documentation,</b></u></p><p>- NA.</p><p>- Link ()</p><p><u><b>Job Progress,</b></u></p><p>- 100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-03-17_TS WP04 Crane Solar Charger Regulator HI Battery Volt Alarm', '2025-03-17 20:22:38', '2025-03-18 22:11:13', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-0473-EN', 'ZTK-CR-0473-EN', 'Pedestal Crane Diesel Engine WP04', NULL, NULL, 'Pedestal Crane Diesel Engine WP04', 'WP04', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
