-- Inserting report ID 35370
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Chiller unit-B tripped by High pressure', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-03-19', '<p><u>Activity</u>,</p><p>-T/S Chiller unit-B (A-7820B) tripped by High pressure alarm (Top Side)</p><p><u>History</u>,</p><p>-Continued from 10, 13, 14, 16&nbsp; and 18 of Mar 2025.&nbsp;</p><p><u>Equipment description and location</u>,</p><p>-Air cooled chiller unit-B, Lower Deck.</p><p><u>As found</u>,</p><p>-The pressures are more than normal.</p><p>-While releasing the pressure, found that there are a little oily from LP side of the compressor. Not much oily from HP side.</p><p>-The water is not condensed around the area of TXV (thermal expansion valve), suspected that the TXV is overfeeding.</p><p><u>What happen</u>,</p><p>-While running, the pressure is tripped by high pressure alarm yesterday.</p><p><u>Action</u>,</p><p>-Reduced the pressure from high side and low side of compressor while running.</p><p>&nbsp; &nbsp; Before: Low Pressure : 40 psi (at F-L)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;High Pressure : 260 psi (at F-L)</p><p>&nbsp; &nbsp; After: Low Pressure : 37-34.8 psi (at F-L and 75%)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;High Pressure : 240 - 190 psi (at F-L and 75%)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Average Ampere : Around 110-120 A</p><p>-Adjusted the thermal expansion valve (increase) into 4/4 turn.</p><p><br></p><p>&nbsp; <b><i>Note: Release the pressure from high side after 5 sec starting.</i></b></p><p><u>As left,</u></p><p>-Low Pressure: 34.8 psi at 50% load</p><p>-High Pressure: 190 psi at 50% load</p><p>-Average Ampere: 110 A.</p><p><u>Next plan</u>,</p><p>-Keep running and adjusted the TXV if needed.</p><p><u>Documentation</u>,</p><p>-NA</p><p><u>Job progress</u>,</p><p>-In progress.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-03-19_TS Chiller 7820-B High Pressure">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-03-19_TS Chiller 7820-B High Pressure</a><br></p>', '2025-03-19 16:13:27', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-7820B', 'ZTK-A-7820B', 'Air Cooled Chiller Standby Unit', NULL, NULL, 'Air Cooled Chiller Standby Unit', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2025-03-19 16:13:27', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2025-03-19 16:13:27', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL);
