  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS sump pump cannot operate', 'Electrical & Instrument', 'CM ', 'Completed', '2025-03-20', '<div><u>Activity</u>,</div><div><p>-TS sump pump cannot operate at WP-07.</p><p><u>History</u>,</p><p>- N/A</p><p><u>Equipment description and location</u>,</p><p>- Sump pump, Sea Deck, WP-07.</p><p><u>As found</u>,</p><p>-The pump is operating at as-found PCV (3 bar).</p><p>-The sump tank level is dropped but the discharge pressure is lower than sea-line pressure. (discharge pressure : 26 bar and sea-line pressure : 27 bar)</p><p><u>What happen</u>,</p><p>-PCV 3 bar is much more for operating the sump pump. (too fast operating the pump)</p><p><u>Action</u>,</p><p>-Reduced the PCV to 2 bar and check the discharge pressure built up to 27.4 bar. (Sea-line pressure : 27 bar)</p><p>-The level is dropped.</p><p>-Check leak. &gt; No leak.</p><p><u>As left</u>,</p><p>-Pump is working properly. (The sump tank level is low)</p><p><u>Next plan</u>,</p><p>-NA</p><p><u>Documentation</u>,</p><p>- N/A</p><p>-Link ()</p><p><u>Job progress</u>,</p><p>-100% Completed</p></div>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-03-20_P-0752, TS sump pump cannot operate at WP-07">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-03-20_P-0752, TS sump pump cannot operate at WP-07</a><br></p>', '2025-03-20 22:58:25', '2025-03-20 23:02:35', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
