-- Inserting report ID 35382
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S engine speed drop and HYD leak ', 'Mechanic', 'CM ', 'In Progress', '2025-03-20', '<p>Problem: Hydraulic oil leaking at auxiliary anti two block.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Engine speed suddenly drop during boom up and down.</p><p><br></p><p>Found : HYD oil was leak from anti two block switch due to switch spool was rusty.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;When using crane bypass with the fuel shut off valve, the valve was not fully open.</p><p><br></p><p>Action : -The out side part AUX anti two block switch was rusty and when its activated HYD was seeping&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;from&nbsp; this spool.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Removed anti two block valve from it''s assembly.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Applied RTC to the sealing surface of switch''s spool and removed rusty from it''s surface and&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; reinstate back.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Removed all the engine''s bypass and let fully open the fuel shut off valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Using three function the engine''s RPM was not drop.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Actual problem is when fuel shutoff valve was bypassed the valve was not fully open and that&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;condition restrict the fuel flow to made RPM drop during running.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><div><br></div><p></p>', NULL, '2025-03-20 23:07:08', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-0773-EN', 'ZTK-CR-0773-EN', 'Pedestal Crane Diesel Engine WP07', NULL, NULL, 'Pedestal Crane Diesel Engine WP07', 'WP07', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2025-03-20 23:07:08', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'John', NULL, 'EXTERNAL', '2025-03-20 23:07:08', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
END $$;

