-- Inserting report ID 35417
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fixed gas leak in valve control panel', 'Electrical & Instrument', 'CM ', 'Completed', '2025-03-24', '<p><u><b>Activity,</b></u></p><p>-&nbsp;Fixed gas leak in valve control panel of ESDV-06211</p><p><u><b>History,</b></u></p><p>- NA.</p><p><u><b>Equipment description and location,</b></u></p><p>- ESDV for WP-06 Export Line , Sump Deck.</p><p><u><b>As found,</b></u></p><p>- Gas seeping from regulator inlet connector.</p><p><u><b>What happen,</b></u></p><p>- Tube connection was loosening.</p><p><u><b>Action,</b></u></p><p>- Removed the tube connector after platform ESD 2.</p><p>- Inspected the connector thread that are normal condition.</p><p>- Retightened the connector and gas leak check with pressure 5 bar about 5mins.</p><p>- Gas leak checked for all connector during valve function test.(Normal).</p><p>- Recorded the valve travelling time that opening time 11Seconds and closing time 10Seconds.</p><p><u><b>As left,</b></u></p><p>- ESDV valve operated without gas seeping.</p><p><u><b>Next Plan,</b></u></p><p>- NA.</p><p><u><b>Documentation,</b></u></p><p>- NA.</p><p>- Link ()</p><p><u><b>Job Progress,</b></u></p><p>- 100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-03-24_Fix Gas Seeping ESDV-06211', '2025-03-24 23:33:28', '2025-03-25 00:02:56', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-ESDV-06211', 'ZTK-ESDV-06211', 'ESDV on 18"-GC-06011-B31.8 for ESD 1,2C', NULL, NULL, 'ESDV on 18"-GC-06011-B31.8 for ESD 1,2C', 'WP06', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
