  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Remove Turbo Charger at WP-07(CR-0773)', 'Mechanic', 'CM ', 'In Progress', '2025-03-25', '<p>Problem : Smoke come out from the crane compartment during engine running.</p><p><br></p><p>Found&nbsp; &nbsp; : Lube oil come out from the engine''s turbo charger drain line to insulation and then smoke come&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;out.</p><p><br></p><p>Action&nbsp; &nbsp; : -Firstly check the engine for any oil leak and oil leak found from the turbo charger.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Tighten the bolts of turbo charger lube oil drain.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Test run the engine and abnormal noise come out from the turbocharger.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Removed the oil and air connection from the turbo charger.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Removed the turbo charger from the engine.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Found blade of the turbo charger''s compressor side was broken, found lock nut for shaft is&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; detached and drop and also some marks found on the turbine side.</p><p><br></p>', NULL, '2025-03-25 19:39:16', '2025-03-28 08:42:24', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-TeamL', false, 'ZTK') RETURNING id INTO new_report_id;
