  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix PDT malfunction ', 'Electrical & Instrument', 'CM ', 'Completed', '2025-04-01', '<p><b><u>Activity</u>,</b></p><p>-T/S transmitter malfunction.(PDT-86151)</p><p><b><u>History</u>,</b><br class="Apple-interchange-newline"></p><p>-Continue from 30.Mar.2025.</p><p><b><u>Equipment description and location</u>,</b></p><p>-Diff Pressure transmitter of Level 1 Air Lock , LQM Level - 1.</p><p><b><u>As found</u>,</b></p><p>-Found transmitter voltage drop to 2.9Vdc.</p><p><b><u>What happen</u>,</b></p><p>-Transmitter (AI Channel AI000) was malfunction.</p><p><b><u>Action</u>,</b></p><p>-Replaced the malfunctioning AI channel AI000 with the spare AI015 cable, connecting it to transmitter terminal TB2 No.2.</p><p>-Updated the mapping of AI channel AI000 to AI015.</p><p>-Checked at the local transmitter and found that transmitter power supply returned to normal.</p><p>-Normalized the transmitter, performed function test and confirmed the readings with HMI.</p><p>-Transmitter is working properly.</p><p><b><u>As left</u>,</b></p><p>-PDT-86151 back to normal. (reading 37 Pa)</p><p><b><u>Next plan</u>,</b></p><p>-NA</p><p><b><u>Documentation</u>,</b><br class="Apple-interchange-newline"></p><p>-N/A</p><p>-Link ()</p><p><b><u>Job progress</u>,</b></p><p>-100%&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-04-01_PDT-86151, To fix PDT malfunction', '2025-04-01 16:55:11', '2025-04-01 17:01:59', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
