  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace bearing as per SKF report', 'Mechanic', 'CM ', 'Completed', '2025-04-07', '<p>Issue: To replace upper fan bearing as per SKF report and bearing abnormal noise.</p><p><br></p><p>On 06-04-2025:</p><p>-Remove fan cover and belt.</p><p>-Remove air shield.</p><p>-Install scaffold pipe for lifting points.</p><p>-Install chain blocks.</p><p>-Remove fan pulley.</p><p>-Remove fan.</p><p>-Remove shaft.</p><p>-Remove bearing. Clean all hardware parts.</p><p>-Replace new bearing.</p><p>&nbsp; &nbsp; Note: Upper bearing is NSK brand.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Lower bearing is LKN brand.<br></p><p>-Install bearing and shaft.</p><p>-Tighten with torque 650 ft-lb.</p><p>-Install fan.</p><p><br></p><p>On 07-04-2025:</p><p>-Install fan pulley.</p><p>-Remove lifting gears.</p><p>-Install air shield.</p><p>-Perform motor pulley alignment.</p><p>-Install belt and adjust tension (26 Hz).</p><p>-Perform test run.</p><p>-Unit is back to normal.</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\GAS COOLER FAN (E-4360-A and E-4360B)\\E-4360 (2nd Stage)\\E-4360A\\2025\\2025-04-06 Replace bearing">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\GAS COOLER FAN (E-4360-A and E-4360B)\\E-4360 (2nd Stage)\\E-4360A\\2025\\2025-04-06 Replace bearing</a><br></p>', '2025-04-06 19:03:14', '2025-04-07 18:14:03', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
