  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS WP-10 crane cannot start', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-04-07', '<p><u><b>Activity,</b></u></p><p>-T/S Crane cannot start (CR-1073).</p><p><u><b>History,</b></u></p><p>-Continue from 06.Apr.2025.</p><p><u><b>Equipment description and location,</b></u></p><p>-Pedestal Crane,WP-10</p><p><u><b>As found,</b></u></p><p>- EMS show ****RPM and crane cannot start.</p><p><u><b>What happen,</b></u></p><p>- Engine Control system (ECM) power loosen.&nbsp;</p><p><u><b>Action,</b></u></p><p>-Replaced the new tachometer for existing on to confirm the RPM.</p><p>-Checked the Engine Control system (ECM) that was power loss.</p><p>-Inspected the power system that found alternator excitation power cable was short circuit.</p><p>-Checked the alternator that was damaged.</p><p>-After removed the alternator, found that alternator, cooling fan and pully was damaged.</p><p>-That cannot be replaced with spare alternator.</p><p><u><b>As left,</b></u></p><p>-Crane out of service.</p><p><u><b>Next Plan,</b></u></p><p>-Plan to replace with WP-11 alternator.</p><p>-To retify the cooling fan and pully of damaged alternator.</p><p><u><b>Documentation,</b></u></p><p>-NA.</p><p><u><b>Job Progress,</b></u></p><p>-70% completed</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-04-07_CR-1073_TS crane cannot start', '2025-04-07 21:41:46', '2025-04-14 06:24:10', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
