DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS E-4750 & E-4752 during GDU Train-1 start up ', 'Electrical & Instrument', 'CM ', 'Completed', '2025-04-10', '<p><u><b>Activity,</b></u></p><p>-Troubleshoot pilot tubes E-4750 and E-4752 for GDU Train-1 unit start up</p><p><u><b>History,</b></u></p><p>-NA.</p><p><u><b>Equipment description and location,</b></u></p><p>-E-4750 &amp; E-4752, GDU-4700 (Upper deck).<br></p><p><u><b>As found,</b></u></p><p>-E-4752 shows unstable flame monitor signal during start up</p><p><u><b>What happen</b>,</u></p><p>-E-4752 air flow adjuster was corroded and surface is not clean</p><p><u><b>Action</b>,</u></p><p>-Starting GDU-4700 (Train-1) after 6MPM E-4750 &amp; E-4752 and 12M PM CO2 injection skid.</p><p>-E-4750 &amp; E-4752 shows pilot flame monitor signal low and current signal unstable.</p><p>-E-4750 cleans the air flow adjuster and monitor the flame signal.</p><p>-E-4752 cleans the air flow adjuster and monitor the flame signal.</p><p>-E-4750 can build up and stable in micro Amp current signal. (21.35 u Amp DC)</p><p>-E-4752 shows transient pilot flame monitor signal and unstable micro Amp values. (Need to be replaced)</p><p>-Replace with overhauled pilot tube E-4752 and GDU Train-1 unit start up again</p><p>-Measure pilot flame monitor signal for both tubes E-4750 and E-4752. </p><p>(E-4750= 18.42 u Amp, E-4752= 20.55 u Amp)&nbsp;&nbsp;</p><p><u><b>As Left,</b></u></p><p>-GDU Train-1 is unit running and monitor by CCR.</p><p><u><b>Next Plan</b>,</u></p><p>-NA</p><p><u><b>Documentation</b>,</u></p><p>-NA</p><p><u><b>Job Progress</b>,</u></p><p>-100% completed.</p>', '<p><a href="M:\\01 E&amp;I\\Activity Photos\\2025-04-10_GDU-4700_GDU Train-1 unit start up and TS E-4752 pilot flame monitor unstable">M:\\01 E&amp;I\\Activity Photos\\2025-04-10_GDU-4700_GDU Train-1 unit start up and TS E-4752 pilot flame monitor unstable</a><br></p>', '2025-04-10 20:00:48', '2025-04-12 18:39:36', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
