  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot pilot tubes E-4850 and E-4852 ', 'Electrical & Instrument', 'CM ', 'Completed', '2025-04-12', '<p><u><b>Activity,</b></u></p><p>-Troubleshoot pilot tubes E-4850 and E-4852 for GDU Train-2 was tripped by pilot flame off</p><p><u><b>History,</b></u></p><p>-NA.</p><p><u><b>Equipment description and location,</b></u></p><p>-E-4850 &amp; E-4852, GDU-4800 (Upper deck).<br></p><p><u><b>As found,</b></u></p><p>-GDU-4800 was tripped and cannot start up the main burner</p><p>-E-4850 shows unstable flame monitor signal</p><p><u><b>What happen,</b></u></p><p>-GDU-4800 was tripped by pilots flame off during strong weather&nbsp;</p><p><u><b>Action,</b></u></p><p>-GDU-4800 (Train-2) was tripped by both pilots flame off (E-4850 &amp; E-4852)</p><p>-Perform starting up the GDU unit again, GDU was tripped by unstable flame signal.</p><p>-E-4850 &amp; E-4852 shows pilot flame monitor signal low and current signal unstable.</p><p>-Perform jump start the both pilot monitor signals and monitor the flame condition&nbsp;</p><p>-E-4850 shows transient pilot flame monitor signal.(10.34 uA)</p><p>-E-4850 do cleaning the air flow adjuster and monitor the flame signal.</p><p>-E-4852 shows good in pilot flame signal.(18.58 uA)</p><p>-Monitor both pilot flame signals rise up about 15 minutes and start up the main burner&nbsp; &nbsp;</p><p>-Measure pilot flame monitor signal for both tubes E-4850 and E-4852.</p><p>(E-4850= 15.07 u Amp, E-4852= 18.16 u Amp)&nbsp;&nbsp;</p><p><u><b>As Left,</b></u></p><p>-GDU Train-2 is unit running and monitor by CCR.</p><p><u><b>Next Plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job Progress,</b></u></p><p>-100% completed.</p>', '<p><a href="M:\\01 E&amp;I\\Activity Photos\\2025-04-12_GDU-4800_TS GDU train-2 tripped by pilot flame off">M:\\01 E&amp;I\\Activity Photos\\2025-04-12_GDU-4800_TS GDU train-2 tripped by pilot flame off</a><br></p>', '2025-04-12 19:06:08', '2025-05-18 10:11:21', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SK-4800', 'ZTK-SK-4800', 'Glycol Regeneration Package Train 2', NULL, NULL, 'Glycol Regeneration Package Train 2', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-E-4850-ASSY', 'ZTK-E-4850-ASSY', 'Fire Tube Heater Assembly', NULL, NULL, 'Fire Tube Heater Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
