  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS both GDU are tripped during squall passing ', 'Electrical & Instrument', 'CM ', 'Completed', '2025-04-13', '<p><u><b>Activity,</b></u></p><p>-Troubleshoot both GDU Train-1 and Train-2 was tripped by pilot flame off</p><p><u><b>History,</b></u></p><p>-NA.</p><p><u><b>Equipment description and location</b>,</u></p><p>-GDU-4700 and GDU-4800 (Upper deck).<br></p><p><u><b>As found,</b></u></p><p>-GDU-4700 was tripped by pilot flame off</p><p>-GDU-4800 was tripped by pilot flame off and cannot start up the main burner</p><p><u><b>What happen,</b></u></p><p>-GDU-4700 was tripped by pilots flame off during strong weather (wind speed=30-35 knot)&nbsp;</p><p>-GDU-4800 was tripped by pilots flame off during strong weather (wind speed=30-35 knot)</p><p><u><b>Action,</b></u></p><p>-GDU-4700 (Train-1) was tripped by both pilots flame off (E-4750 &amp; E-4752)</p><p>-GDU-4800 (Train-2) was tripped by both pilots flame off (E-4850 &amp; E-4852) and </p><p>cannot start up main burner</p><p><b>GDU-4700 (Train-1)</b></p><p>-Perform jump start the both pilot monitor signals and monitor the flame condition</p><p>-Perform cleaning the air flow adjuster and monitor the flame signal.</p><p>-Monitor both pilot flame signals rise up about 15 minutes and start up the main burner&nbsp; &nbsp;</p><p>-Measure pilot flame monitor signal for both tubes E-4750 and E-4752.</p><p>(E-4750= <span style="background-color: rgb(255, 255, 0);">17.77</span> u Amp, E-4752= <span style="background-color: rgb(255, 255, 0);">18.13 </span>u Amp)&nbsp;</p><p><b>GDU-4800 (Train-2)</b></p><p>-Perform starting up the GDU Train-2 again, GDU was tripped by unstable flame signal.</p><p>-E-4850 &amp; E-4852 shows pilot flame monitor signal low and current signal unstable.</p><p>-Perform jump start the both pilot monitor signals and monitor the flame condition&nbsp;</p><p>-Perform cleaning the air flow adjuster and monitor the flame signal.</p><p>-Monitor both pilot flame signals rise up about 5 minutes and start up the main burner&nbsp; &nbsp;</p><p>-Measure pilot flame monitor signal for both tubes E-4850 and E-4852.</p><p>(E-4850= <span style="background-color: rgb(255, 255, 0);">15.46</span> u Amp, E-4852=<span style="background-color: rgb(255, 255, 0);"> 16.82</span> u Amp)&nbsp;&nbsp;</p><p><u><b>As Left,</b></u></p><p>-Both GDU train-1&amp;2 are running and monitor by CCR.</p><p><u><b>Next Plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u>Job Progress,</u></p><p>-100% completed.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-04-13_GDU-4700 &amp; GDU-4800_TS both GDU are tripped by strong weather">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-04-13_GDU-4700 &amp; GDU-4800_TS both GDU are tripped by strong weather</a><br></p>', '2025-04-13 15:59:40', '2025-04-28 18:14:19', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SK-4700', 'ZTK-SK-4700', 'Glycol Regeneration Package Train 1', NULL, NULL, 'Glycol Regeneration Package Train 1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
