-- Inserting report ID 35647
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix air leak at sump pump and verify PSV ', 'Electrical & Instrument', 'CM ', 'Completed', '2025-04-14', '<p><b><u>Activity</u></b><b>,</b></p>  <p>- Fix air leak at sump pump P-1052 and verify downstream PSV-10509.</p>  <p><b><u>History</u></b><b>,</b></p>  <p>- NA</p>  <p><b><u>Equipment description and location</u></b><b>,</b></p>  <p>- Sump pump and downstream PSV, Sump deck</p>  <p><b><u>As found</u></b><b>,</b></p>  <p>- Gas seeping at the sump pump and the pump was not running.</p>  <p><b><u>What happen</u></b><b>,</b></p>  <p>- Air drive spool was not fully tightened.</p>  <p><b><u>Action</u></b><b>,</b></p>  <p>- Removed the spool of the air drive section of the pump.</p><p>-Re-grease the o-rings and fixed the air drive section.</p><p>-Run the sump pump by adjusting the supply pressure to 1.7 bar. The pump downstream pressure becomes 23.9bar.</p><p>-Checked the PSV is passing or not by closing the upstream ball valve of PSV and found the sump pump downstream pressure was not changed.</p><p>-Confirmed the PSV passing by opening downstream vent of PSV. There is no passing from downstream of PSV and the pump pressure was not changed.</p><p>-Run the pump and checked the level drop rate of the sump tank. Found level is dropping as the pump run.&nbsp;</p><p><br></p>  <p><b><u>As left</u></b><b>,</b></p>  <p>- Pump supply pressure 1.7 bar, pump discharge pressure 23.9bar and the pump is running normal.</p>  <p><b><u>Next plan</u></b><b>,</b></p>  <p>- NA</p>  <p><b><u>Documentation</u></b><b>,</b></p>  <p>- N/A</p>  <p><b><u>Job progress</u></b><b>,</b></p>  <p>- 100% completed.</p>  <p>&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-04-14_P-1052,Performance check and fix leak from air pilot', '2025-04-14 21:11:35', '2025-04-14 21:13:26', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PSV-10509', 'ZTK-PSV-10509', 'PSV, WP10, 2"-OW-10519-F06S for V-1051', NULL, NULL, 'PSV, WP10, 2"-OW-10519-F06S for V-1051', 'WP10', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-1052', 'ZTK-P-1052', 'Sump Pump Deliver from V-1051 to ZPQ', NULL, NULL, 'Sump Pump Deliver from V-1051 to ZPQ', 'WP10', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
