DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform de-oiler liner inspection HC-6130', 'Mechanic', 'CM ', 'Completed', '2025-04-14', '<p><u><b>2025-04-14</b></u></p><p><u><b><br></b></u></p><p><b>Perform de-oiler liner inspection and cleaning.&nbsp;</b></p><p>- <b>Made new NC gasket - 2 EA</b>( OD- 530mm and ID -395mm).</p><p><b>- Remove the De-oiler upside flange - 20pieses stud bolt(50mm or 2”).</b></p><p><b>-&nbsp;</b><b>Tight the bolt for derrick nut to lift the flange of&nbsp; De-oiler (1 1/16 nut).</b></p><p><b>-&nbsp;</b><b>Remove the old 2 gasket NC.</b></p>  <p>-&nbsp;<b>Remove liner and dummy liner(block line) 16 each and clean or replace.</b></p><p><b>- Clean inside of de-oiler column.</b></p><p><b>-&nbsp;</b><b>Clean the gasket sealing surface(make sure don’t make sketch).</b></p><p>-&nbsp;<b>Install new gasket and align the liner guide line on the mark.</b></p><p>-&nbsp;<b>Install the gasket on guideline and install back the deoiler flange.</b></p>  <p>-&nbsp;<b>Make sure align with body and install the bolt and slightly loose the derrick bolt nut.</b></p>  <p>-&nbsp;<b>Install the all 20 bolts and tight in sequence with 500 Nm.</b></p>  <p><b>(1,13,5,17,9,3,15,7,19,12,2,14,6,18,10,4,16,8,20,11).&nbsp;</b><b>&nbsp;</b></p><p><b>-</b><b>Install 8 bolts(77Nm) and 3 gasket(2” 600 class) at spool flange.</b></p><p><b>- Performed service pressure test&nbsp; and no leakage.</b></p><p><b><br></b></p><p>  <b><br></b></p><p><b></b></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\61 PRODUCED WATER\\HC-6130\\2025\\2025-04-14 Inspect liner and clean column">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\61 PRODUCED WATER\\HC-6130\\2025\\2025-04-14 Inspect liner and clean column</a><br></p>', '2025-04-15 10:39:43', '2025-04-18 10:20:11', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
