-- Inserting report ID 35676
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Performed de-oiler liner inspection HC-6140', 'Mechanic', 'CM ', 'Completed', '2025-04-17', '<p><u><b>2025-04-17</b></u></p><p>Perform de-oiler liner inspection and cleaning.&nbsp;</p><p>-&nbsp;Made new NC gasket - 2 EA. ( <b>OD- 530mm and ID -395mm)</b>.</p><p>- Remove the De-oiler upside flange - 20pieses stud bolt(50mm or 2”).</p><p>-&nbsp;Tight the bolt for derrick nut to lift the flange of&nbsp; De-oiler (1 1/16 nut).</p><p>-&nbsp;Remove the old 2 gasket NC.</p><p>-&nbsp;Remove liner and dummy liner(block line) for cleaning or replacing.</p><p>- Clean inside of de-oiler column.</p><p>-&nbsp;Clean the gasket sealing surface(make sure don’t make sketch).</p><p>-&nbsp;Install new gasket and align the liner guide line on the mark.</p><p>-&nbsp;Install the gasket on guideline and install back the de-oiler flange.</p><p>-&nbsp;Make sure align with body and install the bolt and slightly loose the derrick bolt nut.</p><p>-&nbsp;Install the all 20 bolts and tight in sequence with&nbsp;<b> 500Nm.</b></p><p>(1,13,5,17,9,3,15,7,19,12,2,14,6,18,10,4,16,8,20,11).&nbsp;&nbsp;</p><p>-Install 8 bolts(77Nm) and 3 gasket(2” 600 class) at spool flange.</p><p>- Performed service pressure test&nbsp; and no leakage.</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\61 PRODUCED WATER\\HC-6140\\2025\\2025-04-17 Inspect liner and blockage">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\61 PRODUCED WATER\\HC-6140\\2025\\2025-04-17 Inspect liner and blockage</a><br></p>', '2025-04-18 10:23:04', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
