-- Inserting report ID 35689
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S ESDV close by itself', 'Electrical & Instrument', 'CM ', 'Completed', '2025-04-19', '<p><b><u>Activity</u></b><b>,</b></p>  <p>- T/S ESDV-15211 close by itself.</p>  <p><b><u>History</u></b><b>,</b></p>  <p>- NA</p>  <p><b><u>Equipment description and location</u></b><b>,</b></p>  <p>- ESDV at sump deck</p>  <p><b><u>As found</u></b><b>,</b></p>  <p>- SOV-15211 was closed and ESDV was closed.</p>  <p><b><u>What happen</u></b><b>,</b></p>  <p>- Voltage drop at power supply to SOV due to terminal loose in the SIS cabinet cause the SOV to close itself.</p>  <p><b><u>Action</u></b><b>,</b></p>  <p>- Checked the physical condition of the valve and control panel. (No abnormal)</p><p>-The supply pressure at regulator was stable. Suspected the valve close from SOV power supply.</p><p>-Checked power supply of the SOV and found only 15VDC.</p><p>-Checked the whole loop of the SOV power supply and found both positive and negative terminals in SIS cabinet(SIS/FGS-WP15-001) were loosen.</p><p>-Removed the fuse and measured the voltage. Found 25VDC.</p><p>-Tightened the loosen terminals and tightened the termination at the whole loop.</p><p>-Performed function test on the ESDV( opening time 14sec and closing time 17sec).</p><p>-Checked leak at the tubing fittings and found no leak.</p>  <p><b><u>As left</u></b><b>,</b></p>  <p>- The ESDV is working normal.</p>  <p><b><u>Next plan</u></b><b>,</b></p>  <p>- NA</p>  <p><b><u>Documentation</u></b><b>,</b></p>  <p>- N/A</p>  <p><b><u>Job progress</u></b><b>,</b></p>  <p>- 100% completed.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-04-19_ESDV-15211,TS ESDV close by itself', '2025-04-19 18:50:12', '2025-04-19 19:05:07', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-ESDV-15211', 'ZTK-ESDV-15211', 'ESDV 18"-GC-15011-F06P for ESD 1,2,2CB', NULL, NULL, 'ESDV 18"-GC-15011-F06P for ESD 1,2,2CB', 'WP15', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'James', NULL, 'EXTERNAL', '2025-04-19 18:50:12', '2025-04-19 19:05:07', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Francis', NULL, 'EXTERNAL', '2025-04-19 18:50:12', '2025-04-19 19:05:07', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
