  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S SDV not fully close', 'Electrical & Instrument', 'CM ', 'Completed', '2025-04-28', '<p><b><u>Activity,</u></b></p>  <p>-T/S SDV-50021 not fully close.</p>  <p><b><u>History,</u></b></p>  <p>-NA</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>- SDV at condensate outlet of condensate flash vessel, Main deck</p>  <p><b><u>As found,</u></b></p>  <p>-Valve was 25% opened.</p>  <p><b><u>What happen,</u></b></p>  <p>-The valve stuck on command from CCR due to spring inside not moving.</p>  <p><b><u>Action,</u></b></p>  <p>-Checked the valve control panel condition.( All are normal)</p><p>-Checked valve functioning. Found it is stuck at open position with discrepancy alarm at CCR.</p><p>-Removed the actuator from the valve body and turn the valve manually. (Valve is normal)</p><p>-Reinstalled the actuator and exercise the valve 15 times.</p><p><br></p>  <p><b><u>As left,</u></b></p>  <p>-The valve is normal in both open and close position( Supply pressure 5 bar).</p><p>-Confirmed with local operator and CCR.</p>  <p><b><u>Next Plan,</u></b></p>  <p>-NA</p>  <p><b><u>Documentation,</u></b></p>  <p>-NA.</p>  <p><b><u>Job Progress,</u></b></p>  <p>-100% completed.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-04-28_SDV-50021,TS valve fully close at local', '2025-04-28 15:51:59', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SDV-50021', 'ZTK-SDV-50021', 'SDV on V-5000 Condensate Outlet, ESD 3LE', NULL, NULL, 'SDV on V-5000 Condensate Outlet, ESD 3LE', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'James', NULL, 'EXTERNAL', '2025-04-28 15:51:59', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Francis', NULL, 'EXTERNAL', '2025-04-28 15:51:59', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL);
