  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Joseph', NULL, 'EXTERNAL', '2025-04-28 16:02:16', '2025-04-28 18:31:59', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Paing', NULL, 'EXTERNAL', '2025-04-28 16:02:16', '2025-04-28 18:31:59', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
