  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS fire hydrant valve malfunction', 'Mechanic', 'CM ', 'Completed', '2025-04-28', '<p>Problem:</p><p>Fire hydrant connection valve malfunction.</p><p><br></p><p>Action:</p><p>After checking at the worksite, the adjustor cap of the hydrant connection valve is moving freely.</p><p>After removing it, we found there is no spring, spring carrier and ball inside the adjustor cap.</p><p>The problem of the valve malfunction comes from no spring.</p><p>We used the spring from old valve, to install it back the the hydrant at the site.</p><p>Test run during the firewater pump running, connect with the hose, the valve can open and close normally and back to normal function.</p><p>With Rhino team, using the flow measure gauge and check the flow pressure is around 150 PSI and same as the another side of the hydrant during fire water pump is running.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\Fire Ring Main\\2025\\2025-04-28 fire hydrant valve">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\Fire Ring Main\\2025\\2025-04-28 fire hydrant valve</a><br></p>', '2025-04-28 17:32:18', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-9017', 'ZTK-X-9017', 'Fire Hydrant on 4"-FW-67532-A7', NULL, NULL, 'Fire Hydrant on 4"-FW-67532-A7', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kaung', NULL, 'EXTERNAL', '2025-04-28 17:32:18', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
