  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS mech seal broken and water leak', 'Mechanic', 'CM ', 'In Progress', '2025-05-05', '<p><b>5-May-2025</b></p><p>Action : Tear down the high speed shaft pump and kept as reference and evidence.</p><p><br></p><p><b>30-Apr-2025</b></p><p>Problem:</p><p>Possible Mech seal broken and water leak.</p><p><br></p><p>Action:</p><p>30/04/2025</p><p>Found water leak from the mech seal housing.</p><p>Drain the gear oil, found gear oil mix with the broken metal pieces and became black color oil.</p><p>Found the outboard bearing is already broken into pieces.</p><p>HP Pump shaft gear teeth are already badly worn out.</p><p>Found the drive gear teeth of the gearbox is also damaged and some teeth are worn out.</p><p>The HP pump shaft also damaged and mech seal, seal assembly is also damaged.</p><p>Removed the gearbox housing, gearbox oil shroud, pump casing.</p><p>Gearbox housing and gearbox oil shroud already badly cover by burnt gear oil and broken metal pieces.</p><p>Clean the gearbox housing and gearbox oil shroud.</p><p>Found the outboard bearing housing inside the gearbox housing also taken apart.</p><p><br></p><p><b style="background-color: rgb(255, 255, 0);">Need to order drive gear of the gearbox urgent to keep the pump back to service.</b></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-04-30 TS mech seal broken P6651">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-04-30 TS mech seal broken P6651</a><br></p>', '2025-04-30 18:31:55', '2025-05-05 17:05:03', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
