-- Inserting report ID 35817
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix gas seeping from grease nipple, valve passing', 'Mechanic', 'CM ', 'In Progress', '2025-05-12', '<p>Problem: </p><p>Gas seeping from grease nipple and possible valve passing.</p><p><br></p><p>Action:</p><p>12 May 2025</p><p>- Inject the valve sealant 5050 to the ball valve of export to sea line side during live line with pressure around 100 Bar</p><p>- Inject the valve sealant 5050 to 1 tube per 1 grease nipple (total 4 nipples)</p><p>- During injection the valve sealant with the pneumatic pump, the pump pressure is up to 5800 PSI due to the pressure inside the line about 100 bar</p><p>- Inject slowly and steadily monitoring the pressure gauge of pump</p><p>- Exercise the valve Close to open, open to close one round by operator.</p><p>- (Check the valve passing test)</p><p><br></p><p><br></p><p>11 May 2025&nbsp;</p><p>- Exercise the 28in ball valve from PIG launcher side by production team Open to close, close to open (2 rounds)</p><p>- Inject valve sealant 5050 to 28in ball valve from PIG launcher side</p><p>- Inject 2 tube per 1 grease nipple, total 4 grease nipple (8 tube) using pneumatic pump, Pressure is around 2000PSI during injecting valve sealant 5050</p><p>- Exercise the valve again by production team Open to Close, close to Open (1 Round)</p><p><br></p><p>- Inject valve cleaner plus to 28in ball valve at the Export line to sea line side</p><p>- Inject 1 tube per 1 grease nipple (due to low stock), total 4 grease nipple (4 tube)</p><p>- Handover to production team for exercise the valve from Close to Open, Open to close 3 Rounds after 40mins of inject the valve cleaner plus (they will continue after 40 mins)</p><p><br></p><p>10 May 2025</p><p>For 28in ball valve at the Gas export PIG Launcher side</p><p>- Plan to inject the valve cleaner plus to the valve ,exercise the valve open and close, leave for one night and apply valve sealant 5050&nbsp;</p><p>- Test and try the pneumatic valve grease pump, clean the grease tube of the pump and still working</p><p>- Apply the valve cleaner plus 2 cartridge to one grease nipple of the ball valve (total 4 grease nipples)</p><p>- After apply one side of the valve (2 grease nipples, 4 cartridge), exercise the valve from close to open, and open to close&nbsp;</p><p>- During injecting valve cleaner, the pressure is around 400 to 500 PSI</p><p>- Leave it for one night and plan to inject sealant 5050 next day</p><p><br></p><p>2 May 2025</p><p>Found grease nipple of the Gas export pig launcher side that is on the firewall side, is gas seeping after losing the nipple for grease injection.</p><p>After inject 4 to 5 stroke, the gas seeping from grease nipple is stopped.</p><p>For valve body, after inject grease for 1 grease tube, pressure cannot hold and build up to 2500 PSI.</p><p><br></p><p>For another side of the grease nipple, at the export line pig launcher side that is one the flare side, the grease nipple is no seeping.</p><p>For valve body, after inject grease more than 10 strokes, pressure cannot hold and build up to 2500 PSI.</p><p><br></p><p>For the rest grease nipples, no seeping from grease nipple.</p><p>Pressure can build up to 2500 PSI after 4 to 5 strokes of grease injection and can hold at the pressure.</p><p><br></p><p>NOTE: </p><p>To exercise after inject the grease, need to perform after pressure equalizing the both side of the valve by the operator.</p><p></p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\103 GENERAL\\2025\\2025-05-10 Fix gas seeping at 28in ball valve (valve cleaner inject)">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\103 GENERAL\\2025\\2025-05-02 Fix gas seeping from grease nipple inject grease export gas Pig launcher line</a><br></p>', '2025-05-02 18:11:36', '2025-05-12 16:58:00', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-28-VB-87N-FB-ED', 'ZTK-28-VB-87N-FB-ED', 'Valve Ball 28" 1500#RTJ,VB-87N-FB-ED', NULL, NULL, 'Valve Ball 28" 1500#RTJ,VB-87N-FB-ED', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'P'' Yai', NULL, 'EXTERNAL', '2025-05-02 18:11:36', '2025-05-12 16:58:00', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kaung', NULL, 'EXTERNAL', '2025-05-02 18:11:36', '2025-05-12 16:58:00', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Yan', NULL, 'EXTERNAL', '2025-05-02 18:11:36', '2025-05-12 16:58:00', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Eric', NULL, 'EXTERNAL', '2025-05-02 18:11:36', '2025-05-12 16:58:00', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zin Aung', NULL, 'EXTERNAL', '2025-05-02 18:11:36', '2025-05-12 16:58:00', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
