-- Inserting report ID 35829
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S UPS battery alarm at EDG', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-05-03', '<p><u><b>Activity,</b></u></p><p>-TS UPS battery alarm &amp; replaced starter battery charger at EDG-7200</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-Emergency Diesel Generator, Lower Deck.</p><p><u><b>As found,</b></u></p><p>-Battery fault alarm at EDG UPS Display.</p><p>-The manual bypass function was ON.</p><p>-Emergency Shutdown Genset &amp; Battery Charger fault alarm.</p><p><u><b>What happen,</b></u></p><p>-Battery deformed.</p><p><u><b>Action,</b></u></p><p>-Reset all emergency shutdown alarms.</p><p>-Disconnected the batteries cable from the UPS.</p><p>-Checked the batteries condition and found that&nbsp; battery No.8 is deformed<span style="background-color: rgb(255, 255, 0);">.(1.051Ohm,12.77V)</span></p><p>-Replaced the deformed battery with the battery that removed from the BDG UPS.<span style="background-color: rgb(255, 255, 0);">(0.085Ohm, 12.83V)</span></p><p><span style="background-color: rgb(255, 255, 0);">-Replaced new starter battery charger.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Set Battery charging voltage is 27.00V.</span></p><p>-Apply the manual bypass function Off.</p><p>-Reset the battery fault alarm by switching off and on the UPS as per manual.&nbsp;</p><p>-After UPS boost up, changed the UPS bypass mode to on line mode.</p><p>-Tested run the EDG by Electrical Mode about 10mins.&nbsp;</p><p><u><b>As left,</b></u></p><p>-All alarm clear and EDG is ready to start.</p><p><u><b>Next Plan</b>,</u></p><p>-Waiting new UPS batteries to replace both EDG &amp; BDG.</p><p><u><b>Documentation,</b></u></p><p>-NA.</p><p>-Link ().</p><p><u><b>Job Progress,</b></u></p><p>-100%</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-05-03_EDG-7200, TS UPS battery alarm &amp; replaced Starter battery charger">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-05-03_EDG-7200, TS UPS battery alarm &amp; replaced Starter battery charger</a><br></p>', '2025-05-03 19:45:07', '2025-05-08 08:53:42', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
