  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Valve Integrity Check for Liquid Fuel PCD Purge Li', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-05-04', '<p><u>Activity,</u></p><p>-TS Pressure drop from PCD to Liq Fuel Circuit Fwd Purge Transmitter at GTG-7210</p><p>-Valve&nbsp;vale integrity check for XV-72159-2, XV-72155-2 and XV-72153-2.</p><p><u>History,</u></p><p>-N/A</p><p><u>Equipment description and location,</u></p><p>-Gas Turbine Generator No.1, Upper Deck.</p><p><u>As found,</u></p><p>-Found that the command for XV-72159-2 (Primary Valve) is open and local fully open.</p><p>-Found that the command for XV-72155-2 (Secondary Valve) is open and local partially open.</p><p>-Found that the command for XV-72153-2 (Vent Valve) is close and local fully open.</p><p><u>What happen,</u></p><p>-N/A</p><p><u>Action,</u></p><p>-When we performed valve integrity check, found that primary and secondary valve unable to travel fully open open and fully close position.</p><p>-Also found that IA leaking at the actuator stem when valve operation.</p><p><u>As left,</u></p><p>-Unit is available.</p><p><u>Next Plan,</u></p><p>-Will check the spare actuator and if we have, will replace the actuator.</p><p><u>Documentation,</u></p><p>-NA.</p><p><u>Job Progress,</u></p><p>-50%.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-05-04_GTG-7210 TS Pressure drop from PCD to Liq Fuel Circuit Fwd Purge Transmitter', '2025-05-04 15:51:47', '2025-05-04 16:02:45', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
