-- Inserting report ID 35844
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Diesel seeping from hatch cover', 'Mechanic', 'CM ', 'Completed', '2025-05-05', '<p>Problem:</p><p>Found diesel seeping from hatch cover of Diesel filter F-7120</p><p><br></p><p>Action:</p><p>Possible diesel seeping from hatch cover because of the seal.</p><p>O-ring spare is not standby, and if damaged during troubleshooting unit will out of service and cannot run diesel consuming equipment.</p><p>Another possible diesel seeping because of hatch cover bolts are not equally tighten.</p><p>So loosen all of the 4 hatch cover bolts.</p><p>Retightened the all bolts equally.</p><p>Deisolate the diesel filter and found no seeping during low pressure.</p><p>After test run the diesel transfer pump, and build up pressure in the diesel filter, found small diesel seeping around the hatch cover.</p><p>Possible diesel leak from O-ring inside, need to wait for spare to fix the problem again.</p><p><br></p><p>Plan: Spare part order in progress.</p><p>&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\71 DIESEL SYSTEM, CRANE &amp; AVIATION\\F-7210 Diesel filter Coalescer\\2025-05-05 TS  Diesel seeping from hatch cover">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\71 DIESEL SYSTEM, CRANE &amp; AVIATION\\F-7210 Diesel filter Coalescer\\2025-05-05 TS  Diesel seeping from hatch cover</a><br></p>', '2025-05-05 14:47:52', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-F-7120-SKID', 'ZTK-F-7120-SKID', 'Treated Diesel Filter/Coalescers Skid', NULL, NULL, 'Treated Diesel Filter/Coalescers Skid', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Leo', NULL, 'EXTERNAL', '2025-05-05 14:47:52', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kaung', NULL, 'EXTERNAL', '2025-05-05 14:47:52', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
