DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Pressure drop PCD to Liq Fuel Circuit Fwd Purge', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-05-05', '<p><u><b>Activity,</b></u></p><p>-TS Pressure drop from PCD to Liq Fuel Circuit Fwd Purge Transmitter at GTG-7210</p><p><u><b>History,</b></u></p><p><u><b>04 May 2025</b></u></p><p>-Valve&nbsp;vale integrity check for XV-72159-2, XV-72155-2 and XV-72153-2.&nbsp;</p><p>-When we performed valve integrity check, found that primary and secondary valve unable to travel fully open open and fully close position.</p><p>-Also found that IA leaking at the actuator stem when valve operation.</p><p><u><b>Equipment description and location,</b></u></p><p>-Gas Turbine Generator No.1, Upper Deck.</p><p><u><b>As found,</b></u></p><p>-Found that the command for XV-72159-2 (Primary Valve) is open and local fully open.</p><p>-Found that the command for XV-72155-2 (Secondary Valve) is open and local partially open.</p><p>-Found that the command for XV-72153-2 (Vent Valve) is close and local fully open.</p><p><u><b>What happen,</b></u></p><p>-N/A</p><p><u><b>Action,</b></u></p><p>-Replaced the valve and actuator for primary and secondary valve (XV-72159-2 &amp; XV-72155-2) from liquid fuel purge circuit.</p><p>-Performed function test the valve by forcing from logic.</p><p>-Valve able to travel fully open and close position.</p><p>-Checked the leak and found no more IA from valve actuator.</p><p>-Found that accumulated water along the tubing.&nbsp;</p><p><u><b>As left,</b></u></p><p>-Unit is available.</p><p><u><b>Next Plan,</b></u></p><p>-Will perform "Manual purge sequence" by logic during unit running without load.</p><p><u><b>Documentation,</b></u></p><p>-NA.</p><p><u><b>Job Progress,</b></u></p><p>-90%.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-05-05_GTG-7210 TS Pressure drop from PCD to Liq Fuel Circuit Fwd Purge Transmitter', '2025-05-05 14:50:48', '2025-05-05 17:10:10', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
