  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS E-4750 & E-4752 during GDU Train-1 start up', 'Electrical & Instrument', 'CM ', 'Completed', '2025-05-06', '<p><u><b>Activity,</b></u></p><p>-Troubleshoot pilot tubes E-4750 and E-4752 for GDU Train-1 unit start up</p><p><u><b>History,</b></u></p><p>-Starting GDU-4700 (Train-1) after unit stopping 1 week.</p><p><u><b>Equipment description and location,</b></u></p><p>-E-4750 &amp; E-4752, GDU-4700 (Upper deck).<br></p><p><u><b>As found,</b></u></p><p>-E-4750 &amp; E-4752&nbsp; show unstable flame monitor signal during start up</p><p><u><b>What happen,</b></u></p><p>-E-4750 &amp; E-4752 air flow adjuster surface is not clean.</p><p><u><b>Action,</b></u></p><p>-E-4750 &amp; E-4752 shows pilot flame monitor signal low and current signal unstable.</p><p>-E-4750 &amp; E-4752 clean the air flow adjuster and monitor the flame signal.</p><p>-E-4750 &amp; E-4752 can build up and stable in micro Amp current signal.</p><p>-Measure pilot flame monitor signal for both tubes E-4750 and E-4752.</p><p>&nbsp;(E-4750= 20.36 u Amp DC &amp; E-4752=20.84&nbsp;u Amp DC)&nbsp;</p><p><u><b>As Left,</b></u></p><p>-GDU Train-1 is unit running and monitor by CCR.</p><p><u><b>Next Plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job Progress,</b></u></p><p>-100% completed.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-05-06_GDU-4700, TS E-4750 &amp; E-4752 during GDU Train-1 start up', '2025-05-06 20:21:47', '2025-05-18 10:13:43', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
