  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1M PM EDG Onload Test', 'Electrical & Instrument', 'PM ', 'Completed', '2025-05-09', '<p><u><b>Activity,</b></u></p><p>-Perform 1M PM_EL Onload test run EDG-7200.</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-Emergency Diesel Generator, Lower Deck<br></p><p><u><b>Findings,</b></u></p><p>-Loosen hydraulic starter solenoid pin.</p><p>-Outlet Sidewall Louver No.2 malfunction.</p><p>-Battery failure alarm at EDG UPS.</p><p><u><b>What happen,</b></u></p><p>-NA</p><p><u><b>Action,</b></u></p><p>-Performed 1M PM_EDG Onload test.</p><p>-Checked inside the generator package as per procedure with Mech Team.&nbsp;</p><p>-Record all parameter as specified in job card and procedure.</p><p>-Performed onload test with electric mode for 1 hour and engine running properly.</p><p>-During hydraulic mode test, engine failed to start by hydraulic start failed alarm.</p><p>-Observed the loosen hydraulic starter solenoid pin and secured it.</p><p>-Engine test run and found that Outlet Sidewall Louver No.2 failed to maintain a closed position.&nbsp;</p><p>-Replaced with new spare and performed test run the engine with success.&nbsp;</p><p><u><b>As left,</b></u></p><p>-Unit Back to normal and available.</p><p><u><b>Next Plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-Completed.</p><p>-Link(\\\\pttep.com\\DFSRootZPQ\\zpqshare\\Department Share\\04_MAINTENANCE\\03 E&amp;I\\08 PM&amp;CM&amp;Log Sheets Report\\01 PM Records and Test Records\\04. Emergency Diesel Generator\\2025\\May)</p><p><u><b>Job Progress,</b></u></p><p>-100% completed.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-05-09_EDG-7200, 1MPM Onload test', '2025-05-09 14:55:46', '2025-05-10 19:26:41', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EDG-7200', 'ZTK-EDG-7200', 'Emergency Diesel Generator Package', NULL, NULL, 'Emergency Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thomas', NULL, 'EXTERNAL', '2025-05-09 14:55:46', '2025-05-10 19:26:41', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
