  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To overhaul the HP2 accumulator.', 'Electrical & Instrument', 'CM ', 'Completed', '2025-05-10', '<p><u><b>Activity,</b></u></p><p>-To overhaul HP2 accumulator removed from WP06 at workshop.</p><p><b><u>History</u>,</b></p><p>-NA.</p><p><u><b>Equipment description and location,</b></u></p><p>-HP2 Accumulator from WP-06<br></p><p><u><b>As found,</b></u></p><p>-Bladder defective.</p><p><u><b>What happen,</b></u></p><p>-Aging.</p><p><u><b>Action,</b></u></p><p>-To overhaul HP2 accumulator removed from WP06 at workshop.</p><p>-Removed the damaged bladder assembly and anti-extrusion ring assembly&nbsp; from the accumulator.</p><p>-Cleaned inside the accumulator.</p><p>-Inserted the new bladder inside the accumulator with existing plug seal.</p><p>-Replaced O-ring and back-up ring, anti-extrusion ring with new ones.</p><p>-Re-installed hydraulic fluid port assembly and poppet valve.</p><p>-Perform leak test to the bladder side and hydraulic side up to 50 bar with nitrogen. &gt; No leak.</p><p>-Note:&nbsp;</p><p>&nbsp; &nbsp; -Found that the bladder side fitting (Male Connector 1/4" OD to 3/8" Male ISO Parallel Thread, Straight Shoulder) is a little bit damaged (1/4" OD side).&nbsp;</p><p>&nbsp; &nbsp; -We don''t have spare. (Special type : SS-600-1-4RS)</p><p>&nbsp; &nbsp; -We have only 3/8"OD to 3/8" Male ISO Parallel Thread type. We need 3/8" Male ISO Parallel Thread type to 1/4" OD fitting.</p><p><u><b>As Left,</b></u></p><p>-NA</p><p><u><b>Next Plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job Progress,</b></u></p><p>- 100% complete</p><p><br></p>', '<p><a href="M:\\01 E&amp;I\\Activity Photos\\2025-05-10_ZTK-WP06-X-T-2, To overhual HP2 accumulator for WP-06 at workshop">M:\\01 E&amp;I\\Activity Photos\\2025-05-10_ZTK-WP06-X-T-2, To overhual HP2 accumulator for WP-06 at workshop</a><br></p>', '2025-05-10 15:28:10', '2025-07-27 16:51:05', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
