  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS LQM HVAC AHU unit-B tripped ', 'Electrical & Instrument', 'CM ', 'Completed', '2025-05-10', '<p><b><u>Activity</u>,</b></p><p>-T/S LQM HVAC air handling unit AHU B-8640B tripped.</p><p><b><u>History</u>,</b></p><p>- MCC-8640B earth fault common alarm activate by earth fault current detection on 03 May 2025.</p><p><b><u>Equipment description and location</u>,</b></p><p>-AHU blower motor, LQM level-4, Roof Deck</p><p><b><u>As found</u>,</b></p><p>-NA.</p><p><b><u>What happen</u>,</b></p><p>-NA.</p><p><b><u>Action</u>,</b></p><p>-Unit A B-8640A is duty and unit B B-8640B is stand by.</p><p>-When unit A running, the ground current reading is around 20 mA.</p><p>-Alarm set point is (100 mA 0.2 Sec - Alarm) and ( 250mA 0.3 Sec - Trip).</p><p>-Changeover the unit from A to B.</p><p>-Monitor the ground current reading, it is around 40 mA.</p><p>-When we check with ground fault detector, the reading is around 10mA.</p><p>-Change back to unit A and checked the insulation resistance of the motor from VFD.</p><p>-Insulation resistance value are &gt;550 M-Ohm.</p><p>-Replaced ZCT and performed function test.</p><p>-Earth fault current reading is still around 40mA.&nbsp;</p><p><b><u>As left</u>,</b></p><p>-Run the unit B and keep monitor.</p><p><b><u>Next plan</u>,</b></p><p>- NA.</p><p><b><u>Documentation</u>,</b></p><p>- N/A</p><p>-Link ()</p><p><b><u>Job progress</u>,</b></p><p>- 100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-05-10_B-8640B_TS LQM HVAC AHU unit-B tripped', '2025-05-10 16:06:11', '2025-05-18 10:12:47', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-B-8640B', 'ZTK-B-8640B', 'Air Handling Stand-By Unit', NULL, NULL, 'Air Handling Stand-By Unit', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2025-05-10 16:06:11', '2025-05-18 10:12:47', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'P''Rin', NULL, 'EXTERNAL', '2025-05-10 16:06:11', '2025-05-18 10:12:47', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
