  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To overhaul the actuator, PV-50707', 'Electrical & Instrument', 'CM ', 'In Progress (Completed)', '2025-05-11', '<p><b><u>Activity</u>,</b></p><p>-To overhaul the actuator, PV-50707 (Day 2)</p><p><b><u>History</u>,</b></p><p>-Continued job from 09 May 2025.</p><p>-Found O-rings defective &amp; Valve Link arm is broken.</p><p>-Replaced with the new o-rings, diaphragm, Gaskets, hot spare valve link arm &amp; corroded bolts &amp; nuts.</p><p>-When performing the leak test, found the IA leak from the diaphragm cover bolts &amp; nuts.</p><p><b><u>Equipment description and location</u>,</b></p><p>-Pressure control valve of condensate storage vessel &amp; Lower Deck</p><p><b><u>As found</u>,</b></p><p>-(1) The actuator bonnet surface is not smooth due to painting.</p><p><u><b>What happen</b></u>,</p><p>-Paint on the bonnet surface cause improper sealing capability.</p><p><b><u>Action</u>,</b></p><p>- (1) File the actuator bonnet surface and reinstall back. No more IA leak from diaphragm cover bolts and nuts.</p><p>-Function test the PV and found valve cannot move.</p><p>-Remove the valve coupling and exercise actuator alone, actuator working properly.</p><p>-Valve was stuck and possible parking seal damaged.</p><p><b><u>As left</u>,</b></p><p>-Unit is Out of service</p><p><b><u>Next plan</u>,</b></p><p>-Need to overhaul the valve. <span style="background-color: rgb(255, 255, 0);">(WIER valve repair kits cannot order anymore due to sanction)</span></p><p><b><u>Documentation</u>,</b></p><p>-NA</p><p><b><u>Job progress</u>,</b></p><p>-90%</p>', NULL, '2025-05-11 15:36:24', '2025-05-21 13:44:16', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
