  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bo', NULL, 'EXTERNAL', '2025-05-11 15:36:24', '2025-05-21 13:44:16', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Supv');
