-- Inserting report ID 35927
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace Input Shaft Bearing', 'Mechanic', 'CM ', 'Completed', '2025-05-12', '<p>Action : (1) Remove the extended coupling.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(2) Remove input shaft hub and remove the both bearing from the shaft.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(3) Clean the shaft and perform shaft run out test. Test is in the acceptable range.</p><p><br></p><p><b>Gear Teeth Side (Dimension in MM)</b></p><table class="table table-bordered"><tbody><tr><td style="text-align: center;">0</td><td style="text-align: center;">90</td><td style="text-align: center;">180</td><td style="text-align: center;">270</td><td style="text-align: center;">360</td></tr><tr><td style="text-align: center;">0</td><td style="text-align: center;">+0.005</td><td style="text-align: center;">+0.01</td><td style="text-align: center;">+0.01</td><td style="text-align: center;">+0.01</td></tr></tbody></table><p><b>Coupling Hub Side (Dimension in MM)&nbsp;</b></p><table class="table table-bordered"><tbody><tr><td style="text-align: center;">0</td><td style="text-align: center;">90</td><td style="text-align: center;">180</td><td style="text-align: center;">270</td><td style="text-align: center;">360</td></tr><tr><td style="text-align: center;">0</td><td style="text-align: center;">-0.015</td><td style="text-align: center;">-0.03</td><td style="text-align: center;">-0.02</td><td style="text-align: center;">0</td></tr></tbody></table><p><b>Shaft run out test at inboard and out board bearing is ''0'' at all angle.</b></p><p><b><br></b></p><p><b>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</b>&nbsp;(4) Replace the new bearing at both side. <b>(NACHI 6309NSE C3).</b></p><p><b>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</b> (5) As found coupling hub depth is 1.27 mm.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (6) The bore of the extended coupling adapter is 100.05 mm.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (7) New bearing dimension (OD=100mm, ID=45mm, Thickness = 25mm)</p><p><b>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</b> (8) Preserve the extended coupling adapter, coupling hub and input shaft ready to install back.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-05-12 Take out Input Shaft and Replace Input Shaft Bearings">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-05-12 Take out Input Shaft and Replace Input Shaft Bearings</a><br></p>', '2025-05-12 17:02:24', '2025-09-09 16:49:25', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
