  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Check pump''s integrity and replace pump assembly', 'Mechanic', 'CM ', 'Completed', '2025-05-12', '<p><b><u>To check pump''s integrity and replace pump assembly&nbsp;</u></b></p><p><b><u><br></u></b></p><p><b><u>Action</u></b></p><p>-Prepare hand tools</p><p>-Remove pump casing</p><p>-Remove HSS assembly&nbsp;</p><p>-Drain all the gearbox oil</p><p>-Remove the gearbox housing&nbsp;</p><p>-Remove oil shroud and oil slinger to check the Input shaft assembly (<b><u>Found "OK"</u></b>)</p><p>-Oil shroud Gasket condition (<b><u>Found "OK"</u></b>) reuse the old one</p><p>-Check spider coupling condition (<u><b>Found "OK"</b></u>)</p><p>-Check &amp; Clean the Extended coupling&nbsp;</p><p>-Check Torque of the Motor Flange and Extended coupling Flange (<u><b>60 Ft-lbs</b></u>)</p><p>-Check condition of cooling coil inside the gear box (<b>Found "OK"</b>)</p><p>-Reinstall Gearbox housing (<u><b>change new gasket</b></u>)</p><p>-Tighten housing flange Torque (<u><b>30 ft-lbs</b></u>)</p><p>-Replace New High Speed Shaft Assembly</p><p>-Replace New gear oil (<u><b>2 liters)</b></u></p><p>-Replace new pump<b><u> inlet VICTAULIC Flexible coupling (2")</u></b></p><p>-Reinstall the pump casing </p><p>-Test run the unit&nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">**Pump is running smoothly and no abnormal found**</span></p><p>&nbsp; &nbsp;&nbsp;<br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6625\\2025\\2025-05-12 Replace pump assembly">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6625\\2025\\2025-05-12 Replace pump assembly</a><br></p>', '2025-05-12 17:48:55', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-6625', 'ZTK-X-6625', 'Fresh Water Maker 2 Skid', NULL, NULL, 'Fresh Water Maker 2 Skid', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
