-- Inserting report ID 35931
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace damaged bladder no. 1 & 5', 'Mechanic', 'CM ', 'Completed', '2025-05-19', '<p>Issue: To replace damaged bladder for accumulator no 1 &amp; 5.</p><p><u>19-May-2025</u></p><p><u><br></u></p><p>Action: Charge hydraulic pressure up to&nbsp; 200 barg.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Check for any leak. Found no leak.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Unit is back to normal condition and all accumulators are available.<br></p><p><u><br></u></p><p>Action: Reinstall accumulator no.1.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Charge nitrogen pressure up to 103 barg.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Charge nitrogen pressure for accumulator no 5 and 6 up to 103 barg.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Equalize hydraulic pressure to accumulator no 1,5 &amp; 6 and check for any leakage.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found no leak.<br></p><p><u><br></u></p><p><u>15-May-2025</u></p><p><br></p><p>Action: Set up the lifting equipment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Drain remaining HYD oil from accumulator No.1.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the pressure gauge mounting plate.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Disconnected the tubing connection.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed and moved accumulator from the skid to the workshop.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the broken bladder from the accumulator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Cleaned inside the accumulator and equipment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Reinstate new bladder to the accumulator.</p><p><u><br></u></p><p><u>14-May-2025</u></p><p><u><br></u></p><p>Action: Reinstall accumulator no.5.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Charge nitrogen pressure up to 60 barg.</p><p><br></p><p><u>13-May-2025</u></p><p><br></p><p>Action: Set up the lifting equipment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Drain remaining HYD oil from accumulator No.5.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the pressure gauge mounting plate.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Disconnected the tubing connection.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed and moved accumulator from the skid to the workshop.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the broken bladder from the accumulator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Cleaned inside the accumulator and equipment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Reinstate new bladder to the accumulator.</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\P-6700 Diesel Fire Water Pump Package No. 1\\2025\\2025-05-13 Replace bladder">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\P-6700 Diesel Fire Water Pump Package No. 1\\2025\\2025-05-13 Replace bladder</a><br></p>', '2025-05-13 17:53:09', '2025-05-19 17:55:48', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
