  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jason', NULL, 'EXTERNAL', '2025-05-15 16:07:08', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
