  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S shutdown valve malfunction', 'Electrical & Instrument', 'CM ', 'Completed', '2025-05-17', '<p><u><b>Activity,</b></u></p><p>-T/S shutdown valve SDV-50021 malfunction</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-SDV at condensate outlet of condensate flash vessel, Main deck</p><p><u><b>As found,</b></u></p><p>-Valve open when command close and valve close when command open.</p><p><u><b>What happen,</b></u></p><p>-Mismatch between the actuator and valve movement.</p><p><u><b>Action,</b></u></p><p>-Function test with CCR to verify the SDV condition and found that valve movement was reversed relative to the actuator operation.</p><p>-Set the actuator to fail close position and remove from the valve stem.</p><p>-Turn the valve manually to be fully closed.</p><p>-Verify the valve is fully close by monitoring the condensate vessel level. (Level is stable)</p><p>-Reinstall the actuator to the valve stem and perform function test with CCR. It is functioning properly.</p><p><u><b>As left,</b></u></p><p>-Now SDV-50021 is back to normal.</p><p><u><b>Next Plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job Progress,</b></u></p><p>-100% completed.</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-05-17_SDV-50021, TS shutdown valve malfunction', '2025-05-17 14:50:17', '2025-05-18 07:12:57', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
