  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S marine freezer malfunction', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-05-17', '<p><b><u>Activity</u>,</b></p><p>-TS marine freezer malfunction</p><p><b><u>History</u>,</b></p><p>-Continue from 18-Apr-2025.</p><p><b><u>Equipment description and location</u>,</b></p><p>-Marine freezer at Galley, GA-27</p><p><b><u>As found</u>,</b></p><p>-Temperature can not reduce from 27''C.</p><p><b><u>What happen</u>,</b></p><p>-Compressor running current only 2.0A.(Nameplate <a href="Current:3.51A)">Current:3.51A)</a></p><p>-Suspected the refrigerant low and temperature can not reduce.&nbsp;&nbsp;</p><p><b><u>Action</u>,</b></p><p>-Measured the running current that show 2.02A.</p><p>-Charged the refrigerant&nbsp;and measured the current that increased the running current to 2.9A and compartment temperature decreased.</p><p>-But found the refrigerant leak at inlet of the condenser tube and running current decreased to 2.0A that compartment temperature increased.</p><p>-Applied the bonding putty (Oatey) to leakage point after released the refrigerant and wait for 45mins to dry compound as per instruction.</p><p>-Charged the refrigerant during compressor running and checked the leak points.</p><p>-Found refrigerant still leak at same point.</p><p><u><b>As left,</b></u></p><p>- Plan to repair the leakage point.</p><p><b><u>Next plan</u>,</b></p><p>-Continue to repair the leakage point after refrigerant pressure empty.</p><p><b><u>Documentation</u>,</b></p><p>-N/A</p><p><b><u>Job progress</u>,</b></p>-50%.', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-05-17_GA-27, TS the Marine Refrigerator malfunction', '2025-05-17 15:49:22', '2025-05-17 20:23:10', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LQM-GALLEY', 'ZTK-LQM-GALLEY', 'Galley Room', NULL, NULL, 'Galley Room', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2025-05-17 15:49:22', '2025-05-17 20:23:10', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine');
