  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace bladder no. 1 & 5', 'Mechanic', 'CM ', 'In Progress', '2025-05-19', '<p>Issue: To replace damaged bladder for accumulator no 1 &amp; 5.</p><p><u>19-May-2025</u></p><p><br></p><p>Action:&nbsp; Removed the broken bladder from the accumulator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Cleaned inside the accumulator and equipment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Reinstate new bladder to the accumulator.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Reinstall accumulator no.1.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Charge nitrogen pressure up to 103 barg for both accumulator no. 1 &amp; 5.<br></p><p><u><br></u></p><p><u>18-May-2025</u></p><p><br></p><p>Action: Set up the lifting equipment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Drain remaining HYD oil from accumulator No.1.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the pressure gauge mounting plate.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Disconnected the tubing connection.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed and moved accumulator from the skid to the workshop.</p><p><u><br></u></p><p><u>17-May-2025</u></p><p><br></p><p>Action: Set up the lifting equipment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Drain remaining HYD oil from accumulator No.5.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the pressure gauge mounting plate.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Disconnected the tubing connection.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed and moved accumulator from the skid to the workshop.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the broken bladder from the accumulator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Cleaned inside the accumulator and equipment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Reinstate new bladder to the accumulator.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Reinstall accumulator no.5.</p><p><br></p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\P-6710 Diesel Fire Water Pump Package No. 2\\2025\\2025-05-17 Replace bladder no.5">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\67 FIRE WATER SYSTEM\\P-6710 Diesel Fire Water Pump Package No. 2\\2025\\2025-05-17 Replace bladder no.5</a><br></p>', '2025-05-17 16:30:22', '2025-05-19 17:54:03', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
