  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S GDFR shows IOP alarm', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-05-19', '<div><u><b>Activity,</b></u></div><div><p>-TS GDFR-50201 shows IOP alarm.</p><p><u><b>History,</b></u></p><p>-N/A</p><p><u><b>Equipment description and location,</b></u></p><p>-Open path gas detector, Fire and Gas System, Lower Deck.</p><p><u><b>As found,</b></u></p><p>-GDFR-50201 shows IOP alarm.</p><p><u><b>What happen,</b></u></p><p>-Fuse has blown.</p><p><u><b>Action,</b></u></p><p>-Checked at MSH-CPP-271 (TB12, terminal 12), found fuse has blown.</p><p>-Replaced with the same rating fuse (0.5A, 250V).</p><p>-Checked the heater settings and found that receiver heater control was set at 100% and transmitter side was 30%.</p><p>-Set the heater control to 30% on both transmitter and receiver. (Load current = 0.32 A)</p><p>-Performed function test with CCR and confirmed that GDFR is working properly.</p><p><u><b>As left,</b></u></p><p>-GDFR-50201 is back to normal.</p><p><u><b>Next Plan,</b></u></p><p>-To monitor GDFR-50201.</p><p><u><b>Documentation,</b></u></p><p>-NA.</p><p><u><b>Job Progress,</b></u></p><p>-Completed.</p></div>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-05-19_GDFR-50201, TS GDFR shows IOP alarm', '2025-05-19 14:34:50', '2025-05-19 19:11:07', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
