  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS AGDs show fault alarm', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-05-20', '<p><u><b>&nbsp;Activity,</b></u></p><p>- AGD-05001/05002, T/S detector shows fault low low alarm time to time.</p><p><u><b>History,</b></u></p><p>- NA.</p><p><u><b>Equipment description and location,</b></u></p><p>- Acoustic Gas Detector, Mezzanine Deck.</p><p><u><b>As found,</b></u></p><p>- AGD-05001 shows ERAC that show self test failure alarm.</p><p>-AGD-05002 shows 4.0mA.</p><p><u><b>What happen,</b></u></p><p>- AGD-05001 was internal detector failure.&nbsp;</p><p><u><b>Action,</b></u></p><p>- Visual inspected and tightened the cable terminal of the AGDs.</p><p>- Hard rested&nbsp; the AGD-05001 due to ERAC alarm.</p><p>- Function tested the AGDs with CCR that are normal.</p><p>- Measured the mA during function testing that show High alarm:16mA&nbsp;&amp; High High Alarm:20mA.</p><p>- After about one Hr,AGD-05001 came the ERAC alarm.</p><p><u><b>As left,</b></u></p><p>- AGD-05001 still have ERAC alarm and need to replace with new one.</p><p>-AGD-05002 back to normal condition</p><p><u><b>Next Plan,</b></u></p><p>- AGD-05001,Plan to replace with new one. (Need Scaffold)</p><p>-AGD-05002,Plan to replace with GM Observer I. (Need Scaffold)</p><p><u><b>Documentation,</b></u></p><p>- NA.</p><p>- Link ()</p><p><u><b>Job Progress,</b></u></p><p>- 80%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-05-20_AGD-05001&amp;AGD-05002, TS AGDs show fault alarm', '2025-05-20 23:07:03', '2025-05-21 06:15:06', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
