-- Inserting report ID 36003
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS diesel drop for X-7115B', 'Mechanic', 'CM ', 'Under Monitoring', '2025-05-23', '<p><u>2025-05-23</u></p><p>Problem - Diesel seeping from bottom of the bowl at Unit B.</p><p>Action:</p><p>&nbsp; - Running test about 15 minutes for Unit B found diesel seeping rate @ 2 drops/sec.</p><p>&nbsp; - Then ad<span style="font-size: 15px;">just operating flow rate as per P&amp;ID (3.5 m3/hr.) then running test about 15 minutes found no leakage.</span></p><p><span style="font-size: 15px;">&nbsp; - Keep monitoring due to Diesel tank level is closely full.</span></p><p><br></p><p><u>&nbsp;Test run about 15 minutes for Unit B</u>&nbsp;-&nbsp;</p><p><br></p><table class="table table-bordered"><tbody><tr><td><table class="table table-bordered"><tbody><tr><td>Feed pump suction&nbsp;</td><td>0.6 bar</td></tr><tr><td>Fresh water inlet</td><td>4.7 bar</td></tr><tr><td>Untreated diesel inlet&nbsp;</td><td>3.&nbsp; bar</td></tr><tr><td>Clean oil outlet&nbsp;</td><td>3 bar&nbsp;</td></tr><tr><td>Flow rate</td><td>3.5 m3/hr</td></tr></tbody></table><p></p></td><td><p>&nbsp;<br></p></td></tr></tbody></table><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p><b><u>2025-05-22</u></b></p><p><br></p><p>Problem - Diesel seeping from bottom of the bowl.</p><p>Action - </p><p>We swapped the solenoid unit for fresh water inlet ( top side) from Unit A to Unit B, Unit B to Unit A..</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<b>Test run about 20 minutes for Unit A .</b> ( No leakage)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><table class="table table-bordered"><tbody><tr><td>Feed pump suction&nbsp;</td><td>0.6 bar</td></tr><tr><td>Fresh water inlet</td><td>4 bar</td></tr><tr><td>Untreated diesel inlet&nbsp;</td><td>3.3 bar</td></tr><tr><td>Clean oil outlet&nbsp;</td><td>3.1 bar&nbsp;</td></tr><tr><td>Flow rate</td><td>4 m3/hr</td></tr></tbody></table><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <b><u>&nbsp;Test run about 15 minutes for Unit B</u></b> - found diesel seeping rate - 2 drops/sec.</p><p><br></p><table class="table table-bordered"><tbody><tr><td><table class="table table-bordered"><tbody><tr><td>Feed pump suction&nbsp;</td><td>0.6 bar</td></tr><tr><td>Fresh water inlet</td><td>4.7 bar</td></tr><tr><td>Untreated diesel inlet&nbsp;</td><td>2.5 bar</td></tr><tr><td>Clean oil outlet&nbsp;</td><td>3 bar&nbsp;</td></tr><tr><td>Flow rate</td><td>4 m3/hr</td></tr></tbody></table><p></p></td><td><p>&nbsp;Remark : </p><p>Adjusted untreated diesel pressure from 2.5 bar to 3.0 bar.</p><p>Then, Clean oil outlet - 3.3 bar.&nbsp;</p></td></tr></tbody></table><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; Tomorrow, we''ll optimize and fine tune controller set point.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\71 DIESEL SYSTEM, CRANE &amp; AVIATION\\X-7115B\\2025\\2025-05-22 TS diesel overflow under bowl">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\71 DIESEL SYSTEM, CRANE &amp; AVIATION\\X-7115B\\2025\\2025-05-22 TS diesel overflow under bowl</a><br></p>', '2025-05-22 18:06:16', '2025-05-25 17:28:14', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-TeamL', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-7115A-SKID', 'ZTK-X-7115A-SKID', 'Centrifuge A Skid', NULL, NULL, 'Centrifuge A Skid', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-7115B-SKID', 'ZTK-X-7115B-SKID', 'Centrifuge B Skid', NULL, NULL, 'Centrifuge B Skid', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'John', NULL, 'EXTERNAL', '2025-05-22 18:06:16', '2025-05-25 17:28:14', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-TeamL');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2025-05-22 18:06:16', '2025-05-25 17:28:14', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-TeamL');
