-- Inserting report ID 36004
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist mechanic team to swap solenoids', 'Electrical & Instrument', 'CM ', 'Completed', '2025-05-22', '<p><u><b>Activity,</b></u></p><p>-Assist mechanic team to swap shut off valve solenoids.</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-Diesel centrifuge package, Lower Deck</p><p><u><b>As found,</b></u></p><p>-Diesel seeping from the bottom of the bowl at diesel centrifuge unit B (X-7115B)</p><p><u><b>What happen,</b></u></p><p>-Mechanic team still finding the root cause</p><p><u><b>Action,</b></u></p><p>-Performed isolation and swapped the shutoff valve solenoids between Unit A and Unit B (XSV-71122A and XSV-71122B).</p><p>-Checked both solenoids and XSV-71122B has signs of physical wear at terminal cover but remains operational (No spare on hand)&nbsp;</p><p>-For XSV-71122A was found in good physical and functional condition.</p><p>-Normalized the system and test run the unit. No leakage found at unit A and diesel seeping at unit B approximately 2 drops/sec.</p><p><b>Note : XSV-71122B (Burkert, Type 5282, G3/4, PN: 00328283)</b></p><p><b>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;XSV-71122A (Burkert, Type 5282, Ac3/4, PN: 00628631)</b></p><p><u><b>As left,</b></u></p><p>-Solenoids functioning properly.</p><p><u><b>Next Plan,</b></u></p><p>-Mechanic team will continue to troubleshoot for diesel seeping issue.</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job Progress,</b></u></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-05-22_XSV-71122A&amp;B, Assist mechanic team to swap solenoids', '2025-05-22 19:38:11', '2025-05-23 07:38:47', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-7110', 'ZTK-A-7110', 'Diesel Centrifuge Package', NULL, NULL, 'Diesel Centrifuge Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-XSV-71122A', 'ZTK-XSV-71122A', 'Shutoff Valve,Water Displace to X-7115A', NULL, NULL, 'Shutoff Valve,Water Displace to X-7115A', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
