-- Inserting report ID 36023
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace cooler fan bearings', 'Mechanic', 'CM ', 'Completed', '2025-05-25', '<p>Problem : Found cooler fan shaft is loosen from bearings during seaowl team PM.</p><p><u>24-05-2025</u></p><p>Action&nbsp; &nbsp; &nbsp;: Prepare spare parts and tapping holes for correct greasing and vibration probe.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Remove fan belt, fan blade, fan pulley, motor and defective bearings LDK, shaft.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Clean fan pulley sprocket, mounting bolts&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;Install new bearings NFK(upper, lower), new shaft and new motor pulley.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Check shaft alignment during installation.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Apply torque mounting bolts 450Nm.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Will be continue tomorrow due to heavy rain.&nbsp;</p><p><u>25-05-2025</u></p><p>Action&nbsp; &nbsp; &nbsp; : Install fan pulley, fan blades and applied torque.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Install new belt GT4 and tension by seaowl team with correct mass, span value. (31Hz)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Test run with satisfied.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Housekeeping the area and cooler fan toolbox.&nbsp;</p><p><br></p><p>Remark</p><p>-Fan pulley sprocket teeth gap is worn out, need to be replace. (waiting spare)</p><p>&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p><br></p>', NULL, '2025-05-24 18:07:43', '2025-05-25 17:56:54', 'PTTEP\\ZPQ.Mechanical-Turbi', 'PTTEP\\ZPQ.Mechanical-Turbi', false, 'ZTK') RETURNING id INTO new_report_id;
