-- Inserting report ID 36036
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify HS01908 and HS01909 function under MOS.', 'Automation', 'CM ', 'In Progress', '2025-05-27', '<p><b><u>Activity</u>,</b></p><p>-Verified HS01908 and HS01909 function under MOS.</p><p><b><u>History</u>,</b></p><p>- While HS01908 (soft switch from HMI) is initiated under MOS, ESD1 activated (without de-activating “MOS”).</p>  <div>- While HS01909 (soft switch from HMI) is initiated under MOS, ESD2 activated (without de-activating “MOS”).</div><p><b><u>Equipment description and location</u>,</b></p><p>- Softswitches at WP1 HMI in E&amp;I Room</p><p><b><u>As found</u>,</b></p><p>- HS01908 (Without MOS function) is used for input signal in ESD1 function block.</p><p>- HS01908 (With MOS function) is used for input signal in ESD1 function block.</p><p>- So there have two input signals (HS01908) in ESD1 function block.</p><p>- When applied MOS for HS01908, it can only MOS for HS01908 (With MOS function).</p><p>- When SoftSwitch is initiated under MOS, HS01908(With MOS function) is not activated ESD1.</p><p>- But HS01908(Without MOS function) is activated ESD1.</p><p>- HS01909 (Without MOS function) is used for input signal in ESD2 function block.</p><p>- HS01909 (With MOS function) is used for input signal in ESD2 function block.</p><p>- So there have two input signals (HS01909) in ESD2 function block.</p><p>- When applied MOS for HS01909, it can only MOS for HS01909 (With MOS function).</p><p>- When SoftSwitch is initiated under MOS, HS01909(With MOS function) is not activated ESD2.</p><p>- But HS01909(Without MOS function) is activated ESD2.</p><p><b><u>What happen</u>,</b></p><p>-N/A</p><p><b><u>Action</u>,</b></p><p>- Prepared the presentation and proposed the solution.</p><p>1.Align HS01908 and HS01909 function with other remote platform (No MOS function)</p><div>2.Implement MOS function for HS01908 and HS01909. (Delete HS01908 and HS01909 direct signal inputs to ESD function block.)&nbsp;</div><p><b><u>As left</u>,</b></p><p>-N/A</p><p><b><u>Next plan</u>,</b></p><p>- Waiting the final decision from site management team.</p><p><b><u>Documentation</u>,</b></p><p>- N/A</p><p>-Link (\\\\pttep.com\\dfsrootzpq\\zpqshare\\Department Share\\04_MAINTENANCE\\03 E&amp;I\\01 Automation\\WP1 Softswitches for ESD1 and ESD2)</p><p><b><u>Job progress</u>,</b></p><p>- Inprogress</p>', NULL, '2025-05-27 13:57:05', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ever Kyaw', NULL, 'EXTERNAL', '2025-05-27 13:57:05', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Brown', NULL, 'EXTERNAL', '2025-05-27 13:57:05', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL);
