  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replaced Emergency Battery on Life Boat No.4', 'Electrical & Instrument', 'CM ', 'Completed', '2025-06-07', '<p><b><u>Activity,</u></b></p>  <p>- To replace the emergency battery on life boat no.4.(SC-7740)</p>  <p><b><u>History,</u></b></p>  <p>- Finding from life boat PM on 05-Jun-2025.</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>- Life Boat No.4,Mazzine Deck</p>  <p><b><u>As found,</u></b></p>  <p>- Life Boat No.4(SC-7740) can''t start the engine with emergency battery.</p>  <p><b><u>What happen,</u></b></p>  <p>- Emergency battery low performance.</p>  <p><b><u>Action,</u></b></p>  <p>- Measured the existing emergency battery that show 13.06VDc,428CCA and 5.94mOhm which is bad in Solar battery tester.</p>  <p>- Replaced the main battery with new one that was 11.97VDc, 609CCA and 3.98mOhm.</p><p>- After that replaced the emergency battery with old main battery as life boat battery replacement philosophy.</p><p>- Charged the replaced new main battery about 15 min and measured the charging volt and current that is&nbsp; 12.57VDc and 1.57A&nbsp;</p><p>- Tested the engine with main and emergency battery that are in normal operating.(Both Load Current about 9.57A)</p><p><br></p>  <p><b><u>As left,</u></b></p>  <p>- Lifeboat no.4 can start with both main and emergency batteries.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>- Low Performance emergency battery was kept on batter room.&nbsp;</p>  <p><b><u>Next plan,</u></b></p>  <p>- NA</p>  <p><b><u>Documentation,</u></b></p>  <p>- NA</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>- 100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\202-06-07_X-7740, Replaced emergency battery on life boat no.4', '2025-06-07 18:53:29', '2025-06-07 19:05:01', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SC-7740', 'ZTK-SC-7740', 'Free Fall Life Boat No.4 Main Deck', NULL, NULL, 'Free Fall Life Boat No.4 Main Deck', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
