  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S VESDA Air Flow Alarm at MSWGR, Main Deck', 'Electrical & Instrument', 'CM ', 'Completed', '2025-06-08', '<p><b><u>Activity,</u></b></p>  <p>-T/S VESDA HSSD-79004B,Air Flow Alarm at MSWGR, Main Deck.</p>  <p><b><u>History,</u></b></p>  <p>-VESDA (HSSD-79004B),Air Flow Alarm during 1Y PM Top side on 06-06-25.</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-VESDA (HSSD-79004B),at MSWGR, Main Deck.</p>  <p><b><u>As found,</u></b></p>  <p>-Found airflow alarm and zone alarm at (HSSD-79004B).</p>  <p><b><u>What happen,</u></b></p>  <p>-Found pipe No.3 connection for mono rail ACDB-CPP-221 was misaligned.</p>  <p><b><u>Action,</u></b></p>  <p>-Connect with hand held to VESDA panel.</p>  <p>-Checked alarm and found pipe No.3 high airflow alarm(122%).</p><p>-Disconnect the pipe No.3 and reinstall with correct alignment.</p><p>-Check the status on hand held and found airflow reduced to 109%.</p><p>-Note:High Airflow alarm is 120% and Urgent Airflow alarm is 150%.</p>  <p><b><u>As left,</u></b></p>  <p>-No alarm at HSSD 79004B panel and PCS.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-NA.</p>  <p><b><u>Next plan,</u></b></p>  <p>-N/A</p>  <p><b><u>Documentation,</u></b></p>  <p>-NA.</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-08_HSSD-79004B, TS VESDA air flow alarm', '2025-06-08 11:23:26', '2025-06-12 07:21:32', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HSSD-79004B', 'ZTK-HSSD-79004B', 'Hssd (Vesda) Smoke Det,Main SWGR', NULL, NULL, 'Hssd (Vesda) Smoke Det,Main SWGR', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Barry', NULL, 'EXTERNAL', '2025-06-08 11:23:26', '2025-06-12 07:21:32', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
