  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S the abnormal noise Electrolux refrigerator', 'Electrical & Instrument', 'CM ', 'Completed', '2025-06-08', '<p><u><b>Activity,</b></u></p><p>-T/S the abnormal noise from Electrolux refrigerator (LQM level-4)</p><p><u><b>History,</b></u></p><p>-N/A&nbsp;</p><p><u><b>Equipment description and location,</b></u></p><p>-Electrolux Refrigerator (LQM level-4)</p><p><u><b>As found,</b></u></p><p>-Found abnormal noise from condensing coil motor fan</p><p><u><b>What happen,</b></u></p><p>-Aging, Dust, Misalignment</p><p><u><b>Action,</b></u></p><p>-Performed running test for checking the refrigerator condition.</p><p>-Found abnormal noise coming from condensing cooler motor fan.</p><p>-Isolated the power and removed the motor fan.</p><p>-Checked and measure the resistance of the motor.</p><p>-Checked the physical condition of the fan blade.</p><p>-Cleared the dust and impurity of the fan blade cover .</p><p>-Applied the grease at the motor fan blade shaft.</p><p>-Performed function test and checked the abnormal noise again.&nbsp;</p><p>-There is no any abnormal noise after running.</p><p><u><b>As left,</b></u></p><p>-Unit is running back to normal (No abnormal noise)</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><u><b>Next plan,</b></u></p><p>-N/A</p><p><u><b>Documentation,</b></u></p><p>-N/A</p><p><u><b>Job progress,</b></u></p><p>-100% completed</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-08_Electrolux_TS abnormal noise from Electrolux refrigerator at LQM Level 4">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-08_Electrolux_TS abnormal noise from Electrolux refrigerator at LQM Level 4</a><br></p>', '2025-06-08 16:07:12', '2025-06-09 14:15:18', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
