  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix marine freezer refrigerant leak point', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-06-11', '<p><u><b>Activity,</b></u></p><p>-Fixed marine freezer refrigerant leak, GA-27</p><p><u><b>History,</b></u></p><p>-Continues job from 08 June 2025&nbsp;</p><p><u><b>Equipment description and location,</b></u></p><p>-Marine freezer GA-27 (Galley Room)</p><p><u><b>As found,</b></u></p><p>-Found leak at the points that applied Belzona.</p><p><u><b>What happen,</b></u></p><p>-NA</p><p><u><b>Action,</b></u></p><p>-Checked the leak point with snoop during running compressor.</p><p>-Found still small bubbles at the point.</p><p>-Cut out the leaking parts and used Swagelok fittings 1/4" Union to connect the two ends.</p><p>-Checked leak again and found no more leak.</p><p>-Performed vacuum of the compressor with (-30 InHg) for 30mins.</p><p>-Topped up refrigerant R-404A and monitoring the current. (as left 2.92A) _Rated ampere = 3.5A</p><p><br></p><p><u><b>As left,</b></u></p><p>-Unit under monitoring.&nbsp;</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-Kept Vacuum pump back to Switchgear HVAC cabinet.</p><p><u><b>Next plan,</b></u></p><p>-N/A</p><p><u><b>Documentation,</b></u></p><p>-In progress.</p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-100%</p>', NULL, '2025-06-11 15:36:01', '2025-06-11 17:07:55', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LQM-GALLEY', 'ZTK-LQM-GALLEY', 'Galley Room', NULL, NULL, 'Galley Room', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2025-06-11 15:36:01', '2025-06-11 17:07:55', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Francis', NULL, 'EXTERNAL', '2025-06-11 15:36:01', '2025-06-11 17:07:55', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation');
