  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S AFDS loop 1 fault alarm', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-06-13', '<p><b><u>Activity,</u></b></p>  <p>-T/S AFDS loop 1 fault alarm.</p>  <p><b><u>History,</u></b></p>  <p>-The loop 1 fault alarm was not cleared and comes all the time.</p>  <p>-</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-AFDS panel at LQM Level 4 and detector loop 01 LQM Level 1</p>  <p><b><u>As found,</u></b></p>  <p>-Loop1 is open on minus wire between SD-79203E and BSD 310 loop 01.</p>  <p><b><u>What happen,</u></b></p>  <p>-N/A</p>  <p><b><u>Action,</u></b></p>  <p>-Checked loop 1 by disabling the loop.&nbsp;</p><p>-The fault was between SD-79203E and loop 1 return at the panel. But the SD was too high and cannot access with ladder. So, checked the cable before that Smoke detector.&nbsp;</p>  <p>-Checked SD-87114C (the smoke detector before the SD-79203E) cable tightness and condition check. All are normal.</p><p>-Checked MAC-87109 and MAC-87111 at air lock. Performed cable tightening and function check. All are normal.</p><p>-Checked HDR-87114B condition and found the detector is dirty. Replaced with the hot spare.&nbsp;</p><p>-Performed the individual check as per point fault status as below.</p><p>-Checked the condition of the GDF-87223 at level 2 and GDFR-87506 at roof deck. All are normal.</p><p>-Checked the condition of SD-87110A in dry store. Found it was normal.&nbsp;</p><p><br></p>  <p><b><u>As left,</u></b></p>  <p>-No alarm at AFDS panel and repeater panels.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-N/A</p>  <p><b><u>Next plan,</u></b></p>  <p>-Continued to check the fault and clear one by one.</p>  <p><b><u>Documentation,</u></b></p>  <p>-N/A</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-50%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-13_AFDS_TS loop 1 fault alarm', '2025-06-13 15:36:54', '2025-06-13 17:16:32', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SFGS-AFDS', 'ZTK-SFGS-AFDS', 'Addressable Fire & Gas Detection System', NULL, NULL, 'Addressable Fire & Gas Detection System', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-AFDS-GAS-LOOP01', 'ZTK-AFDS-GAS-LOOP01', 'Gas Detection Loop 01 LQM Level 1', NULL, NULL, 'Gas Detection Loop 01 LQM Level 1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
