DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S marine range 4 hot plates malfunction', 'Electrical & Instrument', 'CM ', 'Completed', '2025-06-15', '<p><b><u>Activity,</u></b></p>  <p>-T/S marine range 4 hot plates GA-02A malfunction.</p>  <p><b><u>History,</u></b></p>  <p>-N/A</p>  <p>-</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Marine range 4 hot plates and oven, LQM level 1</p>  <p><b><u>As found,</u></b></p>  <p>-Found 2 hot plates at the range was malfunction.</p>  <p><b><u>What happen,</u></b></p><p>-1)Hot plate no.3 was not in full functioning state.</p><p>-2)Hot plate no.4 has selector switch misaligned.</p>  <p><b><u>Action,</u></b></p>  <p>-1)For hot plate no.3(the back plate at the left side of the hot plates),</p><p>Removed the hot plate and checked the condition. Found the wire was installed in wrong position. </p><p>The wire for terminal 2 and 3 are swapped. Rearranged the wire and installed back.&nbsp;</p><p>Measured the resistance of the coils from the terminal and found both are around 242 ohm.&nbsp;</p>  <p>-2)For hot plate no.4(the front plate at the left side of the hot plates),</p><p>Found the position selector switch was misaligned. Checked the selector switch condition and the resistance of the coils. Found both the coils are around 236 ohm.</p><p>-Performed function test for both the plates and found both are working normal.</p>  <p><b><u>As left,</u></b></p>  <p>-All of 4 hot plates are working normal now.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-N/A</p>  <p><b><u>Next plan,</u></b></p>  <p>-N/A</p>  <p><b><u>Documentation,</u></b></p>  <p>-N/A</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-15_GA-02A TS marine heater malfunction', '2025-06-15 16:00:48', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-TeamLead', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-ACDB-LQM-325', 'ZTK-ACDB-LQM-325', '400V AC Galley Dist Board', NULL, NULL, '400V AC Galley Dist Board', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
