  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S cold store ACCU2 controller alarm', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-06-16', '<p><b><u>Activity</u>,</b></p><p>-T/S cold store ACCU2 controller alarm</p><p><b><u>History</u>,</b></p><p>-N/A</p><p><b><u>Equipment description and location</u>,</b></p><p>-ACCU2 Cold Store Unit B, Cold Store Room (LQM Level-1)</p><p><b><u>As found</u>,</b></p><p>-ACCU2 freezer controller shows E2 alarm</p><p><b><u>What happen</u>,</b></p><p>-FCU-2 defrost sensor wire connection loosen (Terminal=55/56)</p><p><b><u>Action</u>,</b> <br class="Apple-interchange-newline"></p><p>-Check the freezer temperature (-23.4 Deg C)</p><p>-Change the freezer &amp; chiller duty from ACCU2 to ACCU-1&nbsp;</p><p>-Check &amp; measure the defrost heater sensor = 721 Ohm (sensor is good)&nbsp;</p><p>-Check &amp; measure the resistance of the freezer defrost heater.(U5=102.4/ V5=78.1/ W5=75.9) Ohm</p><p>-Found that FU2 defrost sensor wire is removed, E2 alarm shows at the UCP (55/56)</p><p>-Found that FU2 cooling sensor wire is removed, E1 alarm shows at the UCP (57/58)</p><p>-Check and tighten for both defrost and cooling sensor wires&nbsp;</p><p>-Visual check the freezer condition inside the freezer room (No ice block)</p><p>-Perform running the defrost for FCU-2 about 15 min and keep monitor the temperature</p><p>-No E-2 alarms show still 32.9 Deg C and ACCU2 freezer is in good condition&nbsp; &nbsp; &nbsp;</p><p>-Perform function test and running for the duty of ACCU 2 and freezer FCU-2 (No alarm)&nbsp;</p><p><b><u>As left</u>,</b></p><p>-Unit is running normal</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><b><u>Next plan</u>,</b></p><p>-NA</p><p><b><u>Documentation</u>,</b></p><p>-N/A</p><p><b><u>Job progress</u>,</b></p><p>-100% completed. (Under monitoring)</p><br>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-16_ACCU-02_TS cold store ACCU2 controller alarm">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-16_ACCU-02_TS cold store ACCU2 controller alarm</a><br></p>', '2025-06-16 15:10:12', '2025-06-16 18:12:43', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
