-- Inserting report ID 36232
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS both GDUs were tripped by pilot flame off', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-06-16', '<p><u><b>Activity,</b></u></p><p>-Troubleshoot both GDUs were tripped by pilot flame off during squall passing</p><p><u><b>History,</b></u></p><p>-NA.</p><p><u><b>Equipment description and location,</b></u></p><p>-E-4750 &amp; E-4752, GDU-4700 (Upper deck)</p><p>-E-4850 &amp; E-4852, GDU-4800 (Upper deck).<br></p><p><u><b>As found,</b></u></p><p>-GDU-4700 was tripped by E-4752</p><p>-GDU-4800 was tripped by E-4850 (two times)</p><p><u><b>What happen,</b></u></p><p>-GDU-4700 and GDU-4800 were tripped by pilots flame off during strong weather&nbsp;</p><p><u><b>Action,</b></u></p><p><b style="background-color: rgb(255, 255, 0);">GDU-4700</b></p><p>-GDU-4700 (Train-1) was tripped by pilot flame off (E-4752)</p><p>-Perform starting up the GDU-4700 again, it can start up normal running steps.&nbsp;</p><p>-E-4750 shows good in pilot flame signal.(13.66 uA)</p><p>-E-4752 shows good in pilot flame signal.(16.10 uA)</p><p>-Monitor both pilot flame signals rise up about 5 minutes and start up the main burner&nbsp; &nbsp;</p><p>-Measure pilot flame monitor signal for both tubes E-4750 and E-4752.</p><p>(E-4750= 17.20 u Amp, E-4752= 19.60 u Amp)</p><p><b style="background-color: rgb(255, 255, 0);">GDU-4800</b></p><p>-GDU-4800 (Train-2) was tripped by pilot flame off (E-4850)</p><p>-Perform starting up the GDU-4800 again, it can start the main burner about 10 min.&nbsp;</p><p>-After running the main burner, GDU-4800 was tripped by pilot flame signal (E-4850) again</p><p>-E-4850 shows transient pilot flame monitor signal.(11.34 uA)</p><p>-E-4850 do cleaning the air flow adjuster and monitor the flame signal.</p><p>-E-4852 shows good in pilot flame signal.(13.58 uA)</p><p>-Monitor both pilot flame signals rise up about 15 minutes and start up the main burner&nbsp; &nbsp;</p><p>-Measure pilot flame monitor signal for both tubes E-4850 and E-4852.</p><p>(E-4850= 17.10 u Amp, E-4852= 16.30 u Amp)</p><p><u><b>As Left,</b></u></p><p>-Both GDU units are running normal and monitor by CCR.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><u><b>Next Plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job Progress,</b></u></p><p>-100% completed.(Under Monitoring)</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-16_GDU-4700 &amp; 4800_ TS both GDUs were tripped by pilot flame off during strong weather">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-16_GDU-4700 &amp; 4800_ TS both GDUs were tripped by pilot flame off during strong weather</a><br></p>', '2025-06-16 17:30:08', '2025-06-16 17:36:46', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
