-- Inserting report ID 36235
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS common alarm at flare ignition panel', 'Electrical & Instrument', 'CM ', 'Completed', '2025-06-17', '<p><b><u>Activity,</u></b></p>  <p>-TS common alarm at flare ignition panel and verify TE-63253B.</p>  <p><b><u>History,</u></b></p>  <p>-Common alarm comes time to time from flare ignition panel.</p>  <p>-</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Flare ignition panel, Main Deck</p>  <p><b><u>As found,</u></b></p>  <p>-The common alarm was cleared. The wire for thermocouple TE-63253A was loosen.</p>  <p><b><u>What happen,</u></b></p>  <p>-Terminal was not tightened properly.</p>  <p><b><u>Action,</u></b></p>  <p>-Removed the wire for thermocouple TE-63253B to verify the condition and found the value was 0.711Mohm( open circuit).</p>  <p>-The wires for the thermocouple TE-63253A was loosen. Found the alarm comes to CCR and local panel has pilot 6 failure alarm.</p><p>-Removed and measured the resistance value(160ohm). Retightened the wires and checked the alarm. No more alarm.</p>  <p><b><u>As left,</u></b></p>  <p>-No alarm at panel and CCR.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-N/A</p>  <p><b><u>Next plan,</u></b></p>  <p>-Will monitor the common alarm at CCR.</p>  <p><b><u>Documentation,</u></b></p>  <p>-N/A</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-17_LCP-6330, TS flare panel common alarm and verify TC', '2025-06-17 13:32:17', '2025-06-18 10:57:01', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-6330', 'ZTK-X-6330', 'Flare Ignition and Flare Pilot Assembly', NULL, NULL, 'Flare Ignition and Flare Pilot Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'James', NULL, 'EXTERNAL', '2025-06-17 13:32:17', '2025-06-18 10:57:01', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Joseph', NULL, 'EXTERNAL', '2025-06-17 13:32:17', '2025-06-18 10:57:01', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

-- Inserting report ID 36236
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS turbine air inlet filter DP abnormal reading', 'Electrical & Instrument', 'CM ', 'Completed', '2025-06-17', '<p><u><b>Activity,</b></u></p><p>-TS&nbsp;turbine air inlet filter DP PDT-72220-1 is not detected.</p><p><u><b>History</b>,</u></p><p>-NA.</p><p><u><b>Equipment description and location,</b></u></p><p>-Gas Turbine Generator, Upper Deck</p><p>-Pressure Differential Transmitter for turbine air inlet filter</p><p><u><b>As found,</b></u></p><p>-Low side sensing tubing of PDT is out from the fitting.</p><p><u><b>What happen,</b></u></p><p>-Transmitter sensing point become same and it detected no difference.</p><p><u><b>Action,</b></u></p><p>-Removed and check the Swagelok OD from the fitting.</p><p>-Found that the front ferrule of Swagelok OD is missing.&nbsp;</p><p>-Installed new Swagelok OD at the tubing.</p><p>-Performed function test with success and normalized the transmitter.</p><p><u><b>As left,</b></u></p><p>-Transmitter is back to normal.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-NA</p><p><u><b>Next plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p>-G:\\Department Share\\04_MAINTENANCE\\03 E&amp;I\\08 PM&amp;CM&amp;Log Sheets Report\\02 CM Calibration Sheets\\GTG CM records\\GTG-7220</p><p><u><b>Job progress,</b></u></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-17_ GTG-7220 , PDT-72220 TS transmitter reading is abnormal', '2025-06-17 13:57:31', '2025-06-17 15:48:53', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PDT-72220-1', 'ZTK-PDT-72220-1', 'PDT Across F-7222-1,AL HI & SD HH', NULL, NULL, 'PDT Across F-7222-1,AL HI & SD HH', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
