BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Setup PLC, communication module & router.', 'Automation', 'OTH ', 'Completed', '2025-06-17', '<p><b><u>Activity</u>,</b></p><p>-&nbsp;Setup PLC, communication module &amp; router for preparation to troubleshoot WP2 telemetry failure.</p><p><b><u>History</u>,</b></p><p>-&nbsp;ESD3A was activated on WP02 due to Telemetry failure between WP02 PLC and PLC gateway.</p><p></p><p><b><u>Equipment description and location</u>,</b></p><p>- ZTK-WP02: Zawtika Wellhead Platform 02</p><p><b><u>As found</u>,</b></p><p>- NA<br class="Apple-interchange-newline"></p><p><b><u>What happen</u>,</b></p><p>- NA</p><p><b><u>Action</u>,</b></p><p>-Setup the power supply to simulation chassis.</p><p>-Installed Logic controller in simulation chassis.</p><p>-Performed download "WP02 project file" from the engineering laptop using RS232 to USB port.</p><p>-After downloaded the project file, installed the communication module (1756-EN2T).</p><p>-Checked the IP address. IP address is not automatically assigned.</p><p>-Changed the selector switch form 999 to 022 on the communication module (1756-EN2T)</p><p>-The communication module (1756-EN2T) IP address is now 192.168.1.22.</p><p>-Setup the router and installed the LAN cable between the communication module and the router.</p><p>-Installed the LAN cable between the router and the engineering laptop.</p><p>-The engineering laptop can go online to the logic controller.</p><p>-Installed the LAN cable between the communication module and the engineering laptop.</p><p>-The engineering laptop can go online to the logic controller.</p><p><b><u>As left</u>,</b></p><p>- The new communication module IP address is 192.168.1.22.</p><p>- The revision is 10.001.</p><p>- The existing communication module revision is 3.001.</p><p><b><u>Next plan</u>,</b></p><p>- Troubleshoot WP02 telemetry failure.<br class="Apple-interchange-newline"></p><p><b><u>Documentation</u>,</b></p><p>- NA.</p><p><u><b>Links</b></u></p><p>-NA</p><p><b><u>Job progress</u>,</b></p><p>-Completed</p>', NULL, '2025-06-17 15:25:37', '2025-06-17 15:57:58', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
