  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix gas seeping from seal gas filter PDIT of GTC-2', 'Electrical & Instrument', 'CM ', 'Completed', '2025-06-18', '<p><b><u>Activity,</u></b></p>  <p>-Fix gas seeping at the high side vent port of PDIT-43206 (Seal Gas Supply filter DP).</p>  <p><b><u>History,</u></b></p>  <p>-Production team observed that gas seeping from <b>PDIT-43206 (</b>Seal Gas Filter Differential Pressure Transmitter) vent plug during hydrocarbon release survey. </p><p><b><u> Equipment description and location, </u></b></p><p> -Seal Gas Filter Differential Pressure Transmitter, Upper Deck.</p><p><b><u>  As found, </u></b></p><p> - Found that gas leak at the high side vent port and high side sensing tubing fitting of PDIT-43206 (Seal Gas Supply filter DP). </p><p><b> What happen, </b></p><p> -Gas Leak.</p><p><b><u>  Action,</u></b></p><p> - Forced the value of&nbsp;<b>PDIT-43206&nbsp;</b>to prevent unexpected alarm &amp; SD during troubleshooting.&nbsp;</p>  <p>- Insolated the the transmitter from the sensing line and release the pressure.</p><p>- Replaced the fitting at the high side vent port.</p><p>- Cleaned and retightened the high side sensing tubing fitting.</p><p>- Normalized the isolation and equalizing valves.</p><p>- Performed leak check with laser methane and also check with snoop, there is no leak.</p><p>- Removed the Forced value and normalized the system.</p>  <p><b><u>As left,</u></b></p>  <p>-&nbsp;PDIT-43206 is back to normal.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-NA.</p>  <p><b><u>Next plan,</u></b></p>  <p>-NA.</p>  <p><b><u>Documentation,</u></b></p>  <p>-NA.</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-18_GTC-4400, PDIT43206 Fix gas seeping from seal gas filter PDIT of GTC-2', '2025-06-18 13:49:02', '2025-06-18 13:54:59', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4300', 'ZTK-GTC-4300', 'Train 2,Gas Turbine Comp Package', NULL, NULL, 'Train 2,Gas Turbine Comp Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
