  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, ' Fix the refrigerant leak at condenser tube GA-27', 'Electrical & Instrument', 'CM ', 'In Progress (Completed)', '2025-06-20', '<p><b><u>Activity</u>,</b></p><p>-To fix the refrigerant leak at condenser tube.</p><p><b><u>History</u>,</b></p><p>-11/06/2025</p><p><b><u>Equipment description and location</u>,</b></p><p>-Marine freezer GA-27 (Galley Room).</p><p><b><u>As found</u>,</b></p><p>- Found that&nbsp; Swagelok&nbsp; fittings 1/4" Union to connect the two ends at refrigerant pipe</p><p><b><u>Action</u>,</b></p><p>-Removed the Swagelok fitting and replaced&nbsp; bronze refrigerant fitting.</p><p>-Cut out the leaking parts and used bronze refrigerant 1/4"&nbsp;Union to connect the two ends.</p><p>-Make a copper flaring fitting and tighten back.</p><p>-Performed vacuum of the compressor with (1500 Microns) for 30mins.</p><p>-Topped up refrigerant R-404A and monitoring the current. (as left 3 A) _Rated ampere = 3.5A</p><p>-Checked leak again and found no more leak.</p><p>-R404A Refrigerant usage around&nbsp; 3.2Kg.</p><p><b><u>As left</u>,</b></p><p>-The unit navailable.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><b><u>Next plan</u>,</b></p><p>-Under monitoring .</p><p><b><u>Documentation</u>,</b></p><p>-N/A</p><p><b><u>Job progress</u>,</b></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-20_Fix the refrigerant leak at condenser tube GA-27', '2025-06-20 16:51:07', '2026-01-01 10:38:24', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
