  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2025-06-20 16:51:07', '2026-01-01 10:38:24', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
