  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Remove rust, painting and hot bolting', 'Mechanic', 'OTH ', 'Completed', '2025-06-25', '<p>Remove rust and painting at bling flange and hot bolting to swap SS to CS</p><p><br></p><p><u>21-6-2025</u></p><p><u><br></u></p><p>-Clean all the flange and bolts that are rusty</p><p>-Remove 1 SS bolt to swap with CS bolt</p><p>-Clean the flange surface using power tool</p><p>-Replace CS bolt 3/4" (B7M) (L-120 mm)&nbsp;&nbsp; (only 1 bolt/ flange&nbsp;at a time)</p><p><br></p><p><br></p><p>22-Jun-2025</p><p>Removed SS 8 bolts.</p><p>Perform sandblasting and Painting to the flange</p><p>Replaced new CS 8 bolts apply torque 169NM to 2inch flange and 96 NM to 1 inch flange.</p><p><br></p><p>23-Jun-2025</p><p>Removed SS 8 bolts.</p><p>Perform sandblasting and Painting to the flange</p><p>Replaced new CS 8 bolts apply torque 169NM to 2inch flange and 96 NM to 1 inch flange.</p><p><br></p><p>24-Jun-2025</p><p>Removed SS 8 bolts.</p><p>Perform sandblasting and Painting to the flange</p><p>Replaced new CS 8 bolts apply torque 169NM to 2inch flange and 96 NM to 1 inch flange.</p><p><br></p><p>To continue with proper blasting and painting&nbsp; &nbsp; ( 75% in progress )</p><p><br></p><p><br></p>', NULL, '2025-06-21 16:45:26', '2025-06-25 18:13:52', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
