-- Inserting report ID 36295
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S N2 seeping at accumulator No.2 of HP1 pump', 'Electrical & Instrument', 'CM ', 'Completed', '2025-06-23', '<p><u><b>Activity,</b></u></p><p>-T/S N2 seeping at accumulator No.2 of HP1 pump at WHCP-WP01-100.</p><p><u><b>History,</b></u></p><p>-During PM activities, found N2 seeping at accumulator No.2 of HP1 pump.</p><p><u><b>Equipment description and location,</b></u></p><p>-HP1 accumulator at WHCP and WP-01 lower deck</p><p><u><b>As found,</b></u></p><p>-Found no seeping at the fittings and&nbsp;<b>accumulator No.2&nbsp;pressure is 340 bar.</b></p><p>-NA</p><p><u><b>Action,</b></u></p><p>-Checked and verified the leak points at the accumulator No.2.</p><p>-Found no leak points at the accumulator fittings and other tubing fittings points.</p><p>-Checked accumulator No.1 pressure for HP-1 is 320 bar.</p><p>-Performed isolate header line and drain the hydraulic from accumulator to the tank.</p><p>-Checked the accumulator No.2 Pre-charge pressure and <b>found the pressure is 200 bar.</b></p><p><u><b>As left,</b></u></p><p>-Haskel pump (HP-1) is working properly and <b>accumulator No.1&amp;2 pressure are 315 bar</b>.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-NA</p><p><u><b>Next Plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA.</p><p><u><b>Job Progress,</b></u></p><p>-Completed.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-23_WP-01, WHCP-TS N2 leak at the accumulator No.2 for HP-1">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-23_WP-01, WHCP-TS N2 leak at the accumulator No.2 for HP-1</a><br></p>', '2025-06-23 14:38:27', '2025-06-23 17:41:24', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
