-- Inserting report ID 36303
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To troubleshoot strange noise ', 'Mechanic', 'CM ', 'Completed', '2025-06-24', '<p>Problem - Strange noise from chill water pump.</p><p>As found - pump bearing damaged.</p><p>Action -</p><p>23.6.2025</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;- Performed electrical isolation for motor (E&amp;I team).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Remove motor from pump housing.( motor mounting bolt spanner size 15/16 inch).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Remove bearing housing and impeller shaft ( bearing mounting bolt spanner size 15/16 inch).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Remove impeller from shaft ( impeller lock nut spanner size 41mm).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Remove mechanical seal from housing.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Remove snap ring from bearing housing.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Remove pump shaft together with bearing.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Remove bearing from shaft by hydraulic press.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Performed proper cleaning for pump shaft.</p><p><br></p><p>24.6.2025</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Apply heat to the new bearing with bearing heater to install to the shaft.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Installed the new bearing to the shaft, installed the snap ring for lock.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Replaced the mech seal , stationary face with the new one.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Replaced the deflector protector with new one.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Installed the shaft with new bearing to the bearing housing.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Installed the mech seal, rotation face with new one to the shaft.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Installed back the impeller with the shaft key.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - installed the o-ring for the impeller ring.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Installed back the lock nut to the shaft.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Installed the bearing housing and impeller assembly to the pump casing.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Installed the motor and installed the shaft key lock nut.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Installed the accessories to the package.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Performed deisolation of process and electrical.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Test run and no more abnormal noise from the pump.</p><p><br></p><p>&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\86 LQM HVAC\\P-8610 A\\2025\\2025-06-23 TS strange noise as per SKF report" target="_blank">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\86 LQM HVAC\\P-8610 A\\2025\\2025-06-23 TS strange noise as per SKF report</a><br></p>', '2025-06-23 18:07:24', '2025-06-24 18:18:50', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Cmms-Tech', false, 'ZTK') RETURNING id INTO new_report_id;
