  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Setup new HMI for sewage unit and TS unit freeze', 'Automation', 'CM ', 'Pending', '2025-06-25', '<p><u><b>Activity,</b></u></p><p>-T/S HMI for sewage unit is freeze, X-7300, sewage unit, sea deck.</p><p><u><b>History,</b></u></p><p>-HMI is freezing and can''t operate</p><p><u><b>Equipment description and location,</b></u></p><p>-X-7300, sewage unit, sea deck.</p><p><u><b>As found,</b></u></p><p>-HMI is freeze and touch is not working.</p><p>-Found that HMI touch is not working.</p><p><u><b>Action,</b></u></p><ul><li><p>-Verified the spare HMI reserved for the air compressor. It has the same size as the HMI used in the sewage unit but is a different model.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;Spare HMI for Air Compressor:</p><ul><li>&nbsp;&nbsp;&nbsp;&nbsp;Model: HMIGTO2310</li><li>&nbsp;&nbsp;&nbsp;&nbsp;Firmware Runtime Version: 7.0</li></ul><p>&nbsp;&nbsp;&nbsp;&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;Existing HMI in Sewage Unit:</p><ul><li>&nbsp;&nbsp;&nbsp;&nbsp;Model: XBTGT2220</li><li>&nbsp;&nbsp;&nbsp;&nbsp;Firmware Runtime Version: 6.1</li></ul></li><li><p><br></p><p>-Attempted to download sewage unit data into the spare HMI using Vijeo Designer software, but the operation was unsuccessful.</p></li><li><p>-Identified that Vijeo Designer version 6.2 or higher is required for compatibility with the spare HMI.</p><ul><li>&nbsp;&nbsp;&nbsp;&nbsp;<i>Current available version: 6.1</i></li><li><br></li><li>-Downloading version 6.2 is in progress.</li></ul></li></ul><p><u><b>As left,</b></u></p><p>-Install the new Vijeo Designer software version 6.2</p><p>-Download the data to the HMI.</p><p>-Check the functionality at the HMI.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-No on-hand spare and will order.</p><p>-HMI screen display model:</p><p>&nbsp; &nbsp;&nbsp;Model: Maglis Advanced Panel Schneider</p><p>&nbsp; &nbsp; Model No: XBTGT2220</p><p>&nbsp; &nbsp; Size: 5.7"</p><p><u><b>Next Plan,</b></u></p><p>-To setup new HMI and if working properly, installed at the sewage unit.</p><p><b style="background-color: rgb(255, 255, 0);">-Requested software support from PMO/I Engineer.</b></p><p><u><b>Documentation,</b></u></p><p>-NA.</p><p><u><b>Job Progress,</b></u></p><p><span style="background-color: rgb(255, 255, 0);"><b>-Waiting Software from PMO/I Engineer.(Vijeo Designer 6.3)</b></span></p>', NULL, '2025-06-25 15:40:57', '2025-09-05 08:04:33', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-7300', 'ZTK-X-7300', 'Sewage Treatment Package', NULL, NULL, 'Sewage Treatment Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
