  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Heat detector fault cannot clear TR-CPP201 area', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-06-26', '<p><b><u>Activity</u>,</b></p><p>- TS Heat detector&nbsp; HDC-79315A High Fault Alarm cannot be reset at transformer TR-CPP-201 area&nbsp;</p><p><b><u>History</u>,</b></p><p>-The high Alarm cannot be reset after function test YPM job on 24 Jun 2025.</p><p><b><u>Equipment description and location</u>,</b></p><p>- Heat Detector, Lower Deck at transformer TR-CPP-201 area&nbsp;</p><p><b><u>As found</u>,</b></p><p>- High Fault alarm HDC-79315A.</p><p><b><u>What happen</u>,</b></p><p>- NA.</p><p><b><u>Action</u>,</b></p><p>- Performed power isolation for TR-CPP-201.</p><p>- Checked the wiring and termination board, found all are normal.</p><p>- Measured as found the diode is (0.637 V) and the resistance reading&nbsp; 35.75K Ohm same with the new spare Heat detector.</p><p>- Measured the loop voltage and found 5.6 VDC due to the thermal sensor was in activation (Sensor contact close).</p><p>- Softly knocked the thermal sensor tip and found the contact sensor was Open &amp; Close intermittently.</p><p>- Thermal Sensor should be Contact&nbsp; NO during normal and NC when applying heat.</p><p>- So, replaced the new thermal sensor and reset the Alarm with Automation.</p><p>- Function test Alarm with Automation and High Alarm working properly.</p><p>- The alarm can be reset and the detector back to normal.</p><p><b><u>As left</u>,</b></p><p>- HDC-79315A back to normal.</p><p><b><u>Next plan</u>,</b></p><p>- NA</p><p><b><u>Documentation</u>,</b></p><p>- N/A</p><p><b><u>Job progress</u>,</b></p><p>- 100%&nbsp;</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-26_HDC-79315A TS fault alarm cannot clear', '2025-06-26 15:59:36', '2025-06-27 08:08:15', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HDC-79315A', 'ZTK-HDC-79315A', 'Heat Det,Transformer Bay-3 Area', NULL, NULL, 'Heat Det,Transformer Bay-3 Area', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2025-06-26 15:59:36', '2025-06-27 08:08:15', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'P''Rin', NULL, 'EXTERNAL', '2025-06-26 15:59:36', '2025-06-27 08:08:15', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
