  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot BDV valve control panel PSV passing', 'Electrical & Instrument', 'CM ', 'Completed', '2025-06-26', '<p><b><u>Activity,</u></b></p>  <p>-Troubleshoot BDV-01006 valve control panel PSV passing.</p>  <p><b><u>History,</u></b></p>  <p>-NA</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-BDV on production manifold to HP flare, WP-01</p>  <p><b><u>As found,</u></b></p>  <p>-Found that the PSV is pop-up and PSV setpoint is 5.3 bar.</p><p>-Also found that regulator pressure gauge damage.</p>  <p><b><u>What happen,</u></b></p>  <p>-IA is leaking from PSV down stream.</p>  <p><b><u>Action,</u></b></p>  <p>-Closed the downstream ball valve of BDV-01006.</p><p>-Isolated the IA supply and vent out the pressure. Valve was unable to open fully.</p>  <p>-Replaced the pressure gauge and deisolated the IA supply.</p><p>-Found that the regulating pressure is around 6 bar and it made the PSV to pop up.</p><p>-Regulated the IA pressure to 4.5 bar.</p><p>-Apply WD40 to the spools of solenoid and pilot valve.</p><p>-Performed function test with CCR and valve can open and close smoothly.</p><p>-Checked the leak and found there is no leak.</p><p>-Normalized the downstream ball valve of BDV-01006.</p>  <p><b><u>As left,</u></b></p>  <p>-BDV-01006 is in normal operation.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-NA</p>  <p><b><u>Next plan,</u></b></p>  <p>-NA</p>  <p><b><u>Documentation,</u></b></p>  <p>-NA</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-06-26 BDV-01006 TS PSV at vale control panel is passing', '2025-06-26 16:12:42', '2025-06-26 16:25:43', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-BDV-01006', 'ZTK-BDV-01006', 'BDV,2"-GC-01014-J4N,Prod MAN to HP flare', NULL, NULL, 'BDV,2"-GC-01014-J4N,Prod MAN to HP flare', 'WP01', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2025-06-26 16:12:42', '2025-06-26 16:25:43', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Han', NULL, 'EXTERNAL', '2025-06-26 16:12:42', '2025-06-26 16:25:43', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO spare (report_id, action, mesc, detail, qty, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Withdraw', '60.35.10.347.9', 'Troubleshoot BDV valve control panel PSV passing', '0', '2025-06-26 16:14:27', '2025-06-26 16:25:43', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
