  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS abnormal noise', 'Mechanic', 'CM ', 'Completed', '2025-06-27', '<p>Problem - Abnormal noise from Lube oil cooler fan E-4393A.</p><p>Found&nbsp; &nbsp; - 2 of 3 belts is slipped off from the grooves and worn out.&nbsp;&nbsp;</p><p>Action&nbsp; &nbsp; - Measured tension on remaining belt (24Hz)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Measured pulley alignment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Replaced new 3 belts.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Adjust recommended tension (44-46Hz) on all belts.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Clean the area and Reinstate fan guard.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Test run the unit and running normal.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Housekeeping the area.</p>', NULL, '2025-06-27 15:53:26', '2025-06-27 15:57:32', 'PTTEP\\ZPQ.Mechanical-Turbi', 'PTTEP\\ZPQ.Mechanical-Turbi', false, 'ZTK') RETURNING id INTO new_report_id;
