-- Inserting report ID 36350
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replaced AMOT valve at CR-0173', 'Mechanic', 'CM ', 'Completed', '2025-07-04', '<p>28-6-2025</p><p>Job Description : T/S AMOT valve malfunction.</p><p>Found&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : AMOT valve was not functioning.</p><p>Job Task&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Removed damage AMOT valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Installed with new AMOT.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Test run the engine and can start the engine.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : But found engine cannot stop with the emergency stop.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Tomorrow will troubleshoot.&nbsp;</p><p>30-6-2025</p><p>Job Description : T/S engine cannot killed by AMOT emergency stop switch.</p><p>Job Task&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Adjust the AMOT valve lever and test emergency stop function cannot activate.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Replaced with the another AMOT valve but emergency stop function still cannot activate.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the air shutoff valve and lubricate the internal part to make sure freely&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;movement.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Replaced another new AMOT valve and check it''s function but still cannot activate&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;emergency stop.</p><p><br></p><p>1-7-2025</p><p>Job Task&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Checked and adjusted the killed cable.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Found that killed wire holder was deteriorated and cannot tightly hold the killed cable.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;And also found that killed cable was stacked.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Next day will modified the cable holder.&nbsp;</p><p><br></p><p>4-7-2025</p><p>Job Task&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Removed the killed cable and it''s holder bracket.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Insert some spacer washer between the cable holder and base plate.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Installed back the killed cable and it''s holder.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Function test the E stop and it can shutdown the engine.</p><p><br></p><p>&nbsp;&nbsp;</p>', NULL, '2025-06-28 17:40:05', '2025-07-04 18:08:27', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Crane', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP01-CR-0173', 'ZTK-WP01-CR-0173', 'Pedestal Crane Package for ZTK WP01', NULL, NULL, 'Pedestal Crane Package for ZTK WP01', 'WP01', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
