  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Plate', NULL, 'EXTERNAL', '2025-06-28 17:40:05', '2025-07-04 18:08:27', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Crane');
