  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '8K PM Air Comp: A-6500C ', 'Mechanic', 'PM ', 'Completed', '2025-07-01', '<p>Perform 8K PM of Instrument air compressor A-6500C</p><p><br></p><p>Maintenance Kit&nbsp;(8K HR, P/N.2906074100)&nbsp;</p><br><p><u>29-06-2025</u></p><p><u>Action</u></p><p>-Drain all lube oil.</p><p>-Flush with new lube oil until it is&nbsp;clean</p><p>-Top up lube oil approximately - 35 L</p><p>-Change lube oil filter (Atlas Copco&nbsp;16148747 99)</p><p>-Running Hour - 25078 hr</p><p><br></p><p><u>30-06-2025</u></p><p><u>Action</u></p><p><u><br></u></p><p>-Replaced air filter&nbsp;</p><p>-Clean auto drain valve HP and LP debris collector(sponge)&nbsp;</p><p>-Replaced unloader valve gasket and replaced diaphragm</p><p>-Replaced lube oil breather filter and washer</p><p>-Replace check v/v at LP side</p><p>-Check the coupling</p><p>-Check silencer (<span style="background-color: rgb(255, 255, 0);">Found that broken replace with hot spare)</span></p><p><span style="background-color: rgb(255, 255, 0);">-Perform borescope inspection for&nbsp;</span><span style="background-color: rgb(255, 255, 0);">gear teeth inside gear box (Look ok)&nbsp;</span></p><p>-Test run the unit <span style="background-color: rgb(255, 255, 0);">(OK)</span></p><p><br></p><p>1-7-2025</p><p>Action</p><p><br></p><p>-Performed borescope inspection for HP and LP element.</p><p>-Removed the PT line tubing from the HP side, removed the valve at the line.</p><p>-Performed borescope inspection for HP, found some minor scratches at Male rotor and minor scratches and small area of thermal coating peel off at the Female rotor side.</p><p>-Removed the air filter and performed inspection from unloader valve flapper to LP side.</p><p>-Found only small area of thermal coating peel off at the male rotor and female rotor found normal condition.</p><p><span style="background-color: rgb(255, 255, 0);"><b>-Overall result is seem normal condition for HP and LP screw pump.</b></span></p><p><u><br></u></p><p><u><br></u></p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\65 INSTRUMENT AIR, UTILITY AIR &amp; N2\\6501 Instrument Air Compressors\\A-6500 C\\2025\\2025-06-29 8K PM">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\65 INSTRUMENT AIR, UTILITY AIR &amp; N2\\6501 Instrument Air Compressors\\A-6500 C\\2025\\2025-06-29 8K PM</a><br></p>', '2025-06-29 17:24:42', '2025-07-01 18:01:29', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Cmms-Tech', false, 'ZTK') RETURNING id INTO new_report_id;
