  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1M Lube Oil replacement', 'Mechanic', 'PM ', 'Completed', '2025-07-01', '<p>1 Monthly lube oil replacement and mech seal flushing</p><p><br></p><p>Action.</p><p>-Check mech-seal by using Borescope (<span style="background-color: rgb(255, 255, 0);">found Salty inside</span>)</p><p>-Flush mech-seal with fresh water while running</p><p>-Recheck with borescope (Found that clean)</p><p>-Stop the unit&nbsp;</p><p>-Remove the expansion chamber</p><p>-Drain lube oil from the pump.</p><p>-Clean the lube oil level sight glass that was dirty</p><p>-Apply RTV and reinstall the sight glass</p><p>-Top up lube oil appro~2.5 Liter</p><p>-Reinstall the expansion chamber</p><p>-Run the unit (No Abnormal Found)</p><p><br></p>', NULL, '2025-07-01 13:58:47', '2025-07-01 14:04:54', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
