-- Inserting report ID 36400
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Prepare drive gear for water maker A', 'Mechanic', 'CM ', 'In Progress', '2025-07-02', '<p>Prepare drive gear for water maker A</p><p><br></p><p><u>2-July-2025</u></p><p><u><br></u></p><p>Action</p><p>-make the measurement of fabricated gear&nbsp;(Check the measurement detail as attached PDF file)&nbsp;</p><p>-clean the ext-coupling adapter and input shaft</p><p>-input the shaft completely to the shaft cavity</p><p>-install the collar on the input shaft and tighten the set screws\\</p><p>-install the slinger on the collar edge</p><p><br></p><p>- Grind the gear bore appr~0.15 mm&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Shaft Dia&nbsp; - 40.6mm&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Bore Dia of old gear -40.6mm&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Bore Dia of new Gear-40.45mm&nbsp; &nbsp;&nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">Note - * Refurbished gear cannot be separated addendum or dedendum because Gear teeth are&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">more likely to V shape and pitch circle could not&nbsp; be clearly determined *&nbsp;</span></p><p><br></p><p>- Heat up the gear by using induction heater (set Temp 145''C)</p><p>- Install the gear on the input shaft (machine face to the motor side)</p><p>-Check and prepare the hub and spider coupling</p><p><br></p><p style="margin-left: 25px;">Lock ahead plan : Waiting for instruction to install on the unit.</p><p><br></p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-07-02 Prepare Drive Gear for Water maker A">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-07-02 Prepare Drive Gear for Water maker A</a><br></p>', '2025-07-02 17:52:49', '2025-07-02 20:56:56', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
