  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS engine cannot crank.', 'Mechanic', 'CM ', 'Completed', '2025-07-03', '<p>Problem : Engine is failed to crank and shaft locked during monthly unit change over.</p><p>Action&nbsp; &nbsp; &nbsp;: Isolate starter motor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Try to turn the starter motor manually by torque wrench as per solar recommend torque value&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(Start from 200nm).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The shaft is released on 800Nm torque.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; De-isolate starter motor.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Test crank the engine for 3mins.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Normal start the engine by gas mode.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Load share with GTG-7210 and stop GTG-7230 as per PMO/I running schedule.&nbsp;</p><p><br></p><p><br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', NULL, '2025-07-03 17:59:24', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Cmms-Tech', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
