  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Eric', NULL, 'EXTERNAL', '2025-07-03 17:59:24', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Cmms-Tech', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'EI (Ko Zargi', NULL, 'EXTERNAL', '2025-07-03 17:59:24', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Cmms-Tech', NULL);
