  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Unloader valve pilot manifold malfunction', 'Mechanic', 'CM ', 'Completed', '2025-07-04', '<p>Problem:</p><p><br></p><p>2nd stage discharge of the A-6500 C is low and around 2.5 bar during running as Lag 1.</p><p><br></p><p>Action:</p><p>Check the air compressor package tubing and accessories.</p><p>Found that one tubing line of the pilot control manifold of the unloader valve is coming off.</p><p>The thread at the pilot manifold is gone and cannot install back.</p><p>Replaced with the new pilot manifold, <b>Part no.1621528200.</b></p><p>Installed back the new pilot manifold with the gasket and diaphragm set of the manifold.</p><p>Test run and unit back to normal.</p><p>2nd discharge outlet pressure is around 8.33 bar which is normal range.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\65 INSTRUMENT AIR, UTILITY AIR &amp; N2\\6501 Instrument Air Compressors\\A-6500 C\\2025\\2025-07-04 Replace Unloader pilot manifold">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\65 INSTRUMENT AIR, UTILITY AIR &amp; N2\\6501 Instrument Air Compressors\\A-6500 C\\2025\\2025-07-04 Replace Unloader pilot manifold</a><br></p>', '2025-07-04 18:08:17', '2025-07-04 20:36:52', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
