  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'P-4810A 2Y PM', 'Mechanic', 'PM ', 'Under Monitoring', '2025-07-09', '<p>Job : 2Y PM</p><p><br></p><p>Action:</p><p>5 July 2025</p><p>-Drained gear oil from the crankcase.</p><p>-Drained gear oil from the reducer gearbox.</p><p>-Removed the old crankcase gasket.</p><p>-Cleaned the crankcase oil level gauge.</p><p>-Cleaned the gearbox oil level gauge.</p><p>-Top up lube oil EP 220 to crankcase about 60L.</p><p>-Top up lube oil EP 220 to gearbox about 9L.</p><p>-Install back the crankcase cover with new gasket.</p><p>-Removed the coupling guards and check the couplings condition.</p><p>-Housekeeping the area.</p><p><br></p><p>6 July 2025</p><p>-Removed the end plates of the plunger from the hydraulic end.</p><p>-Disconnected the cross head and plunger by removed the two to two rings.</p><p>-Removed all the plungers out and checked the plunger condition.</p><p>-Removed the plunger packing and stuffing boxes.</p><p>-Removed existing mean seal packings and rear seal packing.</p><p>-Removed the packing lantern.</p><p>-Found No.2 packing lantern is damaged surface area, replaced with new packing lantern.</p><p>-Cleaned the stuffing boxes and check the condition.</p><p>-Inserted the new mean seal and rear seal packings into the stuffing boxes.</p><p>-Installed back the packing lantern to the stuffing boxes.</p><p>-Cleaned the plungers and check the plunger condition with Spotcheck ( Cleaner, Penetrant, Developer)</p><p>-Found plungers are in normal condition without crack.</p><p>-Ready to install back next day.</p><p>-Housekeeping the working area and package area.</p><p><br></p><p>7 July 2025</p><p>-Installed stuffing boxes at the hydraulic end.</p><p>-Installed plungers.</p><p>-Reconnected the plungers with the crossheads, installed with two two rings and tighten the crosshead lock nuts.</p><p>-Check and tightened all plunger locking nuts and counter nuts.</p><p>-Installed back the end plates with new O-rings.</p><p>-Installed back the drain line tubing and found ferrules damaged.</p><p>-Remodified it with new 10mm double ferrules union at the workshop.</p><p>-Housekeeping the worksite area.</p><p><br></p><p><u>08-July-2025</u></p><p>Install back drain line.</p><p>Nitrogen check for dampener - 7 bar&nbsp; and recharge to 40 bar.</p><p>Test run and adjust the packing.</p><p>Tomorrow, we''ll continue adjusting the packing.</p><p><br></p><p><b><u>09-July-2025</u></b></p><p>- Top up the lube oil up to 50 % of sight glass for crankcase.</p><p>-&nbsp; Adjusted the packing&nbsp; - no.1 - 15 drops/min, no.2 - 11 drops/min and no.3 8 drops/min to maintain the temperature around 70''C for all stuffing boxes.</p><p>- Unit running normal and keep under monitoring.</p><p><br></p><p><br></p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\48 GLYCOL REGENERATION T2\\P-4810 A\\2025\\2025-07-05 2 Year PM">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\48 GLYCOL REGENERATION T2\\P-4810 A\\2025\\2025-07-05 2 Year PM</a><br></p>', '2025-07-05 18:26:36', '2025-07-09 18:03:03', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Cmms-Tech', false, 'ZTK') RETURNING id INTO new_report_id;
