  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S damper air leakage.', 'Electrical & Instrument', 'CM ', 'Completed', '2025-07-07', '<p><u><b>Activity,</b></u></p><p>-HFD-86100 and HFD-86306, T/S damper air leakage at LQM Level-2&amp;3.</p><p><u><b>History,</b></u></p><p>-Found air leak during yearly HVAC fire damper PM.</p><p><u><b>Equipment description and location,</b></u></p><p>-Fire damper at LQM level 2 &amp; 3</p><p><u><b>As found,</b></u></p><p>-Both fire dampers were air leaking from pilot SOV.</p><p><u><b>What happen,</b></u></p><p>-Aging.</p><p><u><b>Action,</b></u></p><p>-By-passed the instrument supply line to open the fire dampers when overhauling the pilot.</p><p>-Overhaul the pilot new repair kits.</p><p>-Reinstalled back the instrument supply line and fire dampers are back to normal.</p><p>-Found no air leak and check with snoop at the instrument supply line.&nbsp; &nbsp;</p><p><u><b>As left,</b></u></p><p>-Both fire dampers are back to service.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-NA</p><p><u><b>Next plan,</b></u></p><p>-To overhaul the removed pilot tubes.</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-100%</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-07_HFD-86100 &amp; HFD-86306 TS damper air leakage">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-07_HFD-86100 &amp; HFD-86306 TS damper air leakage</a><br></p>', '2025-07-07 16:09:09', '2025-07-07 16:11:28', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
