  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS hypochlorite low performance', 'Electrical & Instrument', 'CM ', 'Completed', '2025-07-09', '<p><b><u>Activity,</u></b></p>  <p>-X-6640, TS hypochlorite low performance.</p>  <p><b><u>History,</u></b></p>  <p>-Hypochlorite flow is not stable.&nbsp;</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Hypochlorite generator, Lower Deck.&nbsp;</p>  <p><b><u>As found,</u></b></p>  <p>-Found the chlorine inside the Electrolyser Module assembly.&nbsp;</p>  <p><b><u>What happen,</u></b></p>  <p>-Aging.</p>  <p><b><u>Action,</u></b></p>  <p>-Removed the parts of Electrolyser Module.</p>  <p>-Assembly the the Electrolyser Module with new spare part.&nbsp;</p><p>-Re-installed back and found no leak.</p><p>-Perform test run and monitor the unit.</p>  <p><b><u>As left,</u></b></p>  <p>-Sea water inlet flow (FT-66465) is <b>7.1 m3/h</b>,</p><p>-Hypochlorite package, X-6640 is back to service.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-Will keep in common store after cleaning the old parts of Electrolyser Module.</p>  <p><b><u>Next plan,</u></b></p>  <p>-Will clean the old parts of Electrolyser Module</p>  <p><b><u>Documentation,</u></b></p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-09_X-6640, TS hypochlorite low performanace', '2025-07-09 15:55:59', '2025-07-09 18:03:40', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
