-- Inserting report ID 36472
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace fan bearings and motor', 'Mechanic', 'CM ', 'Under Monitoring', '2025-07-11', '<p>Problem : Abnormal noise.</p><p>Found&nbsp; &nbsp; : Belt is slipping during running and generate abnormal sound.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Fan pulley and motor mis-alignment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Bearings are defective.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Fan belt is 50% worn out.&nbsp; &nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Motor pulley worn out.&nbsp; &nbsp;</p><p><br></p><p><b><u>11.7.25</u></b></p><p>Action&nbsp; &nbsp; : Removed fan belt, fan blade and fan pulley.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Drilled and tapping for vibration probe and grease ports on both upper and lower bearings.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Drilled and tapping to install stopper plate on fan shaft.&nbsp;</p><p><br></p><p><u><b>12.7.25</b></u></p><p>Action&nbsp; &nbsp; : Installed new fan shaft, upper bearings, and lower bearings. (NSK)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked pulley alignment between motor and fan.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Tighten all bolts with recommended torque values.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Installed new belt and adjust tension.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; During tensioning(20.8Hz), the pulleys are difficult to turn by hand.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the belt and turned both pulleys each at a time by hand.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Fan pulley could turn by hand. No abnormal found.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Motor pulley is difficult to turn by hand.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Reported EI team to troubleshoot the motor.&nbsp;</p><p><br></p><p><u><b>13.7.25</b></u></p><p>Action&nbsp; &nbsp; : Verified motor bearing by test run the motor without load together with EI team.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found abnormal noise likely bearing damage noise from motor DE side during unit running.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Stop the motor and re-isolate power.&nbsp;</p><p><br></p><p><u><b>14.7.25</b></u></p><p>Action&nbsp; &nbsp; : Support EI team to remove old motor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Set up lifting tools, and disconnected cables.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <b>Lifting tools- 2xM16 swivel eye bolts, 1xM20 eye bolt, 3x1ton chain hoists, 3x1.5m 1ton&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; slings</b>,&nbsp;<b>and 3xshackles.&nbsp;</b></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <b>Connection points- Motor shaft lifting point and lifting eye bolt holes.</b></p><p><b>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </b>Loosen motor mountain bolts and recorded shims at DE foot. (No shim at NDE foot)&nbsp;</p><p><br></p><table class="table table-bordered"><tbody><tr><td><b>DE (left)</b></td><td><b>DE (right)</b></td></tr><tr><td>1.9mm</td><td>1.6mm</td></tr><tr><td><b>NDE (left)</b></td><td><b>NDE (right)</b></td></tr><tr><td>N/A</td><td>N/A</td></tr></tbody></table><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Moved down the motor from the frame.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Lifted up spare motor and installed at the frame.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Disassembly lifting tools.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; EI team re-connected cables.</p><p><br></p><p><u><b>14.7.25</b></u></p><p>Action&nbsp; &nbsp; : Checked motor soft foot, shaft alignment without shims and shafts centerline.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><table class="table table-bordered"><tbody><tr><td>Shaft Angular&nbsp;</td><td>-0.6 degree</td></tr><tr><td>Shaft Parallel&nbsp;</td><td>0 degree</td></tr></tbody></table><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed alignment with shims on both motor DE foot and final result as below;</p><p><br></p><p>&nbsp; &nbsp;</p><table class="table table-bordered"><tbody><tr><td><b>DE (left)</b></td><td><b>DE (right)</b></td></tr><tr><td>2.4mm</td><td>2mm</td></tr><tr><td><b>NDE (left)</b></td><td><b>NDE (right)</b></td></tr><tr><td>N/A</td><td>N/A</td></tr></tbody></table><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><table class="table table-bordered"><tbody><tr><td>Shaft Angular&nbsp;</td><td>-0.20 degree</td></tr><tr><td>Shaft Parallel&nbsp;</td><td>0 degree</td></tr></tbody></table><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Test run the motor without load.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Performed laser alignment between two pulleys.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Adjusted belt tension at both side. (31.0Hz)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Applied Lube-A spray on bolts and shafts.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Reinstated fan guard, power deisolate and test run the unit.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Unit is running normal, and unit monitoring.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p><u><b>Replaced spare</b></u></p><p><b>1. Fan bearings x2</b></p><p><b>2. Fan Shaft</b></p><p><b>3. Motor pulley</b></p><p><b>4. Fan belt</b></p><p><b>5. Motor (EI team)</b></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p><br></p><p><br></p><p> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\GAS COOLER FAN (E-4360-A and E-4360B)\\E-4330 (1st Stage)\\E-4330 A\\2025\\2025-07-11 Replace motorbearings">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\43 GAS COMPRESSOR T 2\\GAS COOLER FAN (E-4360-A and E-4360B)\\E-4330 (1st Stage)\\E-4330 A\\2025\\2025-07-11 Replace motorbearings</a><br></p>', '2025-07-11 20:41:23', '2025-07-20 19:46:33', 'PTTEP\\ZPQ.Mechanical-Turbi', 'PTTEP\\ZPQ.Mechanical-Turbi', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EF-4330A', 'ZTK-EF-4330A', '1st Stg Comp Disch Cooler Fan A', NULL, NULL, '1st Stg Comp Disch Cooler Fan A', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-FM-4330A', 'ZTK-FM-4330A', '1st Comp Disch Cooler Fan Motor A', NULL, NULL, '1st Comp Disch Cooler Fan Motor A', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'P''Witt', NULL, 'EXTERNAL', '2025-07-11 20:41:23', '2025-07-20 19:46:33', 'PTTEP\\ZPQ.Mechanical-Turbi', 'PTTEP\\ZPQ.Mechanical-Turbi');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Eric', NULL, 'EXTERNAL', '2025-07-11 20:41:23', '2025-07-20 19:46:33', 'PTTEP\\ZPQ.Mechanical-Turbi', 'PTTEP\\ZPQ.Mechanical-Turbi');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'John', NULL, 'EXTERNAL', '2025-07-11 20:41:23', '2025-07-20 19:46:33', 'PTTEP\\ZPQ.Mechanical-Turbi', 'PTTEP\\ZPQ.Mechanical-Turbi');
