-- Inserting report ID 36514
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS hyd seeping from hand pump', 'Mechanic', 'CM ', 'Completed', '2025-07-15', '<p>Issue: Hydraulic seeping from hand pump and crane cannot start.</p><p>Action: Check hydraulic accumulator pressure. All accumulator pressure is low.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Check every line up position and fitting condition of hand pump.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Found hydraulic fitting bond seal from hand pump is broken and loosen.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Remove broken seal and wrap with PTFE tape at sealing area.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Reinstall the fitting and check for leakage. Found no leak.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Recharge one hydraulic accumulator up to 180 barg with hand pump.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Start the crane engine. Crane can start easily.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Check accumulator nitrogen pressure.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Accumulator no.1 = 35 barg</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; Accumulator no.2 = 70 barg</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; Accumulator no.3 = 40 barg<br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP6\\Crane CR-0673\\2025\\2025-07-15 TS hyd seeping from hand pump">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP6\\Crane CR-0673\\2025\\2025-07-15 TS hyd seeping from hand pump</a><br></p>', '2025-07-15 19:22:11', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-0673-EN', 'ZTK-CR-0673-EN', 'Pedestal Crane Diesel Engine WP06', NULL, NULL, 'Pedestal Crane Diesel Engine WP06', 'WP06', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Plate', NULL, 'EXTERNAL', '2025-07-15 19:22:11', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'John', NULL, 'EXTERNAL', '2025-07-15 19:22:11', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
