-- Inserting report ID 36515
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS coolant leak from radiator and replace radiator', 'Mechanic', 'PM ', 'In Progress', '2025-07-16', '<p>15-07-2025</p><p>Problem&nbsp; : Coolant leaked from the base of the radiator fin tube.</p><p>Job Task : Drained all the coolant from the radiator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Performed surface preparation for leak area.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Clean and dry the leak area.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Applied Belzona to the leak area.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Wait for Belzona curing time.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Top up de-ionized water to the radiator and found no leak.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Test run the engine for 15 mins and observed leakage found no leak.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;At evening time crew boat arrived and lift the spare radiator and tool container to the WP-02</p><p><br></p><p>16-7-2025</p><p>Job Task&nbsp; : Drained all the coolant form old radiator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Disconnected hose of Hyd cooler and removed Hyd cooler.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the cover of radiator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the radiator and moved to deck floor.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Inspected the new radiator and top up water to new radiator.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found that different flow path and suspected leak from fins.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Reinstalled old radiator and top up with de-ionized water.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Test run the engine and function test the crane for 25 mins.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Radiator was not found leak.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', NULL, '2025-07-15 19:25:26', '2025-07-16 20:39:41', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Crane', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP02-CR-0273', 'ZTK-WP02-CR-0273', 'Pedestal Crane Package WP02', NULL, NULL, 'Pedestal Crane Package WP02', 'WP02', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'P'' Witt', NULL, 'EXTERNAL', '2025-07-15 19:25:26', '2025-07-16 20:39:41', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Crane');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2025-07-15 19:25:26', '2025-07-16 20:39:41', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Crane');
