  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS level transmitter malfunction', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-07-18', '<p><u><b>Activity,</b></u></p><p>-Troubleshoot level transmitter of test separator malfunction at WP-15</p><p><u><b>History,</b></u></p><p>-N/A</p><p><u><b>Equipment description and location,</b></u></p><p>-LT-15106, Level transmitter of test separator at WP-15</p><p><u><b>As found,</b></u></p><p>-Level transmitter reading values fluctuate&nbsp;</p><p><u><b>What happen,</b></u></p><p>-Impurity and High side valve passing&nbsp;</p><p><u><b>Action,</b></u></p><p>-Perform isolation for both inlet ball valves of the level transmitter column</p><p>-Check the transmitter reading values by Hart communication (62.4% PV in Range)</p><p>-Flushed and drained the liquid water of level transmitter column</p><p>-Found a lot of impurity and dirty foaming from the drain water</p><p>-Found the high side ball valve is passing&nbsp;</p><p>-Compare with LT-15117 and check the LT value (65.3% PV in Range)</p><p>-De-isolate the both inlet ball valves and check the level transmitter values</p><p>-Confirm CCR and local HMI with the LT-15106 reading values stable</p><p><u><b>As left,</b></u></p><p>-LT-15106 reading value is normal and stable</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><u><b>Next plan,</b></u></p><p>-N/A</p><p><u><b>Documentation,</b></u></p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-90% completed.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-18_LT15106, TS test separator level transmitter malfunction">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-18_LT15106, TS test separator level transmitter malfunction</a><br></p>', '2025-07-18 19:53