  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS EDG ESD activated and spurious tripped', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-07-19', '<p><u><b>Activity,</b></u></p><p>-Troubleshoot EDG-7200 was tripped by emergency stop signal. (Day-1)</p><p><u><b>History,</b></u></p><p>-N/A</p><p><u><b>Equipment description and location,</b></u></p><p>-EDG-7200, Emergency Diesel Generator, Lower Deck&nbsp;</p><p><u><b>As found,</b></u></p><p>-EDG-7200_UCP-10, Emergency Shutdown Genset</p><p>-EDG-7200_BCH-02, Alarm Battery charger fault</p><p>-EDG-7200_ENG-28, Air inlet shutoff valve closed</p><p>-EDG-7200_BCH-01, Low battery charger voltage</p><p><u><b>What happen,</b></u></p><p>-Emergency stop signal activated&nbsp; (Unit is in stop condition)</p><p><u><b>Action,</b></u></p><p>-Visual check the alarm signals and records the emergency stop status</p><p>-Reset the air inlet valve and fuel inlet valve at local Genset</p><p>-Reset the activated Emergency stop signal at local and HMI</p><p>-Perform test run the generator with Electric mode. Generator running normal 15 minutes without load</p><p>-Perform test run the generator with Hydraulic mode, Generator running normal 15 minutes without load</p><p>-Visual check the condition, after running test the generator (No leak of lube oil or Hydraulic)</p><p><u><b>As left,</b></u></p><p>-Unit back to normal</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><u><b>Next plan,</b></u></p><p>-To verify the root cause of spurious ESD trip while unit is in stop condition.</p><p><u><b>Documentation,</b></u></p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-50% completed.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-19_EDG-7200_TS EDG-7200 was tripped by Emergency Stop Alarm">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-19_EDG-7200_TS EDG-7200 was tripped by Emergency Stop Alarm</a><br></p>', '2025-07-19 16:18:34', '2025-07-29 08:25:55', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
