  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS shutdown valve cannot operate', 'Electrical & Instrument', 'CM ', 'Completed', '2025-07-22', '<p><b><u>Activity,</u></b></p>  <p>-TS shutdown valve cannot operate, SDV-41004</p>  <p><b><u>History,</u></b></p>  <p>-NA</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Shutdown valve for Oily water to Desander cyclone, inlet separator (Main deck)</p>  <p><b><u>As found,</u></b></p>  <p>-Valve status show close and cannot open by manual valve knot.</p>  <p><b><u>What happen,</u></b></p>  <p>-Solenoid valve (SOV-41004) pilot is corroded and stuck.</p>  <p><b><u>Action,</u></b></p>  <p>-Check instrument air regulator pressure and found pressure gauge is damaged.</p><p>-Replaced new pressure gauge and check regulator pressure. (4 bar)</p><p>-Perform exercise manually open/close to shutdown valve.</p><p>-Found valve is not moving and status show close.</p><p>-Check instrument air supply of solenoid valve outlet to shutdown valve actuator.</p><p>-Check power supply of SOV (22.33 VDC) and coil resistance (197.2 Ohm)</p><p>-Found solenoid pilot is stuck and no air supply at the outlet of SOV.</p><p>-Replace new solenoid valve and function test with operator.</p><p>-Found shutdown valve can open/close properly. (opening time= 5 seconds, closing time=2 seconds)</p><p><b><u>As left,</u></b></p>  <p>-Shutdown valve is back to Inservice.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-NA</p>  <p><b><u>Next plan,</u></b></p>  <p>-NA</p>  <p><b><u>Documentation,</u></b></p>  <p>-NA</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-22_SDV-41004, TS shutdown valve cannot operate', '2025-07-22 16:07:09', '2025-07-23 17:53:01', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SDV-41004', 'ZTK-SDV-41004', 'SDV,V-4100 Oily Water to DesanderCyclone', NULL, NULL, 'SDV,V-4100 Oily Water to DesanderCyclone', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Peter', NULL, 'EXTERNAL', '2025-07-22 16:07:09', '2025-07-23 17:53:01', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
