  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S refrigerator is not working', 'Electrical & Instrument', 'CM ', 'In Progress (Completed)', '2025-07-22', '<p><u><b>Activity,</b></u></p><p>-T/S refrigerator is not working.(Day-1)</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-Refrigerator for baker, Gallery room.</p><p><u><b>As found,</b></u></p><p>-Refrigerator temperature not change.</p><p>-Suspected low refrigerant.&nbsp;</p><p><u><b>What happen,</b></u></p><p>-Refrigerant leak at the inlet of the evaporator.</p><p><u><b>Action,</b></u></p><p>-Checked the running capacitor and starting capacitor. (Normal)</p><p>-Tested run the unit and check the compressor status. (Compressor running - 1A)</p><p>-There was no refrigerant charging port at the compressor. (Charging port was welded and sealed)</p><p>-Modified the refrigerant charging port.</p><p>-Charged the refrigerant (404A) and check leak at the compressor unit.</p><p>-Found refrigerant leak at the inlet of the evaporator.</p><p>-Fixed the leak point with Belzona compound and let it dry.</p><p><u><b>As left,</b></u></p><p>-unit still unavailable.&nbsp;</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-Vacuum pump, refrigerant cylinder (R404A) and tool bag put inside LVL-1 switchgear.</p><p><u><b>Next plan,</b></u></p><p>-Vacuumed the compressor, charge refrigerant and check leak.&nbsp;&nbsp;</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job progress,</b></u></p><p>-In Progress</p>', NULL, '2025-07-22 17:25:43', '2025-07-28 08:09:47', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LQM-GALLEY', 'ZTK-LQM-GALLEY', 'Galley Room', NULL, NULL, 'Galley Room', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
