  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS FD-61706 shows short circuit fault', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-07-24', '<p><u><b>Activity,</b></u></p><p>-Troubleshoot Flame Detector FD-61706 shows short circuit fault alarm</p><p><u><b>History,</b></u></p><p>-During 1YPM flame detector function test, FD-61706 shows fault at SIS. (23-07-25)&nbsp;</p><p><u><b>Equipment description and location,</b></u></p><p>-Flame detector FD-61706 at lower deck.</p><p><u><b>As found,</b></u></p><p>-Sensor is defective&nbsp;</p><p><u><b>What happen,</b></u></p><p>-Aging, Optical part reflector error</p><p><u><b>Action,</b></u></p><p>- Troubleshoot FD-61706 shows short circuit alarm at SIS</p><p>- Perform function test flame detector with automation to confirm the fault alarm</p><p>- Remove the defective optical reflector part and check inside the condition</p><p>- Found no water ingress and no physical damage inside</p><p>- Check and measure the voltage of base housing terminal block, (23.02 Vdc)</p><p>- Replace with new optical reflector part GM- FL4000H</p><p>-Configure the Dip switch off same as the old one&nbsp;</p><p>- Perform function test again and shows High-High alarms at CCR and automation</p><p><u><b>As left,</b></u></p><p>-Unit back to normal</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-Defective part is keep in workshop (to verify)</p><p><u><b>Next plan,</b></u></p><p>-N/A</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job progress,</b></u></p><p>-90% completed</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-24_ZTK-SFGS-FD_Perform 1YPM flame detectors at lower deck">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-24_ZTK-SFGS-FD_Perform 1YPM flame detectors at lower deck</a><br></p>', '2025-07-24 15:19:11', '2025-07-28 08:25:27', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
