  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S refrigerator is not working.', 'Electrical & Instrument', 'CM ', 'In Progress (Completed)', '2025-07-25', '<p><u><b>Activity,</b></u></p><p>-T/S refrigerator is not working. (Day-3)</p><p><u><b>History,</b></u></p><p>-Continue job from (23-Jul-2025)</p><p><u><b>Equipment description and location,</b></u></p><p>-Refrigerator for baker, Gallery room.</p><p><u><b>As found,</b></u></p><p>-Refrigerator temperature not change.</p><p>-Suspected low refrigerant.&nbsp;</p><p><u><b>What happen,</b></u></p><p>-Refrigerant leak at the inlet of the evaporator.</p><p><u><b>Action,</b></u></p><p>-Checked Belzona condition (Hardness is ok)</p><p>-Vacuumed the compressor for 15 mins.&nbsp;</p><p>- Charged refrigerant (R404a) and checked leak. (No leak).</p><p>-Charged refrigerant (gas pressure - 55 psi) and checked current. (<b>as Left current - 2.3A, Rating current - 2.7A</b>)</p><p>-<span style="background-color: rgb(255, 255, 0);">Let the refrigerator running from 10:00 to 18:00 and check compressor current (2.3A) and gas pressure 55psi.</span></p><p>- Refrigerator set temp - 4 C.</p><p><u><b>As left,</b></u></p><p>-Unit under monitoring.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-Vacuum pump, refrigerant cylinder (R404A) and tool bag put inside LVL-1 switchgear.</p><p><u><b>Next plan,</b></u></p><p>-N/A</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job progress,</b></u></p><p>-Under monitoring</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-25_Gallery Room,TS refrigerator is not working', '2025-07-25 17:28:01', '2025-07-30 17:39:24', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LQM-GALLEY', 'ZTK-LQM-GALLEY', 'Galley Room', NULL, NULL, 'Galley Room', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
