  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S GDFR point fault cannot reset at AFDS panel', 'Electrical & Instrument', 'CM ', 'Completed', '2025-07-28', '<p><b><u>Activity,</u></b></p>  <p>-T/S GDFR-86506 point fault cannot reset at AFDS panel</p>  <p><b><u>History,</u></b></p>  <p>-Continued from 23 Jul 2025.</p>  <p>-</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-GDFR at LQM roof deck</p>  <p><b><u>As found,</u></b></p>  <p>-Reading 4-20mA current underrange alarm at AFDS panel and yellow light at BN-342/2 power card of GDFR-86506.</p>  <p><b><u>What happen,</u></b></p>  <p>-Wrong termination at GDFR-86506.</p>  <p><b><u>Action,</u></b></p>  <p>-Checked the condition at AFDS panel and found yellow light(fault status) is on at power card of GDFR-86506.</p><p>-Checked power loop at terminal T6 for supply and return power. Found power loop is normal.</p><p>-Checked mA loop power and found there was only 1.053VDC( normal should be 5.75VDC).</p><p>-Checked the termination at the local and found the mA power terminal was wrongly terminated at terminal no.8 and it should be terminal no.9.</p><p>-Removed the wrong termination and installed at correct terminal.</p><p>-Reset the alarm and the alarm was clear.</p>  <p>-</p>  <p><b><u>As left,</u></b></p>  <p>-No alarm at panel for GDFR-86506.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-N/A</p>  <p><b><u>Next plan,</u></b></p>  <p>-N/A</p>  <p><b><u>Documentation,</u></b></p>  <p>-N/A</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-28_GDFR-86506, TS GDFR alarm', '2025-07-28 15:45:39', '2025-07-31 08:04:50', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GDFR-86506', 'ZTK-GDFR-86506', 'Gas Det,Southeast LVL Roof', NULL, NULL, 'Gas Det,Southeast LVL Roof', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
