-- Inserting report ID 36643
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS EDG ESD activated and spurious tripped', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-07-28', '<p><u><b>Activity,</b></u></p><p>-T/S EDG-7200 ESD activated and spurious tripped (Day-3)</p><p><u><b>History,</b></u></p><p>-Continuous job from 19 Jul and 27 Jul.</p><p><u><b>Equipment description and location,</b></u></p><p>-EDG-7200 at lower deck and UCP-7200 for EDG at main deck.</p><p><u><b>As found,</b></u></p><p>-N/A</p><p><u><b>What happen</b>,</u></p><p>-EDG-7200 ESD activated and spurious tripped</p><p><u><b>Action,</b></u></p><p>-Perform thermography scan for EDG-7200 ECP at local control panel.</p><p>- During Energized condition, all relay contactors temperature are around 42''C.&nbsp;</p><p>-Stimulate the Emergency Shutdown signal and remove the cable (E12.7) Rack1/Slot 2 at PLC rack.</p><p>-Result : no alarm signal energized the emergency shutdown for EDG-7200&nbsp; (<b>To verify PLC fault signal</b>)</p><p>-Isolated fuses F-231 &amp; F-232 to cut out&nbsp; 24VDC supply to ECP and replace relays.</p><p>-Replace the old magnetic contactors (K1/K2/K3) SIEMENS SIRIUS *E04* with new type SIEMENS SIRIUS *E06*. (Like to like changes, contact and coil rating are same). -E06 is higher rated durability.&nbsp;</p><p>-Found one terminal loosen K3 magnetic contactor NO contact 23.</p><p>-Check all the cables for re-terminated and tighten the terminals for new magnetic contractors</p><p>-Re-connect the fuse to supply the power for 24 VDC at ECP&nbsp;</p><p>-Clear all the ESD alarm signals and open the fuel &amp; air shut-off&nbsp; valves</p><p>-Perform function test EDG-7200 without load about 15 minutes (<b>running normal</b>)</p><p><u><b>As left,</b></u></p><p>-EDG is available&nbsp;</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-Keep the magnetic contactors as hot spare at workshop (<b>To verify the function</b>)</p><p><u><b>Next plan,</b></u></p><p>-Continuous troubleshoot the ESD alarm activated.</p><p><u><b>Documentation,</b></u></p><p>-N/A</p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-In progress</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-28_EDG-7200_TS EDG-7200 shows Emergency Shutdown activated and spurious tripped">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-07-28_EDG-7200_TS EDG-7200 shows Emergency Shutdown activated and spurious tripped</a><br></p>', '2025-07-28 20:51:36', '2025-07-29 10:42:20', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EDG-7200', 'ZTK-EDG-7200', 'Emergency Diesel Generator Package', NULL, NULL, 'Emergency Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-UCP-CPP-7200', 'ZTK-UCP-CPP-7200', 'Unit Control Panel for EDG PCKG', NULL, NULL, 'Unit Control Panel for EDG PCKG', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EDG-7200-ECP', 'ZTK-EDG-7200-ECP', 'Engine Control Panel for EDG-7200', NULL, NULL, 'Engine Control Panel for EDG-7200', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw', NULL, 'EXTERNAL', '2025-07-28 20:51:36', '2025-07-29 10:42:20', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Brown', NULL, 'EXTERNAL', '2025-07-28 20:51:36', '2025-07-29 10:42:20', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
