-- Inserting report ID 36645
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS LV-48604 is fluctuating at CCR', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-07-29', '<p><b><u>Activity,</u></b></p>  <p>-TS Level Control Valve LV-48604 is fluctuating at CCR.</p>  <p><b><u>History,</u></b></p>  <p>-Continued from 20-Jul-25, 22-Jul-25 and 25-Jul-25.</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Level control valve at glycol unit train 2</p>  <p><b><u>As found,</u></b></p>  <p>-The valve was swinging up and down from the set point.</p>  <p><b><u>What happen,</u></b></p>  <p>-The valve position differs more than 1%.</p>  <p><b><u>Action,</u></b></p>  <p>-Changed PID value to original: P 50, I 4000 l/ds and D 0 l/ds.</p>  <p>-Checked the parameter and condition of LV-47604. Copy parameter from it.</p><p>-Checked the parameter and condition of LV-48604.</p><p>-The valve position was -1.2% when the set point was 0%.&nbsp;</p><p>-Performed travel calibration and tuning calibration. Found the calibration failed.</p><p>-Tried to send the parameter saved from LV-47604 and found the data cannot be received from LV-48604.</p><p>-Performed power recycle at LV-48604 and the GDU train 2 was tripped by level spike high.</p><p>-Found the AO card for LV-48604 has fault due to unit tripped and performed reset at UCP-CPP-4800.</p><p>-Checked the LV condition and performed calibration at zero position with calibration success.&nbsp;</p><p>-The position was -0.5% at 0% command. </p><p>-Performed valve travel check with CCR at 0%, 25%, 50%, 75% and 100%. Found the valve was travelling normal.</p><p>-Changed PID value: P 40, I 1000 l/ds and D 5l/ds. The reading becomes stable at the set point.</p>  <p><b><u>As left,</u></b></p>  <p>-GDU train 2 was running normal.&nbsp;</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-N/A</p>  <p><b><u>Next plan,</u></b></p>  <p>-The valve will be monitor in auto mode.</p><p><span style="background-color: rgb(255, 255, 0);">-To verify with production team fault high trip case whether need to change fault low or not.</span></p>  <p><b><u>Documentation,</u></b></p>  <p>-N/A</p>  <p><b><u>Job progress,</u></b></p>  <p>-90%</p>', NULL, '2025-07-29 13:58:13', '2025-07-30 11:12:17', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LV-48604', 'ZTK-LV-48604', 'LV to Control Level to V-4845', NULL, NULL, 'LV to Control Level to V-4845', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'James', NULL, 'EXTERNAL', '2025-07-29 13:58:13', '2025-07-30 11:12:17', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Supv');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Francis', NULL, 'EXTERNAL', '2025-07-29 13:58:13', '2025-07-30 11:12:17', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Supv');
