-- Inserting report ID 36663
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'P-6651; Reinstate Pump Assembly.', 'Mechanic', 'CM ', 'Completed', '2025-07-31', '<p><b>Description</b>: Reinstate pump assembly. (with the new spare drive gear; genuine part).</p><p><br></p><p><b>Working steps:</b></p><p>-Removed the suction and discharge pipe spool assembly.</p><p>-Removed and taken out the HP shaft assembly. <span style="background-color: rgb(255, 255, 0);">(hard to remove)</span>.</p><p>-Measured the IP shaft end and gear surface. (1.5mm)</p><p>-Measured the coupling gap between motor side and IP shaft. (1/16")</p><p>-Removed the installed fabricated gear drive.</p><p><br></p><p><b>Installation the new gear drive.</b></p><p>-Heat up the gear drive to <span style="background-color: rgb(255, 255, 0);">140 deg C</span>.</p><p>-Aligned and installed the gear to the IP shaft. <span style="background-color: rgb(255, 255, 0);">(with the new key)</span>.</p><p>-Installed oil shroud and slinger plate.</p><p>-Reused the old gear-box housing and gasket and tighten it with <span style="background-color: rgb(255, 255, 0);">torque 30 ft-lb./50N-m</span></p><p>-Installed the overhauled HP shaft assembly.</p><p>-Installed the suction and discharge pipe spool, tighten it with torque <span style="background-color: rgb(255, 255, 0);">52 ft-lb./70N-m</span></p><p>-Replaced the VICTUALIC clamps of suction and discharge with the new one.</p><p>-Installed the cooling tubing and<span style="background-color: rgb(255, 255, 0);"> vinyl tube to the overboard.</span></p><p>-Filled up lube oil (2.5 quart).</p><p>-the unit is ready to be electrical and process de-isolation for test run.</p><p><br></p><p><b>Required spare parts.</b></p><p>-gear box gasket; 42.70.06.032.3</p><p>-Key, drive gear; K1172.</p><p>-Gear, Drive SER20; G1041.</p><p>-suction and discharge VICTAULIC clamps.&nbsp;</p><p>-Lube oil C-treat; 2.5 quarts.</p><p>-Overhauled HP shaft assembly.</p><p>-the cooling line tubing.</p><p><br></p><p><b>Working step: (31-07-2025)</b></p><p>-Performed process and electrical de-isolation.</p><p>-Performed test run and monitored for any abnormal condition.</p><p>-found coolant line tubing leaking and replaced it with the new fabricated tubing.</p><p>-Installed the cooling tubing and coupling guard.</p><p>-Test run again and monitored the temperature.</p><p>-Take vibration data and pump temperature.</p><p><span style="background-color: rgb(0, 255, 0);">-the unit is back to service and running now.</span></p><p><br></p><p><b>Photo in details:&nbsp;</b></p><p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-07-30 Replaced the IP shaft drive gear drive with the Geniue part">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-07-30 Replaced the IP shaft drive gear drive with the Geniue part</a></p><p><br></p><p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-07-31 Test run and monitoring">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-07-31 Test run and monitoring</a><br><b><br></b></p>', '<p>-need to reassembly the removed HP shaft assembly.</p><p>-the new gearbox housing has a small scratch on the seat of HP shaft body.</p>', '2025-07-30 18:20:26', '2025-08-02 06:33:41', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-X-6620', 'ZTK-X-6620', 'Fresh Water Maker 1 Skid', NULL, NULL, 'Fresh Water Maker 1 Skid', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6651', 'ZTK-P-6651', 'Fresh Water High Pressure Pump', NULL, NULL, 'Fresh Water High Pressure Pump', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jason', NULL, 'EXTERNAL', '2025-07-30 18:20:26', '2025-08-02 06:33:41', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Gary', NULL, 'EXTERNAL', '2025-07-30 18:20:26', '2025-08-02 06:33:41', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
