  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify & T/S P-4884 and P-48893 alarms comes.', 'Automation', 'CM ', 'In Progress', '2025-08-03', '<p><b><u>Activity</u>,</b></p><p>-Verify and troubleshoot P-4884 and P-48893 alarms comes when pH pump (P-4784) and Anti-foam pump (P-4788) MCC drawers rack out.</p><p><b><u>History</u>,</b></p><p>- When LTMR firmware upgrade on pH pump (P-4784) and Anti-foam pump (P-4788), CCR received P-8884 and P-4888 alarms. There have only pH pump (P-4784) and Anti-foam pump (P-4788).</p><p><b><u>Equipment description and location</u>,</b></p><p>-ZTK-MMU-P4788: Motor Start Unit for Antifoam Pump Motor</p><div class="ms-sel-item "></div><div class="ms-sel-item ">-ZTK-MMU-P4784: Motor Starter Unit,PH Inject Pump Motor</div><p><b><u>As found</u>,</b></p><p>-There have alarms message configuration and alarm mapping configuration for pH pump (P-4784) and Anti-foam pump (P-4788) in PCS.</p><p>-These alarms signals come from GDU-Train2 package.</p><p>-pH pump (P-4784) and Anti-foam pump (P-4788) are used common units for GDU-Train1 and Train2.</p><p><b><u>What happen</u>,</b></p><p>-N/A</p><p><b><u>Action</u>,</b></p><p>-Verified and checked alarms message configuration in PCS.</p><p>-Verified and checked alarms mapping configuration in PCS.</p><p>-Verified and checked alarms message configuration in GDU-Train2 PLC project files.&nbsp;</p><p>-Verified and checked alarms mapping configuration in GDU-Train2 PLC project files.&nbsp;</p><p><b><u>As left</u>,</b></p><p>-N/A</p><p><b><u>Next plan</u>,</b></p><p>-Edit and delete the graphics for P-4884 and P-4888.</p><p>-Edit and delete the alarm message configuration for P884F_AN (P4884 Motor Fault ALM), XA48853_AN (Ph Buf Injec Pump Fault ALM), P888F_AN (P4888 Motor Fault ALM), XA48893_AN (Antifoam Injection Fault ALM)</p><p><b><u>Documentation</u>,</b></p><p>- N/A</p><p>- Link (G:\\Department Share\\04_MAINTENANCE\\03 E&amp;I\\01 Automation\\01. Picture and Document for History Report\\Hand Over Rev.65 (22 Jul - 19 Aug 25)\\03 Aug 2025_P-4884 and P-4888 alarms)</p><p><u>Job progress</u>,</p><p>- Inprogress</p>', NULL, '2025-08-03 14:45:10', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-MMU-P4784', 'ZTK-MMU-P4784', 'Motor Starter Unit,PH Inject Pump Motor', NULL, NULL, 'Motor Starter Unit,PH Inject Pump Motor', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
