-- Inserting report ID 36701
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S cold store controller alarm.', 'Electrical & Instrument', 'CM ', 'Completed', '2025-08-03', '<p><b><u>Activity</u>,</b></p><p>-TS cold store (ACCU2) cannot control temperature.</p><p><b><u>History</u>,</b></p><p>-Continue from 19-Jun-2025.</p><p><b><u>Equipment description and location</u>,</b></p><p>-ACCU2 freezer cold Store at LQM Level-1.</p><p><b><u>As found</u>,</b></p><p>-ACCU2 freezer controller shows E2 alarm during deforest time.&nbsp;</p><p><b><u>What happen</u>,</b></p><p>-Under investigation.</p><p><b><u>Action</u>,</b></p><p>-Checked the resistance of the defrost and drain pan heaters that are normal condition.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -Defrost Heater no.1:51.1Ohm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -Defrost Heater no.2:52.3Ohm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;-Defrost Heater no.3:50.0Ohm</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-Drain Pan Heater:51.3Ohm&nbsp;</p><p>-Checked the Defrost temperature sensor that is ice block on terminal box(JB-15)</p><p>-Cleaned the ice block and and tightened the sensor after measured resistance of the sensor.</p><p>-Visual check the freezer condition that no ice block.</p><p>-Checked the drain pipe line flex: heater that found insulation damaged.</p><p>-Replaced with new one for drain pipe line flex: heater.(New heater resistance=1.273KOhm)</p><p>-Tested run the ACCU-2 and measured the defrost heater currents that around 5.0A.</p><p><b><u>As left</u>,</b></p><p>-Unit change over to ACCU-2 and under monitoring.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><b><u>Next plan</u>,</b></p><p>-plan to monitor the ACCU-2 with running condition.</p><p><u><b>Documentation,</b></u></p><p>-NA&nbsp;</p><p>-Link ()</p><p><b><u>Job progress</u>,</b></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-08-03_ACCU02, TS cold store controller alarm', '2025-08-03 21:03:46', '2025-09-27 18:49:30', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LQM-COLDST', 'ZTK-LQM-COLDST', 'Cold Store Room LQM', NULL, NULL, 'Cold Store Room LQM', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
