  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Delete graphic, alarm message for P4884 & P4888', 'Automation', 'CM ', 'Completed', '2025-08-04', '<p><b><u>Activity</u>,</b></p><p>-Edit and delete the graphic and alarm message for P-4888 and P-4884.</p><p><b><u>History</u>,</b></p><p>- When LTMR firmware upgrade on pH pump (P-4784) and Anti-foam pump (P-4788), CCR received P-8884 and P-4888 alarms. There have only pH pump (P-4784) and Anti-foam pump (P-4788).</p><p><b><u>Equipment description and location</u>,</b></p><p>-ZTK-MMU-P4788: Motor Start Unit for Antifoam Pump Motor</p><div class="ms-sel-item "></div><div class="ms-sel-item ">-ZTK-MMU-P4784: Motor Starter Unit,PH Inject Pump Motor</div><p><b><u>As found</u>,</b></p><p>-There have alarms message configuration and alarm mapping configuration for pH pump (P-4784) and Anti-foam pump (P-4788) in PCS.</p><p>-These alarms signals come from GDU-Train2 package.</p><p>-pH pump (P-4784) and Anti-foam pump (P-4788) are used common units for GDU-Train1 and Train2.</p><p><b><u>What happen</u>,</b></p><p>-N/A</p><p><u>Action</u>,</p><p>-Edit and delete the graphics for P-4884 and P-4888 in GH1102 page.</p><p>-Performed download the graphics for all stations.</p><p>-Edit and delete the alarm message configuration in FCS0102, DR0097 for P884F_AN (P4884 Motor Fault ALM), XA48853_AN (Ph Buf Injec Pump Fault ALM), P888F_AN (P4888 Motor Fault ALM), XA48893_AN (Antifoam Injection Fault ALM).</p><p>-Performed online download for FCS0102, DR0097.</p><p>-Performed function test and CCR received the alarms as per the drawers rack out.</p><p><b><u>As left</u>,</b></p><p>-Now the alarms show as per the drawers rack out.</p><p><b><u>Next plan</u>,</b></p><p>NA</p><p><b><u>Documentation</u>,</b></p><p>- N/A</p><p>- Link (G:\\Department Share\\04_MAINTENANCE\\03 E&amp;I\\01 Automation\\01. Picture and Document for History Report\\Hand Over Rev.65 (22 Jul - 19 Aug 25)\\04 Aug 2025_Delete alarm message configuration for P4884 and P4888)</p><p><b><u>Job progress</u>,</b></p><p>- Inprogress</p>', NULL, '2025-08-04 15:45:37', '2025-08-04 16:49:56', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
