  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace new helium cylinder No.1 at OGC', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-08-07', '<p><b><u>Activity</u>,</b></p><p>-Replace helium cylinder No.01 at OGC skid</p><p><u>History</u>,<br class="Apple-interchange-newline"></p><p>-N/A</p><p><u>Equipment description and location</u>,</p><p>-AE-46001- GC analyzer skid, Cooler Deck&nbsp;&nbsp;</p><p><u>As found</u>,</p><p>-Helium cylinder No.01 is empty.</p><p><u>What happen</u>,</p><p>-N/A</p><p><u>Action</u>,</p><p>-Isolate the valve of the empty cylinder</p><p>-Isolate the valve No.2 Helium gas supply to GC</p><p>-Turn around the pressure regulator counter-clock wise direction&nbsp;</p><p>-Open the vent valve No.1 and depressurized the trapped pressure</p><p>-Remove the tubing fitting and pressure regulator&nbsp;</p><p>-Replace with new helium cylinder from spare rack</p><p>-Connect the tubing fitting and pressure regulator&nbsp;</p><p>-Close the vent valve and open the new cylinder&nbsp;</p><p>-Perform check leak test for the cylinder side</p><p>-Open vent valve No.1 and&nbsp;purging&nbsp;the moisture inside</p><p>-Adjust the required pressure 105 psi with vent valve open position</p><p>-Close the vent valve No.1 and leak test again</p><p>-De-isolate the valve No.2 and cylinder No.01 helium gas supply to GC</p><p>-Keep monitor the pressure stable and final leak test&nbsp; &nbsp; &nbsp;&nbsp;</p><p><u>As left</u>,</p><p>-Helium cylinder No.01= 2100 psi / 105 psi (Lag)</p><p>-Helium cylinder No.02= 2200 psi / 110 psi (Lead)</p><p><u>Next plan</u>,</p><p>-N/A</p><p><u>Documentation</u>,<br class="Apple-interchange-newline"></p><p>-N/A</p><p><u>Job progress</u>,</p><p>- 100% job completed.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-08-07_AE46001_Replace empty helium cylinder No.1">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-08-07_AE46001_Replace empty helium cylinder No.1</a><br></p>', '2025-08-07 15:38:20', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-AE-46001', 'ZTK-AE-46001', 'GC Aanlyzer Element,M-4600,CH,CO2,N2', NULL, NULL, 'GC Aanlyzer Element,M-4600,CH,CO2,N2', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
