  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify the logic of LV-48604, LV-47604 in HIMA PLC', 'Automation', 'OTH ', 'Completed', '2025-08-08', '<p><u><b>Activity,</b></u></p><p>-Online GDU Train1 and GDU Train 2 HIMA PLC and verify the logic of LV-48604 and LV-47604 in HIMA PLC.</p><p><u><b>History,</b></u></p><p>-TS Level Control Valve LV-48604 is fluctuating at CCR.</p><p>-Continued from 20-Jul-25, 22-Jul-25 and 25-Jul-25.</p><p><u><b>Equipment description and location,</b></u></p><p>-Level control valve at glycol unit train 2</p><p><u><b>As found,</b></u></p><p>- LIC-47604 and LIC-48604 configurations are same except the manual input PID turning parameters from HMI are different.&nbsp;</p><p>LIC-47604: P=50, I=20000, D=0 (The manual input PID turning parameters from HMI)</p><p>LIC-48604: P=40, I=1000, D=5 (The manual input PID turning parameters from HMI)</p><p><u><b>What happen,</b></u></p><p>-The valve position differs more than 1%.</p><p><u>Action,</u></p><p>-Perform online monitoring LIC-47604 and LIC-48604 configurations and parameters.</p><p>-Took the records and compare the configurations and parameters between LIC-47604 and LIC-48604.</p><p><u><b>As left,</b></u></p><p>-GDU train 1 and 2 are running normal.&nbsp;</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><u><b>Next plan,</b></u></p><p>-NA.</p><p><u><b>Documentation,</b></u></p><p>-N/A</p><p>-Link(G:\\Department Share\\04_MAINTENANCE\\03 E&amp;I\\01 Automation\\01. Picture and Document for History Report\\Hand Over Rev.65 (22 Jul - 19 Aug 25)\\08 Aug 2025_LIC48604 and LIC47604)</p><p><u><b>Job progress,</b></u></p><p>-100%</p>', NULL, '2025-08-08 16:03:25', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
