-- Inserting report ID 36745
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS NDE barrier fluid level drop', 'Mechanic', 'CM ', 'In Progress', '2025-08-08', '<p>Problem:&nbsp;</p><p>NDE barrier fluid level drop during running.</p><p><br></p><p>Action:</p><p>Barrier fluid - Castrol Hyspin Spindle oil ep5</p><p>Bearing oil - PTT Hydraulic 32</p><p><br></p><p>Drain all the barrier fluid from NDE side about 18L.</p><p>Drain all the barrier fluid from DE side about 18L.</p><p>Flush with the new oil for both NDE and DE barrier fluid port.</p><p>Remove the mech seal cover guard for both NDE and DE side.</p><p>Check the area and no abnormal found.</p><p>Removed the tubing line of Mech seal and flush with air and new oil for both side.(No abnormal particles in the seal chamber).</p><p>Drain the bearing lube oil of NDE and DE side.</p><p>Removed the refill cap and level gauge, clean all parts.</p><p>Refill new Hydraulic 32 for both side, 2 L for each side.</p><p>Installed back all the accessories.</p><p>Refill the new barrier fluid Castrol Hyspin Spindle oil ep5 to NDE side about 14 L, level around 50%.</p><p>Refill the new barrier fluid Castrol Hyspin Spindle oil ep5 to DE side about 14 L, level around 50%.</p><p>Process deisolate and line up for test run, both NDE and DE level drop to about 40% after line up.</p><p>Test Run and found NDE side barrier fluid level drop to 30 from 40 within 10 minutes.</p><p>DE side barrier fluid level stable a 40%.</p><p><br></p><p>Refill the both side barrier fluid to 80%.</p><p>Production team can perform sand jetting pump running activity and monitor for further process.</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\61 PRODUCED WATER\\P- 6180\\2025\\2025-08-08 TS NDE seal port level drop">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\61 PRODUCED WATER\\P- 6180\\2025\\2025-08-08 TS NDE seal port level drop</a><br></p>', '2025-08-08 18:47:03', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6180-SKID', 'ZTK-P-6180-SKID', 'Permanent Sand Jetting Pump Skid', NULL, NULL, 'Permanent Sand Jetting Pump Skid', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Leo', NULL, 'EXTERNAL', '2025-08-08 18:47:03', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kaung. Tom', NULL, 'EXTERNAL', '2025-08-08 18:47:03', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
END $$;

