  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS DGS primary vent creeping up', 'Mechanic', 'CM ', 'Completed', '2025-08-09', '<p>Problem -&nbsp;DGS primary vent creeping up</p><p><br></p><p>Action - 1) Drain primary seal gas supply ( DE/NDE ).</p><p>Found -&nbsp; &nbsp; &nbsp; Small amount of liquid with particles.</p><p>Action - 2) Disconnect seal gas supply drain line ( DE/NDE ) and Performed borescope inspection.</p><p>Action - 3) Drain primary vent line ( DE/NDE ).</p><p>Found-&nbsp; &nbsp; &nbsp; &nbsp;Liquid with black particles. (25ML)</p><p>Action-&nbsp; 4)&nbsp; Verify restriction at outlet of primary vent and adjacent piping, 3" check valve (VC-122) and Orifice FE44208A/B&nbsp; and Perform borescope inspection.</p><p>Found -&nbsp; &nbsp; &nbsp; &nbsp; Some particles like salts.</p><p>Action-&nbsp; 5)&nbsp; Swap inlet seal gas filter and drain liquid and inspect filter condition&nbsp; </p><p>Found-&nbsp; &nbsp; &nbsp; nothing anormal found and replaced new filter with new oring.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', NULL, '2025-08-09 16:13:15', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Turbi', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
