  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S LSS axial displacement A  abnormal high alarm', 'Electrical & Instrument', 'CM ', 'Completed', '2025-08-09', '<p><b><u>Activity</u>,</b></p><p>-T/S ZT-44204A LSS axial displacement A&nbsp; abnormal high alarm RANK MAGG gearbox axial displacement</p><p><b><u>History</u>,</b></p><p>-6 Aug 2025: ZE-44204A&nbsp;LSS MAAG Gear abnormal high alarm&nbsp; since 03:48 AM and fluctuating abnormally (High Alarm time to time).</p><p><b><u>Equipment description and location</u>,</b></p><p>-ZE-44204A LSS RANK MAAG Gearbox of GTC-4400, Upper Deck</p><p><b><u>As found</u>,</b></p><p>-ZE-44204A&nbsp;LSS MAAG Gear reading abnormal.</p><p><b><u>What happen</u>,</b></p><p>-During the unit running,&nbsp;LSS axial displacement A&nbsp; abnormal high alarm time to time. (High Alarm Setpoint - 0.689mm/ High High Alarm Setpoint - 0.896mm)</p><p><b><u>Action</u>,</b></p><p>-Stopped the unit to replace the new sensor probe, vibration proximitor and extension.</p><p>-Checked the parameters of the old sensor probe as below;</p><p>-V-PS (1) &amp; V-XDR (2) = -5.8 VDC (displacement 0.55 mm), V-Sig (3) = -25.08 VDC and R-total 9.0 Ohm.</p><p>-Replace new vibration probe, new extension and proximitor.</p><p>-Measured the new sensor parameters after installation as below;</p><p>-V-Sig (3) = -25.08 VDC and R-total 9.0 Ohm.</p><p>-Adjust the gap voltage to -9.0 VDC (displacement 0.114 mm)</p><p><b><u>As left</u>,</b></p><p>-ZE-44204A LSS MAAG Gear reading back to normal.</p><p><b><u>Next plan</u>,</b></p><p>-NA</p><p><b><u>Documentation</u>,</b></p><p>-Link ()</p><p><b><u>Job progress</u>,</b></p><p>-100%</p>', NULL, '2025-08-09 16:31:32', '2025-08-09 18:08:45', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-ZT-44204A', 'ZTK-ZT-44204A', 'VT,GB LO SPD NDE Axial,ALM HI/SD HH', NULL, NULL, 'VT,GB LO SPD NDE Axial,ALM HI/SD HH', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
