  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Performance check DE-NDE Compressor seal vent PCV', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-08-10', '<p><b><u>Activity,</u></b></p>  <p>-Checked the performance of DE and NDE Compressor seal vent pressure control valve PCV-44211A/B (removed from GTC-4400)&nbsp; at EI Workshop.</p>  <p><b><u>History,</u></b></p>  <p>-Replaced PCVs PCV-44211A/B&nbsp;at GTC-4400 due to the seal gas vent pressure creeping up.</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Pressure control valve of seal gas primary vent DE &amp; NDE</p>  <p><b><u>As found,</u></b></p>  <p>-NA</p>  <p><b><u>What happen,</u></b></p>  <p>-NA</p>  <p><b><u>Action,</u></b></p>  <p>-Checked the set pressure of both PCVs.</p><p>-Found that the pressure set point of PCV-44211A (NDE) is 4.22 Psi and PCV-44211B is 3.9 Psi.</p>  <p>-Found there was no leak at both PCVs.</p><p>-Posted the sticker on both PCVs.</p>  <p><b><u>As left,</u></b></p>  <p>-Will keep as hot spares.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-NA</p>  <p><b><u>Next plan,</u></b></p>  <p>-For PCV-44211A (NDE), need to clean and paint the valve body.</p><p>-For both, need to adjust the set pressure to the document setpoint4.9 Psi (0.34 bar).</p>  <p><b><u>Documentation,</u></b></p>  <p>-NA</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-50%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-08-09_PCV-44211A,B, Function PCV for seal gas primary vent', '2025-08-10 16:03:26', '2025-08-16 11:22:59', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PCV-44211A', 'ZTK-PCV-44211A', 'Press Regulator,Seal Gas Pri Vent Nde', NULL, NULL, 'Press Regulator,Seal Gas Pri Vent Nde', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
