  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot pressure cannot build up', 'Mechanic', 'CM ', 'Completed', '2025-08-13', '<p>Problem: Pressure cannot build up during running.</p><p><br></p><p>Found: Lube oil seeping around the adjustor stroke.</p><p><br></p><p>Action:</p><p>- Drained the lube oil CPL 100.</p><p>- Removed the adjustor stroke.</p><p>- Replaced lip seal at the adjusting stroke.</p><p>- Reinstalled back the adjustor stroke and set zero.</p><p>- Removed and checked suction and discharge check-valve.&nbsp;</p><p>- Found Biocide solid deposit stuck at the suction ball valve, the small ball is stuck and not running, back&nbsp; to normal after clean and exercise.</p><p>- Clean and re-install the check-valves.</p><p>- Removed and Cleaned the strainer from the suction inlet line, found strainer is deformed and block, reformed the strainer and clean.</p><p>-Top Up lube oil CPL 100 about 1.5L.</p><p>-Test run with satisfied.&nbsp; &nbsp;</p><p><b>Adjusted Final Parameters</b></p><p>- Discharge Pressure - 2.8 to 3 bar</p><p>- Discharge Flow&nbsp; &nbsp; &nbsp; &nbsp; - 3.7 L/H</p>', '\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ&nbsp; MECH&nbsp; HISTORY PICTURE\\01 ZPQ\\69 CHEMICAL INJECTION\\P-6920B\\2025-8-13 TS no discharge pressure', '2025-08-13 17:53:23', '2025-08-13 18:12:18', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
