-- Inserting report ID 36832
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS choke valve passing ZTK-HCV-08K04', 'Mechanic', 'CM ', 'Completed', '2025-08-15', '<p>Problem: TS choke valve is passing</p><p><br></p><p>Action : </p><p><br></p><p>-Prepare tools and lifting equipment to remove choke v/v</p><p>-Depressurize the choke valve vent plug from body trap pressure (by 3/4 spanner)</p><p>- Loosen the bonnet cap 8 bolt with 55 mm and hammer wrench</p><p>- Lift the actuator together with the v/v stem and bonnet cap with chain block. <span style="background-color: rgb(255, 255, 0);">(cause of Allen bolts attached </span>&nbsp;&nbsp;&nbsp;&nbsp;<span style="background-color: rgb(255, 255, 0);">t</span><span style="background-color: rgb(255, 255, 0);">o actuator and bonnet are seriously corroded)</span></p><p>- Left two bolts as safety barrier for any trap pressure</p><p>- Lift the actuator and bonnet&nbsp;</p><p>- Remove seal and trim kit <span style="background-color: rgb(255, 255, 0);">(found sand erosion and O-ring were damage)</span>&nbsp;</p><p>- Clean &amp; check the valve body inside <span style="background-color: rgb(255, 255, 0);">(OK)&nbsp;</span></p><p>- Replace the new trim kit and seal kit <span style="background-color: rgb(255, 255, 0);">(except the stem packing)</span></p><p>- Install back inside of valve body</p><p>- Install back bonnet and actuator</p><p>- Retighten the valve body vent plug</p><p>- Tighten the bonnet bolt with 80Nm,170Nm,260Nm,300Nm with 4 time multiplier</p><p>- Pressure test and passing test with <span style="background-color: rgb(255, 255, 0);">60 bar</span>,<span style="background-color: rgb(255, 255, 0);"> found no leak.</span></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP8\\Choke Valve\\HCV-08K04\\2025\\2025-08-15 TS Choke Valve passing">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP8\\Choke Valve\\HCV-08K04\\2025\\2025-08-15 TS Choke Valve passing</a><br></p>', '2025-08-16 08:00:12', '2025-08-17 17:27:07', 'PTTEP\\ZPQ.Cmms-Tech', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP08', 'ZTK-WP08', 'Zawtika Wellhead Platform 08', NULL, NULL, 'Zawtika Wellhead Platform 08', 'WP08', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-HCV-08K04', 'ZTK-HCV-08K04', 'Valve Choke on 6''''GC08K01-J70 for Well K', NULL, NULL, 'Valve Choke on 6''''GC08K01-J70 for Well K', 'WP08', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Leo', NULL, 'EXTERNAL', '2025-08-16 08:00:12', '2025-08-17 17:27:07', 'PTTEP\\ZPQ.Cmms-Tech', 'PTTEP\\ZPQ.Mechanical-Works');
