-- Inserting report ID 36833
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS pressure switch low alarm come time to time', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-08-16', '<p><b><u>Activity</u>,</b></p><table border="0" cellspacing="0" cellpadding="0" width="2111"><tbody><tr><td width="490"><p>-TS&nbsp;PS-65101 pressure low alarm come time to time.</p></td></tr></tbody></table><p><b><u>History</u>, (13 Aug 2025)</b></p><p>-Replaced new micro switch and test run the unit and monitor the pressure switch alarm.</p><p>-Found low alarm still come on air dryer regeneration cycle.</p><p>(Note: Suspected Micro switch activated arm and mechanism are malfunction)</p><p><b><u>Equipment description and location</u>,</b></p><p>-Instrument Air Dryer Skid, Mezzanine deck</p><p><b><u>As found</u>,</b></p><p>-Pressure switch low alarm come time to time. (during operation)</p><p><b><u>What happen</u>,</b></p><p>-Micro switch activated arm and mechanism were malfunction and cannot be adjusted.</p><p><b><u>Action</u>,</b></p><p>-Verified the switch mechanism at Workshop and found it cannot be adjusted to set point.</p><p>-Prepared new pressure switch and adjusted set point Low/High with hand pump.</p><p>-Checked the microswitch contacts are working properly.</p><p>-High pressure set point PSH-65101 is 3.1 bar, reset = 2.5 bar.</p><p>-Low pressure set point PSL-65101 is 0.68 bar, reset = 1.2 bar,</p><p>-Re-installed new pressure switch at site and perform function test for Low and High Alarm with Hand pump at Local HMI.</p><p>-Normalized the pressure switch and the sensing tubing.</p><p>-Deisolation process and function test run.</p><p>-The unit can run properly and no any abnormal pressure switch alarm.</p><p><b><u>As left</u>,</b></p><p>-Low pressure switch PS-65101 back to normal.</p><p><b><u>Next plan</u>,</b></p><p>-NA</p><p><b><u>Documentation</u>,</b></p><p>-NA</p><p>-Link ()</p><p><b><u>Job progress</u>,</b></p><p>-Under Monitoring</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-08-16_PSL-65101_TS Pressure switch Low alarm time to time', '2025-08-16 15:40:24', '2025-08-17 09:59:34', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PS-65101', 'ZTK-PS-65101', 'Press SW on Air Dryer Tank A,AL HI-LO', NULL, NULL, 'Press SW on Air Dryer Tank A,AL HI-LO', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
