-- Inserting report ID 36839
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '-T/S barrier fluid level drop', 'Mechanic', 'CM ', 'In Progress', '2025-08-16', '<div><b>T/S barrier fluid level drop</b></div><div><br></div><div><u>Action</u></div><div><u><br></u></div><div>-Process and electrical isolation</div><div>-Removed the coupling and guard</div><div>-Drain all the bearing oil (<span style="background-color: rgb(255, 255, 0);">NDE</span>)&nbsp;</div><div>-Removed shaft end cover (<span style="background-color: rgb(255, 255, 0);">NDE</span>)</div><div>-Install dial gauge to measure shaft clearance</div><div>-Release the seal retaining ring&nbsp;</div><div>-Lock the mech seal to prevent axial movement</div><div>-Apply some lever force from shaft </div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style="background-color: rgb(255, 255, 0);">&nbsp;DE to NDE&nbsp; movement is 0.27mm</span></div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;<span style="background-color: rgb(255, 255, 0);">NDE to DE&nbsp; movement is 0.1 mm</span></div><div><br></div><div>-Relocate shaft position to 0 mm reading in dial gauge</div><div>-Reinstall the coupling and shaft end cover&nbsp;<span style="background-color: rgb(255, 255, 0);">(NDE)</span></div><div>-Fill bearing oil (~ 2 Liter)</div><div>-Deisolate and test run the pump</div><div><br></div><div>-Before running barrier fluid level is <span style="background-color: rgb(255, 255, 0);">60 %</span></div><div>-After running <span style="background-color: rgb(255, 255, 0);">30mins</span> barrier fluid level&nbsp; <span style="background-color: rgb(255, 255, 0);">57% (very less amount&nbsp; and found the improvement)</span></div><div><br></div><div>&nbsp;<span style="background-color: rgb(255, 255, 0);">Tonight Production team will run again to test level drop for long time running.</span></div><div>&nbsp;</div>', NULL, '2025-08-16 17:54:42', '2025-08-16 18:27:57', 'PTTEP\\ZPQ.Mechanical-TeamL', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6180', 'ZTK-P-6180', 'Permanent Sand Jetting Pump', NULL, NULL, 'Permanent Sand Jetting Pump', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
