-- Inserting report ID 36875
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS belt shaking', 'Mechanic', 'CM ', 'Completed', '2025-08-20', '<p>Problem - Belt is shaking.&nbsp;</p><p>Found&nbsp; &nbsp; - Fan belt is loosen.&nbsp;</p><p>Action&nbsp; &nbsp; - Checked belt tension and alignment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; As found tension ( 22Hz)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; As found alignment is aligned.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked both bearings, upper and lower.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked vibration prob at upper bearings.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Performed tension (25.6Hz).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Test run the unit for 2 hours.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Stop the unit and re-tighten tension.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Test run with satisfied.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\42 GAS COMPRESSOR T 1\\GAS COOLER\\E-4260 (2nd Stage)\\E-4260B\\2025\\2025-08-20 TS belt shake">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\42 GAS COMPRESSOR T 1\\GAS COOLER\\E-4260 (2nd Stage)\\E-4260B\\2025\\2025-08-20 TS belt shake</a><br></p>', '2025-08-20 15:30:04', '2025-08-20 17:01:13', 'PTTEP\\ZPQ.Cmms-Tech', 'PTTEP\\ZPQ.Cmms-Tech', false, 'ZTK') RETURNING id INTO new_report_id;
