-- Inserting report ID 36881
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Check parameter for seal gas heater temp controlle', 'Electrical & Instrument', 'OTH ', 'In Progress', '2025-08-20', '<p><b><u>Activity,</u></b></p>  <p>-Checked and collected the parameters of seal gas heater temp controller.</p>  <p><b><u>History,</u></b></p>  <p>-Cannot control from CCR.</p>  <p>-</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Local control panel for seal gas heater No.1, Upper Deck</p>  <p><b><u>As found,</u></b></p>  <p>-Temperature cannot go up over 100 deg C.</p>  <p><b><u>What happen,</u></b></p>  <p>-NA</p>  <p><b><u>Action,</u></b></p>  <p>-Checked the parameter of the temp controller and found that there is no "Digital Input/Output Menu" from set up page. So we cannot check the parameter for the output from controller.&nbsp;</p>  <p>-The range command from PCS is 4-20mA (1-200 Deg C). (From controller parameter)</p><p>-The range of output signal to PCS is also 4-20mA (1-200 Deg C). (By measuring the output mA).</p><p>-Changed the calibration offset value for process input RTD (TE-42213A) (AI01) from -3 to 0.</p><p>-Observed that the temp value is stable around 100 DegC. Cannot go up and down as per command.</p><p>-Simulated the process temp to 60 degC and set value from CCR keep at 100 deg C.</p><p>-Check the output from controller and found that no output to SSR 1 and 2 to energized the heating elements.</p>  <p><b><u>As left,</u></b></p>  <p>-Set value is 100 Deg C and process value is around 100 Deg C.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-NA</p>  <p><b><u>Next plan,</u></b></p>  <p>-Need to troubleshoot for the temp controller no output issue.</p>  <p><b><u>Documentation,</u></b></p>  <p>-NA</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-50%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-08-20_SK-4205 Checked the parameter of temp controller for Seal Gas Heater', '2025-08-20 18:55:49', '2025-08-20 19:15:41', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SK-4205', 'ZTK-SK-4205', 'Seal Gas Conditioning Skid', NULL, NULL, 'Seal Gas Conditioning Skid', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LCP-CPP-4225A', 'ZTK-LCP-CPP-4225A', 'Local Panel for Gas Seal Heater No.1', NULL, NULL, 'Local Panel for Gas Seal Heater No.1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
