-- Inserting report ID 36896
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS heat tracing system for GTC train 1', 'Electrical & Instrument', 'CM ', 'Completed', '2025-08-22', '<p><u><b>Activity,</b></u></p><p>-To troubleshoot heat tracing for seal gas supply of GTC train 1, main deck and upper deck.</p><p><u><b>History,&nbsp;</b></u>-<b><u>06 August 2025</u></b></p><p>-GTC-4200, Heat tracing element temp is 51.4 degC and piping temp 51.4 degC.(Abnormal)</p><p>-GTC-4300, Heat tracing element temp is 63.1 degC and piping temp 66.1 degC.</p><p>-GTC-4400, Heat tracing element temp is 67.4 degC and piping temp 65.4 degC.</p><p>-ACDP-CPP-201, Found GTC-4200, Heater pilot lamp is not ON and C23 magnetic contactor not energize.</p><p><u><b>Equipment description and location,</b></u></p><p>-Electrical heat tracing for GTC train 1, Main Deck and Upper Deck</p><p><u><b>As found,</b></u></p><p>-No pilot light ON for heat tracing of seal gas supply for GTC train 1</p><p><u><b>What happen,</b></u></p><p>-The heat tracing cables are loosen and the insulation are not properly covered.</p><p>-The temperature thermostat setting for GTC train 1 is lower than GTC train 2 and 3.</p><p><u><b>Action,</b></u></p><p>-Performed checking to heat tracing cables for seal gas supply skid for GTC train 1 at ACDB-CPP-201.</p><p>-Found that no MCB, RCCB and contactor trip.</p><p>-Measured the incoming and outgoing power voltage of MCB, RCCB and contactor &gt;OK</p><p>-Found that the pilot light is damaged. Replaced and the pilot light is ON. </p><p>&nbsp;&nbsp;&nbsp;&nbsp;<i>(Note: no spare for exactly same, install the identical 230V pilot light)</i></p><p>-Checked all the heat tracing cable at local in upper deck.</p><p>-Measured the temperature of the heat tracing cables and piping. (temperature of heat tracing cables are mostly same but the temperature of piping are different)</p><p>-Found that the heat tracing cables are loosen and insulation are not properly covered.</p><p>-Properly bundled all heat tracing cables and insulation cover for Seal Gas skids for all GTCs.</p><p>-Checked the thermostat control system for all GTCs at local.&nbsp;</p><p>-Found that the thermostat setting for GTC train 1 is a bit lower around 75 deg C than train 2 and 3 set point 80 degC. </p><p>&nbsp;&nbsp;&nbsp;&nbsp;<i>(Note: Thermostat setting n the applied sticker description at ACDB panel is 65 degree for all.)</i></p><p>-Adjusted same with train 2 and train 3 set point around 80 degC.</p><p>-Keep under monitoring for two hours and found that the heat tracing for seal gas of GTC train 1 working normal.</p><p><u><b>As left,</b></u></p><p>-Heat tracing for seal gas of GTC train 1 is back to normal.</p><p>-Now pilot light ON at ACDB-CPP-201.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><u><b>Next plan,</b></u></p><p>-N/A</p><p><u><b>Documentation,</b></u></p><p>-N/A</p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-100%</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-08-22_ZTK-GTC-4200, Heat Tracing Cable, TS abnormal heat tracing temperature for seal gas system">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-08-22_ZTK-GTC-4200, Heat Tracing Cable, TS abnormal heat tracing temperature for seal gas system</a><br></p>', '2025-08-22 15:52:14', '2025-08-23 13:30:18', 'PTTEP\\ZPQ.Cmms-Tech', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-ACDB-CPP-201', 'ZTK-ACDB-CPP-201', 'Heat Tracing Dist Board on MSWG Room', NULL, NULL, 'Heat Tracing Dist Board on MSWG Room', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4200-SGS', 'ZTK-GTC-4200-SGS', 'Gas Seal Supply for C-4220/C-4250', NULL, NULL, 'Gas Seal Supply for C-4220/C-4250', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Herbert', NULL, 'EXTERNAL', '2025-08-22 15:52:14', '2025-08-23 13:30:18', 'PTTEP\\ZPQ.Cmms-Tech', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Benjamin', NULL, 'EXTERNAL', '2025-08-22 15:52:14', '2025-08-23 13:30:18', 'PTTEP\\ZPQ.Cmms-Tech', 'PTTEP\\ZPQ.EI-Workshop');
