-- Inserting report ID 36897
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To replace motor bearing of P-4810B', 'Electrical & Instrument', 'CM ', 'Completed', '2025-08-22', '<p><u>Activity,</u></p><p>-To replace motor bearing of glycol circulation pump, P-4810B.</p><p><u>History,</u></p><p>-Continue from 21-08-2025</p><p><u>Equipment description and location,</u></p><p>-Glycol circulation pump, P-4810B and upper deck.</p><p><u>As found,</u></p><p>-Motor abnormal noise.</p><p>-Found Corrosion at DE &amp; NDE inner surface of the motor housing.</p><p>-Winding insulation resistance: &gt;550Mohm&nbsp;</p><p>-Winding resistance: 0.2ohm</p><p>-Space Heater: Coil resistance_453.2ohm, Insulation Resistance_&gt;220Mohm.</p><p>-Motor model: AB30250ML4B3-3F&nbsp;</p><p><u>What happen,</u></p><p>-Aging</p><p><u>Action,</u></p><p>-Measured the insulation resistance and winding resistance of the motor and space heater; the results were the same as those found previously.</p><p>-Cleaned and repainted the inside of the fan cowl.</p><p>-Assisted the mechanical team with aligning the motor and pump coupling installation.</p><p>-Performed a test run of the unit. The average current was 35.4A, while the nameplate rating was 97.0A.</p><p>-No abnormalities were found during the running time.</p><p><u>As left,</u></p><p>-The unit is online and operating under normal conditions.</p><p><u>Material/Equipment/Tool status,</u></p><p>-N/A</p><p><u>Next plan,</u></p><p>-N/A</p><p><u>Documentation,</u></p><p>-N/A</p><p>-Link (G:\\Department Share\\04_MAINTENANCE\\03 E&amp;I\\08 PM&amp;CM&amp;Log Sheets Report\\02 CM Calibration Sheets\\GDU CM record)</p><p><u>Job progress,</u></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-08-22_P-4810B, To replace the motor bearing', '2025-08-22 15:52:44', '2025-08-22 18:40:14', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-4810B-ASSY', 'ZTK-P-4810B-ASSY', 'Glycol Circulation Pump Assembly Train2B', NULL, NULL, 'Glycol Circulation Pump Assembly Train2B', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
