  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS pneumatic damper not open', 'Electrical & Instrument', 'CM ', 'Completed', '2025-08-23', '<p><b>Activity,</b></p><p>-TS pneumatic damper (fresh air supply line) HPD-86108 not open, HPD-86108, LQM Lvl 1.</p><p><b>History,</b></p><p>-NA</p><p><b>Equipment description and location,</b></p><p>-LQM Fresh Air Supply Duct, LQM Level 1.</p><p><b>As found,</b></p><p>-Pneumatic damper closed and can''t run the B-8745B.</p><p>-HPD''s actuator was stuck when opening.</p><p><b>What happen,</b></p><p>-The damper is not able to open.</p><p><b>Action,</b></p><p>-Performed changeover the blower unit, B-8745 from A to B.</p><p>-Checked if the pneumatic damper can be opened or not. (Not open).</p><p>-Found that the blower unit, B-8745B unit tripped.</p><p>-Checked the solenoid instrument supply and discharge. (OK)</p><p>-Checked the solenoid coil resistance. (OK)</p><p>-Found HPD''s actuator was stuck when opening.</p><p>-Performed manual exercise to the pneumatic damper actuator. (OK)</p><p>-Adjusted the proximity switches for open and close to position.</p><p>-Checked the wiring for blower unit B in MCC-LQM-8670B. (OK)</p><p>-Performed the blower unit test run<b>, </b>B-8745B is running and HPD-86108 is open<b>.</b></p><p><b>As left,</b></p><p>-B-8745B is running properly.</p><p>-B-8745A is standby and B-8745B is duty.</p><p>-HPD-86108 is back to service.</p><p><b>Next Plan,</b></p><p>-If this issue happen again, will replace the actuator for pneumatic damper, HPD-86108.</p><p><b>Documentation,</b></p><p>-NA</p><p><b>Job Progress,</b></p><p>-Completed.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-08-23_HPD-86108, TS pneumatic damper not open">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-08-23_HPD-86108, TS pneumatic damper not open</a><br></p>', '2025-08-23 16:01:03', '2025-08-23 17:17:19', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-B-8745A-ASSY', 'ZTK-B-8745A-ASSY', 'Galley Supply Fan Duty Unit Assembly', NULL, NULL, 'Galley Supply Fan Duty Unit Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
