  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S air compressor tripped by temp high alarm', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-08-25', '<p><u><b>Activity,</b></u></p><p>-T/S air compressor tripped by temp high alarm</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-Air Compressor C, Main Deck</p><p><u><b>As found,</b></u></p><p>- Air Compressor C unit tripped.</p><p><u><b>What happen,</b></u></p><p>-During test running the compressor C, found that HP Compressor Discharge Temp (TT-65002C) was going to high high alarm that happened to unit trip.</p><p><u><b>Action,</b></u></p><p>-Visual inspected and checked the condition of transmitter is in good condition.</p><p>-Measured the resistance of temp element and found 90.8 Ohm</p><p>-Removed the temp element and found the element tip was slightly bent.&nbsp;</p><p>-Suspected that caused the sensor was malfunction and reading spike high during start up the compressor.</p><p>-Replaced with new spare PT100 RTD sensor with same range resistance&nbsp; about 110.3 Ohm.</p><p>-Performed function loop test for the temperature transmitter and it functioned properly. (Cal Range 0 to 300 DegC).</p><p>-Normalized the unit and function test run with site operator and CCR.</p><p>-The unit is running normal with no any abnormal alarm.</p><p><u><b>As left,</b></u></p><p>-Alarm cleared and A-6500C is back to service.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-Bring the old temp sensor at EI Workshop to check function.</p><p><u><b>Next Plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p>-Link</p><p><u><b>Job Progress,</b></u></p><p>-100%</p><p><br></p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-08-25_TT- 65002C_TS temp high high trip', '2025-08-25 14:40:17', '2025-08-25 18:10:55', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-6500C', 'ZTK-A-6500C', 'Air Compressor No.3 Packages', NULL, NULL, 'Air Compressor No.3 Packages', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-TT-65002C', 'ZTK-TT-65002C', 'TT on C-6501C Disch Line,AL HI & SD HH', NULL, NULL, 'TT on C-6501C Disch Line,AL HI & SD HH', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
