-- Inserting report ID 36925
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform mechanical seal replacement (NDE side)', 'Mechanic', 'CM ', 'Completed', '2025-08-29', '<p>Task:&nbsp;&nbsp; &nbsp; : Perform Mechanical Seal Replacement</p><p><u><br></u></p><p><u><b style="background-color: rgb(255, 255, 0);">29-08-2025</b></u></p><p>Problem: </p><p>Found oil seeping from NDE side bearing housing and breather.</p><p>Abnormal noise around the NDE side.</p><p><br></p><p>Action:</p><p>Found breather is aging and since it is short in height, the oil accumulated in the breather and seeping during running.</p><p>Removed the NDE side breather and installed with 1/2 inch NPT connector and fitting to extend the breather length.</p><p>Installed same design and height for the DE side breather too.</p><p>Found oil seeping from the NDE bearing housing end cover plate.</p><p>Removed the bearing housing end cover plate, cleaned the old RTV.</p><p>Made gasket with non-caf gasket, apply RTV on the end cover plate, installed gasket and apply RTV, and installed the cover plate to the bearing housing.</p><p>Test run for 1 hour, found no seeping from NDE bearing cover plate and no seeping from the breather cap.</p><p><br></p><p>Found no abnormal noise during running from both DE and NDE side.</p><p>(noise only exist the casing drain line tubing around the NDE side)</p><p>Unit running normal.</p><p><u><br></u></p><p><u>Action</u>&nbsp;</p><p><u>(25-08-2025)</u></p><p><u><br></u></p><p>-Remove barrier fluid flow line from mechanical seal</p><p>-Release set screw of drive collar from both side (DE &amp; NDE)</p><p>-Put the setting plate to lock position (DE &amp; NDE)</p><p>-Drain baring lube oil from NDE side</p><p>-Remove end cover(outboard) of the bearing housing</p><p>-Remove Oil Ring</p><p>-Remove the bearing housing of NDE side</p><p>-Measure the shim plate between housing and End cover (0.75mm)</p><p>-Remove lock ring from the shaft</p><p>-Measure the distance from shaft end to Sleeve (20.5 mm)</p><p>-Measure the distance from the shaft to bearing (53.2 mm)</p><p>-Remove bearing together with open end cover and flinger</p><p>&nbsp; &nbsp; (By&nbsp;using split bearing puller to avoid unnecessary damage of the end cover and bearing)</p><p>-Remove Mechanical Seal from the pump</p><p>&nbsp; &nbsp; &nbsp;(Found that so many sticky sand as debris between Mech-seal and pump body)</p><p>-Clean the seal housing and shaft</p><p><br></p><p>-Put the setting plate of the NEW MECH-SEAL in lock position</p><p>-Install new O-ring (internal and outside) on new MECH-SEAL</p><p>-Release the Set Screws of the drive collar from New MECH-SEAL</p><p>-Install it on the shaft and torque (45 Nm)</p><p>&nbsp;&nbsp;</p><p>(Look Ahead Plan- Continued installation of NDE bearing and housing)</p><p><br></p><p><u>(26-08-2025)</u></p><p><u><br></u></p><p>-Clean the inlet line strainer&nbsp;</p><p>-Clean inside the strainer housing</p><p>&nbsp;&nbsp;&nbsp;&nbsp; (The line is not block but we found some sludge are sticking inside the whole housing)</p><p>-Remove the coupling and measured DBFF (178.11 mm)</p><p>-Clean the shaft surface readiness to install thrust bearings</p><p>-Heat up the bearings with induction heater (set team; at 110''C)</p><p>-Install the bearing open end cover and flinger to the shaft.</p><p>-Install the bearing on the shaft.</p><p>-Install back bearing housing for temporary protection.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;</p><p>Look ahead plan- To check shaft end play and install back coupling</p><p><br></p><p>(27-08-2025)</p><p>-Tightened the bearing open end cover plate.</p><p>-Loosen the lock screw of the DE side mech seal.(lock the mech seal locking plate)</p><p>-Play the shaft to measure the shaft end play from the DE side coupling.</p><p>-Install the dial gauge at the NDE side shaft end.</p><p>-Move the shaft from the DE side coupling and found the end play measurement is 0.26mm.</p><p>-Measured again to make sure and still got 0.26mm.</p><p>-Adjusted the shaft at the 0.13mm to make it center.</p><p>-Tightened the mech seal lock screw both DE and NDE side.</p><p>-Adjusted the NDE Flinger position between the flinger and bearing open end cover plate at 1.02mm.</p><p>-Tightened the flinger lock screws.</p><p>-Removed the 3 locking plate of the mech seal from the lock position from both DE and NDE mech seal.</p><p>-Adjusted the DE side flinger position at 1.02mm.</p><p>-Installed back the coupling hub.</p><p>-Installed the oil ring to NDE bearing housing.</p><p>-Installed back the NDE side bearing housing end plate cover with RTV gasket compound.</p><p>-Tightened all the bolts of bearing housing and bearing housing end plate cover.</p><p>-Measured alignment with laser alignment and found good condition.</p><p>-Installed back the coupling guard.</p><p>-Flush and clean the barrier fluid inlet and outlet lines of the NDE mech seal with air pressure.</p><p>-Installed back the barrier fluid line inlet and outlet tubing.</p><p>-Top Up the the bearing oil (hydraulic 32) to the NDE bearing housing about 90% of sight glass.</p><p>-Filled the auto filled lube oil cup of NDE and DE.</p><p>-Top Up the NDE side barrier fluid tank to 90% Castrol Hi-spin E5.</p><p>-Opened the air pressure about 6.5 bar and check the pressure drop, found normal, no drop.</p><p>-Process deisolation done.</p><p>-Housekeeping the worksite area.</p><p><br></p><p>Tomorrow plan- waiting electrical isolation and test run.</p><p><br></p><p>28-08-2025</p><p>-Performed electric deisolation.</p><p>-Check every parts and accessories.</p><p>-Start test run.</p><p><b style="background-color: rgb(255, 255, 0);">-Pump running normal.</b></p><p><b style="background-color: rgb(255, 255, 0);">-NDE Seal inlet and outlet no leak, temperature normal.</b></p><p><b style="background-color: rgb(255, 255, 0);">-NDE barrier seal not dropping after 30 mins test run.</b></p><p><br></p><p>Running parameter</p><p>NDE&nbsp;</p><p>Bearing housing temp- 28.8 C</p><p>Barrier fluid Seal inlet 31.5 C</p><p>Barrier fluid Seal outlet 37.1 C</p><p>Seal housing 28.5 C</p><p><br></p><p>DE</p><p>Bearing housing temp- 30.2 C</p><p>Barrier fluid Seal inlet 34.8 C</p><p>Barrier fluid Seal outlet 38.8 C</p><p>Seal housing 28.5 C</p><p><br></p><p>Pump suction pressure 1.5 bar</p><p>Pump housing pressure 5 bar</p><p>Pump discharge pressure 25 bar</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\61 PRODUCED WATER\\P- 6180\\2025\\2025-08-25 NDE barrier fluid drop Replace NDE mech seal and bearing">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\61 PRODUCED WATER\\P- 6180\\2025\\2025-08-25 NDE barrier fluid drop Replace NDE mech seal and bearing</a><br></p>', '2025-08-25 18:15:05', '2025-08-30 08:23:30', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Cmms-Tech', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6180-SKID', 'ZTK-P-6180-SKID', 'Permanent Sand Jetting Pump Skid', NULL, NULL, 'Permanent Sand Jetting Pump Skid', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6180', 'ZTK-P-6180', 'Permanent Sand Jetting Pump', NULL, NULL, 'Permanent Sand Jetting Pump', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Leo', NULL, 'EXTERNAL', '2025-08-25 18:15:05', '2025-08-30 08:23:30', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Cmms-Tech');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2025-08-25 18:15:05', '2025-08-30 08:23:30', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Cmms-Tech');
