-- Inserting report ID 36974
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 4K PM crank soak wash', 'Mechanic', 'PM ', 'Completed', '2025-08-31', '<p>Perform engine crank soak wash for 4K PM</p><p>(1)&nbsp; &nbsp; Remove piping accessary.</p><p>(2)&nbsp; &nbsp; Remove ignition cable and install dummy spark plug.</p><p>(3)&nbsp; &nbsp; Install air supply 30 psi to front bearing seal.</p><p>(4)&nbsp; &nbsp; Open air inlet premium man hole.</p><p>(5)&nbsp; &nbsp; Fill cleaning product ZOK 1 pail and Deionized water 4 pail into mobile injection tank.</p><p>(6)&nbsp; &nbsp; Crank engine by using test crank mode.</p><p>(7)&nbsp; &nbsp; Open the spray valve 50% at the package to spray cleaning product while engine NGP reach to 21.1%.</p><p>(8)&nbsp; &nbsp; Steps of cleaning</p><p></p><p></p><p><br>(9)&nbsp; &nbsp; Take water sample from drain line of exhaust duct.</p><p>(10)&nbsp; &nbsp; Wait for 15 min then continue process washing.</p><p>(11)&nbsp; &nbsp; Step of rinse water</p><p>&nbsp;Fill Deionized water 5 pail in to mobile injection tank</p><p></p><p>(12)&nbsp; &nbsp;Dry crank 8 min for 1 time.</p><p>(13)&nbsp; &nbsp;Reinstated piping and replaced new spark plug.</p><p>(14)&nbsp; &nbsp;Apply CI to VIGV and exercise by firing dry by running engine without load for 20 min.</p><p>Running&nbsp; Hour : 17847hr Start Count 74.</p><p><br></p><p></p><p><br></p>', NULL, '2025-09-01 10:57:50', '2025-09-08 13:17:24', 'PTTEP\\ZPQ.Mechanical-Turbi', 'PTTEP\\ZPQ.Mechanical-Turbi', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTG-7210', 'ZTK-GTG-7210', 'Gas Turbine Generator Package No.1', NULL, NULL, 'Gas Turbine Generator Package No.1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
