-- Inserting report ID 36982
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhaul Water Maker HSS assembly', 'Mechanic', 'CM ', 'In Progress', '2025-09-01', '<p>Task:&nbsp; &nbsp; :&nbsp; &nbsp; To overhaul water maker HP pump HSS assembly</p><p><br></p><p>Action:&nbsp; &nbsp; :</p><p><br></p><p>Disassemble the HSS assembly</p><p><br></p><p>-Remove inducer</p><p>-Remove impeller and O-ring</p><p>-Remove O-ring on seal housing</p><p>-Separate seal housing from the bearing housing</p><p>-Remove the Mech seal rotating face</p><p>-Remove process seal cover from the seal housing</p><p>-Remove O-ring from the process seal&nbsp;</p><p>-Remove O-ring from the shaft sleeve</p><p>-Remove Shaft sleeve and O-ring from the labyrinth seal</p><p>-Separate Lyby seal rotor &amp; the stator</p><p>-Remove snap ring and lift the outboard roller bearing&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p><p>-Remove Inboard bearing from the bearing housing&nbsp;</p><p>-Slide out the retainer of the inboard bearing&nbsp;</p><p>-Remove inboard bearing by using hydraulic press from the shaft pinion</p><p>-Remove inner race of the outboard bearing by using bearing puller</p><p><br></p><p><u>02-09-2025</u></p><p>-Install HSS assembly for hot spare as per the procedure (1 set)</p><p>-Another hot spare can''t be completed cause of gear teeth on the HSS shaft is damaged</p><p>-Install outboard bearing seat in Gear Box housing together with Tolerance ring</p><p>-Update spare parts list in the excel file</p><p>**Now we have only 1 hot spare for HSS assembly, 1 new set already order under #WO<b> 500639947**</b></p><p><b><u><br></u></b></p><p><b><u>Used Spares as follow</u></b></p><p><b><u><br></u></b></p><table class="table table-bordered"><tbody><tr><td>&nbsp;Seal Kit Complete Set (42.70.05.018.3)</td><td>P/N K2535</td><td>1 EA</td></tr><tr><td><p>Labyrinth Seal, Stator (42.70.06.001.3)</p><p>Seal Housing (42.70.06.005.3)</p><p>Tolerance ring&nbsp;</p></td><td><p>P/N S2506</p><p>P/N H2502</p><p>P/N H1010</p></td><td><p>1 EA</p><p>1 EA</p><p>1 EA</p></td></tr></tbody></table><p><br></p>', NULL, '2025-09-01 18:34:07', '2025-09-03 16:31:27', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'LEO', NULL, 'EXTERNAL', '2025-09-01 18:34:07', '2025-09-03 16:31:27', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'P'' witt', NULL, 'EXTERNAL', '2025-09-01 18:34:07', '2025-09-03 16:31:27', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
