  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 4K PM GTC4300', 'Mechanic', 'PM ', 'Completed', '2025-09-04', '<p>Performed crank soak wash.</p><p><u><br></u></p><p>(1)&nbsp; &nbsp; Remove piping accessary.</p><p>(2)&nbsp; &nbsp; Remove ignition cable and install dummy spark plug.</p><p>(3)&nbsp; &nbsp; Install air supply 30 psi to bearings seals.</p><p>(4)&nbsp; &nbsp; Open air inlet premium manhole and Turbine air inlet filter duct to collect chloride sample. (Before and after)</p><p>(5)&nbsp; &nbsp; Fill cleaning product ZOK 1 pail and Deionized water 4 pail into mobile injection tank.</p><p>(6)&nbsp; &nbsp; Crank engine by using test crank mode.</p><p>(7)&nbsp; &nbsp; Open the spray valve 50% at the package to spray cleaning product while engine NGP reach to 20%.</p><p>(8)&nbsp; &nbsp; Step of cleaning</p><p>(9)&nbsp; &nbsp; Take water sample from combustor drain port.&nbsp;</p><p><br></p><table class="table table-bordered"><tbody><tr><td><br></td><td>ZOK + Water</td><td>Soaking time</td></tr><tr><td>CSW</td><td>8 mins</td><td>15 mins</td></tr></tbody></table><p>(10)&nbsp; &nbsp; Wait for 15 min then continue process washing.</p><p>(11)&nbsp; &nbsp; Step of rinse water</p><p>&nbsp;Fill Deionized water 5 pail into mobile injection tank</p><table border="1" cellspacing="0" cellpadding="0"><tbody><tr><td width="126" valign="top"><p>&nbsp;</p></td><td width="198" valign="top"><p align="center">Spray</p></td><td width="198" valign="top"><p align="center">Stop</p></td></tr><tr><td width="126" valign="top"><p>1st&nbsp;Rinse</p></td><td width="198" valign="top"><p align="center">8 min</p></td><td width="198" valign="top"><p align="center">10 min</p></td></tr><tr><td width="126" valign="top"><p>2nd&nbsp;Rinse</p></td><td width="198" valign="top"><p align="center">8 min</p></td><td width="198" valign="top"><p align="center">10 min</p></td></tr></tbody></table><p>(12)&nbsp; &nbsp;Dry crank for 8 min.</p><p>(13)&nbsp; &nbsp;Reinstated piping and replaced new spark plug.</p><p>(14)&nbsp; &nbsp;Apply CI to VIGV.</p><p>(15)&nbsp; Clean the inside by utility air.&nbsp;</p><p>Running Hour: 14102 Hr. Start Count 15.</p><p>Water properties analysis collected from combustor drain port.&nbsp;</p><p></p><p></p>', NULL, '2025-09-04 17:39:49', '2025-09-12 14:23:38', 'PTTEP\\ZPQ.Mechanical-Turbi', 'PTTEP\\ZPQ.Mechanical-Turbi', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4300', 'ZTK-GTC-4300', 'Train 2,Gas Turbine Comp Package', NULL, NULL, 'Train 2,Gas Turbine Comp Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'P''Wit', NULL, 'EXTERNAL', '2025-09-04 17:39:49', '2025-09-12 14:23:38', 'PTTEP\\ZPQ.Mechanical-Turbi', 'PTTEP\\ZPQ.Mechanical-Turbi');
