-- Inserting report ID 37002
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S High Temperature at Washdown water PUMP P-6835', 'Mechanic', 'CM ', 'Completed', '2025-09-07', '<p>Problem : </p><p>Temperature was high during running and pressure was slowly drop.</p><p>Found&nbsp; &nbsp; : </p><p>When the pump is running pump body, suction pipe and also discharged pipe was heat up.</p><p><br></p><p>Job Task: </p><p><br></p><p>4/9/2025</p><p><br></p><p>Test run the pump first to verified the problem found black water came out from the discharge.</p><p>Opened the pump drain pipe and found water come out with very low pressure.</p><p>Removed the pump''s discharge pipe and inspected with bore scope tool found that pump''s impeller and volute was badly rusty.</p><p>Removed the pump''s mech seal flushing line and checked any blockage found nothing block inside.</p><p>Also checked the discharged pipe and found nothing block inside.</p><p>Reinstate the pump''s piping and all accessories.&nbsp;</p><p><br></p><p>5/9/2025</p><p><br></p><p>Drained the bearing lube oil.</p><p>Lock the mech seal by moving the lock plate.</p><p>Removed the seal flushing line piping.</p><p>Removed the coupling guard and removed the coupling.</p><p>Measured the DBFF 141.86mm.</p><p>Erected the scaffold to lift the pump housing.</p><p>Removed the housing bolts from the pump housing and volute.</p><p>Tightened the jack bolts and removed the pump housing, lift by the chain hoist to keep level.</p><p>Removed the impeller hub cap nut (30mm socket) inside the workshop.</p><p>Removed the impeller by using two crow bar.</p><p>Found the impeller surface and stuffing box surfaces are badly corroded.</p><p>Removed the O-ring T1 and T2.</p><p>Cleaned the impeller surfaces both sides.</p><p>Cleaned the stuffing box surface.</p><p>Found dents and pits after cleaning the corrosion.</p><p>Checked the inlet line at the wok site area.</p><p>Open the inlet valve and water come out from volute, line not block.</p><p><br></p><p>Tomorrow plan</p><p>Verify the temp high reason.</p><p>Clean and surface prepare the impeller.</p><p>Install back the pump.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p>6/9/2025</p><p>Measured the impeller&nbsp; wear ring OD-94.5mm.</p><p>Measured the casing wear ring ID- 94.91mm.</p><p>Cleaned the volute.</p><p>Installed the O-ring T1 and T2 to the impeller and casing.</p><p>Installed impeller back to the pump, tightened the impeller hub cap with 150 N-m(CW).</p><p>Carried the pump back to the site, installed back to the volute casing by lifting gears.</p><p>Installed the casing gasket with new one.</p><p>Tightened the casing bolts with 63 Nm.</p><p>Measured the DBFF, 140.04 mm.</p><p>Installed the coupling.</p><p>Performed laser alignment, adjusted the horizontal alignment.</p><p>Adjusted the vertical alignment by removing shims 0.2mm from both side of motor NDE legs.</p><p>Found good alignment after laser alignment remeasurement.</p><p>Installed the coupling guard.</p><p>Refilled new bearing lube oil Hydraulic 32 about 0.7L.</p><p>Refilled the autofill cap and installed back.</p><p>Reinstalled the mech seal flushing line.</p><p>Housekeeping the area.</p><p><br></p><p>Tmr plan, Test run.</p><p><br></p><p>7/9/2025</p><p>Electrical and process deisolation.</p><p>Performed test run.</p><p>Monitor temperature, pressure and vibration about 40 mins.</p><p>Temperature ( C )</p><p>Pump DE 34.7</p><p>Pump NDE 31.5</p><p>Suction line 27.2</p><p>Discharge 27.6</p><p>Seal flushing line 29.5</p><p><br></p><p>Pressure</p><p>Suction 0.02 bar</p><p>Discharge 10.5 bar</p><p><br></p><p>Recorded vibration data will send to SKF with September measurement.</p><p><br></p><p><b>During test run, no abnormal sound and vibration is found, pump running in normal condition with normal temperature.</b></p><p><br></p><p>Test run again at 4:15 PM, and performed condition check.</p><p>Test run about over 20mins and temperature and pressure in normal range.</p><p>Temperature ( C )</p><p>Pump DE 42</p><p>Pump NDE 38</p><p>Suction line 29.4</p><p>Discharge 29.8</p><p>Seal flushing line 30</p><p>Pump volute body 30.1</p><p>Mech Seal 31.5</p><p><br></p><p>Pressure</p><p>Suction 0.02 bar</p><p>Discharge 10.5 bar</p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\68 COOLING WATER, FRESH WATER &amp; PORTABLE WATER\\P-6835\\2025\\2025-09-05 TS hig temp Removed pump and TS\\2025-09-06 TS high Temp">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\68 COOLING WATER, FRESH WATER &amp; PORTABLE WATER\\P-6835\\2025\\2025-09-05 TS hig temp Removed pump and TS\\2025-09-06 TS high Temp</a><br></p>', '2025-09-04 17:46:03', '2025-09-08 18:05:53', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-6835-ASSY', 'ZTK-P-6835-ASSY', 'Wash Down Water Pump Assembly', NULL, NULL, 'Wash Down Water Pump Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kaung', NULL, 'EXTERNAL', '2025-09-04 17:46:03', '2025-09-08 18:05:53', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Plate', NULL, 'EXTERNAL', '2025-09-04 17:46:03', '2025-09-08 18:05:53', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2025-09-04 17:46:03', '2025-09-08 18:05:53', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jason', NULL, 'EXTERNAL', '2025-09-04 17:46:03', '2025-09-08 18:05:53', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-Works');
END $$;

