  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS SCBA air compressor malfunction', 'Mechanic', 'CM ', 'In Progress', '2025-09-05', '<p><b><u>Problem</u></b></p><p>No discharge air coming out.</p><p><b><u>Action</u></b></p><p>-Checked compressor lube oil, compressor inlet air filter and fittings before start the unit.</p><p><br></p><p>-<b>1st attempt</b> start the unit, compressor is running and pressurizing by seeing the pressure gauge at the air inlet of the CO moisture monitor assembly.&nbsp;</p><p>-After 1 min, the unit is tripped by the alarm <span style="background-color: rgb(255, 255, 0);">(<b>Checked cable connection. Replace all cartridge and seat correctly.)</b></span></p><p><b>-</b>Reset the alarm then re-positioning the pressure transmitter of CO moisture monitoring assembly.&nbsp;</p><p><br></p><p>-2nd attempt start the unit and the alarm <span style="background-color: rgb(255, 255, 0);">(</span><b><span style="background-color: rgb(255, 255, 0);">Replace Cartridge Soon</span>)</b>&nbsp;pop up while running.&nbsp;</p><p>-Once reset the alarm on the screen, the final pressure is built up. <span style="background-color: rgb(255, 255, 0);">(1053PSI)</span></p><p>-Then the unit is tripped by motor overload.&nbsp;</p><p><br></p><p>-3rd attempt start the unit and found<span style="background-color: rgb(255, 255, 0);"> <b>leak points</b></span> at the discharge hose from CO moisture monitoring assembly.</p><p><br></p><p><b><u>Remarks</u></b></p><p>-Already ordered spare and will be replaced when received.&nbsp;</p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\102 PORTABLE EQUIPMENTS\\A-7410 Mini Unicus SCBA air compressor\\2025\\2025-09-05 TS no air discharge">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\102 PORTABLE EQUIPMENTS\\A-7410 Mini Unicus SCBA air compressor\\2025\\2025-09-05 TS no air discharge</a><br></p>', '2025-09-05 18:27:43', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Turbi', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-7410', 'ZTK-A-7410', 'Compressor BAUER COMPRESSOR, Mini-Unicus', NULL, NULL, 'Compressor BAUER COMPRESSOR, Mini-Unicus', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
