-- Inserting report ID 37040
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhaul Closed drain sump pump.', 'Mechanic', 'CM ', 'Completed', '2025-09-08', '<p><b>Description:</b> Performed overhauling closed drain sump pump for WP 15.</p><p><br></p><p><b>Working steps:</b></p><p>-dismantled the assembly in orders.</p><p>-Replaced O-rings and seal kits of pneumatic air drive assembly and piston rod assembly.</p><p>-Replaced Diaphragm with the hot spare as found dents and pitting.</p><p>-Replaced both cylinder end caps and barrels as found dents and pitting.</p><p>-Replaced one hydraulic check valve end caps with the hot spare as found the check valve is not proper seating.</p><p>-Re-assembled the parts in order.</p><p>-Performed functional test run.</p><p>-Closed the discharged valve and observed the pressure, found went up to 500psi.</p><p><span style="background-color: rgb(0, 255, 0);">-the assembly is ready to be in service.</span></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\Closed Drain Sump Pump\\2025-09-08 Overhaul sump pump">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\Closed Drain Sump Pump\\2025-09-08 Overhaul sump pump</a><br></p>', '2025-09-08 19:01:38', '2025-09-08 19:02:13', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTHER', 'OTHER', 'OTHER', NULL, NULL, 'OTHER', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
