-- Inserting report ID 37075
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist PMO/I for 2Y UPS & 4Y Discharge Test', 'Electrical & Instrument', 'PM ', 'Completed', '2025-09-12', '<p><b><u>Activity,</u></b></p>  <p>-Assist to perform 2Y PM UPS and 4Y Batteries Discharge Test.(Day-1)</p>  <p><b><u>History,</u></b></p>  <p>-NA</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-UPS System, PMA</p>  <p><b><u>As found,</u></b></p>  <p>-UPS-CPP-233 panel was dirty with dust.</p><p>-6 of 102 cells are low performance during discharge test (3Hrs).&nbsp;</p>  <p><b><u>What happen,</u></b></p>  <p>- Ageing.</p>  <p><b><u>Action,</u></b></p><p>-Performed electrical isolation of UPS-CPP-233 in PMA.</p><p>-Performed battery discharge test at 156A (5-hour discharge rate) using the battery load units.</p><p>-Measured and recorded battery voltages every 30 minutes.</p><p>-Discharge test was stopped after 3 hours because 6 out of 102 cells showed low performance (approx. 1.90-1.91?VDC). These were cells No. 23, 46, 48, 62, 65, and 77.</p><p>-Checked and re-tightened the battery terminals (12 N.m).</p><p>-Marked stickers for the six low-performance batteries.</p><p>-Cleaned the UPS-233 panel and replaced the defective display board.</p><p>-Performed alarm function tests (fan failure, rectifier fault, etc.) and measured relevant parameters as per procedure.</p>  <p><b><u>Next plan,</u></b></p>  <p>-Continue PM on UPS-CPP-230A.&nbsp;</p>  <p><b><u>Documentation,</u></b></p>  <p>-Will submit by PMO/I after UPS PM campaign completed.&nbsp;</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-09-12_UPS-CPP-233,Assist 2Y PM UPS and Charger and 4Y PM Battery Discharge Test', '2025-09-12 15:08:56', '2025-09-13 17:02:57', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-UPS-CPP-233-SKID', 'ZTK-UPS-CPP-233-SKID', '400Vac UPS Panel Skid for HVAC PMA', NULL, NULL, '400Vac UPS Panel Skid for HVAC PMA', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
