-- Inserting report ID 37083
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S System fault alarm on PMA UPS', 'Electrical & Instrument', 'CM ', 'Completed', '2025-09-12', '<p><u><b>Activity,</b></u></p><p>-T/S System fault alarm on PMA UPS during PM inspection.(UPS-CPP-233)</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-UPS System, PMA</p><p><u><b>As found,</b></u></p><p>-Inverter Fault (System Fault) alarm came during power re-energised on UPS-CPP-233 PM inspection.</p><p><u><b>What happen,</b></u></p><p>- Inverter interface card was malfunction.</p><p><u><b>Action,</b></u></p><li data-start="119" data-end="220"><p data-start="121" data-end="220">-During power re-energization of UPS-CPP-233, an <strong data-start="169" data-end="202">Inverter Fault (System Fault)</strong> alarm occurred.</p> </li> <li data-start="221" data-end="306"> <p data-start="223" data-end="306">-Found inverter output magnetic contactor (<strong data-start="274" data-end="280">K7</strong>) was <strong data-start="286" data-end="303">not energized</strong>.</p> </li> <li data-start="307" data-end="401"> <p data-start="309" data-end="401">-Tested contactor K7 with an external power supply (20A) — found it was functioning normally.</p> </li> <li data-start="402" data-end="489"> <p data-start="404" data-end="489">-Suspected that "261 inverter interface P8 3-Phase" card output (24VDC) is low performance or malfunction.</p> </li> <li data-start="490" data-end="587"> <p data-start="492" data-end="587">-Replaced with new Inverter Interface card (P/N 8000022441).</p><p data-start="492" data-end="587">-Power up the UPS-CPP-233 again with success. Normal operation was restored.</p></li><p><u><b>As left,</b></u></p><p>-UPS-CPP-233 back to service.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-Old Inverter card was already disposed.</p><p><u><b>Next plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-09-12_UPS-CPP-233, TS the System fault alarm on PMA UPS', '2025-09-12 22:04:18', '2025-09-13 13:25:36', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-UPS-CPP-233-SKID', 'ZTK-UPS-CPP-233-SKID', '400Vac UPS Panel Skid for HVAC PMA', NULL, NULL, '400Vac UPS Panel Skid for HVAC PMA', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
