  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bo', NULL, 'EXTERNAL', '2025-09-12 22:04:18', '2025-09-13 13:25:36', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Supv');
