  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist PMO/I for 2Y UPS & 4Y Discharge Test', 'Electrical & Instrument', 'PM ', 'Completed', '2025-09-13', '<p><u><b>Activity,</b></u></p><p>-Assist to perform 2Y PM UPS and 4Y Batteries Discharge Test</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-UPS System, for Instrument and telephone</p><p><u><b>As found,</b></u></p><p>-UPS-CPP-230A panel was dirty with dust.</p><p>-4 of 102 cells are low performance during discharge test (3Hrs).&nbsp;</p><p><u><b>What happen,</b></u></p><p>- Ageing.</p><p><u><b>Action,</b></u></p><p>-Performed electrical isolation of UPS-CPP-230A</p><p>-Performed battery discharge test at 156A (5-hour discharge rate) using the battery load units.</p><p>-Measured and recorded battery voltages every 30 minutes.</p><p>-Discharge test was stopped after 3 hours because 4 out of 102 cells showed low performance (approx. 1.89-1.91?VDC). These were cells No. 72, 79, 89 and 101</p><p>-Checked and re-tightened the battery terminals (12 N.m).</p><p>-Marked stickers for the six low-performance batteries.</p><p>-Cleaned the UPS-230A panel.</p><p>-Performed alarm function tests (fan failure, rectifier fault, etc.) and measured relevant parameters as per procedure.</p><p><u><b>Next plan,</b></u></p><p>-Continue PM on UPS-CPP-231A&nbsp;</p><p><u><b>Documentation</b>,</u></p><p>-Will submit by PMO/I after UPS PM campaign completed.&nbsp;</p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-09-13_UPS-CPP-230A,Assist 2Y PM UPS and Charger and 4Y PM Battery Discharge Test', '2025-09-13 15:55:56', '2025-09-14 13:40:14', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
