DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Crane Engine cannot Accelerate at WP-02', 'Mechanic', 'CM ', 'Completed', '2025-09-14', '<p>Problem : During lifting operation crane engine was cannot increase RPM and black smoke come out from&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;exhaust.</p><p>Found&nbsp; &nbsp; : During pre-check by mechanic air shutoff valve handle from AMOT valve was obstruct by HYD&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;hose.</p><p>Action&nbsp; &nbsp; : At first check all the engine condition.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the air filter and check the fuel shut off valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Test run the engine, engine is running normal and can increase the engine''s RPM.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Keep running the crane for 10 lifts (1 hr 30 mins)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the broken bolt of throttle lever by drilling and tapping with M6,</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Replaced new bolt and tighten with thread locker at throttle leaver.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p><br></p>', NULL, '2025-09-14 17:40:21', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Crane', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP02-CR-0273', 'ZTK-WP02-CR-0273', 'Pedestal Crane Package WP02', NULL, NULL, 'Pedestal Crane Package WP02', 'WP02', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2025-09-14 17:40:21', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Crane', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'John', NULL, 'EXTERNAL', '2025-09-14 17:40:21', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Crane', NULL);
END $$;

