-- Inserting report ID 37100
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 8K PM GTC4200', 'Mechanic', 'PM ', 'Completed', '2025-09-16', '<p>Perform 8K PM</p><p><br></p><p><b><u>15-09-2025</u></b></p><p><b><u>Perform Crank Soak Wash</u></b></p><p>- Performed mechanical isolation.&nbsp; &nbsp;&nbsp;</p><p>- Performed process isolation.</p><p>-Remove piping accessary.</p><p>-Remove ignition cable and install dummy spark plug.</p><p>-Install air supply 30 psi to bearings seals.</p><p>-Open air inlet premium manhole and Turbine air inlet filter duct to collect chloride sample. (Before and after)</p><p>-Fill cleaning product ZOK 1 pail and Deionized water 4 pail into mobile injection tank.</p><p>-Crank engine by using test crank mode. NGP20%</p><p>-Open the spray valve 50% at the package to spray cleaning product while engine NGP reach to 20%.</p><p>&nbsp; &nbsp;</p><p>Step of cleaning&nbsp;&nbsp;</p><table class="table table-bordered"><tbody><tr><td>ZOK + Water</td><td>Soaking time</td></tr><tr><td>1st attempt</td><td>50%&nbsp;</td><td>15 mins</td></tr><tr><td>2nd attempt</td><td>50%&nbsp;</td><td>15 mins</td></tr></tbody></table>-Take water sample from combustor drain port.&nbsp; &nbsp; &nbsp;<p>-Wait for 15 min then continue process washing.</p><p><br></p><p>&nbsp; &nbsp; Step of rinse water</p><p>&nbsp;Fill Deionized water 5 pail into mobile injection tank</p><table border="1" cellspacing="0" cellpadding="0"><tbody><tr><td width="126" valign="top"><p>&nbsp;</p></td><td width="198" valign="top"><p align="center">Spray</p></td><td width="198" valign="top"><p align="center">Stop</p></td></tr><tr><td width="126" valign="top"><p>1st&nbsp;Rinse</p></td><td width="198" valign="top"><p align="center">8 min</p></td><td width="198" valign="top"><p align="center">10 min</p></td></tr><tr><td width="126" valign="top"><p>2nd&nbsp;Rinse</p></td><td width="198" valign="top"><p align="center">8 min</p></td><td width="198" valign="top"><p align="center">10 min</p></td></tr></tbody></table><p>-Dry crank for 8 min.</p><p>-Reinstated piping and replaced new spark plug.</p><p>- Apply CI to VIGV.</p><p>-Clean the inside by utility air.&nbsp;</p><p>Running Hour: 22947Hr. 34 Start Count .</p><p>Water properties analysis collected from combustor drain port.&nbsp;</p><p></p><p></p><p><br></p><p><b>Performed 8K PM as per job card.&nbsp;</b></p><p>- Performed mechanical isolation.</p><p>- Performed process isolation.</p><p>- Replaced lube oil filters.</p><p>- Replaced fuel gas filter.</p><p>- Replaced instrument air filter.</p><p>- Replaced oil demisters filter from HSS and LSS.</p><p>- Replaced spark plugs.</p><p>- Flushed out air trapping from lube oil filter by running backup lube oil pump.</p><p><br></p><p><b><u>16-09-2025</u></b></p><p><br></p><p>Continued 8K PM as per job card.&nbsp;</p><p>- Replaced 1st and 2nd stage air intake filters.</p><p>- Cleaned TAI housing by water and air.&nbsp;</p><p>- Replaced enclosure filters.&nbsp;</p><p>- Cleaned enclosure housing by water and air.&nbsp;</p><p>- Replaced seal gas filter and separation gas filter.</p><p>- Performed borescope inspection. (35% completed)&nbsp;</p><p>- Cleaned inside the package.</p><p>- De-isolation process, electrical and mechanical.&nbsp;</p><p>- Checked inside and outside enclosure, No abnormal finding.</p><p><br></p><p></p><p><u>Remark</u></p><p>-Recorded sample at seal gas primary vent NDE and DE. (found liquid 50ml at NDE side)</p><p>-Recorded sample at seal gas supply drain line. (No any abnormal found)&nbsp;</p><p>-Found ignition cable fitting is crack and replaced new spare by EI team.&nbsp;</p><p>-Replaced water wash cart (water only) outlet female connector.</p><p>-Replaced insulation sleeve for PCD line from engine to pressure transmitters.&nbsp;</p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\42 GAS COMPRESSOR T 1\\2025\\2025-09-15 Perform 8K PM">\\\\10.15.131.205\\maint-share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\42 GAS COMPRESSOR T 1\\2025\\2025-09-15 Perform 8K PM</a><br></p>', '2025-09-15 18:48:43', '2025-09-17 21:31:06', 'PTTEP\\ZPQ.Mechanical-Turbi', 'PTTEP\\ZPQ.Mechanical-Turbi', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4200', 'ZTK-GTC-4200', 'Train 1,Gas Turbine Comp Package', NULL, NULL, 'Train 1,Gas Turbine Comp Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
