  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist PMO/I for 2Y UPS & 4Y Discharge Test', 'Electrical & Instrument', 'PM ', 'Completed', '2025-09-17', '<p><b><u>Activity,</u></b></p>  <p>-Assist to perform 2Y PM UPS and 4Y Batteries Discharge Test.</p><p>-UPS-CPP-231B</p>  <p><b><u>History,</u></b></p>  <p>-NA</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-UPS System for Elec and UCP load</p>  <p><b><u>As found,</u></b></p>  <p>-NA</p>  <p><b><u>What happen,</u></b></p>  <p>- NA</p>  <p><b><u>Action,</u></b></p>  <p>-Performed electrical isolation of UPS-CPP-231B.</p><p>-Performed battery discharge test at 105A (8-hour discharge rate) using the battery load units.</p><p>-Measured and recorded battery voltages every 60 minutes.</p><p>-Discharge test was stopped after 5 hours because cell no.14 has 0.7VDC.</p><p>-Checked and re-tightened the battery terminals (10 N.m).</p><p>-Cleaned Battery Bank and UPS-231B feeder.</p><p>-Performed alarm function tests (fan failure, rectifier fault, etc.) and measured relevant parameters as per procedure.</p><p>-Found the rectifier communication error during battery test due to the rectifier interface card malfunction.</p><p>-Replaced the interface card and the error was cleared and continued the alarm function tests.</p><p>-All are functioning normal. </p><p>-De-isolated the power for the UPS-231B and normalised both UPS-231A and B.</p>  <p><b><u>As left,</u></b></p>  <p>-Both UPS-231A and B are running normal without any alarm.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-N/A</p>  <p><b><u>Next plan,</u></b></p>  <p>-Continue PM on UPS-CPP-232B</p>  <p><b><u>Documentation,</u></b></p>  <p>-Will submit by PMO/I after UPS PM campaign completed.&nbsp;</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-09-17_UPS-CPP-231B,Assist 2Y PM UPS and Charger and 4Y PM Battery Discharge Test', '2025-09-17 15:40:52', '2025-09-18 18:03:52', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-UPS-CPP-231B', 'ZTK-UPS-CPP-231B', '230V AC UPS No.2 for Elec & UCP Load', NULL, NULL, '230V AC UPS No.2 for Elec & UCP Load', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
