  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist PMO/I for 2Y UPS & 4Y Discharge Test', 'Electrical & Instrument', 'PM ', 'Completed', '2025-09-18', '<p><u><b>Activity,</b></u></p><p>-Assist to perform 2Y PM UPS and 4Y Batteries Discharge Test.</p><p>-UPS-CPP-232B</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-UPS System for Elec and UCP load</p><p><u><b>As found,</b></u></p><p>-NA</p><p><u><b>What happen,</b></u></p><p>- NA</p><p><u><b>Action,</b></u></p><p>-Performed electrical isolation of UPS-CPP-232B.</p><p>-During electrical isolation, found Front Display Module FDM121 for Feeder no. F16-60 can''t enter the metering page.</p><p>-Replaced with the spare feeder Front Display Module FDM121, Feeder no.F6-24.</p><p>-After replaced Front display module FDM121 of feeder F16-60 still can''t enter metering page.</p><p>-Performed battery discharge test at 136A (8-hour discharge rate) using the battery load units.</p><p>-Measured and recorded battery voltages every 60 minutes.</p><p>-<span style="background-color: rgb(255, 255, 0);">At the 8 hours discharge time, found Battery No. 36 = 1.743V, Battery No.54 = 1.747V, Battery No.78 = 1.707V, Battery No.81 = 1.741V.</span></p><p>-Checked and re-tightened the battery terminals (10 N.m).</p><p>-Cleaned Battery Bank and UPS-232B feeder.</p><p>-De-isolated the power for the UPS-232B and normalised both UPS-232A and B.</p><p><u><b>As left,</b></u></p><p>-Front display module FDM121 of feeder F16-60 still can''t enter metering page.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><u><b>Next plan,</b></u></p><p>-Need to verify Front display module FDM121 of feeder F16-60 still can''t enter metering page.</p><p><u><b>Documentation,</b></u></p><p>-Will submit by PMO/I after UPS PM campaign completed.&nbsp;</p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-09-18_UPS-CPP-232B, Assist to perform 2Y PM UPS and 4Y Batteries Discharge Test', '2025-09-18 14:51:54', '2025-09-19 07:16:41', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
