erly', '2025-09-18 16:05:18', '2025-09-18 17:52:03', 'PTTEP\\ZPQ.Cmms-Tech', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LV-66445', 'ZTK-LV-66445', 'LV,Hypochlorite Outlet from P-6642A/B', NULL, NULL, 'LV,Hypochlorite Outlet from P-6642A/B', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
