  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist 2Y PM BC Charger and 4Y PM Battery Discharg', 'Electrical & Instrument', 'PM ', 'Completed', '2025-09-19', '<p><b><u>Activity,</u></b></p>  <p>-Assist to perform 2Y PM UPS and 4Y Batteries Discharge Test.</p><p>-BC-CPP-231A</p>  <p><b><u>History,</u></b></p>  <p>-N/A</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-DC System for Electrical load, ESWGR</p>  <p><b><u>As found,</u></b></p>  <p>-NA</p>  <p><b><u>What happen,</u></b></p>  <p>-NA</p>  <p><b><u>Action,</u></b></p>  <p>-Performed electrical isolation of BC-CPP-241A.</p><p>-Performed battery discharge test at 29A (10-hour discharge rate) using the battery load unit.</p><p>-Measured and recorded battery voltages every 60 minutes.</p><p>-At the 8 hours discharge time, found Battery No.7,9,18,23,44 and 45 voltages are lower than 1.88VDC.&nbsp;</p><p>-Stopped the discharging.</p><p>-Checked and re-tightened the battery terminals (10 N.m).</p><p>-Cleaned Battery Bank and BC-CPP-241A feeder.</p><p>-De-isolated and normalized the power for the BC-CPP-241A.</p>  <p><b><u>As left,</u></b></p>  <p>-N/A</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-N/A</p>  <p><b><u>Next plan,</u></b></p>  <p>-To continue PM for BC-CPP-240A.</p>  <p><b><u>Documentation,</u></b></p>  <p>-Will submit by PMO/I after UPS PM campaign completed.&nbsp;</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-09-19_BC-CPP-241A,Assist PMOI for YPM on BC and discharge test', '2025-09-19 17:02:36', '2025-09-19 18:09:43', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
