  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhauled water-maker HSS assembly.', 'Mechanic', 'OTH ', 'Completed', '2025-09-20', '<p><b>Description: </b>Overhauled and preserved the HSS pump which removed from the P-6651 as for lube oil abnormal condition verification.</p><p><br></p><p><b>Working steps:</b></p><p>-Checked the impeller gap and found the gap <span style="background-color: rgb(255, 255, 0);">0.5 ~ 1.5 mm clearance.</span></p><p>-Dismantled the assembly as per procedures.</p><p>-Replaced all O-rings.</p><p>-Replaced the Inboard and outboard bearings.</p><p>-Replaced Labyrinth stator seal.</p><p>-Replaced shaft sleeve.</p><p><b><i>-Reused the mech seal assembly.</i></b></p><p><br>-Reinstated the assembly as per procedures.</p><p>-Tightened the inducer with torque <b><i>52 N-m (38 ft-lb).</i></b></p><p>-checked the impeller gap and found the gap <span style="background-color: rgb(255, 255, 0);">0.5 ~ 1.5 mm clearance.</span></p><p>-Removed the impeller and replaced with the hot spare one.</p><p>-Tightened the inducer with torque and checked the impeller gap, found <span style="background-color: rgb(0, 255, 0);">0.5 mm.&nbsp;</span></p><p><span style="background-color: rgb(0, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 255);">-Preserved the assembly''s bearings with C-treat Oil and plastic sheet.</span></p><p><span style="background-color: rgb(0, 255, 0);">-the assembly is ready to be service.</span></p><p><br></p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\66 SERVICE WATER &amp; SEA WATER\\X-6620\\2025\\2025-09-13 Overhaul HSS assembly">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare