-- Inserting report ID 37148
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Analyze lube oil results for turbomachinery Q2 25', 'Mechanic', 'PM ', 'Completed', '2025-09-21', '<p>Summarize turbomachinery lube oil sample results for 2nd quarter of 2025.&nbsp;</p><p><br></p><p><u>GTC-4200</u></p><p>-Note viscosity is slightly lower than normal limits.</p><p>-Particle count indicates that oil cleanliness level is near to unacceptable range.</p><p><br></p><p><u>GTC-4300</u></p><p>-Particle count indicates that oil cleanliness level is near to unacceptable range.</p><p>-Foaming Tendency and Stability ASTM D-892 is acceptable in all Sequences tested.</p><p><br></p><p><u>GTC-4400</u></p><p>-All OIL CONDITIONS and OIL TESTS appear in NORMAL working range.</p><p>-Foaming Tendency and Stability ASTM D-892 is acceptable in all Sequences tested.</p><p>-Particle count indicates that oil cleanliness level is near to unacceptable range.</p><p><br></p><p><u>GTG-7210</u></p><p>-Note viscosity is slightly lower than normal limits.</p><p>-Particle count indicates that oil cleanliness level is near to unacceptable range.</p><p><br></p><p><u style="background-color: rgb(255, 255, 0);">GTG-7220</u></p><p>-Note abnormal wear metals. Recommend monitor the abnormal trend closely.</p><p>-Lead(Pb), may be from wear of plain bearings, journal bearings or bushings.</p><p>-Particle count indicates that oil cleanliness level is above Alarm Limits range. ( Cleanliness Target ) and NEEDS TO BE IMPROVED.</p><p>-Recommend check why the oil filtration system is not keeping this oil within cleanliness specifications.</p><p>-Suggest using a portable off-line filtration system to clean up the oil system.</p><p><br></p><p><u style="background-color: rgb(255, 255, 0);">GTG-7230</u></p><p>-Note abnormal wear metals. Recommend monitor the abnormal trend closely.</p><p>-Lead(Pb) are probably from wear of plain bearings or journal bearings.</p><p>-All OIL CONDITIONS and OIL TESTS appear in NORMAL working range.</p><p>-Particle count indicates that oil cleanliness level is above Alarm Limits range. ( Cleanliness Target ) and NEEDS TO BE IMPROVED.</p><p>-Suggest using a portable off-line filtration system to clean up the oil system.</p><p><br></p>', NULL, '2025-09-21 21:41:05', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Turbi', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4200', 'ZTK-GTC-4200', 'Train 1,Gas Turbine Comp Package', NULL, NULL, 'Train 1,Gas Turbine Comp Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
