  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform load balancing for battery chargers', 'Electrical & Instrument', 'OTH ', 'Completed', '2025-09-23', '<p><b><u>Activity,</u></b></p>  <p>-Perform load balancing for battery chargers.</p>  <p><b><u>History,</u></b></p>  <p>-N/A</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-DC System for Electrical load, Switchgear and DC System for Electrical load, GTG,GTC, Main Deck</p>  <p><b><u>As found,</u></b></p>  <p>-Load for each BC are unbalance.</p>  <p><b><u>What happen,</u></b></p>  <p>-N/A</p>  <p><b><u>Action,</u></b></p>  <p>-Checked and compared the battery voltage and battery temperature(27 degree C each) for each BC for BC-CPP-240A and B.</p>  <p>-For load balancing battery temperature are equal. But the voltage of BC-CPP-240B was a bit higher than of A.</p><p>-Go to set up and calibrate set up to increase voltage. Then increased voltage reading of A to 0.5%.</p><p>-Then the load current becomes 18.8A for BC-CPP-240A and 12.4A for BC-CPP-240B.(5V difference which is acceptable as per AEG)</p><p>-Continue load balancing for BC-CPP-241A and B.</p><p>-Compare battery temperature and found both are 26 degree C each.</p><p>-The voltage are compared and found unit A voltage is a bit higher than of B.</p><p>-Reduced the voltage to load share with the result of 4.5A for BC-CPP-241A and 9.7A for BC-CPP-241B.(5V difference)</p><p>Note: password:1211</p>  <p><b><u>As left,</u></b></p>  <p>-Both units are normal.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-N/A</p>  <p><b><u>Next plan,</u></b></p>  <p>-N/A</p>  <p><b><u>Documentation,</u></b></p>  <p>-N/A</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-09-23_BC-CPP-240AB and BC-CPP-241AB, Load share for battery charger', '2025-09-23 16:49:19', '2025-09-23 18:19:35', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-BC-CPP-240A', 'ZTK-BC-CPP-240A', '120V DC Battery Charger No.1', NULL, NULL, '120V DC Battery Charger No.1', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
