  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS air booster is not running', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-09-23', '<p><u><b>Activity,</b></u></p><p>-TS air booster pump (Haskel pump at air receiver tank V-6560) is not running, </p><p>- C-6565 for firewater pump no.2.</p><p><u><b>History,</b></u></p><p>-NA</p><div><u><b>Equipment description and location,</b></u></div><p>-Air booster pump for V-6560, Main Deck.</p><p><u><b>As found,</b></u></p><p>-Found that the air receiver tank pressure is 17 barg but not the pump has not started yet.</p><p><u><b>What happen,</b></u></p><p>- Found air pilot switch adjuster lock nut was loosen and pilot spool was stuck.</p><p><u><b>Action,</b></u></p><p>-Perform exercise the pilot switch, spring and spool.</p><p>-Readjusted the pilot pressure switch at around 21 bar.</p><p>-After adjusted the pressure switch and exercise the pilot switch, spring and spool, pump is running.</p><p><u><b>As left,</b></u></p><p>-Pump is running as the set point.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-NA</p><p><u><b>Next plan,</b></u></p><p>-If the pump was not stopped as the set point, plan to replace new pilot pressure switch and adjust the set point.</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job progress,</b></u></p><p>-Under monitoring.</p>', NULL, '2025-09-23 17:36:32', '2025-09-25 18:52:56', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-C-6565', 'ZTK-C-6565', 'Air Pressure Multiplier No.2', NULL, NULL, 'Air Pressure Multiplier No.2', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Peter', NULL, 'EXTERNAL', '2025-09-23 17:36:32', '2025-09-25 18:52:56', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ben', NULL, 'EXTERNAL', '2025-09-23 17:36:32', '2025-09-25 18:52:56', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
