-- Inserting report ID 37177
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS GC shows Preamp input out of range alarm', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-09-25', '<p><u><b>Activity,</b></u></p><p>-TS GC shows Preamp input out of range alarm. (AT-46001) _ Day-1</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-Gas Chromatograph Analyzer AT-46001, Cooler Deck.</p><p><u><b>As found,</b></u></p><p>-Carrier gas helium cylinder No.1 = 0 Psi, Cylinder No.2 = 0 Psi.</p><p>-Cylinder No.1 replaced on 17-09-2025.</p><p><u><b>What happen,</b></u></p><p>-Alarm occur due to no carrier gas.</p><p><u><b>Action,</b></u></p><p>-Replaced helium cylinder No.2 with new cylinder.</p><p>-After replaced, performed leak test the whole loop start from cylinder head to the GC analyzer unit.</p><p>-Found 3 seeping/Leak point.</p><p>&nbsp; &nbsp; - 1st point - Regulator outlet fitting.</p><p>&nbsp; &nbsp; - 2nd point - 4-way cross union fitting at the inlet of the GC Oven No.1.</p><p>&nbsp; &nbsp; - 3rd point - GC oven No.1 6-ports valve.</p><p>-Fixed the seeping/leak point.</p><p>-Adjusted the helium cylinder No.2 = 110 Psi. (cylinder pressure = 2200Psi)</p><p>-Replaced helium cylinder No.1 and adjusted the pressure = 105Psi but close the cylinder back after adjusted the pressure in order to prevent both cylinders loss pressure.</p><p>-Checked the GC status at ITR room metering cabinet. (No alarm)</p><p><u><b>As left,</b></u></p><p>-Unit under monitoring.</p><p>-Only helium cylinder No.2 was in duty (cylinder pressure = 2200 Psi).</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-Both empty cylinder was store at the cylinder rack at cooler deck. (Put empty tag on both cylinder)</p><p><u><b>Next plan,</b></u></p><p>-Inform Team lead to inform night shift operator to monitor the Helium cylinder No.2 pressure.</p><p>-If cylinder pressure suddenly drop, will check the leak point again.</p><p>-If the cylinder pressure was ok, will online the helium cylinder No.1 as a stand by unit.</p><p><u><b>Documentation,</b></u></p><p>-In progress.</p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-Under monitoring</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-09-25_AT-46001,GC Alarm', '2025-09-25 17:38:12', '2025-10-01 17:07:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-AT-46001', 'ZTK-AT-46001', 'GC Analyzer Trans,M-4600,CH,CO2,N2 IND', NULL, NULL, 'GC Analyzer Trans,M-4600,CH,CO2,N2 IND', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Francis', NULL, 'EXTERNAL', '2025-09-25 17:38:12', '2025-10-01 17:07:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2025-09-25 17:38:12', '2025-10-01 17:07:53', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

