-- Inserting report ID 37199
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S EDG cannot run due to louver actuator defect', 'Electrical & Instrument', 'CM ', 'Completed', '2025-09-27', '<p><b><u>Activity,</u></b></p>  <p>-T/S EDG-7200 cannot run due to louver actuator defective.</p>  <p><b><u>History,</u></b></p>  <p>-Continued from 26-09-25.</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Emergency diesel gen, Lower deck</p>  <p><b><u>As found,</u></b></p>  <p>-Louver 2 was not opened.</p>  <p><b><u>What happen,</u></b></p>  <p>-Actuator for louver 2 was defective.</p>  <p><b><u>Action,</u></b></p>  <p>-Removed the support of the louver actuator and weld the nuts to the body for support nut and actuator nut.</p>  <p>-Opened the old actuator and investigated the situation. Found the pinion for the main drive was defective with two broken parts.</p><p>-Checked the condition of spare with manual open and close. (normal)</p><p>-Reinstalled the support and the actuator.</p><p>-The actuator support nuts were difficult to align because of the welded nut.</p><p>-Normalized the wiring for status. Exercise two times with force signal from UCP.</p><p>-Run EDG to check condition. (no abnormal)</p>  <p><b><u>As left,</u></b></p>  <p>-Normal condition.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-Tool bag is still kept at EDG to continue electrical PM.</p>  <p><b><u>Next plan,</u></b></p>  <p>-To continue to investigate the old actuator and monitor the action of new spare at the package.</p>  <p><b><u>Documentation,</u></b></p>  <p>-N/A</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-09-27_EDG-7200, TS outlet louver no.2 defective', '2025-09-27 18:50:37', '2025-10-27 11:19:36', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EDG-7200', 'ZTK-EDG-7200', 'Emergency Diesel Generator Package', NULL, NULL, 'Emergency Diesel Generator Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'James', NULL, 'EXTERNAL', '2025-09-27 18:50:37', '2025-10-27 11:19:36', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2025-09-27 18:50:37', '2025-10-27 11:19:36', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO spare (report_id, action, mesc, detail, qty, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Withdraw', '77.88.14.110.3', 'T/S EDG cannot run due to louver actuator defect', '0', '2025-10-27 11:19:36', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL);
