  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Clean and increase liner quantity', 'Mechanic', 'OTH ', 'Completed', '2025-09-28', '<p>Job Scope&nbsp; &nbsp;-Remove top cover and flange and remove old liners.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Cleaned top cover and flange and remove all liners ( 15 Dummy + 16 liners)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Found 4 liners broken and sand 50% tank.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Increase liner quantity ( 16+7 liners &amp; 8 Dummy)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Install 2 new top cover flange gaskets.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Tighten torque to cyclone cover flange to 380 N-m.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Tighten torque to the outlet flange is 240 N-m.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Test by Nitrogen pressure 3 bars and found no leak.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Test by process pressure @23 bars found no leak.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -Housekeeping the area.</p><p><br></p><p>Require Tools&nbsp;</p><p><br></p><table class="table table-bordered"><tbody><tr><td>Spanner 41mm&nbsp;</td><td>SPW gasket&nbsp; 6" #300&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td></tr><tr><td>Heavy socket 41 mm&nbsp;</td><td>Special Gasket for top cover flange</td></tr><tr><td>Spanner 11/16 inch</td><td>&nbsp;Ply bar</td></tr><tr><td>L-Key 10 mm</td><td>Chain block 1 ton - 3 EA</td></tr><tr><td>Spanner 1 1/4 inch</td><td>Bean Clamp 1 EA</td></tr><tr><td>Socket 1 1/4 inch&nbsp;</td><td>Shackle 5/8 -5 EA and Web Sling 1 ton - 5 EA&nbsp;</td></tr></tbody></table><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\61 PRODUCED WATER\\HC-6100\\2025\\2025-09-28 Clean and inspect liner">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\61 PRODUCED WATER\\HC-6100\\2025\\2025-09-28 Clean and inspect liner</a><br></p>', '2025-09-28 15:43:07', '2025-09-29 08:37:01', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
