  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS dumb waiter door malfunction', 'Mechanic', 'CM ', 'Completed', '2025-09-29', '<p><b><u>2025-09-29</u></b></p><p><br></p><p>Problem : Lift door is stuck and cannot close as well.</p><p>Found : Door lifting chain is stuck with roller-gear teeth(right side).</p><p>Action : Cleaned the old grease between chain and roller-gear teeth.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Aligned the chain and roller-gear teeth for proper operation.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Exercise the door and greasing along the chain and roller-teeth for smooth operation.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Unit back in service.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\73 LIVING QUATER EQUIPMENT &amp; SEWAGE TREATMENT UNIT\\2025\\2025-09-29 TS dump waiter door malfunction">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\73 LIVING QUATER EQUIPMENT &amp; SEWAGE TREATMENT UNIT\\2025\\2025-09-29 TS dump waiter door malfunction</a><br></p>', '2025-09-29 18:19:34', '2025-09-29 21:44:08', 'PTTEP\\ZPQ.Cmms-Tech', 'PTTEP\\ZPQ.Mechanical-TeamL', false, 'ZTK') RETURNING id INTO new_report_id;
