  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S alarm page is not working in fire water pump 2', 'Automation', 'CM ', 'In Progress', '2025-09-29', '<p><u><b>Activity,</b></u></p><p>- T/S alarm page is not working in fire water pump no.2.</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-HMI, LCP-CPP-6710, Lower Deck.</p><p><u><b>As found,</b></u></p><p>-HMI is not working at "Alarm" page when "Alarm" page is selected.</p><p><u><b>What happen,</b></u></p><p>-Project file needs to configure parameter for "Alarm" and "Event" page.</p><p><u><b>Action,</b></u></p><p>-(1) Reset the HMI and checked all parameters and HMI screen page.</p><p>-(2) Other pages are working but "Alarm" and "Event" page are not working.</p><p>-(3) Download the project file with version.7,8,9,10 and 11.</p><p>-(4) "Alarm" and "Event" page are not working.</p><p></p><p><u><b>As left,</b></u></p><p>-"Alarm" and "Event" page are not working but other pages are working.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-NA</p><p><u><b>Next plan,</b></u></p><p>-Check, reconfigure and rebuild the parameter for "Alarm" and "Event" page in the project file.</p><p><u><b>Documentation,</b></u></p><p>-N/A</p><p>-Link ()</p><p><u>Job progress,</u></p><p>-50%</p>', NULL, '2025-09-29 18:29:46', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
