-- Inserting report ID 37219
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS crane cannot boom down and SLI error', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-09-29', '<p><u><b>Activity,</b></u></p><p>-TS crane cannot boom down and SLI reading error.CR-1373.</p><p><u><b>History,</b></u></p><p>-N/A</p><p><u><b>Equipment description and location,</b></u></p><p>-Crane Column, CR-1373, WP-13</p><p><u><b>As found,</b></u></p><li data-start="81" data-end="232"><p data-start="83" data-end="232">-As the Well Service team, the crane could not boom down. The load cell reading was incorrect, and the angle display was inaccurate.</p> </li><p> </p><li data-start="233" data-end="297"> <p data-start="235" data-end="297">-The crane battery voltage was found to be low (flattened).</p></li><p><u><b>What happen,</b></u></p><p>-PLC error is suspected.</p><p><u><b>Action,</b></u></p><p>-Checked the battery voltage and found it to be low at 8.66 VDC.</p> <li data-start="168" data-end="285"> <p data-start="170" data-end="285">-Inspected the condition of the junction boxes inside the power pack and cabin; no abnormal findings observed.</p> </li> <li data-start="286" data-end="370"> <p data-start="288" data-end="370">-Started the engine and checked the PLC status; no fault alarms were present.</p> </li> <li data-start="371" data-end="468"> <p data-start="373" data-end="468">-Verified the load cell with an actual load of 4 tons, but the HMI displayed 2.4 tons.</p> </li> <li data-start="469" data-end="561"> <p data-start="471" data-end="561">-Checked the angle sensor; the actual angle was 30°, but the HMI displayed 49.5°.</p> </li> <li data-start="562" data-end="661"> <p data-start="564" data-end="661">-Measured alternator voltages: Alternator No.1_39.25 VDC, Alternator No.2 _28.25 VDC.</p> </li> <li data-start="662" data-end="776"> <p data-start="664" data-end="776">-Function tested the crane''s boom, slew, and hoist limit switches that all operated within normal conditions.</p></li><p><u><b>As left,</b></u></p><p>-Crane is available but with load cell and angle sensor errors.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-All tools and equipment have been returned to their designated areas.</p><p><u><b>Next Plan,</b></u></p><p>-Plan to replace the batteries and calibration the load cell.</p><p><u><b>Documentation,</b></u></p><p>-N/A.</p><p><u><b>Job Progress,</b></u></p><p>-50% complete</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-09-29_CR-1373, TS crane cannot boom down and SLI reading error', '2025-09-29 21:55:19', '2025-09-30 12:25:42', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-1373-EN', 'ZTK-CR-1373-EN', 'Pedestal Crane Diesel Engine WP13', NULL, NULL, 'Pedestal Crane Diesel Engine WP13', 'WP13', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2025-09-29 21:55:19', '2025-09-30 12:25:42', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Francis', NULL, 'EXTERNAL', '2025-09-29 21:55:19', '2025-09-30 12:25:42', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
END $$;

