  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS GC shows Preamp input 1 out of range alarm.', 'Electrical & Instrument', 'CM ', 'Completed', '2025-10-01', '<p><u><b>Activity,</b></u></p><p>-TS GC shows Preamp input 1 out of range alarm. (AT-46001) _Day-3</p><p><u><b>History,</b></u></p><p>-Continue from 30-09-2025.</p><p><u><b>Equipment description and location,</b></u></p><p>-Gas Chromatograph Analyzer AT-46001, Cooler Deck.</p><p><u><b>As found,</b></u></p><p>-GC have alarm.</p><p><u><b>What happen,</b></u></p><p>-Alarm occur due to no carrier gas.</p><p><u><b>Action,</b></u></p><p>-Half the GC.</p><p>-Performed leak check the carrier gas line as per the Daniel GC model 500 manual. (Still have leak)</p><p>-Checked leak the carrier gas line section by section.</p><p>-The leak was found at the Flow Panel at the Oven-1.</p><p>-Flow Panel have 2 equipment, Regulator and Pressure gauge.</p><p>-Removed the Regulator form the flow panel and performed pressure test. (No leak)</p><p>-Removed the Pressure gauge form the flow panel and performed pressure test, found leakage at the pressure gauge bellow.&nbsp;</p><p>-Replaced with the new pressure gauge and normalized the all the section that have been removed.</p><p>-Performed leak check the carrier gas line as per the manual again. (No leak)</p><p>-Put the GC to auto analysis.</p><p><u><b>As left,</b></u></p><p>-Unit available but mole low alarm will occur due to the oven temperature change while performing leak test</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><u><b>Next plan,</b></u></p><p>-Keep the GC running until tomorrow in order to get the oven temperature back to normal.</p><p>-Performed calibration.</p><p><u><b>Documentation,</b></u></p><p>-In progress.</p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-In Progress</p>', NULL, '2025-10-01 18:00:38', '2025-10-11 17:25:45', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-AT-46001', 'ZTK-AT-46001', 'GC Analyzer Trans,M-4600,CH,CO2,N2 IND', NULL, NULL, 'GC Analyzer Trans,M-4600,CH,CO2,N2 IND', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
