  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S blower fail to start', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-10-02', '<p><b>Activity,</b></p><p>-T/S blower fail to start, B-8745B.</p><p><b>History,</b></p><p>-On 25/Sep/2025, blower fan fail to start during changeover the galley supply fan unit B to A.</p><p><b>Equipment description and location,</b></p><p>-Galley Supply Fan,LQM Level-2</p><p><b>As found,</b></p><p>-HDP-86108, Pneumatic damper closed and can''t run the B-8745B.</p><p>-Found instrument supply air pressure gauge defective for HPDs actuator.</p><p>-HPD''s actuator was stuck when opening.</p><p><b>What happen,</b></p><p>-The damper is not able to open.</p><p><b>Action,</b></p><p>-Performed manual exercise to the pneumatic damper actuator.&nbsp;</p><p>-HPD-86108 by manually force to open and performed the blower unit test run,&nbsp;B-8745B is running</p><p>-Replaced the hot spare pressure gauge for regulator.</p><p>-Found the regulator was working properly and can set the pressure.</p><p>-Performed function test HPD with instrument supply around 6 bar and found HPD cannot open properly.</p><p>-Performed exercise the damper by manually and found damper was slightly tight.</p><p>-Removed the HPD''s actuator.</p><p><b>As left,</b></p><p>-B-8745B is running properly and job is in progress for HPD-86106.</p><p><b>Next Plan,</b></p><p>-Plan to verify the actuator for HPD-86106 at workshop.</p><p>-Plan to verify and exercise the damper.</p><p><b>Documentation,</b></p><p>-NA</p><p><b>Job Progress,</b></p><p>-In progress.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-10-02_B-8745B, TS blower fail to start">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-10-02_B-8745B, TS blower fail to start</a><br></p>', '2025-10-02 15:55:49', '2025-10-02 19:27:57', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
