  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S blower fail to start', 'Electrical & Instrument', 'CM ', 'Completed', '2025-10-03', '<p><b>Activity,</b></p><p>-T/S galley supply air blower fail to start, B-8745B.</p><p><b>History,</b></p><p>-On 25/Sep/2025, blower fan fail to start during changeover the galley supply fan unit B to A.</p><p>-Continued from 02-10-2025.</p><p><b>Equipment description and location,</b></p><p>-Galley Supply Fan,LQM Level-2</p><p><b>As found,</b></p><p>-HDP-86108, Pneumatic damper closed and can''t run the B-8745B.</p><p>-Found instrument supply air pressure gauge defective for HPDs actuator.</p><p>-HPD''s actuator was stuck when opening.</p><p><b>What happen,</b></p><p>-The damper is not able to open.</p><p><b>Action,</b></p><p>-Verified and function test the the actuator at workshop.</p><p>-Found the actuator was working properly.</p><p>-Performed exercise the damper by manually.(OK)</p><p>-Installed the HPD''s actuator back and performed function test HPD with instrument supply around 5 bar.</p><p>-Found HPD-86106 open properly by auto change mode.</p><p><b>As left,</b></p><p>-Both B-8745B is running and HPD-86106 is working properly.</p><p><b>Next Plan,</b></p><p>-NA</p><p><b>Documentation,</b></p><p>-NA</p><p><b>Job Progress,</b></p><p>-Completed.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-10-03_B-87415B, TS blower cannot start">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-10-03_B-87415B, TS blower cannot start</a><br></p>', '2025-10-03 14:52:52', '2025-10-03 17:30:10', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
