  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'GTC#2 tripped by GB HS NDE bearing temp failure', 'Electrical & Instrument', 'CM ', 'Completed', '2025-10-03', '<p><b><u>Activity,</u></b></p>  <p>-TS GTC#2 tripped by Gearbox high speed shaft NDE bearing temp failure,TE-43209A</p>  <p><b><u>History,</u></b></p>  <p>-NA</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Gearbox high speed shaft NDE bearing temperature RTD sensor, Upper Deck</p>  <p><b><u>As found,</u></b></p>  <p>-TE-43209A,Temperature value at UCP HMI show -200 degC</p>  <p><b><u>What happen,</u></b></p>  <p>-RTD sensor cable at local JB (USBN-CPP-4327) was loosen.</p><p><b><u>Action,</u></b></p>  <p>-Tightened the loosen cable and check tightness of cable termination at USBN-CPP-4327.</p><p>-Temperature parameter of TE-43209A are back to normal.</p><p>-CCR can start GTC-4300 at 16:27 PM and ready to load at 16:37 PM.</p><p><br></p><p>Note: BDV-43356, Fuel gas supply blowdown valve command disagree alarm status show during unit is stopping. Check and exercise the valve open/close. Found open proximity switch was defective. Replace new proximity switch.</p>  <p><b><u>As left,</u></b></p>  <p>-GTC-4300 back to normal.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-NA</p>  <p><b><u>Next plan,</u></b></p>  <p>-NA</p>  <p><b><u>Documentation,</u></b></p>  <p>-NA</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-10-03_GTC-4300, TS GTC#2 tripped by TE-43209A GB&nbsp; HS NDE temp high', '2025-10-03 19:14:52', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
