  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Level transmitter mismatch with actual level', 'Electrical & Instrument', 'CM ', 'Completed', '2025-10-06', '<p><u><b>Activity,</b></u></p><p>-LT-03921, T/S Level transmitter mismatch with actual toke tank''s level.</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-Level transmitter at CI tank,WP-03</p><p><u><b>As found,</b></u></p><p>-LT show 56.5% and actual tank level was around 25%.</p><p><u><b>What happen,</b></u></p><p>-Level transmitter mismatch with actual level.</p><p><u><b>Action,</b></u></p><p>-Verified the level transmitter with HART.</p><p>-Verified the CI line is block or air trap and found normal.</p><p>-Found the 2" ball valve was tight and valve handle was broken for the LT''s sensing tubing line.</p><p>-Removed the valve and reinstalled the 1/2" SWAGELOK valve.</p><p>-As found&nbsp;LRV-1435 mmH2O and URV-2965mmH2O.</p><p>-Calibrated the LT with actual tank level and recorded tank level 0%, 50% and 100%.</p><p><span style="background-color: rgb(181, 214, 165);">-As left&nbsp;&nbsp;LRV-1934 mmH2O and URV-3474 mmH2O.</span></p><p><span style="background-color: rgb(181, 214, 165);">-After calibrated and changed the range and LT showed 23.6%.</span></p><p>-Monitoring the LT reading around 30 mins.</p><p>-Found LT reading was stable and matched with actual tank level.</p><p><u>As left,</u></p><p>-LT-03921 is back to service.</p><p><u>Material/Equipment/Tool status,</u></p><p>-NA</p><p><u>Next plan,</u></p><p>-NA</p><p><u>Documentation,</u></p><p>-NA</p><p>-Link ()</p><p><u>Job progress,</u></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-10-06_LT-03921_TS level mismatch with local and HMI', '2025-10-06 22:28:52', '2025-10-06 22:36:51', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LT-03921', 'ZTK-LT-03921', 'LT for T-0398A/B ALM L /LL with ESD 3E', NULL, NULL, 'LT for T-0398A/B ALM L /LL with ESD 3E', 'WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
