  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS sump pump low performance and function test', 'Mechanic', 'CM ', 'Completed', '2025-10-08', '<p>TS sump pump low performance and function test</p><p><br></p><p><u>Action</u></p><p><br></p><p>-Visual check external leak and piping joints are Leaking or not&nbsp;</p><p>-Run the unit by opening IG-SDV from CCR (IG pressure ~ 2.8 bar)</p><p>-The pump didn''t run&nbsp;</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">**Found that Drive section Allan bolts are missing and forming gap between drive section and pump body**</span></p><p><br></p><p>-Isolate the unit and Remove the defective pump&nbsp;</p><p>-Remove all the connections from defective pump to&nbsp;overhauled HOT SPARE</p><p>-Installed the piping and flange joints to New Pump (overhauled hot spare)</p><p>-Deisolate the unit and run the unit.<span style="background-color: rgb(0, 255, 0);">(found no leak and run normal)</span></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style="background-color: rgb(0, 255, 0);">&nbsp;IG supply pressure (~2.5 Bar)&nbsp;</span></p><p><span style="background-color: rgb(0, 255, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Pump Dis Pressure (~ 29 Bar)</span></p><p><span style="background-color: rgb(0, 255, 0);">&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;Globe v/v position ~ 45 Degree From fully close to open position.</span></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP10\\Sump Pump\\2025\\2025-Oct-08 Replace Defective sump pump with Overhaul Spare">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\02 ZWP\\ZWP10\\Sump Pump\\2025\\2025-Oct-08 Replace Defective sump pump with Overhaul Spare</a><br></p>', '2025-10-08 20:17:15', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-P-1052', 'ZTK-P-1052', 'Sump Pump Deliver from V-1051 to ZPQ', NULL, NULL, 'Sump Pump Deliver from V-1051 to ZPQ', 'WP10', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
