  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Shutdown Valve Show Travelling ', 'Electrical & Instrument', 'CM ', 'Completed', '2025-10-08', '<p><b><u>Activity,</u></b></p>  <p>-TS shut down valve SDV-10010 show travelling when command open.</p>  <p><b><u>History,</u></b></p>  <p>-NA</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Shut down valve between production manifold and test manifold, WP-10</p>  <p><b><u>As found,</u></b></p>  <p>-Found that valve is fully close at local but feedback show travelling for open command.</p>  <p><b><u>What happen,</u></b></p>  <p>-Valve show travelling when command open.</p>  <p><b><u>Action,</u></b></p>  <p>-Performed function test with CCR for investigation.</p>  <p>-Found that the positioner feedback show travelling in valve open position.</p><p>-Checked the positioner limit switches and magnet.</p><p>-Found the magnet for open position misaligned with limit switch.</p><p>-Adjust the magnet position, checked and tightened all cable terminations.</p><p>-Performed function test with CCR with success.</p><p><b><u>As left,</u></b></p>  <p>-SDV-10010 is back to normal operation.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-NA</p>  <p><b><u>Next plan,</u></b></p>  <p>-NA</p>  <p><b><u>Documentation,</u></b></p>  <p>-NA</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-10-08_SDV-10010, TS flow switch low low alarm is not cleared', '2025-10-08 20:20:07', '2025-10-08 20:31:33', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
