  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS Deluge valve unable to open', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-10-20', '<p><b><u>&nbsp;Activity,</u></b></p>  <p>-Deluge valve XV-67907 for zone 303 sea deck assembly unable to open during weekly FWP test run.&nbsp;&nbsp;</p>  <p><b><u>History,</u></b></p>  <p>-NA</p>  <p>-</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Deluge valve for zone 303 sea deck assembly, Lower Deck</p>  <p><b><u>As found,</u></b></p>  <p>-Found that valve unable to open during test run.</p>  <p><b><u>What happen,</u></b></p>  <p>-Valve stuck in close position.</p>  <p><b><u>Action,</u></b></p>  <p>-Removed the tubing from PCV outlet to confirm control system able to release pressure from diaphragm.</p>  <p>-Confirmed that control system can release pressure from diaphragm chamber properly, but valve unable to open.</p><p>-Valve stuck at close position even opened the drain plug from the diaphragm chamber.</p><p>-MECH team performed bore scope inspection for diaphragm and internal part.</p><p>-Closed the restrictor to prevent inlet water pressure to diaphragm chamber.</p><p>-Opened the supply valve and water come out from diaphragm chamber.</p><p>-It proved that the diaphragm damage.</p>  <p><b><u>As left,</u></b></p>  <p>-Deluge valve XV-67907 is out of service.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-NA</p>  <p><b><u>Next plan,</u></b></p>  <p>-MECH team will check the spare availability.</p>  <p><b><u>Documentation,</u></b></p>  <p>-NA</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-50%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-10-20_XV-67903 Delgue valve stuck at close position', '2025-10-20 16:02:25', '2025-10-20 17:45:47', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-XV-67907-ASSY', 'ZTK-XV-67907-ASSY', 'Deluge Valve Zone 303 Sea Deck Assy', NULL, NULL, 'Deluge Valve Zone 303 Sea Deck Assy', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2025-10-20 16:02:25', '2025-10-20 17:45:47', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
