BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist Z1E - Brownfield modification.', 'Automation', 'MD ', 'In Progress', '2025-10-20', '<p><u>&nbsp;<b>Activity,</b></u></p><p>-Assist Z1E - Brownfield modification. (Day-15)</p><p><u><b>History,</b></u></p><p>-Continued job from 19 Oct 2025.</p><p><u><b>Equipment description and location,</b></u></p><p>-ZTK-SC-SCADA: Zawtika SCADA system (Automation Room)</p><p>-Sand Monitoring System (CCR).</p><p>-PLC Gateway implementation.</p><p><u><b>As found,</b></u></p><p>-NA</p><p><u><b>What happen,</b></u></p><p>-NA</p><p><u><b>Action,</b></u></p><p><u><font color="#0000ff">ZPQ SCADA and Fast tools System Modification</font></u></p><p><font color="#ff00ff">-Add UGS tag number for Phase1E at PCS.</font></p><p><font color="#ff00ff">-Performed online download tag from PCS.</font></p><p>History,</p><p>-Performed Online signal function test for IP-2 loop and IP-7 loop.</p><p>&nbsp; &nbsp; &gt;&nbsp;For IP-2 loop, Function test completed and no abnormal found.</p><p>&nbsp; &nbsp; &gt;For IP -7 loop, Function test completed.</p><p>Found US-07911 (ESD 2CA) MOD request signal from SCADA mapping was duplicate.</p><p>Need to add new mapping and function test for MOD Request.</p><p>-Checked communication link between PLC gateway and Fast tool.</p><p>&nbsp;( Dry test for WP-16, WP-17,WP-18,WP-19) completed.</p><p><br></p><ul><li>Continued to perform Online Edit: Add Item (Tags configuration) related with existing WP.</li></ul><ul><li>Continued to perform Database import, object and graphic to exiting running system&nbsp;</li></ul><p>(Z1E Latest FAT: WP16,17,18,19)</p><ul><li>Continued to re-arrange and adjust program hierarchy and graphic to alight with existing database</li></ul><ul><li>Continued to perform OPC Tags import for New Sand Monitoring and configure communication routing</li></ul><ul><li>Continued to perform OPC Tags import and re-alight address for PI system &amp; Alarm</li></ul><p>management system&nbsp;</p><p><br></p><p><font color="#0000ff"><u>ZPQ New sand server system installation and existing sand server migration</u>&nbsp;</font></p><p><font color="#ff00ff">-Put manual key-in value at SCADA server 1D and compare value with New Sand Server.</font></p><p><font color="#ff00ff">-Checked flow parameter for following well data,</font></p><p><font color="#ff00ff"><b>Gas,Oil,Water,Temperature and Pressure&nbsp;</b></font></p><p><font color="#ff00ff"><b>Completed for WP-01 to WP-06.</b></font></p><p>History,</p><p>-Check Data mapping between New Sand Server and SCADA system.</p><p>-Check Data conversion calculation between SCADA system and Sand Server.</p><p>Connect LAN cable at SCADA PLC Gateway Cabinet.</p><p>Waiting to perform function test and communication test between SCADA 1D and New Sand Server.</p><ul><li>Continued to perform Running New sand Server &amp; Existing Server then verify communication status and Field Watch configuration&nbsp;</li></ul><ul><li>Continued to perform new sand server function testing (Data comparison test between new sand server and existing sand server of Z1A, Z1B, Z1C and Z1D)</li><li><br></li><li><u><font color="#0000ff">Back up and Updated HMI configuration for WP-01 to WP-15.</font></u></li><li><u><br></u></li><li>-Performed online download for OPS station at CCR.(Completed)</li><li>-Checked communication link between PLC gateway and Fast tool.(Completed)</li><li>-Add New tag for WP-16 to WP-19 at PLC gateway.(Completed)</li><li>-Performed online uploading existing running HMI configuration file.</li><li>-Compared existing configuration HMI with Updated one.</li></ul><p><br></p><p><u><font color="#0000ff">PLC Gateway Implementation for WP-16 t oWP-19</font></u></p><p><br></p><p>-Performed function test between WP-17,PLC gateway and SCADA System.</p><p>&nbsp; &nbsp; &gt;Function test completed for ESD1A at WP-16 as per PLC logic.(Completed)</p><p>-Performed function test between WP-19,PLC gateway and SCADA System.</p><p>&nbsp; &nbsp; &gt;Function test completed for ESD1A at WP-17 as per PLC logic.(Completed)</p><p>-WP13 Inter-trip signal for incoming ESDV-13221 and ESDV-13215.</p><p>Performed online logic implementation and function test.</p><p>-All PLC Logic working properly.</p><p><u><br></u></p><p>History,</p><p>-Performed function test between WP-16 ,PLC Gateway and SCADA system.</p><p>&nbsp; &nbsp; &gt; Function Test Signal dry test for ESD1A as per PLC logic.(Completed)</p><p>-Performed function test between WP-18 , PLC Gateway and SCADA System.</p><p>&nbsp; &nbsp; &gt; Function Test Signal dry test for ESD1A as per PLC logic (Completed).</p><p></p><p><u><b>As left,</b></u></p><p>-NA</p><p><u><b>Next Plan</b>,</u></p><p>-Continue Z1E-Brownfield modification.</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job Progress,</b></u></p><p>-InProgress</p>', NULL, '2025-10-21 11:05:19', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Automation', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SC-SCADA', 'ZTK-SC-SCADA', 'Zawtika SCADA system', NULL, NULL, 'Zawtika SCADA system', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
