-- Inserting report ID 37463
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS abnormal noise from waste food grinder', 'Mechanic', 'CM ', 'Completed', '2025-10-22', '<p>Problem: Abnormal noise from rotating grinder touching with stator teeth.</p><p><br></p><p>Action:</p><p><br></p><p>21-10-2025</p><p>Possible bearing damage.</p><p>Remove the package cover.</p><p>Remove the top baffle connector.</p><p>Remove the control box.</p><p>Loosen the motor mounting bolts and remove the belt.</p><p>Belt condition is still good.</p><p>Remove the Middle connector and offset inlet.</p><p>Remove the pump body including rotor and chamber.</p><p>Remove the outlet connector.</p><p>Found some residual food and clean them.</p><p>Found lower bearing assembly is seem to be damaged.</p><p><br></p><p>22-10-2025</p><p>Removed the pulley sprocket and bottom bearing. bottom plate assembly.</p><p>Found stuck food waste with roller bearing pieces from the top seal bearing.</p><p>Top seal bearing is damaged and broken into pieces.</p><p>The shaft is rotation only with the bottom bearing and the food crusher blade is rotating with abnormal noise.</p><p>Prepared the new set of food waste grinder.</p><p>Installed the new food waste grinder set together with bottom bearing and new pulley sprocket.</p><p>Installed the belt and adjusted tension, tightened the motor mounting bolts.</p><p>Connected the outlet connector, top baffle connector, connected the water inlet line.</p><p>Installed the package frame.</p><p>Installed the control box.</p><p>Deisolate and test run.</p><p>Running normal and test with some food waste, function properly.</p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\115 LQM Utility\\Waste Food Grinder\\2025\\2025-10-21 Abnormal noise food waste grinder">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\115 LQM Utility\\Waste Food Grinder\\2025\\2025-10-21 Abnormal noise food waste grinder</a><br></p>', '2025-10-21 18:21:26', '2025-10-22 17:37:22', 'PTTEP\\ZPQ.Cmms-Tech', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WD03-ASSY', 'ZTK-WD03-ASSY', 'Waste Food Grinder Assembly', NULL, NULL, 'Waste Food Grinder Assembly', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WD03', 'ZTK-WD03', 'Waste Food Grinder', NULL, NULL, 'Waste Food Grinder', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kaung', NULL, 'EXTERNAL', '2025-10-21 18:21:26', '2025-10-22 17:37:22', 'PTTEP\\ZPQ.Cmms-Tech', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2025-10-21 18:21:26', '2025-10-22 17:37:22', 'PTTEP\\ZPQ.Cmms-Tech', 'PTTEP\\ZPQ.Mechanical-Works');
