  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-XV-67907-ASSY', 'ZTK-XV-67907-ASSY', 'Deluge Valve Zone 303 Sea Deck Assy', NULL, NULL, 'Deluge Valve Zone 303 Sea Deck Assy', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
