  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist to troubleshoot Mobile Air Compressor', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-10-22', '<div><u><b>Activity,</b></u></div><div><p>-Assist MECH team to troubleshoot Mobile Air Compressor at lower deck.</p><p><u><b>History,</b></u></p><p>-N/A</p><p><u><b>Equipment description and location,</b></u></p><p>-ZTK-AC-WP-001, Rig Safe Diesel Air Compressor</p><p><u><b>As found,</b></u></p><p>-Air compressor''s engine crank and cannot start.</p><p><u><b>What happen,</b></u></p><p>-Found water in the fuel line.</p><p><u><b>Action,</b></u></p><p>-Checked the battery and measured the voltage was 12.3 Vdc.</p><p>-Removed the fuel pre filter and found water in the line.</p><p>-Found the water in the fuel tank.</p><p>-Removed the battery to drain and flush the fuel tank.</p><p><u><b>As left,</b></u></p><p>-Mobile air compressor cannot start and work is in progress.</p><p><u><b>Next Plan,</b></u></p><p>-Will plan to flush the tank and will install back the battery.</p><p><u><b>Documentation,</b></u></p><p>-Link:&nbsp;</p><p><u><b>Job Progress,</b></u></p><p>-In progress.</p></div>', NULL, '2025-10-22 15:09:57', '2025-10-22 17:14:32', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
