DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS mobile air com pressor cannot run', 'Mechanic', 'CM ', 'Completed', '2025-10-23', '<p><u>TS mobile air com pressor cannot run</u></p><p><u><br></u></p><p><u>2025-OCT-22</u></p><p><u><br></u></p><p>-Check Battery&nbsp;Voltage <span style="background-color: rgb(255, 255, 0);">(12.4 Vdc) </span>(normal)</p><p>-Start the engine with normal start (<span style="background-color: rgb(255, 255, 0);">Not Run</span>)</p><p>-Check electrical connection to make sure there is no loosen point</p><p>-Then start engine again (<span style="background-color: rgb(255, 255, 0);">Not Run</span>)&nbsp;</p><p>-check <span style="background-color: rgb(255, 255, 0);">fuel water separator and fuel filter</span></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Found a water ingress inside Diesel fuel filter and Diesel day tank.</p><p>-Dismantle enclosure cover for removal of Diesel day tank</p><p>-Remove battery to drain and flush the fuel tank</p><p>-Remove diesel tank and found water and sludge&nbsp;</p><p>&nbsp;-To be continued next day (to clean the tank and check engine oil)</p><p><br></p><p>23-10-2025</p><p>-Cleaned the diesel tank and flush two times with new diesel.</p><p>-Bleed out the remaining diesel inside the engine diesel supply loop.</p><p>-Replaced the new primary fuel water separator.</p><p>-Replaced the new fuel filter.</p><p>-Reinstated the fuel tank at the compressor.</p><p>-Top up diesel to the thank about 90%.</p><p>-Checked the engine oil condition found good.</p><p>-Reconnected all the diesel fuel piping and fittings.</p><p>-Bleed out the air from the fuel filter, fuel separator and fuel return line from the injectors by manual fuel&nbsp; &nbsp;priming pump.&nbsp;</p><p>-Test crank the engine 4 times and at the 5th times engine start few seconds and stop again.</p><p>- After that battery voltage was 8.7 Volt and EI team will charge the battery.</p><p>-Tomorrow plan EI team will installed back the battery and mechanic team will T/S diesel fuel line.&nbsp;</p><p><br></p><p>24-10-2025</p><p>-EI team installed back new battery.</p><p>-Bleed out the from the diesel fuel line by fuel priming pump.</p><p>-Installed back the body side cover.</p><p>-Test run the compressor and found diesel leak from the diesel pipe connection of the primary diesel pump.</p><p>-Cut the damage part of the diesel hose and connect at the primary pump.</p><p>-Test run again the compressor, found no more leak and compressor was running normal.</p><p><br></p><p>&nbsp;</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\102 PORTABLE EQUIPMENTS\\Rig Safe Diesel Air Compressor\\2025\\2025-10-22 TS Mobile Air com cannot start">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\102 PORTABLE EQUIPMENTS\\Rig Safe Diesel Air Compressor\\2025\\2025-10-22 TS Mobile Air com cannot start</a><br></p>', '2025-10-22 17:54:59', '2025-10-27 21:49:14', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Cmms-Tech', false, 'ZTK') RETURNING id INTO new_report_id;
