-- Inserting report ID 37478
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S LT alarm fault high', 'Electrical & Instrument', 'CM ', 'Pending', '2025-10-22', '<p><b><u>Activity,</u></b></p>  <p>-T/S LT-07501 alarm fault high.</p>  <p><b><u>History,</u></b></p>  <p>-Continued from&nbsp; 02 May 2025 and 22 Apr 2025.</p>  <p>-</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Level transmitter at sump tank, Sump deck</p>  <p><b><u>As found,</u></b></p>  <p>-No signal alarm was displayed in transmitter.</p>  <p><b><u>What happen,</u></b></p>  <p>-Probe sensor was defective due to water ingress and aging.</p>  <p><b><u>Action,</u></b></p>  <p>-Checked the transmitter card and found no visible damage.</p><p>-Checked the transmitter power supply and found it was 16VDC. </p><p>-Removed one wire and measure the voltage again.(Found 24VDC).</p><p>-Replaced the transmitter module card and power module, checked the voltage and found same result.</p><p>-Removed the sensor from transmitter module and checked the supply voltage ( Found 24 VCD).</p><p>-It was confirmed that there was problem with sensor and it cannot sent the signal to transmitter. (Transmitter show "No Signal" message).</p><p>-Checked the sensor cable and found that some water ingress.</p>  <p>-Cleared water ingress and checked again (found same error).</p>  <p><b><u>As left,</u></b></p>  <p>-The fault still remains.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-NA</p>  <p><b><u>Next plan,</u></b></p>  <p>-Plan to replace with new sensor probe when the spare arrive.</p>  <p><b><u>Documentation,</u></b></p>  <p>-Na</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-60%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-10-22_LT-07501 TS level transmitter fault high', '2025-10-22 22:36:52', '2025-10-22 22:52:04', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-LT-07501', 'ZTK-LT-07501', 'LT for V-0751 Alarm H/L Start/Stop P-075', NULL, NULL, 'LT for V-0751 Alarm H/L Start/Stop P-075', 'WP07', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2025-10-22 22:36:52', '2025-10-22 22:52:04', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Paing', NULL, 'EXTERNAL', '2025-10-22 22:36:52', '2025-10-22 22:52:04', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
