-- Inserting report ID 37486
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS mobile air com pressor cannot run', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-10-23', '<div><u><b>Activity,</b></u></div><div><p>-Assist MECH team to troubleshoot Mobile Air Compressor at lower deck.</p><p><u><b>History,</b></u></p><p>-Continued on 22/Oct/2025.</p><p><u><b>Equipment description and location,</b></u></p><p>-ZTK-AC-WP-001, Rig Safe Diesel Air Compressor</p><p><u><b>As found,</b></u></p><p>-Air compressor''s engine crank and cannot start.</p><p><u><b>What happen,</b></u></p><p>-Found water in the fuel line.</p><p><u><b>Action,</b></u></p><p>-Cleaned the diesel tank and flush two times with new diesel.</p><p>-Reinstated the fuel tank at the compressor.</p><p>-Top up diesel to the thank about 90%.</p><p>-Test crank the engine 4 times and at the 5th times engine start few seconds and stop again.</p><p>-Checked the battery and measured the voltage was 8.69 Vdc.</p><p>-Stopped the work and tomorrow will continue to troubleshoot.</p><p><u><b>As left,</b></u></p><p>-Mobile air compressor cannot start and work is in progress.</p><p><u><b>Next Plan,</b></u></p><p>-Will plan to replace the new battery and charge&nbsp;the old battery at workshop.</p><p>-Will MECH team troubleshoot the fuel line.</p><p><u><b>Documentation,</b></u></p><p>-Link:&nbsp;</p><p><u><b>Job Progress,</b></u></p><p>-In progress.</p></div>', NULL, '2025-10-23 18:20:51', '2025-10-23 18:24:26', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-AC-WP-001', 'ZTK-AC-WP-001', 'Rig Safe Diesel Air Compressor', NULL, NULL, 'Rig Safe Diesel Air Compressor', 'WP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Joseph', NULL, 'EXTERNAL', '2025-10-23 18:20:51', '2025-10-23 18:24:26', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2025-10-23 18:20:51', '2025-10-23 18:24:26', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
