  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replaced Internal parts of Deluge Valve XV67907', 'Mechanic', 'CM ', 'Completed', '2025-10-28', '<p>Problem&nbsp; : Valve was not open during FW pump weekly test run.</p><p>Found&nbsp; &nbsp; &nbsp;: The bladder the deluge valve was damaged.</p><p>Job Task : Prepared the lifting equipment.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Removed the deluge valve from it''s piping.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Separated the valve body''s parts by parts.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Removed the damaged tube diaphragm from the deluge valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Cleaned the internal parts of the valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Installed back the new tube diaphragm&nbsp;to the valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Reinstated the deluge valve body and tighten with torque 45ft.lb.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Installed back the deluge valve at it''s position and tighten with torque 120Nm by using new stud&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;bolts.</p><p>28-10-2025</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Perform process deisolation and leak test.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Perform function test by production team and found normal functioning.</p><p>&nbsp;&nbsp;</p>', NULL, '2025-10-27 18:30:13', '2025-10-29 07:45:54', 'PTTEP\\ZPQ.Mechanical-Crane', 'PTTEP\\ZPQ.Mechanical-TeamL', false, 'ZTK') RETURNING id INTO new_report_id;
