  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify secondary seal drain of comp DE PMO/I plan', 'Mechanic', 'CM ', 'Completed', '2025-11-11', '<p><u>Verify lube oil accumulation in secondary seal drain of GTC4400 compressor DE as per PMO/I way forward plan.</u></p><p><u><br></u></p><p><u>1) Check&nbsp; the drain line of coupling demisters and coupling</u></p><p>- Disconnect the hosing drain lines of coupling demister and blow by the air one point at a time.</p><p>- Found oil sludge at the drain line of coupling demister between engine and gearbox.</p><p>- Found small amount of dirt at the drain line of coupling demister between gearbox and compressor.</p><p>- Re-connect the drain lines.</p><p>- Borescope inside the coupling drain line and no abnormal found.</p><p><br></p><p><u>2) Check any restriction and cleanliness along the separation gas line.</u></p><p>- Performed Separation gas process isolation.</p><p>- Disconnect separation gas supply line tubing at DE and NDE side.</p><p>- Flush along the separation gas line by air.&nbsp;</p><p>- No abnormal found.</p><p>- Reconnect the tubing&nbsp;</p><p>- De-isolation and check for leakage. No leak found.</p><p><br></p><p><br></p><p><br></p>', NULL, '2025-11-11 18:14:41', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Turbi', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4400', 'ZTK-GTC-4400', 'Train 3,Gas Turbine Comp Package', NULL, NULL, 'Train 3,Gas Turbine Comp Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
