-- Inserting report ID 37660
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'HP LP element replacement due to Low Performance', 'Mechanic', 'CM ', 'Completed', '2025-11-20', '<p>Problem:</p><p>To replace HP LP elements due to low performance.</p><p><br></p><p>Action:</p><p>12-11-2025</p><p>Prepare tools and spare parts for replacement.</p><p>Erect scaffold shelf and install lifting gears for lifting HP LP.</p><p><br></p><p>13-11-2025</p><p>Removed the enclosure doors.</p><p>Removed all the sensors around the HP LP element by EI.</p><p>Removed the side enclosure frames, top enclosure covers.</p><p>Remove air intake flexible, inlet filter &amp; air system piping.&nbsp;</p><p>Remove inlet filter and intake flexible.&nbsp;</p><p>Remove the throttle valve.&nbsp;</p><p>Remove air piping of LP compressor suction and discharge.&nbsp;</p><p>Remove air piping of HP compressor suction and discharge.&nbsp;</p><p>Disconnect air piping between LP and HP interconnection.&nbsp;</p><p>Remove HP discharge silencer and check valve.&nbsp;</p><p>Remove the discharge connection bolts.&nbsp;</p><p>Lift out to outside of package with chain block.&nbsp;</p><p>Remove LP discharge silencer.&nbsp;</p><p>Disconnect connection bolts and lift out of package with chain block.&nbsp;</p><p>Remove HP/LP moisture drain trap.&nbsp;</p><p>Drain compressor oil and Disconnect oil system piping.&nbsp;</p><p>Drain the compressor oil from gearbox casing and oil cooler.&nbsp;</p><p>Disconnection the oil supply and return line.&nbsp;</p><p>Remove gearbox breather.&nbsp;</p><p>Remove LP element.&nbsp;</p><p>Prepare 24mm eye bolts x 2 and use lifting gear in attached.&nbsp;</p><p>Remove main bolts and pull out slowly.&nbsp;</p><p>Lift out to outside of package with chain block.&nbsp;</p><p>Remove HP element.&nbsp;</p><p>Prepare 10mm eye bolts x 1 and use lifting gear in attached.&nbsp;</p><p>Remove main bolts and pull out slowly.&nbsp;</p><p>Lift out to outside of package with chain block.&nbsp;</p><p>Moved from the Main Deck to Lower Deck by Crane.</p><p>Swap Gear Pinions for HP and LP screw elements. </p><p>Remove pinion gear from old screw element with special puller. (Before removal measure the distance to make sure)</p><p>(Note: bolt removing is Clockwise direction)&nbsp;</p><p>Reuse plug and tubing from old elements.</p><p>Prepare and arrange bearing heater.&nbsp;</p><p>Heat up the pinion gear up to 130 ‘C.&nbsp;</p><p>Fit the pinion gear on new screw element.&nbsp;</p><p>Torque tighten (60Nm for HP &amp; 250 Nm for LP) (Note: bolt tightening&nbsp;</p><p>is Counterclockwise direction).</p><p><br></p><p>14-11-2025</p><p>Removed the LP silencer, replaced the LP silencer filter, new O-rings and reinstalled.</p><p>Removed the HP silencer, clean and check the condition. (Arrived filter spare is not same)</p><p>Reinstalled the HP element. (47N-m) (Reinstalled the O-ring with old one)</p><p>Reinstalled the LP element. (81N-m) (Reinstalled the O-ring with old one)</p><p>Reinstalled the Oil line piping.</p><p>Reinstalled the HP-LP interconnecting air line.</p><p>Reinstalled the HP silencer.</p><p>Reinstalled the unloading valve.</p><p>Reinstalled the air line piping.</p><p>Reinstalled the air filter after cleaning.&nbsp;</p><p>Reinstalled the HP/LP side auto drain line.</p><p>Reinstalled the top baffles, side frame, covers and roof components.</p><p><br></p><p>15-11-2025.</p><p><br></p><p>Replaced the new oil filter. (Last replacement - 22526 hrs on 25.6.25)</p><p>Top Up lube oil about 35 L.</p><p>(Running hours - 24737 hrs)</p><p>Replaced the new gear case breather.</p><p>Deisolate and test run.</p><p>Monitor the parameter.</p><p><br></p><p>20-11-2025</p><p>Test Run with Lag 1 and Lead.</p><p>Monitor the parameter.</p><p>Record vibration data.</p><p>Check with Thermoscan for all elements.</p><p>Running normal condition.</p><p><br></p><p><br></p><p><br></p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\65 INSTRUMENT AIR, UTILITY AIR &amp; N2\\6501 Instrument Air Compressors\\A-6500 A\\2025\\2025-11-12 HP LP replacement">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\65 INSTRUMENT AIR, UTILITY AIR &amp; N2\\6501 Instrument Air Compressors\\A-6500 A\\2025\\2025-11-12 HP LP replacement</a><br></p>', '2025-11-12 18:20:14', '2025-11-24 18:17:43', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-A-6500A', 'ZTK-A-6500A', 'Air Compressor No.1 Packages', NULL, NULL, 'Air Compressor No.1 Packages', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kaung', NULL, 'EXTERNAL', '2025-11-12 18:20:14', '2025-11-24 18:17:43', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Mercelo', NULL, 'EXTERNAL', '2025-11-12 18:20:14', '2025-11-24 18:17:43', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Moe Oo', NULL, 'EXTERNAL', '2025-11-12 18:20:14', '2025-11-24 18:17:43', 'PTTEP\\ZPQ.Mechanical-Works', 'PTTEP\\ZPQ.Mechanical-Works');
