  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot GDF-03001 shows Fault alarm', 'Electrical & Instrument', 'CM ', 'Completed', '2025-11-15', '<p><u><b>Activity,</b></u></p><p>-Troubleshoot Gas Detector Fault alarm and reading abnormal values</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-GDF-03001, Gas Detector near well bay area at WP-03</p><p><u><b>As found,</b></u></p><p>-Gas detector shows fault alarm and reading error values</p><p><u><b>What happen,</b></u></p><p>-Aging</p><p><u><b>Action,</b></u></p><p>-Found GDF-03001 shows reading values flatulate and fault alarm</p><p>-Check gas detector the reading values (-17.70 %LEL) with CCR&nbsp;</p><p>-Confirm MOS and check the physical condition</p><p>-Replace with new gas detector and perform zero calibration (0.0% LEL)</p><p>-Confirm with CCR for gas detector reading values by applying gas cylinder</p><p>-Remove MOS by CCR and unit running back to normal</p><p><u><b>As left,</b></u></p><p>-GDF-03001 is back to normal</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-The defective gas detector sent back to workshop.</p><p><u><b>Next plan,</b></u></p><p>-N/A</p><p><u><b>Documentation,</b></u></p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-90% completed.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-15_GDF-03001_TS gas detector fault alarm at WP-03">\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-15_GDF-03001_TS gas detector fault alarm at WP-03</a><br></p>', '2025-11-15 23:03:52', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.EI-Workshop', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
