-- Inserting report ID 37704
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S DC Backup Lube Oil Pump Failure', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-11-16', '<p><u><b>Activity,</b></u></p><p>T/S DC Backup Lube Oil Pump Failure (M-4492). (Day1)</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>DC Backup Lube Oil Pump ,GTC Train-3</p><p><u><b>As found,</b></u></p><p>-Backup Lube Oil Pump Test Failure alarm during periodic run check (Every 24Hrs at 12PM).</p><p><u><b>What happen,</b></u></p><p>-Fuse blown every time command signal send to main contactor (M).</p><p><u><b>Action,</b></u></p><p>-Checked the breakers status of STR-CPP-4492 &amp; TCP-CPP-4492 on DCDB-CPP-240A.</p><p>-Found MCB 2Q44 (Supply for STR-CPP-4492) was tripped.</p><p>-Reset the breakers and checked the STR-CPP-4292 panel incoming voltage = 133.5Vdc.</p><p>-Checked CFU (Control fuse) and found fuse (bel&lt;PS&gt;EJET125V, 3SB 8A 250V) was blown.</p><p>-Replaced with fuse (313, Lf 5A 250V) due to no original spare.</p><p>-Checked diode and found diode is damaged. Replaced with new diode.</p><p>-Test run the control circuit and found fuse blown again by high current.</p><p>-Measured the magnetic contactors coil resistance, M = 60.3Ohm (Good), 1A = 69 Ohm (Good).</p><p><span style="background-color: rgb(255, 255, 0);">!! Note,</span></p><p><span style="background-color: rgb(255, 255, 0);">1 . On hand spare magnetic contactors coil voltage 24VDC is not same as original coil voltage 125VDC.</span></p><p><span style="background-color: rgb(255, 255, 0);">2 . On hand spare part MTU (M contactor timing unit) is not working.</span></p><p><u><b>As left,</b></u></p><p>-DC backup lube oil pump not available.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-Hand tools kept on switchgear room.&nbsp;</p><p><u><b>Next plan,</b></u></p><p>-To replace with GTG standby train Dc lube oil pump magnetic contactors.</p><p>-To order correct magnetic contactor coil.</p><p>-To order new MTU spare.</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job progress,</b></u></p><p>-50%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-16 TS DC Backup Lube Oil Pump Test Fail GTC-4400', '2025-11-16 18:31:56', '2025-11-18 07:44:57', 'PTTEP\\ZPQ.EI-Turbine', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4400', 'ZTK-GTC-4400', 'Train 3,Gas Turbine Comp Package', NULL, NULL, 'Train 3,Gas Turbine Comp Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
