-- Inserting report ID 37711
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S DC Backup Lube Oil Pump Failure', 'Electrical & Instrument', 'CM ', 'Completed', '2025-11-17', '<p><u><b>Activity,</b></u></p><p>T/S DC Backup Lube Oil Pump Failure (M-4492). (Day2)</p><p><u><b>History,</b></u></p><p>-Continued job from 16-Nov-2025.</p><p><u><b>Equipment description and location,</b></u></p><p>DC Backup Lube Oil Pump ,GTC Train-3</p><p><u><b>As found,</b></u></p><p>-Backup Lube Oil Pump Test Failure alarm during periodic run check.</p><p><u><b>What happen,</b></u></p><p>-Magnetic contactor (M) coil extra external diode was damaged cause short circuit between positive and negative.</p><p><u><b>Action,</b></u></p><p>-Checked the magnetic contactor (M) diode condition again. Found diode is damaged and shorted.</p><p>-Allen-Bradley, 100-C60 magnetic contactor has build in integrated diode. Installing diode in parallel can damaged to one of the diode depend on which one have weaker Vf (forward voltage).</p><p>-Removed damaged extra external diode.</p><p>-Replace new spare fuse (313, Lf 5A 250V) due to no original spare.</p><p>-Function test the control system without installing the extra external diode. (All control working properly)</p><p>-Function test back up lube oil pump with CCR. All system working properly.</p><p><u><b>As left,</b></u></p><p>-DC backup lube oil pump back to normal condition.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-All tool and spare kept it back to location.</p><p><u><b>Next plan,</b></u></p><p>-To order correct rating magnetic contactor</p><p>-To order spare MTU units</p><p>-To order original spare fuse (8A)</p><p>-To check other trains for similar installation.</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job progress,</b></u></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-17_M-4492,TS DC Backup Lube Oil Pump Test Fail GTC-4400', '2025-11-17 14:45:40', '2025-11-18 08:32:06', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Supv', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4400', 'ZTK-GTC-4400', 'Train 3,Gas Turbine Comp Package', NULL, NULL, 'Train 3,Gas Turbine Comp Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
