-- Inserting report ID 37741
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS communication loss for SCADA system.', 'Automation', 'CM ', 'Completed', '2025-11-20', '<p><u><b>Activity,</b></u></p><p>- Troubleshoot communication loss for SCADA system</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-ZTK-SC-SCADA: Zawtika SCADA system (Automation Room)</p><p><u><b>As found,</b></u></p><p>-NA</p><p><u><b>What happen,</b></u></p><p>-<b>1. Physical Layer Issues (Cabling and Connections)&nbsp;</b></p>  <ul type="disc">  <li><b>Cause:</b>&nbsp;Loose,      damaged, or corroded cables (Ethernet, fiber, serial) can cause signal      integrity issues and temporary dropouts.</li><li>-2.&nbsp;<b>Network Congestion</b><ul type="disc">  <li><b>Cause:</b>&nbsp;Too      much network traffic (network storms) on network switches.</li><li>-3.&nbsp;<b>Electromagnetic Interference (EMI)</b><br>  <b>Cause:</b>&nbsp;High-voltage equipment, Variable Frequency Drives (VFDs), or lightning can induce noise in communication lines, corrupting data packets and causing communication timeouts.&nbsp;</li><li>-4.&nbsp;<b>Power Supply Instability</b><ul type="disc">  <li><b>Cause:</b>&nbsp;Momentary      power dips, fluctuations at the remote site or SCADA master can cause devices to briefly      reboot or malfunction, leading to a temporary loss of communication.</li> </ul></li> </ul></li> </ul><p><u><b>Action,</b></u></p><p>- Performed PING test and checked the communication signals between SCADA and wellhead platform PLCs.</p><p>- Checked SCADA network switches and network switches at PLC gateway.</p><p><u><b>As left,</b></u></p><p>- Communication for SCADA system is back to normal and under monitoring.</p><p><u>Next Plan,</u></p><p>- Under monitoring for SCADA communication&nbsp;</p><p><u>Documentation,</u></p><p>-NA</p><p><u>Job Progress,</u></p><p>-Under monitoring</p>', NULL, '2025-11-21 07:14:44', '2025-11-23 15:42:52', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
