  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace washing machine PRIMUS with Electrolux', 'Electrical & Instrument', 'OTH ', 'Completed', '2025-11-22', '<p><b><u>Activity,</u></b></p>  <p>-Replace washing machine PRIMUS with Electrolux.</p>  <p><b><u>History,</u></b></p>  <p>-Continued from 21-11-2025.</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-LD01B, Washing machine B, Laundry room.</p>  <p><b><u>As found,</u></b></p>  <p>-Washing machine PRIMUS was out of service due to high vibration.</p>  <p><b><u>What happen,</u></b></p>  <p>-Shock absorber may be malfunction.</p>  <p><b><u>Action,</u></b></p>  <p>-Install the footings of the Electrolux are installed and adjusted until the machine is balanced.</p>  <p>-Install water pipe lines and electrical power supply.</p><p>-During installation of the isolator, one part of isolator was missing and the spare will be required to be ordered.</p><p>-De-isolated the power and run the machine.(Running is normal)</p><p>-Installed the transportation lock at the PRIMUS washing machine.(Completed)</p><p>-The cover of PRIMUS is still need to be installed.(In progress)</p>  <p><b><u>As left,</u></b></p>  <p>-Washing machine B is available.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-N/A</p>  <p><b><u>Next plan,</u></b></p>  <p>-N/A</p>  <p><b><u>Documentation,</u></b></p>  <p>-N/A</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-22_LD01B, Washing machine B, Replace washing machine PRIMUS to Electrolux', '2025-11-22 18:12:23', '2025-11-30 07:29:22', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
