-- Inserting report ID 37778
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S deluge valve at WP01 bridge cannot close', 'Electrical & Instrument', 'CM ', 'Completed', '2025-11-24', '<p><b><u>Activity,</u></b></p>  <p>-T/S deluge valve XV-67909 at WP01 bridge cannot close.</p>  <p><b><u>History,</u></b></p>  <p>-N/A</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Deluge valve at WP01 bridge, Bridge to WP01</p>  <p><b><u>As found,</u></b></p>  <p>-The valve was opened all the time during deluge valve check.</p>  <p><b><u>What happen,</u></b></p>  <p>-SOV of XV-67909 malfunction.</p>  <p><b><u>Action,</u></b></p>  <p>-Checked the manual valve condition and found it is working normal.</p>  <p>-Checked SOV and found power supply was only 9.61VDC.</p><p>-Measured coil resistance and compare with the SOV of XV-67908.(Both have same coil resistance with around 271k ohm)</p><p>-Asked CCR to command de-energized the SOV and found the valve was not moving.</p><p>-Checked the fuse at power supply from the marshalling cabinet and check loop. (all are normal)</p><p>-Found the cable is moving out from the cable gland at the SOV. And found water ingress sign.</p><p>-Connect power cable to new SOV and found 0.7VDC at energized state and 22VDC at de-energized state.</p><p>-Replaced the old coil of SOV with new one(resistance 287.4k ohm). (Did not replaced the SOV because process isolation will be required)</p><p>-Function test and found the XV is working normal.</p>  <p><b><u>As left,</u></b></p>  <p>-The XV can be closed with command from CCR.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-The new SOV body will be kept in SWGR.</p>  <p><b><u>Next plan,</u></b></p>  <p>-N/A</p>  <p><b><u>Documentation,</u></b></p>  <p>-N/A</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-24_XV-67909, Deluge valve at WP01 bridge, TS deluge valve cannot command from CCR', '2025-11-24 16:30:08', '2025-11-24 17:52:57', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-XV-67909', 'ZTK-XV-67909', 'Deluge Valve Zone 101 on 8"-FW-67032', NULL, NULL, 'Deluge Valve Zone 101 on 8"-FW-67032', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'James', NULL, 'EXTERNAL', '2025-11-24 16:30:08', '2025-11-24 17:52:57', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Peter', NULL, 'EXTERNAL', '2025-11-24 16:30:08', '2025-11-24 17:52:57', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
