  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS crane Malfunction', 'Electrical & Instrument', 'CM ', 'Completed', '2025-11-24', '<p><b><u>Activity</u>,</b></p><p>-T/S crane malfunction.(CR-1573)</p><p><b><u>History</u>,</b></p><p>- N/A</p><p><b><u>Equipment description and location</u>,</b></p><p>-&nbsp;Pedestal crane, WP-15.</p><p><b><u>As found</u>,</b></p><p>-Slew cannot swivel to the left, and the boom cannot lower without the override.</p><p><b><u>What happen</u>,</b></p><p>- Slew Left Limit solenoid (SV12) and control relay (K14&amp;K20) are defective.&nbsp;</p><p><b><u>Action</u>,</b></p><li data-start="45" data-end="130"><p data-start="47" data-end="130">-Checked the slew left limit SOV interlock relay (K20) and found it was defective.</p> </li> <li data-start="131" data-end="205"> <p data-start="133" data-end="205">-Replaced the slew left limit SOV interlock relay (K20) with a new one.</p> </li> <li data-start="206" data-end="364"> <p data-start="208" data-end="364">-Measured the slew left limit solenoid (SV12) coil resistance and found it to be 1.191 kOhm, which is defective (the new SOV coil resistance is only 19.8 Ohm).</p> </li> <li data-start="365" data-end="458"> <p data-start="367" data-end="458">-Replaced the solenoid with a new SOV and performed a function test; operation was normal.</p> </li> <li data-start="459" data-end="564"> <p data-start="461" data-end="564">-Checked the luff out limit SOV control relay (K14) and found burn marks, indicating it was defective.</p> </li> <li data-start="565" data-end="696"> <p data-start="567" data-end="696">-Replaced the luff out limit SOV control relay (K14) with a new one and performed a function test,operation returned to normal.</p> </li> <li data-start="697" data-end="844" data-is-last-node=""> <p data-start="699" data-end="844" data-is-last-node="">-Performed function tests for slew left/right, luff in/out, and hoist up/down cutoff and alarm set points; all functions were in normal condition.</p><p data-start="699" data-end="844" data-is-last-node="">-Function tested by Well service team that also normal condition.</p></li><p><b><u>As left</u>,</b></p><p>-WP-15 crane is available.</p><p><u><b>Material/Equipment/Tool status</b></u></p><p>-Damaged SOV and relays are already scrapped.</p><p><b><u>Next plan</u>,</b><br class="Apple-interchange-newline"></p><p>-N/A</p><p><b><u>Documentation</u>,</b></p><p>- N/A</p><p>-Link ()</p><p><b><u>Job progress</u>,</b></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-24_CR-1573, TS crane malfunction', '2025-11-25 02:23:05', '2025-12-25 12:25:26', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-1573-EN', 'ZTK-CR-1573-EN', 'Pedestal Crane Diesel Engine WP15', NULL, NULL, 'Pedestal Crane Diesel Engine WP15', 'WP15', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2025-11-25 02:23:05', '2025-12-25 12:25:26', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
  INSERT INTO spare (report_id, action, mesc, detail, qty, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Withdraw', '36.56.48.718.3', 'TS crane Malfunction', '2', '2025-11-25 12:09:54', '2025-12-25 12:25:26', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop');
