  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To replace new PMA chiller compressor', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-11-25', '<p><b><u>&nbsp;Activity</u>,</b></p><p>-To replace new PMA chiller compressor (C-7890A) (Day-3)</p><p><b><u>History</u>,</b></p><p>- Due to compressor insulation low&nbsp;</p><p><u><b>Equipment description and location</b></u>,</p><p>-PMA HVAC chiller compressor, Main Deck.</p><p><b><u>As found</u>,</b></p><p>-NA</p><p><b><u>What happen</u>,</b></p><p>-NA</p><p><b><u>Action</u>,</b></p><p>- Open suction and discharge service valve.</p><p>- As found pressure, low side is 80 psi and high side is 80 psi.</p><p>- Test run unit and after run for 3 mins, compressor is trip by overload.</p><p>- Checked compressor current. Found 16 A and overload setting is 14A for each winding.</p><p>- Compressor have dual winding, magnetic contactor (KMC C-7890A and KCT C-7890A)</p><p>- Checked only KCT C-7890A winding is loading (16A) and KMC C -7890A winding is not loading. ( 0A)</p><p>- Checked KMC C-7890A upstream voltage is 399.5 VAC and downstream voltage is 355VAC.</p><p>- Due to voltage drop, compressor KMC C-7890A winding is not loading (0A)</p><p><b><u>As left</u>,</b></p><p>-PMA chiller compressor unit A is not available.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-NA</p><p><u><b>Next plan</b></u>,</p><p>- check and remove magnetic contactor KMC C-7890A.</p><p><b><u>Documentation</u>,</b></p><p>-InProgress</p><p><b><u>Job progress</u>,</b></p><p>-80%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-25_C-7890A_To replace new PMA chiller compressor', '2025-11-25 18:42:26', '2025-11-25 18:58:10', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-C-7890A', 'ZTK-C-7890A', 'Compressor for PMA ACCU Duty Unit', NULL, NULL, 'Compressor for PMA ACCU Duty Unit', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
