  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist Mech to T/S GTG cannot start by liquid mode', 'Electrical & Instrument', 'OTH ', 'Completed', '2025-11-26', '<p><u><b>Activity,</b></u></p><p>-Assist Mech to troubleshoot GTG cannot start by liquid mode.</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-Gas Turbine Generator Package No.1.</p><p><u><b>As found,</b></u></p><p>-Ignition fail when starting by liquid mode.</p><p><u><b>What happen,</b></u></p><p>-NA</p><p><u><b>Action,</b></u></p><p>-Checked and cleaned the liquid fuel line tubing, replaced the orifices and new spark plug.</p><p>-Performed valve exercised from PLC at UCP panel for the atomizing air valve SOV-72168-2 and liquid fuel valve SOV-72162-2.</p><p>-Found&nbsp; shut off valve for liquid fuel supply cannot fully open. </p><p>-Perform manual exercise the valve and exercise the valve by PLC forcing.</p><p>-Liquid fuel valve for the torch are functioning properly.</p><p>-Normalized the unit and function test run by liquid mode.</p><p>-The unit can start and running properly by liquid mode.</p><p><u><b>As left,</b></u></p><p>-The unit is back to normal.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-NA</p><p><u><b>Next plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-NA</p><p><u><b>Job progress,</b></u></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-26_GTG-7210, Assist mechanic to troubleshoot GTG cannot start by liquid mode', '2025-11-26 16:17:01', '2025-11-26 18:52:56', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
