  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Adjust PCV at water maker B', 'Electrical & Instrument', 'CM ', 'Completed', '2025-11-26', '<p><b><u>Activity,</u></b></p>  <p>-Adjust PCV-66502 at water maker B X-6625 after new spare installation.</p>  <p><b><u>History,</u></b></p>  <p>-Continued from 24-11-25 and 25-11-25.</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-Water maker B, X-6625, Main Deck</p>  <p><b><u>As found,</u></b></p>  <p>-Water leak at PCV-66502.</p>  <p><b><u>What happen,</u></b></p>  <p>-Corrosion</p>  <p><b><u>Action,</u></b></p>  <p>-Adjust PCV after mech team filter troubleshooting completed.</p>  <p>-Found pressure was stable at 1 bar.&nbsp;</p><p>-Removed and inspected the PCV and found the PCV flow direction was reverse.</p><p>-Install piping according to the local installation.</p><p>-Reinstall PCV at local and adjust to 6 bar before unit run.</p><p>-De-isolated power and process to run the unit.</p><p>-Found the outlet pressure was reduced to 5 bar during running. Readjusted to 6 bar.</p>  <p><b><u>As left,</u></b></p>  <p>-Unit is running normal.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-Old PCV is still in workshop.</p>  <p><b><u>Next plan,</u></b></p>  <p>-To overhaul the PCV if the seal kit is available.</p>  <p><b><u>Documentation,</u></b></p>  <p>-N/A</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-26_PCV-66502, TS water leak at PCV', '2025-11-26 18:04:54', '2025-11-26 18:08:19', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PCV-66502', 'ZTK-PCV-66502', 'Press Regulator for Fresh Water Inlet', NULL, NULL, 'Press Regulator for Fresh Water Inlet', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'James', NULL, 'EXTERNAL', '2025-11-26 18:04:54', '2025-11-26 18:08:19', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dol', NULL, 'EXTERNAL', '2025-11-26 18:04:54', '2025-11-26 18:08:19', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-TeamLead');
