  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To replace new PMA chiller compressor', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2025-11-26', '<p><b><u>Activity</u>,</b></p><p>-To replace new PMA chiller compressor (C-7890A) (Day-4)</p><p><b><u>History</u>,</b></p><p>- Due to compressor insulation low&nbsp;</p><p><b><u>Equipment description and location</u>,</b></p><p>-PMA HVAC chiller compressor, Main Deck.</p><p><b><u>As found</u>,</b></p><p>-NA</p><p><b><u>What happen</u>,</b></p><p>-NA</p><p><b><u>Action</u>,</b></p><p>- Removed KMC C-7890A magnetic contactor.<b>(SIEMENS SIRIUS 3RT2025-1AC20)</b></p><p>- Check and found that L1 L2 are out of phase.</p><p>- Even though clean contacts, MC contactor are already deteriorated.</p><p>- Currently (SIEMENS SIRIUS 3RT2025-1AC20) spare is not on hand.</p><p>- Temporary use <b>Schneider LC1D32 </b>as KCTC-7890A. (After receive spare, will replace)</p><p>- Test run unit and check upstream and downstream voltage. (Both are 399VAC) (Normal)</p><p>- Charged refrigerant suction pressure 25 Psi and discharge pressure is 180 psi.</p><p>- Checked all fitting points and flange joint (No leak is found)</p><p>- Checked current for KMC-C7890A is 6.9 A and KCTC-7890A is 9.28A.</p><p>- Checked new compressor is started from <b>20604.3 hr</b></p><p><b><u>As left</u>,</b></p><p>-PMA chiller compressor unit A is available.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-Old compressor is still at Upper deck gally lay down area</p><p>- When crane is available, move to lower deck and temporary keep at transformer area.&nbsp;</p><p><b><u>Next plan</u>,</b></p><p><b>- </b>Will monitor refrigerant pressure. If needed, will charge.&nbsp;&nbsp;</p><p>- Will monitor for a week.</p><p>- Will order magnetic contactor.</p><p>- Will clear area.</p><p><b><u>Documentation</u>,</b></p><p>-InProgress</p><p><b><u>Job progress</u>,</b></p><p>-90%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-26_C-7890A_To replace with new compressor due to insulation low', '2025-11-26 18:33:52', '2025-11-26 19:03:00', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
