  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To remove & inspect the actuator at E&I Workshop', 'Electrical & Instrument', 'OTH ', 'In Progress', '2025-11-29', '<p><u><b>Activity, (Continued job from (28-11-2025)</b></u></p><p>-To remove and inspect the actuator diaphragm from PV-03115&nbsp; test separator gas outlet Valve.</p><p><u><b>History,</b></u><br class="Apple-interchange-newline"></p><p>-PV-03115 control valve set removed from WP-03 due to actuator leak.</p><p>-Moved the control valve from WP-01 lower deck to E&amp;I Workshop.</p><p><u><b>Equipment description and location,</b></u></p><p>-Pressure Control Valve of the test separator gas outlet (PV-03115), WP-03.</p><p><u><b>As found,</b></u></p><p>-N/A</p><p><u><b>What happen,</b></u></p><p>- NA</p><p><u><b>Action,</b></u><br class="Apple-interchange-newline"></p><p>-Re-installed the actuator and tightened firmly the locknut of the diaphragm actuator stem.</p><p>-Performed the actuator leak test by applying Instrument air 2.4 bar. (Max air supply 4.1 bar as per nameplate).</p><p>-Monitored the actuator travel and it can travel properly. (Travel range 127 mm as per nameplate).</p><p>-Checked leak by Snoop and found no any leak.</p><p>-Keep monitoring for hold pressure for 30 mins and no air pressure drop (OK).</p><p>-Applied Torque 320 Nm&nbsp; for the valve flange 16 bolts.</p><p>-Re-installed the valve actuator.</p><p><u><b>Next Plan,</b></u></p><p>-To install tubing fittings and valve positioner.</p><p>-To perform calibration and function test.</p><p><u><b>Documentation,</b></u></p><p>-NA.</p><p><u><b>Job Progress,</b></u></p><p>- 80% Completed (In progress)</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-29_PV_03115_Remove and inspect the actuator diaphragm', '2025-11-29 14:20:24', '2025-11-29 18:31:15', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-PV-03115', 'ZTK-PV-03115', 'PCV for V-0311 Gas Outlet to Prod Header', NULL, NULL, 'PCV for V-0311 Gas Outlet to Prod Header', 'WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
