RNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-E-5010', 'ZTK-E-5010', 'Condt Air Cooler for V-5000 Condt Outlet', NULL, NULL, 'Condt Air Cooler for V-5000 Condt Outlet', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
