-- Inserting report ID 37852
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S flow transmitter not show below 1.5 mmscfd ', 'Electrical & Instrument', 'CM ', 'Completed', '2025-11-30', '<p><u><b>Activity,</b></u></p><p>-T/S FT-02112 reading not show below 1.5 mmscfd.</p><p><u><b>History,</b></u></p><p>-N/A</p><p><u><b>Equipment description and location,</b></u></p><p>-Flow transmitter at gas outlet of test separator, Mezz deck</p><p><u><b>As found,</b></u></p><p>-Flow transmitter reading is normal with stable zero.</p><p><u><b>What happen,</b></u></p><p>-The transmitter showed zero reading when the flow is below 1.5 mmscfd.</p><p><u><b>Action,</b></u></p><p>-Checked the physical condition of transmitter. (No water ingress)</p><p>-Checked the configuration and found flow cut off value is set at 299 kg/day (As found)</p><p>-Backup the configuration of as found existing FT-02112 and keep inside the Laptop.</p><p>-Load the configuration of WP-01 (FT-01112) and checked the configuration.</p><p>-Found the cut off value is 50 kg/day (As left).</p><p>-Backup the as left configuration and kept inside Laptop.</p><p>-Perform zero calibration and normalized the transmitter.</p><p>-Perform well test with CCR to check the flow and it can read the flow below 1.5 mmscfd.</p><p><u><b>As left,</b></u></p><p>-FT-02112 can read below 1.5 mmscfd and back to service.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><u><b>Next plan,</b></u></p><p>-N/A</p><p><u><b>Documentation,</b></u></p><p>-N/A</p><p>-Link ()</p><p><u><b>Job progress,</b></u></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-11-30_WP-02_FT-02112_TS test separator gas outlet flow transmitter reading not show below 1.5 mmscfd', '2025-11-30 21:59:50', '2025-12-01 07:39:04', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-FT-02112', 'ZTK-FT-02112', 'FT on8"-PG-02104-JS2N forV-0211GasOutlet', NULL, NULL, 'FT on8"-PG-02104-JS2N forV-0211GasOutlet', 'WP02', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
