DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS WP-15 SIS Remote I/O Communication Ring Fault.', 'Automation', 'CM ', 'In Progress', '2025-12-03', '<p><u><b>Activity,</b></u></p><p>-Troubleshoot WP-15 SIS Remote I/O Communication Ring Fault.</p><p><u><b>History,</b></u></p><p>-N/A</p><p><u><b>Equipment description and location,</b></u></p><p>-SIS PLC, WP-15</p><p><u><b>As found,</b></u></p><p>-Found that communication Ring Under SIS Remote IO communication shows communication failure.</p><p><u><b>What happen,</b></u></p><p>-Ring Communication failure due to rapid communication fail during Active Ring Supervisor check.</p><p><u><b>Action,</b></u></p><p>-Go online and checked 1756-EN2TR properties and reset Fault counter and fault alarm.</p><p>- Cannot reset fault alarm.</p><p>- Checked port1 and port2 LED status in 1756-EN2TR (ETHERNET COMMUNICATION MODULE).(In EI room)</p><p>- Port2 LED status is OFF.</p><p>- Replaced 1756-EN2TR (ETHERNET COMMUNICATION MODULE) with new one.</p><p>- Rapid communication fault is clear and SIS remote I/O communication is back to normal for SBN-WP15-001 and SBN-WP15-002.</p><p>- But there has still "Ring fault" alarm and SIS remote I/O communication is failed for SBN-WP15-100.</p><p>- Replaced 1794-AENTR (dual-port EtherNet/IP communication adapter&nbsp;belonging to the FLEX I/O) for SBN-WP15-100.</p><p>- SIS remote I/O communication is back to normal for SBN-WP15-100.</p><p>-Checked the remaining SBN-WP15-001 and SBN-WP15-002. </p><p>-Found one communication cable in SBN-WP15-001 is loosen. Cut the cable connector and tried to repair by replacing with new RJ-45 connector.</p><p>-The new type cannot be installed since the cable size and connector are mismatched.&nbsp;</p><p><u><b>As left,</b></u></p><p>-Fault counter reset to zero.</p><p>-Communication Back to normal.</p><p>-There has still "Ring Fault" alarm.</p><p><u><b>Next Plan,</b></u></p><p>-Need to replace RJ45 socket for SBN-WP15-001.</p><p><u><b>Documentation,</b></u></p><p>-N/A</p><p><u><b>Job Progress,</b></u></p><p>-50%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-12-03_TS WP-15 SIS Remote IO Communication Ring Fault', '2025-12-03 18:15:10', '2025-12-03 23:54:41', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-TeamLead', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-WP15-PLCS', 'ZTK-WP15-PLCS', 'Process Control and ESD System', NULL, NULL, 'Process Control and ESD System', 'WP15', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ever  Kyaw', NULL, 'EXTERNAL', '2025-12-03 18:15:10', '2025-12-03 23:54:41', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'James', NULL, 'EXTERNAL', '2025-12-03 18:15:10', '2025-12-03 23:54:41', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-TeamLead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Brown', NULL, 'EXTERNAL', '2025-12-03 18:15:10', '2025-12-03 23:54:41', 'PTTEP\\ZPQ.Automation', 'PTTEP\\ZPQ.EI-TeamLead');
