-- Inserting report ID 37887
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'GTC1 Cannot Start by LP Discharge Valve Discrepany', 'Electrical & Instrument', 'CM ', 'Completed', '2025-12-03', '<p><b><u>Activity,</u></b></p>  <p>-TS GTC-4200 trip by HPC suction valve discrepancy alarm SDV-42401 during unit start up.</p>  <p><b><u>History,</u></b></p>  <p>-NA</p>  <p>-</p>  <p><b><u>Equipment description and location,</u></b></p>  <p>-HPC suction Shut down valve, Main Deck</p>  <p><b><u>As found,</u></b></p>  <p>-Found that SOV-42401B didn''t receive the power supply when command open.</p>  <p><b><u>What happen,</u></b></p>  <p>-SOV-42401 unable to open and not allowed the unit to start.</p>  <p><b><u>Action,</u></b></p>  <p>-Checked the positioner limit switches and both are Ok.</p><p>-Checked the resistance of solenoid coils and the result is normal ( 0.646 k-Ohm).&nbsp;</p><p>-Checked the power supply to SOV A and B and found that the SOV-42401B didn''t get the power when command open.</p>  <p>-Checked the whole power supply loop for SOV-4240B.</p><p>-Found that cable termination at "controller active relay- KA-0533" is not tightened enough and retightened it.</p><p>-SOV-42401B received the power and open the SDV-42401.</p><p>-Start the unit and load the unit.</p>  <p><b><u>As left,</u></b></p>  <p>-Unit is running with load.</p>  <p><b><u>Material/Equipment/Tool status,</u></b></p>  <p>-NA</p>  <p><b><u>Next plan,</u></b></p>  <p>-NA</p>  <p><b><u>Documentation,</u></b></p>  <p>-NA</p>  <p>-Link ()</p>  <p><b><u>Job progress,</u></b></p>  <p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-12-03_GTC-4200 TS SDV-42401 Discrepancy Alarm', '2025-12-04 11:32:01', '2025-12-04 17:06:23', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTC-4200', 'ZTK-GTC-4200', 'Train 1,Gas Turbine Comp Package', NULL, NULL, 'Train 1,Gas Turbine Comp Package', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
