  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PDG Alternator Performance Check and Test Run', 'Electrical & Instrument', 'CM ', 'In Progress', '2025-12-05', '<p><u><b>Activity,</b></u></p><p>-PDG-452&nbsp; Alternator Performance Check and Test Run</p><p><u><b>History,</b></u></p><p>-N/A</p><p><u><b>Equipment description and location,</b></u></p><p>-Portable diesel generator, WP01 Upper deck.</p><p><u><b>As found,</b></u></p><p>-Charging Alternator drive belt tension was abnormal (too loose)</p><p>-Engine coolant level was low.</p><p><u>What happen,</u></p><p>-N/A</p><p><u>Action,</u></p><p>-Performed visual inspection of PDG</p><p>-Checked and confirmed engine oil, diesel fuel, and coolant levels were within specifications</p><p>-Performed test run and found the generator was working normal with 220VAC load.</p><p>-Mechanical Team topped up coolant and adjusted the charging alternator drive belt tension/alignment &amp; cleaned out the PDG-452 inside cabinet.</p><p>-Checked the alternator output voltage &amp; charging current(Ok)</p><p>-During the test run, noted excessive noise/grinding from the charging alternator bearing.</p><p><u><b>As left,</b></u></p><p>-Unit is operational and available for service.</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-PDG-452 is at WP01 upper deck.</p><p><u><b>Next plan,</b></u></p><p>-<span style="background-color: rgb(255, 255, 0);">Immediate plan is to schedule the replacement of the charging alternator due to bearing noise.(Spare is in stock)</span></p><p><u>Documentation,</u></p><p>-N/A</p><p>-Link ()</p><p><u>Job progress,</u></p><p>-90%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-12-05_PDG-452 To check the alternator performance and test run', '2025-12-05 14:53:39', '2025-12-05 18:38:04', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.EI-Workshop', false, 'ZTK') RETURNING id INTO new_report_id;
