-- Inserting report ID 37909
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS abnormal noise while running PDG-452', 'Mechanic', 'CM ', 'Completed', '2025-12-05', '<p><b><u>TS abnormal noise while running PDG-452</u></b></p><p><br></p><p>Findings and Fixing</p><p>&nbsp;(1)</p><p>-Found that Fan belt was loosen</p><p>-Tighten the fan belt and run the unit</p><p>-The noise still come out from Alternator bearing&nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">*Inform EI team to replace new alternator if the spare is available*</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p>(2)</p><p>-Found that lube oil seeping from the lube oil dipstick while running</p><p>*Change new O-ring and test run <span style="background-color: rgb(255, 255, 0);">(OK)*</span></p><p><br></p><p>(3)</p><p>-Found that coolant level was low</p><p>*Top up coolant <span style="background-color: rgb(255, 255, 0);">~4 liters*</span></p><p><br></p><p>(4)</p><p>-Found that inside the enclosure was filled with water and sludge</p><p>-Clean all the sludge but it will happen again during monsoon season</p><p>*<span style="background-color: rgb(255, 255, 0);">Water ingress inside enclosure due to the enclosure doors are not closing/sealing properly, need to fix properly*</span></p><p><br></p><p>(5)</p><p>-Found that Fuel seeping from injector no 2 and 3</p><p><span style="background-color: rgb(255, 255, 0);">*Need major overhaul*</span>&nbsp;</p><p><br></p><p>(6)</p><p>-Found that trace of oil seeping from the head gasket</p><p><span style="background-color: rgb(255, 255, 0);">*Need to confirm when major overhaul was performed*</span></p><p><br></p><p><br></p>', NULL, '2025-12-05 18:58:06', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-DG-WP-452', 'ZTK-DG-WP-452', 'Portable Diesel Generator', NULL, NULL, 'Portable Diesel Generator', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Leo. Shane', NULL, 'EXTERNAL', '2025-12-05 18:58:06', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
END $$;

