-- Inserting report ID 37969
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS generator rotor ground fault relay alarm', 'Electrical & Instrument', 'CM ', 'Completed', '2025-12-12', '<p><u><b>Activity,</b></u></p><p>-T/S generator rotor ground fault alarm.</p><p><u><b>History,</b></u></p><p>-On 10 Dec 2025, 01;05 GTG-7230 tripped by "CN_Gen_GF__Relay_MF" (Generator Rotor Ground Fault Relay Malfunction) alarm (CDNL).</p><p>Start GTG-7210 and shared the load.&nbsp;</p><p>For GTG-7230, checked the relay and termination for rotor ground fault relay at UCP and found nothing abnormal.</p><p>Reset the alarm and plan to check at the local on the next day.</p><p>GTG-7210 and GTG-7220 are running with load.</p><p>GTG-7230 is stand by.</p><p><u><b>Equipment description and location,</b></u></p><p>-Gas Turbine Generator Package No.3 Upper Deck</p><p><u><b>As found,</b></u></p><p>-N/A</p><p><u><b>What happen,</b></u></p><p>-N/A</p><p><u><b>Action,</b></u></p><p>-Check the ground fault monitoring JB and feel high temp around 44 degC.</p><p>-Informed&nbsp; onboard Solar vendor to check and recommended that is normal condition due to the JB nearby exciter.</p><p>-Checked JB 72 and verified the cable terminations are in good condition.</p><p>-Check the ground fault monitor relay (KA-4203) coil voltage 23.25 VDC (OK) and resistance about 1.486 kOhm. (compared with new relay coil resistance 1.384 kOhm).</p><p>-Replaced new relay set Solar P/N: 1061979-1.</p><p>-Check the wiring loop and tighten the cable as per the loop drawing.</p><p>-Check UPS power supply GTG-7230 Rotor Earth Fault Relay from CB 1Q68 and found it is normal 231.8 VAC.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p><u><b>As left,</b></u></p><p>-NA</p><p><u><b>Material/Equipment/Tool status,</b></u></p><p>-N/A</p><p><u><b>Next plan,</b></u></p><p>-NA</p><p><u><b>Documentation,</b></u></p><p>-N/A</p><p>-Link</p><p><u><b>Job progress,</b></u></p><p>-100% complete</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-12-12_GTG-7230_TS generator rotor ground fault alarm', '2025-12-12 16:17:20', '2025-12-17 10:51:05', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Turbine', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-GTG-7230', 'ZTK-GTG-7230', 'Gas Turbine Generator Package No.3', NULL, NULL, 'Gas Turbine Generator Package No.3', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
