  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Zargi', NULL, 'EXTERNAL', '2025-12-12 16:17:20', '2025-12-17 10:51:05', 'PTTEP\\ZPQ.EI-TeamLead', 'PTTEP\\ZPQ.EI-Turbine');
