  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS abnormal noise from E-7228C GTG#2 ', 'Mechanic', 'CM ', 'Completed', '2025-12-22', '<p>Problem -&nbsp; &nbsp;Abnormal noise came out during running.</p><p>Found&nbsp; &nbsp; -&nbsp; &nbsp;1.) Misalignment fan pulley and motor pulley.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 2.) Belt condition is deformed about 60% from normal condition.</p><p>Action&nbsp; &nbsp; -&nbsp; Removed the guard and checked<span style="background-color: rgb(255, 156, 0);"><b> belt tension - 45 Hz </b></span>(<span style="background-color: rgb(0, 255, 0);"><b> normal range should be 64-66Hz</b></span>)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked the pulleys alignment and <span style="background-color: rgb(255, 156, 0);"><b>found misalignment</b></span>. ( <span style="background-color: rgb(255, 255, 0);">we consider as major root cause </span>)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Removed the old two belts and replaced with new belts. <b style="background-color: rgb(0, 255, 0);">( V-belt,drive,imperial,3VX-475)</b></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Loosen the motor mounting bolts then adjust motor position for alignment.</p><p>&nbsp; &nbsp; &nbsp;Checked alignment for motor pulley and fan pulley with laser alignment tools and water level gauge ruler.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Adjust <span style="background-color: rgb(0, 255, 0);"><b>belt tension to 64.8 Hz.</b></span></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Test run and unit bac in service with satisfactory result.</p>', '<p><a href="http://\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\72 MAIN &amp; VITAL POWERr GENERATION\\7220 Gas Turbine Generator No. 2\\Lube oil cooler\\E-7228 C\\2025\\2025-12-22 TS abnormal noise">\\\\10.15.131.205\\Maint-Share\\Maintenance_Moved_from_UnOfficialShare\\Mechanical Photos\\05-ZPQ  MECH  HISTORY PICTURE\\01 ZPQ\\72 MAIN &amp; VITAL POWERr GENERATION\\7220 Gas Turbine Generator No. 2\\Lube oil cooler\\E-7228 C\\2025\\2025-12-22 TS abnormal noise</a><br></p>', '2025-12-22 16:44:19', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-EF-7228C-3', 'ZTK-EF-7228C-3', 'Lube Oil Cooler Fan No.3', NULL, NULL, 'Lube Oil Cooler Fan No.3', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ko Leo', NULL, 'EXTERNAL', '2025-12-22 16:44:19', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Works', NULL);
