DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To overhaul shutdown valve', 'Electrical & Instrument', 'CM ', 'Completed', '2025-12-26', '<p><u><b>Activity,</b></u></p><p>-To overhaul shutdown valve, SDV-45154.</p><p><u><b>History,</b></u></p><p>-NA</p><p><u><b>Equipment description and location,</b></u></p><p>-Glycol Circulation Pump Outlet to contractor Train 1 at Upper deck</p><p><u><b>As found,</b></u></p><p>-SDV 45154, IA leaking continuously from exhaust.</p><p><u><b>What happen,</b></u></p><p>-Corrosion by weather.</p><p><u><b>Action,</b></u></p><p>-Checked valve opening and closing condition.</p><p>-SDV-45154 (Opening time is 1s and closing time is 1s)</p><p>-Found during open condition both SDV air exhaust are leaking due to actuator piston Oring are defective.</p><p>-Removed actuator workshop to overhaul.</p><p>-Dissemble and found that badly corrosion inside actuator.</p><p>-Cleaned inside actuator and found that piston ring and housing are already deteriorated.</p><p>-Cleaned and apply zine for corroded area.</p><p>-Replaced new soft seal kit.</p><p>-Function test valve and stroke check. (Opening time is 1.5 sec and closing time is 1.5sec)</p><p>-Check leak test at 6 bar. (No leak found) but not reliable for long time use.&nbsp;</p><p><u><b>As left,</b></u></p><p>-SDV-45154 is out of service</p><p><u><b>Next Plan,</b></u></p><p>-Will remove SDV-71510 actuator and install at SDV-45151 as per management decision.</p><p>-Send back SDV-45154 actuator to shore for repair.</p><p><u><b>Documentation,</b></u></p><p>-NA.</p><p>-Link ().</p><p><u><b>Job Progress,</b></u></p><p>-100%</p>', '\\\\10.15.131.205\\Maint-Share\\01 E&amp;I\\Activity Photos\\2025-12-26_SDV-45154_To overhaul SDV-45154', '2025-12-26 14:47:18', '2025-12-29 08:48:26', 'PTTEP\\ZPQ.EI-Workshop', 'PTTEP\\ZPQ.Automation', false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-SDV-45154', 'ZTK-SDV-45154', 'SDV for Lean Glycol to E-4515, ESD 3GA', NULL, NULL, 'SDV for Lean Glycol to E-4515, ESD 3GA', 'PQ', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
