  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Crane cannot hoist during lifting', 'Mechanic', 'CM ', 'In Progress', '2026-01-03', '<p>Problem : During performing cargo lifting , hoist cannot up with the load.</p><p>Action&nbsp; &nbsp; : Put the load on the WP-12 lower deck.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Checked the Solenoid valve SV-03 and found the this valve was malfunctioning.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; EI team also check the relays and other solenoids, found that 5 Relays and 2 solenoid was&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;damaged.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Bypassed the SV-03 and move the boom to the boom rest.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Normalized the SV-03 hoist up solenoid valve.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Cannot perform the MM 12M PM because of crane cannot lift the cargo and crane was out of&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;service.&nbsp;</p>', NULL, '2026-01-04 00:01:42', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Crane', NULL, false, 'ZTK') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-CR-1273-EN', 'ZTK-CR-1273-EN', 'Pedestal Crane Diesel Engine WP12', NULL, NULL, 'Pedestal Crane Diesel Engine WP12', 'WP12', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ali', NULL, 'EXTERNAL', '2026-01-04 00:01:42', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Crane', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Plate', NULL, 'EXTERNAL', '2026-01-04 00:01:42', CURRENT_TIMESTAMP, 'PTTEP\\ZPQ.Mechanical-Crane', NULL);
