  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZTK-VR-WP12-350', 'ZTK-VR-WP12-350', 'Solar Charger and Regulator Board WP12', NULL, NULL, 'Solar Charger and Regulator Board WP12', 'WP12', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
